// empire-glance.js - 'At a glance' takeaways, 'Did you know?' and key events per profile. Loaded only by generator.html.

var GLANCE = {
  "Abbasid Caliphate": {t:["The Abbasids overthrew the Umayyads in 750 and ruled a multi-ethnic Islamic empire from their new capital, Baghdad.","Baghdad's House of Wisdom translated Greek, Persian and Indian learning into Arabic and helped give the world algebra.","Turkic slave soldiers, then Buyid and Seljuk overlords, hollowed out caliphal power long before the Mongols sacked Baghdad in 1258."],dyk:"The word 'algebra' comes from al-jabr in the title of al-Khwarizmi's treatise on calculation, written in Abbasid Baghdad around 820.",ev:[["750","Abbasid rebels defeat the Umayyads at the Battle of the Great Zab"],["762","Al-Mansur founds the Round City of Baghdad on the Tigris"],["c. 820","Al-Khwarizmi writes the treatise that gives algebra its name"],["836","Al-Mu'tasim moves the capital to Samarra to house his Turkic slave army"],["861","Assassination of al-Mutawakkil begins the Anarchy at Samarra"],["945","The Buyids take Baghdad, leaving the caliphs only religious authority"],["1258","Hulagu Khan's Mongols sack Baghdad and execute Caliph al-Musta'sim"],["1517","Selim I conquers Egypt, ending the Mamluk-sponsored shadow caliphate in Cairo"]]},
  "Achaemenid Empire": {t:["The first Persian Empire, built by Cyrus the Great, stretched from the Indus to the Aegean and the Nile.","Darius I's satrapies, Royal Road, coinage and Aramaic chancery became the model for later Near Eastern empires.","Weakened by revolts and court murders, it fell to Alexander the Great in just four years, 334 to 330 BCE."],dyk:"Royal couriers on the 2,700-kilometre Royal Road from Susa to Sardis could cover the distance in around a week, using relays of fresh riders.",ev:[["550 BCE","Cyrus II defeats Astyages and takes over the Median Empire"],["539 BCE","Cyrus defeats the Babylonians at Opis and enters Babylon"],["525 BCE","Cambyses II defeats Psamtik III at Pelusium and conquers Egypt"],["480 BCE","Xerxes invades Greece, wins at Thermopylae, sacks Athens but loses at Salamis"],["404 BCE","Egypt revolts on the death of Darius II and stays independent for six decades"],["343 BCE","Artaxerxes III reconquers Egypt"],["331 BCE","Alexander the Great defeats Darius III at Gaugamela"],["330 BCE","Alexander burns Persepolis; Darius III is murdered by his satrap Bessus"]]},
  "Adal Sultanate": {t:["Adal was a Muslim sultanate of the Horn of Africa, rich from the port of Zeila and later ruled from Harar.","Under Imam Ahmad ibn Ibrahim, firearms helped it overrun much of the Ethiopian highlands between 1529 and 1543.","Ahmad's death at Wayna Daga, then Oromo migrations and Ethiopian victories, reduced Adal to remnant states by 1577."],dyk:"The Ethiopian-Adal War drew in both global rivals of the age: about 400 Portuguese musketeers fought for Ethiopia, while Ottoman musketeers fought for Adal.",ev:[["c. 1415","Sabr ad-Din III founds Adal after returning from exile in Yemen"],["1445","Sultan Badlay is defeated and killed by Zara Yaqob at the Battle of Gomit"],["1520","Sultan Abu Bakr moves the capital from Dakkar to Harar"],["1529","Imam Ahmad routs Lebna Dengel's larger Ethiopian army at Shimbra Kure"],["1543","Imam Ahmad is killed at Wayna Daga and his coalition collapses"],["1559","Nur ibn Mujahid kills Emperor Gelawdewos at the Battle of Fatagar"],["1576","Sarsa Dengel defeats Sultan Muhammad ibn Nasir at the Webi River"],["1577","The dynasty withdraws to the oasis of Aussa"]]},
  "Afsharid Empire": {t:["Nader Shah, a general from the Afshar tribe, expelled Iran's occupiers and crowned himself Shah in 1736.","His 1739 sack of Delhi crippled the Mughal Empire and brought the Peacock Throne and Koh-i-Noor to Persia.","Built on one man's military genius, the empire shattered within months of his assassination in 1747."],dyk:"The treasure Nader Shah took from Delhi in 1739 was so vast that he remitted taxes throughout Iran for three years.",ev:[["1729","Nader expels the Ghilzai Afghans from Isfahan after seven years of occupation"],["1736","Nader is proclaimed Shah after a great assembly on the Mughan plain"],["1739","Nader crushes a much larger Mughal army at Karnal and enters Delhi"],["1740","Nader campaigns in Central Asia, subduing Bukhara and Khiva"],["1742","Nader has his eldest son Reza Qoli blinded on suspicion of plotting"],["1745","Nader defeats the Ottomans at Kars"],["1747","Nader Shah is assassinated by his own officers near Quchan"],["1796","Agha Mohammad Khan Qajar takes Mashhad; Shahrokh dies, ending the dynasty"]]},
  "Akkadian Empire": {t:["Founded by Sargon of Akkad, it is widely regarded as the world's first empire, uniting the Sumerian city-states under one ruler.","Its governors, standard measures and written Akkadian set the template that later Mesopotamian empires followed.","Gutian raids, palace murders and a severe drought around 2200 BCE brought it down; its capital has never been found."],dyk:"Sargon's daughter Enheduanna, high priestess of the moon god at Ur, is often described as the first named author in recorded history.",ev:[["c. 2334 BCE","Sargon of Akkad founds the empire after supplanting King Ur-Zababa of Kish"],["c. 2254 BCE","Naram-Sin, Sargon's grandson, begins the reign that marks the empire's zenith"],["c. 2240 BCE","Akkadian power peaks under Naram-Sin, self-styled King of the Four Quarters"],["c. 2200 BCE","The 4.2-kiloyear drought brings crop failure and famine across the Near East"],["c. 2193 BCE","Shar-Kali-Sharri dies, leaving a chaotic succession of short-lived kings"],["c. 2154 BCE","The Akkadian dynasty comes to an end"]]},
  "Aksumite Empire": {t:["Aksum, in highland Ethiopia and Eritrea, grew rich trading African ivory and gold through its Red Sea port of Adulis.","Under King Ezana it became one of the first states to adopt Christianity, founding Ethiopia's Orthodox tradition.","Cut off from Red Sea trade by Persia and the early Islamic conquests, it shrank into a regional highland kingdom."],dyk:"Aksum was one of the very few ancient states to mint its own gold coins, and the first to place the Christian cross on its coinage.",ev:[["c. 270","King Endubis introduces Aksumite gold, silver and bronze coinage"],["c. 350","King Ezana conquers the Kingdom of Kush, reaching the Nile"],["c. 525","King Kaleb's seaborne expedition overthrows the Himyarite king Dhu Nuwas in Yemen"],["570s","A Sasanian force takes Yemen, cutting Aksum off from the Arabian trade"],["c. 615","Aksum shelters early Muslim emigrants from Arabia"],["Early 7th century","Aksumite coinage ceases after more than three centuries"]]},
  "Almohad Caliphate": {t:["A Berber religious reform movement from the Atlas Mountains that united the whole Maghreb and Muslim al-Andalus.","Its court patronised Averroes, whose Aristotle commentaries reshaped European scholastic thought.","Defeat at Las Navas de Tolosa in 1212 shattered its prestige; the Marinids took Marrakesh in 1269."],dyk:"Seville's Giralda, now the cathedral bell tower, was begun in 1184 as the minaret of the city's Almohad Great Mosque.",ev:[["1121","Ibn Tumart is proclaimed the Mahdi by his followers in the Atlas Mountains"],["1147","Abd al-Mu'min captures the Almoravid capital Marrakesh and takes the title of caliph"],["1160","Almohads complete the conquest of the Maghreb from Morocco to Tunisia"],["1172","Abu Yaqub Yusuf I absorbs the last independent Muslim principality of al-Andalus"],["1195","Yaqub al-Mansur crushes Alfonso VIII of Castile at the Battle of Alarcos"],["1212","Christian coalition shatters the Almohad army at Las Navas de Tolosa"],["1248","Ferdinand III of Castile takes Seville"],["1269","The last caliph, Idris al-Wathiq, is killed as the Marinids seize Marrakesh"]]},
  "Almoravid Empire": {t:["Saharan Berber reformists who built an empire from the Senegal River to the Ebro, ruled from Marrakesh.","Their victory at Sagrajas in 1086 halted Castile's advance and kept much of al-Andalus Muslim for generations.","Overstretched on two fronts, they fell to the Almohads, who used the same charge of impiety the Almoravids once used."],dyk:"The Almoravid gold dinar was so trusted that Christian Iberia imitated it as the morabetino, the origin of the Castilian maravedí.",ev:[["1054–1055","Almoravids capture Sijilmasa, northern terminus of the trans-Saharan gold trade"],["c. 1070","Marrakesh is founded as the capital of the northern branch"],["1086","Yusuf ibn Tashfin shatters Alfonso VI's army at the Battle of Sagrajas"],["1091","Almoravids absorb the taifa kingdom of Seville"],["1106","Death of Yusuf ibn Tashfin, the empire's greatest ruler"],["1118","Alfonso I of Aragon takes Zaragoza"],["1145","Tashfin ibn Ali dies near Oran, opening Morocco to the Almohads"],["1147","Almohads storm Marrakesh and kill the last Almoravid ruler, Ishaq ibn Ali"]]},
  "Ashanti Empire": {t:["Osei Tutu I united Akan chiefdoms in Ghana's forest zone around 1700, bound together by the sacred Golden Stool.","Rich in gold and kola, Asante resisted British expansion through five wars between 1824 and 1900.","Annexed by Britain in 1902, it never surrendered the Golden Stool, and its king is still recognised in Ghana today."],dyk:"No one sits on the Golden Stool: the Asantehene is enstooled beneath it, as it embodies the soul of the whole Asante nation.",ev:[["1701","Asante coalition defeats Denkyira at Feyiase, gaining access to coastal trade"],["1824","Asante army annihilates a British-led force at Nsamankow, killing Governor MacCarthy"],["1826","A British-led coalition aided by Congreve rockets defeats Asante at Katamansu"],["1831","Treaty of Peace fixes the River Pra as the southern limit of Asante influence"],["1874","Sir Garnet Wolseley's expedition enters Kumasi and burns the capital"],["1896","British occupy Kumasi without a fight and depose Asantehene Prempeh I"],["1900","Yaa Asantewaa leads the War of the Golden Stool against British rule"],["1902","Asante is formally annexed as a British crown colony"]]},
  "Assyrian Empire": {t:["From the city of Assur on the Tigris, Assyria grew from a merchant network into the largest empire the world had yet seen.","Its provinces, royal couriers, siege engineers and mass deportations became models for Babylon and Persia.","Overstretched and hated by its subjects, it was destroyed by Medes and Babylonians in barely sixty years after its peak."],dyk:"The Library of Ashurbanipal at Nineveh preserved the standard version of the Epic of Gilgamesh, one of the oldest surviving works of literature.",ev:[["c. 2025 BCE","Assur emerges as an independent city-state after the fall of the Third Dynasty of Ur"],["c. 1225 BCE","Tukulti-Ninurta I conquers Babylon and captures its Kassite king"],["911 BCE","Adad-nirari II launches the Neo-Assyrian revival"],["745 BCE","Tiglath-pileser III takes the throne and reorganises army and provinces"],["722 BCE","Samaria falls and the population of the Kingdom of Israel is deported"],["671 BCE","Esarhaddon conquers Egypt, bringing the empire to its greatest extent"],["612 BCE","Babylonians and Medes destroy the Assyrian capital Nineveh"],["609 BCE","Ashur-uballit II fails to retake Harran and vanishes from the record"]]},
  "Austro-Hungarian Empire": {t:["The 1867 Compromise turned the Habsburg lands into a Dual Monarchy: Austria and Hungary under one ruler, Franz Joseph.","Its Vienna produced Freud, Mahler, Klimt and Wittgenstein, while Bohemia became a major industrial region.","The war it began in 1914 broke its multinational army, and it dissolved into successor states in October 1918."],dyk:"Budapest was only created in 1873, by uniting Buda, Óbuda and Pest, and grew to almost 900,000 people by 1910.",ev:[["1866","Prussia defeats Austria at Königgrätz, excluding it from German affairs"],["1867","The Ausgleich creates the Dual Monarchy; Franz Joseph is crowned King of Hungary"],["1878","Austria-Hungary occupies Bosnia-Herzegovina"],["1907","Austria introduces universal male suffrage for the Reichsrat"],["1914","Gavrilo Princip assassinates Archduke Franz Ferdinand in Sarajevo"],["1916","Brusilov Offensive breaks the army; Franz Joseph dies in November"],["1918","The empire dissolves; armistice of Villa Giusti signed on 3 November"]]},
  "Ayyubid Empire": {t:["Founded by the Kurdish commander Saladin, it united Egypt, Syria and Upper Mesopotamia against the Crusader states.","Saladin's victory at Hattin and recapture of Jerusalem in 1187 permanently shifted the balance in the Levant.","Divided among quarrelling kinsmen, it was overthrown by its own mamluk soldiers in 1250 and finished by the Mongols."],dyk:"Saladin's nephew, Sultan al-Kamil, later handed Jerusalem to Emperor Frederick II by treaty in 1229, in return for help against his own Ayyubid relatives.",ev:[["1171","Saladin ends the Fatimid Caliphate, restoring Egypt to Sunni Abbasid allegiance"],["1174","After Nur al-Din's death, Saladin takes Damascus"],["1187","Saladin destroys the Crusader army at Hattin and takes Jerusalem"],["1192","Treaty of Jaffa ends the Third Crusade with Jerusalem still in Ayyubid hands"],["1193","Saladin dies, triggering a succession struggle among his sons"],["1229","Al-Kamil cedes Jerusalem to Holy Roman Emperor Frederick II"],["1250","Bahri mamluks murder Sultan Turanshah and seize Egypt"],["1259–1260","Mongols invade the Levant, sack Aleppo and end Ayyubid rule in Syria"]]},
  "Aztec Empire": {t:["The Triple Alliance of Tenochtitlan, Texcoco and Tlacopan ruled central Mexico from 1428 through a vast tribute system.","Tenochtitlan, fed by lake-bed chinampa gardens, held 200,000 or more people, one of the largest cities in the world.","It fell in under two years to smallpox and to a Spanish-led army made up mostly of its own resentful neighbours."],dyk:"At the final siege of Tenochtitlan, Cortés's army may have numbered up to 100,000 warriors, of whom fewer than 1,000 were Spaniards.",ev:[["c. 1325","The Mexica settle on a swampy island in Lake Texcoco, founding Tenochtitlan"],["1428","Itzcoatl's coalition defeats Azcapotzalco and the Triple Alliance is formed"],["1479","The Purépecha rout Axayacatl's army, fixing the empire's western frontier"],["1487","Ahuitzotl rededicates the enlarged Templo Mayor"],["1502","Moctezuma II comes to power and centralises tribute and appointments"],["1519","Hernán Cortés enters Tenochtitlan as Moctezuma II's guest"],["1520","Spanish flee Tenochtitlan on La Noche Triste; smallpox then ravages the city"],["1521","Tenochtitlan falls after a three-month siege; Cuauhtémoc is captured"]]},
  "Babylonian Empire": {t:["Under Hammurabi, a small Amorite city-state became the master of Mesopotamia in barely a decade of conquest.","His Code of 282 laws is the most complete legal collection to survive from the ancient Near East.","Lacking strong institutions, the empire fragmented soon after his death and ended with a Hittite raid around 1595 BCE."],dyk:"Hammurabi destroyed the city of Eshnunna not by storming it but by damming and then releasing floodwater against it.",ev:[["c. 1894 BCE","Sumu-abum takes control of Babylon and begins building its walls"],["c. 1792 BCE","Hammurabi becomes king of Babylon"],["1764 BCE","Hammurabi defeats an Elamite-led coalition, launching his conquests"],["1763 BCE","Hammurabi conquers Larsa, bringing all southern Mesopotamia under his rule"],["1761 BCE","Hammurabi conquers his former ally Mari"],["c. 1754 BCE","The Code of Hammurabi is inscribed"],["1750 BCE","Hammurabi dies; his son Samsu-iluna soon faces widespread revolt"],["c. 1595 BCE","Hittite king Mursili I sacks Babylon, ending the First Dynasty"]]},
  "Benin Empire": {t:["An Edo kingdom in southern Nigeria whose Obas built a regional empire from Benin City from the 15th century.","Royal guilds produced the Benin Bronzes, among the finest figurative sculpture of sub-Saharan Africa.","A British expedition burned Benin City in 1897 and looted its art, now at the centre of the restitution debate."],dyk:"Much of the metal for the Benin Bronzes came from Portuguese brass manillas, horseshoe-shaped bracelets used as currency in trade.",ev:[["c. 1180","Eweka I founds the Oba dynasty after the Ogiso line loses legitimacy"],["c. 1440","Ewuare the Great seizes the throne, rebuilds Benin City and begins expansion"],["1480s","Portuguese traders under João Afonso de Aveiro reach Benin"],["c. 1515–1516","Oba Esigie defeats a major Igala invasion from the north"],["c. 1606","Death of Ehengbuda, the last of Benin's warrior kings"],["c. 1700–1712","Civil war under Oba Ewuakpe brings the monarchy close to abolition"],["1897","British Punitive Expedition burns Benin City and exiles Oba Ovonramwen"]]},
  "Brazilian Empire": {t:["Prince Pedro declared Brazil independent of Portugal in 1822 and ruled it as Emperor Pedro I.","Under Pedro II the monarchy held a vast country together, while coffee grown by enslaved people drove its wealth.","Abolition in 1888 cost it the planters' support, and an army coup ended the empire in 1889 almost unopposed."],dyk:"Pedro II studied languages including Hebrew, Sanskrit and Tupi, and corresponded with Louis Pasteur and Henry Wadsworth Longfellow.",ev:[["1822","Prince Pedro proclaims independence at the Ipiranga and is acclaimed Emperor Pedro I"],["1831","Pedro I abdicates in favour of his five-year-old son"],["1840","Pedro II is declared of age at fourteen, ending the Regency"],["1850","The Eusébio de Queirós Law effectively ends the transatlantic slave trade"],["1864","Paraguayan War begins; Brazil will bear most of six years of fighting"],["1871","The Law of the Free Womb is passed"],["1888","Princess Isabel signs the Lei Áurea, abolishing slavery"],["1889","Marshal Deodoro da Fonseca's coup ends the monarchy"]]},
  "British Empire": {t:["The largest empire in history, ruling roughly a quarter of the world's people at its peak around 1920.","Naval supremacy, industrial power and the City of London spread its laws, parliaments and language worldwide.","Two world wars drained its wealth; after Indian independence in 1947 it dissolved within a few decades."],dyk:"The Indian Civil Service ran a country of some 300 million people with a cadre of only about 1,000 to 1,200 senior officers.",ev:[["1607","English settlers found Jamestown, Virginia, the first permanent colony in the Americas"],["1707","Acts of Union join England and Scotland as the Kingdom of Great Britain"],["1763","Treaty of Paris ends the Seven Years' War, stripping France of Canada"],["1805","The Royal Navy wins at Trafalgar, securing a century of naval supremacy"],["1857","The Indian Rebellion leads to the abolition of East India Company rule"],["1947","India gains independence, removing the empire's most vital possession"],["1956","The Suez Crisis exposes Britain's inability to act against US wishes"],["1997","Britain hands Hong Kong to China, formally closing the imperial era"]]},
  "Byzantine Empire": {t:["The eastern Roman Empire, ruled from Constantinople, whose people called themselves Romans for over 1,100 years.","It preserved Roman law in Justinian's Code and Greek learning, and spread Orthodox Christianity to Russia and the Balkans.","Manzikert in 1071 and the crusader sack of 1204 crippled it; the Ottomans took Constantinople in 1453."],dyk:"Hagia Sophia, completed under Justinian in 537, remained the largest church in the world for nearly a thousand years.",ev:[["330","Constantine I dedicates Constantinople on the site of Byzantion"],["395","Death of Theodosius I divides the empire permanently into east and west"],["537","Justinian completes the Hagia Sophia"],["717–718","Leo III's Greek fire helps defeat the second Arab siege of Constantinople"],["1071","Seljuk Turks defeat and capture Romanos IV Diogenes at Manzikert"],["1204","The Fourth Crusade sacks Constantinople and founds a Latin Empire"],["1261","Michael VIII Palaiologos recovers Constantinople from the Latins"],["1453","Mehmed II captures Constantinople; Constantine XI dies on the walls"]]},
  "Carolingian Empire": {t:["Charlemagne's Frankish empire united much of Western and Central Europe and revived the Western imperial title in 800.","Its scholars copied much of the classical Latin literature that survives today, in the new Carolingian minuscule script.","The Frankish custom of dividing realms among sons split it at Verdun in 843 and broke it apart for good by 888."],dyk:"Charlemagne's silver penny, struck at 240 to the pound, was the basis of the pound-shilling-penny system used in Britain until 1971.",ev:[["732","Charles Martel checks an Umayyad raid near Tours and Poitiers"],["751","Pepin the Short deposes the last Merovingian king and is made king with papal approval"],["774","Charlemagne conquers the Lombard kingdom and becomes King of the Lombards"],["778","Basques destroy Charlemagne's rearguard under Roland at Roncevaux Pass"],["800","Pope Leo III crowns Charlemagne emperor in Rome on Christmas Day"],["814","Louis the Pious inherits the undivided empire"],["843","Treaty of Verdun divides the empire among Charlemagne's grandsons"],["887","Charles the Fat is deposed and the empire fragments permanently"]]},
  "Chagatai Empire": {t:["The Mongol realm that Genghis Khan allotted to his son Chagatai, spanning Central Asia's steppe and Silk Road cities.","It produced Timur and, through him, a Chagataid line that helped legitimise the Mughal emperors of India.","Torn between nomadic tribes and settled Muslim cities, it split apart, losing Transoxiana to Timur by 1370."],dyk:"The city of Qarshi in Uzbekistan takes its name from the palace that Kebek Khan built there, near Nasaf, in the early 14th century.",ev:[["1227","Chagatai Khan begins his rule over the appanage allotted by Genghis Khan"],["1260","Alghu exploits the Mongol civil war to assert real independence"],["1299","Qutlugh Khwaja leads a great Chagataid army to the outskirts of Delhi"],["c. 1321","Kebek Khan introduces a standardised silver coinage, the kebeks"],["1334","Eastern nomadic tribes revolt against Tarmashirin and overthrow him"],["1360–1361","Tughlugh Timur briefly reunites the khanate"],["1370","Timur completes his seizure of power in Transoxiana"],["1514","The Yarkent Khanate is founded as a Chagataid successor state"]]},
  "Chaldean Empire": {t:["The Neo-Babylonian Empire rose on Assyria's ruins and, under Nebuchadnezzar II, dominated the Near East.","Its destruction of Jerusalem and the Babylonian captivity reshaped Judaism into a portable, text-centred faith.","Weak successors and a king who neglected Marduk let Cyrus the Great take Babylon almost unopposed in 539 BCE."],dyk:"Babylonian sky-watching was so renowned that 'Chaldean' became a byword for astronomer and astrologer in the Greek and Roman worlds.",ev:[["626 BCE","Nabopolassar seizes Babylon and restores native Babylonian kingship"],["612 BCE","Babylonians and Medes sack Nineveh, the Assyrian capital"],["605 BCE","Crown prince Nebuchadnezzar II defeats Necho II's Egyptians at Carchemish"],["597 BCE","Nebuchadnezzar captures Jerusalem and deports King Jehoiachin"],["587/586 BCE","Babylonians destroy Jerusalem and its Temple after a second siege"],["c. 585 BCE","Babylonians begin a thirteen-year siege of the island city of Tyre"],["562 BCE","Nebuchadnezzar II dies; four kings follow in six years"],["539 BCE","Cyrus the Great wins at Opis and Babylon falls without real resistance"]]},
  "Darfur Sultanate": {t:["The Keira sultans ruled Darfur from Jebel Marra for over 250 years, building an Islamic state in the eastern Sahel.","Its Forty Days Road carried slaves, ivory and feathers to Egypt, and West African pilgrims passed through it to Mecca.","Conquered in 1874 and revived in 1898, it fell to an Anglo-Egyptian force with aircraft in 1916."],dyk:"Much of what we know of the sultanate's court comes from Muhammad al-Tunisi, a Tunisian traveller who lived in Darfur from about 1803 to 1811.",ev:[["c. 1650","Suleiman Solong unites the Fur under the Keira dynasty"],["c. 1682","Ahmad Bukr begins his reign and makes Islam the religion of the state"],["c. 1791","Sultan Abd al-Rahman fixes the royal court at El Fasher"],["1821","Egypt conquers Kordofan, cutting Darfur's eastern trade"],["1874","Al-Zubayr defeats Sultan Ibrahim at Manawashi and Darfur is annexed by Egypt"],["1898","Ali Dinar returns to El Fasher and restores the sultanate"],["1916","Anglo-Egyptian force wins at Birinjiya; Ali Dinar is killed in November"]]},
  "Delhi Sultanate": {t:["Five dynasties of Turkic and Afghan origin ruled northern India from Delhi for 320 years, from 1206 to 1526.","It repelled repeated Mongol invasions and fostered the Indo-Islamic culture of the Qutb Minar and Amir Khusrau.","Overreach, provincial breakaways and Timur's sack of Delhi weakened it before Babur won at Panipat in 1526."],dyk:"The Moroccan traveller Ibn Battuta served as a qazi, or judge, at the court of Muhammad bin Tughlaq in Delhi from 1334.",ev:[["1206","Qutb ud-Din Aibak founds the Mamluk or Slave Dynasty after Muhammad of Ghor's murder"],["1229","Abbasid caliph sends Iltutmish a diploma recognising him as sultan"],["1299","Alauddin Khalji's forces turn back a Mongol army that reaches Delhi's outskirts"],["1311","Malik Kafur plunders the Pandya lands around Madurai"],["1327","Muhammad bin Tughlaq forcibly moves the capital to Daulatabad"],["1347","The Bahmani Sultanate breaks away in the Deccan"],["1398","Timur sacks Delhi and carries off its artisans to Samarkand"],["1526","Babur defeats Ibrahim Lodi at the First Battle of Panipat"]]},
  "Dutch Empire": {t:["A small republic built a trading empire across four continents through the VOC and the West India Company.","The VOC's permanent capital and tradable shares created a model of the joint-stock company still recognisable today.","Weakened by wars with Britain, the VOC was dissolved in 1799; Indonesian independence in 1949 ended its Asian empire."],dyk:"Hugo Grotius wrote Mare Liberum (1609) in defence of the VOC, and it became a founding text of international law.",ev:[["1602","The States-General merges rival traders into the VOC with quasi-sovereign powers"],["1619","Jan Pieterszoon Coen founds Batavia on Java"],["1641","The VOC captures Malacca from Portugal"],["1652","Jan van Riebeeck founds the Cape Colony as a VOC resupply station"],["1664","England takes New Netherland and New Amsterdam"],["1799","The VOC is formally dissolved and its debts pass to the Dutch state"],["1942","Japan conquers the Netherlands East Indies in about three months"],["1975","Suriname's independence ends the Dutch colonial empire"]]},
  "Egyptian Empire New Kingdom": {t:["Egypt's imperial age, founded when Ahmose I expelled the Hyksos c. 1550 BCE, stretched from Nubia to the Euphrates.","Nubian gold, Levantine tribute and the Amarna letters' great-power diplomacy made Egypt the hub of the Late Bronze Age world.","It ended not by conquest but by dissolution, as the Bronze Age Collapse and the rising Amun priesthood hollowed out royal power."],dyk:"Ramesses II and the Hittites made peace in 1258 BCE in the earliest treaty to survive in both parties' versions, settling a stalemate after the Battle of Kadesh.",ev:[["c. 1550 BCE","Ahmose I completes the expulsion of the Hyksos and reunites Egypt"],["1457 BCE","Thutmose III defeats a Canaanite coalition at Megiddo after a daring march through the Aruna pass"],["c. 1353 BCE","Akhenaten begins his reign, elevating the Aten and moving the capital to Akhetaten"],["1274 BCE","Ramesses II fights the Hittite king Muwatalli II to a draw at the Battle of Kadesh"],["1258 BCE","Egypt and the Hittites conclude a peace treaty acknowledging strategic stalemate"],["c. 1177 BCE","Ramesses III repels land and sea invasions by the Sea Peoples"],["c. 1153 BCE","Ramesses III is assassinated by harem conspirators"],["c. 1070 BCE","Death of Ramesses XI ends the New Kingdom amid administrative dissolution"]]},
  "Elamite Confederation": {t:["Elam joined lowland Susa and highland Anshan in southwestern Iran, a pairing that let it survive conquest and revive for two millennia.","It repeatedly broke Mesopotamian powers, sacking Ur and toppling Kassite Babylon, and its rulers once outranked Hammurabi.","Ashurbanipal destroyed Susa c. 646 BCE, but Elamite language and bureaucracy lived on inside the Persian Achaemenid state."],dyk:"The Code of Hammurabi was found at Susa, not Babylon: Elamite kings carried it off as a war trophy c. 1158 BCE, and French excavators recovered it around 1900.",ev:[["c. 2100 BCE","Kutik-Inshushinak of Awan first unifies Susa and the highlands after the Akkadian collapse"],["c. 2004 BCE","Shimashki king Kindattu sacks Ur and captures Ibbi-Sin, last ruler of the Third Dynasty of Ur"],["c. 1765 BCE","Sukkalmah Siwe-Palar-Khuppak conquers Eshnunna and is addressed as 'father' by Hammurabi"],["c. 1158 BCE","Shutruk-Nahhunte and Kutir-Nahhunte overthrow the Kassite dynasty of Babylon"],["720 BCE","Humban-nikash I fights Sargon II of Assyria at the Battle of Der"],["694 BCE","Sennacherib's son Ashur-nadin-shumi is handed to Elam and dies in captivity"],["c. 646 BCE","Ashurbanipal destroys Susa, looting its treasuries and desecrating royal tombs"],["540s BCE","Cyrus the Great begins absorbing Elam into the Achaemenid Empire"]]},
  "Empire of Japan": {t:["Born of the 1868 Meiji Restoration, Japan went from feudal isolation to industrial great power in barely a generation.","Its 1905 defeat of Russia showed the colonised world that European supremacy was not inevitable.","A system with no check on its military drove it into a war it could not sustain, ending in surrender in 1945."],dyk:"Japan imported roughly 80 per cent of its oil from the United States, so the American oil embargo of August 1941 pushed Tokyo towards attacking Pearl Harbor.",ev:[["1868","Meiji Restoration overthrows the Tokugawa shogunate after some 265 years"],["1889","Meiji Constitution establishes a constitutional monarchy with an Imperial Diet"],["1894","First Sino-Japanese War begins, ending in Japanese victory over Qing China in 1895"],["1905","Admiral Togo annihilates the Russian fleet at Tsushima, sealing victory over Russia"],["1931","Army officers stage the Mukden Incident, launching independent action in Manchuria"],["1941","US oil embargo in August pushes Japan towards the attack on Pearl Harbor"],["1942","Japan loses four fleet carriers at Midway, surrendering the strategic initiative"],["1945","After Hiroshima, Nagasaki and Soviet entry into the war, Japan surrenders aboard USS Missouri"]]},
  "Ethiopian Empire": {t:["A Christian highland kingdom ruled by the Solomonic dynasty, which claimed descent from Solomon and the Queen of Sheba, from 1270 to 1974.","Menelik II's victory over Italy at Adwa in 1896 kept Ethiopia independent and made it a symbol for pan-Africanists worldwide.","An unreformed feudal land system and the concealed Wollo famine brought down Haile Selassie and the monarchy in 1974."],dyk:"Ethiopia's survival in 1543 owed much to some 400 Portuguese musketeers, whose firepower helped Emperor Galawdewos defeat and kill Ahmad Gran at Wayna Daga.",ev:[["1270","Yekuno Amlak overthrows the last Zagwe king and founds the Solomonic dynasty"],["1445","Zara Yaqob defeats the Adal Sultanate at the Battle of Gomit"],["1529","Ahmad Gran crushes Lebna Dengel at the Battle of Shimbra Kure"],["1543","Galawdewos, aided by Portuguese musketeers, defeats and kills Ahmad Gran at Wayna Daga"],["1769","The Zemene Mesafint, the Era of the Princes, begins as regional lords eclipse the emperors"],["1896","Menelik II routs the Italian army at Adwa, securing Ethiopian independence"],["1936","Italian forces using aerial bombardment and poison gas capture Addis Ababa"],["1974","The Derg deposes Haile Selassie; the monarchy is abolished in March 1975"]]},
  "Fatimid Caliphate": {t:["An Ismaili Shia caliphate born of a secret missionary network in North Africa, set up in 910 as a rival to Abbasid Baghdad.","From Cairo, which it founded, it controlled Red Sea to Mediterranean trade and built al-Azhar, still a leading centre of Islamic learning.","Famine, army factions and a schism in 1094 eroded it until Saladin quietly restored Abbasid prayers in 1171."],dyk:"The Nizari Ismailis who broke away after the 1094 succession crisis gave rise to the imams known today as the Aga Khans, a lineage tracing back to the Fatimid missionary network.",ev:[["910","Abdallah al-Mahdi Billah is proclaimed caliph at Raqqada after the Kutama overthrow the Aghlabids"],["969","General Jawhar al-Siqilli conquers Egypt; Cairo is founded north of Fustat"],["970","The al-Azhar mosque is begun, later developing into a great teaching institution"],["c. 1048","The Zirid governor of Ifriqiya renounces Fatimid allegiance, severing North Africa"],["1073","Badr al-Jamali arrives and takes over as vizier and commander after years of chaos"],["1094","Succession crisis over Nizar splits the Ismaili community permanently"],["1099","The First Crusade captures Jerusalem"],["1171","Saladin restores prayers for the Abbasid caliph; the last Fatimid caliph al-Adid dies"]]},
  "French Empire": {t:["France built two colonial empires: one in North America and the Caribbean, lost in 1763, and a larger one in Africa and Asia.","Plantation slavery made Saint-Domingue the world's richest colony, while the later empire extracted raw materials for French industry.","Nationalist wars from Dien Bien Phu to Algeria ended it, leaving French as an official language in twenty-nine countries."],dyk:"By the 1780s Saint-Domingue, now Haiti, produced around 40 per cent of Europe's sugar and some 60 per cent of its coffee.",ev:[["1534","Jacques Cartier reaches the Gulf of St. Lawrence and claims land for Francis I"],["1608","Samuel de Champlain founds Quebec as the capital of New France"],["1664","Colbert establishes the French East India Company"],["1763","Treaty of Paris cedes Canada and lands east of the Mississippi to Britain"],["1830","France invades Algiers, beginning the second colonial empire"],["1954","The Viet Minh force the surrender of the French garrison at Dien Bien Phu"],["1960","Fourteen sub-Saharan colonies and trust territories become independent"],["1962","The Evian Accords bring Algerian independence after eight years of war"]]},
  "Garamantian Empire": {t:["A Saharan kingdom in Libya's Fezzan, sustained by underground foggara channels tapping fossil water beneath the desert.","It controlled trans-Saharan routes, sending ivory, enslaved people and wild animals to Carthaginian and Roman markets.","As the water table sank below the channels and trade faltered, it faded into scattered oases before the Arab conquest."],dyk:"In the Wadi al-Ajal alone the Garamantes dug an estimated 550 or more foggara channels with over 100,000 vertical shafts to bring water to their fields.",ev:[["20-19 BCE","Lucius Cornelius Balbus captures Garama, earning Rome's last triumph for a non-imperial general"],["69","The Garamantes join Oea against Leptis Magna and are driven back by Valerius Festus"],["c. 202","Septimius Severus campaigns against the Garamantes and sets outposts at Ghadames and Bu Njem"],["429","The Vandal conquest of North Africa begins, disrupting Mediterranean trade demand"],["c. 500","Garama is greatly reduced as falling groundwater starves the foggara system"],["640s","Arab expeditions into the Fezzan begin, meeting little significant resistance"]]},
  "German Empire": {t:["Proclaimed at Versailles in 1871 after victory over France, it united German states under Prussian leadership.","It became continental Europe's industrial giant and created the world's first national social insurance system.","After Bismarck's dismissal its diplomacy unravelled; defeat in the First World War ended it in revolution in 1918."],dyk:"By 1913 German chemical firms such as BASF, Bayer and Hoechst supplied roughly 80 to 90 per cent of the world's synthetic dyes.",ev:[["1871","Wilhelm I is proclaimed German Emperor in the Hall of Mirrors at Versailles"],["1878","Bismarck's Anti-Socialist Laws target the rising labour movement"],["1883","Bismarck introduces national health insurance, the first of his social insurance laws"],["1890","Wilhelm II dismisses Bismarck; the Reinsurance Treaty with Russia lapses"],["1898","The first Naval Law launches Tirpitz's challenge to British sea power"],["1914","The Schlieffen Plan fails at the Marne, locking Germany into a two-front war"],["1916","Verdun and the Somme cost roughly 300,000 German dead without a breakthrough"],["1918","The Kiel mutiny sparks revolution; Wilhelm II abdicates and the armistice follows"]]},
  "Ghana Empire": {t:["Wagadou, the Soninke kingdom Arab writers called Ghana, sat between West Africa's goldfields and the Saharan caravan routes.","It grew rich by taxing gold going north and salt going south, and its gold supplied mints across North Africa and Muslim Spain.","Almoravid attacks, shifting trade routes and drought broke its power; Mali absorbed what remained in the thirteenth century."],dyk:"Ghana's king kept every gold nugget found in the kingdom for himself, letting subjects trade only gold dust, a deliberate way to stop the price of gold from collapsing.",ev:[["c. 750","Wagadou crystallises as a recognisable state under Soninke rule"],["c. 992","Ghana captures Awdaghast, the southern terminus of the western trans-Saharan route"],["1054","The Almoravids seize Awdaghast, ending some sixty years of Ghanaian control"],["1068","Al-Bakri completes his famous description of the gilded royal court"],["1076","Almoravids sack Koumbi Saleh, reducing Ghana for a time to a tributary"],["1087","Death of the Almoravid leader Abu Bakr ibn Umar lets the Soninke regain independence"],["c. 1235","Sundiata Keita defeats Sumanguru at Kirina; Ghana's remnant passes into the Mali Empire"],["c. 1240","The old capital is traditionally said to have been abandoned"]]},
  "Gokturk Empire": {t:["The first state to bear the name Turk, a steppe khaganate that at its peak stretched from Manchuria towards the Black Sea.","It protected Silk Road trade, drew vast silk tribute from China and left the Orkhon Inscriptions, the oldest major Turkic texts.","Rival claimants under lateral succession and Chinese divide-and-rule broke it twice; the Uyghurs ended it for good in 744."],dyk:"According to the Orkhon Inscriptions, Ilterish Qaghan began rebuilding the fallen Turkic empire in 682 with just seventeen men in the Yin Shan mountains.",ev:[["552","Bumin destroys the Rouran and declares himself Qaghan of the Turks"],["568","The Gokturks send their first embassy to Constantinople, led by the Sogdian Maniakh"],["576","Gokturk forces reach the Crimea and besiege the Byzantine city of Bosporus"],["c. 603","The First Khaganate splits into eastern and western halves"],["630","Tang China conquers the Eastern Khaganate and captures Illig Qaghan"],["682","Ilterish Qaghan founds the Second Khaganate through guerrilla warfare"],["734","Bilge Qaghan is poisoned by one of his own ministers"],["744","Uyghurs, Karluks and Basmyls seize Otuken and kill the last Gokturk qaghan"]]},
  "Gupta Empire": {t:["A north Indian empire built from the Ganges plain by Chandragupta I and Samudragupta from around 320 CE.","Its age saw Aryabhata's mathematics, Kalidasa's poetry and art that shaped Southeast Asia, earning it the name Golden Age of India.","Huna invasions and feudatories who broke away dissolved it into regional kingdoms by the mid-sixth century."],dyk:"Aryabhata, whose Aryabhatiya dates to 499 CE, approximated pi to four decimal places and proposed that the earth rotates on its axis.",ev:[["c. 320","Chandragupta I ascends and takes the title Maharajadhiraja, great king of kings"],["c. 335","Samudragupta begins the campaigns recorded on the Allahabad Pillar"],["c. 375","Chandragupta II succeeds and later defeats the Shaka satraps of western India"],["c. 455","Skandagupta takes the throne and repels a major Huna incursion"],["499","Aryabhata composes the Aryabhatiya"],["c. 500","Hunas under Toramana and Mihirakula occupy much of northwestern and central India"],["c. 528","Aulikara king Yashodharman, not a Gupta, defeats Mihirakula"],["c. 540","Vishnugupta, the last recognised Gupta emperor, rules only a remnant kingdom"]]},
  "Han Dynasty": {t:["Founded by the commoner Liu Bang in 202 BCE, the Han replaced Qin brutality with Confucian government and lasted four centuries.","It opened the Silk Road, drove back the Xiongnu and built a bureaucratic model of rule that China kept until 1912.","Landed elites, court feuds and the Yellow Turban Rebellion handed power to warlords, and the dynasty ended in 220."],dyk:"China's majority ethnic group still calls itself Han, after this dynasty, more than eighteen centuries after it fell.",ev:[["202 BCE","Liu Bang defeats Xiang Yu and proclaims himself emperor as Gaozu"],["141 BCE","Emperor Wu takes the throne, beginning the dynasty's most expansive reign"],["124 BCE","The Imperial Academy is founded to train officials in the Confucian classics"],["119 BCE","Wei Qing and Huo Qubing drive Xiongnu power beyond the Gobi Desert"],["2","The Han census records a population of nearly 60 million"],["25","The dynasty is restored as the Eastern Han after Wang Mang's usurpation"],["184","The Yellow Turban Rebellion erupts amid famine and peasant displacement"],["220","Cao Pi deposes Emperor Xian and declares the Wei dynasty, ending the Han"]]},
  "Hittite Empire": {t:["A Bronze Age power ruled from Hattusa in central Anatolia that rivalled Egypt for control of Syria and the Levant.","Its vassal treaties and its peace with Ramesses II are among the earliest milestones of international law and diplomacy.","It vanished in the Bronze Age Collapse when Hattusa was abandoned and burned c. 1180 BCE; Neo-Hittite city-states carried on its legacy."],dyk:"A replica of the Hittite-Egyptian peace treaty, the earliest to survive in both parties' versions, hangs at the United Nations headquarters in New York.",ev:[["c. 1650 BCE","Hattusili I founds the Old Kingdom with Hattusa as his capital"],["c. 1595 BCE","Mursili I raids Babylon, ending the First Babylonian Dynasty"],["c. 1525 BCE","The Edict of Telipinu recounts decades of palace murders and coups"],["c. 1344 BCE","Suppiluliuma I takes the throne and goes on to dismantle the Mitanni kingdom"],["1274 BCE","Muwatalli II fights Ramesses II at Kadesh, perhaps the largest chariot battle of antiquity"],["c. 1259 BCE","Hattusili III and Ramesses II conclude the Treaty of Kadesh"],["c. 1180 BCE","Hattusa is abandoned and burned under Suppiluliuma II"]]},
  "Holy Roman Empire": {t:["A loose union of princes, bishops and free cities in central Europe, under an elected emperor from 962 to 1806.","Its fragmentation let the Reformation survive and produced religious settlements that shaped the modern idea of state sovereignty.","Napoleon's Confederation of the Rhine made the title meaningless, and Francis II quietly dissolved the empire in 1806."],dyk:"The empire had no standing army for most of its history; its military strength depended on contingents the princes sent only when politically willing.",ev:[["800","Pope Leo III crowns Charlemagne emperor in Rome on Christmas Day"],["962","Otto I is crowned emperor by Pope John XII, the empire's functional founding"],["1176","The Lombard League defeats Frederick Barbarossa at Legnano"],["1356","Charles IV's Golden Bull fixes the election of the emperor by seven electors"],["1517","Martin Luther launches the Reformation at Wittenberg"],["1555","The Peace of Augsburg lets rulers choose Catholicism or Lutheranism for their lands"],["1648","The Peace of Westphalia ends the Thirty Years' War and lets princes make foreign alliances"],["1806","Francis II abdicates and declares the Holy Roman Empire dissolved"]]},
  "Ilkhanate": {t:["The Mongol khanate founded by Hulagu in Persia and Iraq after he destroyed the Abbasid Caliphate at Baghdad in 1258.","Under Ghazan it became a Persianised Islamic state whose reforms, trade and court scholarship linked China and the Mediterranean.","When Abu Said died without an heir in 1335 it broke into rival successor states such as the Jalayirids and Chupanids."],dyk:"Rashid al-Din's Jami al-Tawarikh, written at the Ilkhanid court with Mongol, Chinese, Persian and European informants, is often called the first universal history of Eurasia.",ev:[["1256","Hulagu destroys the Nizari Ismaili state and takes Alamut"],["1258","Mongol forces capture Baghdad and execute the Abbasid caliph al-Mustasim"],["1260","The Mamluks defeat Kitbuqa's Mongol army at Ain Jalut in Galilee"],["1287","The monk Rabban Sauma begins an embassy to Europe seeking an alliance against the Mamluks"],["1295","Ghazan converts to Islam and begins sweeping reforms with Rashid al-Din"],["1299","Ghazan wins at Wadi al-Khaznadar, briefly taking Damascus"],["1318","Rashid al-Din, the state's ablest administrator, is executed"],["1335","Abu Said dies without an heir and the Ilkhanate fragments"]]},
  "Italian Empire": {t:["Newly unified Italy's late bid for colonies, spanning Eritrea, Somaliland, Libya, the Dodecanese and, briefly, Ethiopia.","Under Mussolini it became a vehicle for Fascist dreams of a new Roman empire, enforced with poison gas, camps and racial laws.","It collapsed within three years in the Second World War, and the 1947 Treaty of Paris formally stripped Italy of its colonies."],dyk:"In 1938 Governor Italo Balbo oversaw the arrival in Libya of some twenty thousand Italian settlers in a single state-organised convoy.",ev:[["1882","The Italian government takes over Assab Bay on the Red Sea, its first colonial foothold"],["1890","The colony of Eritrea is formally proclaimed"],["1896","Menelik II routs General Baratieri's army at Adwa"],["1911","The Italo-Turkish War begins, bringing coastal Libya and the Dodecanese under Italian control"],["1931","Libyan resistance leader Omar Mukhtar is executed"],["1936","Mussolini proclaims the empire after Addis Ababa falls; Africa Orientale Italiana is formed"],["1941","British and Commonwealth forces end Italian rule in East Africa; Haile Selassie returns"],["1943","The Allies invade Sicily; Mussolini is dismissed and Italy signs an armistice"]]},
  "Jolof Empire": {t:["A Wolof-led confederation in Senegambia, uniting Waalo, Cayor, Baol, Sine and Saloum under an overlord called the buurba.","It linked the interior with the Atlantic coast just as Portuguese traders arrived, and spread Wolof language across the region.","Atlantic wealth let coastal vassals break away; Cayor's victory at Danki c. 1549 ended Jolof's imperial phase."],dyk:"In 1488 the exiled Jolof prince Bemoim was received and baptised at the court of King Joao II in Lisbon.",ev:[["c. 1350","Ndiadiane Ndiaye, by tradition, draws the Wolof and Serer states into the Jolof confederation"],["1455","Venetian Alvise Cadamosto sees Portuguese traders exchanging horses for slaves on the Senegal coast"],["1488","Exiled Jolof prince Bemoim is baptised at the court of Joao II in Lisbon"],["c. 1549","Amari Ngone Sobel Fall of Cayor defeats and kills the buurba Leele Fuli Fak at Danki"],["1890","The rump kingdom of Jolof is absorbed into French Senegal"]]},
  "Kaabu Empire": {t:["A Mandinka state in today's Guinea-Bissau and Senegambia that began as a western province of the Mali Empire.","Ruled by the nyancho warrior aristocracy, it grew rich by selling war captives into the Atlantic slave trade for guns and goods.","Fula forces from Futa Jallon destroyed its capital Kansala in 1867, and the region later fell to European colonial rule."],dyk:"At the fall of Kansala in 1867, the mansaba Janke Waali had the gunpowder stores ignited, destroying the city, its defenders and many of the attackers.",ev:[["13th century","Tiramakhan Traore, by tradition, founds Kaabu as a western province of Mali"],["15th-16th centuries","Kaabu becomes autonomous as Mali's central authority weakens"],["1588","The Portuguese found Cacheu, a key coastal port for Kaabu's slave trade"],["1867","Futa Jallon forces besiege and destroy Kansala, ending the empire"]]},
  "Kanem-Bornu Empire": {t:["A Lake Chad empire ruled for close to eight centuries by the Sayfawa dynasty, one of the longest in world history.","Its control of the trans-Saharan route to Tripoli and its Islamic institutions tied the central Sudan to the Muslim world.","The Fulani jihad, the rise of the shehus and Rabih's 1893 conquest ended it before European powers divided the land."],dyk:"As early as the thirteenth century, a hostel for students and pilgrims from Kanem was maintained in Cairo.",ev:[["c. 1085","Mai Hummay, by tradition, adopts Islam for the ruling house"],["c. 1221","Mai Dunama Dabbalemi begins a reign that expands and institutionalises the state"],["c. 1470","Driven from Kanem by the Bulala, Mai Ali Gaji founds a new capital at Ngazargamu in Bornu"],["1808","Fulani jihadist forces sack Ngazargamu"],["1846","Umar, son of al-Kanemi, ends the Sayfawa line and founds the dynasty of the shehus"],["1893","Sudanese warlord Rabih az-Zubayr conquers Bornu and destroys Kukawa"],["1900","French forces kill Rabih at Kousseri; Britain, France and Germany partition the territory"]]},
  "Khazar Khaganate": {t:["A Turkic steppe state between the Volga and the Caucasus, ruled jointly by a sacral khagan and a military bek.","It held back Arab expansion north of the Caucasus and taxed the Volga trade linking the Islamic world to Northern Europe.","Its ruling elite famously converted to Judaism; Sviatoslav of Kiev's campaign of the 960s brought the khaganate down."],dyk:"The Byzantine emperor Constantine V married the Khazar princess Tzitzak, and their son reigned as Leo IV, known as 'the Khazar'.",ev:[["mid-600s","The khaganate emerges on the Pontic-Caspian steppe as the Western Turkic Khaganate fragments"],["730","The Khazars destroy an Arab army at Marj Ardabil"],["737","Marwan ibn Muhammad's great campaign forces a temporary Khazar submission"],["c. 840","The fortress of Sarkel is built on the Don with Byzantine engineers"],["c. 965","Sviatoslav I of Kiev captures Sarkel and sacks Atil, dismantling the khaganate"]]},
  "Khmer Empire": {t:["A Cambodian empire founded in 802, whose god-kings ruled much of mainland Southeast Asia from Angkor.","Vast reservoirs and canals fed a huge population and paid for Angkor Wat and Angkor Thom, among the world's great monuments.","Strained waterworks, drought, Thai invasions and shifting trade led the court to abandon Angkor for the Phnom Penh region."],dyk:"An inscription at the temple of Ta Prohm records thousands of villages and attendants assigned to its upkeep, showing how temples worked as economic centres.",ev:[["802","Jayavarman II is consecrated universal monarch on Phnom Kulen, founding the empire"],["late 800s","Yasovarman I settles the capital at Angkor"],["1177","Cham forces sack Angkor"],["1203","Jayavarman VII, having expelled the Cham, subjugates Champa itself"],["1296","Chinese envoy Zhou Daguan arrives and later writes a vivid account of Angkor"],["1431","The Thai kingdom of Ayutthaya captures Angkor, by traditional dating"]]},
  "Khwarazmian Empire": {t:["A Turkic-ruled, Persianised empire that rose from the Amu Darya oasis of Khwarazm to rule from western Iran to the Syr Darya.","It grew rich on Silk Road trade, but rapid conquests left it with divided commands and loyalties it never resolved.","Killing a Mongol envoy in 1218 brought Genghis Khan's invasion, which destroyed the empire and opened Iran to the Mongols."],dyk:"In 1217 Muhammad II marched on Baghdad against the Abbasid caliph, but the campaign was abandoned when snow overwhelmed his army in the Zagros mountains.",ev:[["1172","Ala ad-Din Tekish comes to power and throws off Seljuk overlordship"],["1194","Tekish defeats and kills Toghrul III, the last Seljuk sultan of Iraq"],["1200","Ala ad-Din Muhammad II takes the throne and expands against the Ghurids and Qara Khitai"],["1217","Muhammad II's march on Baghdad is abandoned in the snows of the Zagros"],["1218","Otrar's governor massacres a Mongol-sponsored caravan; the shah executes a Mongol envoy"],["1220","Bukhara and Samarkand fall to Genghis Khan's armies"],["1221","The empire effectively ceases to exist; Jalal ad-Din is defeated on the Indus"],["1231","Jalal ad-Din dies after a decade of resistance in Iran and the Caucasus"]]},
  "Kongo Empire": {t:["A Central African kingdom south of the lower Congo River, ruled from Mbanza Kongo by an elected manikongo.","It was among the first African states to sustain diplomacy with Europe, adopting Christianity and Portuguese literacy.","The Atlantic slave trade fuelled rivalries, and defeat at Mbwila in 1665 tipped it into civil war and long decline."],dyk:"Kongo used nzimbu shells, gathered on the royal fishery of Luanda Island, as currency alongside squares of finely woven raffia cloth.",ev:[["1483","Portuguese navigator Diogo Cao reaches the mouth of the Congo"],["1491","King Nzinga a Nkuwu is baptised as Joao I"],["1509","Afonso I wins the throne by defeating his half-brother Mpanzu a Kitima"],["1526","Afonso I writes to Joao III of Portugal protesting the abuses of the slave trade"],["1568","Jaga invaders drive Alvaro I from his capital until Portuguese troops restore him"],["1665","Portuguese forces defeat Kongo at Mbwila, killing King Antonio I"],["1706","Beatriz Kimpa Vita, leader of the Antonian movement, is executed"],["1709","Pedro IV reoccupies Sao Salvador and nominally reunifies the kingdom"]]},
  "Kushite Empire": {t:["A Nubian kingdom on the Nile south of Egypt, centred first at Napata and later at Meroe.","Its kings conquered Egypt and ruled it as the Twenty-Fifth Dynasty, then built an iron-working, pyramid-building civilisation at Meroe.","Shifting trade, environmental strain and pressure from Aksum ended Kush as a unified state by the mid-fourth century CE."],dyk:"The Kushites built more pyramids, at El-Kurru, Nuri and Meroe, than were built in Egypt itself.",ev:[["c. 728 BCE","Piye defeats the Delta coalition of Tefnakht and records his triumph at Jebel Barkal"],["671 BCE","The Assyrian king Esarhaddon takes Memphis"],["663 BCE","Ashurbanipal's army sacks Thebes, ending Kushite rule in Egypt"],["c. 593 BCE","An Egyptian army under Psamtik II raids Nubia"],["c. 300 BCE","The royal centre's move south to Meroe is complete"],["20s BCE","Kush raids Roman Egypt; Petronius' punitive expedition ends in a peace favourable to Kush"],["c. 350","King Ezana of Aksum records an invasion of Kush along the Nile"]]},
  "Luba Empire": {t:["The Luba Empire was a sacred kingship centred on the Upemba Depression in what is now south-eastern DR Congo.","Its model of royal power, checked by the Bambudye society, was copied by neighbours such as the Lunda across the southern savanna.","A succession war after c. 1870, slave raiding and Congo Free State conquest in the 1890s ended its independence."],dyk:"Luba historians kept royal memory on the lukasa, a hand-held beaded board whose patterns of beads and shells helped Bambudye adepts recall kings, places and lineages.",ev:[["c. 1585","Kalala Ilunga overthrows Nkongolo Mwamba and founds the Second Luba Dynasty"],["c. 1780","Ilunga Sungu begins the reign that opens the empire's apogee"],["c. 1810","Kumwimbe Ngombe succeeds; Luba expeditions push towards Lake Tanganyika"],["c. 1870","Death of Ilunga Kabale triggers a long civil war between rival royal claimants"],["1890s","Congo Free State forces absorb the divided Luba lands into Leopold II's colony"],["1917","Kasongo Nyembo is captured after years of resisting Free State and Belgian rule"]]},
  "Lunda Empire": {t:["The Lunda Empire was a tributary state of the Central African savanna, ruled by a sacred king titled the Mwaant Yaav.","Positional succession and perpetual kinship let it absorb chiefdoms without removing their rulers, linking the interior to Atlantic trade.","Succession disputes, the rise of the Chokwe and colonial partition in the 1890s broke it up, though the Mwaant Yaav title survives."],dyk:"Under perpetual kinship, a new Lunda office-holder inherited his predecessor's identity and relationships, so ties between chiefdoms could last for generations unchanged.",ev:[["16th century","Tradition: Luba hunter-prince Chibinda Ilunga marries the Lunda heiress Lueji, bringing sacred kingship"],["Late 17th century","Mwaant Yaav I, traditionally Naweej I, rules a regional power from the royal musumba"],["c. 1740","An eastern expedition founds the kingdom of Kazembe on the Luapula River"],["Mid-1880s","The Chokwe, armed through the rubber, wax and ivory trades, overrun the Lunda capital"],["1890s","Lunda lands are partitioned between the Congo Free State, Portuguese Angola and Northern Rhodesia"]]},
  "Macedonian Empire": {t:["Philip II turned Macedon from a raided frontier kingdom into the master of Greece with a pike phalanx and Companion cavalry.","Alexander the Great conquered the Achaemenid Empire from Egypt to the Indus, spreading Greek language and cities across Asia.","It split among his generals after 323 BCE, but their kingdoms created the Hellenistic world that Rome later absorbed."],dyk:"Philip II's phalanx carried the sarissa, a pike of up to about six metres, letting several ranks present their points to the enemy at once.",ev:[["359 BCE","Philip II becomes king of Macedon and begins reforming its army"],["338 BCE","Philip defeats Athens and Thebes at Chaeronea and becomes master of Greece"],["334 BCE","Alexander crosses into Asia and wins his first victory at the Granicus"],["331 BCE","Alexander defeats Darius III at Gaugamela, sealing the fall of Persia"],["326 BCE","Alexander defeats Porus at the Hydaspes in India"],["323 BCE","Alexander dies at Babylon, leaving no clear successor"],["168 BCE","Rome defeats the last Antigonid king, Perseus, at Pydna"],["146 BCE","Macedonia becomes a Roman province, ending independent Macedonian rule"]]},
  "Majapahit Empire": {t:["Majapahit was a Hindu-Buddhist kingdom in eastern Java that dominated the archipelago's sea lanes in the 14th century.","Rice from the Brantas valley and control of the spice trade funded fleets, temples and a network of tribute-paying vassals.","Civil war, Malacca's rise and Muslim coastal sultanates such as Demak eroded it; its court culture lived on in Bali."],dyk:"Majapahit's founder Raden Wijaya used a Mongol army sent by Kublai Khan to defeat his rival, then turned on the invaders and drove them from Java.",ev:[["1292","Jayakatwang of Kediri kills Kertanegara, ending the Singhasari kingdom"],["1293","Raden Wijaya expels the Mongols and becomes Majapahit's first king"],["1343","Forces directed by Gajah Mada subjugate Bali"],["1350","Hayam Wuruk begins the reign that marks Majapahit's height"],["1357","The Sundanese royal party is massacred at the Battle of Bubat"],["1365","Mpu Prapanca completes the Nagarakretagama, describing the realm at its peak"],["1404–1406","The Regreg War between the western and eastern courts drains the kingdom"],["c. 1527","Demak conquers the last reduced Majapahit court, probably at Kediri"]]},
  "Mali Empire": {t:["The Mali Empire was a Mandinka state founded by Sundiata Keita that dominated West Africa from the 13th century.","Its gold from Bambuk and Bure fed trans-Saharan trade and made Timbuktu and Djenné centres of commerce and Islamic learning.","Succession disputes, Tuareg and Songhai attacks and shifting trade routes shrank it to its Manding heartland by the 1600s."],dyk:"Mansa Musa spent so much gold in Cairo on his 1324 pilgrimage that it was remembered for years, and Mali soon appeared on the Catalan Atlas of 1375.",ev:[["c. 1235","Sundiata Keita defeats Sumanguru Kanté of Sosso at the Battle of Kirina"],["1240","Mali traditionally captures Koumbi Saleh, the former capital of Ghana"],["c. 1312","Mansa Musa begins his reign, Mali's era of greatest renown"],["1324","Mansa Musa makes his pilgrimage to Mecca, dazzling Cairo with gold"],["1352–1353","Ibn Battuta visits and describes the court of Mansa Sulayman"],["c. 1433","The Tuareg seize Timbuktu and Walata"],["1468","Songhai ruler Sonni Ali captures Timbuktu"],["c. 1610","Death of Mahmud IV, the last powerful mansa; the kingdom splits among his heirs"]]},
  "Mamluk Sultanate": {t:["The Mamluk Sultanate was ruled from Cairo by slave soldiers, renewed by fresh purchases rather than hereditary succession.","It halted the Mongols at Ain Jalut, ended the Crusader states and grew rich on the spice trade between India and Europe.","Plague, Portuguese competition at sea and Ottoman guns brought it down, ending with Selim I's conquest of Egypt in 1517."],dyk:"Though rulers of slave origin, the Mamluk sultans hosted a line of Abbasid caliphs in Cairo from 1261, whose nominal blessing lent them religious legitimacy.",ev:[["1250","Mamluks assassinate Turanshah, the last Ayyubid sultan of Egypt, and seize power"],["1260","Qutuz and Baybars defeat the Mongols at Ain Jalut; Baybars then takes the throne"],["1291","Al-Ashraf Khalil captures Acre, ending the Crusader states"],["1315","Al-Nasir Muhammad orders the rawk, a new land survey that reshapes the iqta system"],["1347","The Black Death reaches Egypt, beginning repeated catastrophic population losses"],["1382","Barquq inaugurates the Burji regime of Circassian mamluks"],["1509","The Portuguese defeat a Mamluk fleet at Diu, cutting customs revenue"],["1517","Selim I wins at Ridaniya and conquers Egypt, ending Mamluk sovereignty"]]},
  "Maratha Empire": {t:["The Maratha Empire grew from Shivaji's hill forts in the Western Ghats into a confederacy that dominated 18th-century India.","It broke Mughal supremacy, reaching Attock on the Indus in 1758 and later controlling Delhi and the Mughal emperor.","Defeat at Panipat in 1761, rivalry among its chiefs and three wars with the East India Company ended its independence in 1818."],dyk:"The Marathas built a capable navy with sea forts such as Sindhudurg; under Kanhoji Angre in the early 18th century it challenged even the English and Dutch.",ev:[["1646","Shivaji captures the fort of Torna, beginning his rise"],["1659","Shivaji kills the Bijapur general Afzal Khan at Pratapgad"],["1674","Shivaji is crowned Chhatrapati at Raigad, formally asserting sovereignty"],["1689","Shivaji's son Sambhaji is executed during the long war with Aurangzeb"],["1728","Peshwa Baji Rao I defeats the Nizam at Palkhed"],["1758","Maratha armies reach Attock on the Indus"],["1761","The Durrani army of Ahmad Shah Abdali crushes the Marathas at the Third Battle of Panipat"],["1818","Peshwa Baji Rao II surrenders to the British and the Peshwa's office is abolished"]]},
  "Maurya Empire": {t:["The Maurya Empire, ruled from Pataliputra, was the first state to unite almost the whole Indian subcontinent.","Its centralised administration and Ashoka's edicts promoting dhamma helped carry Buddhism across Asia.","It fell apart after Ashoka's death and ended c. 185 BCE when Pushyamitra Shunga killed the last emperor, Brihadratha."],dyk:"Ashoka's Lion Capital from Sarnath, carved from polished sandstone over 2,000 years ago, is today the national emblem of the Republic of India.",ev:[["c. 321 BCE","Chandragupta Maurya overthrows the Nanda dynasty of Magadha"],["c. 305–303 BCE","Chandragupta gains the north-west from Seleucus I in exchange for 500 war elephants"],["c. 261 BCE","Ashoka conquers Kalinga, then renounces conquest by force"],["c. 232 BCE","Ashoka dies and the empire begins a rapid decline"],["c. 185 BCE","Pushyamitra Shunga assassinates Brihadratha, ending Maurya rule"]]},
  "Median Empire": {t:["The Median Empire grew from a confederation of Zagros tribes into a leading Near Eastern power ruled from Ecbatana.","Allied with Babylon, the Medes destroyed Assyria, sacking Ashur in 614 BCE and Nineveh in 612 BCE.","Cyrus the Great absorbed it c. 550 BCE, but its nobles and court customs lived on inside the Achaemenid Empire."],dyk:"Median influence on Persia ran so deep that Greek writers often called the Persians 'Medes' and termed collaboration with Persia 'Medism'.",ev:[["c. 700 BCE","Deioces, according to Herodotus, unites the Median clans and founds Ecbatana"],["c. 653 BCE","Phraortes dies and a period of Scythian domination begins"],["c. 625 BCE","Cyaxares restores Median power and reorganises the army"],["614 BCE","The Medes capture Ashur"],["612 BCE","Cyaxares and Nabopolassar of Babylon destroy Nineveh"],["585 BCE","War with Lydia ends after the battle of the eclipse, fixing the Halys River frontier"],["c. 550 BCE","Astyages' army mutinies and hands him to Cyrus, who seizes Ecbatana"]]},
  "Ming Empire": {t:["The Ming dynasty restored Han Chinese rule in 1368 after driving the Mongol Yuan court back to the steppe.","Its examination-based bureaucracy, Zheng He's voyages and global silver trade made it a centre of the early modern world.","Fiscal crisis, famine and rebellion let Li Zicheng take Beijing in 1644, opening the way for the Manchu Qing."],dyk:"The Ming Great Wall seen by visitors today is largely a 16th-century brick-faced work, built after the Zhengtong Emperor was captured by the Oirats at Tumu in 1449.",ev:[["1363","Zhu Yuanzhang defeats Chen Youliang at the naval battle of Lake Poyang"],["1368","Zhu Yuanzhang proclaims the Ming dynasty and his armies take the Yuan capital, Dadu"],["1405","Zheng He's first expedition sets out on voyages that reach East Africa by 1433"],["1420","The Forbidden City is completed in the Yongle Emperor's new capital, Beijing"],["1449","The Oirat Mongols capture the Zhengtong Emperor at Tumu"],["1592–1598","The Ming intervene in Korea against the Japanese invasions"],["1644","Li Zicheng takes Beijing; the Chongzhen Emperor takes his own life and the Qing occupy the city"],["1662","The last Southern Ming loyalist regime comes to an end"]]},
  "Mitanni Empire": {t:["Mitanni was a Late Bronze Age great power in northern Syria, with a Hurrian population and kings bearing Indo-Aryan names.","Famed for chariot warfare, it rivalled and later allied with Egypt, sealing ties through royal marriages and letters.","A murdered king and contested succession let the Hittites and Assyria carve it up; Assyria annexed the remnant by c. 1250 BCE."],dyk:"A Mitanni treaty with the Hittites calls on the gods Mitra, Varuna, Indra and the Nasatyas, some of the earliest evidence for Indo-Aryan languages anywhere.",ev:[["c. 1500 BCE","Barattarna extends Mitanni authority over Aleppo and Alalakh"],["c. 1450 BCE","Shaushtatar sacks Ashur and rules vassals such as Arrapha"],["c. 1340 BCE","Hittite king Suppiluliuma I sacks the capital, Washukanni"],["c. 1330 BCE","The Shattiwaza treaty makes Mitanni a Hittite vassal"],["Mid-13th century BCE","Shalmaneser I of Assyria crushes Shattuara II and annexes Hanigalbat"]]},
  "Mongol Empire": {t:["Genghis Khan united the steppe tribes in 1206 and built the largest contiguous land empire in history.","Under the Pax Mongolica, protected trade routes linked China, the Middle East and Europe as never before.","Succession wars split it into rival khanates after 1260; the Yuan fell to the Ming in 1368."],dyk:"The Mongols generally tolerated diverse faiths, even granting clergy tax exemptions in return for prayers for the khan.",ev:[["1206","Temüjin is proclaimed Genghis Khan at a kurultai on the Mongolian steppe"],["1219–1221","Genghis Khan destroys the Khwarazmian Empire in Central Asia"],["1223","Subutai and Jebe defeat the Rus and Kipchaks at the Kalka River"],["1241","Mongol armies defeat Polish and Hungarian forces at Legnica and Mohi"],["1258","Hülegü sacks Baghdad, ending the Abbasid Caliphate"],["1260–1264","The succession war between Kublai and Ariq Böke splits the empire into khanates"],["1294","Kublai's death removes the last Great Khan widely recognised across the empire"],["1368","The Ming drive the Yuan dynasty out of China"]]},
  "Mughal Empire": {t:["The Mughal Empire was founded by the Timurid prince Babur in 1526 and came to rule most of the Indian subcontinent.","Akbar's cash revenue system, ranked nobility and religious accommodation built one of the largest economies of its age.","Aurangzeb's costly wars, regional revolts and the rise of the East India Company hollowed it out before its end in 1858."],dyk:"Babur descended from Timur on his father's side and from Genghis Khan on his mother's, and his dynasty's name comes from the Persian word for Mongol.",ev:[["1526","Babur defeats Ibrahim Lodi at the First Battle of Panipat and founds the empire"],["1527","Babur defeats the Rajput confederacy of Rana Sanga at Khanwa"],["1555","Humayun recovers Delhi after years of exile under Sher Shah Suri's rule"],["1556","Akbar begins his reign, turning a fragile conquest into a stable empire"],["1564","Akbar abolishes the jizya tax on non-Muslims"],["1687","Aurangzeb annexes Golconda, bringing the empire near its greatest extent"],["1739","Nader Shah of Persia sacks Delhi and carries off the Peacock Throne"],["1858","The British exile Bahadur Shah II, the last emperor, to Rangoon"]]},
  "Mutapa Empire": {t:["The Mutapa Empire was a Shona state between the Zambezi and Limpopo, founded c. 1430 as Great Zimbabwe declined.","Its gold, traded via Swahili merchants at ports such as Sofala, tied the African interior to the Indian Ocean economy.","Succession disputes, Portuguese meddling and the rise of the Rozvi broke its power, though a remnant survived until 1917."],dyk:"In 1561 the Jesuit Gonçalo da Silveira briefly converted the reigning Mwene Mutapa to Christianity, only to be killed at the royal court soon afterwards.",ev:[["c. 1430","Nyatsimba Mutota traditionally founds the state on the northern Zimbabwe plateau"],["1561","Jesuit Gonçalo da Silveira converts the Mwene Mutapa and is then killed at court"],["1571–1573","A large Portuguese expedition under Francisco Barreto fails, largely through disease"],["1607","Gatsi Rusere cedes mining rights to the Portuguese in return for military help"],["1629","The Portuguese depose Kapararidze and install Mavura as a vassal ruler"],["1680s–1690s","The Rozvi under Changamire Dombo supplant Mutapa authority across the plateau"],["1917","The Portuguese suppress the last reduced Mutapa kingdom in the Zambezi valley"]]},
  "Neo-Sumerian Empire": {t:["The Neo-Sumerian Empire, or Third Dynasty of Ur, revived Sumerian rule in southern Mesopotamia after the Akkadian collapse.","Its bureaucracy recorded the economy on tens of thousands of tablets, and its law code is the oldest that survives.","Amorite incursions, grain shortages and breakaway governors weakened it until Elam sacked Ur c. 2004 BCE."],dyk:"The Code of Ur-Nammu, some three centuries older than Hammurabi's, punished many offences with monetary fines rather than physical penalties.",ev:[["c. 2112 BCE","Ur-Nammu founds the Third Dynasty of Ur after Utu-hegal expels the Gutians"],["c. 2094 BCE","Shulgi becomes king and expands and centralises the state"],["c. 2047 BCE","Shulgi's long reign ends; under his successors the empire begins to decline"],["c. 2004 BCE","Elamite forces sack Ur and carry the last king, Ibbi-Sin, into captivity"]]},
  "Ottoman Empire": {t:["The Ottoman Empire grew from a frontier beylik in Anatolia into a power spanning three continents for over six centuries.","Janissary infantry, gunpowder artillery and a sophisticated bureaucracy let it take Constantinople and rule a diverse realm.","Lost wars, nationalist revolts and European debt control eroded it; defeat in the First World War ended the sultanate in 1922."],dyk:"The architect Mimar Sinan is credited with more than three hundred buildings, including the Süleymaniye Mosque in Istanbul and the Selimiye Mosque in Edirne.",ev:[["1302","Osman I defeats a Byzantine force at the Battle of Bapheus"],["1326","Orhan captures Bursa, the dynasty's first true capital"],["1453","Mehmed II captures Constantinople after a siege of some fifty-three days"],["1516–1517","Selim I conquers the Mamluk Sultanate, gaining Egypt, Syria and the holy cities"],["1526","Suleiman the Magnificent destroys the Hungarian royal army at Mohács"],["1683","Jan III Sobieski routs the Ottoman army at the second siege of Vienna"],["1839","The Tanzimat reforms begin to modernise administration and law"],["1922","The Grand National Assembly abolishes the sultanate"]]},
  "Oyo Empire": {t:["The Oyo Empire was a Yoruba savannah state whose cavalry made it the leading power between the Niger and the Volta.","It grew rich on tribute and the Atlantic slave trade, forcing Dahomey into vassalage and shaping the Bight of Benin coast.","Feuds between king and chiefs, Afonja's revolt and the Ilorin emirate destroyed it; Oyo-Ile was abandoned c. 1835–1836."],dyk:"Oyo's council of chiefs could reject an Alaafin by presenting him with an empty calabash or parrots' eggs, after which the king was expected to take his own life.",ev:[["c. 1610","Alaafin Abipa reoccupies Oyo-Ile after some eighty years of exile"],["1726","Oyo begins repeated cavalry invasions of Dahomey"],["1748","A treaty confirms Dahomey as a tribute-paying vassal of Oyo"],["c. 1774","Alaafin Abiodun overthrows and executes Basorun Gaa, who had dominated the state"],["c. 1796","Alaafin Awole is forced to take his own life after his war chiefs mutiny"],["c. 1817","Afonja rebels at Ilorin with Fulani and Hausa support inspired by the Sokoto jihad"],["c. 1835–1836","Oyo-Ile is abandoned; Alaafin Atiba founds a reduced state at New Oyo"],["1888","New Oyo signs a treaty with the British"]]},
  "Parthian Empire": {t:["The Parthian Empire was an Iranian power founded by the Arsacids that ruled from the Euphrates to the Iranian plateau.","Its cavalry held Rome at the Euphrates for centuries, and it profited as the Silk Road link between Rome and Han China.","Noble rivalry, civil wars and Roman captures of Ctesiphon weakened it; Ardashir I's Sasanians ended Arsacid rule in 224 CE."],dyk:"At Carrhae in 53 BCE, the Parthian general Surena kept his horse archers supplied from a camel train of arrows, destroying a Roman army under Crassus.",ev:[["c. 238 BCE","Arsaces I of the Parni seizes the satrapy of Parthia from Andragoras"],["c. 141 BCE","Mithridates I conquers the Seleucid heartland of Mesopotamia"],["53 BCE","Surena's Parthian army destroys the Roman army of Crassus at Carrhae"],["36 BCE","Mark Antony's invasion ends in a costly Roman retreat"],["116","Trajan captures the Parthian capital, Ctesiphon"],["198","Septimius Severus captures Ctesiphon again"],["224","Ardashir I kills Artabanus IV at Hormozdgan, founding the Sasanian Empire"]]},
  "Polish-Lithuanian Commonwealth": {t:["The Commonwealth joined Poland and Lithuania in 1569 into one of Europe's largest states, with an elected king and noble parliament.","Its religious tolerance made it a refuge for dissenters and home to the world's largest Jewish population.","The liberum veto paralysed reform, letting Russia, Prussia and Austria partition it out of existence by 1795."],dyk:"In 1610, after the victory at Klushino, Polish troops occupied Moscow and a group of boyars elected the Polish prince Władysław as Tsar.",ev:[["1569","The Union of Lublin creates the Commonwealth from Poland and Lithuania"],["1573","The Warsaw Confederation guarantees religious peace among the nobility"],["1610","Żółkiewski wins at Klushino and Polish troops occupy Moscow"],["1648","Bohdan Khmelnytsky's Cossack uprising begins in Ukraine"],["1652","Władysław Siciński breaks up the Sejm with a single objection, the first liberum veto"],["1683","Jan III Sobieski leads the cavalry charge that relieves Vienna"],["1791","The Constitution of 3 May abolishes the liberum veto"],["1795","The Third Partition erases the Commonwealth from the map"]]},
  "Portuguese Empire": {t:["Portugal built the first sea-borne trading empire linking Europe, Africa, Asia and the Americas, starting at Ceuta in 1415.","It controlled the spice route around Africa and became the largest national carrier in the Atlantic slave trade.","Dutch rivals, Brazilian independence and colonial wars wore it down; the last territory, Macau, went to China in 1999."],dyk:"Portuguese traders who landed on Tanegashima in 1543 introduced the arquebus to Japan, where gunsmiths quickly copied it and changed Sengoku-era warfare.",ev:[["1415","João I and his sons capture Ceuta, beginning the imperial project"],["1488","Bartolomeu Dias rounds the Cape of Good Hope"],["1498","Vasco da Gama reaches Calicut, opening the sea route to India"],["1500","Pedro Álvares Cabral makes landfall in Brazil"],["1510","Afonso de Albuquerque seizes Goa"],["1578","King Sebastião I is killed at Alcácer Quibir, triggering a succession crisis"],["1822","Brazil declares independence under Pedro I"],["1974","The Carnation Revolution topples the dictatorship and opens the way to African independence"]]},
  "Ptolemaic Empire": {t:["The Ptolemaic Kingdom was a Macedonian dynasty that ruled Egypt as pharaohs from Alexandria for nearly three centuries.","Nile grain made it rich, and Alexandria's Library, Mouseion and Pharos made it the intellectual capital of the Hellenistic world.","Dynastic feuds, native revolts and Roman meddling wore it down; after Actium, Rome annexed Egypt in 30 BCE."],dyk:"The Rosetta Stone, the key to deciphering hieroglyphs, records a Ptolemaic priestly decree of 196 BCE written in hieroglyphic, demotic and Greek.",ev:[["323 BCE","Ptolemy becomes satrap of Egypt after the death of Alexander the Great"],["305 BCE","Ptolemy I Soter proclaims himself king, founding the dynasty"],["283 BCE","Ptolemy II Philadelphus begins his reign over an empire reaching Cyprus and the Aegean"],["217 BCE","Ptolemy IV defeats Antiochus III at Raphia with a phalanx of native Egyptians"],["206–186 BCE","A great native revolt disrupts Upper Egypt"],["196 BCE","Priests issue the decree later inscribed on the Rosetta Stone"],["31 BCE","Octavian defeats Cleopatra VII and Mark Antony at Actium"],["30 BCE","Rome annexes Egypt, ending the Ptolemaic state"]]},
  "Punic Empire": {t:["Carthage, a Phoenician colony of Tyre in Tunisia, built a trading empire across the western Mediterranean.","Its fleets, mercenary armies and Hannibal's invasion of Italy made it Rome's greatest rival for over a century.","Three Punic Wars stripped it of Sicily, Spain and its navy; Rome razed the city in 146 BCE and enslaved its survivors."],dyk:"After destroying Carthage, the Roman Senate ordered the farming treatise of the Carthaginian writer Mago, in twenty-eight books, to be translated into Latin.",ev:[["814 BCE","Elissa (Dido) of Tyre traditionally founds Carthage"],["264–241 BCE","Carthage loses Sicily to Rome in the First Punic War"],["237 BCE","The Barcid family begins the conquest of southern Iberia"],["218 BCE","Hannibal crosses the Alps and invades Italy"],["216 BCE","Hannibal annihilates a Roman army at Cannae"],["202 BCE","Scipio defeats Hannibal at Zama"],["146 BCE","Scipio Aemilianus storms and razes Carthage, ending the Third Punic War"]]},
  "Qing Empire": {t:["The Qing was a Manchu dynasty that conquered Ming China in 1644 and ruled the world's most populous empire.","It reached its greatest extent in the 18th century, setting the territorial framework of modern China.","Rebellion, defeat in the Opium Wars and by Japan, and failed reform led to revolution and Puyi's abdication in 1912."],dyk:"Nurhaci's Banner system organised the entire Jurchen population into colour-coded units that were at once army formations, census registers and social structures.",ev:[["1616","Nurhaci proclaims the Later Jin dynasty"],["1636","Hong Taiji proclaims the Qing dynasty"],["1644","Wu Sangui opens the Shanhai Pass and Qing forces capture Beijing"],["1683","The Qing conquer Taiwan from the Zheng regime, completing consolidation"],["1839–1842","Britain defeats the Qing in the First Opium War, forcing the Treaty of Nanjing"],["1850–1864","The Taiping Rebellion kills an estimated twenty to thirty million people"],["1894–1895","Japan defeats the Qing in the First Sino-Japanese War"],["1912","The six-year-old Puyi abdicates, ending imperial rule in China"]]},
  "Rashidun Caliphate": {t:["The Rashidun Caliphate was the rule of the first four caliphs after the Prophet Muhammad, from Medina, in 632–661.","In about 25 years it destroyed the Sasanian Empire and took Syria and Egypt from Byzantium, setting Arabic on its path to dominance.","Disputes over succession led to the murders of three caliphs and civil war, ending in the hereditary Umayyad Caliphate."],dyk:"Umar adopted the Islamic lunar calendar for official dating, anchoring it to the hijra of 622, the system still used in the Muslim world today.",ev:[["632","Abu Bakr is acclaimed first caliph after Muhammad's death and launches the Ridda Wars"],["634","Umar ibn al-Khattab succeeds Abu Bakr and accelerates the conquests"],["636","Khalid ibn al-Walid and Abu Ubayda defeat the Byzantines at the Yarmuk"],["640–642","Amr ibn al-As conquers Egypt"],["642","Victory at Nihawand breaks the last organised Sasanian field army"],["656","Rebels assassinate Uthman, triggering the First Fitna"],["657","Ali and Muawiya fight the inconclusive Battle of Siffin"],["661","Ibn Muljam assassinates Ali at Kufa; the Umayyad Caliphate follows"]]},
  "Roman Empire": {t:["Augustus turned the war-torn Roman Republic into a monarchy in 27 BCE while keeping the Senate and consuls as a republican facade.","Its professional legions, 80,000 km of roads and Roman law bound a realm stretching from Britain to Mesopotamia.","The West fell gradually through civil war, Gothic and Vandal invasions and lost revenues, ending when Odoacer deposed Romulus Augustulus in 476."],dyk:"When Odoacer deposed the last Western emperor in 476, he simply sent the imperial regalia to Constantinople, and contemporaries barely remarked on it.",ev:[["31 BCE","Octavian defeats Mark Antony and Cleopatra VII at the Battle of Actium"],["27 BCE","The Senate grants Octavian the title Augustus, making him Rome's first emperor"],["9","Arminius destroys three legions under Varus in the Teutoburg Forest, fixing the Rhine frontier"],["212","The Edict of Caracalla extends citizenship to virtually all free inhabitants of the empire"],["313","Constantine and Licinius agree the Edict of Milan, ending the persecution of Christians"],["378","Gothic forces kill Emperor Valens and much of the Eastern field army at Adrianople"],["410","Alaric's Visigoths sack Rome, shattering the myth of Roman invulnerability"],["476","Odoacer deposes Romulus Augustulus, the last Western Roman emperor"]]},
  "Rozvi Empire": {t:["Founded by the former herdsman Changamire Dombo I, the Rozvi Empire dominated the Zimbabwean plateau from the late 17th century.","Dombo drove Portuguese traders and settlers from the interior in the 1690s, keeping the gold and ivory trade under African control.","Drought, a shift in coastal demand and Nguni invasions of the Mfecane destroyed the state in the 1830s; its stone ruins and Mwari cult endured."],dyk:"The Mwari cult patronised by the Rozvi outlived the empire and helped organise resistance to British South Africa Company rule in 1896-1897.",ev:[["c. 1670s","Changamire Dombo builds a power base in Guruuswa under the Mutapa ruler Mukombwe"],["1684","Dombo defeats Mutapa and Portuguese forces at the Battle of Maungwe"],["1693","Rozvi forces destroy the Portuguese settlement at Dambarare and sweep away the interior fairs"],["1695","The Portuguese fair at Masekesa in Manica falls, shortly before Dombo's death"],["c. 1810s","The rise of Shaka's Zulu kingdom sets off the Mfecane, displacing Nguni groups northwards"],["c. 1830s","Zwangendaba's Ngoni cross the plateau; Nyamazana's forces later kill the reigning Changamire"],["c. 1840","Mzilikazi's Ndebele occupy the former Rozvi heartland"]]},
  "Russian Empire": {t:["Proclaimed by Peter the Great in 1721 after defeating Sweden, the Russian Empire grew to cover some 22.8 million square kilometres.","It spread Russian rule from the Baltic to the Pacific and Central Asia, and freed some 23 million serfs in 1861.","Autocracy, rural discontent and the strain of the First World War brought revolution and Nicholas II's abdication in 1917."],dyk:"Before the Battle of Tsushima in 1905, Russia's Baltic Fleet sailed some 18,000 nautical miles around the world, only to be annihilated by Japan.",ev:[["1703","Peter I begins building Saint Petersburg on conquered Swedish territory"],["1709","Peter's reformed army defeats Charles XII of Sweden at Poltava"],["1721","The Senate proclaims Peter I Emperor of All Russia after the Treaty of Nystad"],["1812","Napoleon's Grande Armée invades Russia and is destroyed in the winter retreat"],["1861","Alexander II's Emancipation Edict frees some 23 million privately owned serfs"],["1891","Construction of the Trans-Siberian Railway begins"],["1905","Defeat at Tsushima and revolution force Nicholas II to issue the October Manifesto"],["1917","Nicholas II abdicates after the Petrograd garrison mutinies"]]},
  "Safavid Empire": {t:["Founded in 1501 by the Sufi leader Ismail I, the Safavid Empire reunited Iran for the first time since the Mongol Ilkhanate.","By imposing Twelver Shia Islam it gave Iran its lasting religious identity and turned the Sunni-Shia divide into a frontier with the Ottomans.","Weak harem-raised shahs and religious intolerance left it open to an Afghan revolt; Isfahan fell in 1722 and the dynasty ended in 1736."],dyk:"After surrendering Isfahan in 1722, Shah Sultan Husayn personally placed the crown on the head of the Afghan conqueror Mir Mahmud Hotak.",ev:[["1501","Ismail I defeats the Aq Qoyunlu, seizes Tabriz and proclaims Twelver Shiism the state religion"],["1514","Selim I's Ottoman guns and janissaries rout the Qizilbash cavalry at Chaldiran"],["1598","Shah Abbas I's reformed army recovers Herat and Khorasan from the Uzbeks"],["1604","Abbas I begins moving the Armenian merchants of Julfa to New Julfa beside Isfahan"],["1622","Abbas I expels the Portuguese from Hormuz with English naval help"],["1639","The Treaty of Zuhab fixes a Safavid-Ottoman frontier close to today's Iran-Iraq border"],["1722","Mir Mahmud Hotak wins at Gulnabad and takes Isfahan after a seven-month siege"],["1736","Nader Quli Afshar is proclaimed Shah on the Mughan plain, ending the Safavid dynasty"]]},
  "Sasanian Empire": {t:["The Sasanian Empire ruled Iran and Mesopotamia from 224 to 651, a centralised Zoroastrian monarchy that was Rome's great rival for four centuries.","Its armoured cavalry, fixed land tax and court culture shaped Byzantium and, above all, the Islamic caliphates that followed.","A ruinous war with Byzantium and a succession crisis left it defenceless against the Arab conquests that ended it by 651."],dyk:"Shapur I captured the Roman emperor Valerian at Edessa in 260, the only time a reigning Roman emperor was taken prisoner by a foreign power.",ev:[["224","Ardashir I defeats and kills the last Parthian king, Artabanus IV, at Hormozdgan"],["260","Shapur I captures the Roman emperor Valerian at the Battle of Edessa"],["363","Shapur II wins Nisibis and lands beyond the Tigris in a peace with Rome's Jovian"],["c. 557","Khosrow I and the Göktürks begin destroying the Hephthalite empire"],["614","Khosrow II's general Shahrbaraz captures Jerusalem"],["627","Heraclius defeats the Sasanians at the Battle of Nineveh"],["c. 636","Arab armies destroy the main Sasanian field army at al-Qadisiyyah"],["651","The last king, Yazdegerd III, is murdered near Merv"]]},
  "Seleucid Empire": {t:["Carved out of Alexander's conquests by his general Seleucus I, the Seleucid Empire stretched from Syria towards India at its height.","Its many new Greek cities spread Hellenistic language and culture across the Near East and Central Asia for centuries.","Defeat by Rome, Parthian conquest of the east and endless dynastic civil war reduced it to a Syrian rump that Pompey annexed in 64-63 BCE."],dyk:"Seleucus I traded eastern lands to Chandragupta Maurya for 500 war elephants, which helped him win the Battle of Ipsus in 301 BCE.",ev:[["312 BCE","Seleucus retakes Babylon after the Battle of Gaza, the starting point of the Seleucid era"],["301 BCE","Seleucus and Lysimachus defeat and kill Antigonus at the Battle of Ipsus"],["281 BCE","Seleucus defeats Lysimachus at Corupedium but is assassinated within months"],["212 BCE","Antiochus III begins a seven-year eastern campaign that earns him the title 'the Great'"],["190 BCE","Rome routs Antiochus III's army at the Battle of Magnesia"],["167 BCE","Antiochus IV's suppression of Jewish practice sparks the Maccabean revolt"],["141 BCE","Mithridates I of Parthia conquers Mesopotamia and captures Seleucia-on-Tigris"],["64 BCE","Pompey deposes Antiochus XIII and makes Syria a Roman province"]]},
  "Seljuk Empire": {t:["Oghuz Turks from the Central Asian steppe, the Seljuks built an empire from Khorasan to the Mediterranean and became protectors of Sunni Islam.","Their victory at Manzikert opened Anatolia to Turkish settlement, paving the way for the Ottomans and helping provoke the Crusades.","With no fixed succession, the empire splintered after 1092; Qara Khitai and Khwarazmian blows ended the Great Seljuk line by 1194."],dyk:"The poet and mathematician Omar Khayyam worked under Seljuk patronage on the Jalali solar calendar of 1079, more accurate than the Julian calendar.",ev:[["1037","Tughril and Chaghri take Merv and Nishapur, throwing off Ghaznavid authority"],["1040","Tughril and Chaghri rout the Ghaznavid sultan Masud I at Dandanaqan"],["1055","Tughril enters Baghdad and is recognised as sultan by the Abbasid caliph"],["1071","Alp Arslan defeats and captures the Byzantine emperor Romanos IV at Manzikert"],["1092","Vizier Nizam al-Mulk is assassinated and Malik Shah dies weeks later, sparking civil war"],["1141","The Qara Khitai defeat Sultan Sanjar at the Battle of Qatwan"],["1157","Sanjar's death ends the eastern Seljuk line"],["1194","The Khwarazm Shah Tekish kills Toghrul III, extinguishing the Great Seljuks"]]},
  "Sikh Empire": {t:["Maharaja Ranjit Singh united the feuding Sikh Misls into a single Punjab state, ruling from Lahore from 1799.","Its European-drilled army was among the strongest in India, and it governed a Muslim-majority population with a mixed-faith court.","Without institutions to manage succession, it collapsed into court intrigue after 1839 and was annexed by Britain in 1849."],dyk:"Ranjit Singh had the upper storeys of the Harmandir Sahib covered in gilded copper, giving it its popular name: the Golden Temple.",ev:[["1799","Ranjit Singh, aged eighteen, seizes Lahore from its Bhangi chiefs"],["1801","Ranjit Singh is proclaimed Maharaja of the Punjab on Baisakhi"],["1809","The Treaty of Amritsar fixes the Sutlej as the Sikh-British boundary"],["1819","Sikh forces conquer Kashmir"],["1834","The Sikhs occupy Peshawar, extending the empire to the Khyber Pass"],["1839","Ranjit Singh dies, leaving the Lahore court to rival factions"],["1846","Defeat at Sobraon ends the First Anglo-Sikh War; Kashmir is lost"],["1849","Lord Dalhousie annexes the Punjab after the Second Anglo-Sikh War"]]},
  "Sokoto Caliphate": {t:["Born of Usman dan Fodio's Islamic reform jihad of 1804, the Sokoto Caliphate became the largest state in 19th-century West Africa.","Some thirty emirates shared one Islamic legal culture, a decentralised design that survived for almost a century without succession crises.","British forces with Maxim guns conquered it in 1903, then governed northern Nigeria through its emirs under indirect rule."],dyk:"The last independent Sultan, Attahiru I, answered the British conquest with a hijra eastwards that deliberately echoed dan Fodio's founding migration.",ev:[["1804","Usman dan Fodio makes his hijra to Gudu and declares jihad against the Hausa kings"],["1808","Jihad forces storm Alkalawa, the Gobir capital, killing Sultan Yunfa"],["1817","Dan Fodio dies; his son Muhammad Bello becomes Sultan of Sokoto"],["1886","Britain charters the Royal Niger Company"],["1900","Frederick Lugard proclaims the Protectorate of Northern Nigeria"],["1903","British forces take Kano in February and occupy Sokoto in March"],["1903","Sultan Attahiru I is killed fighting the British at Burmi in July"]]},
  "Song Dynasty": {t:["The Song Dynasty ruled China from 960 to 1279, governed by exam-selected scholar-officials rather than generals.","It ran the world's most commercial economy, with paper money and huge cities, and developed gunpowder weapons, the compass and movable type.","Lacking warhorses and cavalry, it lost the north to the Jurchen in 1127 and fell to Kublai Khan's Mongols after four decades of resistance."],dyk:"Bi Sheng invented movable type using ceramic characters around 1040, some four centuries before Gutenberg's printing press.",ev:[["960","Zhao Kuangyin seizes power in the Chenqiao Mutiny and founds the Song Dynasty"],["1005","The Chanyuan Treaty commits the Song to annual silk and silver payments to the Liao"],["1069","Wang Anshi launches the New Policies to reform state finances"],["1127","The Jurchen Jin capture Kaifeng and carry off emperors Huizong and Qinzong"],["1161","Southern Song fleets defeat the Jin at Tangdao and Caishi"],["1268","The Mongols begin the five-year siege of Xiangyang"],["1276","Lin'an surrenders and the boy emperor Gong is taken north"],["1279","The loyalist fleet is destroyed at Yamen, ending the Song Dynasty"]]},
  "Songhai Empire": {t:["The largest empire in West African history, Songhai controlled the Niger Bend and its trade cities of Gao, Timbuktu and Djenné.","Its wealth came from the trans-Saharan gold and salt trade, and its patronage made Timbuktu a centre of Islamic scholarship.","Weakened by civil war, it was shattered in 1591 by a small Moroccan army whose firearms routed a far larger Songhai force at Tondibi."],dyk:"The traveller Leo Africanus, visiting Timbuktu around 1510, reported that books were sold there at greater profit than any other merchandise.",ev:[["1464","Sunni Ali begins his reign and launches campaigns of conquest"],["1468","Sunni Ali takes Timbuktu from the Tuareg"],["c. 1473","Djenné submits to Songhai after a long siege"],["1493","Muhammad Ture defeats Sunni Baru and takes the title Askia"],["1496","Askia Muhammad sets out on his pilgrimage to Mecca"],["1528","Askia Muhammad is deposed by his son Askia Musa"],["1588","Civil war divides the Songhai Empire"],["1591","Judar Pasha's Moroccan army routs Askia Ishaq II at the Battle of Tondibi"]]},
  "Spanish Empire": {t:["Often called the first global empire, Spain ruled lands across Europe, the Americas, Africa and Asia from the 1490s.","American silver from mines like Potosí reshaped world money, and the Columbian Exchange transformed diets, populations and faiths.","Costly wars and bankruptcies eroded its power; the American colonies broke away by 1826 and the last major ones were lost in 1898."],dyk:"From 1565 to 1815 the Manila Galleon linked Acapulco and Manila, the first sustained direct trade link between the Americas and Asia.",ev:[["1492","Granada falls, ending the Reconquista, and Columbus sails west for Castile"],["1494","The Treaty of Tordesillas divides the world between Spain and Portugal"],["1519","Hernán Cortés begins the conquest of the Aztec Empire, completed in 1521"],["1532","Francisco Pizarro begins the conquest of the Inca Empire"],["1580","Philip II unites the crowns of Spain and Portugal"],["1588","The Spanish Armada sent against England is defeated and wrecked by storms"],["1648","The Peace of Westphalia confirms Dutch independence from Spain"],["1898","Defeat by the United States strips Spain of Cuba, Puerto Rico and the Philippines"]]},
  "Srivijaya Empire": {t:["Based at Palembang in Sumatra, Srivijaya was a sea power that ruled the Strait of Malacca from the 7th to the 13th century.","It grew rich by taxing China-India shipping and became a renowned centre of Buddhist learning, spreading Old Malay across the region.","Chola raids, Javanese rivals, direct Chinese shipping and the spread of Islam wore it down until Temasek and Malacca took its role."],dyk:"The Chinese pilgrim Yijing, who stopped there in 671, found over a thousand Buddhist monks and advised Chinese monks to study in Srivijaya before going to India.",ev:[["671","The Chinese pilgrim Yijing visits Srivijaya on his way to India"],["682","The Kedukan Bukit inscription records Sri Jayanasa's military expedition"],["c. 990","Srivijaya withstands an attack on Sumatra by Dharmawangsa of Medang"],["1016","The Medang court in Java is destroyed by the rebellion of the ruler of Wurawari"],["1025","Rajendra Chola I sacks Srivijaya and its ports and captures its ruler"],["c. 1068","A further Chola naval expedition under Virarajendra strikes the region"],["1275","Kertanagara of Singhasari launches the Pamalayu expedition against Malayu"]]},
  "Swedish Empire": {t:["In the 17th century a poor kingdom of some 2.5 million people made itself the dominant power of the Baltic.","Gustavus Adolphus's military reforms reshaped European warfare and his intervention changed the course of the Thirty Years War.","Charles XII's defeat by Russia at Poltava in 1709 broke Swedish power, and the Peace of Nystad in 1721 ended the empire."],dyk:"Stockholms Banco issued Europe's first banknotes in 1661, and its successor, the Sveriges Riksbank of 1668, is the oldest central bank still operating.",ev:[["1617","The Peace of Stolbovo gives Sweden Ingria and Kexholm from Russia"],["1630","Gustavus Adolphus intervenes in the Thirty Years War"],["1631","Swedish and Saxon forces rout Tilly's Catholic League army at Breitenfeld"],["1648","The Peace of Westphalia grants Sweden Western Pomerania, Bremen, Verden and Wismar"],["1658","Charles X Gustav marches across the frozen Belts and forces the Treaty of Roskilde on Denmark"],["1709","Peter the Great crushes Charles XII's army at Poltava"],["1718","Charles XII is killed at the siege of Fredriksten in Norway"],["1721","The Peace of Nystad cedes Estonia, Livonia and Ingria to Russia"]]},
  "Tang Dynasty": {t:["Founded in 618, the Tang Dynasty pushed Chinese power deep into Central Asia and made Chang'an one of the world's great cities.","Its law code, government model and Buddhist culture were adopted by Japan, Korea and Vietnam and shaped East Asia for centuries.","The An Lushan Rebellion left power with regional generals; the Huang Chao uprising finished it and a warlord deposed the last emperor in 907."],dyk:"The Diamond Sutra of 868, found at Dunhuang, is the oldest surviving dated printed book in the world.",ev:[["618","Li Yuan proclaims the Tang Dynasty after seizing Chang'an from the collapsing Sui"],["626","Li Shimin kills his brothers at the Xuanwu Gate and becomes Emperor Taizong"],["630","The Tang destroy the Eastern Turkic Khaganate; Taizong is hailed as Heavenly Khagan"],["690","Wu Zetian proclaims her own Zhou dynasty, interrupting Tang rule until 705"],["751","Abbasid forces defeat Gao Xianzhi's Tang army at the Battle of Talas"],["755","An Lushan rebels, capturing Luoyang and Chang'an and forcing Xuanzong to flee"],["881","Huang Chao's rebels sack Chang'an"],["907","Zhu Wen deposes the last Tang emperor and founds the Later Liang"]]},
  "Timurid Empire": {t:["Timur, a Barlas noble from Transoxiana, carved out an empire from Anatolia to the borders of China by conquest and calculated terror.","His heirs turned Samarkand and Herat into brilliant centres of painting, poetry and astronomy that shaped Safavid and Mughal culture.","Built on one man's authority, it split among feuding princes after 1405 and fell to the Uzbeks, but Babur carried its legacy to Mughal India."],dyk:"Ulugh Beg's Samarkand star catalogue of over a thousand stars was among the most accurate before the telescope, and was published at Oxford in 1665.",ev:[["1387","Timur's army raises towers of skulls from the population of Isfahan"],["1395","Timur defeats Tokhtamysh of the Golden Horde on the Terek"],["1398","Timur sacks Delhi, leaving the city devastated for decades"],["1402","Timur defeats and captures the Ottoman Sultan Bayezid I at Ankara"],["1405","Timur dies at Otrar while marching to invade Ming China"],["1449","Ulugh Beg is put to death at the instigation of his own son"],["1469","Abu Sa'id, last Timurid to reunite much of the realm, is killed fighting the Aq Qoyunlu"],["1507","Muhammad Shaybani Khan takes Herat, ending Timurid rule"]]},
  "Tokugawa Shogunate": {t:["After victory at Sekigahara, the Tokugawa shoguns ruled Japan from Edo from 1603 to 1868, keeping some 260 daimyo in check.","Two and a half centuries of peace fostered a commercial economy, a city of a million in Edo, and arts like kabuki and ukiyo-e.","Unable to resist Perry's 'Black Ships' or the rising domains of Satsuma and Choshu, the last shogun handed power back to the emperor in 1867."],dyk:"After the Shimabara Rebellion of 1637-1638, Japan under the Tokugawa saw no major warfare for more than two centuries.",ev:[["1600","Tokugawa Ieyasu defeats Ishida Mitsunari's western coalition at Sekigahara"],["1603","The imperial court appoints Ieyasu shogun"],["1615","The siege of Osaka Castle destroys the Toyotomi house"],["1635","Iemitsu formalises sankin-kotai, the alternate attendance of daimyo in Edo"],["1641","Dutch traders are confined to the artificial island of Dejima in Nagasaki"],["1853","Commodore Perry's 'Black Ships' enter Edo Bay demanding open ports"],["1867","Shogun Tokugawa Yoshinobu returns governing authority to Emperor Meiji"],["1868","Imperial rule is restored and the Boshin War begins at Toba-Fushimi"]]},
  "Umayyad Caliphate": {t:["The Umayyads turned the caliphate into a hereditary monarchy ruled from Damascus, from 661 to 750.","Their conquests reached from Spain to Sind and Central Asia, spreading Arabic and laying the ground for Islam across three continents.","Favouring Arabs over non-Arab converts bred revolt; the Abbasids overthrew them in 750, though a survivor founded a new Umayyad state in Spain."],dyk:"Abd al-Malik's gold dinar of 697 dropped Byzantine and Persian imagery for Arabic Quranic inscriptions, creating a distinctly Islamic coinage.",ev:[["661","Muawiyah secures the caliphate after Ali's assassination and rules from Damascus"],["680","Husayn ibn Ali is killed at Karbala, the defining martyrdom of Shia Islam"],["c. 691","Abd al-Malik completes the Dome of the Rock in Jerusalem"],["711","Tariq ibn Ziyad crosses into Spain and overthrows the Visigothic kingdom"],["717","The second Arab siege of Constantinople begins and fails the following year"],["732","Charles Martel checks Umayyad raids at the Battle of Tours"],["747","Abu Muslim proclaims the Abbasid Revolution in Khorasan"],["750","Marwan II is defeated at the Great Zab and killed, ending Umayyad rule in the east"]]},
  "Wadai Empire": {t:["Wadai was an Islamic sultanate in what is now eastern Chad, founded in the early 17th century after a revolt against the Tunjur.","Its caravan road to Benghazi made it a major trans-Saharan trading power, fed largely by slave raiding into the lands to the south.","Weakened by succession wars, it fell to the French, who took Abéché in 1909 and abolished the sultanate in 1912."],dyk:"The Anglo-French convention of 1899 assigned Wadai to France and Darfur to Britain, a division that still broadly underlies the Chad-Sudan border.",ev:[["c. 1611","Abd al-Karim ibn Jama overthrows the Tunjur and founds the Wadai sultanate at Wara"],["c. 1803","Sultan Sabun begins his reign and opens a caravan route through Kufra to Benghazi"],["c. 1850","Sultan Muhammad al-Sharif moves the capital from Wara to Abéché"],["1871","Sultan Ali's armies sack Massenya, capital of the rival sultanate of Bagirmi"],["1899","An Anglo-French convention places Wadai in the French sphere"],["1909","A French column captures Abéché and installs Adam Asil as a client sultan"],["1911","Sultan Dud Murra surrenders after years of resistance from the countryside"],["1912","France abolishes the Wadai sultanate"]]},
  "Xiongnu Empire": {t:["The first great steppe empire of eastern Eurasia, the Xiongnu confederation dominated Mongolia from about 209 BCE.","For decades it forced Han China to pay tribute in silk and princesses; its decimal army and court became the model for later steppe empires.","Han campaigns, natural disasters and rival chanyu split it in 48 CE; the Northern Xiongnu vanished as a power around 91 CE."],dyk:"In 200 BCE the Xiongnu trapped the Han founder, Emperor Gaozu, for seven days at Baideng; he escaped only after his envoys bribed the chanyu's consort.",ev:[["209 BCE","Modu seizes power from his father Touman and unites the Xiongnu"],["200 BCE","Modu surrounds Han Emperor Gaozu for seven days at the Battle of Baideng"],["198 BCE","The Han accept the heqin treaty of gifts and royal brides in exchange for peace"],["133 BCE","A failed Han ambush at Mayi ends the policy of appeasement"],["119 BCE","Wei Qing and Huo Qubing defeat the Xiongnu at the Battle of Mobei"],["51 BCE","Chanyu Huhanye travels to Chang'an and acknowledges Han overlordship"],["48","The confederation splits into Southern and Northern Xiongnu"],["89","The Northern Xiongnu suffer a crushing defeat by Han forces and their allies"]]},
  "Yuan Dynasty": {t:["Kublai Khan proclaimed the Yuan Dynasty in 1271, making China the centre of the Mongol world and ruling it from Dadu (Beijing).","It linked China to Persia and Europe across the Mongol network, and its rigid ethnic hierarchy put southern Chinese at the bottom.","Floods, epidemics, runaway paper-money inflation and the Red Turban Rebellion brought it down; the Ming took Dadu in 1368."],dyk:"Kublai's Tibetan preceptor Phagpa devised a new script in 1269 to write all the empire's languages; it appeared on seals and coins but never caught on.",ev:[["1260","Kublai's claim to be Great Khan sparks civil war with his brother Ariq Böke"],["1271","Kublai Khan adopts the dynastic name Da Yuan"],["1273","Xiangyang falls to Mongol counterweight trebuchets after a five-year siege"],["1274","The first Mongol invasion of Japan is wrecked by storms"],["1279","The last Song loyalist fleet is destroyed at Yamen, leaving the Yuan masters of all China"],["1344","The Yellow River bursts its dykes, devastating the North China Plain"],["1351","The Red Turban Rebellion breaks out across the Huai and Yangtze valleys"],["1368","Zhu Yuanzhang proclaims the Ming and Toghon Temür flees Dadu"]]},
  "Zand Empire": {t:["Karim Khan Zand restored order to most of Iran after Nader Shah's murder, ruling from Shiraz without ever taking the title of shah.","His mild rule revived trade and farming and left Shiraz its Vakil bazaar, mosque and bath, still among Iran's finest 18th-century buildings.","After his death in 1779 his relatives fought for the throne, and the Qajar Agha Mohammad Khan destroyed the dynasty by 1794."],dyk:"Karim Khan called himself Vakil al-Ruaya, Deputy of the People, rather than shah, and kept a Safavid prince as nominal sovereign.",ev:[["1747","Nader Shah's assassination leaves Iran in a power vacuum"],["c. 1750","Karim Khan Zand and Ali Mardan Khan install the puppet Shah Ismail III"],["1763","Karim Khan lets the British East India Company open a factory at Bushehr"],["1773","Karim Khan restores the tomb of the poet Hafez in Shiraz"],["1776","Sadeq Khan's forces capture Basra from the Ottomans after a long siege"],["1779","Karim Khan dies, opening fifteen years of Zand civil war"],["1791","Shiraz's governor betrays the city to the Qajars"],["1794","Agha Mohammad Khan takes Kerman and executes the last Zand ruler, Lotf Ali Khan"]]},
  "Teotihuacan": {t:["A planned city in the Valley of Mexico that grew to perhaps 100,000 people, among the largest in the world in the 3rd–6th centuries CE.","Its pyramids, obsidian, art and talud-tablero architecture influenced Mesoamerica as far as the Maya cities of Tikal and Copán.","No ruler is named in its art; around 550 its centre was burned, probably in a revolt, and the Aztecs later revered its ruins."],dyk:"In 2003 archaeologists found a sealed tunnel about 100 metres long beneath the Feathered Serpent Pyramid, from which they later recovered tens of thousands of offerings and traces of liquid mercury.",ev:[["c. 100 BCE","Teotihuacan begins to grow rapidly in the north-eastern Basin of Mexico"],["c. 1–150 CE","The Pyramid of the Sun is raised beside the Avenue of the Dead"],["c. 200–250 CE","The Feathered Serpent Pyramid is built, with some 200 sacrificial burials"],["c. 250 CE","The city covers some 20 km² with perhaps 100,000 inhabitants"],["378","Siyaj K’ak’ arrives at Tikal, and a new king linked to Teotihuacan takes power"],["426","K’inich Yax K’uk’ Mo’ founds the royal dynasty of Copán"],["c. 550","The civic centre is burned and the city’s power collapses"]]},
  "Inca Empire": {t:["Tawantinsuyu, the largest pre-Columbian state of the Americas, stretched some 4,000 km from southern Colombia to central Chile.","It ran on labour tribute, storehouses, a 40,000 km road network and khipu records, without money or alphabetic writing.","Smallpox and a civil war between Huáscar and Atahualpa left it open to Francisco Pizarro’s conquest in 1532–1533."],dyk:"Inca officials recorded census figures, tribute and stored goods on khipus, knotted cords whose knot types and positions encoded numbers in a base-ten system.",ev:[["c. 1438","Pachacuti defeats the Chanka and launches Inca imperial expansion"],["c. 1470","Túpac Inca Yupanqui conquers the Kingdom of Chimor"],["c. 1471","Túpac Inca Yupanqui succeeds Pachacuti as Sapa Inca"],["c. 1493","Huayna Capac becomes Sapa Inca and extends the empire northwards"],["c. 1527","Huayna Capac dies of an epidemic, probably smallpox"],["1532","Atahualpa defeats Huáscar, then is captured by Francisco Pizarro at Cajamarca"],["1533","Atahualpa is executed and the Spaniards enter Cusco"]]},
  "Iroquois Confederacy": {t:["A league of the Mohawk, Oneida, Onondaga, Cayuga and Seneca, joined by the Tuscarora around 1722, under the Great Law of Peace.","Fifty hereditary chiefs, chosen and removable by clan mothers, decided by consensus in a Grand Council at Onondaga.","Strongest Native power of the north-east for over a century, it was split by the American Revolution but its councils still meet."],dyk:"The Haudenosaunee issue their own passports, and their national lacrosse team has competed internationally under the confederacy’s flag, the Hiawatha Belt, in a sport they helped to create.",ev:[["c. 1450","Traditional founding date of the league under the Great Law of Peace (dates debated)"],["1649","Haudenosaunee war parties destroy the towns of the Huron Confederacy"],["1677","The Covenant Chain alliance is agreed with the English at Albany"],["1701","The Great Peace of Montreal ends decades of war with New France"],["c. 1722","The Tuscarora join, making the Five Nations the Six Nations"],["1777","The Grand Council covers its fire as the nations take sides in the American Revolution"],["1784","Joseph Brant leads loyalist Haudenosaunee to the Grand River in Ontario"]]},
  "New Spain": {t:["Spain’s richest viceroyalty, ruled from Mexico City over Mexico, Central America, the Caribbean and the Philippines.","Its silver, coined as the Spanish dollar and carried by the Manila galleons, linked Europe, the Americas and China.","Hidalgo’s revolt of 1810 began a long war, and the Plan of Iguala and Treaty of Córdoba ended Spanish rule in 1821."],dyk:"The Manila galleons sailed between Acapulco and Manila for 250 years, from 1565 to 1815, carrying Mexican silver to Asia and returning with Chinese silk and porcelain.",ev:[["1521","Tenochtitlan falls to Hernán Cortés and his indigenous allies"],["1535","Antonio de Mendoza becomes the first viceroy of New Spain"],["1546","Silver is discovered at Zacatecas"],["1565","The Manila galleon route links Acapulco with the Philippines"],["1767","The Jesuits are expelled during the Bourbon reforms"],["1810","Miguel Hidalgo launches the war of independence at Dolores"],["1821","The Plan of Iguala and the Treaty of Córdoba end Spanish rule"]]},
  "New France": {t:["France’s North American empire, reaching from the St Lawrence through the Great Lakes and the Mississippi to the Gulf of Mexico.","It rested on the fur trade and Native alliances, but had only about 70,000 settlers in Canada by 1760.","Britain conquered it in the Seven Years War, yet its language, law and Catholicism survive in Quebec today."],dyk:"Between 1663 and 1673 about 800 young women, the filles du roi, were sent from France at royal expense to marry settlers, and millions of French Canadians descend from them.",ev:[["1534","Jacques Cartier claims the Gaspé Peninsula for France"],["1608","Samuel de Champlain founds Quebec"],["1642","Ville-Marie, later Montreal, is founded"],["1663","Louis XIV makes New France a royal province"],["1682","La Salle reaches the mouth of the Mississippi and claims Louisiana"],["1701","The Great Peace of Montreal ends war with the Iroquois Confederacy"],["1759","Quebec falls after the Battle of the Plains of Abraham"],["1763","The Treaty of Paris cedes Canada to Britain"]]},
  "Viceroyalty of Peru": {t:["Spain’s viceroyalty for South America, ruled from Lima, which at first covered nearly all of Spanish South America.","Silver from Potosí, mined with forced mita labour, financed the Spanish crown and flowed to Europe and China.","Bourbon reforms cut its territory in the eighteenth century, and the Battle of Ayacucho in 1824 ended Spanish rule."],dyk:"The first book printed in South America was a catechism in Spanish, Quechua and Aymara, published in Lima in 1584.",ev:[["1542","The New Laws of Charles V create the Viceroyalty of Peru"],["1545","Silver is discovered at the Cerro Rico of Potosí"],["1551","The University of San Marcos is founded in Lima"],["1572","Túpac Amaru, last ruler of the Neo-Inca State, is executed in Cuzco"],["1746","An earthquake and tsunami destroy much of Lima and the port of Callao"],["1776","Upper Peru and Potosí pass to the new Viceroyalty of the Río de la Plata"],["1780","The rebellion of Túpac Amaru II begins in the southern Andes"],["1824","Sucre defeats the royalists at the Battle of Ayacucho"]]},
  "Suriname": {t:["A Dutch plantation colony on the Guiana coast, taken from the English in 1667 and run for a century by the Society of Suriname.","Enslaved Africans worked its sugar and coffee estates; runaways formed maroon nations that won peace treaties in the 1760s.","Indentured Asian migrants made it highly diverse; it became independent in 1975 and has been a democracy since 1991."],dyk:"Under the Treaty of Breda of 1667 the Dutch kept Suriname while the English kept New Amsterdam, which they had renamed New York.",ev:[["1667","A Zeeland fleet captures the English colony, confirmed as Dutch by the Treaty of Breda"],["1683","The Society of Suriname takes over the colony"],["1760","The colony makes peace with the Ndyuka maroons"],["1863","Slavery is abolished on 1 July, now commemorated as Keti Koti"],["1873","The first indentured labourers from British India arrive"],["1954","Suriname becomes an autonomous country within the Kingdom of the Netherlands"],["1975","Suriname becomes independent on 25 November"],["1980","Sergeants led by Desi Bouterse seize power in a coup"]]},
  "United States": {t:["Founded by thirteen British colonies in 1776, it was the first modern republic built on a written national constitution.","It expanded across North America by purchase, war and the dispossession of Native nations; slavery ended only after civil war.","Victory in the two world wars made it a superpower, and after the fall of the Soviet Union in 1991 it was the only one."],dyk:"The Constitution of the United States, in force since 1789, is the oldest written national constitution still in use.",ev:[["1776","The Declaration of Independence is adopted on 4 July"],["1783","The Treaty of Paris recognises American independence"],["1789","The Constitution takes effect and George Washington becomes president"],["1803","The Louisiana Purchase roughly doubles the country’s area"],["1861","The Civil War begins after eleven Southern states secede"],["1865","Union victory and the Thirteenth Amendment end slavery"],["1945","The United States emerges from the Second World War as a superpower"],["1969","Apollo 11 lands the first astronauts on the Moon"]]},
  "Republic of Haiti (1806-1849)": {t:["A republic founded in 1806 in southern and western Haiti, ruled from Port-au-Prince by Alexandre Pétion and Jean-Pierre Boyer.","Pétion broke up plantations into peasant smallholdings and armed Simón Bolívar on condition that he free the slaves.","Boyer reunited Haiti, ruled all of Hispaniola from 1822 to 1844 and accepted a crushing French indemnity in 1825."],dyk:"When Pétion armed Simón Bolívar in 1816, the payment he asked was that Bolívar abolish slavery in the lands he freed from Spain.",ev:[["1806","Jacques I is assassinated and a republican constitution is adopted"],["1807","Alexandre Pétion is elected president as Haiti splits between republic and north"],["1816","Pétion aids Simón Bolívar and becomes president for life"],["1818","Jean-Pierre Boyer succeeds Pétion"],["1820","Boyer reunites Haiti after Henri Christophe’s suicide"],["1822","Haiti occupies Santo Domingo, ruling all of Hispaniola"],["1825","France recognises Haiti in return for an indemnity of 150 million francs"],["1844","The Dominican Republic proclaims independence"]]},
  "Republic of Chile": {t:["Independent since 1818, after the Army of the Andes defeated the royalists at Chacabuco and Maipú.","The Constitution of 1833 gave it rare stability, and victory in the War of the Pacific made it a regional power.","Salvador Allende was overthrown in 1973; Pinochet’s dictatorship lasted until the return of democracy in 1990."],dyk:"Andrés Bello, a Venezuelan scholar who settled in Chile, wrote its Civil Code of 1855, which was later adopted by Ecuador and Colombia.",ev:[["1818","Independence is proclaimed and secured at the Battle of Maipú"],["1833","A new constitution creates a strong presidential state"],["1839","Victory at Yungay ends the Peru–Bolivian Confederation"],["1879","The War of the Pacific begins against Peru and Bolivia"],["1891","Congress defeats President Balmaceda in a civil war"],["1973","Augusto Pinochet’s coup overthrows Salvador Allende on 11 September"],["1988","Voters reject Pinochet in a plebiscite"],["1990","Democracy returns under President Patricio Aylwin"]]},
  "Gran Colombia": {t:["A republic of 1819–1831 joining Venezuela, New Granada, Quito and Panama, proclaimed by Simón Bolívar’s Congress of Angostura.","Its armies, led by Bolívar and Sucre, ended Spanish rule in South America at Junín and Ayacucho in 1824.","Regional rivalries, debt and disputes over Bolívar’s power broke it into Colombia, Venezuela and Ecuador by 1831."],dyk:"Its official name was simply the Republic of Colombia; historians later coined ‘Gran Colombia’ to distinguish it from the present-day country.",ev:[["1819","Congress of Angostura proclaims the Republic of Colombia after the Battle of Boyacá"],["1821","Congress of Cúcuta adopts a constitution; the Battle of Carabobo frees Venezuela"],["1822","Sucre wins the Battle of Pichincha and Quito joins the republic"],["1824","Colombian armies end Spanish rule in South America at Junín and Ayacucho"],["1826","José Antonio Páez leads the Cosiata revolt in Venezuela"],["1828","Bolívar assumes dictatorial powers and survives an assassination attempt"],["1830","Venezuela and Ecuador secede; Bolívar dies near Santa Marta"],["1831","The remaining provinces are reorganised as New Granada"]]},
  "Republic of Peru": {t:["Independent from 1821, Peru grew from the core of the Inca Empire and Spain’s Viceroyalty of Peru, with Lima as its capital.","Guano wealth funded railways and reforms, but defeat by Chile in the War of the Pacific cost it Tarapacá and Arica.","After military rule, hyperinflation and the Shining Path insurgency, it became a fast-growing mining economy with fragile politics."],dyk:"From the 1840s to the 1870s Peru’s main export was guano, seabird droppings dug from offshore islands and shipped to Europe as fertiliser.",ev:[["1821","José de San Martín proclaims Peruvian independence in Lima"],["1824","Sucre defeats the last royalist field army at the Battle of Ayacucho"],["1854","Ramón Castilla abolishes slavery and the Indian tribute"],["1879","Peru enters the War of the Pacific against Chile"],["1883","The Treaty of Ancón cedes Tarapacá to Chile"],["1968","Juan Velasco Alvarado seizes power and begins radical reforms"],["1992","Alberto Fujimori closes Congress; Abimael Guzmán is captured"],["2022","Pedro Castillo is removed after trying to dissolve Congress"]]},
  "Federal Republic of Central America": {t:["A federation of Guatemala, El Salvador, Honduras, Nicaragua and Costa Rica that broke away from Mexico in 1823.","Liberal reforms under Francisco Morazán angered the Church and rural communities, while the federal government lacked money and an army.","Rafael Carrera’s revolt in Guatemala and the secession of the states destroyed the union by 1841, though the dream of unity lived on."],dyk:"The Central American federation abolished slavery in 1824, more than forty years before the United States did so.",ev:[["1821","Guatemala City signs an act of independence from Spain"],["1822","The Central American provinces are annexed to the First Mexican Empire"],["1823","A congress declares the United Provinces of Central America independent"],["1824","A federal constitution is adopted and slavery is abolished"],["1829","Francisco Morazán takes Guatemala City, ending the civil war"],["1838","Rafael Carrera’s rebels enter Guatemala City; three states secede"],["1840","Carrera defeats Morazán at Guatemala City"],["1842","Morazán is executed in San José, Costa Rica"]]},
  "Republic of Bolivia": {t:["Formed from Upper Peru in 1825 and named after Simón Bolívar, with Sucre as constitutional capital and La Paz as seat of government.","Lost wars cost it the Pacific coast to Chile, Acre to Brazil and most of the Chaco to Paraguay.","Its 1952 revolution and the election of Evo Morales made it a landmark of Latin American social and indigenous politics."],dyk:"Landlocked since the War of the Pacific, Bolivia still maintains a navy, which patrols Lake Titicaca and the country’s rivers.",ev:[["1825","Upper Peru declares independence at Chuquisaca as the Republic of Bolívar"],["1836","Andrés de Santa Cruz forms the Peru-Bolivian Confederation"],["1879","Chile occupies Antofagasta, beginning the War of the Pacific"],["1903","The Treaty of Petrópolis cedes Acre to Brazil"],["1932","The Chaco War with Paraguay begins"],["1952","The National Revolution brings universal suffrage and nationalises the mines"],["2006","Evo Morales becomes Bolivia’s first indigenous president"],["2009","A new constitution creates the Plurinational State of Bolivia"]]},
  "Venezuela": {t:["Venezuela left Gran Colombia in 1830 under José Antonio Páez and for a century was ruled mainly by caudillos.","Oil found in the 1910s and 1920s made it a leading exporter, a founder of OPEC and a stable democracy after 1958.","Under Hugo Chávez and Nicolás Maduro it became the Bolivarian Republic, then suffered economic collapse and mass emigration."],dyk:"Venezuela has the world’s largest proven oil reserves, estimated at around 300 billion barrels, mostly heavy crude in the Orinoco Belt.",ev:[["1830","Venezuela secedes from Gran Colombia and adopts its own constitution"],["1854","Slavery is abolished under President José Gregorio Monagas"],["1863","The Treaty of Coche ends the Federal War"],["1922","The Barroso II blowout reveals the oil riches of Lake Maracaibo"],["1958","Dictator Marcos Pérez Jiménez is overthrown; the Punto Fijo pact follows"],["1960","Venezuela co-founds OPEC at Baghdad"],["1976","The oil industry is nationalised and PDVSA is created"],["1999","A new constitution creates the Bolivarian Republic of Venezuela"]]},
  "Republic of Ecuador": {t:["An Andean republic formed in 1830 when Gran Colombia’s Southern District, centred on Quito, Guayaquil and Cuenca, became independent.","Politics long pitted Catholic, conservative Quito against liberal, commercial Guayaquil, from García Moreno to Eloy Alfaro.","Cacao, bananas and then Amazon oil drove its economy; it lost most of its Amazon claim to Peru in 1942 and adopted the dollar in 2000."],dyk:"Ecuador’s 2008 constitution was the first in the world to give nature itself enforceable rights, allowing any person to go to court on behalf of a river or forest.",ev:[["1830","A Quito assembly declares the Southern District of Gran Colombia independent"],["1832","Ecuador annexes the Galápagos Islands"],["1875","Gabriel García Moreno is assassinated in Quito"],["1895","The Liberal Revolution brings Eloy Alfaro to power"],["1908","The Guayaquil–Quito railway reaches Quito"],["1942","The Rio Protocol assigns most of the disputed Amazon to Peru"],["1972","Oil exports begin through the Trans-Ecuadorian pipeline"],["2000","Ecuador replaces the sucre with the US dollar"]]},
  "Republic of Nicaragua": {t:["The first state to leave the Central American federation, in 1838, long torn between liberal León and conservative Granada.","Its possible canal route drew British, filibuster and American interventions, from William Walker in 1856 to US Marines in 1912–1933.","The Somoza dynasty ruled from 1936 to 1979 until the Sandinista revolution; Daniel Ortega has governed again since 2007."],dyk:"In 1902 opponents of a Nicaraguan canal sent US senators Nicaraguan postage stamps showing Momotombo volcano in eruption; shortly afterwards the Senate chose Panama.",ev:[["1838","Nicaragua becomes the first state to leave the Federal Republic of Central America"],["1852","Managua is chosen as a compromise capital between León and Granada"],["1856","The American filibuster William Walker makes himself president"],["1894","José Santos Zelaya incorporates the Mosquito Reserve"],["1912","US Marines land, beginning an occupation that lasts until 1933"],["1934","Augusto César Sandino is murdered on the orders of Anastasio Somoza García"],["1979","The Sandinista revolution overthrows Anastasio Somoza Debayle"],["1990","Violeta Barrios de Chamorro defeats Daniel Ortega, ending the Contra war"]]},
  "Republic of Honduras": {t:["Honduras left the Central American federation in 1838; Marco Aurelio Soto made Tegucigalpa its permanent capital in 1880.","American fruit companies dominated its north coast from the 1900s, and O. Henry coined ‘banana republic’ with Honduras in mind.","Dictatorship, military rule, the 1969 Football War, Contra bases and the 2009 coup have marked its modern history."],dyk:"In 1911 the banana magnate Samuel Zemurray financed an invasion of Honduras that restored the former president Manuel Bonilla, who rewarded him with land concessions.",ev:[["1838","Honduras declares its separation from the Federal Republic of Central America"],["1880","Marco Aurelio Soto moves the capital from Comayagua to Tegucigalpa"],["1911","Manuel Bonilla invades with mercenaries financed by Samuel Zemurray"],["1933","Tiburcio Carías Andino begins sixteen years of rule"],["1954","The great banana strike wins workers the right to organise"],["1969","Honduras and El Salvador fight the Football War"],["1998","Hurricane Mitch devastates the country"],["2009","The army removes President Manuel Zelaya in a coup"]]},
  "Republic of El Salvador": {t:["The smallest country of mainland Central America, independent under its 1841 constitution after the federation collapsed.","Coffee built a powerful landowning elite; in 1932 the army’s Matanza crushed a peasant and indigenous revolt in the west.","Civil war in 1980–1992 killed about 75,000; peace, dollarisation and Nayib Bukele’s anti-gang crackdown followed."],dyk:"El Salvador is the only Central American country with no Caribbean coastline: its whole shore, about 300 kilometres long, faces the Pacific Ocean.",ev:[["1841","A constitution declares El Salvador a sovereign and independent state"],["1863","Rafael Carrera takes San Salvador and overthrows Gerardo Barrios"],["1881","The abolition of communal lands opens the way for coffee estates"],["1932","The army crushes a peasant uprising in La Matanza"],["1969","El Salvador and Honduras fight the Football War"],["1980","Archbishop Óscar Romero is assassinated while saying mass"],["1992","The Chapultepec Peace Accords end the civil war"],["2001","El Salvador adopts the US dollar"]]},
  "Republic of Guatemala": {t:["Proclaimed a republic by the conservative caudillo Rafael Carrera in 1847, it is the most populous country of Central America.","Liberal dictators built a coffee economy on forced Maya labour and gave the United Fruit Company great privileges.","A CIA-backed coup in 1954 ended a decade of reform; civil war in 1960–1996 killed about 200,000 people, most of them Maya."],dyk:"A young Argentine doctor, Ernesto Guevara, was living in Guatemala City when the CIA-backed coup toppled Árbenz in 1954, an experience that radicalised the future ‘Che’.",ev:[["1847","Rafael Carrera proclaims the Republic of Guatemala"],["1871","The Liberal Revolution overthrows the conservative regime"],["1885","Justo Rufino Barrios is killed at Chalchuapa trying to reunite Central America"],["1944","The October Revolution opens a decade of democratic reform"],["1952","Jacobo Árbenz enacts the agrarian reform of Decree 900"],["1954","A CIA-backed invasion forces Árbenz to resign"],["1982","Efraín Ríos Montt intensifies the scorched-earth campaign in the highlands"],["1996","Peace accords end thirty-six years of internal armed conflict"]]},
  "Argentine Republic": {t:["Reunited in 1861 after Bartolomé Mitre’s victory at Pavón, under the federal Constitution of 1853 as amended in 1860.","Mass European immigration and exports of beef and grain made it one of the world’s richest countries by 1914.","From 1930 coups, Peronism and economic crises alternated, until democracy returned in 1983 after the Falklands War."],dyk:"In the national census of 1914 about 30 per cent of Argentina’s population had been born abroad, twice the share in the United States at the time.",ev:[["1861","Bartolomé Mitre defeats the Confederation at Pavón, reuniting Buenos Aires and the provinces"],["1865","Argentina joins Brazil and Uruguay in the war against Paraguay"],["1879","Julio Argentino Roca leads the Conquest of the Desert"],["1912","The Sáenz Peña Law introduces secret and compulsory male suffrage"],["1930","General José Félix Uriburu overthrows Hipólito Yrigoyen in the first military coup"],["1946","Juan Perón is elected president"],["1982","Argentina loses the Falklands War to Britain"],["2001","Economic collapse ends in riots and a sovereign default"]]},
  "Mexico": {t:["The republic was restored in 1867 when Benito Juárez defeated the French-backed empire of Maximilian of Habsburg.","The Revolution of 1910–1920 produced the Constitution of 1917, land reform and a ruling party that held power until 2000.","Since NAFTA in 1994 and the democratic transition of 2000, Mexico has become a large industrial economy tied to the United States."],dyk:"The ruling party founded in 1929 changed its name twice, becoming the PRI in 1946, and won every presidential election for 71 years until Vicente Fox’s victory in 2000.",ev:[["1867","Maximilian is executed at Querétaro and Benito Juárez restores the republic"],["1876","Porfirio Díaz seizes power under the Plan of Tuxtepec"],["1910","Francisco I. Madero’s call to revolt begins the Mexican Revolution"],["1917","The Constitution of 1917 is promulgated at Querétaro"],["1929","Plutarco Elías Calles founds the National Revolutionary Party"],["1938","Lázaro Cárdenas expropriates foreign oil companies"],["1994","NAFTA comes into force and the Zapatistas rise in Chiapas"],["2000","Vicente Fox’s election ends seven decades of PRI rule"]]},
  "Canada": {t:["Formed on 1 July 1867 by the union of British colonies, with John A. Macdonald as its first prime minister.","It grew by purchase and union into the world’s second-largest country, tied together by the Canadian Pacific Railway.","It won full independence gradually, through the Statute of Westminster of 1931 and the Constitution Act, 1982."],dyk:"Ottawa was chosen as capital of the Province of Canada by Queen Victoria in 1857, partly as a compromise between the rival cities of Toronto, Kingston, Montreal and Quebec.",ev:[["1864","The Charlottetown and Quebec conferences agree the terms of Confederation"],["1867","The British North America Act creates the Dominion of Canada on 1 July"],["1870","Canada acquires Rupert’s Land and creates the province of Manitoba"],["1885","The Canadian Pacific Railway is completed and Louis Riel is executed"],["1917","The Canadian Corps captures Vimy Ridge"],["1931","The Statute of Westminster confirms Canada’s legislative independence"],["1949","Newfoundland joins Canada as the tenth province"],["1982","The Constitution Act patriates the constitution and adds the Charter of Rights and Freedoms"]]},
  "Commonwealth of Australia": {t:["Six British colonies federated by popular referendum on 1 January 1901, with Edmund Barton as first prime minister.","Its constitution blends Westminster responsible government with an American-style Senate, federalism and a High Court.","A British dominion became an independent, multicultural nation by gradual steps, ending in the Australia Act of 1986."],dyk:"The plan for Canberra came from an international competition won in 1912 by the American architect Walter Burley Griffin, with drawings by his wife and partner Marion Mahony Griffin.",ev:[["1901","Six colonies federate as the Commonwealth of Australia on 1 January"],["1902","Women gain the right to vote and stand in federal elections"],["1915","Australian and New Zealand troops land at Gallipoli on 25 April"],["1942","Singapore falls and Japanese aircraft bomb Darwin"],["1951","The ANZUS Treaty allies Australia with the United States"],["1967","A referendum allows Aboriginal people to be counted in the census"],["1986","The Australia Act ends the remaining legal links with Britain"],["1992","The High Court’s Mabo decision recognises native title"]]},
  "Republic of Panama": {t:["Panama seceded from Colombia in 1903 with American backing so that the United States could build a canal across the isthmus.","The United States controlled the Canal Zone for most of the century, and military rulers governed Panama from 1968 to 1989.","Under the Torrijos–Carter Treaties Panama took full control of the canal on 31 December 1999."],dyk:"The 1903 treaty granting the United States the Canal Zone was signed for Panama by a Frenchman, Philippe Bunau-Varilla, before the Panamanian delegation had reached Washington.",ev:[["1903","Panama declares independence from Colombia and signs the Hay–Bunau-Varilla Treaty"],["1914","The Panama Canal opens on 15 August"],["1964","Flag riots in the Canal Zone leave more than 20 Panamanians dead"],["1968","The National Guard overthrows Arnulfo Arias, beginning military rule"],["1977","Omar Torrijos and Jimmy Carter sign the canal treaties"],["1989","The United States invades and removes Manuel Noriega"],["1999","Panama takes full control of the canal on 31 December"],["2016","The expanded canal with larger locks opens"]]},
  "New Zealand": {t:["A Pacific island democracy that gained full legislative independence in 1947 while keeping the British monarch as head of state.","It broke with the United States over nuclear weapons in 1985–1987 and made its nuclear-free status law.","The Waitangi Tribunal and Treaty settlements since 1975 have reshaped relations between the Crown and Māori."],dyk:"New Zealand adopted the Statute of Westminster only in 1947, sixteen years after Britain passed it, and created its own citizenship from 1 January 1949.",ev:[["1947","Parliament adopts the Statute of Westminster, completing legislative independence"],["1951","ANZUS Treaty signed with Australia and the United States; Legislative Council abolished"],["1973","Britain joins the EEC, ending New Zealand\u0027s secure British market"],["1975","Treaty of Waitangi Act creates the Waitangi Tribunal"],["1985","French agents sink the Rainbow Warrior in Auckland harbour"],["1987","Nuclear Free Zone Act passed; te reo Māori becomes an official language"],["1996","First election under mixed-member proportional representation"],["2019","Christchurch mosque shootings; most semi-automatic weapons banned"]]},
  "Shang dynasty": {t:["The first Chinese dynasty known from its own writing, ruling the middle Yellow River plain from c. 1600 to 1046 BCE.","Its kings divined with inscribed oracle bones, the oldest substantial body of Chinese writing.","Its bronze ritual vessels, chariots and royal tombs at Anyang make it one of the great Bronze Age civilisations."],dyk:"Before scholars recognised the writing on them around 1899, Shang oracle bones were ground up and sold by apothecaries as \u0027dragon bones\u0027 for medicine.",ev:[["c. 1600 BCE","Tang of Shang overthrows Jie of the Xia, according to tradition"],["c. 1600–1400 BCE","The walled city at Zhengzhou flourishes in the Erligang period"],["c. 1300 BCE","Pan Geng moves the capital to Yin near Anyang"],["c. 1250 BCE","Wu Ding begins his long reign; the earliest oracle-bone inscriptions"],["c. 1200 BCE","Chariots appear at Anyang; Fu Hao is buried in her tomb"],["1046 BCE","King Wu of Zhou defeats Di Xin at the Battle of Muye"]]},
  "State of Qi": {t:["A great eastern state of ancient China, founded on the Shandong peninsula by Jiang Ziya after the Zhou conquest.","Duke Huan and his minister Guan Zhong made Qi the first hegemon of the Zhou states in the 7th century BCE.","Its capital Linzi and the Jixia Academy made Qi a centre of wealth and philosophy until it surrendered to Qin in 221 BCE."],dyk:"Qi\u0027s later ruling family, the Tian, descended from a prince of the State of Chen who had fled to Qi as a refugee in 672 BCE.",ev:[["c. 1046 BCE","Jiang Ziya receives Qi as a fief after the Zhou conquest"],["685 BCE","Duke Huan takes the throne and appoints Guan Zhong as minister"],["651 BCE","Duke Huan presides over the covenant of Kuiqiu as hegemon"],["386 BCE","The Zhou king recognises Tian He as ruler of Qi"],["342 BCE","Sun Bin\u0027s strategy defeats Wei at the Battle of Maling"],["284 BCE","Yue Yi\u0027s coalition army sacks Linzi"],["279 BCE","Tian Dan breaks the siege of Jimo and restores Qi"],["221 BCE","King Jian surrenders to Qin, completing the Qin unification"]]},
  "Western Zhou": {t:["The dynasty that overthrew the Shang in 1046 BCE and ruled northern China from Haojing near modern Xi\u0027an.","It proclaimed the Mandate of Heaven: Heaven grants rule to the virtuous and withdraws it from the wicked.","It governed through regional states held by royal kinsmen, which later grew into the rival powers of the Warring States."],dyk:"The He zun, a bronze vessel cast under King Cheng, contains the earliest known use of zhongguo, \u0027the central state\u0027, later the Chinese name for China.",ev:[["1046 BCE","King Wu defeats the Shang at the Battle of Muye"],["c. 1042–1039 BCE","The Duke of Zhou crushes the Rebellion of the Three Guards"],["c. 957 BCE","King Zhao dies on a disastrous southern campaign"],["841 BCE","King Li is driven out and the Gonghe regency begins"],["827 BCE","King Xuan begins a revival against the Xianyun and the Huaiyi"],["771 BCE","The Quanrong and the Marquis of Shen sack Haojing and kill King You"]]},
  "State of Chu": {t:["The great southern kingdom of ancient China, based on the middle Yangtze and the Han River.","Its rulers called themselves kings from 704 BCE and absorbed dozens of states, organising many as counties.","Its distinctive culture produced the Songs of Chu, and Chu rebels overthrew the Qin dynasty that had conquered it."],dyk:"The oldest known manuscript of parts of the Daodejing was found in a Chu tomb at Guodian, written on bamboo slips around 300 BCE.",ev:[["704 BCE","Xiong Tong proclaims himself king as King Wu of Chu"],["597 BCE","King Zhuang defeats Jin at the Battle of Bi"],["506 BCE","The State of Wu defeats Chu at Boju and occupies Ying"],["381 BCE","Nobles kill the reformer Wu Qi after the death of King Dao"],["278 BCE","Bai Qi of Qin captures Ying; the capital moves to Chen"],["241 BCE","Chu moves its capital to Shouchun"],["223 BCE","The Qin general Wang Jian captures King Fuchu and annexes Chu"]]},
  "State of Qin": {t:["A western frontier fief of the Zhou kings that took over the old Zhou heartland in the Wei River valley.","Shang Yang\u0027s reforms from 356 BCE built a state of registered farmers, ranks earned in war and appointed officials.","King Zheng conquered the six rival states between 230 and 221 BCE and became China\u0027s First Emperor."],dyk:"The Shiji records that 177 people followed Duke Mu of Qin into death in 621 BCE; a poem in the Book of Songs, \u0027Yellow Bird\u0027, laments three brothers among them.",ev:[["770 BCE","Duke Xiang escorts King Ping of Zhou east and is raised to full ducal rank"],["645 BCE","Duke Mu defeats Jin at Han and captures Duke Hui of Jin"],["356 BCE","Shang Yang begins his reforms under Duke Xiao"],["350 BCE","The capital moves to Xianyang"],["316 BCE","Qin conquers Ba and Shu in the Sichuan basin"],["260 BCE","Bai Qi destroys the army of Zhao at Changping"],["230–221 BCE","King Zheng conquers Han, Zhao, Wei, Chu, Yan and Qi"],["221 BCE","Zheng takes the title of First Emperor"]]},
  "Saka": {t:["The Saka were the eastern Scythians, Iranian-speaking horse nomads spread from the Aral Sea to the Altai and the Tarim Basin.","They formed many tribes rather than one state, fighting and serving Persia and resisting Alexander the Great.","Driven south by the Yuezhi in the 2nd century BCE, they founded Indo-Scythian kingdoms in Iran and India."],dyk:"The Pazyryk tombs in the Altai, linked to the wider Saka-Scythian world, filled with ice soon after burial and so preserved the oldest known knotted pile carpet.",ev:[["530 BCE","Cyrus the Great dies fighting the Massagetae, according to Herodotus"],["c. 519 BCE","Darius I captures the pointed-cap Saka chief Skunkha"],["490 BCE","Saka troops fight in the Persian centre at the Battle of Marathon"],["329 BCE","Alexander the Great defeats a Saka force at the Jaxartes"],["c. 160 BCE","The Yuezhi drive the Saka from the Ili valley and Zhetysu"],["c. 127 BCE","Saka warriors kill the Parthian king Phraates II"],["c. 100 BCE","Mithridates II of Parthia subdues the Saka, many of whom settle in Sakastan"]]},
  "Yuezhi": {t:["A nomadic people of the Gansu corridor, strong enough in the 3rd century BCE to hold the Xiongnu prince Modu hostage.","Defeated by the Xiongnu, they migrated west to the Ili valley and then took Bactria, probably in the 130s BCE.","Zhang Qian\u0027s mission to them opened Han China to the West, and their Guishuang chiefs founded the Kushan Empire."],dyk:"The Xiongnu turned the skull of a defeated Yuezhi king into a drinking cup; according to the Han shu, Han envoys later drank from it when swearing a blood oath with a Xiongnu chanyu.",ev:[["209 BCE","Modu, once a hostage of the Yuezhi, seizes power among the Xiongnu"],["c. 176 BCE","The Xiongnu defeat the Yuezhi in the Gansu corridor"],["c. 160s BCE","The Greater Yuezhi move west and drive the Saka from the Ili valley"],["c. 130s BCE","The Wusun expel the Yuezhi, who move south and take Bactria"],["c. 128 BCE","The Han envoy Zhang Qian reaches the Yuezhi court"],["c. 30 CE","Kujula Kadphises unites the five xihou and founds the Kushan Empire"]]},
  "Xianbei": {t:["Descendants of the Donghu, the Xianbei replaced the Xiongnu as masters of the Mongolian steppe after 91 CE.","Tanshihuai united them around 156 CE and destroyed a major Han expedition into the steppe in 177 CE.","Their clans, above all the Tuoba of the Northern Wei, went on to rule much of northern China."],dyk:"According to the Hou Han shu, Tanshihuai\u0027s mother conceived him after a hailstone fell into her mouth; her husband, away at war for three years, at first refused to raise the child.",ev:[["c. 206 BCE","The Xiongnu destroy the Donghu; survivors become the Wuhuan and Xianbei"],["87 CE","Xianbei warriors kill the Northern Xiongnu chanyu Youliu"],["c. 91 CE","The Xianbei move into Mongolia and absorb over 100,000 Xiongnu tents"],["c. 156","Tanshihuai unites the Xianbei tribes"],["177","Tanshihuai routs a three-pronged Han expedition into the steppe"],["c. 181","Tanshihuai dies and his confederation breaks up"],["231","Kebineng marches to Beidi in support of Zhuge Liang"],["235","Kebineng is assassinated on the orders of Wang Xiong of Cao Wei"]]},
  "Silla": {t:["Silla grew from Saro, a chiefdom at Gyeongju traditionally founded in 57 BCE, into one of Korea\u0027s Three Kingdoms.","Allied with Tang China, it destroyed Baekje in 660 and Goguryeo in 668, then expelled Tang forces by 676.","Its bone-rank aristocracy presided over a Buddhist golden age that produced Bulguksa and the Seokguram grotto."],dyk:"King Munmu, who completed Silla\u0027s unification, is said to have asked for burial at sea so that he could become a dragon guarding Korea; a rock islet off the coast near Gyeongju is held to be his tomb.",ev:[["57 BCE","Traditional founding of Saro by Bak Hyeokgeose"],["527","King Beopheung recognises Buddhism after the martyrdom of Ichadon"],["553","King Jinheung seizes the Han River valley from Baekje"],["562","Silla conquers Daegaya, the last Gaya state"],["660","Silla and Tang destroy Baekje after the Battle of Hwangsanbeol"],["668","Silla and Tang take Pyongyang and destroy Goguryeo"],["676","Victory at Gibeolpo ends the Silla–Tang War"],["935","King Gyeongsun surrenders Silla to Goryeo"]]},
  "Goguryeo": {t:["Goguryeo grew from a clan federation on the Yalu into the largest of Korea\u0027s Three Kingdoms, ruling Manchuria and the northern peninsula.","It took the Chinese commandery of Lelang in 313 and adopted Buddhism, a Confucian academy and a law code under King Sosurim.","Its fortresses held off Sui and Tang invasions for seventy years before a Tang and Silla alliance took Pyongyang in 668."],dyk:"Goguryeo itself was often called Goryeo from the 5th century, and through the later kingdom of Goryeo that name became the English word Korea.",ev:[["37 BCE","Traditional founding of Goguryeo by Jumong at Jolbon"],["313","Goguryeo captures the Lelang commandery, ending Chinese rule around Pyongyang"],["372","Buddhism is received and the Taehak academy founded under King Sosurim"],["414","King Jangsu erects the stele of Gwanggaeto the Great at Ji\u0027an"],["427","The capital moves from Gungnae to Pyongyang"],["475","Jangsu takes the Baekje capital Hanseong"],["612","Eulji Mundeok routs a Sui army at the Salsu River"],["668","Tang and Silla forces take Pyongyang; the kingdom ends"]]},
  "Baekje": {t:["Baekje grew from a Mahan statelet on the Han River into a kingdom of south-western Korea, ruled from Hanseong, Ungjin and Sabi.","Its court was celebrated for refined Buddhist art, metalwork and stone pagodas, seen in King Muryeong\u0027s tomb and the Baekje incense burner.","Baekje passed Chinese writing, Buddhism and skilled craftsmen to Yamato Japan, its closest ally, before falling to Silla and the Tang in 660."],dyk:"King Muryeong\u0027s tomb at Gongju, found unlooted in 1971, held an epitaph stone naming the king, a rare case in which a Three Kingdoms royal tomb can be identified with certainty.",ev:[["18 BCE","Traditional founding of Baekje by Onjo at Wiryeseong"],["371","Geunchogo\u0027s army kills the Goguryeo king Gogugwon at Pyongyang"],["384","The monk Marananta brings Buddhism from the Eastern Jin"],["475","Goguryeo takes Hanseong; the court moves to Ungjin"],["538","King Seong moves the capital to Sabi"],["554","King Seong is killed fighting Silla at Gwansanseong"],["660","Silla and Tang take Sabi; King Uija surrenders"],["663","Tang and Silla defeat Baekje loyalists and a Yamato fleet at Baekgang"]]},
  "Kushan Empire": {t:["The Kushans, a branch of the Yuezhi, built an empire from Bactria across the Hindu Kush to the Ganges plain in the 1st–2nd centuries.","They controlled Silk Road trade between Han China, Parthia and Rome, and minted abundant gold coins showing gods of many religions.","Under Kanishka the Great, Gandharan and Mathuran art produced early images of the Buddha, and Buddhism spread into Central Asia."],dyk:"Kushan coins show a remarkable mix of gods, from the Iranian Mithra and the goddess Nana to Shiva, Heracles and the Buddha, labelled in Bactrian as Boddo.",ev:[["c. 30","Kujula Kadphises unites the five Yuezhi chiefdoms of Bactria"],["90","A Kushan army crossing the Pamirs is repulsed by the Han general Ban Chao"],["c. 127","Accession of Kanishka the Great and start of his era"],["c. 150","Huvishka succeeds Kanishka; the empire is at its height"],["229","An embassy from the Kushan king, probably Vasudeva I, reaches the Wei court"],["c. 262","Shapur I claims Kushanshahr as far as Peshawar"],["c. 375","Kidarites overrun the last Kushan kingdoms"]]},
  "Eastern Jin": {t:["The Eastern Jin carried on the Jin dynasty at Jiankang (Nanjing) after northern China fell to the Xiongnu-led Han Zhao in 311–316.","Power lay with great aristocratic clans such as the Wang, Huan and Xie, while the emperors were usually weak.","Its era saw Wang Xizhi\u0027s calligraphy, Tao Yuanming\u0027s poetry and the victory over the Former Qin at the Fei River in 383."],dyk:"Contemporaries said that \u0027the Wang and the Sima share the realm\u0027, so great was the power of the Wang clan of Langye at the court of the first Eastern Jin emperor.",ev:[["318","Sima Rui takes the imperial title at Jiankang as Emperor Yuan"],["347","Huan Wen conquers the Cheng Han state in Sichuan"],["353","Wang Xizhi writes his preface at the Orchid Pavilion gathering"],["383","Jin forces defeat the Former Qin at the Battle of Fei River"],["399","Sun En\u0027s Daoist rebellion breaks out in the coastal south"],["403","Huan Xuan usurps the throne as emperor of Chu"],["417","Liu Yu\u0027s army conquers the Later Qin and takes Chang\u0027an"],["420","Emperor Gong abdicates to Liu Yu, founder of the Liu Song"]]},
  "Rouran Khaganate": {t:["The Rouran ruled the Mongolian steppe from 402 to 552 as a confederation led by the Yujiulü clan.","Their khagan Shelun is the first ruler recorded as using khagan as the title of a supreme steppe sovereign.","Their Turkic ironworkers under Bumin revolted in 552, destroying the khaganate and founding the Turkic Khaganate."],dyk:"The Northern Wei emperor Taiwu ordered that the Rouran be called \u0027Ruanruan\u0027, meaning \u0027wriggling insects\u0027, as a deliberate insult.",ev:[["402","Shelun takes the title khagan after conquering the Gaoche"],["424","Rouran cavalry raid the Northern Wei centre of Shengle"],["429","Emperor Taiwu of Northern Wei routs the khagan Datan in Mongolia"],["460","The Rouran install Kan Bozhou as king of Gaochang"],["487","The Gaoche break away under Afuzhiluo"],["520","Anagui flees to the Northern Wei, which later restores him"],["552","Bumin\u0027s Turks defeat the Rouran; Anagui kills himself"],["555","The last Rouran refugees are killed at Chang\u0027an"]]},
  "Tibetan Empire": {t:["Yarlung kings united the Tibetan plateau in the 7th century and ruled it from Lhasa as divine emperors (tsenpo).","Its cavalry fought Tang China for the Tarim Basin and Hexi Corridor, and briefly occupied Chang\u0027an in 763.","It gave Tibet its script and made Buddhism the religion of the court, founding Samye monastery around 779."],dyk:"The peace treaty Tibet swore with Tang China in 821–822 was carved in Tibetan and Chinese on a stone pillar that still stands in front of the Jokhang temple in Lhasa.",ev:[["641","Princess Wencheng of Tang China arrives as a bride for the Tibetan royal house"],["663","Tibet conquers the Tuyuhun around Lake Kokonor"],["670","Tibetans defeat a Tang army at the Dafei River and overrun the Tarim Basin"],["763","A Tibetan army occupies the Tang capital Chang\u0027an for about two weeks"],["c. 779","Trisong Detsen founds Samye monastery"],["821–822","Tibet and Tang China swear a peace treaty, recorded on a pillar in Lhasa"],["842","Emperor Udumtsen (Langdarma) is assassinated and the empire breaks apart"]]},
  "Balhae": {t:["Founded in 698 by Dae Joyeong, who led Goguryeo refugees and Mohe tribesmen after the fall of Goguryeo.","It ruled Manchuria and northern Korea from Tang-style capitals such as Sanggyeong, modelled on Chang\u0027an.","Conquered by the Khitan in 926, it is claimed in Korean history as the northern partner of Unified Silla."],dyk:"The Tang Xuanming calendar, which Japan used for more than 800 years from 862, first reached Japan with an embassy from Balhae.",ev:[["698","Dae Joyeong defeats a Tang army at Tianmenling and founds the state of Jin"],["713","Tang recognises Dae Joyeong as Commandery Prince of Bohai"],["727","The first Balhae embassy reaches Japan"],["732","A Balhae fleet raids Dengzhou in Shandong"],["c. 756","King Mun moves the court to Sanggyeong, laid out on the plan of Chang\u0027an"],["818","King Seon begins a reign of northern expansion"],["926","King Dae Inseon surrenders to the Khitan; Balhae becomes the client state of Dongdan"]]},
  "Kara-Khanid Khanate": {t:["A Turkic dynasty, probably of Karluk origin, that ruled from Balasagun and Kashgar from the mid-9th century.","The first Turkic state to adopt Islam, it took Bukhara from the Samanids in 999, bringing Transoxiana under Turkic rule.","Its court culture gave rise to the first works of Turkic Islamic literature; rivalry split it in two around 1042."],dyk:"Mahmud al-Kashgari, a prince of the Kara-Khanid dynasty, drew a round map of the world with the Turkic lands at its centre for his dictionary of the Turkic languages.",ev:[["c. 840","The fall of the Uyghur Khaganate opens the way for a new Karluk-led khanate"],["893","The Samanid amir Ismail ibn Ahmad captures Talas"],["c. 934","Satuq Bughra Khan converts to Islam, according to tradition"],["960","Chroniclers record the conversion of 200,000 tents of Turks to Islam"],["999","Nasr ibn Ali takes Bukhara and ends the Samanid Empire"],["1008","Mahmud of Ghazni defeats the Kara-Khanids near Balkh"],["c. 1042","The khanate splits into eastern and western khanates"]]},
  "Ghurid Sultanate": {t:["Shansabani chiefs from the mountains of Ghor rose from Ghaznavid vassals to rulers of an empire from Khurasan to Bengal.","Mu\u0027izz al-Din won the Second Battle of Tarain in 1192, and his slave generals went on to found the Delhi Sultanate.","The Minaret of Jam, about 65 metres high, survives in a remote Afghan valley as a UNESCO World Heritage Site."],dyk:"In northern India the Ghurid sultan Mu\u0027izz al-Din Muhammad issued gold coins bearing the image of the Hindu goddess Lakshmi, following local coin designs.",ev:[["1011","Mahmud of Ghazni invades Ghor and captures its chief, Muhammad ibn Suri"],["c. 1150","Ala al-Din Husayn burns Ghazni for seven days, earning the name \u0027World Burner\u0027"],["1173","Mu\u0027izz al-Din takes Ghazni and makes it his base for campaigns in India"],["1186","The Ghurids take Lahore, ending Ghaznavid rule"],["1192","Mu\u0027izz al-Din defeats Prithviraj Chauhan at the Second Battle of Tarain"],["1204","The Khwarazmshah and the Qara Khitai defeat Mu\u0027izz al-Din at Andkhud"],["1206","Mu\u0027izz al-Din is assassinated; Qutb al-Din Aybak takes power at Lahore"],["1215","The Khwarazmian Empire takes Ghazni, ending Ghurid rule"]]},
  "Liao dynasty": {t:["Abaoji united the Khitan tribes and proclaimed himself emperor in 916; the state took the dynastic name Liao in 947.","It ruled nomads and Chinese farmers through a dual system of Northern and Southern Administrations.","The Treaty of Chanyuan of 1005 brought Song silver and silk; the Jurchen Jin destroyed the Liao by 1125."],dyk:"Cathay, the medieval European name for China, and Kitai, its Russian name, both come from the Khitan, the people who ruled the Liao empire.",ev:[["916","Abaoji proclaims himself emperor of the Khitan"],["926","The Khitan destroy Balhae and set up the client kingdom of Dongdan"],["938","Later Jin hands over the Sixteen Prefectures around modern Beijing"],["947","Yelü Deguang takes Kaifeng and adopts the dynastic name Liao"],["1005","The Treaty of Chanyuan brings annual Song payments of silver and silk"],["1056","The wooden Sakyamuni Pagoda at Yingxian is completed"],["1115","Wanyan Aguda proclaims the Jin dynasty and routs the Liao at Hubudagang"],["1125","The Jin capture the last Liao emperor, Tianzuo"]]},
  "Goryeo": {t:["A Korean kingdom founded by Wang Geon in 918 that reunited the peninsula in 936 and ruled it from Kaegyong (Kaesong).","Buddhism was the state religion: the court carved the Tripitaka Koreana, and Goryeo potters perfected inlaid celadon.","Military rule from 1170 and Mongol overlordship from 1259 weakened the crown, and Yi Seong-gye replaced it with Joseon in 1392."],dyk:"The Jikji, printed at Heungdeoksa temple in Cheongju in 1377, is the oldest surviving book printed with movable metal type; its only surviving volume is in the National Library of France.",ev:[["918","Wang Geon is raised to the throne and founds Goryeo"],["936","Taejo defeats Later Baekje, completing the reunification of the peninsula"],["958","Gwangjong introduces civil service examinations"],["1019","Gang Gam-chan destroys a Khitan army at the Battle of Gwiju"],["1170","Military officers seize power and depose King Uijong"],["1232","The court withdraws to Ganghwa Island during the Mongol invasions"],["1251","Carving of the Tripitaka Koreana woodblocks is completed"],["1392","Yi Seong-gye deposes King Gongyang and founds Joseon"]]},
  "Ghaznavid Empire": {t:["A sultanate founded by Turkic slave soldiers of the Samanids, ruling from Ghazni over Afghanistan, Khurasan and the Punjab.","Mahmud of Ghazni (r. 998–1030) led repeated raids into northern India, sacking the temple of Somnath in 1026.","The Seljuks took Khurasan at Dandanaqan in 1040; the Ghurids burned Ghazni and took Lahore in 1186."],dyk:"The scholar al-Biruni, brought to Ghazni after Mahmud conquered Khwarazm, learned Sanskrit and wrote a detailed study of Indian religion, science and customs, completed around 1030.",ev:[["977","Sabuktigin is chosen as leader of the Turkic garrison at Ghazni"],["999","Mahmud takes Khurasan and is recognised by the Abbasid caliph"],["1001","Mahmud defeats the Hindu Shahi king Jayapala near Peshawar"],["c. 1010","Ferdowsi completes the Shahnameh"],["1026","Mahmud sacks the temple of Somnath"],["1040","The Seljuks defeat Mas\u0027ud I at the Battle of Dandanaqan"],["c. 1150","Ala al-Din Husayn of Ghur sacks and burns Ghazni"],["1186","The Ghurids take Lahore, ending the dynasty"]]},
  "Jin dynasty (1115-1234)": {t:["An empire of the Jurchen people of Manchuria, founded by Wanyan Aguda in 1115 and named Jin, \u0027gold\u0027.","It destroyed the Liao, took the Song capital Kaifeng in 1127 and ruled northern China, moving its capital to Beijing in 1153.","Mongol invasions from 1211 drove the court to Kaifeng, and the dynasty ended at Caizhou in 1234."],dyk:"In 1127 Jin armies carried off two Song emperors, Huizong and his son Qinzong, to Manchuria, where both died in captivity.",ev:[["1115","Wanyan Aguda proclaims the Great Jin"],["1125","Jin capture the Liao emperor Tianzuo, ending the Liao state"],["1127","Jin take Kaifeng and carry off two Song emperors"],["1141","The Treaty of Shaoxing fixes the Song border on the Huai River"],["1153","Prince Hailing moves the capital to Zhongdu (Beijing)"],["1211","Genghis Khan invades and defeats the Jin at Yehuling"],["1215","The Mongols take Zhongdu"],["1234","Caizhou falls and Emperor Aizong takes his own life"]]},
  "Golden Horde": {t:["The khanate of Jochi\u0027s descendants, founded by Batu after the Mongol conquest of the western steppe and Rus\u0027 in 1236–1242.","From Sarai on the Volga its khans took tribute from the Rus\u0027 princes and traded with Genoese Crimea, Central Asia and Egypt.","Civil war after 1359 and Timur\u0027s campaigns broke it into the khanates of Kazan, Crimea and Astrakhan and the Great Horde."],dyk:"The name Golden Horde was coined by Russian writers centuries later; contemporaries called the state the Ulus of Jochi, after Genghis Khan\u0027s eldest son.",ev:[["1240","Batu\u0027s armies take Kiev"],["1242","Batu withdraws to the lower Volga and establishes his ulus"],["1313","Uzbek Khan begins a reign in which Islam becomes the state religion"],["1346","Plague strikes Janibeg\u0027s army besieging Caffa"],["1380","Dmitry of Moscow defeats Mamai at the Battle of Kulikovo"],["1395","Timur defeats Tokhtamysh on the Terek and sacks Sarai"],["1480","The Great Stand on the Ugra River ends Moscow\u0027s tribute"],["1502","Meñli I Giray of Crimea defeats the last khan and sacks Sarai"]]},
  "Joseon": {t:["Korea\u0027s longest-ruling dynasty, founded by Yi Seong-gye in 1392 and ruled from Hanseong, today\u0027s Seoul.","A model Neo-Confucian state run by examination-trained yangban officials; King Sejong created the Korean alphabet in 1443.","It survived Japanese and Manchu invasions but was forced open by Japan in 1876 and became the Korean Empire in 1897."],dyk:"The Annals of the Joseon Dynasty record 472 years of government day by day, written by court historians whose drafts even the king was not supposed to read.",ev:[["1392","Yi Seong-gye deposes the last Goryeo king and founds Joseon"],["1394","The capital moves to Hanyang (Seoul)"],["1443","King Sejong creates the Korean alphabet"],["1485","The Gyeongguk daejeon law code is promulgated"],["1592","Hideyoshi invades; Yi Sun-sin wins at Hansan Island"],["1637","Injo surrenders to the Qing after the siege of Namhansanseong"],["1876","The Treaty of Ganghwa opens Korea to Japan"],["1897","Gojong proclaims the Korean Empire"]]},
  "Ryukyu Kingdom": {t:["Sho Hashi unified Okinawa in 1429 and ruled from Shuri as a tributary king of Ming China.","Royal ships carried Chinese, Japanese and Southeast Asian goods, making Ryukyu a major trading hub in the 15th and 16th centuries.","After Satsuma\u0027s invasion in 1609 it served China and Japan at once, until Meiji Japan annexed it as Okinawa Prefecture."],dyk:"The bronze bell cast for Shuri Castle in 1458 bears an inscription calling Ryukyu a \u0027bridge of all nations\u0027, linking China, Japan and Korea by its ships.",ev:[["1429","Sho Hashi conquers Nanzan and completes the unification of Okinawa"],["1458","The \u0027bridge of all nations\u0027 bell is cast for Shuri Castle"],["1470","Kanemaru takes the throne as Sho En, founding the Second Sho dynasty"],["1500","Sho Shin\u0027s forces defeat Oyake Akahachi and take control of the Yaeyama Islands"],["1609","Satsuma invades and King Sho Nei surrenders Shuri"],["1719","Tamagusuku Chokun\u0027s kumi odori dance-dramas are first performed for Chinese envoys"],["1854","Commodore Perry signs a compact with the kingdom at Naha"],["1879","Japan abolishes the Ryukyu Domain and creates Okinawa Prefecture"]]},
  "Kazakh Khanate": {t:["Founded around 1465 by Kerei and Janibek, who broke away from the Uzbek ruler Abu\u0027l-Khayr Khan with their followers.","A nomadic confederation of three juzes under Genghisid khans, with law kept by biys and codified in the Zhety Zhargy.","Dzungar invasions after 1723 drove the juzes towards Russia, which abolished the khans\u0027 power in the 1820s."],dyk:"The name Kazakh is generally explained as meaning a free or independent wanderer, a word once used of men who had broken away from their own tribe or ruler.",ev:[["c. 1465","Kerei and Janibek lead their followers from the Uzbek Khanate into Moghulistan"],["1598","Tauekel Khan takes Tashkent and Turkistan from Bukhara"],["1643","Jahangir Khan checks the Dzungars at the Battle of Orbulaq"],["c. 1680–1715","Tauke Khan\u0027s reign; the Zhety Zhargy law code is attributed to him"],["1723","Dzungar invasion begins the \u0027Years of the Great Disaster\u0027"],["1731","Abulkhair Khan of the Junior Juz swears allegiance to Russia"],["1822","Russia abolishes the khanship in the Middle Juz"],["1847","Kenesary Kasymov, the last khan, is killed and his revolt ends"]]},
  "Dzungar Khanate": {t:["An Oirat Mongol khanate founded in the 1630s in Dzungaria and the Ili valley under the Choros dynasty.","It conquered the Tarim Basin, sacked Lhasa in 1717 and devastated the Kazakh steppe, contesting Central Asia with the Qing.","After succession wars, Qing armies destroyed it in 1755–1758 in a campaign many historians call a genocide."],dyk:"The Dzungars cast cannon with the help of Johan Gustaf Renat, a Swedish officer captured by Russia at Poltava in 1709 who later fell into Dzungar hands.",ev:[["1640","Erdeni Batur joins the assembly that drafts the Mongol-Oirat Code"],["1680","Galdan conquers the Yarkent Khanate and the Tarim Basin oases"],["1696","Kangxi\u0027s armies defeat Galdan at the Battle of Jao Modo"],["1717","Dzungar forces under Tsering Dondub sack Lhasa"],["1723","Dzungar invasion of the Kazakh steppe begins the \u0027Great Disaster\u0027"],["1731","Galdan Tseren destroys a Qing army at Hoton Nor"],["1755","Qing armies reach the Ili valley; Amursana rebels"],["1755–1758","Qing troops and smallpox destroy most of the Dzungar population"]]},
  "Republic of China": {t:["Founded in 1912 after the Xinhai Revolution, it ended more than two thousand years of imperial rule in China.","Under Chiang Kai-shek’s Nationalists it reunified much of China in 1928 and resisted Japan from 1937 to 1945.","After losing the civil war in 1949 it moved to Taiwan, where martial-law rule gave way to democracy in the 1990s."],dyk:"The Republic of China was a founding member of the United Nations and held one of the five permanent seats on the Security Council until 1971.",ev:[["1911","The Wuchang Uprising on 10 October begins the Xinhai Revolution"],["1912","Sun Yat-sen becomes provisional president at Nanjing; the last Qing emperor abdicates"],["1928","The Northern Expedition takes Beijing and the Nationalists reunify much of China"],["1937","War with Japan begins after the Marco Polo Bridge Incident"],["1949","Defeated in the civil war, the government moves to Taipei"],["1971","UN Resolution 2758 transfers China’s seat to the People’s Republic"],["1987","Martial law on Taiwan is lifted after 38 years"],["1996","First direct presidential election, won by Lee Teng-hui"]]},
  "People\u0027s Republic of China": {t:["Proclaimed by Mao Zedong on 1 October 1949 after the Communist victory in the Chinese Civil War.","The Great Leap Forward famine and the Cultural Revolution were among the greatest human catastrophes of the century.","Deng Xiaoping’s reforms from 1978 combined market economics with one-party rule and made China a global economic power."],dyk:"Hanyu Pinyin, the romanisation now used worldwide to spell Chinese names, was adopted by the People’s Republic in 1958.",ev:[["1949","Mao Zedong proclaims the People’s Republic in Beijing on 1 October"],["1950","Chinese People’s Volunteers enter the Korean War"],["1958","The Great Leap Forward begins, leading to the famine of 1959–61"],["1966","Mao launches the Cultural Revolution"],["1971","The People’s Republic takes China’s seat at the United Nations"],["1978","Deng Xiaoping launches reform and opening"],["1989","The army crushes the Tiananmen Square protests on 4 June"],["2001","China joins the World Trade Organization"]]},
  "Middle Kingdom of Egypt": {t:["Mentuhotep II of Thebes reunited Egypt, and the Twelfth Dynasty ruled it from a new residence, Itjtawy, near el-Lisht.","Kings built a bureaucratic state, curbed provincial governors, reclaimed the Faiyum and fortified the Nubian frontier at Semna.","Its literature and Middle Egyptian language became classics, studied by Egyptian scribes for some two thousand years."],dyk:"The Rhind Mathematical Papyrus, one of the main sources for Egyptian mathematics, was copied under the Hyksos from an original written in the reign of Amenemhat III.",ev:[["c. 2055 BCE","Mentuhotep II becomes king at Thebes and later reunites Egypt"],["c. 1985 BCE","Amenemhat I founds the Twelfth Dynasty and the residence of Itjtawy"],["c. 1956 BCE","Senusret I takes sole power and conquers Lower Nubia to the Second Cataract"],["c. 1862 BCE","Senusret III sets up a boundary stele at Semna fixing the Nubian frontier"],["c. 1831 BCE","Amenemhat III begins a long reign of Faiyum reclamation and pyramid building"],["c. 1773 BCE","Sobekneferu, last ruler of the Twelfth Dynasty, ends her reign"],["c. 1650 BCE","The Hyksos take Memphis and Itjtawy is abandoned"]]},
  "Numidia": {t:["Masinissa united the Massylii and Masaesyli after Zama in 202 BCE, creating a Berber kingdom centred on Cirta.","Its light cavalry was famed across the Mediterranean, and Punic was the language of its court and towns.","Jugurtha\u0027s war with Rome (112–105 BCE) exposed Roman corruption, and Caesar annexed the kingdom after Thapsus in 46 BCE."],dyk:"The historian Sallust, whose Jugurthine War is the main account of Numidia, was the first governor of the Roman province that replaced the kingdom.",ev:[["206 BCE","Masinissa leaves Carthage and allies with Scipio"],["202 BCE","Masinissa\u0027s cavalry helps Rome win the Battle of Zama; Numidia is united"],["150 BCE","Masinissa defeats Carthage, giving Rome a pretext for the Third Punic War"],["148 BCE","Masinissa dies; royal powers are divided among his sons"],["112 BCE","Jugurtha takes Cirta and kills Adherbal and Italian traders"],["105 BCE","Bocchus I hands Jugurtha over to Sulla"],["46 BCE","Caesar defeats Juba I at Thapsus and creates the province of Africa Nova"]]},
  "Africa Proconsularis": {t:["Rome made Carthage\u0027s land a province in 146 BCE; Augustus united it with Africa Nova and refounded Carthage as its capital.","Its grain, olive oil and fine pottery fed and furnished Rome, and its cities were among the richest in the empire.","It was a heartland of Latin Christianity, home to Tertullian, Cyprian and the long Donatist schism."],dyk:"The Acts of the Scillitan Martyrs, about Christians tried at Carthage in 180, are the oldest dated Christian document written in Latin.",ev:[["146 BCE","Rome destroys Carthage and creates the province of Africa, governed from Utica"],["46 BCE","Caesar annexes Numidian lands as Africa Nova after Thapsus"],["c. 27 BCE","Augustus unites the provinces as Africa Proconsularis, with Carthage as capital"],["17–24 CE","Revolt of Tacfarinas among the peoples of the interior"],["238","A revolt at Thysdrus proclaims Gordian I emperor"],["c. 303","Diocletian divides the province, creating Byzacena and Tripolitania"],["439","The Vandals under Gaiseric seize Carthage"]]},
  "Roman Egypt": {t:["Annexed by Octavian in 30 BCE, Egypt was ruled by a prefect answerable to the emperor alone.","Its grain fed Rome and Constantinople, and Alexandria was a centre of trade, science and philosophy.","Christian monasticism began in its deserts, and after 451 most Egyptians followed the church that became the Coptic Church."],dyk:"Senators were forbidden to visit Egypt without the emperor\u0027s permission, and Tiberius rebuked his nephew Germanicus for touring the country in 19 CE.",ev:[["30 BCE","Octavian takes Alexandria; Antony and Cleopatra VII die"],["115–117","Jewish revolt destroys the Jewish community of Alexandria"],["212","The Constitutio Antoniniana makes most free Egyptians Roman citizens"],["c. 320s","Pachomius founds communal monasteries at Tabennisi"],["451","Council of Chalcedon; most Egyptian Christians reject its creed"],["c. 619","The Sasanian Persians take Alexandria and occupy Egypt until 629"],["641","Alexandria is surrendered by treaty to the Rashidun Caliphate"]]},
  "Makuria": {t:["A Christian kingdom of the Middle Nile, ruled from Old Dongola, that absorbed neighbouring Nobadia by about 700.","Its archers repelled Arab invasions in 642 and 652, and the Baqt treaty kept it independent for some six centuries.","Mamluk intervention from 1276, Arab migration and civil war broke the kingdom, and the court left Dongola in the 1360s."],dyk:"Arab writers called the Makurian archers the pupil-smiters, because they aimed at their enemies\u0027 eyes and blinded many of the invaders in 642 and 652.",ev:[["c. 569","The Makurian court accepts Christianity, according to John of Biclaro"],["642","Makurian archers repel an Arab raid sent from newly conquered Egypt"],["652","Siege of Old Dongola ends with the Baqt treaty with Muslim Egypt"],["c. 700","Makuria and Nobadia form a single kingdom by the reign of Merkurios"],["c. 836","Prince Georgios travels to Baghdad to negotiate with the caliph al-Mu\u0027tasim"],["1172","Turan-Shah, brother of Saladin, sacks Qasr Ibrim"],["1276","A Mamluk army defeats King David and installs a tributary king"],["1317","The Throne Hall at Old Dongola is converted into a mosque"]]},
  "Hafsid Sultanate": {t:["A Berber dynasty of Almohad origin that ruled Ifriqiya, roughly modern Tunisia and eastern Algeria, from Tunis between 1229 and 1574.","Tunis prospered on grain, wool and leather exports and on treaties that let Italian and Catalan merchants trade under their own consuls.","Squeezed between Habsburg Spain and the Ottomans in the sixteenth century, the dynasty fell when Ottoman forces took Tunis in 1574."],dyk:"In 1257 an embassy from the king of Kanem, near Lake Chad, crossed the Sahara and presented the Hafsid ruler al-Mustansir with a giraffe, which caused a sensation in Tunis.",ev:[["1229","Abu Zakariya Yahya breaks with the Almohad caliph and rules Ifriqiya independently from Tunis"],["1253","Al-Mustansir takes the caliphal title of commander of the faithful"],["1270","Louis IX of France dies near Tunis during the Eighth Crusade"],["1332","Ibn Khaldun is born in Tunis"],["1347","The Marinid sultan Abu al-Hasan briefly occupies Tunis"],["1394–1434","Reign of Abu Faris Abd al-Aziz II restores Hafsid power"],["1535","Charles V takes Tunis and makes the Hafsid sultan a Spanish vassal"],["1574","Sinan Pasha’s Ottoman forces take Tunis and end the dynasty"]]},
  "Funj Sultanate": {t:["A sultanate on the Blue Nile, ruled from Sennar from 1504 to 1821, that took the place of the Christian Nubian kingdom of Alodia.","Its wealth came from gold, ivory and slaves traded to Egypt and the Red Sea, and its sultans ruled through vassal lords such as the Abdallab.","Under Funj rule Islam and Arabic spread across the middle Nile through Sufi orders and holy men, shaping modern Sudanese identity."],dyk:"The Scottish traveller James Bruce passed through Sennar in 1772 on his way back from Ethiopia and left one of the few eyewitness accounts of the Funj court.",ev:[["1504","Amara Dunqas founds Sennar, according to tradition"],["c. 1504","Funj and Abdallab forces destroy Soba, capital of Christian Alodia"],["c. 1612","Sultan Adlan I defeats and kills the Abdallab ruler Ajib at Karkoj"],["1644–1681","Reign of Badi II Abu Diqn, who builds a slave army"],["1744","Funj forces defeat the Ethiopian emperor Iyasu II on the Dinder River"],["1762","Hamaj regents take power after deposing Badi IV"],["1785","Darfur takes Kordofan from Sennar"],["1821","Badi VII submits to the Egyptian army of Ismail Kamil Pasha"]]},
  "Saadi Sultanate": {t:["A sharifian dynasty from the Draa valley that ruled Morocco from Marrakesh and Fez between 1510 and 1659.","It won the Battle of Alcácer Quibir in 1578, where three kings died, and kept Morocco outside the Ottoman Empire.","Ahmad al-Mansur grew rich on sugar and Saharan gold and conquered Songhai, but his death in 1603 opened a ruinous civil war."],dyk:"In 1612 the library of Sultan Zidan, sent by ship to safety during the civil war, was seized by Spanish vessels and ended up in the Escorial, where much of it remains.",ev:[["1510","The tribes of the Sus proclaim Muhammad al-Qa’im leader of the holy war against Portugal"],["1541","Muhammad al-Shaykh takes Agadir from the Portuguese"],["1549","The Saadis take Fez from the Wattasids"],["1578","Victory over Sebastian of Portugal at the Battle of Alcácer Quibir"],["1591","Judar Pasha defeats Songhai at the Battle of Tondibi"],["1603","Death of Ahmad al-Mansur and start of civil war among his sons"],["1627","Morisco corsairs found the Republic of Salé"],["1659","The last Saadi sultan is killed in Marrakesh"]]},
  "Regency of Algiers": {t:["An Ottoman province founded by the Barbarossa brothers, which became a largely self-governing corsair state ruled by elected deys.","Corsairing, captive ransoms and tribute from European states paid for a small Turkish military elite that ruled a mostly rural Maghreb.","It defeated Charles V in 1541 but was crippled by bombardments in 1815–1816 and conquered by France in 1830."],dyk:"Miguel de Cervantes spent five years as a captive in Algiers and tried to escape four times before Trinitarian friars ransomed him in 1580.",ev:[["1516","The corsair Oruç Barbarossa seizes Algiers"],["c. 1519","Hayreddin Barbarossa places Algiers under the Ottoman sultan and becomes beylerbey"],["1529","Hayreddin captures the Spanish fort on the Peñón and builds the harbour mole"],["1541","Charles V’s expedition against Algiers is wrecked by a storm and repulsed"],["1671","The corsair captains impose the first dey"],["1708","Algiers takes Oran from Spain, losing it in 1732 and recovering it in 1792"],["1816","An Anglo-Dutch fleet under Lord Exmouth bombards Algiers"],["1830","French troops land at Sidi Ferruch and Algiers capitulates on 5 July"]]},
  "French Algeria": {t:["Conquered from 1830 in a long and brutal war, Algeria was governed as part of France, with three departments from 1848.","About a million European settlers held land and power, while some eight to nine million Muslims lived as subjects without full rights.","The war of independence from 1954 brought down the Fourth Republic and ended with Algerian independence on 5 July 1962."],dyk:"The French Foreign Legion was founded in 1831 for service in Algeria and kept its headquarters at Sidi Bel Abbès until Algerian independence in 1962.",ev:[["1830","French troops land at Sidi Ferruch and Algiers capitulates on 5 July"],["1847","Abdelkader surrenders to French forces after fifteen years of resistance"],["1848","Northern Algeria is divided into the French departments of Algiers, Oran and Constantine"],["1870","The Crémieux Decree grants French citizenship to Algerian Jews"],["1871","The Mokrani revolt is crushed and followed by large land confiscations"],["1945","The Sétif and Guelma massacres follow riots on 8 May"],["1954","The FLN launches the war of independence on 1 November"],["1962","The Évian Accords end the war and Algeria becomes independent on 5 July"]]},
  "Ephesus": {t:["An Ionian Greek port near the mouth of the Cayster, founded by tradition c. 1000 BCE and famed for its sanctuary of Artemis.","The Artemision acted as bank, refuge and pilgrimage centre; its rebuilt temple was one of the Seven Wonders of the Ancient World.","Ephesus passed from Lydian, Persian, Athenian and Hellenistic overlords to Rome in 133 BCE and became the chief city of Roman Asia."],dyk:"A deposit beneath the Temple of Artemis contained some of the oldest coins ever found, small lumps of electrum from around 600 BCE.",ev:[["c. 1000 BCE","Ionian settlers, by tradition led by Androclus, found Greek Ephesus"],["c. 560 BCE","Croesus of Lydia takes the city and pays for columns of the marble Artemision"],["546 BCE","Ephesus passes under the Achaemenid Empire after the fall of Lydia"],["406 BCE","Lysander defeats the Athenian fleet at Notium, near Ephesus"],["356 BCE","Herostratus burns the Temple of Artemis"],["334 BCE","Alexander the Great restores democracy and gives the Persian tribute to Artemis"],["c. 290 BCE","Lysimachus moves the city to a new site and renames it Arsinoeia"],["133 BCE","Attalus III bequeaths Pergamon, including Ephesus, to Rome"]]},
  "Chios": {t:["An Ionian island state off Asia Minor, settled c. 1000 BCE, that became one of the richest cities in the Greek world.","Its wine, mastic and fleet made it a leading member of the Ionian League and, later, an autonomous naval ally of Athens.","Chios had early popular institutions and, by ancient accounts, more slaves than any Greek state except Sparta."],dyk:"Herodotus credits Glaucus of Chios with inventing the welding of iron; he made a famous iron stand for a silver bowl dedicated at Delphi by Alyattes of Lydia.",ev:[["c. 1000 BCE","Ionian Greeks settle Chios, which joins the Ionian League"],["c. 575–550 BCE","An inscribed law refers to a popular council on Chios"],["494 BCE","Chios sends 100 ships to the Battle of Lade"],["412 BCE","Chios revolts from Athens with Spartan support"],["378 BCE","Chios becomes a founding member of the Second Athenian League"],["357 BCE","Athenian general Chabrias is killed attacking the harbour of Chios in the Social War"],["86 BCE","Mithridates VI of Pontus deports the Chians towards the Black Sea"]]},
  "Miletus": {t:["The richest city of archaic Ionia, at the mouth of the Maeander, with its own oracle of Apollo at Didyma.","Milesian colonists founded dozens of settlements around the Black Sea, and Thales and his successors began Greek philosophy there.","Miletus led the Ionian Revolt against Persia and was sacked in 494 BCE, a disaster that led to the Persian Wars."],dyk:"The Athenian playwright Phrynichus was fined for staging The Capture of Miletus, because the play reminded Athenians of the disaster to their Ionian kin.",ev:[["c. 1000 BCE","Ionian Greeks settle Miletus, traditionally under Neleus, son of Codrus"],["c. 600 BCE","Thrasybulus makes peace with Alyattes of Lydia after eleven years of war"],["546 BCE","Miletus alone among Ionian cities gains a treaty with Cyrus the Great"],["499 BCE","Aristagoras launches the Ionian Revolt against the Achaemenid Empire"],["494 BCE","Persia defeats the Ionians at the Battle of Lade and sacks Miletus"],["479 BCE","Miletus is freed after the Battle of Mycale and rebuilt on a grid plan"],["334 BCE","Alexander the Great takes Miletus after a siege"],["133 BCE","Bequest of Attalus III brings Miletus under Roman supremacy in Asia"]]},
  "Samos": {t:["An Ionian island state off Mount Mycale, home of the great sanctuary of Hera and an early Greek naval power.","Under the tyrant Polycrates around 530 BCE it dominated the Aegean and built the harbour mole, the Heraion and the Tunnel of Eupalinos.","Samos was the birthplace of Pythagoras, Epicurus and Aristarchus, who argued that the earth moves around the sun."],dyk:"The Tunnel of Eupalinos, 1,036 metres long, was dug from both ends of a mountain at once in the sixth century BCE, and the two teams met almost exactly.",ev:[["c. 638 BCE","The Samian merchant Colaeus reaches Tartessos in Spain"],["c. 538 BCE","Polycrates seizes power and builds a fleet of a hundred ships"],["c. 525 BCE","A Spartan and Corinthian siege of Samos fails after forty days"],["c. 522 BCE","Polycrates is killed by the Persian satrap Oroetes"],["494 BCE","Most Samian ships desert at the Battle of Lade"],["440–439 BCE","Athens under Pericles crushes the Samian revolt"],["365 BCE","Athens takes Samos and settles it with Athenian cleruchs"],["129 BCE","Samos becomes part of the Roman province of Asia"]]},
  "Sparta": {t:["A Dorian city-state of the Eurotas valley that conquered Messenia and lived off the labour of state-owned serfs, the helots.","With two kings, five ephors and a citizen army trained from childhood, it was the leading land power of Classical Greece.","Sparta led Greece against Persia, defeated Athens in 404 BCE, and lost its power for good at Leuctra in 371 BCE."],dyk:"Classical Sparta had no city walls; for centuries it relied on its army alone and was fortified only in the Hellenistic period.",ev:[["c. 743–724 BCE","First Messenian War: Sparta conquers Messenia and reduces its people to helots"],["480 BCE","Leonidas I and 300 Spartiates fall at the Battle of Thermopylae"],["479 BCE","The regent Pausanias leads the Greeks to victory at the Battle of Plataea"],["464 BCE","An earthquake strikes Sparta and the helots of Messenia revolt"],["404 BCE","Athens surrenders to Sparta, ending the Peloponnesian War"],["371 BCE","Thebes defeats Sparta at the Battle of Leuctra"],["222 BCE","Cleomenes III is defeated at the Battle of Sellasia"],["146 BCE","After the Achaean War Sparta becomes a free city allied to Rome"]]},
  "Athens": {t:["Athens unified Attica and in 508/507 BCE created the democracy that let the citizen Assembly decide war, finance and law.","Its fleet won at Salamis in 480 BCE and led the Delian League, which Athens turned into a tribute-paying Aegean empire.","Defeated by Sparta in 404 BCE and dominated by Macedon after 338 BCE, it stayed the cultural capital of Greece until Sulla\u0027s sack."],dyk:"Athenian jurors and many officials were chosen by lot; from the fourth century a stone allotment machine, the kleroterion, was used to assign citizens to courts at random.",ev:[["594 BCE","Solon\u0027s reforms cancel debts on the person and abolish debt bondage"],["508 BCE","Cleisthenes reorganises the citizen body and founds the democracy"],["480 BCE","The Athenian-led Greek fleet defeats Xerxes I at Salamis"],["447 BCE","Construction of the Parthenon begins under Pericles"],["404 BCE","Athens surrenders to Sparta at the end of the Peloponnesian War"],["338 BCE","Philip II of Macedon defeats Athens and Thebes at Chaeronea"],["86 BCE","Sulla storms Athens after it sides with Mithridates VI"]]},
  "Knossos": {t:["Knossos grew from the ruins of the Minoan palace into one of the two leading Greek city-states of Iron Age Crete.","It was governed by annual kosmoi and a council of elders, with men\u0027s messes and age groups for citizen training.","Long rivalry with Gortyn and Lyttos ended when Quintus Caecilius Metellus conquered Crete for Rome in 69–67 BCE."],dyk:"Classical Knossos put the Labyrinth on its silver coins, sometimes with the Minotaur, centuries after the Bronze Age palace that inspired the legend had fallen into ruin.",ev:[["c. 800 BCE","Rich burials in the North Cemetery show Knossos among the wealthiest Aegean towns"],["c. 450 BCE","Treaty between Knossos and Tylissos made under the arbitration of Argos"],["c. 425 BCE","Knossos begins striking silver coins showing the Labyrinth"],["c. 220 BCE","Knossos seizes and destroys its rival Lyttos in the Lyttian War"],["c. 216 BCE","Philip V of Macedon becomes protector of the Cretan Koinon"],["c. 71 BCE","Cretans defeat the Roman fleet of Marcus Antonius near Kydonia"],["69–67 BCE","Quintus Caecilius Metellus conquers Crete, including Knossos"]]},
  "Delphi": {t:["Delphi was a small city-state in Phocis that existed to run the sanctuary of Apollo and the most famous oracle of the Greek world.","The Amphictyonic League of twelve peoples protected the shrine, ran the Pythian Games and could proclaim sacred wars.","Phocians, Macedonians, Aetolians and finally Romans controlled it in turn, until Greece came under Roman oversight in 146 BCE."],dyk:"Greeks believed Delphi was the centre of the earth: Zeus released two eagles from opposite ends of the world and they met there, a spot marked by a stone navel, the omphalos.",ev:[["c. 595–586 BCE","First Sacred War: the Amphictyons destroy Kirrha and consecrate its plain to Apollo"],["586 or 582 BCE","The Pythian Games are reorganised as a panhellenic festival"],["548 BCE","The temple of Apollo burns and is rebuilt with contributions from across Greece"],["479 BCE","The Greeks dedicate the Serpent Column after the victory at Plataea"],["356–346 BCE","Third Sacred War: the Phocians seize Delphi and spend its treasures"],["279 BCE","A Gallic army under Brennus is driven back from Delphi"],["191 BCE","Rome ends Aetolian control and restores Delphian autonomy"]]},
  "Byzantium": {t:["Byzantium was founded by colonists from Megara, traditionally in 667 BCE, on the promontory that commands the Bosporus.","It grew rich from tuna fishing, tolls and the Black Sea grain trade, and the great powers of Greece fought for its loyalty.","After centuries as an ally of Rome it lost its freedom under Vespasian; Constantine refounded it as Constantinople in 330 CE."],dyk:"Herodotus tells how the Persian general Megabazus called the people of Chalcedon blind for settling on the Asian shore when the far better site of Byzantium lay opposite.",ev:[["667 BCE","Megarian colonists found Byzantium, according to tradition"],["493 BCE","A Phoenician fleet burns the city after the failure of the Ionian Revolt"],["478 BCE","Pausanias captures Byzantium from the Persians"],["408 BCE","Alcibiades recovers Byzantium for Athens after a siege"],["340–339 BCE","Byzantium withstands the siege of Philip II of Macedon"],["220 BCE","Tolls on Black Sea shipping provoke war with Rhodes and Bithynia"],["c. 73 CE","Vespasian takes away the city\u0027s freedom and annexes it to a Roman province"]]},
  "Celtiberians": {t:["The Celtiberians were a group of Celtic-speaking peoples, including the Arevaci and Belli, living in fortified towns on the plateau of central Spain.","Famed as warriors and sword-makers, they served as mercenaries and resisted Rome in a series of wars from 181 to 133 BCE.","The fall of Numantia in 133 BCE broke their independence, and after the Sertorian War they were absorbed into Roman Spain."],dyk:"The poet Catullus mocked a Celtiberian named Egnatius for brushing his teeth with urine, a custom that the historian Diodorus Siculus also reported among the Celtiberians.",ev:[["211 BCE","Celtiberian mercenaries desert the Scipio brothers, contributing to their defeat"],["179 BCE","Tiberius Sempronius Gracchus ends the First Celtiberian War with treaties"],["153 BCE","The Belli under Carus ambush and defeat the consul Quintus Fulvius Nobilior"],["137 BCE","Numantia forces the consul Gaius Hostilius Mancinus to surrender with about 20,000 men"],["133 BCE","Scipio Aemilianus starves Numantia into surrender and razes it"],["87 BCE","The Tabula Contrebiensis records a land dispute settled at Contrebia Belaisca"],["72 BCE","Pompey ends the Sertorian War and reduces the last Celtiberian towns"]]},
  "Boeotian League": {t:["A federation of the cities of Boeotia in central Greece, led by Thebes, with a common coinage stamped with the Boeotian shield.","Its fifth-century constitution of eleven districts and a representative council of 660 is one of the best documented in Greece.","Under Epaminondas and Pelopidas it broke Spartan power at Leuctra in 371 BCE and briefly led Greece."],dyk:"The young Philip II of Macedon spent several years as a hostage at Thebes in the 360s BCE, at the height of Theban power, and probably learned from its generals.",ev:[["479 BCE","Boeotians fight on the Persian side and are defeated at the Battle of Plataea"],["447 BCE","Victory over Athens at Coronea leads to the refounding of the league"],["424 BCE","Pagondas defeats the Athenians at the Battle of Delium"],["386 BCE","The King’s Peace dissolves the league"],["379 BCE","Pelopidas and the exiles liberate Thebes and rebuild the league"],["371 BCE","Epaminondas defeats Sparta at the Battle of Leuctra"],["335 BCE","Alexander the Great destroys Thebes"],["171 BCE","Roman envoys break up the league"]]},
  "Roman Republic": {t:["Rome’s state from the expulsion of the kings in 509 BCE to Augustus in 27 BCE, ruled by elected magistrates, Senate and assemblies.","Its citizen army and Italian allies conquered Italy, defeated Carthage and the Hellenistic kingdoms, and took most of the Mediterranean.","From 133 BCE political violence and civil wars, from Sulla to Caesar and Octavian, ended in monarchy under Augustus."],dyk:"In the First Punic War Rome, with little naval tradition, built fleets of a hundred or more warships at a time, and fitted them with a boarding bridge, the corvus, to win at Mylae in 260 BCE.",ev:[["509 BCE","Traditional expulsion of Tarquinius Superbus and election of the first consuls"],["451–450 BCE","The Twelve Tables set out Roman law in writing"],["338 BCE","Victory in the Latin War and dissolution of the Latin League"],["216 BCE","Hannibal destroys a Roman army at the Battle of Cannae"],["146 BCE","Carthage and Corinth are destroyed"],["133 BCE","The tribune Tiberius Gracchus is killed, opening an age of political violence"],["44 BCE","Julius Caesar is murdered on the Ides of March"],["27 BCE","Octavian receives the name Augustus, beginning the Principate"]]},
  "Odrysian Kingdom": {t:["The first large Thracian state, formed after the Persian retreat from Europe and ruled from the valleys of the Maritsa and Tundzha.","Under Sitalces it reached from the Aegean to the Danube and invaded Macedonia in 429 BCE as an ally of Athens.","Divided after 360 BCE, it fell to Philip II and lived on as a client kingdom until Rome annexed Thrace in 46 CE."],dyk:"Thucydides noted that the Odrysians, unlike the Persians, made it a custom to receive gifts rather than give them, so that nothing could be done without one.",ev:[["c. 480 BCE","Teres I begins to unite the Thracian tribes under the Odrysians"],["431 BCE","Sitalces becomes an ally of Athens at the start of the Peloponnesian War"],["429 BCE","Sitalces invades Macedonia with a vast army"],["400 BCE","Seuthes II hires the survivors of Xenophon’s Ten Thousand"],["360 BCE","Murder of Cotys I; the kingdom is divided between three rulers"],["342–340 BCE","Philip II of Macedon conquers most of the Odrysian lands"],["c. 320 BCE","Seuthes III builds Seuthopolis near Kazanlak"],["46 CE","Claudius annexes Thrace as a Roman province"]]},
  "Bosporan Kingdom": {t:["A Greek kingdom on both shores of the Kerch Strait, ruled from Panticapaeum (modern Kerch) by the Spartocid dynasty for over three centuries.","Its grain exports helped feed classical Athens, which honoured its kings with citizenship, privileges and crowns.","It passed to Mithridates VI of Pontus and then lived on as a Roman client kingdom until the Hunnic invasions."],dyk:"Jewish communities in Panticapaeum freed slaves in the synagogue and recorded it on stone; one such manumission inscription dates from 81 CE.",ev:[["c. 480 BCE","The Archaeanactids unite the Greek cities around Panticapaeum"],["438 BCE","Spartocus I takes power, founding the Spartocid dynasty"],["389–349 BCE","Leucon I takes Theodosia and grants Athens privileges in the grain trade"],["310–309 BCE","Civil war between the sons of Paerisades I; Eumelus wins the throne"],["c. 108 BCE","Paerisades V hands the kingdom to Mithridates VI of Pontus"],["63 BCE","Mithridates VI dies at Panticapaeum; Pharnaces II becomes a Roman client king"],["45–49 CE","Rome replaces Mithridates, son of Aspurgus, with Cotys I"],["370s","The Huns overrun the region and the kingdom disappears"]]},
  "Rhodes": {t:["A single city-state created in 408 BCE by the union of the three old cities of Rhodes: Ialysos, Kamiros and Lindos.","Its skilled navy policed the eastern Mediterranean and protected the grain trade, making it the leading Hellenistic sea power.","Rome’s punishment in 167 BCE broke its economy, and it lost its freedom to Claudius and finally to Vespasian."],dyk:"After the Colossus fell in an earthquake, its remains lay where they had fallen for centuries; Pliny the Elder wrote that few people could wrap their arms around its thumb.",ev:[["408 BCE","Ialysos, Kamiros and Lindos unite to found the city of Rhodes"],["305–304 BCE","Rhodes withstands the siege of Demetrius Poliorcetes"],["c. 280 BCE","Completion of the Colossus of Rhodes by Chares of Lindos"],["c. 227 BCE","An earthquake ruins the city and topples the Colossus"],["190 BCE","The Rhodian fleet defeats a Seleucid squadron under Hannibal off Side"],["188 BCE","The Treaty of Apamea gives Rhodes Lycia and much of Caria"],["167 BCE","Rome takes Lycia and Caria and makes Delos a free port"],["43 BCE","Gaius Cassius captures and plunders Rhodes"]]},
  "Antigonid Kingdom of Macedonia": {t:["Founded by Alexander\u0027s general Antigonus I, the dynasty lost Asia at Ipsus in 301 BCE but won Macedon under Antigonus II Gonatas.","From Pella its kings dominated Greece with the sarissa phalanx and garrisons at Corinth, Chalcis and Demetrias.","Philip V\u0027s alliance with Hannibal began a series of wars with Rome that ended at Pydna in 168 BCE."],dyk:"The Colossus of Rhodes is said to have been paid for by selling the siege engines that Demetrius Poliorcetes left behind after his failed siege of the city in 305–304 BCE.",ev:[["306 BCE","Antigonus I and Demetrius take the royal title after the naval victory off Salamis"],["301 BCE","Antigonus I is killed at the Battle of Ipsus"],["277 BCE","Antigonus II Gonatas defeats the Gauls near Lysimachia and wins Macedon"],["243 BCE","Aratus of Sicyon seizes Acrocorinth from its Macedonian garrison"],["222 BCE","Antigonus III Doson defeats Cleomenes III of Sparta at Sellasia"],["215 BCE","Philip V allies with Hannibal against Rome"],["197 BCE","Rome defeats Philip V at Cynoscephalae"],["168 BCE","Perseus is defeated at Pydna; Rome abolishes the monarchy"]]},
  "Sarmatians": {t:["Iranian-speaking horse nomads who broke the Scythians and held the steppe from the Volga to the Danube for six centuries.","Not one state but a confederation of tribes such as the Iazyges, Roxolani, Aorsi, Siraces and Alans, each with its own kings.","Their armoured lancers fought and served Rome; the Goths and then the Huns ended their dominance in the 3rd and 4th centuries."],dyk:"Herodotus claimed that a Sauromatian girl could not marry until she had killed an enemy in battle, and archaeologists have found many early Sarmatian women buried with weapons.",ev:[["c. 250 BCE","Sarmatian tribes cross the Don and lay waste much of Scythia"],["179 BCE","The Sarmatian ruler Gatalos is named in the treaty ending the war of Pharnaces I of Pontus"],["69 CE","The Legio III Gallica destroys 9,000 Roxolani raiders in Moesia"],["92 CE","A Sarmatian war under Domitian costs Rome a legion"],["175 CE","Iazyges king Zanticus makes peace; 5,500 Sarmatian horsemen are sent to Britain"],["334 CE","The Limigantes revolt; Constantine settles Sarmatian refugees in the empire"],["c. 375 CE","The Huns defeat the Alans and Goths, scattering the Sarmatian peoples"]]},
  "Achaean League": {t:["A federation of Greek cities with shared citizenship, coinage and foreign policy, led by an annually elected general.","Under Aratus and Philopoemen it grew from four Achaean towns to the whole Peloponnese by 191 BCE.","Rome dissolved it after the war of 146 BCE and the sack of Corinth; Polybius made it a model for later federal thinkers."],dyk:"James Madison discussed the Achaean League in The Federalist No. 18 as a lesson for the new United States on the strengths and dangers of federal union.",ev:[["280 BCE","Dyme, Patrae, Tritaia and Pharai renew the Achaean League"],["251 BCE","Aratus frees Sicyon and brings it into the league"],["243 BCE","Aratus seizes Acrocorinth from the Macedonians"],["224 BCE","The league cedes Acrocorinth to Antigonus III Doson for help against Sparta"],["207 BCE","Philopoemen defeats Machanidas of Sparta at Mantinea"],["191 BCE","With Messene and Elis, the league unites the whole Peloponnese"],["167 BCE","About 1,000 Achaeans, including Polybius, are deported to Italy"],["146 BCE","Rome defeats the league and Lucius Mummius sacks Corinth"]]},
  "Lusitania": {t:["Augustus created the province from western Hispania Ulterior, with its capital at the veteran colony of Emerita Augusta.","Farming, mining and fish-salting made it prosperous, and its monuments at Mérida and Alcántara still stand.","The Alans and then the Suebi ended Roman rule by 439, but its name survives as a classical name for Portugal."],dyk:"Roman writers repeated a legend that Lusitanian mares could conceive from the west wind, which was said to explain the remarkable speed of their foals.",ev:[["139 BCE","The Lusitanian leader Viriathus is murdered, ending the Lusitanian War"],["27 BCE","Augustus begins the division of Hispania Ulterior"],["25 BCE","Emerita Augusta is founded for veterans of the Cantabrian Wars"],["58 CE","Otho begins a decade as governor of Lusitania"],["c. 104–106","The bridge at Alcántara is built over the Tagus"],["304","Eulalia is martyred at Emerita"],["411","The Alans receive Lusitania in the division of Hispania"],["439","The Suebic king Rechila takes Emerita"]]},
  "Hispania Tarraconensis": {t:["Formed from Hispania Citerior, it stretched from the Pyrenees to Galicia and was governed from Tarraco.","It held Rome\u0027s only Iberian legion, the VII Gemina at León, guarding the great gold mines of the north-west.","Split by Diocletian around 293, the reduced province was the last Roman territory in Iberia, lost to the Visigoths in the 470s."],dyk:"When the people of Tarraco told Augustus that a palm tree had sprouted on his altar, he reportedly replied that this showed how often they lit fires on it, according to Quintilian.",ev:[["26–25 BCE","Augustus campaigns against the Cantabri and winters at Tarraco"],["19 BCE","Agrippa ends the Cantabrian Wars"],["15 CE","Tiberius allows a temple to the deified Augustus at Tarraco"],["68 CE","The governor Galba is proclaimed emperor at Carthago Nova"],["259","Bishop Fructuosus is martyred in the amphitheatre of Tarraco"],["c. 293","Diocletian splits off Gallaecia and Carthaginiensis"],["449","Bagaudae and Suebi plunder the Ebro valley"],["c. 472–475","The Visigoths under Euric take Tarraco"]]},
  "Roman Britain": {t:["Roman Britain was the province of Britannia, covering most of England and Wales from the Claudian invasion of 43 until about 410.","It held one of the largest garrisons in the empire, guarding a northern frontier marked by Hadrian\u0027s Wall and the Antonine Wall.","Towns such as London, York and Lincoln, a road network, villas and Christianity were its lasting legacies."],dyk:"Constantine the Great was proclaimed emperor at York in 306, after his father Constantius died there while campaigning in Britain.",ev:[["43","Claudius\u0027s general Aulus Plautius invades with four legions; Camulodunum falls"],["60 or 61","Boudica of the Iceni destroys Camulodunum, Londinium and Verulamium before her defeat"],["83 or 84","Agricola defeats the Caledonians at Mons Graupius in northern Scotland"],["c. 122","Building begins on Hadrian\u0027s Wall from the Tyne to the Solway"],["286","Carausius declares himself emperor and rules Britain independently until 293"],["306","Constantine the Great is proclaimed emperor at York"],["367","Picts, Scotti and Saxons overrun the province in the \u0027barbarian conspiracy\u0027"],["410","Honorius reportedly tells the cities of Britain to look to their own defence"]]},
  "Alemanni": {t:["A confederation of Germanic peoples on the upper Rhine and Danube, ruled by many separate kings rather than one.","After Rome abandoned the Limes around 260 they settled the lands of later Swabia, Alsace and northern Switzerland.","Defeated by Clovis I around 496–506, they became the Frankish Duchy of Alamannia; their dialects survive today."],dyk:"The French word for Germany, Allemagne, and the Spanish Alemania come from the Alemanni, one people of the south-west, not from the Germans as a whole.",ev:[["213","Caracalla campaigns on the Main; Cassius Dio names the Alemanni"],["c. 260","Rome abandons the Limes and the Alemanni begin to settle the Agri Decumates"],["271","Alemanni and Juthungi defeat Aurelian at Placentia before he destroys them"],["357","Julian defeats Chnodomar’s coalition at the Battle of Strasbourg"],["374","Valentinian I makes peace with King Macrianus on the Rhine near Mainz"],["378","Gratian’s army defeats the Lentienses at Argentaria in Alsace"],["c. 496","Clovis I defeats the Alemanni, traditionally at Tolbiac"],["c. 506","A second Frankish victory ends Alemannic independence"]]},
  "Franks": {t:["A confederation of Germanic peoples on the lower Rhine, formed in the 3rd century from older groups such as the Chamavi and Bructeri.","Franks raided Roman Gaul but also served Rome, reaching the highest commands under generals such as Arbogast and Bauto.","Childeric I and his son Clovis I turned the confederation into the Frankish kingdom from which France and Germany grew."],dyk:"Childeric I’s grave at Tournai, found in 1653, held some 300 gold bees or cicadas; Napoleon adopted the bee as an imperial emblem partly in their memory.",ev:[["c. 257","Frankish raiders break into Roman Gaul; some reportedly reach Spain"],["c. 306","Constantine throws the Frankish kings Ascaric and Merogaisus to beasts at Trier"],["358","Julian allows the Salian Franks to stay in Toxandria"],["392","The Frankish general Arbogast makes Eugenius emperor in the West"],["c. 445","King Chlodio takes Cambrai and the land up to the Somme"],["451","Franks fight with Aetius at the Battle of the Catalaunian Plains"],["c. 481","Childeric I dies at Tournai and Clovis I becomes king"]]},
  "Saxons": {t:["A confederation of north German peoples between the Elbe and the Rhine, ruled by nobles and assemblies rather than kings.","Saxon sea raiders troubled Roman Britain and Gaul, and Saxon settlers helped create Anglo-Saxon England.","Charlemagne’s Saxon Wars of 772–804 ended their independence with mass deportations and forced conversion."],dyk:"In Finnish and Estonian, Germany is still named after the Saxons: Saksa and Saksamaa.",ev:[["c. 285","Carausius is given command against Frankish and Saxon pirates"],["367","Saxons join the \u0027barbarian conspiracy\u0027 that overruns Roman Britain"],["c. 449","Bede’s traditional date for the arrival of Saxon settlers in Britain"],["c. 695","Saxons conquer the lands of the Bructeri between the Lippe and the Ruhr"],["772","Charlemagne takes the Eresburg and destroys the Irminsul"],["782","Saxons defeat the Franks in the Süntel hills; mass execution at Verden"],["785","Widukind is baptised at Attigny with Charlemagne as godfather"],["804","Deportation of the Nordalbingian Saxons ends the Saxon Wars"]]},
  "Kingdom of the Picts": {t:["The Picts were the peoples of Scotland north of the Forth, united from the 6th century under powerful over-kings.","Bridei son of Beli’s victory at Dun Nechtain in 685 ended Northumbrian rule north of the Forth.","After Viking defeats in the 9th century, Picts and Gaels merged into the kingdom of Alba, the core of Scotland."],dyk:"Pictish carved symbols, such as the crescent and V-rod and the double disc and Z-rod, appear on many stones across Scotland, yet their meaning has never been deciphered.",ev:[["297","A Roman panegyric first names the Picts as enemies of Britain"],["367","Picts join the \u0027barbarian conspiracy\u0027 against Roman Britain"],["c. 565","Columba visits King Bridei son of Maelchon near the River Ness"],["685","Bridei son of Beli defeats and kills Ecgfrith of Northumbria at Dun Nechtain"],["717","Nechtan son of Der-Ilei expels the clergy of Iona"],["741","Óengus son of Fergus carries out the \u0027smiting\u0027 of Dál Riata"],["839","Vikings kill King Eóganán and many Pictish nobles"],["c. 843","Cináed mac Ailpín becomes king of the Picts"]]},
  "Kingdom of Powys": {t:["A Welsh kingdom formed in the old territory of the Cornovii after Roman rule ended, centred on the upper Severn and the hills of mid Wales.","For three centuries it bore the brunt of Mercian expansion, losing its eastern lowlands; Offa’s Dyke was built along its frontier.","Its dynasty revived under Bleddyn ap Cynfyn and Madog ap Maredudd, but the kingdom was divided into two after Madog died in 1160."],dyk:"The inscription on the Pillar of Eliseg is now almost illegible; its text is known mainly because the scholar Edward Lhuyd copied it in 1696.",ev:[["c. 615","King Selyf ap Cynan is killed at the Battle of Chester against Æthelfrith of Northumbria"],["late 8th c.","Offa of Mercia builds Offa’s Dyke along the frontier with Powys"],["822","The Mercians take Powys ‘into their power’, according to the Annales Cambriae"],["854","Cyngen ap Cadell, last of the old line, dies on pilgrimage at Rome"],["1063","Bleddyn ap Cynfyn becomes ruler of Powys and Gwynedd"],["1141","Madog ap Maredudd leads Welsh troops for Ranulf of Chester at the Battle of Lincoln"],["1160","Madog dies and Powys is divided into Powys Fadog and Powys Wenwynwyn"]]},
  "Kingdom of Gwynedd": {t:["The leading Welsh kingdom, based on the mountains of Snowdonia and the grain lands of Anglesey, with its chief royal court at Aberffraw.","Its rulers, from Rhodri the Great to Llywelyn the Great, repeatedly brought much of Wales under their authority.","Llywelyn ap Gruffudd was recognised as Prince of Wales in 1267, but Edward I conquered Gwynedd in 1282–1283."],dyk:"A sixth-century gravestone at Penmachno calls the dead man a citizen of ‘Venedotis’, one of the earliest written records of the name of Gwynedd.",ev:[["547","Maelgwn Gwynedd, the king Gildas called the dragon of the island, dies of plague"],["633","Cadwallon ap Cadfan and Penda of Mercia defeat and kill Edwin of Northumbria"],["855","Rhodri the Great adds Powys to Gwynedd"],["1165","Henry II’s invasion of Wales founders on the Berwyn mountains against Owain Gwynedd"],["1218","The Treaty of Worcester confirms Llywelyn the Great’s dominance in Wales"],["1267","The Treaty of Montgomery recognises Llywelyn ap Gruffudd as Prince of Wales"],["1282","Llywelyn ap Gruffudd is killed near Cilmeri"],["1284","The Statute of Rhuddlan turns Gwynedd into English shires"]]},
  "Kingdom of the Franks": {t:["Founded by Clovis I, it was the most durable kingdom to emerge from the Western Roman Empire and the common ancestor of France and Germany.","Clovis’s Catholic baptism allied the Franks with the church; the Carolingians later allied with the papacy, which crowned Charlemagne emperor in 800.","Kings divided the realm among their sons, and the Treaty of Verdun of 843 split it into West, Middle and East Francia."],dyk:"The Carolingian reckoning of 12 pennies to the shilling and 240 to the pound survived in Britain’s pounds, shillings and pence until decimalisation in 1971.",ev:[["486","Clovis I defeats Syagrius and takes the Roman Domain of Soissons"],["507","Clovis defeats the Visigoths at the Battle of Vouillé, winning Aquitaine"],["534","The Franks conquer the Kingdom of the Burgundians"],["687","Pippin of Herstal wins at Tertry and becomes the real ruler of the Franks"],["732","Charles Martel defeats an Umayyad army between Poitiers and Tours"],["751","Pippin the Short deposes the last Merovingian king and is anointed"],["800","Pope Leo III crowns Charlemagne emperor in Rome"],["843","The Treaty of Verdun divides the realm among Charlemagne’s grandsons"]]},
  "Dal Riata": {t:["A Gaelic kingdom straddling the North Channel, with lands in County Antrim and in Argyll, ruled from the rock fortress of Dunadd.","Columba’s monastery on Iona, founded under its kings in 563, carried Christianity and learning to the Picts and Northumbria.","Weakened by defeats and Pictish attack, it merged with Pictland in the ninth century, and its Gaelic speech became Scotland’s."],dyk:"The summit of Dunadd bears a carved human footprint, a rock basin and a boar, which are thought to have been used in the inauguration of kings.",ev:[["563","Columba founds the monastery of Iona"],["574","Áedán mac Gabráin becomes king, ordained by Columba according to Adomnán"],["603","Æthelfrith of Northumbria defeats Áedán at the Battle of Degsastan"],["637","Domnall Brecc is defeated at the Battle of Mag Rath in Ireland"],["736","Óengus son of Fergus, king of the Picts, captures Dunadd"],["795","Viking raids on the Hebrides and Iona begin"],["c. 842","Cináed mac Ailpín becomes king of the Picts"]]},
  "Kingdom of Wessex": {t:["The kingdom of the West Saxons, centred on Winchester, which grew from small beginnings in the upper Thames valley and the Solent region.","Under Alfred the Great it alone of the English kingdoms survived the Viking onslaught, defended by a network of fortified burhs.","Alfred’s heirs conquered the Danelaw, and in 927 Æthelstan made Wessex the core of the Kingdom of England."],dyk:"The Anglo-Saxon Chronicle, first compiled in Wessex in Alfred’s reign, was still being kept up at Peterborough Abbey in 1154.",ev:[["577","Ceawlin wins the Battle of Dyrham, taking Gloucester, Cirencester and Bath"],["635","King Cynegils is baptised by Bishop Birinus"],["c. 694","Ine issues the first West Saxon law code"],["825","Ecgberht defeats Mercia at the Battle of Ellendun"],["878","Alfred defeats Guthrum at the Battle of Edington"],["886","Alfred occupies London and is recognised as king of the Anglo-Saxons"],["927","Æthelstan takes York and becomes king of the English"]]},
  "Kingdom of Mercia": {t:["A midland Anglo-Saxon kingdom that grew from a frontier people into the largest and strongest of the English kingdoms.","Under Æthelbald and Offa (716–796) it dominated southern England, built Offa\u0027s Dyke and dealt with Charlemagne.","Wessex broke its power in 825; the Vikings split it in 877, and western Mercia joined the English kingdom in 918."],dyk:"Offa issued a gold coin copying an Abbasid dinar, complete with an Arabic inscription, to which the moneyer added the Latin words OFFA REX.",ev:[["633","Penda and Cadwallon kill Edwin of Northumbria at the Battle of Hatfield Chase"],["655","Penda is killed by Oswiu of Northumbria at the Battle of the Winwaed"],["679","Æthelred defeats Ecgfrith of Northumbria at the Battle of the Trent"],["787","An archbishopric is created at Lichfield and Offa\u0027s son Ecgfrith is consecrated king"],["825","Ecgberht of Wessex defeats Beornwulf of Mercia at the Battle of Ellendun"],["873–874","The Great Heathen Army winters at Repton and King Burgred flees to Rome"],["877","The Vikings divide Mercia, settling its eastern half"],["918","Æthelflæd dies; Edward the Elder takes Mercia into the West Saxon kingdom"]]},
  "Duchy of Bavaria": {t:["Bavaria was a duchy from c. 555 to 1623, ruled in turn by the Agilolfings, Frankish kings, Luitpoldings, Welfs and Wittelsbachs.","Bavarian settlers and the church of Salzburg spread Christianity and German speech into the eastern Alps and Austria.","Under Maximilian I it led the Catholic League and in 1623 was raised to an electorate, later the Kingdom of Bavaria."],dyk:"Austria began as an eastern frontier march of Bavaria and only became a separate duchy in 1156; Bavarian dialects are still spoken across most of Austria.",ev:[["c. 555","The Franks recognise Garibald I of the Agilolfing family as duke of the Bavarians"],["739","Boniface organises the bishoprics of Salzburg, Regensburg, Freising and Passau"],["788","Charlemagne deposes Duke Tassilo III, ending Agilolfing rule"],["1156","The Privilegium Minus separates Austria from Bavaria as a duchy"],["1180","Frederick Barbarossa grants Bavaria to Otto of Wittelsbach"],["1340","Emperor Louis IV reunites Upper and Lower Bavaria"],["1505","The Landshut War of Succession ends; Albert IV reunites Bavaria"],["1623","Maximilian I receives the electoral dignity; Bavaria becomes an electorate"]]},
  "Avar Khaganate": {t:["A steppe khaganate that ruled the Carpathian basin from 568, with a mounted warrior elite over Slavs, Gepids and others.","It drew huge gold payments from Byzantium and besieged Constantinople in 626, but failed to take it.","Charlemagne\u0027s Franks destroyed the Avar Ring in 795–796; the Avars are last mentioned in 822."],dyk:"The Avars are generally credited with bringing the iron stirrup into Europe, and the Byzantine Strategikon advised Roman cavalry to copy their equipment.",ev:[["558","Avar envoys reach Justinian I in Constantinople"],["567","Bayan I and the Lombards destroy the Kingdom of the Gepids"],["582","The Byzantine city of Sirmium surrenders to the Avars after a long blockade"],["626","The Avars and Persians besiege Constantinople and fail"],["c. 631","A struggle for the khaganate between an Avar and a Bulgar candidate"],["791","Charlemagne campaigns down the Danube against the Avars"],["795–796","Frankish forces capture the Ring and carry off the Avar treasure"],["822","Avar envoys at Frankfurt; the last mention of the Avars"]]},
  "Kingdom of Northumbria": {t:["A union of the Anglian kingdoms of Bernicia and Deira that stretched from the Humber to the Firth of Forth.","Its monasteries produced Bede, Alcuin, the Lindisfarne Gospels and the Codex Amiatinus, the Northumbrian Renaissance.","Defeat at Nechtansmere in 685 ended its expansion; the Vikings took York in 867 and England absorbed it in 954."],dyk:"The Codex Amiatinus, made at Wearmouth-Jarrow and the oldest surviving complete Latin Bible, was long thought to be Italian until its Northumbrian origin was identified in the 1880s.",ev:[["655","Oswiu defeats and kills Penda of Mercia at the Battle of the Winwaed"],["664","The Synod of Whitby adopts Roman practice for dating Easter"],["685","The Picts defeat and kill Ecgfrith at the Battle of Nechtansmere"],["731","Bede completes the Ecclesiastical History of the English People"],["793","Vikings sack the monastery of Lindisfarne"],["867","The Great Heathen Army holds York; kings Osberht and Ælla are killed"],["954","Eric Bloodaxe is expelled and Northumbria passes to the English crown"]]},
  "First Bulgarian Empire": {t:["Founded in 681 by Asparuh\u0027s Bulgars among the Slavs south of the Danube, it was Byzantium\u0027s chief Balkan rival for three centuries.","Boris I\u0027s conversion in 864 and the schools of Preslav and Ohrid made it the cradle of Slavonic letters and Cyrillic.","Under Simeon I (893–927) it dominated the Balkans; Basil II destroyed it after the Battle of Kleidion in 1014."],dyk:"After killing the emperor Nikephoros I in 811, Khan Krum had the emperor\u0027s skull lined with silver and used it as a drinking cup, according to Byzantine sources.",ev:[["681","Byzantium makes peace with Asparuh\u0027s Bulgars, recognising the new state"],["811","Krum destroys the army of Nikephoros I, who is killed"],["864","Boris I accepts baptism from Byzantium"],["886","Boris I receives the disciples of Cyril and Methodius"],["917","Simeon I crushes a Byzantine army at the Battle of Achelous"],["927","Byzantium recognises Peter I as tsar and the Bulgarian patriarchate"],["1014","Basil II destroys Samuel\u0027s army at the Battle of Kleidion"],["1018","The Bulgarian nobles surrender to Basil II at Ohrid"]]},
  "Republic of Venice": {t:["A merchant republic on the lagoon, led by an elected doge and a closed hereditary nobility for about eleven centuries.","Its fleets and colonies, from Dalmatia to Crete and Cyprus, made it the main link between Latin Europe and the East.","Ottoman advances and new ocean routes eroded its power, and Napoleon ended the republic in 1797."],dyk:"Venice opened the first public opera house, the Teatro San Cassiano, in 1637, when opera elsewhere was still largely a court entertainment.",ev:[["697","Traditional date of the election of Paolo Lucio Anafesto as first doge"],["828","Venetian merchants bring the relics of Saint Mark from Alexandria"],["1082","Alexios I Komnenos grants Venice tax-free trade in the Byzantine Empire"],["1204","The Fourth Crusade, led by Doge Enrico Dandolo, takes Constantinople"],["1297","The Serrata closes the Great Council to a hereditary nobility"],["1381","The Peace of Turin ends the War of Chioggia against Genoa"],["1571","Cyprus falls to the Ottomans; the Holy League wins at Lepanto"],["1797","Doge Ludovico Manin abdicates and the Great Council dissolves the republic"]]},
  "Volga Bulgaria": {t:["A Bulgar state founded by Turkic-speaking migrants at the confluence of the Volga and Kama rivers.","In 922 its ruler adopted Islam, making it the first state of eastern Europe with Islam as its official faith.","It grew rich on northern furs and Islamic silver until the Mongols destroyed it in 1236."],dyk:"Chuvash, spoken today in the Volga region of Russia, is the only living language of the Oghuric branch of Turkic, the branch spoken by the Volga Bulgars.",ev:[["c. 700","Bulgar groups move north from the Black Sea steppe to the middle Volga"],["922","Ruler Almish adopts Islam during the embassy described by Ibn Fadlan"],["965","Sviatoslav I of Kiev breaks Khazar power, ending Bulgar tribute"],["985","Vladimir of Kiev campaigns against the Bulgars and makes peace"],["1164","Andrei Bogolyubsky of Vladimir-Suzdal takes the Bulgar town of Bryakhimov"],["1223","The Bulgars defeat a Mongol force near the Samara Bend"],["1236","The Mongols destroy Bilyar and conquer Volga Bulgaria"]]},
  "Kingdom of Asturias": {t:["A small Christian kingdom in the Cantabrian Mountains founded after the Muslim conquest of Iberia, traditionally at Covadonga.","Its kings claimed to restore the Visigothic order, an idea that later fed the Reconquista.","Expansion to the Douro shifted power south, and in 924 the kingdom merged into the Kingdom of León."],dyk:"Pelagius’s son and successor Favila was killed by a bear in 739, after only two years as king, according to the Asturian chronicles.",ev:[["718 or 722","Pelagius defeats a Muslim force at Covadonga"],["c. 761","Fruela I founds Oviedo"],["791","Alfonso II becomes king and makes Oviedo the royal capital"],["c. 820s–830s","The supposed tomb of Saint James is discovered at Compostela"],["848","Santa María del Naranco is consecrated under Ramiro I"],["868","Vímara Peres takes Porto, creating the County of Portugal"],["878","Coimbra is taken and Alfonso III wins at Polvoraria"],["910","Alfonso III is deposed and the realm divided among his sons"]]},
  "Papal States": {t:["The lands of central Italy ruled by the popes as temporal sovereigns from the Frankish donations of the 750s until 1870.","Papal control was often weak, but Renaissance popes made the state a real power and Rome an artistic capital.","Napoleon and then Italian unification dismantled it; Vatican City, created in 1929, is its last remnant."],dyk:"Pope Julius II, who founded the Swiss Guard in 1506, personally led his army in winter 1511 and entered the captured town of Mirandola through a breach in its walls.",ev:[["754","Pope Stephen II wins the protection of Pepin the Short against the Lombards"],["800","Leo III crowns Charlemagne emperor in Rome"],["1357","Cardinal Albornoz issues the Egidian Constitutions"],["1506","Julius II takes Bologna and founds the Swiss Guard"],["1527","Imperial troops sack Rome"],["1809","Napoleon annexes the Papal States to the French Empire"],["1860","Defeat at Castelfidardo; the Marche and Umbria join Italy"],["1870","Italian troops enter Rome through the breach at Porta Pia"]]},
  "Emirate of Córdoba": {t:["Founded in 756 by Abd al-Rahman I, a survivor of the Abbasid massacre of the Umayyad family.","It made al-Andalus an independent Islamic state and began the Great Mosque of Córdoba around 785.","After decades of revolt, Abd al-Rahman III reunited it and declared it a caliphate in 929."],dyk:"Exiles expelled from Córdoba after the Revolt of the Arrabal of 818 later took part in the conquest of Crete, which became an Arab emirate for over a century.",ev:[["756","Abd al-Rahman I defeats Yusuf al-Fihri at al-Musara and becomes emir"],["778","Charlemagne’s expedition to Zaragoza fails; rearguard destroyed at Roncesvalles"],["c. 785","Construction of the Great Mosque of Córdoba begins"],["818","Al-Hakam I crushes the Revolt of the Arrabal in Córdoba"],["844","Vikings sack Seville and are defeated at Tablada"],["c. 880","Umar ibn Hafsun begins his rebellion from Bobastro"],["928","Bobastro falls to Abd al-Rahman III"],["929","Abd al-Rahman III proclaims himself caliph"]]},
  "County of Toulouse": {t:["A great principality of southern France, ruled by the Raymondine counts of Toulouse from the ninth century until 1271.","Its courts patronised the troubadours, and Count Raymond IV led a major army on the First Crusade that founded the County of Tripoli.","The Albigensian Crusade against the Cathars broke the counts, and the county passed to the French crown in 1271."],dyk:"Simon de Montfort, leader of the Albigensian Crusade, was killed in 1218 by a stone from a siege engine outside Toulouse; an Occitan chronicle says women of the city worked the machine.",ev:[["778","Charlemagne appoints Chorson as count of Toulouse"],["1096","Raymond IV leaves for the First Crusade at the head of the southern army"],["1109","Raymond IV’s son Bertrand takes Tripoli, founding the County of Tripoli"],["1159","Henry II of England besieges Toulouse but withdraws"],["1209","The Albigensian Crusade begins with the massacre at Béziers"],["1213","Simon de Montfort defeats Raymond VI and Peter II of Aragon at Muret"],["1229","The Treaty of Paris marries Raymond VII’s heiress to Alphonse of Poitiers"],["1271","The county passes to the French crown"]]},
  "Kingdom of Navarre": {t:["A Basque kingdom of the western Pyrenees, ruled from Pamplona, which emerged around 824 between the Franks and the Muslim Ebro valley.","Under Sancho III the Great (1004–1035) it dominated Christian Iberia, and his sons founded the royal lines of Castile and Aragon.","Castile conquered its southern part in 1512, but Navarre kept its own laws until 1841, while its northern kings became kings of France."],dyk:"In 958 the elderly Queen Toda of Pamplona travelled to Córdoba with her grandson Sancho the Fat of León, who was treated there by the caliph’s physician for his obesity.",ev:[["c. 824","Íñigo Arista becomes ruler of Pamplona after a Frankish defeat at Roncevaux"],["905","Sancho Garcés I founds the Jimena dynasty"],["1034","Sancho III the Great occupies León, the height of his power"],["1076","Murder of Sancho IV at Peñalén; Pamplona passes to the king of Aragon"],["1134","García Ramírez restores an independent kingdom"],["1212","Sancho VII fights at Las Navas de Tolosa"],["1512","Ferdinand the Catholic conquers Upper Navarre"],["1841","The Ley Paccionada makes Navarre a province of Spain"]]},
  "Kingdom of Scotland": {t:["A northern British kingdom formed from the Picts and Gaelic Dál Riata, traditionally dated to Kenneth MacAlpin around 843.","It kept its independence against England in the Wars of Independence, won by Robert the Bruce at Bannockburn in 1314.","James VI inherited England in 1603, and the Acts of Union of 1707 merged the two kingdoms into Great Britain."],dyk:"James II of Scotland, an enthusiast for artillery, was killed in 1460 when one of his own cannons burst during the siege of Roxburgh Castle.",ev:[["c. 843","Kenneth MacAlpin becomes king of the Picts"],["1266","The Treaty of Perth transfers the Western Isles from Norway"],["1314","Robert the Bruce defeats Edward II at Bannockburn"],["1320","The Declaration of Arbroath asserts Scottish independence"],["1513","James IV is killed at the Battle of Flodden"],["1560","The Reformation Parliament creates a Protestant church"],["1603","James VI inherits the English throne"],["1707","The Acts of Union create the Kingdom of Great Britain"]]},
  "Duchy of Saxony": {t:["A stem duchy of northern Germany between the Rhine and the Elbe, ruled by the Liudolfing, Billung, Welf and Ascanian families.","Its dukes became German kings and emperors, from Henry the Fowler in 919 through the Ottonians to Lothair III.","Henry the Lion made it a near-royal power, but his fall in 1180 broke up the duchy, which was finally divided around 1296."],dyk:"The bronze lion that Henry the Lion set up in Brunswick around 1166 is often described as the first large free-standing hollow-cast sculpture made north of the Alps since antiquity.",ev:[["852","Count Liudolf and Oda found the convent of Gandersheim"],["919","Duke Henry is elected king of East Francia"],["933","Henry the Fowler defeats the Magyars at Riade"],["1115","Saxon princes defeat Emperor Henry V at Welfesholz"],["c. 1159","Henry the Lion refounds Lübeck on the Baltic"],["1180","Frederick Barbarossa deposes Henry the Lion and divides Saxony"],["c. 1296","The duchy splits into Saxe-Lauenburg and Saxe-Wittenberg"]]},
  "County of Flanders": {t:["A county on the North Sea coast, founded in 862, whose counts held most of it from France and a smaller part from the German emperors.","Its cloth towns of Ghent, Bruges and Ypres made it one of the wealthiest and most urbanised regions of medieval Europe.","It passed to Burgundy in 1384, then to the Habsburgs, lost its south to France, and was annexed by France in 1795."],dyk:"Flanders’ founder, Baldwin Iron Arm, won his county by eloping with Judith, a Carolingian princess who had already been married to two kings of Wessex, father and son.",ev:[["862","Baldwin Iron Arm elopes with Judith, daughter of Charles the Bald"],["1127","Count Charles the Good is murdered in Bruges"],["1204","Baldwin IX becomes the first Latin emperor of Constantinople"],["1302","Flemish militias defeat French knights at the Battle of the Golden Spurs"],["1340","Edward III is proclaimed king of France at Ghent"],["1384","Flanders passes to Philip the Bold of Burgundy"],["1432","The Ghent Altarpiece is completed"],["1795","France annexes the county"]]},
  "Kingdom of Norway": {t:["Traditionally united by Harald Fairhair around 872, Norway became a Christian kingdom under Olaf Tryggvason and Saint Olaf.","Its medieval realm reached from Greenland to the Baltic, and Magnus the Lawmender gave it a national law code in 1274.","After union with Denmark from 1380 and with Sweden from 1814, Norway became fully independent again in 1905."],dyk:"When Magnus Erlingsson was crowned in Bergen in 1163 or 1164, it was the first royal coronation held anywhere in Scandinavia.",ev:[["c. 872","Harald Fairhair wins the Battle of Hafrsfjord, by tradition uniting Norway"],["1030","Olaf Haraldsson is killed at Stiklestad and soon venerated as Saint Olaf"],["1262–1264","Iceland submits to the Norwegian crown, following Greenland"],["1274","Magnus the Lawmender issues a national law code"],["1380","Olaf IV inherits Norway, beginning the union with Denmark"],["1814","The Eidsvoll constitution is adopted; Norway enters union with Sweden"],["1905","The union with Sweden is dissolved and Haakon VII becomes king"],["1940–1945","Germany occupies Norway; the king and government continue the war from London"]]},
  "Kievan Rus\u0027": {t:["A federation of East Slavic principalities ruled by the Rurikid dynasty from Kiev, on the river route from the Baltic to Byzantium.","Vladimir the Great\u0027s conversion around 988 brought Orthodox Christianity, Cyrillic writing and Byzantine art to Rus\u0027.","Fragmented into rival principalities after 1132, it was destroyed by the Mongols, who sacked Kiev in 1240."],dyk:"More than a thousand letters written on birch bark, found at Novgorod since 1951, show ordinary townspeople of Rus\u0027 writing everyday notes, debts and family messages.",ev:[["882","Oleg of Novgorod takes Kiev and makes it his seat"],["911","Oleg concludes a trade treaty with the Byzantine Empire"],["c. 965","Sviatoslav I destroys the Khazar Khaganate"],["c. 988","Vladimir the Great accepts Byzantine Christianity"],["1036","Yaroslav the Wise becomes sole ruler and defeats the Pechenegs"],["1097","The Council of Liubech confirms each prince\u0027s hereditary patrimony"],["1169","Andrei Bogolyubsky of Vladimir-Suzdal sacks Kiev"],["1240","Batu Khan\u0027s Mongol army storms and sacks Kiev"]]},
  "Duchy of Aquitaine": {t:["Founded by William the Pious in 893, the duchy was ruled from Poitiers by the counts of Poitou for nearly two centuries.","Duke William IX is the earliest troubadour whose songs survive, and the ducal courts helped create courtly love poetry.","Through Eleanor of Aquitaine it passed to the English crown, which held Gascony until the French victory at Castillon in 1453."],dyk:"William the Pious, the first duke of Aquitaine, founded the abbey of Cluny in 910; its reformed monasticism spread to hundreds of houses across Latin Europe.",ev:[["893","William the Pious, count of Auvergne, takes the title of duke of Aquitaine"],["910","William the Pious founds the abbey of Cluny"],["1137","Eleanor of Aquitaine inherits the duchy and marries the future Louis VII of France"],["1152","Eleanor marries Henry Plantagenet, joining Aquitaine to the Angevin lands"],["1259","The Treaty of Paris confirms English rule of Gascony under French overlordship"],["1337","Philip VI confiscates Gascony, opening the Hundred Years\u0027 War"],["1360","The Treaty of Brétigny grants England an enlarged Aquitaine in full sovereignty"],["1453","French victory at Castillon ends English rule; Guyenne joins France"]]},
  "County of Hainaut": {t:["A county on the Scheldt and Sambre, ruled from Mons and Valenciennes, within the Holy Roman Empire but facing France.","Its counts became Latin emperors of Constantinople and married into the French and English royal houses.","Absorbed by Burgundy in 1433 and partly lost to France in 1659–1678, it was annexed by revolutionary France in 1795."],dyk:"Philippa of Hainaut, queen of Edward III, took the Valenciennes chronicler Jean Froissart into her service, giving him access to the English court for his chronicles.",ev:[["c. 898","Reginar Longneck holds comital power in Hainaut"],["1051","Countess Richilde marries Baldwin of Flanders"],["1204","Count Baldwin VI becomes the first Latin emperor of Constantinople"],["1299","John II of Avesnes unites Hainaut with Holland and Zeeland"],["1328","Philippa of Hainaut marries Edward III of England"],["1433","Jacqueline of Bavaria surrenders Hainaut to Philip the Good of Burgundy"],["1678","The Treaty of Nijmegen confirms the French conquest of southern Hainaut"],["1795","Revolutionary France annexes Hainaut as the department of Jemmapes"]]},
  "Kingdom of León": {t:["Successor of Asturias, the kingdom took its name from León, the royal seat from 914, and ruled Galicia and the Douro plain.","Its kings claimed Visigothic heritage and an imperial title, and Alfonso VI captured Toledo in 1085.","The Cortes of León of 1188 included townsmen; in 1230 León was united permanently with Castile."],dyk:"The Pantheon of the Kings at San Isidoro in León, burial place of Leonese royalty, preserves twelfth-century Romanesque wall paintings that include a calendar of the labours of the months.",ev:[["910","Alfonso III\u0027s sons divide his realm; García I rules from León"],["939","Ramiro II defeats Abd al-Rahman III at Simancas"],["997","Almanzor sacks Santiago de Compostela"],["1037","Ferdinand I of Castile kills Bermudo III at Tamarón and takes León"],["1085","Alfonso VI captures Toledo"],["1135","Alfonso VII is crowned emperor in León"],["1188","Alfonso IX summons the Cortes of León with town representatives"],["1230","The Treaty of Benavente unites León with Castile under Ferdinand III"]]},
  "Duchy of Normandy": {t:["A Viking settlement on the lower Seine, granted to Rollo in 911, that became a French duchy ruled from Rouen.","Its dukes kept unusually firm control over castles, barons and the Church, and its abbeys such as Bec led European learning.","Duke William conquered England in 1066; Philip II of France annexed the duchy in 1204."],dyk:"The Channel Islands are the last part of the old Duchy of Normandy still held by the British crown, and their law still rests partly on Norman custom.",ev:[["911","Charles the Simple grants the Viking leader Rollo lands around Rouen"],["c. 1034","Herluin founds the abbey of Bec, later home to Lanfranc and Anselm"],["1047","William II defeats rebel barons at the Battle of Val-ès-Dunes"],["1066","Duke William defeats Harold Godwinson at Hastings and becomes King of England"],["1106","Henry I of England defeats Robert Curthose at the Battle of Tinchebray"],["1144","Geoffrey Plantagenet takes Rouen and is recognised as duke"],["1204","Philip II of France takes Château Gaillard and Rouen and annexes Normandy"]]},
  "Duchy of Burgundy": {t:["A French duchy around Dijon, Beaune and Chalon, ruled by a Capetian line from 1032 to 1361.","Cîteaux, founded near Dijon in 1098, made Burgundy the cradle of the Cistercian order and of famous monastic vineyards.","Its Valois dukes built a wider Burgundian State; after Charles the Bold fell at Nancy in 1477, France annexed the duchy."],dyk:"In 1395 Duke Philip the Bold ordered the Gamay grape uprooted from Burgundy’s vineyards, calling it a ‘very bad and disloyal’ plant, in favour of Pinot noir.",ev:[["c. 918","Richard the Justiciar is recognised as duke of Burgundy"],["1032","Henry I of France grants the duchy to his brother Robert, founding the Capetian line"],["1098","Robert of Molesme founds Cîteaux, mother house of the Cistercian order"],["1361","Duke Philip of Rouvres dies of plague and the Capetian line ends"],["1363","John II grants Burgundy to his son Philip the Bold"],["1430","Philip the Good founds the Order of the Golden Fleece"],["1435","The Treaty of Arras reconciles Burgundy and France"],["1477","Charles the Bold dies at Nancy and Louis XI occupies the duchy"]]},
  "Kingdom of England": {t:["Unified by Æthelstan in 927, England became one of the most centralised kingdoms of medieval Europe.","It developed the common law, Magna Carta and Parliament, institutions later carried across the world.","Joined with Scotland under one crown in 1603, it merged into the Kingdom of Great Britain in 1707."],dyk:"Domesday Book, compiled in 1086 for William the Conqueror, surveyed more than 13,000 places in England and is one of the most complete records of any medieval kingdom.",ev:[["927","Æthelstan takes York and receives the submission of the northern rulers"],["1066","William of Normandy defeats Harold Godwinson at the Battle of Hastings"],["1215","King John accepts Magna Carta at Runnymede"],["1415","Henry V defeats the French at the Battle of Agincourt"],["1534","The Act of Supremacy makes Henry VIII head of the Church of England"],["1588","English ships help defeat the Spanish Armada"],["1649","Charles I is executed and the Commonwealth of England proclaimed"],["1707","The Acts of Union create the Kingdom of Great Britain"]]},
  "Caliphate of Córdoba": {t:["Abd al-Rahman III proclaimed himself caliph at Córdoba in 929, rivalling the Abbasids of Baghdad and the Fatimids.","Córdoba became the largest city of western Europe, with the Great Mosque, Madinat al-Zahra and celebrated libraries.","After the regent Almanzor’s death, civil war from 1009 broke the caliphate, which was abolished in 1031."],dyk:"In 958 the deposed King Sancho I of León, known as ‘the Fat’, travelled to Córdoba with his grandmother Queen Toda of Navarre to be treated for obesity by Hasdai ibn Shaprut.",ev:[["929","Abd al-Rahman III proclaims himself caliph"],["936","Work begins on the palace city of Madinat al-Zahra"],["939","Ramiro II of León defeats the caliph at the Battle of Simancas"],["961","Al-Hakam II succeeds and later enlarges the Great Mosque of Córdoba"],["997","Almanzor sacks Santiago de Compostela"],["1009","A revolt in Córdoba begins the Fitna, the civil war of al-Andalus"],["1013","Berber troops take and plunder Córdoba"],["1031","The notables of Córdoba abolish the caliphate"]]},
  "Kingdom of Arles": {t:["Formed around 933 by uniting Upper and Lower Burgundy, it stretched from Lake Geneva to the Mediterranean.","From 1032 it was the third kingdom of the Holy Roman Empire, beside Germany and Italy.","Real power lay with counts, bishops and the houses of Savoy and Viennois; France gradually absorbed its lands."],dyk:"In 972 Muslim raiders from Fraxinetum on the Provençal coast captured Abbot Majolus of Cluny in the Alps; the outrage led to the destruction of their base soon afterwards.",ev:[["c. 933","Rudolf II of Upper Burgundy acquires Lower Burgundy from Hugh of Arles"],["937","Conrad the Peaceful succeeds under the protection of Otto I"],["c. 973","Count William of Provence destroys the Muslim base at Fraxinetum"],["1032","Rudolf III dies childless and the kingdom passes to Emperor Conrad II"],["1178","Frederick Barbarossa is crowned king at Arles"],["1349","The Dauphiné of Viennois passes to the heir of the French throne"],["1365","Charles IV is crowned at Arles, the kingdom’s last coronation"],["1378","Charles IV makes the French dauphin imperial vicar of the kingdom for life"]]},
  "Kingdom of Denmark": {t:["Traced to Gorm the Old around 936, Denmark is among the oldest continuous monarchies in the world.","Its kings ruled England under Cnut, led the Kalmar Union of 1397 and taxed Baltic shipping through the Sound Toll.","Defeats by Sweden in 1658 and by Prussia and Austria in 1864 left a small state that rebuilt itself as a welfare democracy."],dyk:"The Royal Law of 1665, which made the Danish king absolute, was not published until 1709 and is often called the only written constitution of European absolutism.",ev:[["c. 965","Harald Bluetooth adopts Christianity and raises the great Jelling stone"],["1219","Valdemar II wins at Lyndanisse and establishes Danish rule in northern Estonia"],["1397","Margaret I unites Denmark, Norway and Sweden in the Kalmar Union"],["1536","Christian III introduces the Lutheran Reformation"],["1658","The Treaty of Roskilde cedes Scania, Halland and Blekinge to Sweden"],["1814","The Treaty of Kiel transfers Norway to Sweden"],["1849","The Constitution of 5 June ends absolute monarchy"],["1864","Defeat in the Second Schleswig War costs Schleswig and Holstein"]]},
  "Duchy of Brittany": {t:["Alan Twisted Beard founded the duchy in 939 after driving the Vikings out of Brittany.","Under the Montfort dukes it built near-sovereign institutions: a council, Estates, a chamber of accounts and its own coinage.","Defeat in 1488 and Anne of Brittany’s marriages to two French kings led to union with France in 1532."],dyk:"The Catholicon, a Breton–French–Latin dictionary compiled in 1464 and printed at Tréguier in 1499, is the first Breton dictionary and one of the earliest of French.",ev:[["939","Alan Twisted Beard defeats the Vikings at Trans"],["1213","Peter Mauclerc of Dreux becomes duke by marriage to the heiress Alix"],["1351","The Combat of the Thirty is fought during the War of the Breton Succession"],["1364","John of Montfort wins the Battle of Auray and becomes Duke John IV"],["1488","French victory at Saint-Aubin-du-Cormier; Francis II dies"],["1491","Anne of Brittany marries Charles VIII of France"],["1532","The Edict of Union joins Brittany to the Kingdom of France"],["1547","Henry II becomes king and the ducal title merges with the crown"]]},
  "Duchy of Lorraine": {t:["Created by the division of Lotharingia in 959, Lorraine was ruled from 1048 to 1737 by the descendants of Gerard of Alsace.","René II’s victory at Nancy in 1477, where Charles the Bold died, secured the duchy between France and the Empire.","French occupations from 1633 and the exchange for Tuscany in 1737 ended its independence; it became French in 1766."],dyk:"The last duke, Francis Stephen, married Maria Theresa and became Holy Roman Emperor; their house of Habsburg-Lorraine ruled Austria until 1918.",ev:[["959","Lotharingia is divided and Upper Lorraine created"],["1048","Emperor Henry III grants the duchy to Gerard of Alsace"],["1477","René II defeats and kills Charles the Bold at the Battle of Nancy"],["1542","The Treaty of Nuremberg recognises Lorraine as a free duchy"],["1552","France seizes the Three Bishoprics of Metz, Toul and Verdun"],["1633","French troops occupy Nancy"],["1697","The Treaty of Ryswick restores Duke Leopold"],["1766","Stanisław Leszczyński dies and Lorraine is annexed to France"]]},
  "Kingdom of Sweden": {t:["The kingdom grew from the union of the Svear around Uppsala and the Geats of the south-west around the year 1000.","Under Gustav II Adolf and his successors it became the dominant Baltic power, winning German lands at Westphalia in 1648.","Defeat at Poltava in 1709 ended its empire; after 1814 it kept out of war and built a model welfare state."],dyk:"The Riksbank, founded in 1668, is the oldest central bank still in operation, and its predecessor Stockholms Banco issued Europe’s first banknotes in 1661.",ev:[["1164","Uppsala becomes the seat of an archbishopric"],["1397","Sweden joins Denmark and Norway in the Kalmar Union"],["1523","Gustav Vasa is elected king and Sweden leaves the Kalmar Union"],["1632","Gustav II Adolf is killed at the Battle of Lützen"],["1648","The Peace of Westphalia gives Sweden lands in northern Germany"],["1709","Charles XII is defeated by Peter the Great at Poltava"],["1809","Finland is ceded to Russia by the Treaty of Fredrikshamn"],["2024","Sweden joins NATO"]]},
  "Prince-Bishopric of Liège": {t:["Bishop Notger (972–1008) turned the see of Liège into a territorial principality of the Holy Roman Empire.","The Peace of Fexhe of 1316 bound the prince-bishop to change the law only with the consent of the estates.","Coal and arms making made it rich; the Liège Revolution of 1789 and French annexation in 1795 ended it."],dyk:"The Feast of Corpus Christi began in Liège, instituted by its bishop in 1246 after the visions of Juliana of Cornillon, before Pope Urban IV extended it to the whole church.",ev:[["985","Otto III grants Bishop Notger the county of Huy"],["1096","Liège buys Bouillon from Godfrey of Bouillon"],["1246","The Feast of Corpus Christi is first instituted in Liège"],["1316","The Peace of Fexhe establishes government with the consent of the estates"],["1408","John the Fearless defeats the Liège rebels at Othée"],["1468","Charles the Bold sacks and burns Liège"],["1789","The Liège Revolution drives out the prince-bishop"],["1795","France annexes the principality"]]},
  "Kingdom of France": {t:["Founded when Hugh Capet was elected king in 987, it was ruled by Capetians, Valois and Bourbons for more than 800 years.","Its kings grew a small domain around Paris into Europe\u0027s most populous kingdom through war, marriage, inheritance and law.","Louis XIV\u0027s Versailles made France the model of European monarchy, but unreformed debt led to the Revolution of 1789."],dyk:"The Estates-General, the kingdom\u0027s assembly of clergy, nobles and commons, did not meet at all between 1614 and 1789, when its summons opened the Revolution.",ev:[["987","Hugh Capet is elected and crowned king, founding the Capetian dynasty"],["1214","Philip II Augustus defeats Otto IV and his allies at the Battle of Bouvines"],["1337","The Hundred Years\u0027 War with England begins"],["1429","Joan of Arc relieves Orléans and Charles VII is crowned at Reims"],["1598","Henry IV\u0027s Edict of Nantes grants toleration to the Huguenots"],["1682","Louis XIV moves the court and government to Versailles"],["1789","The Estates-General meets and the Revolution begins"],["1792","The monarchy is abolished and the First Republic proclaimed"]]},
  "Kingdom of Hungary (1000-1301)": {t:["Founded when Stephen I was crowned in 1000 or 1001, it brought the Magyars into Latin Christendom.","Royal counties, a Latin church and the union with Croatia in 1102 made it a major power of central Europe.","The Mongols devastated it in 1241; after rebuilding, baronial power grew until the Árpád male line ended in 1301."],dyk:"The Golden Bull of 1222, issued seven years after England\u0027s Magna Carta, allowed the nobles to resist a king who broke its terms.",ev:[["1000","Stephen I is crowned the first king of Hungary"],["1030","Emperor Conrad II\u0027s invasion of Hungary fails"],["1102","Coloman is crowned king of Croatia, uniting the two crowns"],["1222","Andrew II issues the Golden Bull, limiting royal power"],["1241","The Mongols destroy the royal army at the Battle of Mohi"],["1278","Hungarian troops help Rudolf of Habsburg defeat Ottokar II on the Marchfeld"],["1301","Andrew III dies, ending the Árpád male line"]]},
  "Kingdom of Aragon": {t:["A Pyrenean kingdom that took Zaragoza and the Ebro valley from al-Andalus in the twelfth century.","Petronila\u0027s marriage to the count of Barcelona created the Crown of Aragon, which later joined Castile to form Spain.","Its Cortes, fueros and the Justicia limited royal power until Philip V abolished them in 1707."],dyk:"Ramiro II, a monk called from the cloister to the throne in 1134, married to provide an heir and retired to monastic life once his baby daughter Petronila was betrothed.",ev:[["1035","Ramiro I receives Aragon on the death of Sancho III of Navarre"],["1096","Peter I takes Huesca after the Battle of Alcoraz"],["1118","Alfonso I the Battler captures Zaragoza"],["1137","Petronila is betrothed to Ramon Berenguer IV, count of Barcelona"],["1283","Peter III grants the General Privilege to the Union of Aragon"],["1469","Ferdinand II of Aragon marries Isabella of Castile"],["1591","The Justicia Juan de Lanuza is executed after the Antonio Pérez affair"],["1707","The Nueva Planta decrees abolish Aragon\u0027s fueros"]]},
  "Kingdom of Castile": {t:["Created when Ferdinand I divided his realms in 1065, Castile was ruled together with León for most of its history.","Alfonso VI\u0027s capture of Toledo in 1085 made Castile the leading Christian power and a centre of translation from Arabic.","Victory at Las Navas de Tolosa in 1212 opened al-Andalus, and union with León in 1230 created the Crown of Castile."],dyk:"Henry I of Castile, king at ten, died in 1217 aged thirteen after being struck on the head by a roof tile while playing with other boys at the bishop\u0027s palace in Palencia.",ev:[["1065","Ferdinand I\u0027s death leaves Castile to his eldest son Sancho II"],["1072","Sancho II is murdered at Zamora and Alfonso VI reunites Castile and León"],["1085","Alfonso VI captures Toledo"],["1086","The Almoravids defeat Alfonso VI at the Battle of Sagrajas"],["1135","Alfonso VII is crowned emperor in León"],["1195","The Almohads defeat Alfonso VIII at the Battle of Alarcos"],["1212","A Christian coalition destroys the Almohad army at Las Navas de Tolosa"],["1230","Ferdinand III inherits León, creating the Crown of Castile"]]},
  "Electoral Palatinate": {t:["The counts palatine of the Rhine ruled scattered Rhineland lands from Heidelberg and were imperial electors from 1356.","It was the leading Reformed Protestant state of the Empire and the home of the Heidelberg Catechism of 1563.","Frederick V\u0027s acceptance of the Bohemian crown in 1619 began its ruin; in 1803 its last lands were divided among Baden and others."],dyk:"Much of Heidelberg\u0027s great library, the Bibliotheca Palatina, was sent to Rome in 1623 as a gift to the pope after the city fell, and it remains in the Vatican Library.",ev:[["1214","Emperor Frederick II grants the Palatinate to the Wittelsbach Louis I of Bavaria"],["1356","The Golden Bull confirms the count palatine as an imperial elector"],["1386","Rupert I founds the University of Heidelberg"],["1400","Elector Rupert III is elected King of the Romans"],["1563","Frederick III issues the Heidelberg Catechism"],["1619","Frederick V accepts the crown of Bohemia"],["1689","French troops burn Heidelberg and Mannheim in the Nine Years\u0027 War"],["1803","The Imperial Recess divides the remaining lands among Baden and others"]]},
  "Republic of Genoa": {t:["A Ligurian port that became one of the great medieval sea powers, with colonies from Chios to Caffa in the Crimea.","It pioneered commercial contracts, marine insurance and the Bank of Saint George, which managed debt, taxes and colonies.","After 1528 an aristocratic republic allied to Spain, its bankers financed the Spanish Empire until c. 1627."],dyk:"The Bank of Saint George, a creditors’ bank founded in 1407, governed the island of Corsica on the republic’s behalf for over a century.",ev:[["1099","Genoese citizens form the compagna communis as their ships join the capture of Jerusalem"],["1261","Treaty of Nymphaeum with Byzantium opens the Black Sea to Genoese trade"],["1284","Oberto Doria destroys the Pisan fleet at the Battle of Meloria"],["1339","Simone Boccanegra is elected the first doge of Genoa"],["1381","The Peace of Turin ends the War of Chioggia with Venice"],["1407","The Bank of Saint George is founded to manage the public debt"],["1528","Andrea Doria allies Genoa with Charles V and reforms its constitution"],["1797","The republic is replaced by the French-backed Ligurian Republic"]]},
  "Republic of Florence": {t:["A Tuscan commune that grew rich on wool cloth and banking and ruled most of Tuscany by the fifteenth century.","Its gold florin, minted from 1252, became a standard coin of international trade across Europe.","From 1434 the Medici steered the republic informally, and it was the birthplace of the Renaissance."],dyk:"Florentine offices were filled by lot: names of eligible citizens were drawn from leather bags, and priors served for only two months.",ev:[["1115","Death of Matilda of Canossa; Florentine citizens take control of their city"],["1252","Florence mints the gold florin"],["1293","The Ordinances of Justice exclude the magnates from government"],["1348","The Black Death kills perhaps half the population"],["1406","Florence conquers Pisa after a long siege"],["1434","Cosimo de’ Medici returns from exile and leads the republic"],["1494","The Medici are expelled after the French invasion"],["1532","Alessandro de’ Medici becomes Duke and the republic ends"]]},
  "Duchy of Pomerania": {t:["A Baltic duchy on the lower Oder ruled by the Slavic Griffin dynasty from the 1120s until 1637.","Converted by Otto of Bamberg, it became an imperial fief and absorbed German settlers and Hanseatic towns.","When the last duke died in the Thirty Years’ War, Sweden and Brandenburg divided the duchy in 1648."],dyk:"A Griffin prince, Eric of Pomerania, became king of Denmark, Norway and Sweden in 1397, and later ended his days as a minor duke in Pomerania.",ev:[["c. 1121","Bolesław III of Poland conquers Pomerania; Wartislaw I becomes a Polish vassal"],["1124","Otto of Bamberg begins his mission to convert the Pomeranians"],["1181","Bogislaw I receives Pomerania as an imperial fief from Frederick Barbarossa"],["1295","The duchy is divided into Pomerania-Stettin and Pomerania-Wolgast"],["1478","Bogislaw X reunites all Pomerania"],["1534","A diet at Treptow adopts the Lutheran Reformation"],["1637","Bogislaw XIV dies, the last Griffin duke"],["1648","The Peace of Westphalia divides Pomerania between Sweden and Brandenburg"]]},
  "Kingdom of Sicily": {t:["Founded by Roger II in 1130, it joined Sicily and southern Italy in one of medieval Europe’s most centralised states.","Its Norman court mixed Latin, Greek and Arabic government and art, seen in Palermo, Cefalù and Monreale.","After the Vespers of 1282 it survived as an island kingdom under Aragon, Spain and others until 1816."],dyk:"From 1530 the Knights Hospitaller held Malta as a fief of the kingdom, paying the king of Sicily an annual tribute of a single falcon.",ev:[["1130","Roger II is crowned king of Sicily in Palermo"],["1154","Al-Idrisi completes his world geography, the Book of Roger"],["1194","Henry VI conquers the kingdom, bringing the Hohenstaufen to the throne"],["1231","Frederick II issues the Constitutions of Melfi"],["1266","Charles of Anjou defeats Manfred at Benevento"],["1282","The Sicilian Vespers drive the Angevins from the island"],["1713","The Treaty of Utrecht gives Sicily to Victor Amadeus II of Savoy"],["1816","Sicily and Naples are merged into the Kingdom of the Two Sicilies"]]},
  "Novgorod Republic": {t:["A merchant city-state of the Russian north that elected its officials and archbishop and hired princes by contract.","It ruled a huge fur-producing hinterland to the White Sea and the Urals and traded with the Hanseatic League.","Ivan III of Moscow crushed its army in 1471, annexed it in 1478 and took away its veche bell."],dyk:"Archaeologists have found over a thousand birchbark letters in Novgorod, including a thirteenth-century boy Onfim’s school exercises and drawings.",ev:[["1136","Novgorodians expel Prince Vsevolod Mstislavich; the republic begins"],["1170","Novgorod repels the army of Andrey Bogolyubsky"],["1242","Alexander Nevsky defeats the Livonian knights on Lake Peipus"],["1323","Treaty of Nöteborg draws the first border with Sweden"],["1348","Treaty of Bolotovo recognises Pskov’s independence"],["1456","Treaty of Yazhelbitsy limits Novgorod’s independence"],["1471","Ivan III’s army defeats Novgorod at the Shelon River"],["1478","Novgorod surrenders to Ivan III; the veche bell is taken to Moscow"]]},
  "Kingdom of Portugal": {t:["A kingdom founded by Afonso Henriques in 1139 whose border with Castile, fixed in 1297, is among the oldest in Europe.","Its navigators reached India by sea in 1498 and Brazil in 1500, creating an empire of trading posts and colonies.","After union with Spain (1580–1640), loss of Brazil and civil war, the monarchy was overthrown by a revolution in 1910."],dyk:"Between 1808 and 1821 Rio de Janeiro was the seat of the Portuguese monarchy, the only time a European kingdom was ruled from one of its colonies.",ev:[["1139","Afonso Henriques begins to style himself king after the Battle of Ourique"],["1147","Afonso I takes Lisbon with the help of crusaders"],["1249","Afonso III completes the conquest of the Algarve"],["1385","John I defeats Castile at the Battle of Aljubarrota"],["1498","Vasco da Gama reaches Calicut in India by sea"],["1580","Philip II of Spain becomes king, beginning the Iberian Union"],["1640","A revolt restores independence under John IV of Braganza"],["1910","A revolution on 5 October ends the monarchy"]]},
  "Vladimir-Suzdal": {t:["The leading principality of north-eastern Rus’, ruled from Vladimir on the Klyazma after Andrei Bogolyubsky made it his capital in 1157.","Its white-stone churches and the icon of Our Lady of Vladimir became lasting symbols of Russian culture.","After the Mongol conquest of 1238 its grand-princely title was granted by the khans and finally passed to Moscow."],dyk:"The icon of Our Lady of Vladimir, painted in Constantinople in the early 12th century, was brought north by Andrei Bogolyubsky in 1155 and is now in Moscow’s Tretyakov Gallery.",ev:[["1157","Andrei Bogolyubsky becomes prince and makes Vladimir his capital"],["1169","Andrei’s army sacks Kiev"],["1174","Andrei Bogolyubsky is murdered at Bogolyubovo"],["1176–1212","Vsevolod the Big Nest rules as grand prince"],["1216","Battle of Lipitsa between Vsevolod’s sons"],["1238","The Mongols sack Vladimir and kill Yuri II on the Sit River"],["1252","Alexander Nevsky becomes grand prince"],["1331","Ivan I Kalita of Moscow becomes sole grand prince"]]},
  "Margraviate of Brandenburg": {t:["A frontier march east of the Elbe founded by Albert the Bear in 1157, whose ruler became one of the seven electors of the Empire.","From 1415 the Hohenzollerns ruled it, gaining Prussia in 1618 and building a standing army under the Great Elector.","In 1701 its elector became King in Prussia, and Brandenburg remained the Prussian heartland until the Empire ended in 1806."],dyk:"Brandenburg had an African colony: from 1683 its fort of Gross Friedrichsburg stood on the Gold Coast in today’s Ghana, until the Prussian king sold it to the Dutch in 1717.",ev:[["1157","Albert the Bear recaptures Brandenburg an der Havel and styles himself margrave"],["1356","The Golden Bull confirms the margrave as an elector of the Empire"],["1415","Frederick of Hohenzollern is granted the Mark and the electoral title"],["1539","Joachim II introduces the Lutheran Reformation"],["1618","The electors inherit the Duchy of Prussia"],["1675","The Great Elector defeats the Swedes at the Battle of Fehrbellin"],["1685","The Edict of Potsdam invites Huguenot refugees"],["1701","Elector Frederick III crowns himself King in Prussia"]]},
  "Principality of Catalonia": {t:["The Catalan counties united under the counts of Barcelona, who were also kings of Aragon from 1162.","Its Corts, Generalitat and merchant capital Barcelona made it one of the most commercial and parliamentary states of medieval Europe.","Revolts in 1640 and 1705 ended in defeat, and the Nueva Planta decree of 1716 abolished its institutions."],dyk:"The Taula de Canvi, founded by Barcelona’s city council in 1401, was one of the first public banks in Europe, holding deposits and handling the city’s finances.",ev:[["1162","Alfonso II inherits Barcelona and Aragon, uniting them in the Crown of Aragon"],["1258","Treaty of Corbeil: France renounces its claims over the Catalan counties"],["1283","Peter III promises to summon the Catalan Corts every year"],["1359","The Corts of Cervera create the Diputació del General, later the Generalitat"],["1462–1472","Civil war between the Generalitat and John II"],["1640","The Reapers’ War breaks out with the Corpus de Sang in Barcelona"],["1714","Barcelona falls to Philip V’s army on 11 September"],["1716","The Nueva Planta decree abolishes Catalonia’s institutions"]]},
  "Crown of Aragon": {t:["A federation of Aragon, Catalonia, Valencia and Majorca under one king, each realm keeping its own laws, Corts and coinage.","Its fleets won Sicily in 1282, Sardinia from 1323 and Naples in 1442, building an Iberian empire in the Mediterranean.","United with Castile from 1479, it kept its separate institutions until the Nueva Planta decrees of 1707–1716."],dyk:"James I the Conqueror left an account of his own reign, the Llibre dels fets, one of the earliest autobiographies by a medieval Christian king.",ev:[["1137","Petronila of Aragon is betrothed to Ramon Berenguer IV of Barcelona"],["1162","Alfonso II inherits Barcelona, adding Aragon in 1164"],["1229","James I begins the conquest of Majorca"],["1238","Valencia surrenders to James I"],["1282","Peter III takes Sicily after the Sicilian Vespers"],["1412","The Compromise of Caspe gives the throne to Ferdinand of Antequera"],["1442","Alfonso V the Magnanimous conquers Naples"],["1707","The Nueva Planta decrees abolish the laws of Aragon and Valencia"]]},
  "Margraviate of Moravia": {t:["A land of the Bohemian crown with its own estates, diet and law, ruled from Olomouc and later Brno from 1182 to 1918.","Its religious tolerance sheltered the Unity of the Brethren, who printed the Kralice Bible, and Anabaptist Hutterite communities.","After 1620 the Habsburgs curbed its estates; it ended as a crown land of Austria-Hungary and joined Czechoslovakia in 1918."],dyk:"The worldwide Moravian Church takes its name from Brethren refugees who left Moravia for Herrnhut in Saxony in 1722; its missionaries reached the Caribbean by 1732.",ev:[["1182","Frederick Barbarossa makes Conrad III Otto of Znojmo margrave of Moravia"],["1349","Charles IV grants Moravia to his brother John Henry, founding a Moravian Luxembourg line"],["1410","Margrave Jobst of Moravia is elected King of the Romans"],["1479","The Peace of Olomouc leaves Moravia to Matthias Corvinus of Hungary for his lifetime"],["1579","The Unity of the Brethren begins printing the Kralice Bible"],["1628","The Renewed Land Ordinance makes the crown hereditary and curbs the Moravian estates"],["1866","Gregor Mendel publishes his plant experiments made in Brno"],["1918","Moravia becomes a land of the new Czechoslovakia"]]},
  "Duchy of Brabant": {t:["A duchy of the Holy Roman Empire centred on Leuven, Brussels and Antwerp, among the most urbanised lands of medieval Europe.","Its Joyous Entry of 1356 bound every new duke to respect the estates\u0027 rights and was sworn by Burgundian and Habsburg rulers alike.","Antwerp made it Europe\u0027s commercial hub in the 1500s; the Dutch Revolt split it, and France annexed the rest in 1795."],dyk:"Duke John I of Brabant, victor at Worringen in 1288, was also a poet: love songs under his name survive in the famous Codex Manesse of German lyric poetry.",ev:[["1190","The Diet of Schwäbisch Hall confirms Henry I\u0027s ducal rank over Brabant"],["1288","John I wins the Battle of Worringen and gains the Duchy of Limburg"],["1356","Duchess Joanna and Wenceslaus swear the Joyous Entry charter"],["1430","Philip the Good of Burgundy inherits Brabant"],["1531","Antwerp opens its new commercial exchange"],["1585","Alexander Farnese captures Antwerp; the Dutch close the Scheldt"],["1648","The Peace of Münster confirms the split of Brabant between Spain and the Dutch Republic"],["1795","The French Republic annexes the duchy"]]},
  "Second Bulgarian Empire": {t:["A medieval Bulgarian state restored by the revolt of Peter and Asen in 1185 and ruled from the fortress of Tsarevets in Tarnovo.","Kaloyan destroyed the Latin crusaders at Adrianople in 1205, and Ivan Asen II dominated the Balkans after Klokotnitsa in 1230.","Its Tarnovo literary school shaped Orthodox Slavic culture before the Ottomans took Tarnovo in 1393 and Vidin in 1396."],dyk:"After his capture at Adrianople in 1205, the Latin emperor Baldwin I was held at Tarnovo; a tower of the Tsarevets fortress is still known as Baldwin\u0027s Tower.",ev:[["1185","Peter and Asen lead a revolt against Byzantine rule at Tarnovo"],["1205","Kaloyan destroys the Latin crusader army at Adrianople and captures Emperor Baldwin I"],["1230","Ivan Asen II defeats and captures Theodore of Epirus at Klokotnitsa"],["1235","The Bulgarian patriarchate is restored at Tarnovo"],["1242","Mongol invasion forces Bulgaria to pay tribute to the Golden Horde"],["1330","The Serbs defeat and kill Tsar Michael Shishman at Velbazhd"],["1393","The Ottomans capture Tarnovo after a three-month siege"],["1396","Vidin falls after the Battle of Nicopolis, ending the medieval Bulgarian state"]]},
  "Free Hanseatic City of Bremen": {t:["A Weser port that won self-government from its archbishops after Frederick Barbarossa\u0027s privilege of 1186.","A Hanseatic city and free imperial city, it resisted Swedish claims and survived the end of the Holy Roman Empire in 1806.","Through Bremerhaven it became a great emigration port, and it is now the smallest state of the Federal Republic of Germany."],dyk:"The Ratskeller wine cellar beneath Bremen\u0027s town hall, in use since the early fifteenth century, still keeps a cask of Rüdesheim wine from 1653.",ev:[["1186","Frederick Barbarossa\u0027s Gelnhausen Privilege confirms the citizens\u0027 rights"],["1404","The stone Roland statue is set up in the market square"],["1646","The Linz Diploma confirms Bremen as a free imperial city"],["1811","Napoleon annexes Bremen to France"],["1827","Johann Smidt founds Bremerhaven at the mouth of the Weser"],["1857","Norddeutscher Lloyd is founded in Bremen"],["1947","The Land of Bremen is re-established with Bremerhaven"],["1949","Bremen becomes a state of the Federal Republic of Germany"]]},
  "Free and Hanseatic City of Hamburg": {t:["A port on the Elbe that grew from the Carolingian Hammaburg and a twelfth-century merchant town into the Hanse\u0027s North Sea gateway.","Neutral behind its walls in the Thirty Years\u0027 War, it became the largest and richest city of northern Germany and a centre of music and theatre.","Annexed by Napoleon and wrecked in 1943, it survives as a city-state of the Federal Republic and Germany\u0027s largest port."],dyk:"Hamburg celebrates its port\u0027s birthday every May on the strength of a charter of Frederick Barbarossa dated 1189 that historians have shown to be a thirteenth-century forgery.",ev:[["1189","Date of the Barbarossa charter, later forged, that underpins the port\u0027s privileges"],["1241","Hamburg and Lübeck ally to protect the road between them"],["1529","Bugenhagen\u0027s church order brings the Lutheran Reformation"],["1558","The Hamburg Exchange is founded"],["1768","Denmark recognises Hamburg as a free imperial city in the Gottorp Settlement"],["1842","The Great Fire destroys about a quarter of the old town"],["1943","Operation Gomorrah\u0027s firestorm kills around 35,000 people"],["1949","Hamburg becomes a state of the Federal Republic of Germany"]]},
  "Kingdom of Bohemia": {t:["The only kingdom within the Holy Roman Empire, ruled from Prague, whose king was one of the electors of the King of the Romans.","Under Charles IV Prague became an imperial capital with Central Europe’s first university, founded in 1348.","Its Hussite reformation predated Luther by a century, and the Defenestration of Prague in 1618 began the Thirty Years War."],dyk:"The Teutonic Knights’ fortress of Königsberg, founded in 1255, is traditionally said to have been named in honour of King Ottokar II of Bohemia, who had joined their crusade.",ev:[["1212","The Golden Bull of Sicily makes the Bohemian royal title hereditary"],["1278","Ottokar II is defeated and killed at the Battle on the Marchfeld"],["1348","Charles IV founds the university of Prague and the New Town"],["1415","Jan Hus is burned at the Council of Constance, sparking the Hussite revolution"],["1434","Moderate forces defeat the radical Hussites at the Battle of Lipany"],["1526","The estates elect Ferdinand I, beginning Habsburg rule"],["1620","The Protestant estates are crushed at the Battle of White Mountain"],["1918","Czechoslovakia is proclaimed in Prague, with Bohemia at its core"]]},
  "Bailiwick of Jersey": {t:["The largest Channel Island, it stayed with the English crown when King John lost Normandy to France in 1204.","It keeps Norman customary law, its Royal Court and its own parliament, the States, as a Crown Dependency outside the UK.","Once a fortified frontier against France, it became a cod-trading, farming and later financial centre."],dyk:"New Jersey is named after the island: in 1664 the Duke of York granted the land to Sir George Carteret, a Jerseyman who had held the island for the Stuarts.",ev:[["1204","King John loses Normandy, but Jersey stays with the English crown"],["1461","The French take Mont Orgueil and hold Jersey until 1468"],["1481","Pope Sixtus IV grants the Channel Islands neutrality in wartime"],["1649","Charles II is proclaimed king in Saint Helier"],["1781","A French invasion is defeated at the Battle of Jersey"],["1940","German forces occupy the island"],["1945","Jersey is liberated on 9 May"],["2005","Ministerial government with a Chief Minister is introduced"]]},
  "County of Hohenzollern": {t:["A small county in the Swabian Jura, ruled from Zollern castle and Hechingen by the Swabian branch of the Zollern dynasty.","Its Franconian cousins became Burgraves of Nuremberg and later rulers of Brandenburg, Prussia and Germany.","The Catholic counts rose through Habsburg service, gaining Haigerloch and Sigmaringen before dividing the county in 1576."],dyk:"The present Hohenzollern Castle is the third on its hilltop: the medieval fortress was razed by the Swabian imperial cities in 1423, and its successor was rebuilt in the 1850s–1860s.",ev:[["1061","The counts of Zollern are first mentioned in a chronicle"],["c. 1218","The sons of Burgrave Frederick I divide the Franconian and Swabian lands"],["1403","The Schalksburg line sells its lands to Württemberg"],["1423","The Swabian imperial cities take and raze Zollern castle"],["1454","Rebuilding of Zollern castle begins under Jos Niklas I"],["1497","Eitel Friedrich II acquires the lordship of Haigerloch"],["1534","Charles I receives Sigmaringen and Veringen as Austrian fiefs"],["1576","The county is divided into Hechingen, Sigmaringen and Haigerloch"]]},
  "Principality of Achaea": {t:["Founded in 1205 by French crusaders, it was the most durable Latin state created in Greece after the Fourth Crusade.","A model feudal society of twelve baronies, its customs were codified in the Assizes of Romania.","Defeat at Pelagonia in 1259 cost it Mistras, the base from which Byzantium reconquered the Peloponnese by 1432."],dyk:"The Venetian writer Marino Sanudo Torsello reported that at the princes’ court in the Peloponnese French was spoken as well as in Paris.",ev:[["1205","Crusaders defeat the Greeks at the Olive Grove of Koundouros"],["1209","Geoffrey I is recognised as a vassal of the Latin emperor at Ravennika"],["1248","William II takes Monemvasia, completing the conquest of the Peloponnese"],["1259","William II is captured at the Battle of Pelagonia"],["1262","Mistras, Monemvasia and Grand Magne are ceded to Byzantium"],["1267","The Treaty of Viterbo places Achaea under Charles of Anjou"],["1316","Ferdinand of Majorca is killed at the Battle of Manolada"],["1432","Thomas Palaiologos annexes the last of the principality"]]},
  "Canton of Zürich": {t:["An imperial city from 1218, Zürich was ruled by guilds after Rudolf Brun’s revolution of 1336 and joined the Confederacy in 1351.","Its citizens governed a large rural territory through bailiffs, and the city led the Confederacy as its Vorort.","Under Zwingli and Bullinger it became a fountainhead of Reformed Protestantism with influence across Europe."],dyk:"The Zürich Bible, printed by Christoph Froschauer, was completed in 1531, three years before Martin Luther’s complete German Bible appeared.",ev:[["1218","The Zähringen line dies out and Zürich becomes an imperial city"],["1336","Rudolf Brun overthrows the old council and introduces guild rule"],["1351","Zürich joins the Old Swiss Confederacy"],["1443","Zürich is defeated at St. Jakob an der Sihl in the Old Zürich War"],["1489","Burgomaster Hans Waldmann is overthrown and executed"],["1519","Huldrych Zwingli begins preaching at the Grossmünster"],["1531","Zwingli is killed at the Battle of Kappel"],["1798","The French invasion ends the old regime; Zürich joins the Helvetic Republic"]]},
  "State of the Teutonic Order": {t:["A crusading state ruled by the celibate knights of the Teutonic Order, who conquered the pagan Prussians between 1230 and about 1283.","From Marienburg the Grand Masters ran a castle-based administration and profited from Hanseatic grain and an amber monopoly.","Defeat at Grunwald in 1410 and the loss of West Prussia in 1466 broke it; in 1525 it became the Lutheran Duchy of Prussia."],dyk:"The Order held a monopoly on Baltic amber, selling much of the raw amber to rosary makers in Lübeck and Bruges.",ev:[["1226","Golden Bull of Rimini grants Prussian conquests to Grand Master Hermann von Salza"],["1237","The Order absorbs the Livonian Brothers of the Sword"],["1260","The Great Prussian Uprising begins, lasting until 1274"],["1309","The Grand Master moves his seat from Venice to Marienburg"],["1410","A Polish-Lithuanian army crushes the knights at the Battle of Grunwald"],["1466","The Second Peace of Thorn cedes Royal Prussia to Poland"],["1525","Albert of Brandenburg-Ansbach secularises the state as the Duchy of Prussia"]]},
  "Crown of Castile": {t:["Formed in 1230 when Ferdinand III united Castile and León, it took Córdoba and Seville and left Granada as the last Muslim state.","Merino wool marketed by the Mesta, the Cortes and Alfonso X\u0027s Siete Partidas shaped its economy and law.","Under Isabella I it took Granada and sponsored Columbus, and its laws and language spread across the Spanish Americas."],dyk:"The Alfonsine Tables, astronomical tables compiled at the court of Alfonso X in Toledo, remained a standard reference for European astronomers until the sixteenth century.",ev:[["1230","Ferdinand III inherits León, uniting it permanently with Castile"],["1248","Seville surrenders to Ferdinand III after a siege of more than a year"],["1340","Alfonso XI defeats the Marinids and Granada at the Battle of Río Salado"],["1369","Henry of Trastámara kills Peter I at Montiel and founds a new dynasty"],["1492","Granada falls, the Jews are expelled and Columbus sails for the Indies"],["1521","The Comuneros are defeated at the Battle of Villalar"],["1707","The Nueva Planta decrees begin imposing Castilian institutions on Aragon"]]},
  "Emirate of Granada": {t:["Founded in 1232 by Muhammad I ibn al-Ahmar, it survived as a tributary of Castile while the rest of al-Andalus fell.","Silk, sugar and dried fruit exported through Málaga and Almería, often by Genoese merchants, sustained a crowded mountain realm.","Civil wars and the Castilian war of 1482–1492 ended it when Boabdil surrendered Granada on 2 January 1492."],dyk:"The walls of the Alhambra are inscribed with poems by the court poet Ibn Zamrak, some of which speak in the voice of the building itself.",ev:[["1232","Ibn al-Ahmar proclaims himself ruler at Arjona"],["1246","Muhammad I cedes Jaén and becomes a vassal of Ferdinand III of Castile"],["1340","Castile defeats the Marinids and Yusuf I at the Battle of Río Salado"],["1362","Muhammad V regains his throne and later builds the Court of the Lions"],["1410","Castile takes Antequera after a long siege"],["1487","Málaga falls after a long siege and its people are enslaved"],["1492","Boabdil surrenders Granada to Isabella I and Ferdinand II on 2 January"]]},
  "Grand Duchy of Lithuania": {t:["Pagan Lithuanian dukes, united after their victory at Saule in 1236, built one of the largest states of medieval Europe.","Ruled by the Gediminid dynasty, it absorbed much of Rus\u0027 and used Ruthenian as its chancery language.","Joined to Poland from 1386 and in the Commonwealth from 1569, it was partitioned, mostly to Russia, by 1795."],dyk:"Lithuania was the last pagan state in Europe: its official conversion to Catholicism began only in 1387, and that of Samogitia not until 1413.",ev:[["1236","Lithuanians destroy the Livonian Brothers of the Sword at the Battle of Saule"],["1253","Mindaugas is crowned king of Lithuania"],["1323","Gediminas invites Western settlers in letters naming Vilnius as his seat"],["c. 1362","Algirdas defeats the Golden Horde at the Battle of Blue Waters"],["1387","Jogaila begins the conversion of Lithuania to Catholicism"],["1410","Vytautas and the Poles defeat the Teutonic Order at the Battle of Grunwald"],["1569","The Union of Lublin creates the Polish-Lithuanian Commonwealth"],["1795","The Third Partition gives almost all remaining lands to the Russian Empire"]]},
  "Reval": {t:["A German-speaking merchant town under Lübeck law, granted self-government by King Eric IV of Denmark in 1248.","It prospered as a Hanseatic link between Novgorod and Lübeck, governed by a council drawn from the Great Guild.","Ruled by Denmark and from 1346 by the Teutonic Order, it submitted to Sweden in 1561 during the Livonian War."],dyk:"Reval\u0027s Brotherhood of the Blackheads, an association of unmarried merchants, took its name from its patron Saint Maurice, shown as a Moor on its coat of arms.",ev:[["1219","Valdemar II defeats the Estonians at Lindanise and builds a castle on Toompea"],["1248","Eric IV of Denmark grants the town Lübeck law"],["1343","Estonian rebels besiege Reval in the St George\u0027s Night Uprising"],["1346","Denmark sells northern Estonia, with Reval, to the Teutonic Order"],["1404","The Gothic town hall is completed"],["1524","Iconoclastic riots mark the Lutheran Reformation in Reval"],["1561","Reval submits to Eric XIV of Sweden during the Livonian War"]]},
  "Grand Duchy of Moscow": {t:["A small appanage on the Moskva River that rose under Alexander Nevsky\u0027s descendants to unite north-eastern Russia.","Its princes grew rich and powerful as tribute collectors for the Golden Horde, then ended Tatar overlordship in 1480.","Ivan III annexed Novgorod and Tver and rebuilt the Kremlin; in 1547 Ivan IV was crowned tsar and Muscovy became Russia."],dyk:"Ivan I\u0027s nickname Kalita means \u0027money bag\u0027 or \u0027purse\u0027, probably a reference to the wealth he amassed or to his reputed alms-giving.",ev:[["1263","Daniel, son of Alexander Nevsky, receives Moscow as his principality"],["1331","Ivan I Kalita becomes sole grand prince of Vladimir"],["1380","Dmitry Donskoy defeats Mamai at the Battle of Kulikovo"],["1382","Khan Tokhtamysh takes and burns Moscow"],["1478","Ivan III annexes the Novgorod Republic"],["1480","The Great Stand on the Ugra River ends Tatar overlordship"],["1497","Ivan III issues the Sudebnik law code"],["1547","Ivan IV is crowned tsar, founding the Tsardom of Russia"]]},
  "Andorra": {t:["A small Pyrenean state created in 1278 when the bishop of Urgell and the count of Foix agreed to share its lordship.","For centuries a poor community of herders and smugglers, it kept its autonomy by staying neutral between France and Spain.","A constitution in 1993 made it a sovereign parliamentary co-principality; it joined the United Nations the same year."],dyk:"Andorra is the only country where Catalan is the sole official language, and one of its two heads of state is the bishop of a Spanish diocese.",ev:[["1278","The first Pareatge establishes joint lordship by the bishop of Urgell and the count of Foix"],["1419","The Consell de la Terra, forerunner of the Consell General, is created"],["1607","Henry IV joins the Foix co-princedom to the French crown"],["1806","Napoleon restores the French co-princedom abandoned in 1793"],["1866","The Nova Reforma widens the electorate to all heads of household"],["1970","Andorran women gain the vote"],["1993","A new constitution is approved by referendum and Andorra joins the United Nations"]]},
  "Kingdom of Naples": {t:["The mainland half of the old Kingdom of Sicily, ruled separately from Naples after the Sicilian Vespers of 1282.","Angevin, Aragonese, Spanish and Bourbon rulers made Naples one of Europe\u0027s largest cities and a centre of art and learning.","Its feudal baronage and heavy taxes fuelled revolts; in 1816 it merged with Sicily into the Kingdom of the Two Sicilies."],dyk:"Though ruled from Naples, the kingdom officially kept the name Kingdom of Sicily while the island had kings of its own, which is why their union in 1816 was called the Two Sicilies.",ev:[["1282","The Sicilian Vespers leave Charles of Anjou with only the mainland"],["1309","Robert the Wise begins a reign that makes Naples a cultural centre"],["1442","Alfonso V of Aragon conquers Naples"],["1495","Charles VIII of France enters Naples, opening the Italian Wars"],["1504","The Treaty of Lyon ends the war, leaving Naples to Ferdinand II of Aragon"],["1647","The revolt of Masaniello shakes Spanish rule"],["1734","Charles of Bourbon restores an independent kingdom"],["1816","Naples and Sicily are united as the Kingdom of the Two Sicilies"]]},
  "Old Swiss Confederacy": {t:["A defensive pact of three Alpine valleys in 1291 grew into a league of thirteen cantons by 1513.","Swiss pikemen defeated Habsburg and Burgundian armies and served as Europe\u0027s most sought-after mercenaries.","Without a central government, it relied on a consensus Diet; French invasion in 1798 replaced it with the Helvetic Republic."],dyk:"The Federal Charter of 1291 became the official founding document only in the 1890s, when 1 August was chosen as the Swiss national day.",ev:[["1291","Uri, Schwyz and Unterwalden conclude the Federal Charter"],["1315","The Confederates defeat a Habsburg army at the Battle of Morgarten"],["1386","Duke Leopold III of Austria is killed at the Battle of Sempach"],["1476","Charles the Bold of Burgundy is defeated at Grandson and Murten"],["1515","Defeat by Francis I at Marignano ends Swiss great-power ambitions"],["1531","Zwingli is killed in the Second Kappel War"],["1648","The Peace of Westphalia recognises Swiss independence from the Empire"],["1798","French invasion ends the Confederacy; the Helvetic Republic is proclaimed"]]},
  "Kingdom of Hungary (1301-1526)": {t:["The Angevin Charles I rebuilt royal power after the Árpád line died out in 1301, ruling from Visegrád and later Buda.","Gold from its mines made Hungary Europe\u0027s leading producer of precious metals and its florin a standard coin.","Matthias Corvinus made it a Renaissance power, but magnate rule followed and the Ottomans crushed it at Mohács in 1526."],dyk:"The Bibliotheca Corviniana of Matthias Corvinus was one of the largest libraries of Renaissance Europe; over two hundred of its volumes survive in collections across the world.",ev:[["1301","Andrew III dies, ending the Árpád dynasty"],["1310","Charles I is crowned with the Holy Crown at Székesfehérvár"],["1370","Louis I also becomes king of Poland"],["1396","Sigismund\u0027s crusade is destroyed at the Battle of Nicopolis"],["1456","John Hunyadi breaks the Ottoman siege of Belgrade"],["1485","Matthias Corvinus captures Vienna"],["1514","The peasant revolt of György Dózsa is crushed"],["1526","Suleiman the Magnificent defeats the Hungarians at Mohács; Louis II dies"]]},
  "Kingdom of Sardinia": {t:["Founded by Aragon’s conquest of Pisan Sardinia in 1323–1324, it spent seven decades fighting the native Judicate of Arborea.","In 1720 the island and its royal title passed to the House of Savoy, which ruled the kingdom from Turin with Piedmont, Savoy and Nice.","Under Victor Emmanuel II and Cavour it led Italian unification and in 1861 became the Kingdom of Italy."],dyk:"The Carta de Logu, issued by Eleonora of Arborea in the late fourteenth century, remained in force as Sardinian law until 1827, long after Arborea itself had vanished.",ev:[["1297","Pope Boniface VIII grants the Kingdom of Sardinia and Corsica to James II of Aragon"],["1324","Pisa cedes its Sardinian lands after the Aragonese victory at Lucocisterna"],["1409","Martin the Younger defeats the Judicate of Arborea at the Battle of Sanluri"],["1720","Victor Amadeus II of Savoy exchanges Sicily for Sardinia and its royal title"],["1799","The Savoyard court flees French-occupied Turin for Cagliari"],["1848","Charles Albert grants the Statuto Albertino and goes to war with Austria"],["1859","Victory at Magenta and Solferino wins Lombardy"],["1861","Victor Emmanuel II is proclaimed King of Italy in Turin"]]},
  "Principality of Moldavia": {t:["A Romanian principality founded in the mid-14th century between the Carpathians and the Dniester, independent of Hungary from about 1359.","Stephen the Great defeated the Ottomans at Vaslui in 1475, but Moldavia became an Ottoman tributary and was ruled by Phanariots 1711–1821.","It lost Bukovina to Austria and Bessarabia to Russia, and in 1859 united with Wallachia to form Romania."],dyk:"The Ottomans called Moldavia Kara Boğdan, “Black Bogdania”, after its founding prince Bogdan I, and the name survived in Turkish for centuries.",ev:[["c. 1359","Bogdan I makes Moldavia independent of Hungary"],["1401","Constantinople recognises a Moldavian Orthodox metropolis"],["1475","Stephen the Great defeats the Ottomans at the Battle of Vaslui"],["1484","Bayezid II captures the Black Sea ports of Chilia and Cetatea Albă"],["1711","Cantemir’s alliance with Peter the Great fails on the Pruth; Phanariot rule begins"],["1775","Austria annexes Bukovina"],["1812","Russia annexes Bessarabia by the Treaty of Bucharest"],["1859","Moldavia and Wallachia both elect Alexandru Ioan Cuza as prince"]]},
  "Hanseatic League": {t:["A league of mainly German merchant towns, led by Lübeck, that dominated Baltic and North Sea trade from the 14th to the 16th century.","It had no constitution, army or treasury; diets coordinated policy, and four great Kontore traded at Novgorod, Bergen, Bruges and London.","Strong territorial states, Dutch competition and the shift of trade to the Atlantic eroded it; the last diet met in 1669."],dyk:"In 1473 the Danzig privateer Paul Beneke captured a ship carrying Hans Memling’s Last Judgment triptych; the altarpiece was taken to Danzig and is still in Gdańsk today.",ev:[["1159","Henry the Lion refounds Lübeck, the future head of the Hansa"],["1356","The first general Hanseatic diet meets in Lübeck"],["1370","The Peace of Stralsund ends the war with Valdemar IV of Denmark"],["1474","The Treaty of Utrecht confirms Hanseatic privileges in England"],["1494","Ivan III closes the Hanseatic office at Novgorod"],["1598","Elizabeth I revokes the privileges of the London Steelyard"],["1669","The last Hanseatic diet meets in Lübeck"]]},
  "Electorate of Saxony": {t:["A prince-electorate of the Holy Roman Empire on the Elbe, ruled from 1423 by the Wettin dynasty from Wittenberg and later Dresden.","Frederick the Wise protected Martin Luther, making Saxony the cradle of the Lutheran Reformation.","Under Augustus the Strong, King of Poland from 1697, Dresden became a Baroque capital and Meissen made Europe’s first hard-paste porcelain."],dyk:"Saxony’s Erzgebirge silver was struck from about 1500 into some of the first large silver coins of the type later called the thaler, the name that lives on in the word dollar.",ev:[["1356","The Golden Bull confirms the Duke of Saxe-Wittenberg as a prince-elector"],["1423","Emperor Sigismund grants the electorate to Frederick the Warlike of Meissen"],["1485","The Division of Leipzig splits the Wettin lands between Ernest and Albert"],["1517","Martin Luther publishes his theses at Wittenberg"],["1547","Charles V wins at Mühlberg; the electorate passes to Maurice"],["1697","Augustus the Strong is elected King of Poland"],["1756","Frederick the Great invades; the Saxon army capitulates at Pirna"],["1806","Frederick Augustus III becomes King of Saxony"]]},
  "Republic of Ragusa": {t:["An aristocratic merchant republic centred on Dubrovnik, independent in practice from 1358 to 1808.","It traded Balkan silver and lead and had one of the largest merchant fleets in the Mediterranean in the 16th century.","It kept its freedom by paying tribute to the Ottomans, staying neutral and governing itself through noble councils."],dyk:"The Rector of Ragusa served for just one month and could not leave his palace during that time except on official business, so that no one could gain personal power.",ev:[["1272","The city statute codifies Ragusan law"],["1358","The Treaty of Zadar ends Venetian rule; Ragusa becomes a self-governing republic"],["1377","Ragusa introduces quarantine regulations for travellers from infected areas"],["1416","The Great Council bans the slave trade"],["1458","Ragusa begins paying tribute to the Ottoman Empire"],["1667","A great earthquake destroys much of the city"],["1699","The Treaty of Karlowitz creates Ottoman corridors separating Ragusa from Venice"],["1808","Marshal Marmont abolishes the republic"]]},
  "Duchy of Milan": {t:["An imperial duchy created in 1395 for Gian Galeazzo Visconti, who briefly controlled much of northern and central Italy.","Under the Sforza it was one of Renaissance Europe’s richest courts, where Leonardo da Vinci painted the Last Supper.","Fought over in the Italian Wars, it was ruled by Spain from 1535 and Austria from 1706 until Napoleon ended it in 1796–1797."],dyk:"Gian Galeazzo Visconti did not inherit his ducal title: he bought it in 1395 from Wenceslas, King of the Romans, for a sum reported as 100,000 florins.",ev:[["1395","Gian Galeazzo Visconti buys the ducal title from Wenceslas"],["1402","Gian Galeazzo dies of plague as his armies encircle Florence"],["1447","Death of Filippo Maria Visconti; the Golden Ambrosian Republic is proclaimed"],["1450","Francesco Sforza enters Milan as duke"],["c. 1495","Leonardo da Vinci begins the Last Supper in Santa Maria delle Grazie"],["1499","Louis XII of France conquers the duchy"],["1535","Death of Francesco II Sforza; the duchy passes to Charles V"],["1796","Napoleon enters Milan; the Transpadane Republic replaces the duchy"]]},
  "Duchy of Savoy": {t:["Emperor Sigismund made Savoy a duchy in 1416, joining French-speaking Alpine lands with Italian-speaking Piedmont.","Restored in 1559 after French occupation, it moved its capital to Turin and became a disciplined absolutist military state.","Its dukes became kings of Sicily and then Sardinia, and their kingdom later united Italy; Savoy itself passed to France in 1860."],dyk:"Amadeus VIII, the first Duke of Savoy, retired to a lakeside priory and was then elected antipope as Felix V by the Council of Basel in 1439.",ev:[["1416","Emperor Sigismund raises Amadeus VIII to the rank of duke"],["1439","Amadeus VIII is elected antipope Felix V by the Council of Basel"],["1536","France occupies Savoy and Piedmont; Bern takes the Vaud"],["1559","Treaty of Cateau-Cambrésis restores Emmanuel Philibert"],["1563","The capital moves from Chambéry to Turin"],["1706","Victor Amadeus II and Prince Eugene relieve the Siege of Turin"],["1720","The dukes of Savoy become kings of Sardinia"],["1847","The ‘perfect fusion’ merges the mainland states with Sardinia"]]},
  "Crimean Khanate": {t:["A successor state of the Golden Horde founded c. 1441 by Haci I Giray, a descendant of Genghis Khan.","From 1475 an Ottoman vassal and ally, its cavalry raids on Poland-Lithuania and Muscovy fed the slave market of Caffa.","Russian victories made it a nominally independent protectorate in 1774, and Catherine II annexed it in 1783."],dyk:"Muscovy kept paying the Crimean khans regular ‘gifts’, in effect tribute, until the Treaty of Constantinople in 1700, long after the Golden Horde had vanished.",ev:[["c. 1441","Haci I Giray establishes an independent khanate in the Crimea"],["1475","Ottomans conquer Caffa; Mengli I Giray later accepts Ottoman suzerainty"],["1502","Mengli Giray destroys the Great Horde"],["1571","Devlet I Giray burns Moscow"],["1648","Islam III Giray allies with Bohdan Khmelnytsky against Poland-Lithuania"],["1736","A Russian army under Münnich burns Bakhchysarai"],["1774","Treaty of Kuchuk Kainarji ends Ottoman suzerainty"],["1783","Catherine II annexes the Crimea to the Russian Empire"]]},
  "Habsburg Spain": {t:["Charles I inherited Castile and Aragon in 1516 and became Emperor Charles V in 1519, uniting vast lands in Europe and the Americas.","American silver, the tercios and a council-based government made it Europe’s leading power, especially under Philip II.","War, debt and revolts brought decline after 1640; the childless Charles II’s death in 1700 passed the throne to the Bourbons."],dyk:"Philip II governed his empire largely on paper, reading and annotating thousands of reports in his own hand from his study, and built the Escorial as palace, monastery and royal tomb.",ev:[["1516","Charles I inherits the crowns of Castile and Aragon"],["1519","Charles is elected Holy Roman Emperor; Cortés begins the conquest of Mexico"],["1556","Charles V abdicates; Philip II becomes king"],["1571","The Holy League defeats the Ottoman fleet at Lepanto"],["1580","Philip II becomes king of Portugal"],["1588","The Spanish Armada fails against England"],["1640","Catalonia and Portugal revolt"],["1700","Charles II dies, leaving the throne to Philip of Anjou"]]},
  "Denmark-Norway": {t:["After Sweden left the Kalmar Union in 1523, Denmark and Norway stayed under one Oldenburg king for nearly three centuries.","A Lutheran state funded by the Sound Toll, it became an absolute monarchy in 1660 under the written King’s Law of 1665.","It lost Scania to Sweden in 1658, and defeat as Napoleon’s ally forced it to cede Norway to Sweden in 1814."],dyk:"In 1792 Denmark-Norway became the first European state to ban the transatlantic slave trade by law, though the ban only took effect in 1803.",ev:[["1523","Sweden leaves the Kalmar Union; Frederick I becomes king"],["1536","Christian III introduces the Lutheran Reformation"],["1613","Treaty of Knäred ends the Kalmar War in Denmark-Norway’s favour"],["1658","Treaty of Roskilde cedes Scania and other provinces to Sweden"],["1660","Frederick III establishes hereditary absolute monarchy"],["1721","Hans Egede begins the Danish recolonisation of Greenland"],["1807","Britain bombards Copenhagen and seizes the Danish fleet"],["1814","Treaty of Kiel cedes Norway to Sweden"]]},
  "Habsburg Monarchy": {t:["A union of Austria, Bohemia and Hungary formed in 1526 and held together by the Habsburg dynasty, army and Catholic Church.","It stopped Ottoman expansion at Vienna in 1529 and 1683 and reconquered Hungary by the Treaty of Karlowitz in 1699.","Maria Theresa and Joseph II made it a model of enlightened absolutism before it became the Austrian Empire in 1804."],dyk:"The thaler, struck from the silver of Joachimsthal in Bohemia, gave its name to the dollar.",ev:[["1526","Louis II dies at Mohács; Ferdinand of Austria is elected king of Bohemia and Hungary"],["1529","First Ottoman siege of Vienna is repulsed"],["1620","Bohemian revolt crushed at the Battle of White Mountain"],["1683","Second Ottoman siege of Vienna broken at the Battle of Kahlenberg"],["1699","Treaty of Karlowitz returns almost all of Hungary to Habsburg rule"],["1713","Charles VI issues the Pragmatic Sanction, making the lands indivisible"],["1781","Joseph II issues the Patent of Toleration and abolishes personal serfdom"],["1804","Francis II proclaims himself hereditary Emperor of Austria"]]},
  "Kingdom of Ireland": {t:["Created by Henry VIII in 1542 to replace the Lordship of Ireland, with its own parliament but the English monarch as king.","Tudor and Stuart wars and plantations transferred most land to Protestant settlers, and the Penal Laws excluded Catholics from power.","After winning legislative independence in 1782 and the 1798 rebellion, it was merged into the United Kingdom from 1801."],dyk:"Handel’s Messiah had its first performance not in London but in Dublin, at the Great Music Hall on Fishamble Street in April 1742.",ev:[["1542","Henry VIII’s title of King of Ireland takes effect under the Crown of Ireland Act"],["1601","English victory at the Battle of Kinsale over Irish and Spanish forces"],["1609","The Plantation of Ulster begins"],["1649","Oliver Cromwell storms Drogheda and Wexford"],["1690","William III defeats James II at the Battle of the Boyne"],["1695","First of the Penal Laws restricting Catholics is enacted"],["1782","Irish Parliament gains legislative independence"],["1798","The United Irishmen rebellion is crushed"]]},
  "Duchy of Parma and Piacenza": {t:["Created in 1545 by Pope Paul III for his son Pier Luigi Farnese, from territory taken from the Papal States.","Its duke Alessandro Farnese was Spain’s leading general in the Netherlands, and the Farnese were major patrons of art.","Later ruled by the Bourbon-Parma line and Napoleon’s widow Marie Louise, it joined Italy in 1859–1860."],dyk:"The wooden Teatro Farnese, built in 1618 inside the Pilotta palace, staged its first spectacle only in 1628 and was used for just a few court festivities before falling out of use.",ev:[["1545","Pope Paul III creates the duchy for his son Pier Luigi Farnese"],["1547","Pier Luigi Farnese is murdered in Piacenza"],["1585","Alessandro Farnese captures Antwerp for Spain"],["1618","The Teatro Farnese is built in the Pilotta palace"],["1731","The Farnese line dies out; Charles of Bourbon inherits"],["1748","Treaty of Aix-la-Chapelle founds the Bourbon-Parma line"],["1814","Marie Louise, Napoleon’s wife, receives the duchy"],["1860","A plebiscite approves annexation to the Kingdom of Sardinia"]]},
  "Tsardom of Russia": {t:["Founded when Ivan IV was crowned the first Tsar of All Russia in Moscow in January 1547.","It conquered the Volga khanates, crossed Siberia to the Pacific and took Kyiv and left-bank Ukraine in 1667.","Peter the Great’s reforms and victory over Sweden turned it into the Russian Empire in 1721."],dyk:"Russian explorers reached the Pacific at the Sea of Okhotsk in 1639, less than sixty years after Yermak’s cossacks first crossed the Urals into Siberia.",ev:[["1547","Ivan IV is crowned Tsar of All Russia"],["1552","Russian forces capture Kazan"],["1565","Ivan IV creates the oprichnina"],["1613","Michael Romanov is elected tsar, ending the Time of Troubles"],["1649","The Sobornoe Ulozhenie law code completes the enserfment of the peasantry"],["1667","Truce of Andrusovo gives Russia Kyiv and left-bank Ukraine"],["1709","Peter I defeats Charles XII of Sweden at the Battle of Poltava"],["1721","Treaty of Nystad; Peter I takes the title of emperor"]]},
  "Grand Duchy of Tuscany": {t:["Created in 1569 when Pope Pius V made Cosimo I de’ Medici Grand Duke of Tuscany after his conquest of Siena.","Medici Tuscany sheltered Galileo, saw the birth of opera and made Livorno a cosmopolitan free port.","Under the Habsburg-Lorraine grand duke Peter Leopold it abolished torture and the death penalty in 1786."],dyk:"Galileo named the four moons of Jupiter he discovered in 1610 the Medicean Stars, in honour of Grand Duke Cosimo II and his brothers.",ev:[["1555","Siena surrenders to Cosimo I de’ Medici"],["1569","Pope Pius V makes Cosimo I Grand Duke of Tuscany"],["1593","The Livornine laws open Livorno to Jews and foreign merchants"],["1610","Galileo becomes court mathematician to Cosimo II"],["1737","The Medici line dies out; Francis Stephen of Lorraine succeeds"],["1786","Peter Leopold’s code abolishes torture and the death penalty"],["1801","The grand duchy becomes the Kingdom of Etruria"],["1860","A plebiscite approves annexation to the Kingdom of Sardinia"]]},
  "Dutch Republic": {t:["A federation of seven sovereign provinces, formed in the revolt against Philip II of Spain and governed from The Hague.","Its Baltic trade, East India Company and Amsterdam bank made it Europe’s leading commercial power in the 17th century.","Rembrandt, Vermeer, Spinoza and Grotius worked there; wars and British rivalry wore it down until France conquered it in 1795."],dyk:"In 1628 Piet Heyn of the Dutch West India Company captured an entire Spanish silver fleet off Matanzas in Cuba, a haul that paid the company’s shareholders a large dividend.",ev:[["1579","The northern provinces form the Union of Utrecht"],["1581","The Act of Abjuration renounces Philip II of Spain"],["1602","The Dutch East India Company (VOC) is founded"],["1609","The Twelve Years’ Truce with Spain begins; the Bank of Amsterdam opens"],["1648","Spain recognises Dutch independence in the Peace of Münster"],["1672","Disaster Year: France and England invade and the de Witt brothers are lynched"],["1688","Stadtholder William III invades England and becomes its king"],["1795","French armies overrun the Republic and the Batavian Republic is proclaimed"]]},
  "Kingdom of Prussia": {t:["A Hohenzollern kingdom proclaimed at Königsberg in 1701, built from scattered lands between the Rhine and the Baltic.","Its army and disciplined bureaucracy made a poor, small state a European great power under Frederick II.","Under Bismarck it defeated Denmark, Austria and France and in 1871 united Germany under its king."],dyk:"Prussia’s first king was only ‘King in Prussia’, because part of Prussia still belonged to Poland; Frederick II took the title ‘King of Prussia’ after the partition of 1772.",ev:[["1701","Elector Frederick III crowns himself Frederick I, King in Prussia, at Königsberg"],["1740","Frederick II invades the Habsburg province of Silesia"],["1763","The Peace of Hubertusburg ends the Seven Years’ War; Prussia keeps Silesia"],["1772","The First Partition of Poland gives Prussia West Prussia"],["1806","Napoleon defeats Prussia at Jena and Auerstedt"],["1815","The Congress of Vienna grants Prussia the Rhineland and Westphalia"],["1866","Prussia defeats Austria at Königgrätz"],["1871","William I is proclaimed German Emperor at Versailles"]]},
  "Kingdom of Great Britain": {t:["Created on 1 May 1707 by the union of England and Scotland, with one Parliament at Westminster but separate Scottish law and church.","Naval power, public credit and trade made it the leading colonial power after the Seven Years’ War ended in 1763.","It lost the American colonies in 1783 but began the Industrial Revolution, and it merged with Ireland on 1 January 1801."],dyk:"Scotland’s acceptance of the union was eased by the ‘Equivalent’, a payment of about £398,000 that partly compensated investors in the failed Darien colony in Panama.",ev:[["1707","The Acts of Union join England and Scotland as Great Britain"],["1714","George I becomes the first Hanoverian king"],["1746","The Jacobite army is defeated at the Battle of Culloden"],["1759","Quebec falls after the Battle of the Plains of Abraham"],["1763","The Treaty of Paris gives Britain Canada and Florida"],["1776","The thirteen American colonies declare independence"],["1783","The Treaty of Paris recognises the independence of the United States"],["1800","The Acts of Union with Ireland create the United Kingdom from 1 January 1801"]]},
  "Principality of Liechtenstein": {t:["A principality created in 1719 when the Liechtenstein family united Vaduz and Schellenberg to gain a seat in the Imperial Diet.","It outlived the Holy Roman Empire and the German Confederation, abolished its army in 1868 and tied itself to Switzerland in 1923.","A microstate of about 40,000 people, it combines strong princely powers with direct democracy and very high incomes."],dyk:"The country is named after its ruling family, not the other way round: the Liechtensteins took their name from a castle south of Vienna, far from Vaduz.",ev:[["1699","Prince Johann Adam Andreas buys the Lordship of Schellenberg"],["1712","The same prince buys the County of Vaduz"],["1719","Emperor Charles VI creates the Principality of Liechtenstein"],["1806","Liechtenstein joins the Confederation of the Rhine and becomes sovereign"],["1868","Prince Johann II abolishes the army"],["1921","A new constitution shares power between prince and people"],["1923","Customs union treaty with Switzerland"],["1990","Liechtenstein joins the United Nations"]]},
  "United Kingdom of Great Britain and Ireland": {t:["Formed on 1 January 1801 by the union of Great Britain and Ireland, with a single Parliament at Westminster.","The first industrial nation, it led world trade and finance and ruled the largest empire in history.","Irish grievances, deepened by the Great Famine, led to the Easter Rising, a war of independence and the Irish Free State in 1922."],dyk:"Ireland’s population fell from about 8.2 million in 1841 to about 4.4 million in 1911 through famine deaths and emigration, while Great Britain’s more than doubled.",ev:[["1801","The union of Great Britain and Ireland takes effect on 1 January"],["1805","Nelson defeats the French and Spanish fleets at Trafalgar"],["1815","Wellington and Blücher defeat Napoleon at Waterloo"],["1832","The Great Reform Act widens the franchise"],["1845","The Great Famine begins in Ireland"],["1851","The Great Exhibition opens at the Crystal Palace in London"],["1916","The Easter Rising in Dublin"],["1922","The Irish Free State is established; Northern Ireland stays in the UK"]]},
  "Swiss Confederation": {t:["A federal republic of twenty-six cantons, created by Napoleon in 1803 and turned into a federal state by the constitution of 1848.","Its permanent neutrality, recognised in 1815, kept it out of every European war since and made Geneva a centre of diplomacy.","Referendums and popular initiatives give its citizens an unusually direct say in law-making at federal and cantonal level."],dyk:"Swiss men voted on whether women should have the federal vote: they refused in 1959 and agreed only in 1971, and Appenzell Innerrhoden had to be ordered by the Federal Supreme Court to admit women in 1990.",ev:[["1803","Napoleon\u0027s Act of Mediation creates a confederation of nineteen cantons"],["1815","The great powers recognise Switzerland\u0027s perpetual neutrality"],["1847","Federal troops under General Dufour win the Sonderbund War"],["1848","The Federal Constitution creates a federal state with Bern as federal city"],["1863","The International Committee of the Red Cross is founded in Geneva"],["1874","Constitutional revision introduces the optional referendum on federal laws"],["1971","Women gain the right to vote in federal elections"],["2002","Switzerland joins the United Nations after a popular vote"]]},
  "Austrian Empire": {t:["Francis II created the hereditary Austrian imperial title in 1804, two years before he dissolved the Holy Roman Empire.","Under Metternich, Vienna led the conservative European order after 1815 and dominated both Germany and Italy.","Defeats in 1859 and 1866 ended Austrian power in Italy and Germany and led to the Compromise with Hungary in 1867."],dyk:"Gregor Mendel, an Augustinian friar, presented his pea-plant experiments on heredity in Brünn, Moravia, in 1865; they were largely ignored until they were rediscovered in 1900.",ev:[["1804","Francis II proclaims himself hereditary Emperor of Austria"],["1806","Francis dissolves the Holy Roman Empire"],["1809","Archduke Charles defeats Napoleon at Aspern-Essling before defeat at Wagram"],["1814–1815","The Congress of Vienna redraws Europe under Metternich\u0027s guidance"],["1848","Revolutions drive Metternich into exile; Franz Joseph succeeds Ferdinand I"],["1849","Hungarian forces surrender at Világos after Russian intervention"],["1866","Prussia defeats Austria at the Battle of Königgrätz"],["1867","The Compromise with Hungary creates Austria-Hungary"]]},
  "Kingdom of Württemberg": {t:["Napoleon\u0027s ally Frederick I proclaimed the kingdom in 1806 and roughly doubled the old duchy\u0027s territory.","The constitution of 1819, agreed with the estates, made Württemberg a leading constitutional state of southern Germany.","Within the German Empire it kept its own army corps, posts and railways until the king renounced the throne in 1918."],dyk:"The Cannstatter Wasen, one of Germany\u0027s largest folk festivals, began in 1818 as an agricultural fair founded by King William I after the famine of 1816–1817.",ev:[["1806","Elector Frederick proclaims himself King Frederick I of Württemberg"],["1813","The Treaty of Fulda brings Württemberg over to the Allies"],["1819","William I agrees a constitution with the estates"],["1834","Württemberg joins the German Customs Union"],["1866","Württemberg troops are defeated by Prussia at Tauberbischofsheim"],["1871","Württemberg becomes a federal state of the German Empire"],["1886","Robert Bosch opens his workshop in Stuttgart"],["1918","King William II renounces the throne on 30 November"]]},
  "Grand Duchy of Hesse": {t:["Napoleon\u0027s ally Louis X became Grand Duke Louis I in 1806 and later exchanged Westphalia for Rhenish Hesse with Mainz.","Its constitution of 1820 joined Lutheran Starkenburg and Upper Hesse with Catholic, French-law Rhenish Hesse.","Defeated with Austria in 1866, it joined the German Empire in 1871 and ended with the deposition of Ernest Louis in 1918."],dyk:"After 1866 the grand duchy was split: its province of Upper Hesse had to join the North German Confederation, while Starkenburg and Rhenish Hesse stayed outside until 1871.",ev:[["1806","Landgrave Louis X joins the Confederation of the Rhine as Grand Duke Louis I"],["1816","Hesse exchanges Westphalia for Rhenish Hesse with Mainz and Worms"],["1820","Louis I issues a constitution with a two-chamber parliament"],["1834","Georg Büchner and Friedrich Ludwig Weidig distribute Der Hessische Landbote"],["1866","Hesse is defeated with Austria and loses Hesse-Homburg to Prussia"],["1871","The grand duchy becomes a member state of the German Empire"],["1899","Ernest Louis founds the Darmstadt Artists\u0027 Colony"],["1918","Ernest Louis is declared deposed on 9 November"]]},
  "Kingdom of Bavaria": {t:["Napoleon\u0027s alliance turned the Electorate of Bavaria into a kingdom in 1806, the second largest German state.","Montgelas built a centralised, tolerant administration, and the constitution of 1818 created one of Germany\u0027s first parliaments.","Ludwig I and Ludwig II made Munich and the Bavarian Alps famous for art, architecture and fantasy castles."],dyk:"The Oktoberfest began in October 1810 as a public celebration of the wedding of Crown Prince Ludwig, the future Ludwig I, to Princess Therese of Saxe-Hildburghausen.",ev:[["1806","Maximilian IV Joseph is proclaimed King Maximilian I Joseph of Bavaria"],["1813","The Treaty of Ried brings Bavaria over to the Allies"],["1818","The constitution of 26 May creates a two-chamber parliament"],["1835","Germany\u0027s first railway opens between Nuremberg and Fürth"],["1848","Ludwig I abdicates after the Lola Montez affair and revolution"],["1871","Bavaria joins the German Empire with extensive reserved rights"],["1886","Ludwig II is declared unfit to rule and dies in Lake Starnberg"],["1918","Kurt Eisner proclaims a republic in Munich and Ludwig III flees"]]},
  "Grand Duchy of Luxembourg": {t:["Created by the Congress of Vienna in 1815 and ruled by the Dutch kings until 1890, it lost its western half to Belgium in 1839.","Iron ore and steel, then banking and investment funds, made a poor farming country one of the richest in the world per head.","Occupied by Germany in both world wars, it abandoned neutrality and became a founding member and seat of European institutions."],dyk:"The Schengen Agreement that abolished border checks across much of Europe is named after a small wine-growing village in Luxembourg, where it was signed on a boat on the Moselle in 1985.",ev:[["1815","The Congress of Vienna creates the grand duchy under William I of the Netherlands"],["1839","The Treaty of London gives the western, French-speaking half to Belgium"],["1867","The Treaty of London declares Luxembourg neutral and orders its fortress demolished"],["1890","Adolphe of Nassau-Weilburg becomes grand duke, ending the union with the Netherlands"],["1940","Germany invades; Grand Duchess Charlotte and the government go into exile"],["1952","The High Authority of the European Coal and Steel Community settles in Luxembourg"],["1985","The Schengen Agreement is signed at the village of Schengen"]]},
  "German Confederation": {t:["A league of 39 sovereign German states and free cities created at the Congress of Vienna, with a Diet in Frankfurt under Austrian presidency.","Under Metternich it repressed liberal and national movements through the Carlsbad Decrees of 1819 and later measures.","Rivalry between Austria and Prussia paralysed it, and the Austro-Prussian War of 1866 ended it and opened the way to a Prussian-led Germany."],dyk:"The black, red and gold flag of modern Germany was first adopted officially in 1848 by the Federal Diet of the German Confederation, the body nationalists regarded as the symbol of reaction.",ev:[["1815","The Federal Act creates the German Confederation at the Congress of Vienna"],["1819","The Carlsbad Decrees impose censorship and university supervision"],["1834","The Prussian-led Zollverein customs union comes into force, excluding Austria"],["1848","The Frankfurt Parliament meets in St Paul’s Church"],["1850","Prussia gives up its Erfurt Union in the Punctation of Olmütz"],["1864","Austria and Prussia defeat Denmark in the Second Schleswig War"],["1866","Prussia defeats Austria at Königgrätz; the Peace of Prague ends the Confederation"]]},
  "Kingdom of Belgium": {t:["Born of the 1830 revolution against the United Kingdom of the Netherlands, it was recognised as neutral by the great powers in 1839.","It was continental Europe’s first industrial nation and, through Leopold II, the ruler of the Congo, where forced labour cost countless lives.","Conflict between Dutch and French speakers turned it into a federal state in 1993, while Brussels became home to the EU and NATO."],dyk:"Belgium’s line from Brussels to Mechelen, opened in May 1835, was the first steam passenger railway in continental Europe, built and run by the state itself.",ev:[["1830","Revolution in Brussels; a provisional government declares independence"],["1831","Leopold I takes the oath as first King of the Belgians"],["1839","The Treaty of London recognises Belgium and guarantees its neutrality"],["1885","The powers recognise Leopold II’s Congo Free State"],["1914","Germany invades; the Belgian army holds the Yser front until 1918"],["1960","The Belgian Congo becomes independent"],["1993","A constitutional reform makes Belgium a federal state"]]},
  "Kingdom of Greece": {t:["Created by Britain, France and Russia in 1832 with Otto of Bavaria as king, it was the first nation state carved from the Ottoman Empire.","Pursuing the Great Idea of uniting all Greeks, it more than doubled its territory before defeat in Asia Minor in 1922.","Abolished in 1924, restored in 1935, it lived through occupation, civil war and a military junta that ended the monarchy in 1973."],dyk:"King Alexander of Greece died in October 1920 of an infection from a bite by a pet monkey; his death led to the return of his father Constantine I and changed the course of the war in Asia Minor.",ev:[["1833","Otto of Bavaria lands at Nauplia as first King of Greece"],["1864","Britain cedes the Ionian Islands as George I begins his reign"],["1912–13","The Balkan Wars bring Thessaloniki, Macedonia, Epirus and Crete into Greece"],["1922","Defeat in Asia Minor; Smyrna burns and over a million refugees flee"],["1924","The monarchy is abolished; it is restored by plebiscite in 1935"],["1940","Greece rejects Italy’s ultimatum and drives the invaders into Albania"],["1967","The colonels’ coup; Constantine II goes into exile after a failed counter-coup"],["1973","The junta abolishes the monarchy"]]},
  "Kingdom of the Netherlands": {t:["Took its present form in 1839, when William I accepted Belgian independence; the 1848 constitution established parliamentary government.","Its wealth long rested on the Dutch East Indies, exploited under the cultivation system and lost when Indonesia won independence in 1949.","Occupied by Germany in 1940–45, it became a founding member of NATO and the European Communities and a centre of international law."],dyk:"Since 2010 the Kingdom of the Netherlands has consisted of four countries, the Netherlands, Aruba, Curaçao and Sint Maarten, while Bonaire, Sint Eustatius and Saba are special Dutch municipalities.",ev:[["1839","William I recognises Belgian independence in the Treaty of London"],["1848","Thorbecke’s constitutional revision introduces ministerial responsibility"],["1860","Multatuli’s Max Havelaar attacks colonial exploitation in Java"],["1917","The Pacification brings universal male suffrage and equal funding for schools"],["1940","Germany invades; Rotterdam is bombed and the army capitulates within five days"],["1949","Sovereignty over Indonesia is transferred to the new Indonesian state"],["1953","The North Sea flood kills 1,836 people and leads to the Delta Works"],["1992","The Treaty of Maastricht creating the European Union is signed"]]},
  "Kingdom of Italy": {t:["A constitutional monarchy of the House of Savoy that united Italy between 1859 and 1870 and made Rome its capital in 1871.","Under Mussolini, appointed in 1922, it became the first Fascist dictatorship and built a colonial empire in Africa.","Defeat in the Second World War discredited the monarchy, and a referendum in 1946 replaced it with a republic."],dyk:"Italian troops entered Rome in 1870 through a breach in the walls at Porta Pia, and the popes then lived as self-declared prisoners in the Vatican until the Lateran Treaty of 1929.",ev:[["1861","Parliament in Turin proclaims Victor Emmanuel II king of Italy"],["1870","Italian troops take Rome from the Papal States"],["1896","Ethiopian forces defeat the Italian army at the Battle of Adwa"],["1915","Italy enters the First World War on the side of the Entente"],["1922","The March on Rome brings Benito Mussolini to power"],["1929","The Lateran Treaty creates the Vatican City State"],["1943","The king dismisses Mussolini and Italy signs an armistice with the Allies"],["1946","A referendum abolishes the monarchy and creates the Italian Republic"]]},
  "Russian SFSR": {t:["Created by the Bolsheviks in the October Revolution of 1917, it was the world’s first state committed to building socialism.","It won the Civil War and in 1922 co-founded the Soviet Union, holding about three-quarters of its territory.","In 1990–1991 it declared sovereignty, elected Boris Yeltsin president and became the Russian Federation."],dyk:"The largest Soviet republic was the only one without its own Communist Party until 1990: Moscow feared that a Russian party would become a rival centre of power to the Union party.",ev:[["1917","The Bolsheviks seize power in Petrograd in the October Revolution"],["1918","The capital moves to Moscow and the first Soviet constitution is adopted"],["1920","The Red Army defeats Wrangel’s last White army in Crimea"],["1922","The RSFSR co-founds the Soviet Union"],["1941","Germany invades; Leningrad is besieged and Moscow threatened"],["1990","The RSFSR declares state sovereignty on 12 June"],["1991","Boris Yeltsin is elected president and resists the August coup"],["1991","The republic is renamed the Russian Federation on 25 December"]]},
  "Republic of Finland": {t:["Finland declared independence from Russia on 6 December 1917 and became a republic with the constitution of 1919.","It fought the Soviet Union in the Winter War and the Continuation War, losing Karelia but keeping its independence.","A Cold War neutral, it joined the European Union in 1995, adopted the euro in 1999 and joined NATO in 2023."],dyk:"The parliamentary reform of 1906 made Finland the first country in Europe where women could both vote and stand for parliament; nineteen women were elected in 1907.",ev:[["1917","Parliament declares independence from Russia on 6 December"],["1918","The Whites under Mannerheim win the Finnish Civil War"],["1919","A new constitution makes Finland a republic, with K. J. Ståhlberg as president"],["1939","The Soviet Union attacks, starting the Winter War"],["1944","The Continuation War ends with an armistice and the loss of Karelia"],["1975","The Helsinki Final Act is signed at the Conference on Security and Co-operation in Europe"],["1995","Finland joins the European Union"],["2023","Finland joins NATO on 4 April"]]},
  "Republic of Lithuania": {t:["Lithuania declared independence on 16 February 1918 and, having lost Vilnius to Poland, made Kaunas its interwar capital.","Occupied and annexed by the Soviet Union in 1940, it was the first Soviet republic to declare independence, in 1990.","Restored Lithuania joined NATO and the European Union in 2004 and the eurozone in 2015."],dyk:"Lithuania won the European basketball championships of 1937 and 1939, beginning a national passion for the sport; the 1939 tournament was held in a new hall built in Kaunas.",ev:[["1918","The Council of Lithuania signs the Act of Independence on 16 February"],["1920","Polish forces seize Vilnius; Kaunas becomes the temporary capital"],["1923","Lithuania takes over the Klaipėda Region"],["1926","A military coup restores Antanas Smetona to power"],["1940","The Soviet Union occupies and annexes Lithuania"],["1990","The Supreme Council declares the restoration of independence on 11 March"],["1991","Soviet troops kill fourteen civilians at the Vilnius television tower"],["2004","Lithuania joins NATO and the European Union"]]},
  "Kingdom of Yugoslavia": {t:["Proclaimed on 1 December 1918 as the Kingdom of Serbs, Croats and Slovenes, it united Serbia, Montenegro and former Habsburg lands.","Conflict between Serbian centralism and Croatian autonomy led to the royal dictatorship of 1929 and the name Yugoslavia.","The Axis invasion of April 1941 destroyed the kingdom in eleven days and partitioned it among its enemies."],dyk:"King Alexander’s assassination in Marseille in 1934 was filmed by newsreel cameramen, making it one of the first political assassinations recorded on film.",ev:[["1917","The Corfu Declaration agrees on a South Slav kingdom under the Karađorđević dynasty"],["1918","The Kingdom of Serbs, Croats and Slovenes is proclaimed in Belgrade"],["1921","The centralist Vidovdan Constitution is adopted"],["1928","Stjepan Radić is shot in parliament and dies weeks later"],["1929","King Alexander imposes a dictatorship and renames the country Yugoslavia"],["1934","King Alexander is assassinated in Marseille"],["1939","The Cvetković-Maček Agreement creates the Banovina of Croatia"],["1941","Germany and its allies invade and the army surrenders on 17 April"]]},
  "Czechoslovakia": {t:["A state of Czechs and Slovaks created from the ruins of Austria-Hungary in 1918, with Prague as its capital.","Its interwar democracy was the only one in Central Europe to last until the Munich Agreement of 1938 dismembered it.","After 1948 it was a communist state of the Soviet bloc; the Velvet Revolution of 1989 led to its peaceful division in 1992."],dyk:"The British Bren light machine gun was developed from the Czechoslovak ZB vz. 26; its name joins Brno, where it was designed, and Enfield, where it was made.",ev:[["1918","Independence proclaimed in Prague on 28 October; Masaryk becomes president"],["1938","The Munich Agreement forces the cession of the Sudetenland to Germany"],["1939","Germany occupies Bohemia and Moravia; Slovakia becomes a separate state"],["1948","The Communist Party seizes full power in February"],["1968","Warsaw Pact armies invade to end the Prague Spring"],["1977","Dissidents publish the Charter 77 declaration"],["1989","The Velvet Revolution ends communist rule; Václav Havel becomes president"],["1992","The federation is dissolved peacefully on 31 December"]]},
  "Republic of Estonia": {t:["Estonia declared independence in 1918 and won it in the War of Independence, confirmed by the Treaty of Tartu in 1920.","Occupied by the Soviet Union in 1940, it was restored in 1991 as the legal continuation of the pre-war republic.","Since 2004 it has been a member of the EU and NATO, known worldwide for e-government and internet voting."],dyk:"In 2007 Estonia became the first country to allow online voting nationwide in a parliamentary election, using its national electronic ID card.",ev:[["1918","The Salvation Committee declares the Republic of Estonia on 24 February"],["1920","The Treaty of Tartu ends the War of Independence"],["1934","Konstantin Päts declares a state of emergency and rules by decree"],["1940","The Soviet Union occupies and annexes Estonia"],["1989","The Baltic Way human chain links Tallinn, Riga and Vilnius"],["1991","Independence is restored on 20 August"],["2004","Estonia joins NATO and the European Union"],["2011","Estonia adopts the euro"]]},
  "Republic of Latvia": {t:["Latvia was proclaimed in Riga on 18 November 1918 and won its independence in a war against several enemies.","The Soviet Union occupied and annexed it in 1940, and Nazi Germany occupied it from 1941 to 1944.","Independence was restored in 1990–1991; Latvia joined the EU and NATO in 2004 and the eurozone in 2014."],dyk:"The Minox, a famous miniature spy camera, was first made in 1938 at the state-owned VEF electrical works in Riga.",ev:[["1918","The People\u0027s Council proclaims the Republic of Latvia on 18 November"],["1920","A peace treaty with Soviet Russia recognises Latvian independence"],["1922","The Satversme is adopted; Jānis Čakste becomes president"],["1934","Kārlis Ulmanis suspends parliament and rules as an authoritarian leader"],["1940","The Soviet Union occupies and annexes Latvia"],["1990","The Supreme Council declares the restoration of independence on 4 May"],["1991","Full independence is restored on 21 August"],["2004","Latvia joins NATO and the European Union"]]},
  "United Kingdom": {t:["The UK took its present form in 1922, when the Irish Free State left and Northern Ireland stayed in the union.","It fought both world wars to victory, standing alone against Nazi Germany in 1940, but emerged exhausted and in debt.","After 1945 it built a welfare state, gave up its empire, joined and then left the European Union."],dyk:"The country\u0027s full name changed only in 1927: from 1922 to 1927 it was still officially the United Kingdom of Great Britain and Ireland.",ev:[["1922","The Irish Free State leaves; Northern Ireland remains in the United Kingdom"],["1940","Dunkirk evacuation and the Battle of Britain; Churchill becomes Prime Minister"],["1948","The National Health Service is founded"],["1956","The Suez Crisis exposes the limits of British power"],["1973","The UK joins the European Economic Community"],["1997","Hong Kong is handed over to China"],["1998","The Good Friday Agreement is signed in Belfast"],["2020","The UK leaves the European Union on 31 January"]]},
  "Soviet Union": {t:["Founded in 1922, the USSR was the first communist state, ruled by the Communist Party from Moscow.","It industrialised rapidly under Stalin at enormous human cost, then bore the heaviest losses in defeating Nazi Germany.","As a Cold War superpower it rivalled the United States until Gorbachev\u0027s reforms led to its peaceful dissolution in 1991."],dyk:"The 1924 and later Soviet constitutions formally gave every union republic the right to secede, a provision that only became real in 1990–1991.",ev:[["1922","Four Soviet republics form the Union of Soviet Socialist Republics"],["1928","Stalin launches the First Five-Year Plan"],["1941","Germany invades the Soviet Union on 22 June"],["1945","The Red Army captures Berlin"],["1957","Sputnik 1, the first artificial satellite, is launched"],["1961","Yuri Gagarin becomes the first person in space"],["1985","Mikhail Gorbachev becomes General Secretary"],["1991","The Soviet Union is dissolved on 26 December"]]},
  "Nazi Germany": {t:["A totalitarian dictatorship under Adolf Hitler that replaced the Weimar Republic within months of January 1933.","It rearmed, annexed Austria and the Sudetenland, and launched the Second World War by invading Poland in 1939.","It murdered some six million Jews in the Holocaust and was destroyed by total military defeat in May 1945."],dyk:"Hitler never formally abolished the Weimar constitution: the Enabling Act of 1933 was renewed by the Reichstag in 1937 and 1939 and extended by decree in 1943.",ev:[["1933","Hitler is appointed chancellor; the Enabling Act lets his cabinet make laws without parliament"],["1934","On Hindenburg’s death Hitler merges the offices of president and chancellor as Führer"],["1935","The Nuremberg Laws strip German Jews of citizenship"],["1938","Germany annexes Austria and, after the Munich Agreement, the Sudetenland"],["1939","Germany invades Poland on 1 September, starting the Second World War in Europe"],["1941","Operation Barbarossa: Germany invades the Soviet Union"],["1943","The Sixth Army surrenders at Stalingrad"],["1945","Hitler kills himself on 30 April; Germany surrenders unconditionally on 8 May"]]},
  "Uruk": {t:["Uruk in southern Iraq grew into the largest city in the world in the fourth millennium BCE.","Administrators in its Eanna temple precinct produced proto-cuneiform, among the earliest known writing, around 3300 BCE.","It was the city of Gilgamesh and the capital of Lugal-zage-si before falling to Akkad, Ur and finally Larsa."],dyk:"The Warka Vase and the Mask of Warka, two of Uruk’s greatest treasures, were looted from the Iraq Museum in Baghdad in 2003 and both were later recovered.",ev:[["c. 3300 BCE","Administrators in Eanna begin recording goods on clay tablets: the beginning of writing"],["c. 3100 BCE","Uruk outposts in Syria and Iran are abandoned"],["c. 2900 BCE","A city wall about 9 km long encloses Uruk"],["c. 2700 BCE","Approximate date of Gilgamesh, the city’s legendary king"],["c. 2350 BCE","Lugal-zage-si makes Uruk the capital of a united Sumer"],["c. 2119 BCE","Utu-hengal of Uruk defeats the Gutian king Tirigan"],["c. 1865 BCE","Sin-kashid founds Uruk’s last independent dynasty"],["c. 1802 BCE","Rim-Sin of Larsa conquers Uruk"]]},
  "Ebla": {t:["Ebla, at Tell Mardikh near Aleppo, was the capital of a Bronze Age kingdom in northern Syria.","Its palace archive of about 17,000 tablets and fragments records a Semitic-speaking state of the 24th century BCE.","Destroyed around 2300 and again around 2000 BCE, it revived under Amorite kings until the Hittites destroyed it c. 1600 BCE."],dyk:"The fire that destroyed Ebla’s palace around 2300 BCE baked its clay tablets hard, preserving one of the largest archives of the third millennium BCE.",ev:[["c. 2400 BCE","Mari’s kings press Ebla, which pays large amounts of silver and gold"],["c. 2340 BCE","Ebla, allied with Nagar and Kish, defeats Mari"],["c. 2300 BCE","Palace G burns, probably at the hands of Akkad or Mari"],["c. 2000 BCE","The second Ebla is destroyed; Amorites later rebuild the city"],["c. 1800 BCE","Ebla becomes a vassal of Yamhad, centred on Aleppo"],["c. 1600 BCE","A Hittite king destroys Ebla"],["1968","A statue of King Ibbit-Lim identifies Tell Mardikh as Ebla"],["1974–1975","Italian excavators find the Palace G archive"]]},
  "Mari": {t:["Mari, at Tell Hariri in eastern Syria, controlled river traffic on the middle Euphrates for over a thousand years.","In the 24th century BCE it rivalled Ebla; in the 18th century it was ruled by the Amorite kings of the Lim dynasty.","Hammurabi of Babylon conquered it c. 1761 BCE, but its archive of some 20,000 tablets survived in the ruins."],dyk:"Zimri-Lim boasted of building an ice house at Terqa, a feat he said no earlier king had achieved, to keep ice for cooling drinks at court.",ev:[["c. 2900 BCE","Mari is founded at Tell Hariri on the middle Euphrates"],["c. 2400 BCE","Mari’s kings press Ebla, which pays them silver and gold"],["c. 2300 BCE","The second city of Mari is destroyed, probably by Akkad"],["c. 1810 BCE","Yahdun-Lim leads an expedition to the Mediterranean"],["c. 1796 BCE","Shamshi-Adad takes Mari and installs his son Yasmah-Addu"],["c. 1775 BCE","Zimri-Lim regains the throne with the help of Yamhad"],["c. 1761 BCE","Hammurabi of Babylon conquers Mari; its walls are destroyed two years later"],["1933","Bedouin find a statue on Tell Hariri, leading to French excavations"]]},
  "Byblos": {t:["Byblos, on the coast of Lebanon, is one of the oldest continuously inhabited towns in the world.","For over two thousand years it shipped cedar and resin to Egypt, absorbing Egyptian culture and religion.","Its royal inscriptions are among the earliest in the Phoenician alphabet, ancestor of the Greek and Latin scripts."],dyk:"The Greeks called papyrus byblos after the city through which they obtained it, and from that word came biblion, book, and ultimately the word Bible.",ev:[["c. 2600 BCE","Byblos ships cedar and resin to the pharaohs of the Old Kingdom"],["c. 1850 BCE","Local rulers receive gifts from the pharaohs Amenemhat III and IV"],["c. 1350 BCE","King Rib-Hadda writes dozens of Amarna letters begging Egypt for help"],["c. 1075 BCE","The Egyptian envoy Wenamun bargains with King Zakar-Baal for cedar"],["c. 1000 BCE","The sarcophagus of King Ahiram is inscribed in the Phoenician alphabet"],["c. 870 BCE","Byblos pays tribute to Ashurnasirpal II of Assyria"],["539 BCE","Byblos passes under the Achaemenid Empire"],["332 BCE","Byblos submits to Alexander the Great and its king joins the siege of Tyre"]]},
  "Dilmun": {t:["A Bronze Age merchant state centred on Bahrain, linking Mesopotamia with the copper of Magan and the luxuries of the Indus.","Its springs, harbour, stamp seals and weight standard made it the clearing house of Gulf trade around 2000–1750 BCE.","Later ruled by Kassite governors and then a tributary of Assyria and Babylon, it vanished as a polity in the 6th century BCE."],dyk:"Sumerian myth described Dilmun as a pure land without sickness or old age, where the gods settled the flood hero Ziusudra and gave him eternal life.",ev:[["c. 2500 BCE","Ur-Nanshe of Lagash records ships of Dilmun bringing him timber"],["c. 2050 BCE","Qal’at al-Bahrain becomes a walled town; temples rise at Barbar"],["c. 1750 BCE","Gulf trade contracts as the Indus cities decline and Babylon rises"],["c. 1450 BCE","Kassite Babylonia installs a governor on Bahrain"],["709 BCE","King Uperi of Dilmun sends gifts to Sargon II of Assyria"],["538 BCE","Dilmun passes with Babylonia to the Achaemenid Empire"],["1953","Danish expedition under P.V. Glob and Geoffrey Bibby begins excavations"]]},
  "Kingdom of Ugarit": {t:["A Late Bronze Age port-kingdom at Ras Shamra on the Syrian coast, trading with Egypt, Cyprus, the Aegean and Mesopotamia.","Its scribes used a 30-sign cuneiform alphabet and recorded the Baal cycle and the epics of Kirta and Aqhat.","A vassal of Egypt and then the Hittites, it was destroyed by seaborne raiders c. 1185 BCE and never rebuilt."],dyk:"Many of Ugarit’s clay tablets survived because the fire that destroyed the city baked them hard; some of its last letters report enemy ships off the coast.",ev:[["c. 1765 BCE","King Zimri-Lim of Mari visits Ugarit"],["c. 1350 BCE","Niqmaddu II becomes a vassal of the Hittite king Suppiluliuma I"],["1274 BCE","Ugaritic troops fight for the Hittites at the Battle of Kadesh"],["c. 1250 BCE","Ugarit reaches the height of its prosperity under Ammishtamru II"],["c. 1185 BCE","The city is sacked and burned, probably by seaborne raiders"],["1928","A farmer’s discovery of a tomb at Minet el-Beida leads to excavations"],["1929","Claude Schaeffer begins excavating Ras Shamra"]]},
  "Kingdom of Lydia": {t:["A western Anatolian kingdom ruled from Sardis, which under the Mermnad dynasty dominated Asia Minor west of the Halys.","Lydia struck the world’s earliest known coins from electrum carried by the river Pactolus.","Croesus, famed for his wealth, attacked Persia and lost his kingdom to Cyrus the Great around 546 BCE."],dyk:"The war between Lydia and Media reportedly ended when a solar eclipse darkened a battle in 585 BCE, which Greek tradition said Thales of Miletus had predicted.",ev:[["c. 680 BCE","Gyges kills Candaules and founds the Mermnad dynasty"],["c. 644 BCE","Gyges dies fighting the Cimmerians, who later sack Sardis"],["late 7th c. BCE","The first electrum coins are struck in Lydia"],["c. 600 BCE","Alyattes drives out the Cimmerians and captures Smyrna"],["585 BCE","An eclipse ends the war with Media; the Halys becomes the frontier"],["c. 560 BCE","Croesus becomes king and subdues the Greek cities of Ionia"],["c. 546 BCE","Cyrus the Great takes Sardis; Lydia becomes a Persian satrapy"]]},
  "United Kingdom of Israel": {t:["The kingdom of Saul, David and Solomon, known chiefly from the Hebrew Bible, with its scale debated by historians and archaeologists.","David made Jerusalem the capital and Solomon built its temple, making the city a political and religious centre.","Its memory as a golden age shaped Jewish, Christian and Islamic ideas of kingship and messianic hope."],dyk:"The earliest reference to the “House of David” outside the Bible appears on the Tel Dan stele, an Aramaic inscription found in northern Israel in 1993.",ev:[["c. 1047 BCE","Saul is anointed king by Samuel (traditional chronology)"],["c. 1010 BCE","Saul is killed by the Philistines at the Battle of Mount Gilboa"],["c. 1000 BCE","David captures Jerusalem and makes it his capital"],["c. 970 BCE","Solomon succeeds David after a struggle with his brother Adonijah"],["c. 957 BCE","The Temple of Jerusalem is completed, according to the Bible"],["c. 930 BCE","The northern tribes reject Rehoboam and the kingdom splits in two"]]},
  "Kingdom of Judah": {t:["The southern kingdom of the Israelites, ruled from Jerusalem by kings of the House of David for about 340 years.","It survived as a vassal of Assyria, Egypt and Babylon, resisting Sennacherib’s invasion of 701 BCE.","Nebuchadnezzar II destroyed Jerusalem and its temple in 587 BCE; the exile shaped Judaism and the Hebrew Bible."],dyk:"The Siloam tunnel under Jerusalem, over 500 metres long, was dug from both ends; an inscription records the moment the two teams of diggers met.",ev:[["c. 930 BCE","The kingdom of Solomon splits; Rehoboam keeps Judah and Jerusalem"],["c. 734 BCE","Ahaz becomes a vassal of Tiglath-pileser III of Assyria"],["701 BCE","Sennacherib invades Judah, takes Lachish and besieges Jerusalem"],["622 BCE","Josiah’s religious reform centralises worship in Jerusalem"],["609 BCE","Josiah is killed at Megiddo confronting the pharaoh Necho II"],["597 BCE","Nebuchadnezzar II captures Jerusalem and deports Jehoiachin"],["587 BCE","Jerusalem and the temple are destroyed; the elite are exiled to Babylon"]]},
  "Kingdom of Israel": {t:["The northern Hebrew kingdom, formed when the tribes broke from Solomon’s heir c. 930 BCE, ruled from Samaria after Omri.","Larger and richer than Judah, it fielded 2,000 chariots against Assyria at Qarqar in 853 BCE under King Ahab.","Assyria took Samaria in 722 BCE and deported its people, giving rise to the legend of the Ten Lost Tribes."],dyk:"Assyrian scribes went on calling Israel ‘the House of Omri’ for well over a century, long after Jehu had wiped out Omri’s dynasty.",ev:[["c. 930 BCE","The northern tribes reject Rehoboam at Shechem and make Jeroboam I king"],["c. 880 BCE","Omri founds the new capital of Samaria"],["853 BCE","Ahab fights Shalmaneser III of Assyria at the Battle of Qarqar"],["c. 841 BCE","Jehu’s coup destroys the House of Omri; Jehu pays tribute to Assyria"],["c. 788–747 BCE","Reign of Jeroboam II, Israel’s last period of prosperity"],["732 BCE","Tiglath-pileser III annexes Galilee and Gilead"],["722 BCE","Samaria falls to the Assyrians after a long siege"],["720 BCE","Sargon II deports some 27,000 people and creates the province of Samerina"]]},
  "Kingdom of Urartu": {t:["A mountain kingdom centred on Lake Van, called Biainili by its own kings, that rivalled Assyria in the 9th–7th centuries BCE.","Its kings built rock fortresses, storehouses and canals; Menua’s canal still carries water to the city of Van.","Weakened by Assyria and Cimmerians, Urartu vanished around 590 BCE, and its lands became the Armenian heartland."],dyk:"Yerevan, capital of modern Armenia, traces its origin to the Urartian fortress of Erebuni, founded by Argishti I in 782 BCE, and celebrated its 2,750th anniversary in 1968.",ev:[["856 BCE","Shalmaneser III of Assyria sacks Arzashkun, royal city of King Arame"],["c. 840 BCE","Sarduri I builds the citadel of Tushpa on the rock of Van"],["782 BCE","Argishti I founds the fortress of Erebuni, origin of Yerevan"],["743 BCE","Tiglath-pileser III defeats Sarduri II and his Syrian allies"],["714 BCE","Sargon II defeats Rusa I and sacks the temple of Haldi at Musasir"],["c. 680–650 BCE","Rusa II founds Teishebaini, Bastam, Ayanis and Rusahinili"],["c. 590 BCE","Urartu disappears, probably conquered by the Medes"]]},
  "Kingdom of Saba": {t:["The oldest of the South Arabian kingdoms, centred on the irrigated oasis of Marib in Yemen, and the biblical land of Sheba.","It grew rich on irrigated farming and on frankincense and myrrh carried by caravan to the Mediterranean and Mesopotamia.","Rivals, sea trade and the rise of Himyar wore it down until Himyar absorbed it around 275 CE."],dyk:"Besides formal inscriptions on stone, the Sabaeans wrote letters and contracts in a cursive script on palm-leaf stalks, and many of these everyday texts have been recovered.",ev:[["c. 8th century BCE","Mukarribs rule Saba from Marib and Sirwah; Sabaic inscriptions appear"],["715 BCE","Itamra the Sabaean sends gifts to Sargon II of Assyria"],["7th century BCE","Karib’il Watar destroys Awsan and imposes Sabaean supremacy in South Arabia"],["late 2nd century BCE","The Himyarite kingdom rises in the highlands around Zafar"],["25 BCE","Aelius Gallus besieges Marib for six days and retreats"],["early 3rd century CE","Sha’irum Awtar defeats Hadramawt and takes Shabwa"],["c. 275 CE","Shammar Yuhar’ish of Himyar absorbs Saba"]]},
  "Kingdom of Iberia": {t:["Kartli, the ancient kingdom of eastern Georgia, ruled from Mtskheta and later Tbilisi, and called Iberia by Greeks and Romans.","It guarded the passes of the Caucasus and balanced for centuries between Rome and Persia as client of one or the other.","It adopted Christianity in the 4th century and produced the earliest Georgian inscriptions and literature."],dyk:"Pompey the Great fought his way into Iberia in 65 BCE while chasing Mithridates VI of Pontus, defeating King Artoces in battles on the Mtkvari and Aragvi rivers.",ev:[["c. 300 BCE","Pharnavaz I unites Kartli, according to Georgian tradition"],["65 BCE","Pompey invades Iberia and forces King Artoces to submit"],["35 CE","Pharasmanes I seizes Armenia for his brother Mithridates"],["75 CE","Vespasian fortifies Mtskheta for King Mithridates of Iberia"],["c. 330s","King Mirian III adopts Christianity through the mission of St Nino"],["482","Vakhtang I Gorgasali joins the Armenian revolt against Persia"],["c. 580","Hormizd IV abolishes the Iberian monarchy"]]},
  "Kingdom of Pontus": {t:["A Hellenistic kingdom on the southern Black Sea, ruled by a dynasty of Persian origin from Amaseia and later Sinope.","Rich in metals, timber and Greek ports, it built a Black Sea empire under Mithridates VI Eupator.","Mithridates VI fought Rome in three wars from 89 to 63 BCE before Pompey destroyed the kingdom."],dyk:"The geographer Strabo was born at Amaseia, the first Pontic capital, around 64 BCE, into a family that had served the kings of Pontus.",ev:[["281 BCE","Mithridates I Ktistes takes the title of king"],["183 BCE","Pharnaces I captures Sinope and makes it his capital"],["c. 110–107 BCE","Diophantus brings Chersonesus and the Bosporan Kingdom under Pontic rule"],["88 BCE","Mithridates VI overruns Roman Asia and orders the massacre of Romans and Italians"],["85 BCE","Peace of Dardanus ends the First Mithridatic War"],["72–71 BCE","Lucullus defeats Mithridates at Cabira and occupies Pontus"],["66 BCE","Pompey routs Mithridates on the Lycus river"],["63 BCE","Mithridates VI dies at Panticapaeum; Pompey divides Pontus"]]},
  "Himyarite Kingdom": {t:["A kingdom of the Yemeni highlands, ruled from Zafar, that united all of south Arabia around 300 CE.","Around 380 its kings gave up the old gods for one god, the Merciful, in a monotheism close to Judaism.","Conflict with Christian Najran and Aksum ended in Kaleb’s invasion of 525, in which the last king, Yusuf, was killed."],dyk:"The Himyarites dated their inscriptions by their own era, which began around 110 BCE, so many Himyarite texts can be dated to the exact year.",ev:[["c. 110 BCE","The Himyarite era, later used to date inscriptions, begins"],["26–25 BCE","A Roman expedition under Aelius Gallus reaches south Arabia and withdraws"],["c. 275","Shammar Yuhar\u0027ish annexes the Kingdom of Saba"],["c. 300","Himyar annexes the Kingdom of Hadramawt and unites south Arabia"],["c. 380","The royal court abandons the old gods for monotheism"],["450s","Sharahbil Ya\u0027fur records major repairs of the Marib Dam"],["523","Yusuf As\u0027ar Yath\u0027ar besieges Najran, where many Christians are killed"],["525","Kaleb of Aksum invades, and Yusuf is defeated and killed"]]},
  "Caucasian Albania": {t:["A kingdom of the eastern Caucasus between the Kura river and the Caspian, roughly the north and centre of modern Azerbaijan.","A client first of Rome and then of Sasanian Persia, it guarded the Caspian passes against raiders from the steppe.","It adopted Christianity in the 4th century and had its own church and alphabet, whose texts survive in Sinai palimpsests."],dyk:"A Roman legion left a Latin inscription at Gobustan near Baku under the emperor Domitian, the easternmost Latin inscription known.",ev:[["66–65 BCE","King Oroeses attacks Pompey and is defeated near the Abas river"],["81–96","A detachment of Legio XII Fulminata carves an inscription at Gobustan"],["4th century","King Urnayr adopts Christianity, according to tradition"],["c. 387","Albania receives the Armenian provinces of Artsakh and Utik"],["early 5th century","An alphabet is created for the Caucasian Albanian language"],["451","Albanians join the Armenian rising crushed at the Battle of Avarayr"],["c. 488","Vachagan III issues church canons at the council of Aghuen"],["c. 510","The Sasanians abolish the kingship and rule through marzbans"]]},
  "Alans": {t:["Iranian-speaking horse nomads related to the Sarmatians, who dominated the steppe north of the Caucasus from the 1st century CE.","Broken by the Huns around 370, some Alans crossed the Rhine in 406 and went on with the Vandals to Spain and North Africa.","Those who stayed in the Caucasus formed the Kingdom of Alania, and the Ossetians speak a language descended from theirs."],dyk:"Ammianus Marcellinus wrote that the Alans worshipped a naked sword thrust into the ground as their god of war, and foretold the future with willow rods.",ev:[["early 70s","Alans cross the Caucasus and raid Media and Armenia"],["c. 135","Arrian, governor of Cappadocia, prepares Roman forces against an Alan invasion"],["c. 370","The Huns defeat the Alans near the Don"],["406","Alans cross the Rhine with the Vandals and Suebi"],["418","The Visigoths destroy the Alans of Hispania and kill their king Addac"],["429","Alans cross with the Vandals to North Africa"],["451","Alans under Sangiban fight Attila at the Catalaunian Plains"],["c. 558","Sarosius helps the first Avar envoys reach Constantinople"]]},
  "Shirvanshah State": {t:["A Muslim dynasty of Arab origin that ruled Shirvan, in the north-east of modern Azerbaijan, from 861 to 1538.","It survived by accepting the overlordship of caliphs, Seljuks, Georgians, Mongols and Timurids in turn.","Its court patronised Khaqani and Nizami, and Khalilullah I built the Palace of the Shirvanshahs in Baku."],dyk:"Nizami Ganjavi’s Layla and Majnun, one of the most retold love stories of the Islamic world, was composed in 1188 at the request of Shirvanshah Akhsitan I.",ev:[["861","Haytham ibn Khalid declares himself Shirvanshah"],["1188","Nizami completes Layla and Majnun for Akhsitan I"],["1221","The Mongols under Jebe and Subutai take Shamakhi"],["1382","Ibrahim I founds the Derbendi line and revives the state"],["1441","Khalilullah I completes the mosque of his palace in Baku"],["1488","Farrukh Yasar kills Shaykh Haydar, father of the future Shah Ismail"],["1500","Ismail I defeats and kills Farrukh Yasar at the Battle of Jabani"],["1538","Tahmasp I annexes Shirvan to the Safavid Empire"]]},
  "Buyid dynasty": {t:["Three Daylamite brothers took Fars, the Jibal and Iraq between 934 and 945 and ruled them as a family confederation.","Shia themselves, they kept the Sunni Abbasid caliphs as figureheads in Baghdad for 110 years.","Under Adud al-Dawla (d. 983) they reached their height; family rivalry then left them prey to the Ghaznavids and Seljuks."],dyk:"The astronomer Abd al-Rahman al-Sufi dedicated his Book of Fixed Stars to Adud al-Dawla; it contains one of the earliest recorded descriptions of the Andromeda Galaxy.",ev:[["934","Ali ibn Buya takes Fars and makes Shiraz his base"],["945","Ahmad ibn Buya enters Baghdad and the brothers receive their titles"],["963","Public Ashura mourning and the feast of Ghadir are introduced in Baghdad"],["978","Adud al-Dawla defeats Bakhtiyar and unites the Buyid lands"],["983","Death of Adud al-Dawla, followed by rivalry among his sons"],["1029","Mahmud of Ghazni takes Ray"],["1055","Tughril Beg enters Baghdad and ends Buyid rule in Iraq"],["1062","The last Buyid prince in Fars is killed by Fadluya"]]},
  "Kingdom of Georgia": {t:["A Christian monarchy that united eastern and western Georgia in 1008 under the Bagratid dynasty.","Under David the Builder and Queen Tamar it dominated the Caucasus and enjoyed a golden age of poetry and church building.","Mongol conquest, Timur’s invasions and rebellious regional lords broke it into separate kingdoms by 1490."],dyk:"David the Builder settled thousands of Kipchak families from the steppes in Georgia as soldiers, and Tamar was crowned with the title of king rather than queen.",ev:[["1008","Bagrat III unites western and eastern Georgia"],["1121","David IV routs a Muslim coalition at the Battle of Didgori"],["1122","David IV captures Tbilisi and makes it his capital"],["1184","Tamar becomes sole ruler"],["1204","Georgian-backed Komnenos brothers found the Empire of Trebizond"],["1243","Queen Rusudan submits to the Mongols"],["1386","Timur takes Tbilisi and captures King Bagrat V"],["1490","A royal council accepts the division of Georgia into separate kingdoms"]]},
  "Sultanate of Rum": {t:["A Seljuk sultanate that ruled central Anatolia from Konya for over two centuries after the Byzantine defeat at Manzikert.","Its sultans built a Persianate court and a trade network of ports and caravanserais linking the Mediterranean and Black Sea.","Defeat by the Mongols at Köse Dağ in 1243 made it a vassal state, and it dissolved into the beyliks that included the Ottomans."],dyk:"The Seljuks of Rum built more than a hundred caravanserais along Anatolia’s roads, some so large and fortified that they resemble castles.",ev:[["c. 1077","Suleiman ibn Qutalmish establishes Seljuk rule in western Anatolia"],["1097","The First Crusade takes Nicaea and defeats Kilij Arslan I at Dorylaeum"],["1176","Kilij Arslan II defeats Manuel I Komnenos at Myriokephalon"],["1207","Kaykhusraw I captures the port of Antalya"],["1221","Kayqubad I takes Alanya and fortifies it"],["1243","The Mongols crush the Seljuk army at the Battle of Köse Dağ"],["1273","The poet and mystic Rumi dies in Konya"],["c. 1308","The last sultan, Mesud II, dies and the sultanate lapses"]]},
  "Kingdom of Jerusalem": {t:["The principal Crusader state, founded after the First Crusade took Jerusalem in July 1099.","A small Frankish elite ruled a mostly Muslim and Eastern Christian population, relying on castles, military orders and Italian fleets.","Saladin’s victory at Hattin in 1187 broke it; the kingdom survived on the coast until the Mamluks took Acre in 1291."],dyk:"The kingdom minted gold coins imitating Fatimid dinars, with Arabic inscriptions; after papal objections in the 1250s they carried Christian texts in Arabic.",ev:[["1099","The First Crusade takes Jerusalem"],["1100","Baldwin I is crowned the first king at Bethlehem"],["1124","Tyre falls to the Franks and a Venetian fleet"],["1177","Baldwin IV defeats Saladin at Montgisard"],["1187","Saladin destroys the Frankish army at Hattin and takes Jerusalem"],["1191","The Third Crusade recovers Acre"],["1229","Frederick II regains Jerusalem by treaty"],["1291","The Mamluks take Acre, ending the kingdom"]]},
  "Empire of Trebizond": {t:["A Greek successor state of Byzantium founded in 1204 on the south-eastern Black Sea coast by the Grand Komnenoi.","Its wealth came from trade between Persia and the Black Sea, carried by Genoese and Venetian merchants.","It survived by tribute and marriage alliances until Mehmed II took Trebizond in 1461, eight years after Constantinople fell."],dyk:"Theodora of Trebizond, daughter of John IV, married the Turkmen ruler Uzun Hasan; their daughter was the mother of Shah Ismail I, founder of the Safavid dynasty of Persia.",ev:[["1204","Alexios and David Komnenos seize Trebizond with Georgian troops"],["1214","The Seljuks take Sinop and capture Alexios I"],["1243","Trebizond becomes a vassal of the Mongols"],["1282","John II gives up the title of Emperor of the Romans"],["1340s","Civil war between aristocratic factions weakens the empire"],["1349","Alexios III begins a long reign that restores order"],["1461","Emperor David surrenders Trebizond to Mehmed II"],["1463","David and most of his family are executed in Constantinople"]]},
  "Kingdom of Imereti": {t:["A western Georgian kingdom ruled from Kutaisi by a branch of the Bagrationi dynasty, separate from 1260 and definitively from 1490.","It spent over two centuries as an Ottoman tributary, troubled by rebellious vassals and a cruel trade in slaves.","Solomon I revived it in the eighteenth century, but the Russian Empire deposed Solomon II and annexed it in 1810."],dyk:"Two battles fought at Chikhori shaped Imereti’s history: Bagrat’s victory over George VIII in 1463 and Solomon I’s victory over the Ottomans in 1757.",ev:[["1260","David VI Narin withdraws to Kutaisi and founds a western kingdom"],["1330","George V the Brilliant reunites Imereti with the rest of Georgia"],["1463","Bagrat of Imereti defeats George VIII at Chikhori"],["1490","The division of Georgia leaves Imereti a separate kingdom"],["1555","The Treaty of Amasya places western Georgia in the Ottoman sphere"],["1757","Solomon I defeats the Ottomans at Chikhori"],["1804","Solomon II accepts Russian protection by the Treaty of Elaznauri"],["1810","Russia deposes Solomon II and annexes Imereti"]]},
  "Aq Qoyunlu": {t:["A Turkmen tribal confederation led by the Bayandur clan, based first at Diyarbakır and from 1469 at Tabriz.","Under Uzun Hasan it destroyed the Qara Qoyunlu and the Timurid Abu Sa’id to rule Iran, Iraq and eastern Anatolia.","Defeated by the Ottomans in 1473, it split after 1490 and gave way to the Safavid state of Uzun Hasan’s grandson Ismail."],dyk:"Shah Ismail I, founder of the Safavid dynasty that overthrew the Aq Qoyunlu, was Uzun Hasan’s grandson through his daughter by the Trebizond princess Theodora Komnene.",ev:[["1398","Qara Yuluk Osman defeats and kills Kadi Burhan al-Din"],["c. 1402","Timur rewards Osman with Diyarbakır"],["1467","Uzun Hasan defeats and kills the Qara Qoyunlu ruler Jahan Shah"],["1469","Uzun Hasan defeats the Timurid Abu Sa’id and makes Tabriz his capital"],["1473","Mehmed II defeats Uzun Hasan at the Battle of Otlukbeli"],["1490","Death of Ya’qub opens a decade of succession wars"],["1501","Ismail defeats Alvand at Sharur and takes Tabriz"],["1503","Ismail defeats Murad near Hamadan, ending Aq Qoyunlu rule"]]},
  "Circassia": {t:["The homeland of the Adyghe peoples between the Black Sea, the Kuban river and the north-western Caucasus.","It had no king or capital: princely societies and self-governing free communities shared a language and the code Adyghe Khabze.","A century of war with Russia ended in 1864 with conquest and the deportation of most Circassians to the Ottoman Empire."],dyk:"From the accession of Barquq in 1382 until 1517, most sultans of Mamluk Egypt and Syria were Circassians who had been brought to Cairo as slave soldiers.",ev:[["1561","Ivan the Terrible marries Maria Temryukovna, daughter of the Kabardian prince Temryuk"],["1708","Kabardians defeat a Crimean army at the Battle of Kanzhal"],["1763","Russia founds Mozdok, beginning its advance into Kabarda"],["1774","Treaty of Küçük Kaynarca recognises Kabarda as Russian"],["1829","Ottomans cede the Circassian coast to Russia in the Treaty of Adrianople"],["1861","Circassian delegates meet in a united assembly at Sochi"],["1864","Russia ends Circassian resistance; mass deportation to the Ottoman Empire"]]},
  "Sheikhdom of Sharjah": {t:["The chief seat of the Al Qasimi family on the Trucial Coast from the early nineteenth century.","It lived from pearling, fishing and trade, under British protection after the General Maritime Treaty of 1820.","Losing dependencies and trade to its neighbours, it joined the United Arab Emirates as a founding member in 1971."],dyk:"Sharjah had the first airfield on the Trucial Coast: in 1932 Imperial Airways built a fortified rest house there, Al Mahatta, for passengers flying between Britain and India.",ev:[["1727","Qawasim traditionally said to establish their rule at Sharjah"],["1819","British expedition destroys Qasimi naval power; Sharjah becomes the family’s main seat"],["1820","Sultan bin Saqr signs the General Maritime Treaty with Britain"],["1853","Perpetual Maritime Truce ends warfare at sea"],["1892","Exclusive Agreement places foreign relations under Britain"],["1932","Imperial Airways opens a rest house and airfield at Sharjah"],["1965","Britain deposes Sheikh Saqr bin Sultan"],["1971","Sharjah joins the United Arab Emirates on 2 December"]]},
  "Qajar Iran": {t:["A Turkmen tribal dynasty that reunited Iran in the 1790s and ruled from Tehran, which it made the capital.","Wars with Russia cost Iran the Caucasus by 1828, and Britain and Russia competed for influence over the weak state.","The Constitutional Revolution of 1906 created a parliament; Reza Khan’s coup of 1921 led to the dynasty’s fall in 1925."],dyk:"Naser al-Din Shah was an enthusiastic photographer who took and developed pictures himself, and thousands of Qajar-era photographs survive in the Golestan Palace collections.",ev:[["1786","Agha Mohammad Khan makes Tehran his capital"],["1796","Agha Mohammad Khan is crowned shah"],["1813","Treaty of Gulistan cedes Georgia and most of the Caucasian khanates to Russia"],["1828","Treaty of Turkmenchay surrenders Erivan and Nakhichevan"],["1851","Amir Kabir founds the Dar ol-Fonun in Tehran"],["1891–1892","The Tobacco Protest forces cancellation of a British monopoly"],["1906","Constitutional Revolution creates the Majlis"],["1925","The Majlis deposes Ahmad Shah, ending the dynasty"]]},
  "South Yemen": {t:["Founded in 1967 when the National Liberation Front took power in Aden as British rule in southern Arabia ended.","The only Marxist–Leninist state in the Arab world, ruled by the Yemeni Socialist Party and allied with the Soviet Union.","A party civil war in 1986 and the end of Soviet support led to unification with North Yemen on 22 May 1990."],dyk:"South Yemen’s Family Law of 1974 restricted polygamy and set a minimum age of marriage, making it one of the most progressive family codes in the Arab world.",ev:[["1963","The NLF begins its armed uprising in the Radfan mountains"],["1967","Britain withdraws and the People’s Republic of South Yemen is proclaimed on 30 November"],["1969","The Corrective Move removes President Qahtan al-Shaabi"],["1970","The country is renamed the People’s Democratic Republic of Yemen"],["1978","The Yemeni Socialist Party is founded"],["1979","Border war with North Yemen; treaty of friendship with the Soviet Union"],["1986","Party civil war in Aden kills thousands, including Abdul Fattah Ismail"],["1990","Unification with North Yemen forms the Republic of Yemen on 22 May"]]},
  "United Arab Emirates": {t:["A federation of seven emirates formed in 1971–1972 from the British-protected Trucial States, with Abu Dhabi as its capital.","Abu Dhabi\u0027s oil and Dubai\u0027s ports, airline and free zones made it a global hub of trade, finance and aviation.","Since the 2010s it has acted as an assertive regional power, from Yemen to the Abraham Accords with Israel in 2020."],dyk:"The UAE\u0027s Hope probe, which entered orbit around Mars in February 2021, was the first interplanetary mission by an Arab country.",ev:[["1968","Zayed and Rashid agree to form a union after Britain announces its withdrawal from the Gulf"],["1971","Six sheikhdoms proclaim the United Arab Emirates on 2 December"],["1972","Ras al-Khaimah joins as the seventh emirate"],["1979","Jebel Ali port opens; Rashid of Dubai becomes prime minister"],["1981","The Gulf Cooperation Council is founded in Abu Dhabi"],["2004","Zayed dies and is succeeded by Khalifa bin Zayed"],["2009","Abu Dhabi rescues Dubai during the Dubai World debt crisis"],["2020","The UAE signs the Abraham Accords with Israel"]]},
  "Republic of Yemen": {t:["Formed on 22 May 1990 by the union of the conservative Yemen Arab Republic and the Marxist South Yemen.","A brief democratic opening gave way to the 1994 civil war and Saleh\u0027s long rule through tribal and military patronage.","Since the Houthis seized Sanaa in 2014 it has been torn by war and one of the world\u0027s worst humanitarian crises."],dyk:"In 1990 Yemen sat on the UN Security Council and voted against the resolution authorising force against Iraq, a stand that cost hundreds of thousands of Yemenis their jobs in Saudi Arabia.",ev:[["1990","North and South Yemen unite as the Republic of Yemen on 22 May"],["1994","Northern forces defeat a southern secession and take Aden"],["2000","Treaty of Jeddah fixes the Saudi border; al-Qaeda bombs the USS Cole in Aden"],["2004","The first of six wars against the Houthi movement begins in Saada"],["2011","Mass protests force Saleh to agree to hand over power"],["2014","The Houthis seize Sanaa"],["2015","A Saudi-led coalition intervenes in the war"],["2022","A Presidential Leadership Council takes over the recognised government"]]},
  "Kingdom of Magadha": {t:["A kingdom of south Bihar that grew from one of sixteen rival realms into the dominant power of northern India.","Its kings Bimbisara and Ajatashatru were patrons of the Buddha and Mahavira, and Rajagriha hosted the First Buddhist Council.","Its conquests and its capital Pataliputra became the core of the Nanda, Maurya and later Gupta empires."],dyk:"Buddhist texts say Bimbisara once summoned the headmen of the 80,000 villages of his kingdom to an assembly, then sent them to see the Buddha.",ev:[["c. 544 BCE","Bimbisara of the Haryanka dynasty becomes king (traditional date)"],["c. 530 BCE","Bimbisara annexes the kingdom of Anga"],["c. 492 BCE","Ajatashatru seizes the throne from his father"],["c. 483 BCE","First Buddhist Council at Rajagriha (traditional date)"],["c. 468 BCE","The Vajji league of Vaishali is conquered"],["c. 413 BCE","Shishunaga replaces the Haryanka dynasty"],["c. 383 BCE","Second Buddhist Council at Vaishali under Kalashoka"],["c. 345 BCE","Mahapadma Nanda seizes the throne and founds the Nanda Empire"]]},
  "Pallava dynasty": {t:["A South Indian dynasty that ruled from Kanchipuram for some six centuries, at its height the leading power of the south.","Narasimhavarman I sacked the Chalukya capital Vatapi in 642, during a long rivalry with the Chalukyas of Badami.","Its temples at Mamallapuram and Kanchipuram founded Dravidian architecture, and its script spread across Southeast Asia."],dyk:"King Mahendravarman I wrote a Sanskrit comedy in which a drunken Shaiva ascetic accuses a Buddhist monk of stealing his skull begging bowl, which a dog had actually carried off.",ev:[["c. 350","Samudragupta defeats Vishnugopa of Kanchi"],["c. 575","Simhavishnu defeats the Kalabhras and extends Pallava rule to the Kaveri"],["642","Narasimhavarman I sacks Vatapi; the Chalukya king Pulakeshin II dies"],["c. 700","Rajasimha builds the Shore Temple and the Kailasanatha temple"],["c. 740","Vikramaditya II of the Chalukyas occupies Kanchipuram"],["c. 885","Pallavas and Gangas defeat the Pandyas at Sripurambiyam"],["c. 897","Aditya I of the Cholas defeats Aparajita and annexes the kingdom"]]},
  "Satavahana dynasty": {t:["The first great empire of the Deccan, ruling from Pratishthana (Paithan) and later from the Krishna valley.","Its ports and inland towns traded with the Roman world, and merchants funded Buddhist caves at Karle, Nashik and Kanheri.","Gautamiputra Satakarni defeated the Western Satraps c. 125 CE, but the empire fragmented in the early 3rd century."],dyk:"Satavahana kings were known by their mothers\u0027 names, such as Gautamiputra, \u0027son of Gautami\u0027, and some of their silver coins bear legends in both Prakrit and an early Dravidian language.",ev:[["c. 100 BCE","Simuka founds the dynasty in the northern Deccan (date disputed)"],["1st c. BCE","Queen Naganika\u0027s Naneghat inscription records Satakarni I\u0027s horse sacrifices"],["c. 125","Gautamiputra Satakarni destroys the Kshaharata dynasty of Nahapana"],["c. 150","Rudradaman I of the Western Satraps twice defeats the Satavahanas"],["late 2nd c.","Yajna Sri Satakarni recovers parts of the western Deccan"],["early 3rd c.","The kingdom fragments among the Abhiras, Ikshvakus and Chutus"]]},
  "Chalukyas of Badami": {t:["A Deccan dynasty that ruled from Vatapi, modern Badami in northern Karnataka, from about 543 until 753.","Pulakeshin II defeated Harsha on the Narmada and ruled from the Arabian Sea to the Bay of Bengal.","Its temples at Badami, Aihole and Pattadakal mark the move from rock-cut caves to free-standing stone temples."],dyk:"The Aihole inscription of 634 names the poets Kalidasa and Bharavi, giving one of the earliest firm dates by which Kalidasa’s works were already famous.",ev:[["543","Pulakeshin I fortifies the hill of Vatapi and performs a horse sacrifice"],["c. 610","Pulakeshin II wins the throne in a civil war against his uncle Mangalesha"],["c. 619","Pulakeshin II halts Harsha of Kannauj on the Narmada (date debated)"],["c. 624","Conquest of Vengi; Kubja Vishnuvardhana founds the Eastern Chalukyas"],["634","Ravikirti composes the Aihole inscription celebrating Pulakeshin II"],["642","Pallava king Narasimhavarman I takes Vatapi; Pulakeshin II dies"],["c. 740","Vikramaditya II occupies Kanchipuram; Virupaksha temple built at Pattadakal"],["c. 753","Dantidurga overthrows Kirtivarman II and founds the Rashtrakuta dynasty"]]},
  "Sunda Kingdom": {t:["A Hindu-Buddhist kingdom of West Java, ruled in its last century from Pakuan Pajajaran on the site of modern Bogor.","It exported pepper through Sunda Kalapa, the port that became Jakarta, and resisted both Majapahit and the Muslim coastal states.","Banten’s capture of Pakuan in 1579 ended the kingdom, but Sundanese language, literature and identity endure in West Java."],dyk:"The stone pillar set up for Sunda’s 1522 treaty with Portugal was rediscovered in Jakarta in 1918 and is now kept in the National Museum of Indonesia.",ev:[["669","Traditional date for Tarusbawa’s founding of the kingdom of Sunda"],["1030","Sanghyang Tapak inscriptions of King Sri Jayabupati"],["1357","King Linggabuana is killed by Majapahit troops in the Battle of Bubat"],["c. 1482","Sri Baduga Maharaja unites Sunda and Galuh and rules from Pakuan Pajajaran"],["1522","Sunda signs a treaty of alliance with the Portuguese of Malacca"],["1527","Fatahillah’s forces capture Sunda Kalapa, later Jakarta"],["1533","Surawisesa sets up the Batutulis inscription honouring his father"],["1579","Maulana Yusuf of Banten takes and destroys Pakuan Pajajaran"]]},
  "Udaipur State": {t:["A Rajput kingdom in southern Rajasthan ruled by the Guhila and Sisodia dynasty from the early 8th century to 1949.","Its fortress of Chittor fell to Alauddin Khalji, Bahadur Shah and Akbar, and became a symbol of Rajput resistance.","Mewar accepted Mughal overlordship in 1615 and British protection in 1818, joining Rajasthan in 1948–1949."],dyk:"The rulers of Mewar governed as the diwan, or chief minister, of the god Ekalinga, whom the dynasty regarded as the true king of the land.",ev:[["c. 728","Bappa Rawal traditionally takes Chittor and founds the Guhila kingdom"],["1303","Alauddin Khalji captures Chittor after an eight-month siege"],["1527","Rana Sanga is defeated by Babur at the Battle of Khanwa"],["1559","Udai Singh II founds Udaipur on Lake Pichola"],["1568","Akbar takes Chittor after a siege of several months"],["1576","Maharana Pratap fights a Mughal army at the Battle of Haldighati"],["1615","Amar Singh I accepts Mughal overlordship on honourable terms"],["1948","Udaipur joins the United State of Rajasthan; Bhupal Singh becomes Rajpramukh"]]},
  "Gurjara-Pratihara": {t:["A dynasty from western India that ruled northern India from Kannauj between the early 9th and early 10th centuries.","Its cavalry checked Arab expansion beyond Sindh and Multan, and Arab writers thought its king the most hostile to them in India.","It fought the Palas and Rashtrakutas for Kannauj, and its feudatories became the later Rajput kingdoms."],dyk:"An inscription of 876 at the Chaturbhuj temple in Gwalior Fort, set up under Mihira Bhoja, contains one of the earliest known inscribed zeros in India.",ev:[["c. 738","Nagabhata I repels Arab armies advancing from Sindh"],["c. 786","The Rashtrakuta Dhruva defeats Vatsaraja and drives him from the Doab"],["c. 816","Nagabhata II takes Kannauj from the Ayudha dynasty and makes it the capital"],["c. 836","Mihira Bhoja begins a reign of almost fifty years"],["851","An Arab merchant praises the cavalry and security of the Gurjara kingdom"],["c. 916","The Rashtrakuta Indra III sacks Kannauj"],["1018","Mahmud of Ghazni takes Kannauj after Rajyapala abandons it"],["1036","Last inscription of the dynasty, issued by Yashahpala"]]},
  "Pala Empire": {t:["A Buddhist dynasty that ruled Bengal and Bihar for about four centuries, from around 750 to around 1161.","Its kings founded Vikramashila and Somapura and supported Nalanda, the great monastic universities of eastern India.","Pala scholars and art shaped the Buddhism of Tibet, Nepal and Southeast Asia; Atisha left Vikramashila for Tibet."],dyk:"Devapala granted five villages to support a monastery at Nalanda built by Balaputradeva, the Shailendra king of Suvarnadvipa (Sumatra), at that king’s request.",ev:[["c. 750","Gopala is chosen king of Bengal to end a period of anarchy"],["c. 800","Dharmapala installs Chakrayudha as king of Kannauj"],["c. 840","Devapala’s Nalanda grant at the request of the Shailendra king Balaputradeva"],["c. 988","Mahipala I begins the revival of the Pala kingdom"],["c. 1023","The Chola king Rajendra I sends an expedition to the Ganges"],["c. 1040","Atisha leaves Vikramashila for Tibet"],["c. 1085","Ramapala defeats the Kaivarta rebels and recovers Varendra"],["c. 1161","Death of Madanapala, the last significant Pala king"]]},
  "Rashtrakuta dynasty": {t:["A Deccan empire founded in 753 by Dantidurga, who overthrew his Chalukya overlords; its capital from Amoghavarsha I was Manyakheta.","Its armies reached the Ganges plain and Kanchi, and Arab writers counted its king, the Balhara, among the world’s four great kings.","It carved the Kailasa temple at Ellora and fostered the earliest surviving Kannada literature and major Jain scholarship."],dyk:"The last Rashtrakuta claimant, Indra IV, ended his life in 982 by sallekhana, the Jain ritual fast to death, at the hilltop shrine of Shravanabelagola.",ev:[["c. 753","Dantidurga defeats the Chalukya king Kirtivarman II"],["c. 790","Dhruva defeats the Pratihara and Pala kings in the Ganga–Yamuna doab"],["c. 800","Govinda III campaigns from the Ganges plain to Kanchi"],["814","Amoghavarsha I begins a 64-year reign and later founds Manyakheta"],["c. 916","Indra III sacks Kannauj"],["949","Krishna III defeats the Cholas at the Battle of Takkolam"],["972","The Paramara king Siyaka II sacks Manyakheta"],["973","Tailapa II overthrows Karka II and founds the Western Chalukya Empire"]]},
  "Pagan Kingdom": {t:["The first state to unite the Irrawaddy valley, ruled from Pagan, a walled city on the middle Irrawaddy dated by tradition to 849.","Its kings and subjects built some 10,000 Buddhist monuments on the plain of Bagan, and Theravada Buddhism became the faith of the realm.","Tax-free gifts of land to monasteries weakened the crown, and Mongol invasions in the 1280s broke the kingdom apart."],dyk:"The Myazedi inscription of 1113 repeats the same text in Pali, Mon, Pyu and Old Burmese, and it became the key to deciphering the lost Pyu language.",ev:[["849","Traditional date for the fortification of Pagan"],["1044","Anawrahta takes the throne"],["1057","Anawrahta conquers the Mon city of Thaton, according to tradition"],["1113","The four-language Myazedi inscription is set up"],["c. 1183","Narapatisithu’s Sulamani temple is built"],["1277","Mongol forces from Yunnan defeat Pagan at Ngasaunggyan"],["1287","King Narathihapate is murdered as Yuan forces invade"],["1297","The Myinsaing brothers depose Kyawswa, ending the dynasty"]]},
  "Western Chalukya Empire": {t:["Founded in 973 by Tailapa II, who overthrew the Rashtrakutas and claimed descent from the Chalukyas of Badami.","Its kings ruled from Kalyani and fought the Chola Empire for two centuries over the Raichur doab and Vengi.","Its courts produced the Mitakshara, rich Kannada literature and an ornate temple style that inspired the Hoysalas."],dyk:"Someshvara I, stricken by incurable illness in 1068, ended his life by drowning in the Tungabhadra river, a death recorded by the poet Bilhana and in inscriptions.",ev:[["973","Tailapa II overthrows the Rashtrakuta king Karka II"],["c. 995","Tailapa II defeats and captures the Paramara king Vakpati Munja"],["c. 1020","Rajendra I Chola defeats Jayasimha II at Maski"],["1054","The Chola king Rajadhiraja I is killed at the Battle of Koppam"],["1076","Vikramaditya VI takes the throne and begins the Chalukya-Vikrama era"],["1129","Someshvara III compiles the Manasollasa"],["1162","The Kalachuri Bijjala II takes royal titles at Kalyani"],["c. 1189","Someshvara IV disappears; Yadavas and Hoysalas divide the empire"]]},
  "Hoysala Empire": {t:["Hill chiefs of the Malnad who rose as Western Chalukya feudatories and became an independent kingdom under Veera Ballala II in 1187.","Their soapstone temples at Belur, Halebidu and Somanathapura, on star-shaped platforms, are World Heritage masterpieces of sculpture.","Weakened by the Delhi Sultanate’s invasions from 1311, the dynasty ended when Veera Ballala III was killed in 1343."],dyk:"Many Hoysala temple sculptures are signed: carvers such as Mallitamma and Dasoja left their names beside their work, unusually for medieval India.",ev:[["1116","Vishnuvardhana’s forces take Talakad from the Cholas"],["1117","The Chennakeshava temple at Belur is consecrated"],["1187","Veera Ballala II assumes full imperial titles"],["c. 1190","Ballala II defeats the Seuna Yadavas at Soratur"],["1268","The Keshava temple at Somanathapura is built"],["1311","Malik Kafur captures the Hoysala capital Dwarasamudra"],["1343","Veera Ballala III is killed fighting the Madurai Sultanate"]]},
  "Later Pandyan Empire": {t:["A revival of the ancient Pandya dynasty of Madurai that overturned Chola rule and became the leading power of south India c. 1250–1310.","Its ports, above all Kayal, grew rich on pearls and on importing thousands of horses each year from Arabia and the Persian Gulf.","A succession war and the Delhi Sultanate’s invasions from 1311 destroyed it, and Madurai became a sultanate in 1335."],dyk:"Marco Polo wrote that the horses imported into the Pandya country died quickly in the south Indian climate, so the kings had to buy thousands more each year.",ev:[["c. 1205","The Chola king Kulottunga III sacks Madurai"],["c. 1219","Maravarman Sundara Pandya I burns Thanjavur and Uraiyur"],["c. 1262","Jatavarman Sundara Pandya I defeats and kills the Hoysala Vira Someshvara"],["c. 1279","Maravarman Kulasekara I defeats Rajendra III, the last Chola king"],["c. 1284","Pandya forces take the Tooth Relic from Yapahuwa in Sri Lanka"],["c. 1292","Marco Polo visits the coast of Ma’bar"],["1311","Malik Kafur plunders Madurai"],["1323","Ulugh Khan annexes Madurai to the Delhi Sultanate"]]},
  "Ahom kingdom": {t:["A Tai kingdom founded in 1228 by Sukaphaa that ruled the Brahmaputra valley of Assam for six centuries.","The paik system made every free adult man owe labour or military service, supporting roads, embankments and armies.","The Ahoms resisted the Mughal Empire, winning at Saraighat in 1671, before rebellion and Burmese invasions ended the state."],dyk:"Ahom kings were buried in earthen mounds called maidams at Charaideo, which UNESCO inscribed as a World Heritage Site in 2024.",ev:[["1228","Sukaphaa crosses the Patkai hills into the upper Brahmaputra valley"],["1523","Suhungmung annexes the Chutia kingdom"],["1639","Treaty of Asurar Ali fixes a frontier with the Mughal Empire"],["1662","Mir Jumla\u0027s Mughal army occupies the Ahom capital Garhgaon"],["1671","Lachit Borphukan defeats the Mughals at the Battle of Saraighat"],["1769","The Moamoria rebellion breaks out"],["1817","Burmese armies invade Assam"],["1826","Treaty of Yandabo: Burma renounces Assam, which passes to the East India Company"]]},
  "Sukhothai Kingdom": {t:["A Tai kingdom founded around 1238 when local chiefs expelled the Khmer governor of Sukhothai.","Under Ram Khamhaeng in the late thirteenth century its overlordship stretched across much of present-day Thailand.","Ayutthaya made it a vassal in 1378 and absorbed it around 1438, but it became the founding kingdom of Thai history."],dyk:"Ram Khamhaeng\u0027s inscription says a bell hung at the palace gate so that any subject with a grievance could ring it and be heard by the king.",ev:[["c. 1238","Bang Klang Hao expels the Khmer governor and becomes king as Si Inthrathit"],["c. 1279","Ram Khamhaeng becomes king"],["1292","Date of the Ram Khamhaeng inscription; embassies to the Yuan court begin about this time"],["1347","Li Thai takes the throne and begins a Buddhist revival"],["1351","Ayutthaya is founded in the lower Chao Phraya basin"],["1378","Sukhothai submits as a vassal of Ayutthaya"],["1438","Sukhothai is absorbed into Ayutthaya on the death of Maha Thammaracha IV"]]},
  "Lan Na": {t:["A northern Thai kingdom founded by Mangrai, who took Hariphunchai and built Chiang Mai as his capital in 1296.","Under Tilokarat in the fifteenth century it fought Ayutthaya and became a leading centre of Pali Buddhist learning.","Burma ruled it for most of 1558–1775, after which its principalities passed under Siam."],dyk:"The Emerald Buddha, now Thailand\u0027s most sacred image, was kept in Chiang Mai from 1468 until the early 1550s, when it was taken to Lan Xang.",ev:[["1292","Mangrai conquers the Mon kingdom of Hariphunchai"],["1296","Mangrai founds Chiang Mai as his capital"],["1369","The monk Sumana founds a new Buddhist lineage at Wat Suan Dok"],["1477","Tilokarat convenes a Buddhist council at Wat Chet Yot"],["1558","Bayinnaung of Burma captures Chiang Mai"],["1727","A revolt in Chiang Mai expels the Burmese governor"],["1775","Thonburi forces and northern lords take Chiang Mai from the Burmese"]]},
  "Vijayanagara Empire": {t:["Founded around 1336 by the Sangama brothers on the Tungabhadra as Delhi Sultanate power collapsed in the south.","Under Krishnadevaraya (r. 1509–1529) it was the dominant power of southern India, ruled from a vast capital at Hampi.","Defeat at Talikota in 1565 led to the sack of the capital; nayaka governors became independent and the empire ended by 1646."],dyk:"The site of Madras, where the English built Fort St George in 1639–40, was granted by a local nayaka who served the Aravidu kings of Vijayanagara.",ev:[["c. 1336","Harihara I and Bukka I found the kingdom on the Tungabhadra"],["1378","The Madurai Sultanate is destroyed by Vijayanagara armies"],["1443","Persian envoy Abdur Razzaq visits the capital"],["1509","Krishnadevaraya becomes king"],["1520","Krishnadevaraya defeats Bijapur at the Battle of Raichur"],["1565","The Deccan sultanates defeat Vijayanagara at Talikota and sack the capital"],["c. 1570","Tirumala founds the Aravidu dynasty at Penukonda"],["c. 1646","Sriranga III loses his last territories to Bijapur and Golconda"]]},
  "Bahmani Sultanate": {t:["Founded in 1347 when Deccan nobles rebelled against Muhammad bin Tughluq and proclaimed Bahman Shah sultan.","Its Persianate court ruled from Gulbarga and Bidar and fought Vijayanagara for 150 years over the Raichur Doab.","After Mahmud Gawan\u0027s execution in 1481 its governors broke away, founding the five Deccan sultanates."],dyk:"The Russian merchant Afanasy Nikitin stayed in Bidar around 1470 and wrote one of the earliest European descriptions of the Bahmani court and its people.",ev:[["1347","Alauddin Hasan Bahman Shah is proclaimed sultan at Daulatabad"],["1367","The Jama Masjid in Gulbarga fort is built"],["1420","Firuz Shah is defeated by Vijayanagara at Pangal"],["c. 1429","Ahmad Shah I moves the capital to Bidar"],["1472","Mahmud Gawan\u0027s forces take Goa and his madrasa at Bidar is built"],["1481","Mahmud Gawan is executed on a forged charge of treason"],["c. 1490","The governors of Bijapur, Ahmadnagar and Berar become independent"],["c. 1527","The last Bahmani sultan, Kalimullah, flees Bidar"]]},
  "Ayutthaya Kingdom": {t:["A Siamese kingdom on an island in the Chao Phraya that dominated the central plain of Thailand from 1351 to 1767.","Its wealth came from rice and royal trade, with Chinese, Japanese, Persian, Portuguese, Dutch and French merchants living in the capital.","Burma conquered it in 1569 and destroyed it in 1767, but its institutions passed to Thonburi and Bangkok."],dyk:"In 1753 monks sent from Ayutthaya restored the full ordination of Buddhist monks in Sri Lanka, founding the Siyam Nikaya, still the island\u0027s largest order.",ev:[["1351","U Thong founds Ayutthaya and reigns as Ramathibodi I"],["1438","Ayutthaya absorbs the kingdom of Sukhothai"],["1569","Bayinnaung of Burma takes Ayutthaya after a long siege"],["1584","Naresuan renounces allegiance to Burma"],["1593","Naresuan defeats the Burmese at the Battle of Nong Sarai"],["1686","The Siamese envoy Kosa Pan is received by Louis XIV at Versailles"],["1688","Phetracha seizes power and expels the French garrison"],["1767","Konbaung armies sack and burn Ayutthaya"]]},
  "Bengal Sultanate": {t:["An independent Muslim kingdom that united the Bengal delta in 1352 and ruled it from Pandua and Gaur until 1576.","Rice, sugar, muslin and silk made it rich, and its ports of Chittagong and Satgaon traded from the Red Sea to China.","Its sultans patronised Bengali literature and built distinctive brick and terracotta mosques."],dyk:"In 1414 envoys from Bengal presented a giraffe from East Africa to the Yongle Emperor in China, where it was hailed as a qilin, a mythical creature of good omen.",ev:[["1352","Shamsuddin Ilyas Shah unites Bengal as an independent sultanate"],["1353–1354","Firuz Shah Tughluq\u0027s invasion from Delhi ends in withdrawal"],["c. 1375","The Adina Mosque at Pandua is completed"],["1414","A Bengali embassy presents a giraffe to the Yongle Emperor"],["1494","Alauddin Husain Shah becomes sultan, ending the Habshi period"],["1538","Sher Khan Sur takes Gaur"],["1576","Daud Khan Karrani is defeated at Rajmahal and Bengal passes to the Mughals"]]},
  "Lan Xang": {t:["The first kingdom to unite the Lao lands along the middle Mekong, founded by Fa Ngum in 1353.","A Buddhist mandala state of semi-autonomous principalities, ruled from Luang Prabang and from 1560 from Vientiane.","A succession crisis after Sourigna Vongsa\u0027s death split it into the kingdoms of Luang Phrabang and Vientiane in 1707."],dyk:"King Samsenthai\u0027s name means \u0027three hundred thousand Tai\u0027, traditionally explained by a census that counted 300,000 Tai men available for royal service.",ev:[["1353","Fa Ngum is crowned king of Lan Xang"],["1479","A Vietnamese army sent by Lê Thánh Tông sacks the capital"],["1560","Setthathirath moves the capital to Vientiane"],["1566","The great stupa of That Luang is built in Vientiane"],["1574","Lan Xang becomes a vassal of Burma"],["1641","The Dutch merchant Gerrit van Wuysthoff visits Vientiane"],["1707","Lan Xang divides into the kingdoms of Luang Phrabang and Vientiane"]]},
  "Brunei Sultanate": {t:["A Malay Muslim sultanate on the northwest coast of Borneo whose rulers trace a line back to the fourteenth century.","Around 1500 its fleets and allies made it the leading power of Borneo\u0027s coasts and the southern Philippines.","It lost most of its lands to Sarawak and Britain but survived as a protectorate and, from 1984, an independent state."],dyk:"A king of Po-ni, early Brunei, died during a visit to the Ming court in 1408, and his tomb can still be visited in Nanjing.",ev:[["1408","A king of Po-ni visits the Ming court at Nanjing and dies there"],["1521","Antonio Pigafetta describes the water city of Brunei"],["1578","Spain captures the capital in the Castilian War but soon withdraws"],["1841","Sarawak is granted to James Brooke"],["1888","Brunei becomes a British protectorate"],["1929","Oil is discovered at Seria"],["1984","Brunei becomes fully independent under Sultan Hassanal Bolkiah"]]},
  "Kingdom of Mysore (1399-1799)": {t:["A south Indian kingdom ruled by the Wodeyar dynasty, which grew from a Vijayanagara vassal into a regional power.","Under Hyder Ali and Tipu Sultan it built a modern army with French-trained infantry and iron-cased rockets.","It fought four wars with the East India Company and fell when Srirangapatna was stormed in 1799."],dyk:"Tipu\u0027s Tiger, a wooden automaton of a tiger attacking a European soldier that contains a small organ, was taken from Srirangapatna and is now in the V\u0026A in London.",ev:[["1399","Yaduraya founds the Wodeyar dynasty, according to tradition"],["1610","Raja Wodeyar I takes Srirangapatna and makes it his capital"],["1761","Hyder Ali takes control of the government"],["1780","Hyder Ali destroys a British detachment at the Battle of Pollilur"],["1784","The Treaty of Mangalore ends the Second Anglo-Mysore War"],["1792","Tipu Sultan cedes half his territory in the Treaty of Seringapatam"],["1799","British forces storm Srirangapatna and Tipu Sultan is killed"]]},
  "Sulu Sultanate": {t:["A Tausug Muslim sultanate ruling the islands between Mindanao and Borneo from Jolo, founded by tradition by Sharif ul-Hashim.","It resisted Spanish conquest for three centuries and grew rich exporting sea produce to China in the eighteenth and nineteenth centuries.","Its 1878 grant of North Borneo to a British syndicate is the origin of the Philippine claim to Sabah."],dyk:"Paduka Batara, a Sulu ruler who died in China in 1417, is buried at Dezhou in Shandong; members of his family stayed to tend the tomb and their descendants still live there.",ev:[["1417","Paduka Batara and two other Sulu rulers visit the Ming court; he dies on the journey home"],["c. 1450","Sharif ul-Hashim founds the sultanate, by Sulu tradition"],["1638","Spanish forces under Hurtado de Corcuera capture Jolo"],["1775","Tausug warriors destroy the British post on Balambangan Island"],["1848","Spanish steam gunboats destroy the Balangingi raiding bases"],["1876","Spain occupies Jolo"],["1878","Sultan Jamalul Alam grants North Borneo to Overbeck and Dent"],["1915","Jamalul Kiram II gives up temporal power under the Carpenter Agreement"]]},
  "Later Le dynasty": {t:["Founded by Lê Lợi, who ended twenty years of Ming occupation in 1428, it was Vietnam\u0027s longest-reigning dynasty.","Under Lê Thánh Tông (1460–1497) it became a Confucian bureaucratic state and conquered the Cham capital Vijaya in 1471.","From the 1530s the emperors were figureheads while the Trịnh lords ruled the north and the Nguyễn lords the south."],dyk:"The names of Lê-era doctoral graduates were carved on stone stelae resting on turtles at Hanoi\u0027s Temple of Literature from 1484; dozens of these stelae still stand there.",ev:[["1418","Lê Lợi launches his revolt against Ming rule at Lam Sơn"],["1428","Lê Lợi takes the throne as Lê Thái Tổ at Thăng Long"],["1471","Lê Thánh Tông captures Vijaya, the capital of Champa"],["1527","Mạc Đăng Dung seizes the throne and founds the Mạc dynasty"],["1592","Lê and Trịnh forces retake Thăng Long from the Mạc"],["1627","War between the Trịnh and Nguyễn lords begins; a truce follows in 1672"],["1786","The Tây Sơn overthrow the Trịnh lords"],["1789","Quang Trung defeats the Qing at Đống Đa; Lê Chiêu Thống flees to China"]]},
  "Bijapur Sultanate": {t:["One of the five Deccan sultanates that replaced the Bahmani Sultanate, ruled by the Adil Shahi dynasty from Bijapur.","It joined the coalition that defeated Vijayanagara at Talikota in 1565 and later conquered much of southern Karnataka.","Squeezed by the Mughals and the rising Marathas, it fell to Aurangzeb after a long siege in 1686."],dyk:"The Gol Gumbaz in Bijapur, tomb of Muhammad Adil Shah, has a whispering gallery under its dome where a whisper can be heard clearly on the far side.",ev:[["c. 1490","Yusuf Adil Khan makes himself independent at Bijapur"],["1510","The Portuguese capture Goa from Bijapur"],["1565","Bijapur and its allies defeat Vijayanagara at the Battle of Talikota"],["1619","Ibrahim Adil Shah II annexes the Bidar Sultanate"],["1636","Treaty with Shah Jahan makes Bijapur a Mughal tributary"],["1659","Shivaji kills the Bijapur general Afzal Khan at Pratapgad"],["1686","Aurangzeb takes Bijapur after a siege of more than a year"]]},
  "Aceh Sultanate": {t:["A Muslim sultanate at the northern tip of Sumatra that rose after the Portuguese took Malacca in 1511 and dominated the pepper trade.","Under Iskandar Muda (1607–1636) it conquered much of Sumatra and the Malay Peninsula but lost its fleet at Malacca in 1629.","Its scholars made it a centre of Malay Islam, and it fought the Dutch from 1873 until the sultan surrendered in 1903."],dyk:"Four queens ruled Aceh in succession from 1641 to 1699, beginning with Taj ul-Alam Safiatuddin Syah, daughter of the conqueror Iskandar Muda.",ev:[["1524","Ali Mughayat Syah conquers Pasai and drives out the Portuguese"],["1568","Alauddin al-Kahhar besieges Malacca after seeking Ottoman military aid"],["1613","Iskandar Muda sacks Batu Sawar, the capital of Johor"],["1629","Aceh\u0027s armada is destroyed at Malacca by the Portuguese and their allies"],["1641","Taj ul-Alam Safiatuddin becomes the first of four ruling queens"],["1873","The Netherlands declares war, beginning the Aceh War"],["1874","A Dutch expedition captures the sultan\u0027s palace"],["1903","Sultan Muhammad Daud Syah surrenders to the Dutch"]]},
  "Johor Sultanate": {t:["Founded around 1528 by a son of the last Sultan of Malacca, Johor claimed Malacca\u0027s royal line and maritime empire.","It allied with the Dutch to take Malacca in 1641 and became the leading Malay entrepôt of the late seventeenth century.","Its partition by Britain and the Netherlands in 1824 created modern borders; it survives as a monarchy within Malaysia."],dyk:"Johor\u0027s constitution of 1895, issued under Sultan Abu Bakar, forbade any ruler from surrendering the state or any part of it to a foreign power.",ev:[["c. 1528","Alauddin Riayat Shah II founds a new court on the Johor River"],["1613","Aceh sacks Johor\u0027s capital Batu Sawar"],["1641","Johor and the Dutch take Malacca from the Portuguese"],["1699","Sultan Mahmud Shah II is murdered, ending the Malacca line"],["1819","Raffles recognises Hussein as sultan and founds British Singapore"],["1824","The Anglo-Dutch Treaty splits the realm; Riau-Lingga goes to the Dutch sphere"],["1885","Britain recognises Abu Bakar as Sultan of Johor"],["2024","Sultan Ibrahim Iskandar becomes King of Malaysia"]]},
  "Mataram Sultanate": {t:["An inland Javanese sultanate founded by Panembahan Senapati around 1587, built on the rice lands of Central Java.","Sultan Agung conquered the coastal states, Madura and Surabaya, but twice failed to take Dutch Batavia, in 1628 and 1629.","Rebellion and succession wars made it dependent on the Dutch, and the Treaty of Giyanti split it in two in 1755."],dyk:"Sultan Agung’s Javanese calendar of 1633 kept the old Saka year count but switched to Islamic lunar months; it is still used for court ceremonies in Java.",ev:[["c. 1587","Panembahan Senapati rules Mataram from Kotagede, throwing off Pajang’s authority"],["1625","Surabaya surrenders to Sultan Agung after a long siege"],["1628","First of two failed Mataram sieges of Dutch Batavia"],["1633","Sultan Agung introduces the Javanese calendar"],["1677","Trunajaya’s rebels sack the capital Plered"],["1742","Rebels sack Kartasura during the Chinese War"],["1755","The Treaty of Giyanti divides Mataram into Surakarta and Yogyakarta"]]},
  "Restored Toungoo Kingdom": {t:["Founded at Ava by Nyaungyan Min, a son of Bayinnaung, after the collapse of the First Toungoo Empire in 1599.","Anaukpetlun took Syriam from the Portuguese in 1613; Thalun moved the capital back to Ava and ordered a revenue inquest.","Weakened by Manipuri raids and a Mon rising in 1740, it fell when southern forces took Ava in 1752."],dyk:"Portuguese captives taken at Syriam in 1613 were resettled in Upper Burma as royal gunners; their Catholic descendants, the bayingyi, still live in villages there.",ev:[["1599","Pegu falls and the First Toungoo Empire disintegrates"],["1613","Anaukpetlun captures Syriam and executes Filipe de Brito"],["1615","Chiang Mai is retaken and Lan Na returns to Burmese overlordship"],["1635","Thalun moves the capital from Pegu to Ava"],["1638","Thalun orders a kingdom-wide revenue inquest"],["1662","The Burmese court hands the Ming Yongli Emperor to a Qing army"],["1740","The Mon rise at Pegu and found the Restored Hanthawaddy Kingdom"],["1752","Hanthawaddy forces capture Ava, ending the dynasty"]]},
  "Hyderabad State": {t:["Founded in 1724 by the Mughal viceroy Nizam-ul-Mulk, Asaf Jah I, who made the Deccan his hereditary domain.","A British ally under a subsidiary alliance from 1798, it became the largest and richest princely state in India.","Its last Nizam sought independence in 1947; India annexed the state in Operation Polo in September 1948."],dyk:"Osmania University, founded in 1918, taught in Urdu, and a state translation bureau rendered textbooks in medicine, engineering and law into the language.",ev:[["1724","Nizam-ul-Mulk defeats Mubariz Khan at Shakar Kheda"],["1728","Baji Rao I defeats Nizam-ul-Mulk at Palkhed"],["1763","Nizam Ali Khan moves the capital to Hyderabad"],["1798","Subsidiary alliance with the East India Company"],["1853","Berar’s revenues assigned to the British; Salar Jung I becomes chief minister"],["1918","Mir Osman Ali Khan founds Osmania University"],["1948","The Indian army takes over the state in Operation Polo"],["1956","Hyderabad State is divided on linguistic lines"]]},
  "Konbaung dynasty": {t:["Founded in 1752 by Alaungpaya, a village headman who reunited Burma within a few years and founded Rangoon.","Its armies destroyed Ayutthaya in 1767, repelled four Qing invasions and conquered Arakan, Assam and Manipur.","Three wars with Britain, in 1824–1826, 1852 and 1885, stripped it of territory and ended in annexation."],dyk:"At Mindon’s Kuthodaw Pagoda in Mandalay the entire Pali Buddhist canon is carved on 729 marble slabs, each housed in its own small shrine.",ev:[["1752","Alaungpaya proclaims himself king at Moksobo (Shwebo)"],["1757","Alaungpaya captures Pegu and reunites Burma"],["1767","Burmese armies destroy Ayutthaya"],["1769","The last of four Qing invasions ends in the peace of Kaungton"],["1785","Bodawpaya conquers Arakan"],["1826","Treaty of Yandabo ends the First Anglo-Burmese War"],["1857","Mindon founds Mandalay"],["1885","British forces take Mandalay; King Thibaw is exiled"]]},
  "Kingdom of Nepal": {t:["Created by Prithvi Narayan Shah of Gorkha, who conquered the Kathmandu Valley in 1768–1769.","Defeat by Britain in 1814–1816 fixed its borders; hereditary Rana prime ministers ruled in the king’s name from 1846 to 1951.","Popular movements and a Maoist insurgency ended the monarchy, which the Constituent Assembly abolished in 2008."],dyk:"Prithvi Narayan Shah called his kingdom ‘a yam between two boulders’, squeezed between China and British India, a phrase still quoted in debates on Nepal’s foreign policy.",ev:[["1768","Gorkhali troops capture Kathmandu during the Indra Jatra festival"],["1792","A Qing army forces Nepal to make peace"],["1816","Treaty of Sugauli ends the Anglo-Nepalese War"],["1846","The Kot massacre brings Jang Bahadur Rana to power"],["1854","Jang Bahadur issues the Muluki Ain law code"],["1951","King Tribhuvan ends Rana rule"],["1960","King Mahendra dismisses parliament and introduces the panchayat system"],["2008","The Constituent Assembly abolishes the monarchy"]]},
  "Rattanakosin Kingdom": {t:["Siam’s kingdom under the Chakri dynasty, ruled from Bangkok, which Rama I founded in 1782 after deposing Taksin.","It dominated the Lao states, western Cambodia and the northern Malay sultanates before European pressure forced cessions.","Mongkut and Chulalongkorn modernised the state and kept Siam independent until the 1932 revolution ended absolute rule."],dyk:"Mongkut spent 27 years as a Buddhist monk before becoming king in 1851, founding the reformist Thammayut order and studying Western astronomy.",ev:[["1782","Rama I founds the Chakri dynasty and moves the capital to Bangkok"],["1785–1786","Siam defeats Burma’s invasion in the Nine Armies War"],["1827","Siamese forces crush Anouvong’s rebellion and sack Vientiane"],["1855","The Bowring Treaty with Britain opens Siam to Western trade"],["1893","French gunboats force the Chao Phraya; Siam cedes the lands east of the Mekong"],["1905","The Slave Abolition Act completes the end of slavery"],["1917","Siam joins the First World War on the Allied side"],["1932","The People’s Party’s bloodless revolution ends absolute monarchy"]]},
  "Dutch East Indies": {t:["The colonial state formed when the Dutch government took over the VOC’s Asian possessions on 1 January 1800.","The Cultivation System of 1830 forced Javanese villages to grow export crops, making the colony highly profitable for the Netherlands.","Conquest of the outer islands by about 1910 created the borders that independent Indonesia inherited in 1949."],dyk:"Eduard Douwes Dekker, a former colonial official, attacked the Cultivation System in the 1860 novel Max Havelaar, published under the pen name Multatuli.",ev:[["1800","The Dutch state takes over the possessions of the dissolved VOC"],["1811–1816","Britain occupies Java under Thomas Stamford Raffles"],["1825–1830","Prince Diponegoro leads the Java War against Dutch rule"],["1830","Johannes van den Bosch introduces the Cultivation System"],["1873","The Dutch invade Aceh, beginning a decades-long war"],["1901","Queen Wilhelmina announces the Ethical Policy"],["1942","Japan conquers the colony; the Dutch surrender on 8 March"],["1949","The Netherlands transfers sovereignty to Indonesia on 27 December"]]},
  "Nguyen dynasty": {t:["Vietnam’s last imperial dynasty, founded by Gia Long in 1802 after he defeated the Tay Son and united the country.","Minh Mang built a centralised Confucian state on the Qing model, renamed the country Dai Nam and occupied Cambodia.","French conquest from 1858 reduced the emperors to figureheads, and Bao Dai abdicated to the Viet Minh in 1945."],dyk:"The name Viet Nam was granted by the Qing emperor Jiaqing in 1804, after Gia Long asked for Nam Viet, which recalled the ancient kingdom of Nanyue in southern China.",ev:[["1802","Nguyen Anh proclaims himself Gia Long and unites Vietnam"],["1815","The Gia Long Code, modelled on Qing law, is issued"],["1839","Minh Mang renames the country Dai Nam"],["1858","A Franco-Spanish expedition attacks Da Nang"],["1862","The Treaty of Saigon cedes three provinces of Cochinchina to France"],["1883–1884","Treaties make Annam and Tonkin French protectorates"],["1885","Emperor Ham Nghi flees Hue and the Can Vuong resistance begins"],["1945","Bao Dai abdicates to the Viet Minh on 30 August"]]},
  "British Raj": {t:["Crown rule replaced the East India Company in 1858, after the rebellion of 1857, and lasted until independence in 1947.","A viceroy ruled British provinces directly and more than 560 princely states indirectly, with the Indian Civil Service at its core.","Gandhi’s mass campaigns and the Second World War ended British rule, and partition into India and Pakistan cost hundreds of thousands of lives."],dyk:"The Indian Army of the Second World War, about 2.5 million strong, is often described as the largest all-volunteer army in history.",ev:[["1858","The Government of India Act transfers the East India Company’s territories to the Crown"],["1877","Queen Victoria is proclaimed Empress of India at the Delhi Durbar"],["1885","The Indian National Congress is founded in Bombay"],["1911","George V announces the move of the capital from Calcutta to Delhi"],["1919","Troops kill hundreds of unarmed people at the Jallianwala Bagh in Amritsar"],["1930","Gandhi leads the Salt March to Dandi"],["1942","Congress launches the Quit India movement"],["1947","Independence and partition create India and Pakistan on 14–15 August"]]},
  "French Indochina": {t:["A federation created in 1887 joining Cochinchina, Annam, Tonkin and Cambodia, with Laos added after 1893.","Rice, rubber and state monopolies on opium, salt and alcohol made it France’s most valuable Asian possession.","Japanese occupation and the First Indochina War ended French rule at Dien Bien Phu and Geneva in 1954."],dyk:"Paul Doumer, who built Indochina’s federal government and the Hanoi bridge first named after him, later became President of France and was assassinated in 1932.",ev:[["1887","France creates the Indochinese Union on 17 October"],["1893","The Franco-Siamese crisis adds the Lao lands east of the Mekong"],["1902","The seat of government moves from Saigon to Hanoi"],["1930","The Indochinese Communist Party is founded and the Yen Bai mutiny is crushed"],["1940","Japanese troops enter northern Indochina after France’s defeat"],["1945","Japan overthrows French rule; Ho Chi Minh proclaims the Democratic Republic of Vietnam"],["1946","The First Indochina War begins after fighting in Haiphong and Hanoi"],["1954","Defeat at Dien Bien Phu and the Geneva Accords end French Indochina"]]},
  "Indonesia": {t:["An archipelago of some 17,000 islands, proclaimed independent in 1945 and recognised by the Netherlands after a four-year revolution.","Sukarno\u0027s Guided Democracy gave way after the killings of 1965–1966 to Suharto\u0027s military-backed New Order.","Since 1998 Indonesia has been a decentralised democracy, a G20 economy and the most populous Muslim-majority country."],dyk:"Indonesian, the national language, was chosen in 1928 from Malay, a trading lingua franca, rather than Javanese, the mother tongue of the largest ethnic group.",ev:[["1945","Sukarno and Mohammad Hatta proclaim independence on 17 August"],["1949","The Netherlands transfers sovereignty after the Round Table Conference at The Hague"],["1955","Indonesia hosts the Asian–African Conference at Bandung"],["1965","A failed coup is followed by the mass killing of alleged communists"],["1975","Indonesian forces invade East Timor"],["1998","Suharto resigns during the Asian financial crisis"],["2004","First direct presidential election; the Indian Ocean tsunami devastates Aceh"],["2005","The Helsinki agreement ends the conflict in Aceh"]]},
  "Myanmar": {t:["Burma won independence from Britain in 1948 as a federal union of the Bamar majority and many ethnic minorities.","The army has ruled for most of the period since 1962, first through Ne Win\u0027s isolationist socialism and then through juntas.","Brief reforms after 2011 ended with the coup of 2021, which turned decades of borderland insurgency into nationwide war."],dyk:"The Burmese diplomat U Thant, a close friend of Prime Minister U Nu, served as Secretary-General of the United Nations from 1961 to 1971, the first Asian in that post.",ev:[["1947","Aung San and minority leaders agree to form a union at the Panglong Conference"],["1948","The Union of Burma becomes independent on 4 January"],["1962","General Ne Win seizes power and launches the Burmese Way to Socialism"],["1988","A nationwide uprising is crushed and a new military junta takes power"],["1990","The NLD of Aung San Suu Kyi wins an election the junta refuses to honour"],["2008","Cyclone Nargis kills about 138,000 people in the Irrawaddy delta"],["2017","Army operations drive over 700,000 Rohingya into Bangladesh"],["2021","The military seizes power on 1 February, sparking nationwide armed resistance"]]},
  "United State of Rajasthan": {t:["A union formed in stages in 1948–1950 to merge the princely states of Rajputana into the Indian Union.","The Maharana of Udaipur and the Maharaja of Jaipur held the top titles, while ministers from popular movements governed.","It became the state of Rajasthan in January 1950, today India\u0027s largest state by area."],dyk:"To soothe local rivalries, Greater Rajasthan put its capital at Jaipur but its High Court at Jodhpur, which still hosts the principal seat of the Rajasthan High Court.",ev:[["1948","Nine south-eastern states and two chiefships form a union with its capital at Kota (25 March)"],["1948","Udaipur joins and Nehru inaugurates the United State of Rajasthan (18 April)"],["1949","Jaipur, Jodhpur, Bikaner and Jaisalmer join to form Greater Rajasthan (30 March)"],["1949","The Matsya Union of Alwar, Bharatpur, Dholpur and Karauli joins (15 May)"],["1950","Sirohi joins and the union becomes the state of Rajasthan (26 January)"],["1956","Ajmer and Mount Abu are added and the office of Rajpramukh abolished"]]},
  "Republic of India": {t:["India became a republic on 26 January 1950, when the constitution drafted under B.R. Ambedkar came into force.","It has remained a parliamentary democracy, interrupted only by the Emergency of 1975–1977, with regular elections since 1951–1952.","Now the world\u0027s most populous country, it is a nuclear power and one of the five largest economies by nominal output."],dyk:"The first general election of 1951–1952 had about 173 million voters, most unable to read, so each party was given a symbol, a practice Indian elections still use.",ev:[["1950","The constitution comes into force and India becomes a republic on 26 January"],["1962","China defeats India in the Sino-Indian War"],["1971","India\u0027s victory in the Bangladesh Liberation War creates Bangladesh"],["1975","Indira Gandhi declares the Emergency, suspending civil liberties until 1977"],["1984","Operation Blue Star; Indira Gandhi assassinated; the Bhopal gas disaster"],["1991","Economic liberalisation begins after a balance-of-payments crisis"],["1998","Nuclear tests at Pokhran; India declares itself a nuclear-weapon state"],["2023","Chandrayaan-3 lands near the Moon\u0027s south pole; India hosts the G20 summit"]]},
  "Malaysia": {t:["Malaysia was formed on 16 September 1963 from Malaya, Singapore, Sabah and Sarawak; Singapore left in 1965.","Its king is elected every five years from nine hereditary Malay rulers, a system unique in the world.","The New Economic Policy after the 1969 riots reshaped wealth between ethnic groups as the economy industrialised rapidly."],dyk:"Malaysia\u0027s head of state, the Yang di-Pertuan Agong, is chosen by secret ballot of the nine hereditary Malay rulers, who have largely followed a fixed rotation since 1957.",ev:[["1963","Malaysia is proclaimed on 16 September; Indonesia steps up its Confrontation"],["1965","Singapore is separated from the federation on 9 August"],["1969","Racial riots of 13 May lead to emergency rule and the New Economic Policy"],["1981","Mahathir Mohamad becomes prime minister, serving until 2003"],["1998","Capital controls and the dismissal of Anwar Ibrahim spark the Reformasi movement"],["2018","The Barisan Nasional loses power for the first time since independence"],["2022","Anwar Ibrahim becomes prime minister of a unity government"]]},
  "Socialist Republic of Vietnam": {t:["Vietnam was reunified as a socialist republic on 2 July 1976, a year after the fall of Saigon, with Hanoi as capital.","Wars with Cambodia and China and failed collectivisation left it isolated and poor until the Doi Moi reforms of 1986.","Under one-party rule it became a major exporter of rice, coffee and electronics and a significant Asian middle power."],dyk:"Within three years of the Doi Moi reforms, Vietnam turned from a country that had to import rice into one of the world’s largest rice exporters.",ev:[["1976","The Socialist Republic of Vietnam is proclaimed and Saigon renamed Ho Chi Minh City"],["1978","Vietnam invades Cambodia and overthrows the Khmer Rouge in January 1979"],["1979","China attacks across the northern border in the Sino-Vietnamese War"],["1986","The Sixth Party Congress adopts the Doi Moi market reforms"],["1989","The last Vietnamese troops withdraw from Cambodia"],["1995","Vietnam normalises relations with the United States and joins ASEAN"],["2007","Vietnam joins the World Trade Organization"],["2023","Ties with the United States are raised to a comprehensive strategic partnership"]]},
  "Hausa kingdoms": {t:["A group of walled city-kingdoms in northern Nigeria and southern Niger, including Kano, Katsina, Zazzau, Daura and Gobir.","They never united, but shared a language, court institutions and a trade network linking the Sahara and the forest.","The jihad of Usman dan Fodio (1804–1808) replaced their dynasties with the Fulani emirates of the Sokoto Caliphate."],dyk:"The fine goatskin leather sold in Europe as ‘Morocco leather’ was largely tanned and dyed by Hausa craftsmen and carried across the Sahara.",ev:[["c. 999","Bagauda becomes the first king of Kano, according to the Kano Chronicle"],["14th century","Wangarawa merchants bring Islam to Kano under Sarki Yaji"],["c. 1463","Muhammad Rumfa becomes king of Kano and reforms its government"],["c. 1516","Kanta Kotal of Kebbi throws off Songhai rule"],["c. 1762","Gobir destroys Birnin Zamfara, the capital of Zamfara"],["1804","Usman dan Fodio’s followers defeat Gobir at Tabkin Kwotto"],["1808","Alkalawa falls and Sarki Yunfa of Gobir is killed"]]},
  "Mombasa": {t:["A Muslim Swahili city-state on an island with a deep harbour, trading ivory and gold for Indian cloth and Chinese porcelain.","Ibn Battuta visited in 1331; by 1500 it was among the largest and richest towns on the East African coast.","It resisted the Portuguese for nearly a century until they built Fort Jesus and took control in 1593."],dyk:"Ibn Battuta noted that Mombasa’s people grew no grain on the island: they lived on bananas and fish and brought their grain from the Swahili mainland.",ev:[["1150s","Al-Idrisi mentions Mombasa as a small town on the coast of the Zanj"],["1331","Ibn Battuta visits and describes Mombasa’s wooden mosques"],["1498","Mombasa’s rulers try to seize Vasco da Gama’s ships"],["1505","Francisco de Almeida sacks and burns the town"],["1528","Nuno da Cunha attacks and burns Mombasa again"],["1589","The Portuguese capture Mir Ali Bey and the Zimba massacre the inhabitants"],["1593","The Portuguese begin Fort Jesus and install the ruler of Malindi as sultan"]]},
  "Ajuran Sultanate": {t:["A Somali Muslim state ruled by the Garen lineage, which claimed holy Arab descent, in the land between the Shabelle and Jubba rivers.","Its power rested on control of wells and river water, which it used to levy tribute from herders and farmers.","Revolts in the late 17th century broke it up, and the Hiraab Imamate and the Geledi took over its lands."],dyk:"Many old stone-lined wells across southern Somalia are still attributed by local tradition to the Ajuran, centuries after the sultanate disappeared.",ev:[["13th century","The Ajuran confederation begins to form under the Garen lineage, according to tradition"],["1331","Ibn Battuta visits Mogadishu and praises its cloth trade"],["1499","Vasco da Gama bombards Mogadishu"],["1507","A Portuguese fleet sacks Barawa"],["1580s","The Ottoman corsair Mir Ali Bey wins support on the Benadir coast"],["late 17th century","Revolts led by Hawiye clans break Ajuran power"],["c. 1700","The Hiraab Imamate and the Geledi replace the Ajuran"]]},
  "Kingdom of Buganda": {t:["A kingdom on the northern shore of Lake Victoria that rose from a small state to the dominant power of the Great Lakes by 1800.","Its kabakas ruled through appointed chiefs, with a council, a chief minister and a fleet of war canoes on the lake.","Buganda gave its name to Uganda; abolished in 1967, the monarchy was restored as a cultural institution in 1993."],dyk:"Because princes belonged to their mothers’ clans, the Ganda royal family had no clan of its own, and any clan could hope to provide a future kabaka.",ev:[["c. 1780","Kabakas Junju and Semakookiro conquer the province of Buddu from Bunyoro"],["1862","John Hanning Speke reaches the court of Mutesa I"],["1877","The first Protestant missionaries arrive in Buganda"],["1886","Christian converts are executed at Namugongo on the orders of Mwanga II"],["1892","Protestants defeat Catholics at the Battle of Mengo"],["1900","The Buganda Agreement makes the kingdom a privileged part of the Uganda Protectorate"],["1966","Troops under Idi Amin storm the kabaka’s palace at Mengo"],["1967","Uganda’s new constitution abolishes the kingdoms"]]},
  "Kingdom of Rwanda": {t:["A Great Lakes kingdom ruled by the Nyiginya dynasty, whose sacred mwami governed through army, land and cattle chiefs.","It reached its greatest extent and centralisation under Kigeli IV Rwabugiri in the late nineteenth century.","German and Belgian rule hardened Hutu and Tutsi into fixed categories; the monarchy was abolished in 1961."],dyk:"Rwanda had no fixed capital for most of its history: the royal court moved between residences, Nyanza became the permanent seat only around 1899, and Kigali began as a German residency in 1907.",ev:[["c. 1650","Ruganzu II Ndori establishes the Nyiginya kingdom in central Rwanda"],["c. 1850s","Mutara II Rwogera annexes the Kingdom of Gisaka"],["1895","Kigeli IV Rwabugiri dies on campaign after decades of expansion"],["1896","The Coup of Rucunshu brings Yuhi V Musinga to the throne"],["1897","Rwanda accepts German protection and joins German East Africa"],["1931","Belgium deposes Musinga and installs Mutara III Rudahigwa"],["1959","Mutara III dies and the Hutu revolution begins"],["1961","A UN-supervised referendum confirms the abolition of the monarchy"]]},
  "Kingdom of Ankole": {t:["A cattle kingdom of south-western Uganda ruled by the Hinda dynasty, whose kingship was embodied in the royal drum Bagyendanwa.","Its society was divided between Bahima herders, who held power, and Bairu farmers, who formed the majority.","The 1901 Ankole Agreement enlarged it under British rule; it was abolished in 1967 and never restored."],dyk:"In Nkore the kingship was embodied in the royal drum Bagyendanwa, which had its own shrine, attendants and herds, and a king\u0027s sons traditionally fought one another for the throne.",ev:[["c. 1500","Ruhinda traditionally founds the Hinda dynasty of Nkore"],["late 1600s","Ntare IV Kitabanyoro repels an invasion from Bunyoro"],["c. 1870s","Ntare V becomes king and extends Nkore\u0027s influence over its neighbours"],["c. 1891","Rinderpest destroys most of the kingdom\u0027s cattle"],["1895","Ntare V dies; Kahaya II is installed with Nuwa Mbaguta\u0027s support"],["1901","The Ankole Agreement enlarges the kingdom within the Uganda Protectorate"],["1944","Charles Gasyonga II succeeds Kahaya II"],["1967","Uganda\u0027s new constitution abolishes the kingdom"]]},
  "Kingdom of Bunyoro": {t:["A Great Lakes kingdom founded around 1500 by the Luo-speaking Babito dynasty, which claimed the heritage of ancient Kitara.","Its salt and iron made it rich, and in the sixteenth and seventeenth centuries its armies dominated the region.","Omukama Kabalega rebuilt its power but was defeated by Britain in 1899; Bunyoro is today a cultural kingdom."],dyk:"Kabalega was captured in 1899 together with Mwanga, the deposed king of Buganda, a long-time rival who had become his ally; the British exiled both men to the Seychelles.",ev:[["c. 1500","Babito rulers from the north take over the lands of the Chwezi kingdom of Kitara"],["c. 1830","Kaboyo Olimi breaks away to found the Kingdom of Toro"],["1870","Kabalega wins the throne and builds the standing abarusura army"],["1872","Kabalega forces Samuel Baker to retreat after fighting at Masindi"],["1893","British and Ganda forces invade Bunyoro"],["1899","Kabalega is captured in Lango and exiled to the Seychelles"],["1964","A referendum returns two \u0027lost counties\u0027 from Buganda to Bunyoro"],["1967","The monarchy is abolished; it is restored as a cultural institution in 1993"]]},
  "Merina Kingdom": {t:["A highland kingdom of central Madagascar, reunited by Andrianampoinimerina, who made Antananarivo its capital around 1794.","Radama I\u0027s alliance with Britain from 1817 let it conquer much of the island as the Kingdom of Madagascar.","France invaded in 1883–85 and 1895 and abolished the monarchy in 1897, exiling Queen Ranavalona III."],dyk:"Merina markets used Spanish and French silver dollars cut into small fragments and weighed on tiny scales, rather than counted as whole coins.",ev:[["c. 1540","Andriamanelo traditionally founds the Merina royal line"],["c. 1787","Andrianampoinimerina seizes power at Ambohimanga and begins reuniting Imerina"],["1817","Radama I\u0027s treaty with Britain ends slave exports and brings arms and training"],["1835","Ranavalona I bans Christianity; the Malagasy Bible is published"],["1869","Ranavalona II and Rainilaiarivony are baptised; the royal talismans are burned"],["1881","The Code of 305 Articles is promulgated"],["1895","French troops under General Duchesne take Antananarivo"],["1897","France abolishes the monarchy and exiles Ranavalona III"]]},
  "Kingdom of Dahomey": {t:["A Fon kingdom of the Abomey plateau in present-day Benin, founded in the seventeenth century by a branch of Allada\u0027s dynasty.","It became a major supplier of the Atlantic slave trade after conquering the port of Whydah in 1727.","Its women soldiers fought France in 1890–94, but Abomey fell in 1892 and the kingdom was absorbed by 1904."],dyk:"Dahomey\u0027s women soldiers included a unit of \u0027reapers\u0027 armed with long razors; Europeans called the corps the Amazons, while the Fon called them mino, \u0027our mothers\u0027.",ev:[["c. 1645","Houegbadja founds the kingdom and builds the first palace at Abomey"],["1724","Agaja conquers the Kingdom of Allada"],["1727","Dahomey conquers Whydah, the leading slave-trading port of the coast"],["c. 1730","After Oyo invasions, Dahomey becomes a tributary of the Oyo Empire"],["1818","Ghezo overthrows Adandozan and revives royal power"],["1851","A Dahomean assault on Abeokuta is repulsed with heavy losses"],["1892","French troops under Colonel Dodds take Abomey"],["1894","Behanzin surrenders and is exiled to Martinique"]]},
  "Barotseland": {t:["A Lozi kingdom on the upper Zambezi floodplain, ruled by the Litunga with a princess-chief governing the south from Nalolo.","Kololo invaders from the south ruled the floodplain for a generation until the Lozi restored their kingdom in 1864.","Lewanika’s treaties with Rhodes’s company kept Barotseland’s king and councils alive under British rule until 1964."],dyk:"Silozi, the language of the Lozi kingdom, is mainly derived from Sotho, the speech of the Kololo who ruled the floodplain for only about 25 years.",ev:[["c. 1780","Mulambwa becomes Litunga and extends the kingdom’s tribute over neighbouring peoples"],["c. 1840","The Kololo under Sebitwane conquer the floodplain"],["1864","Sipopa leads a Lozi rising that ends Kololo rule"],["1878","Lubosi, later called Lewanika, becomes Litunga"],["1890","Lewanika signs the Lochner Concession with the British South Africa Company"],["1905","Italian arbitration fixes the border with Angola, cutting off western lands"],["1964","The Barotseland Agreement brings the kingdom into independent Zambia"],["1969","Zambia abrogates the agreement and renames the area Western Province"]]},
  "Swazi Kingdom": {t:["A Nguni kingdom built by the Dlamini dynasty under Sobhuza I and Mswati II, the king after whom the Swazi are named.","The king (Ngwenyama) rules alongside the queen mother (Ndlovukati), and kingship is renewed each year in the Incwala.","After concessions, Boer and British rule, it regained independence in 1968 and remains one of the world’s last absolute monarchies."],dyk:"Sobhuza II reigned from 1899, when he was a few months old, until 1982, one of the longest reigns of any monarch in recorded history.",ev:[["c. 1745","The Dlamini under Ngwane III settle near the lower Pongola river"],["c. 1820","Sobhuza I moves north to the Ezulwini valley under Ndwandwe pressure"],["c. 1840","Mswati II begins his reign and builds the age-regiment system"],["1894","Swaziland becomes a protectorate of the South African Republic"],["1907","The Partition Proclamation leaves the Swazi only about a third of their land"],["1968","Swaziland becomes independent under Sobhuza II"],["1973","Sobhuza II repeals the constitution and bans political parties"],["2018","Mswati III renames the country the Kingdom of Eswatini"]]},
  "Cape Colony": {t:["Britain seized the Dutch Cape in 1795 to guard the route to India and kept it permanently from 1806.","Frontier wars against the Xhosa, the end of slavery in 1834 and the Great Trek shaped the colony and the whole region.","Self-governing from 1872 and enriched by diamonds, it became the Cape Province of the Union of South Africa in 1910."],dyk:"From 1853 the Cape franchise was based on property or income, not race, so some Black and Coloured men could vote; that right was removed in 1936 and 1956.",ev:[["1795","British forces take the Cape after the Battle of Muizenberg"],["1806","Britain reoccupies the colony after the Battle of Blaauwberg"],["1820","About 4,000 British settlers arrive in the Eastern Cape"],["1834","Slavery is abolished across the colony"],["1853","A parliament is elected on a non-racial property franchise"],["1872","The Cape receives responsible government under John Molteno"],["1890","Cecil Rhodes becomes prime minister of the Cape"],["1910","The colony becomes the Cape Province of the Union of South Africa"]]},
  "Zulu Kingdom": {t:["Shaka turned a small chiefdom into the strongest state in southeastern Africa between 1816 and 1828.","Its power rested on age-regiments (amabutho) of young men bound to the king and on royal control of cattle.","The Zulu routed a British force at Isandlwana in 1879 but were defeated at Ulundi, and Britain annexed Zululand in 1887."],dyk:"Zulu regiments could marry only with the king’s permission, often granted when the men were in their late thirties, giving the king control over new households.",ev:[["1816","Shaka seizes leadership of the Zulu chiefdom with Mthethwa support"],["c. 1819","Shaka defeats the Ndwandwe at the Mhlatuze river"],["1828","Shaka is assassinated at Dukuza by his half-brothers Dingane and Mhlangana"],["1838","Boer forces defeat Dingane’s army at the Battle of Blood River"],["1856","Cetshwayo defeats his brother Mbuyazi at the Battle of Ndondakusuka"],["1879","The Zulu win at Isandlwana but are defeated at Ulundi"],["1883","Cetshwayo is restored to part of Zululand; civil war follows"],["1887","Britain annexes Zululand as a British colony"]]},
  "Liberia": {t:["Founded by African American settlers, Liberia became Africa’s first republic on 26 July 1847.","With Ethiopia, it was one of only two African states to escape European colonisation during the partition of Africa.","A settler elite ruled until Samuel Doe’s coup in 1980, which was followed by civil wars from 1989 to 2003."],dyk:"Liberia runs one of the world’s largest ship registries: thousands of foreign-owned merchant ships sail under its flag of convenience, a system set up in 1948.",ev:[["1822","American Colonization Society settlers land at Cape Mesurado, later Monrovia"],["1847","Liberia declares independence under President Joseph Jenkins Roberts"],["1926","Firestone receives a vast rubber concession"],["1930","A forced labour scandal forces President Charles King to resign"],["1944","William Tubman begins a presidency lasting until 1971"],["1980","Samuel Doe’s coup ends True Whig Party rule"],["1989","Charles Taylor’s invasion starts the first Liberian civil war"],["2006","Ellen Johnson Sirleaf becomes Africa’s first elected female head of state"]]},
  "South African Republic": {t:["A Boer republic north of the Vaal River, founded by Voortrekkers and recognised by Britain in the Sand River Convention of 1852.","Gold found on the Witwatersrand in 1886 made it the richest state in Africa and created the city of Johannesburg.","Conflict with Britain over the gold fields and the rights of foreign uitlanders led to the Second Boer War and its end in 1902."],dyk:"Pretoria was named after the Voortrekker leader Andries Pretorius by his son Marthinus Wessel Pretorius, who founded the town in 1855 and became the republic’s first president.",ev:[["1852","The Sand River Convention recognises Boer independence north of the Vaal"],["1860","Pretoria becomes the seat of government"],["1877","Britain annexes the bankrupt republic"],["1881","The Boers defeat a British force at Majuba Hill and regain self-government"],["1886","Gold is discovered on the Witwatersrand and Johannesburg is founded"],["1896","The Jameson Raid ends in surrender at Doornkop"],["1899","The Second Boer War begins after a Transvaal ultimatum expires"],["1902","The Treaty of Vereeniging makes the republic the Transvaal Colony"]]},
  "Orange Free State": {t:["A Boer republic between the Orange and Vaal rivers, recognised by Britain in the Bloemfontein Convention of 1854.","Its orderly constitution and long presidency of Johannes Brand earned it the name of a model republic.","Wars with the Basotho won it fertile land, but its alliance with the Transvaal led to its conquest in the Second Boer War."],dyk:"After Britain took the diamond fields of Griqualand West in 1871, the Free State settled the quarrel peacefully: President Brand accepted £90,000 in compensation in 1876.",ev:[["1848","Britain defeats Boers under Andries Pretorius at Boomplaats and rules the Orange River Sovereignty"],["1854","The Bloemfontein Convention recognises the independence of the Orange Free State"],["1866","Moshoeshoe cedes land west of the Caledon River in the Treaty of Thaba Bosiu"],["1871","Britain annexes the diamond fields of Griqualand West"],["1897","Defensive alliance with the South African Republic"],["1900","Bloemfontein falls to Lord Roberts and Britain annexes the state as the Orange River Colony"],["1902","The Treaty of Vereeniging ends the Second Boer War and the republic"]]},
  "Sultanate of Zanzibar": {t:["An Omani Arab sultanate on Zanzibar and Pemba, separated from Oman when Sayyid Said’s realm was divided in 1856.","Clove plantations, ivory caravans and the slave market made Zanzibar the commercial capital of East Africa.","European partition stripped its mainland claims; it became a British protectorate in 1890 and fell in the revolution of 1964."],dyk:"The Anglo-Zanzibar War of 27 August 1896 is often called the shortest war in recorded history: the British bombardment of the sultan’s palace lasted less than an hour.",ev:[["1856","Majid bin Said becomes sultan of Zanzibar on the division of Sayyid Said’s realm"],["1861","The Canning Award confirms Zanzibar’s separation from Oman"],["1873","Barghash closes the Zanzibar slave market under British pressure"],["1885","A German squadron forces Barghash to recognise German claims on the mainland"],["1890","Zanzibar and Pemba become a British protectorate"],["1896","The Anglo-Zanzibar War ends in under an hour"],["1963","Zanzibar becomes independent under Sultan Jamshid bin Abdullah"],["1964","The Zanzibar Revolution overthrows the sultan; union with Tanganyika follows"]]},
  "Congo Free State": {t:["A state owned personally by King Leopold II of Belgium, recognised at the Berlin Conference and proclaimed in 1885.","Forced collection of wild rubber, enforced by the Force Publique through hostage-taking and mutilation, caused mass death.","An international campaign led by Roger Casement and E. D. Morel forced Belgium to annex it as the Belgian Congo in 1908."],dyk:"Leopold II ruled the Congo Free State for twenty-three years without ever setting foot in it, governing by decree from Brussels.",ev:[["1879","Henry Morton Stanley begins building stations on the Congo River for Leopold"],["1885","Leopold proclaims the Congo Free State after the Berlin Conference"],["1891","The Yeke king Msiri is killed and Katanga is secured for the state"],["1894","The Force Publique defeats the Swahili-Arab traders of the eastern Congo"],["1898","The Matadi–Léopoldville railway is completed"],["1904","Roger Casement’s report is published and the Congo Reform Association is founded"],["1908","Belgium annexes the territory as the Belgian Congo"]]},
  "French West Africa": {t:["A federation of French colonies in West Africa, governed from Saint-Louis and from 1902 from Dakar by a governor-general.","It ruled most Africans as subjects under the indigénat code, with forced labour, head tax and conscription into the tirailleurs.","Post-war reforms shifted power to the territories, and the federation dissolved in 1958–1959 as eight states moved to independence."],dyk:"Despite their name, the tirailleurs sénégalais were recruited from across French West Africa, and many came from present-day Mali, Burkina Faso and Guinea rather than Senegal.",ev:[["1895","A governor-general is created for France’s West African colonies at Saint-Louis"],["1904","Ernest Roume’s decree gives the federation its own administration and budget in Dakar"],["1918","Blaise Diagne leads a recruitment drive for the First World War"],["1940","Vichy forces repel a British and Free French attack on Dakar"],["1944","French troops fire on tirailleurs at the Thiaroye camp near Dakar"],["1946","The indigénat and forced labour are abolished and Africans become citizens"],["1956","The loi-cadre Defferre gives power to elected territorial assemblies"],["1958","Guinea votes for independence; the federation is wound up"]]},
  "Union of South Africa": {t:["A self-governing British dominion formed on 31 May 1910 from the Cape, Natal, Transvaal and Orange River colonies.","Its gold mines, migrant labour system and land laws built Africa’s strongest economy on racial segregation.","It fought in both world wars, gained full sovereignty in 1931 and became the apartheid republic in 1961."],dyk:"The Union had three capitals: Pretoria for the government, Cape Town for parliament and Bloemfontein for the Appellate Division, a compromise South Africa still keeps.",ev:[["1910","The Union of South Africa is proclaimed, with Louis Botha as prime minister"],["1912","The South African Native National Congress, later the ANC, is founded at Bloemfontein"],["1913","The Natives Land Act restricts African land ownership to reserves"],["1915","South African forces conquer German South West Africa"],["1931","The Statute of Westminster confirms the Union’s legislative independence"],["1948","D. F. Malan’s National Party wins power and begins apartheid"],["1960","Police kill 69 protesters at Sharpeville; white voters approve a republic"],["1961","The Union becomes the Republic of South Africa on 31 May"]]},
  "Republic of South Africa": {t:["The Union of South Africa became a republic on 31 May 1961 and left the Commonwealth under Hendrik Verwoerd.","For three decades it enforced grand apartheid, created ethnic homelands and fought a border war in Namibia and Angola.","Negotiations from 1990 led to the 1994 elections, Nelson Mandela’s presidency and the democratic constitution of 1996."],dyk:"South Africa built six nuclear weapons in the 1980s and dismantled them around 1990–1991, the first country to give up a nuclear arsenal it had developed itself.",ev:[["1961","The Union becomes the Republic of South Africa and leaves the Commonwealth"],["1964","Nelson Mandela is sentenced to life imprisonment at the end of the Rivonia Trial"],["1976","Police fire on protesting students in Soweto, setting off a national uprising"],["1990","F. W. de Klerk unbans the ANC; Mandela is released after 27 years in prison"],["1994","The first democratic elections make Nelson Mandela president"],["1996","A new constitution with a Bill of Rights is adopted"],["2012","Police kill 34 striking miners at Marikana"],["2024","The ANC loses its majority and forms a Government of National Unity"]]},
  "Uganda": {t:["Uganda became independent in 1962 as a quasi-federal state built around Buganda and the other Great Lakes kingdoms.","Obote abolished the kingdoms in 1967, and Idi Amin’s rule of 1971–1979 killed an estimated 100,000 or more people.","Yoweri Museveni, in power since 1986, restored order and growth and brought back the kingdoms as cultural institutions in 1993."],dyk:"Rwandan exiles who fought in Museveni’s National Resistance Army, among them Paul Kagame, went on to lead the Rwandan Patriotic Front, which invaded Rwanda from Uganda in 1990.",ev:[["1962","Uganda becomes independent on 9 October under Prime Minister Milton Obote"],["1966","Troops under Idi Amin storm the Kabaka’s palace at Mengo"],["1967","A republican constitution abolishes the kingdoms"],["1971","Idi Amin seizes power in a military coup"],["1972","Amin expels the country’s Asian community"],["1979","Tanzanian forces and Ugandan exiles take Kampala and overthrow Amin"],["1986","The National Resistance Army takes Kampala and Museveni becomes president"],["1993","The kingdoms are restored as cultural institutions"]]},
  "Tanzania": {t:["Tanzania was created on 26 April 1964 by the union of mainland Tanganyika and the islands of Zanzibar.","Julius Nyerere’s Arusha Declaration of 1967 made it Africa’s best-known experiment in socialism, known as ujamaa.","It has had no successful coup or civil war, and Swahili gives it one of the strongest national identities in Africa."],dyk:"Julius Nyerere translated Shakespeare’s Julius Caesar and The Merchant of Venice into Swahili, part of his effort to make Swahili a language of national culture.",ev:[["1964","Tanganyika and Zanzibar unite on 26 April; the name Tanzania is adopted in October"],["1967","The Arusha Declaration launches ujamaa socialism"],["1973","Dodoma is designated the future capital"],["1975","The Tanzania–Zambia Railway is completed"],["1977","TANU and the Afro-Shirazi Party merge as Chama Cha Mapinduzi"],["1979","Tanzanian forces capture Kampala and overthrow Idi Amin"],["1992","Opposition parties are legalised"],["2021","Samia Suluhu Hassan becomes the first woman president"]]},
  "Republic of Somaliland": {t:["A self-declared republic in former British Somaliland, which broke away from Somalia on 18 May 1991.","It built peace through clan conferences and combines an elected president and parliament with a house of elders.","It has its own army, currency and passports and holds competitive elections, but recognition remains very limited."],dyk:"In 1960 British Somaliland was independent for only five days, from 26 June to 1 July, before uniting with Somalia; Somaliland’s claim rests on that brief statehood.",ev:[["1960","British Somaliland is independent for five days, then unites with Somalia"],["1988","Government forces bombard Hargeisa and Burao in the war with the SNM"],["1991","Independence is declared at Burao on 18 May"],["1993","The Borama conference chooses Muhammad Haji Ibrahim Egal as president"],["2001","A referendum approves the constitution and independence"],["2010","Silanyo defeats the incumbent president and power passes peacefully"],["2023","Somaliland forces are driven from positions around Las Anod"],["2025","Israel becomes the first UN member state to recognise Somaliland"]]},
  "Akkadian": {t:["Akkadian, the oldest recorded Semitic language, was the language of the empires of Akkad, Babylon and Assyria, written in cuneiform for more than two and a half thousand years.","In the 2nd millennium BCE it was the international language of diplomacy, used in the letters exchanged between the pharaohs of Egypt and the kings of the Near East.","Its literature, from the Epic of Gilgamesh and the Babylonian creation epic to the laws of Hammurabi, and its records of astronomy, medicine and mathematics were recovered when scholars deciphered cuneiform in the 19th century."],dyk:"In 1857 the Royal Asiatic Society sent copies of a newly found Assyrian inscription to four scholars, who translated it independently; their versions agreed so closely that the decipherment of Akkadian cuneiform was accepted as proved.",ev:[["c. 2300 BCE","Sargon of Akkad unites Mesopotamia and makes Akkadian a language of empire"],["c. 1754 BCE","Hammurabi of Babylon has his laws inscribed in Akkadian on stone stelae"],["14th century BCE","The Amarna letters show Akkadian as the language of diplomacy between Egypt and the kingdoms of the Near East"],["7th century BCE","Ashurbanipal gathers his library of cuneiform tablets at Nineveh"],["539 BCE","Cyrus the Great takes Babylon and records his conquest in Akkadian on the Cyrus Cylinder"],["c. 80","The last datable cuneiform tablet, an astronomical almanac, is written at Uruk"],["1857","Four scholars independently translate an Assyrian inscription, proving the decipherment"],["2010","The Chicago Assyrian Dictionary is completed after nearly ninety years of work"]]},
  "Ancient Egyptian": {t:["Egyptian, the language of the pharaohs, is with Sumerian one of the two earliest written languages, and its records span more than four thousand years, from the first hieroglyphs to Coptic.","It was written in hieroglyphs, a script of pictures standing for sounds and ideas, and in the faster hieratic and demotic, until the Christian Egyptians adopted the Coptic alphabet, based on Greek.","Forgotten after the last hieroglyphs were carved in 394, the script was deciphered by Jean-François Champollion in 1822 with the help of the Rosetta Stone, reopening the history and literature of ancient Egypt."],dyk:"English words such as ebony, oasis and gum come from ancient Egyptian through Greek, and adobe, the sun-dried brick, travelled from Egyptian through Coptic, Arabic and Spanish.",ev:[["c. 3250 BCE","Bone labels in a royal tomb at Abydos carry the earliest known Egyptian writing"],["c. 2700 BCE","A seal of King Peribsen bears the earliest known complete sentence in Egyptian"],["c. 2350 BCE","The Pyramid Texts, the oldest long religious texts in Egyptian, are carved in the pyramid of Unas"],["c. 1900 BCE","The Story of Sinuhe, a classic of Middle Egyptian literature, is composed"],["196 BCE","A decree of Ptolemy V is inscribed in hieroglyphs, demotic and Greek on the Rosetta Stone"],["394","The last known hieroglyphic inscription is carved at the temple of Philae"],["452","The last known inscription in demotic is written at Philae"],["1822","Jean-François Champollion announces the decipherment of hieroglyphs"]]},
  "Arabic": {t:["Arabic, first recorded in inscriptions of the Arabian peninsula and its desert borderlands, became a world language with the Qur’an and the Islamic conquests of the 7th century.","As the language of the caliphates it carried philosophy, science, medicine and mathematics, translated from Greek, Persian and Sanskrit and developed by scholars from Spain to Central Asia, and its literature is one of the richest in the world.","Today spoken by some 400 million people in a family of varieties, with a shared standard written language, it is the language of prayer for Muslims everywhere and has lent words from algebra to coffee to the languages of the world."],dyk:"English words such as algebra, alcohol, sugar, coffee, cotton and zero come from Arabic, and algorithm comes from the name of the 9th-century Baghdad mathematician al-Khwarizmi.",ev:[["853 BCE","An Assyrian inscription names “Gindibu the Arab” among the enemies of Shalmaneser III, the first known mention of Arabs"],["328","The Namara inscription, the epitaph of Imru' al-Qays, “king of all the Arabs”, is carved in Arabic in Nabataean letters"],["512","The Zabad inscription, in Greek, Syriac and Arabic, is one of the oldest dated texts in the Arabic script"],["610–632","The Qur’an is revealed to Muhammad, according to Muslim belief, and becomes the first book in Arabic"],["c. 700","The Umayyad caliph Abd al-Malik makes Arabic the language of government"],["Late 8th century","Sibawayh writes the first comprehensive grammar of Arabic"],["c. 820","Al-Khwarizmi writes his book on algebra in Baghdad"],["1973","Arabic becomes an official language of the United Nations"]]},
  "Aramaic": {t:["Aramaic, first written by the Aramaean kingdoms of Syria in the 9th century BCE, became the common language of the Assyrian, Babylonian and Persian empires, used from Egypt to the borders of India.","It was the everyday language of Jesus and of the Jews of his time, the language of parts of the Bible and most of the Talmud, and, as Syriac, of one of the great literatures of Eastern Christianity.","Its alphabet is the ancestor of the Hebrew, Arabic and Syriac scripts and of many others in Asia, and its modern forms are still spoken by Assyrian, Chaldean, Syriac, Jewish and Mandaean communities, though they are endangered."],dyk:"In the Syrian village of Maaloula and two villages nearby, people still speak Western Neo-Aramaic, the last living form of the western branch of Aramaic, to which the dialect of Jesus’ Galilee belonged.",ev:[["c. 850 BCE","A statue at Tell Fekheriye in Syria carries one of the oldest Aramaic inscriptions, beside an Akkadian text"],["8th century BCE","The Assyrian empire uses Aramaic beside Akkadian, spreading it across the Near East"],["5th century BCE","Papyri of the Jewish garrison at Elephantine in Egypt record the Aramaic of the Persian empire"],["c. 260 BCE","The Indian emperor Ashoka has an edict inscribed in Greek and Aramaic at Kandahar"],["1st century","Jesus and his disciples speak Aramaic in Galilee"],["c. 500","The Babylonian Talmud, written largely in Aramaic, takes shape"],["7th century","After the Arab conquests, Arabic begins to replace Aramaic across the Near East"],["2014","The advance of the Islamic State drives Aramaic-speaking Christians from their towns in northern Iraq"]]},
  "Bahá'í Faith": {t:["The Bahá’í Faith grew from the movement of the Báb, a merchant of Shiraz who in 1844 proclaimed a new revelation, and from the mission of Bahá’u’lláh, who in 1863 declared himself the messenger of God whom the Báb had foretold.","It teaches that the founders of the great religions were messengers of one God, and that humanity must unite in a peaceful world order, with the equality of women and men, universal education and the harmony of science and religion.","Persecuted in Iran from its beginnings to the present day, it spread from its founders’ places of exile in the Ottoman Empire to almost every country, with its world centre in Haifa and Acre."],dyk:"The Bahá’í calendar has nineteen months of nineteen days; during the last month, in March, Bahá’ís fast from sunrise to sunset before celebrating their New Year, Naw-Rúz, at the spring equinox.",ev:[["1844","The Báb declares his mission in Shiraz"],["1850","The Báb is executed by a firing squad in Tabriz"],["1863","Bahá’u’lláh declares his mission in the Garden of Ridván in Baghdad"],["1868","Bahá’u’lláh is exiled to the Ottoman prison city of Acre"],["1892","Bahá’u’lláh dies near Acre; his son ʻAbdu’l-Bahá leads the faith"],["1912","ʻAbdu’l-Bahá travels across North America, speaking in churches, synagogues and universities"],["1963","The Universal House of Justice, the faith’s governing body, is elected for the first time"],["1980s","More than two hundred Bahá’ís are executed or killed in Iran in the years after the Islamic Revolution"]]},
  "Buddhism": {t:["Buddhism grew from the teaching of Siddhartha Gautama, the Buddha, in north-east India in the 5th century BCE: suffering arises from craving, and a path of ethics, meditation and insight leads to its end.","Royal patrons such as Ashoka, monks and merchants carried it to Sri Lanka, Central Asia, China, Korea, Japan, Tibet and Southeast Asia, where it took the Theravada, Mahayana and Vajrayana forms.","It faded from India after about 1200 but remained a major religion of Asia, was revived in India by B. R. Ambedkar in 1956 and reached Europe and the Americas in the 20th century."],dyk:"The oldest printed book that bears a date is a Buddhist scripture: a copy of the Diamond Sutra, printed in China in 868 and found in a sealed cave at Dunhuang in 1900.",ev:[["c. 5th century BCE","Siddhartha Gautama attains awakening at Bodh Gaya and gives his first teaching at Sarnath"],["c. 260 BCE","The Mauryan emperor Ashoka turns to the Buddha’s teaching and promotes it across his empire"],["1st century BCE","The Pali Canon is written down in Sri Lanka, by tradition at the Aluvihara monastery"],["1st century CE","Buddhism reaches China along the trade routes of Central Asia"],["538 or 552","Buddhism is brought to Japan from the Korean kingdom of Baekje"],["c. 779","Samye, the first Buddhist monastery in Tibet, is consecrated"],["c. 1200","The great monastery of Nalanda is sacked, and Buddhism fades from most of India"],["1956","B. R. Ambedkar and hundreds of thousands of his followers become Buddhists at Nagpur"]]},
  "Christianity": {t:["Christianity began among the followers of Jesus of Nazareth, a Jewish teacher crucified in Jerusalem around 30 CE, whom they proclaimed risen from the dead, the Messiah and the Son of God.","Spread by apostles such as Paul across the Roman Empire, it survived persecution, became the empire’s religion under Constantine and Theodosius in the 4th century and shaped the civilisation of Europe.","Divided between East and West in 1054 and again by the Reformation in the 16th century, it spread worldwide with missions and empires and is today the largest religion, with about 2.3 billion followers."],dyk:"The custom of counting years from the birth of Christ, “anno Domini”, was devised by the monk Dionysius Exiguus in 525; he probably placed the birth a few years too late, which is why historians date it to about 6–4 BCE.",ev:[["c. 30","Jesus of Nazareth is crucified in Jerusalem under the Roman governor Pontius Pilate"],["c. 50–60","The apostle Paul writes his letters to the churches, the earliest Christian texts"],["313","Constantine and Licinius grant Christians freedom of worship, the so-called Edict of Milan"],["325","The Council of Nicaea, called by Constantine, defines the faith in the Nicene Creed"],["380","Theodosius I makes Nicene Christianity the religion of the Roman Empire"],["1054","The Great Schism divides the Latin West from the Greek East"],["1517","Martin Luther’s Ninety-five Theses begin the Protestant Reformation"],["1962–1965","The Second Vatican Council reforms the Catholic Church"]]},
  "Classical Chinese": {t:["Classical Chinese, the written language of Confucius, the philosophers and the historians of ancient China, remained the standard written language of China for more than two thousand years, long after the spoken language had changed beyond recognition.","Written in characters that record meaning as well as sound, it was read across East Asia: Korea, Japan and Vietnam used it for government, scholarship and literature, each reading it with its own pronunciation.","Replaced by the vernacular in the 20th century, it remains the foundation of Chinese literature and idiom and is still studied in schools throughout East Asia."],dyk:"Because Chinese characters convey meaning whatever their pronunciation, scholars from China, Korea, Japan and Vietnam who could not speak each other’s languages could converse by writing Classical Chinese on paper, a practice known as “brush talk”.",ev:[["c. 1250 BCE","Diviners of the Shang kings carve the earliest known Chinese writing on oracle bones at Anyang"],["5th–3rd centuries BCE","The Analects, the Mencius and the Zhuangzi set the model of the classical written language"],["221 BCE","The First Emperor of Qin standardises the Chinese script across his empire"],["100","Xu Shen completes the Shuowen Jiezi, the first dictionary to analyse the structure of characters"],["868","The Diamond Sutra in Chinese, the earliest dated printed book, is made in China"],["1446","King Sejong of Korea promulgates the Hangul alphabet as an alternative to Chinese characters"],["1716","The Kangxi Dictionary is completed, listing more than 47,000 characters"],["1920","China’s Ministry of Education orders primary schools to teach the vernacular instead of Classical Chinese"]]},
  "Confucianism": {t:["Confucianism grew from the teaching of Confucius, a scholar of the state of Lu who taught that a good society rests on humane, cultivated people who honour their families, observe ritual and govern by virtue.","Adopted by the Han emperors and later made the basis of the civil service examinations, it was the official orthodoxy of the Chinese empire for some two thousand years and the model of government in Korea, Japan and Vietnam.","Attacked as a cause of backwardness in the 20th century, it has revived since the 1980s, and its ideals of learning, family duty and moral government remain deeply rooted in East Asian societies."],dyk:"The descendants of Confucius have kept their family records for more than eighty generations: their genealogy is often described as the longest recorded family tree in the world.",ev:[["551 BCE","Confucius is born in the state of Lu, by the traditional date"],["479 BCE","Confucius dies; his disciples gather his sayings, later compiled as the Analects"],["c. 300 BCE","Mencius teaches that human nature is good and that rulers who oppress the people lose the mandate of Heaven"],["213 BCE","The Qin dynasty orders the burning of books, the Confucian classics among them, by the traditional account"],["136 BCE","Emperor Wu of Han establishes official chairs for the Five Classics"],["605","The Sui dynasty founds the imperial examinations, later based on the Confucian classics"],["1190","Zhu Xi publishes the Four Books with his commentaries, the core of Neo-Confucianism"],["1905","The Qing government abolishes the imperial examinations"]]},
  "Daoism": {t:["Daoism grew from the Daodejing and the Zhuangzi, works of the Warring States period which taught harmony with the Dao, the Way underlying all things, through simplicity, spontaneity and effortless action.","From 142 CE, with the Way of the Celestial Masters, it became an organised religion of priests, rituals, scriptures and gods, seeking long life and transcendence, and emperors, above all the Tang, who claimed Laozi as their ancestor, patronised it.","It shaped Chinese medicine, painting, poetry, alchemy and the martial arts, survived the persecutions of the 20th century, and its classic, the Daodejing, is one of the most translated works in world literature."],dyk:"The earliest known description of a gunpowder-like mixture comes from a Daoist alchemical text of about the mid-9th century, which warns that heating saltpetre and sulphur with honey has burnt alchemists’ hands and faces and even their houses.",ev:[["c. 300 BCE","Bamboo slips buried in a tomb at Guodian preserve the oldest known passages of the Daodejing"],["142","Zhang Daoling receives a revelation from the deified Laozi and founds the Way of the Celestial Masters"],["184","The Yellow Turban rebellion of the Way of Great Peace shakes the Han dynasty"],["442","The Northern Wei emperor Taiwu receives Daoist registers, making Daoism the religion of his state"],["666","The Tang emperor Gaozong honours Laozi, the dynasty’s claimed ancestor, as an emperor"],["1167","Wang Chongyang founds the monastic school of Complete Perfection (Quanzhen)"],["1222","The Quanzhen master Qiu Chuji meets Genghis Khan in the Hindu Kush"],["1445","The Ming court completes the printing of the Daoist Canon"]]},
  "Ancient Egyptian religion": {t:["For more than three thousand years the Egyptians worshipped many gods, among them Ra, Osiris, Isis, Horus, Amun, Ptah and Thoth, whose cult, carried out by the pharaoh and the temples, upheld maat, the order of the world, against chaos.","Its hope of eternal life inspired the pyramids, mummification, richly furnished tombs and the spells of the Book of the Dead, in which the heart of the dead was weighed before Osiris against the feather of maat.","Briefly overturned by Akhenaten’s worship of the sun disc, it endured through Persian, Greek and Roman rule, carried the cult of Isis across the Roman Empire, and faded with the rise of Christianity."],dyk:"The catacombs dedicated to the jackal god Anubis at Saqqara held some eight million mummified animals, most of them dogs, offered by pilgrims to the god.",ev:[["c. 3100 BCE","Egypt is united under the first kings, who rule as the god Horus on earth"],["c. 2560 BCE","The Great Pyramid is built at Giza as the tomb of the king Khufu"],["c. 2350 BCE","The Pyramid Texts, Egypt’s oldest religious writings, are carved in the pyramid of Unas"],["c. 1350 BCE","Akhenaten raises the Aten, the sun disc, above all other gods and founds a new capital at Amarna"],["30 BCE","Rome annexes Egypt; its emperors are portrayed on temple walls as pharaohs"],["391","The Serapeum of Alexandria is destroyed after the emperor Theodosius bans pagan sacrifice"],["394","The last known hieroglyphic inscription is carved at the temple of Philae"],["c. 537","Officials of the emperor Justinian close the temple of Isis at Philae"]]},
  "Ancient Greek religion": {t:["The Greeks worshipped many gods, led by the twelve Olympians under Zeus, together with heroes, nymphs and local powers, through sacrifice, prayer, festivals and oracles, with no sacred book and no single priesthood to define belief.","Religion was woven into the life of every city: its temples, such as the Parthenon, its festivals, such as the Panathenaia and the Olympic Games, and its drama, born in the festivals of Dionysus.","Banned by the Christian emperors in the 390s, it left myths, told by Homer, Hesiod and the tragedians, that became one of the foundations of Western art and literature."],dyk:"The ancient Olympic Games were a religious festival of Zeus: athletes swore an oath before a statue of the god, and a hundred oxen were sacrificed at his great altar in the middle of the festival.",ev:[["14th–13th centuries BCE","Tablets in Linear B at Knossos and Pylos record offerings to Zeus, Hera, Poseidon and Dionysus"],["776 BCE","The first Olympic Games are held in honour of Zeus, by tradition"],["c. 700 BCE","Homer’s epics and Hesiod’s Theogony give the gods their classic form"],["438 BCE","Pheidias’s gold and ivory statue of Athena is dedicated in the Parthenon"],["399 BCE","Socrates is condemned to death in Athens for impiety"],["392","The emperor Theodosius bans all pagan sacrifice and worship"],["393","The last ancient Olympic Games are held, by tradition"],["529","Justinian forbids pagans to teach; the Platonic school of Athens closes"]]},
  "Hebrew": {t:["Hebrew, a Canaanite language of the Iron Age kingdoms of Israel and Judah, is the language of most of the Hebrew Bible, written and edited over many centuries in the 1st millennium BCE.","Displaced in daily life by Aramaic, Greek and later other languages, it lived on for nearly two thousand years as the language of Jewish prayer, law, poetry, philosophy and correspondence across the world.","Revived as a spoken language from the late 19th century, it is today the language of Israel and of some 9 million speakers, a unique case of a language reborn as the mother tongue of a nation."],dyk:"Ben-Zion Ben-Yehuda, born in Jerusalem in 1882 and raised by his father Eliezer to speak only Hebrew, is often called the first native speaker of the language in modern times.",ev:[["10th century BCE","The Gezer calendar, one of the oldest inscriptions in a Hebrew or related Canaanite dialect, lists the months of the farming year"],["c. 700 BCE","The Siloam inscription records the cutting of a water tunnel under Jerusalem"],["c. 200","The Mishnah, the code of Jewish law, is compiled in Mishnaic Hebrew"],["c. 930","The Aleppo Codex, a masterpiece of the Masoretic text with its vowel signs, is written in Tiberias"],["1881","Eliezer Ben-Yehuda settles in Jerusalem and begins his campaign to revive spoken Hebrew"],["1922","The British Mandate for Palestine recognises Hebrew as an official language beside English and Arabic"],["1947","The first Dead Sea Scrolls, including the oldest known manuscripts of the Hebrew Bible, are found near Qumran"],["1953","Israel founds the Academy of the Hebrew Language"]]},
  "Hinduism": {t:["Hinduism has no single founder or creed: it grew from the Vedic religion of the north-west of India and absorbed many local traditions over three thousand years.","Its central ideas, dharma, karma, rebirth and release (moksha), and its devotion to gods such as Vishnu, Shiva and the Goddess shaped the culture of South Asia and much of Southeast Asia.","Reformed and renewed in the 19th and 20th centuries, it is the world’s third-largest religion, with about 1.2 billion followers and communities on every continent."],dyk:"Angkor Wat in Cambodia, often called the largest religious monument in the world, was built in the early 12th century as a temple to Vishnu.",ev:[["c. 1500–1200 BCE","The hymns of the Rigveda, the oldest Hindu scripture, are composed in north-west India"],["c. 700–500 BCE","The earliest Upanishads explore the identity of the self (atman) and ultimate reality (Brahman)"],["c. 400 BCE–400 CE","The Mahabharata, with the Bhagavad Gita, and the Ramayana take shape"],["c. 320–550","Under the Gupta Empire, temple building, the Puranas and devotion to Vishnu and Shiva flourish"],["8th century","Shankara teaches Advaita Vedanta, the non-dual reading of the Upanishads"],["early 12th century","Angkor Wat is built as a temple to Vishnu under the Khmer king Suryavarman II"],["1893","Swami Vivekananda introduces Hinduism to the World’s Parliament of Religions in Chicago"],["1950","The constitution of the Republic of India abolishes untouchability"]]},
  "Islam": {t:["Islam began with the revelations that Muslims believe the prophet Muhammad received from God through the angel Gabriel in Mecca from 610, gathered in the Quran: there is no god but God, and Muhammad is his messenger.","Within a century of Muhammad’s death in 632 the caliphs ruled from Spain to Central Asia; traders, scholars and Sufis later carried Islam across Africa, India and Southeast Asia.","Divided since the first century into Sunni and Shia traditions, it shaped law, learning, art and the Arabic language across a vast civilisation and is today the faith of about two billion people."],dyk:"The Islamic calendar counts years from Muhammad’s migration from Mecca to Medina in 622; because it is a lunar calendar, its months move through the seasons, and the fast of Ramadan comes about eleven days earlier each year.",ev:[["c. 610","Muhammad receives his first revelation in the cave of Hira near Mecca, according to Islamic tradition"],["622","The Hijra: Muhammad and his followers migrate from Mecca to Medina, the start of the Islamic calendar"],["632","Muhammad dies in Medina; Abu Bakr becomes the first caliph"],["c. 650","The caliph Uthman has the text of the Quran gathered and copies sent to the main cities"],["680","Husayn, Muhammad’s grandson, is killed at Karbala, an event central to Shia Islam"],["691–692","The Dome of the Rock is completed in Jerusalem"],["711","Muslim armies cross from North Africa into Spain"],["1924","The Republic of Turkey abolishes the Ottoman caliphate"]]},
  "Jainism": {t:["Jainism, taught by Mahavira in north-east India in the same age as the Buddha, holds that every living being has a soul and that release from rebirth comes through non-violence, truth and the renunciation of possessions.","Its monks and nuns live by five great vows of extreme strictness, while its lay followers, many of them merchants and bankers, became one of the most prosperous and influential communities of India.","Divided since about the 1st century CE into the Digambara and Svetambara traditions, it built temples of rare beauty and influenced Gandhi’s ideal of non-violence."],dyk:"The colossal statue of Bahubali at Shravanabelagola in Karnataka, carved from a single block of granite around 983, stands about 17 metres high and is anointed with milk, saffron and flowers every twelve years.",ev:[["c. 8th–7th century BCE","Parshvanatha, the 23rd Tirthankara, teaches in the Ganges valley, by Jain tradition"],["c. 6th–5th century BCE","Mahavira attains omniscience and teaches the path of non-violence; he dies at Pavapuri"],["c. 3rd century BCE","By Digambara tradition, Bhadrabahu leads monks to the south, joined by Chandragupta Maurya"],["2nd or 1st century BCE","King Kharavela of Kalinga honours the Jinas in his Hathigumpha inscription"],["c. 1st century CE","The community divides into the Digambara and Svetambara traditions"],["453 or 466","A council at Valabhi writes down the Svetambara canon"],["c. 983","The statue of Bahubali is carved at Shravanabelagola"],["12th century","King Kumarapala of Gujarat embraces Jainism under the teacher Hemachandra"]]},
  "Judaism": {t:["Judaism is the religion of the people of Israel, whose Hebrew Bible tells of one God who made a covenant with them and gave them the Torah, the law and teaching that guides Jewish life.","After the destruction of the Second Temple by Rome in 70 CE, the rabbis rebuilt Judaism around the synagogue, prayer and the study of the Torah and the Talmud, allowing it to survive in dispersion across the world.","Through the centuries of exile, persecution and the Holocaust, and with the founding of the State of Israel in 1948, it has remained the faith of about 15 million people and the root from which Christianity and Islam grew."],dyk:"The Dead Sea Scrolls, found in caves near Qumran from 1947, include copies of books of the Hebrew Bible about a thousand years older than the oldest complete Hebrew manuscripts known before them.",ev:[["c. 10th century BCE","By the biblical account, David makes Jerusalem his capital and Solomon builds the First Temple"],["586 BCE","The Babylonians destroy Jerusalem and the First Temple and take many Judeans into exile"],["516 BCE","The Second Temple is completed in Jerusalem after the return from exile, by the traditional date"],["70","The Romans destroy Jerusalem and the Second Temple at the end of the Jewish revolt"],["c. 200","Judah ha-Nasi compiles the Mishnah, the first great work of rabbinic law"],["c. 600","The Babylonian Talmud reaches its final form"],["1492","The Jews are expelled from Spain"],["1948","The State of Israel is founded, three years after the end of the Holocaust"]]},
  "Latin": {t:["Latin, the language of Latium and Rome, spread with Roman power across the western Mediterranean and became the language of law, government and a great literature from Cicero and Virgil onwards.","Spoken Latin changed region by region into the Romance languages, among them Spanish, Portuguese, French, Italian and Romanian, now the first languages of nearly 900 million people.","Written Latin outlived the Roman Empire by more than a thousand years as the language of the Church, the universities, science and diplomacy in Europe."],dyk:"Latin remained the official language of the Kingdom of Hungary until 1844, when the Hungarian diet made Hungarian the language of government in its place.",ev:[["c. 6th century BCE","The earliest Latin inscriptions, among them the Lapis Niger in the Roman Forum"],["240 BCE","Livius Andronicus stages the first Latin play adapted from a Greek original"],["1st century BCE","The golden age of Latin literature: Cicero, Caesar, Lucretius, Virgil and Horace"],["c. 382–405","Jerome translates the Bible into Latin: the Vulgate"],["813","The Council of Tours orders sermons to be preached in the “rustic Roman tongue” or in German"],["842","The Oaths of Strasbourg, the earliest surviving text in an early form of French"],["1687","Isaac Newton publishes his Principia in Latin"],["1962–1965","The Second Vatican Council opens the way to the Mass in the languages of the people"]]},
  "Manichaeism": {t:["Manichaeism was founded by Mani, a prophet from Sasanian Mesopotamia, who from about 240 taught that the world is a mixture of light and darkness and that souls, sparks of light, can be freed through knowledge and discipline.","Organised into an elite of the Elect and a laity of Hearers, it spread west into the Roman Empire, where the young Augustine of Hippo was a Hearer, and east along the Silk Road to the Uyghurs and China.","Persecuted by Zoroastrian, Christian, Muslim and Chinese rulers alike, it disappeared by the early modern period, leaving its name to any world view that divides everything into good and evil."],dyk:"A temple at Cao’an near Quanzhou in southern China still holds a stone image of Mani as the “Buddha of Light”, carved in 1339: the only Manichaean shrine in the world known to survive.",ev:[["216","Mani is born in Mesopotamia, near the Persian capital Ctesiphon"],["c. 240","Mani begins to preach his religion, after a revelation in his youth"],["c. 274–277","Mani dies in prison under the Sasanian king Bahram I"],["c. 302","The Roman emperor Diocletian orders the persecution of the Manichaeans"],["c. 373–382","Augustine of Hippo is a Manichaean Hearer before his conversion to Christianity"],["762–763","The Uyghur ruler Bögü Qaghan adopts Manichaeism, the faith of his empire for decades"],["843","The Tang emperor Wuzong bans Manichaeism in China"],["1339","The image of Mani as the Buddha of Light is carved at Cao’an near Quanzhou"]]},
  "Mesoamerican religion": {t:["For three thousand years the peoples of Mesoamerica, from the Olmecs to the Maya and the Aztecs, shared a religion of gods of rain, maize, sun and wind, of sacred mountains and caves, and of time measured by interlocking calendars.","Kings and priests offered the gods incense, their own blood and, at times, human lives in pyramid temples, to repay the gods who, in the myths, had sacrificed themselves to set the sun moving and to create humanity.","Suppressed after the Spanish conquest, it survives in a handful of painted books, the Popol Vuh, the ruins of its temple cities and traditions, such as the 260-day calendar, still kept in Maya communities."],dyk:"In 1562 the Franciscan friar Diego de Landa burned the Maya books he found at Maní in Yucatán as works of the devil; only four Maya books survive today, in Dresden, Madrid, Paris and Mexico City.",ev:[["c. 1200 BCE","The Olmec centre of San Lorenzo flourishes on the Gulf Coast of Mexico, with the earliest monumental religious art of Mesoamerica"],["c. 200","The Pyramid of the Sun is completed at Teotihuacan, the city the Aztecs later believed to be the birthplace of the sun"],["292","Stela 29 is raised at Tikal, the earliest known dated monument of the Maya lowlands"],["1325","The Mexica found Tenochtitlan, by tradition where their god Huitzilopochtli had promised"],["1487","The Great Temple of Tenochtitlan is rededicated with the sacrifice of many captives"],["1521","The fall of Tenochtitlan to the Spanish and their allies ends the Aztec state religion"],["1562","The friar Diego de Landa burns Maya books and images at Maní in Yucatán"],["1697","The Spanish take Nojpetén, capital of the Itza, the last independent Maya kingdom"]]},
  "Nahuatl": {t:["Nahuatl, a Uto-Aztecan language that came to central Mexico from the north, was the language of the Aztecs and the common language of trade and empire across much of Mesoamerica.","After the Spanish conquest it was written in the Latin alphabet, producing a large body of Indigenous writing, from chronicles, poetry and wills to the Florentine Codex, one of the greatest records of a society before European rule.","Still spoken by about 1.7 million people in Mexico, it has given words such as chocolate, tomato, avocado and chili to languages around the world."],dyk:"Mexico takes its name from the Mexica, the Nahuatl-speaking founders of Tenochtitlan, and the name of Guatemala comes from a Nahuatl word meaning “place of many trees”.",ev:[["c. 900–1150","Tula, the city of the Toltecs, whose people probably spoke Nahuatl, dominates central Mexico"],["1325","The Mexica found Tenochtitlan, by tradition, on an island in Lake Texcoco"],["1519","Malintzin, a Nahuatl-speaking woman, becomes the interpreter of Hernán Cortés"],["1536","The College of Santa Cruz de Tlatelolco opens, teaching Latin, Spanish and Nahuatl to young Nahua nobles"],["1571","Alonso de Molina publishes his great dictionary of Nahuatl and Spanish"],["c. 1577","Bernardino de Sahagún and Nahua scholars complete the Florentine Codex"],["1770","A royal decree of Charles III calls for Spanish to replace the Indigenous languages of the empire"],["2003","Mexico’s law on linguistic rights recognises Nahuatl and other Indigenous languages as national languages"]]},
  "Norse religion": {t:["The pre-Christian religion of Scandinavia worshipped gods such as Odin, Thor, Freyr and Freyja, with sacrifices, feasts and rituals led by chieftains and kings, in a world of nine realms around the world tree Yggdrasil.","Its myths, of a world made from the body of a giant and destroyed at Ragnarök, are known mainly from Icelandic texts written down by Christians in the 13th century, two centuries after the conversion.","Displaced by Christianity between the 10th and 12th centuries, it gave English four of its weekday names and a mythology that has inspired art and literature from Wagner to Tolkien and modern film."],dyk:"A soapstone mould found in Denmark, from the 10th century, was made to cast both Christian crosses and the hammers of Thor, so that a smith could sell to customers of either faith.",ev:[["793","The Viking raid on the monastery of Lindisfarne opens the Viking Age"],["c. 965","King Harald Bluetooth raises the Jelling stone, recording that he made the Danes Christian"],["c. 1000","The Icelandic assembly, the Althing, adopts Christianity, allowing pagan worship in private for a time"],["c. 1075","Adam of Bremen describes the temple at Uppsala with images of Thor, Odin and Freyr"],["c. 1220","Snorri Sturluson writes the Prose Edda, a handbook of Norse myth and poetry"],["c. 1270","The Codex Regius, the manuscript of the Poetic Edda, is written in Iceland"],["1973","Iceland recognises the modern Ásatrú fellowship as a religion"]]},
  "Old Norse": {t:["Old Norse, the North Germanic language of the Viking Age, was spoken from Scandinavia to Iceland, Greenland, the British Isles and Russia, and carved in runes on thousands of memorial stones.","In Iceland, from the 12th to the 14th centuries, it became the language of a great literature, the sagas, the Eddas and skaldic poetry, which preserves the myths and history of the North.","It is the ancestor of Icelandic, Faroese, Norwegian, Danish and Swedish, and through Viking settlement it gave English some of its most everyday words, from sky and egg to they and take."],dyk:"English owes some of its most basic words to Old Norse, among them they, them and their, sky, egg, knife, take and window, from vindauga, “wind eye”.",ev:[["793","The Viking raid on Lindisfarne opens the Viking Age, which carries Old Norse across the seas"],["c. 800","The Rök stone, with the longest known runic inscription, is raised in Sweden"],["c. 870","Norse settlers begin to colonise Iceland"],["1117–1118","The laws of Iceland are first written down in Old Norse"],["c. 1130","Ari Thorgilsson writes the Book of the Icelanders, the first history in the language"],["c. 1220","Snorri Sturluson writes the Prose Edda, a handbook of poetry and myth"],["c. 1280","Njáls saga, the greatest of the Icelandic family sagas, is written"],["1971","Denmark returns the Codex Regius and Flateyjarbók to Iceland, the first of the medieval manuscripts to go home"]]},
  "Old Turkic": {t:["Old Turkic, the earliest recorded Turkic language, was first written in the 8th century on the stone monuments of the Second Turkic Khaganate in the Orkhon valley of Mongolia, in an alphabet resembling runes.","The Uyghurs, who succeeded the Turks on the steppe and settled in the oases of the Tarim Basin, wrote a large literature in it, Buddhist, Manichaean and Christian, much of it recovered from the sands of Turfan and the caves of Dunhuang.","The Turkic languages, which spread from Mongolia to the Balkans, are spoken today by some 200 million people, who honour the Orkhon inscriptions as the beginning of their written history."],dyk:"The memorial stone of the Turkic prince Kul Tigin, raised in 732, carries an inscription in Old Turkic runes on three sides and, on the fourth, a Chinese text composed by the Tang emperor Xuanzong.",ev:[["552","Bumin founds the Turkic Khaganate, the first state to bear the name Türk"],["c. 720","The adviser Tonyukuk sets up the first of the great Old Turkic inscriptions in Mongolia"],["732","The memorial inscription of Kul Tigin is raised in the Orkhon valley"],["762–763","The Uyghur khagan adopts Manichaeism, whose texts are translated into Old Turkic"],["840","The fall of the Uyghur Khaganate drives the Uyghurs to the oases of Turfan and Gansu"],["1069","Yusuf Khass Hajib completes the Kutadgu Bilig, the first great Islamic work in Turkic"],["1070s","Mahmud al-Kashgari writes his Compendium of the Languages of the Turks in Baghdad"],["1893","Vilhelm Thomsen deciphers the Old Turkic runic script"]]},
  "Persian": {t:["Persian, first written in the inscriptions of the Achaemenid kings in the 6th century BCE, has been spoken and written for some two and a half thousand years, in three stages known as Old, Middle and New Persian.","Reborn after the Arab conquest as New Persian, written in Arabic letters, it became from the 10th century the language of a great literature, from Ferdowsi’s Shahnameh to Rumi and Hafez, and of courts and learning from Anatolia to India.","The language of Iran, Afghanistan and Tajikistan today, it has changed so little since the 10th century that Persian speakers can still read the classical poets with ease."],dyk:"Persian was the official language of the courts of British India until 1837, and words such as bazaar, caravan, pyjamas, paradise and checkmate, from shāh māt, “the king is helpless”, reached English from or through Persian.",ev:[["c. 520 BCE","Darius I has his deeds carved in Old Persian, Elamite and Babylonian on the cliff of Behistun"],["c. 262","Shapur I records his victories over Rome in Middle Persian, Parthian and Greek at Naqsh-e Rostam"],["651","The fall of the Sasanian empire to the Arab conquerors makes Arabic the language of government"],["10th century","The Samanid court at Bukhara patronises poetry in the new Persian language"],["c. 1010","Ferdowsi completes the Shahnameh, the national epic of the Persian-speaking world"],["1273","Death of the poet Rumi, author of the Masnavi"],["1582","The Mughal emperor Akbar makes Persian the language of all government records in his empire"],["1837","Persian is replaced by English and local languages as the official language of British India"]]},
  "Quechua": {t:["Quechua, a family of closely related languages that grew in central Peru in the first millennium CE, became the common language of the Inca empire, which carried it along the Andes from Ecuador to Chile.","After the Spanish conquest, missionaries used it to preach across the Andes, spreading it further than ever, and it was written in the Latin alphabet in grammars, sermons, chronicles and plays.","Spoken today by millions of people in six countries, it is the most widely spoken Indigenous language family of the Americas, and words such as llama, condor, puma and quinoa come from it."],dyk:"English words such as llama, condor, puma, coca, quinoa and guano come from Quechua, and so does jerky, from ch’arki, the dried meat that sustained Andean travellers.",ev:[["c. 600–1000","The Wari state of the central Andes may have carried early Quechua across much of Peru"],["1438","The Inca ruler Pachacuti begins the expansion that makes Quechua the language of an empire, by tradition"],["1560","Domingo de Santo Tomás publishes the first grammar and dictionary of Quechua"],["1584","A catechism in Spanish, Quechua and Aymara becomes the first book printed in South America"],["c. 1608","The Huarochirí Manuscript records the myths and rituals of an Andean province in Quechua"],["c. 1615","Felipe Guaman Poma de Ayala completes his illustrated chronicle of Andean life, with passages in Quechua"],["1975","Peru makes Quechua an official language"],["2019","A doctoral thesis written entirely in Quechua is defended for the first time, at the University of San Marcos in Lima"]]},
  "Sanskrit": {t:["Sanskrit, the sacred and learned language of ancient India, is first known from the hymns of the Rigveda, composed around 1500–1200 BCE and handed down by memory with remarkable precision ever since.","Codified by the grammarian Panini around the 4th century BCE, Classical Sanskrit became the language of Hindu scripture, the great epics, philosophy, science and poetry, and of Buddhist and Jain learning, from Afghanistan to Java.","Its study in Europe from the late 18th century revealed the Indo-European family of languages, and it remains the liturgical language of Hinduism and a source of words for the languages of India and Southeast Asia."],dyk:"In 1786 the British judge William Jones told the Asiatic Society in Calcutta that Sanskrit, Greek and Latin were so alike that they must have sprung from a common source, “which, perhaps, no longer exists”: a founding moment of comparative linguistics.",ev:[["c. 1500–1200 BCE","The hymns of the Rigveda are composed in the north-west of the subcontinent"],["c. 1380 BCE","A treaty of the Mitanni kingdom in Syria invokes the Indo-Aryan gods Mitra, Varuna and Indra"],["c. 4th century BCE","Panini composes the Ashtadhyayi, his grammar of Sanskrit in some four thousand rules"],["c. 150","The Junagadh inscription of Rudradaman, the first long royal inscription in Sanskrit"],["499","Aryabhata writes his treatise on astronomy and mathematics in Sanskrit verse"],["1786","William Jones points out the common origin of Sanskrit, Greek and Latin"],["1950","India’s constitution lists Sanskrit among the languages of the nation"]]},
  "Shinto": {t:["Shinto, “the way of the kami”, is the native religion of Japan: the worship of the kami, the sacred powers present in mountains, trees, rivers, ancestors and great people, at shrines across the country, with no founder and no single scripture.","For a thousand years kami and buddhas were worshipped together, until the Meiji government separated them in 1868 and built a State Shinto around the divine emperor, which the Allied occupation dismantled in 1945.","Today festivals, New Year shrine visits and rites of passage keep Shinto at the heart of Japanese life, while its shrines, rituals and reverence for nature have shaped the country’s art and architecture."],dyk:"The Grand Shrine of Ise has been rebuilt in identical form on a neighbouring site every twenty years since 690, apart from a long interruption during the civil wars of the 15th and 16th centuries: the 62nd rebuilding was completed in 2013.",ev:[["4th century","Ritual offerings to the kami begin on the sacred island of Okinoshima"],["690","The first ritual rebuilding of the Grand Shrine of Ise"],["712","The Kojiki records the myths of the kami and the descent of the emperors from the sun goddess"],["927","The Engishiki lists 2,861 shrines and the court’s rituals and prayers"],["1868","The Meiji government orders the separation of kami and buddhas"],["1869","The shrine later named Yasukuni is founded in Tokyo for those who died fighting for the emperor"],["1945","The Allied occupation’s Shinto Directive ends State Shinto"]]},
  "Sikhism": {t:["Sikhism began with Guru Nanak’s teaching in the Punjab around 1500: one God, remembered in prayer, served through honest work and sharing, and found by all people equally, whatever their caste.","Nine Gurus after him built its institutions: the Golden Temple at Amritsar, the scripture of the Guru Granth Sahib and, under Guru Gobind Singh in 1699, the Khalsa order of initiated Sikhs.","Persecuted under the later Mughals, Sikhs built their own empire under Ranjit Singh, and today some 25 to 30 million Sikhs live in the Punjab and across the world."],dyk:"The free kitchen (langar) of the Golden Temple at Amritsar serves meals to tens of thousands of people every day, of any faith or none, all of them seated together on the floor as equals.",ev:[["c. 1499","Guru Nanak’s spiritual experience at the river Bein near Sultanpur Lodhi begins his mission"],["1577","Guru Ram Das founds the city of Amritsar around its sacred pool"],["1604","Guru Arjan installs the Adi Granth, the Sikh scripture, in the Harmandir Sahib at Amritsar"],["1606","Guru Arjan is executed under the Mughal emperor Jahangir"],["1675","Guru Tegh Bahadur is executed in Delhi on the orders of Aurangzeb"],["1699","Guru Gobind Singh founds the Khalsa at Anandpur on the festival of Vaisakhi"],["1799","Ranjit Singh takes Lahore and goes on to found the Sikh Empire"],["1984","The Indian army’s Operation Blue Star at the Golden Temple, followed by the assassination of Indira Gandhi and anti-Sikh violence"]]},
  "Sumerian": {t:["Sumerian, the language of the city-states of southern Mesopotamia, is with Egyptian one of the two earliest written languages: its speakers developed cuneiform writing, at first to keep accounts, around 3200 BCE.","A language isolate unrelated to any other, it gave way as a spoken language to Akkadian around 2000 BCE, but remained the classical language of Mesopotamian religion and learning for nearly two thousand years.","Its literature, from the hymns of Enheduanna to the first stories of Gilgamesh, its law codes and its scribal schools make it one of the foundations of written civilisation."],dyk:"The Sumerians counted in sixties, and through the astronomy of their Babylonian heirs their system survives in the sixty minutes of an hour and the 360 degrees of a circle.",ev:[["c. 3200 BCE","The first accounting tablets are written at Uruk in proto-cuneiform"],["c. 2600 BCE","The earliest Sumerian literary texts are copied at Shuruppak and Abu Salabikh"],["c. 2300 BCE","Enheduanna, high priestess at Ur and daughter of Sargon of Akkad, composes hymns in Sumerian"],["c. 2100 BCE","The law code of Ur-Nammu, the oldest known, is written in Sumerian"],["c. 1800 BCE","Babylonian scribal schools copy the classics of Sumerian literature, long after the language has ceased to be spoken"],["c. 80","The last datable cuneiform tablet, an astronomical almanac, is written at Uruk"],["1869","The scholar Jules Oppert gives the rediscovered language the name Sumerian"]]},
  "Swahili": {t:["Swahili grew from the Bantu speech of the East African coast, where from around the 8th century merchant towns traded across the Indian Ocean with Arabia, Persia and India, absorbing many Arabic words.","Written in Arabic script from at least the early 18th century, it developed a rich poetic tradition, and in the 19th century caravans carried it inland from Zanzibar as far as the Great Lakes and the Congo.","Spread by colonial administrations and, after independence, promoted by Tanzania as its national language, it is today the common language of East Africa and one of the most widely spoken languages of the continent."],dyk:"Julius Nyerere, the first president of Tanzania, translated Shakespeare’s Julius Caesar and The Merchant of Venice into Swahili, to show that the language could carry any literature in the world.",ev:[["c. 800","Trading towns such as Shanga and Manda grow on the East African coast, where Swahili takes shape"],["1331","Ibn Battuta visits Mombasa and Kilwa and describes the wealth of the Swahili coast"],["1711","Letters in Arabic script written at Kilwa, later seized by the Portuguese and kept at Goa, are the oldest known documents in Swahili"],["1728","The Utendi wa Tambuka, the oldest dated epic poem in Swahili, is composed"],["19th century","Caravans from Zanzibar carry Swahili to the Great Lakes and the eastern Congo"],["1930","A committee of the British East African territories standardises Swahili on the dialect of Zanzibar"],["1967","Tanzania makes Swahili the language of government and of primary schooling"],["2022","The first World Kiswahili Language Day is celebrated on 7 July, proclaimed by UNESCO"]]},
  "Yoruba religion": {t:["The traditional religion of the Yoruba of West Africa worships Olodumare, the supreme god, and the orisha, divine powers such as Obatala, Ogun, Shango, Oshun and Yemoja, honoured with prayer, sacrifice, music, dance and possession.","At its heart lies Ifa, a system of divination whose priests memorise a vast oral literature of verses; UNESCO proclaimed it a masterpiece of the oral heritage of humanity in 2005.","Carried across the Atlantic by enslaved Yoruba, it gave rise to Santería in Cuba, Candomblé in Brazil and related traditions, which made the orisha some of the most widely worshipped African gods in the world."],dyk:"The sacred grove of the river goddess Oshun at Osogbo in Nigeria, one of the last stretches of primary high forest in southern Nigeria, was restored with the help of the Austrian artist Susanne Wenger, who became a priestess of the orisha, and is now a World Heritage Site.",ev:[["c. 1300","Ile-Ife, the sacred city of the Yoruba, is at its height; its artists cast naturalistic heads in copper alloy"],["17th century","The Oyo Empire rises to dominate the Yoruba lands; its kings honour Shango, the orisha of thunder, remembered as one of their predecessors"],["1830s","The collapse of the Oyo Empire and the wars that follow send many enslaved Yoruba to Cuba and Brazil"],["Early 19th century","African priestesses found Casa Branca, one of the first great Candomblé houses, in Salvador, Bahia"],["1993","The Supreme Court of the United States upholds the right of a Santería church in Florida to practise animal sacrifice"],["2005","UNESCO proclaims Ifa divination a masterpiece of humanity’s oral heritage; the sacred grove of Osogbo becomes a World Heritage Site"]]},
  "Zoroastrianism": {t:["Zoroastrianism grew from the hymns of the prophet Zarathustra, who taught that the Wise Lord, Ahura Mazda, calls every person to choose truth over the lie in a cosmic struggle that will end in the triumph of good.","It was the faith of the Achaemenid kings and the state religion of the Parthian and Sasanian empires, and its ideas of judgement, heaven and hell and a final renewal of the world may have influenced Judaism, Christianity and Islam.","After the Arab conquest of Iran it became a minority faith; today it survives among small communities in Iran and among the Parsis of India, whose contribution to modern Bombay was out of all proportion to their numbers."],dyk:"The Magi who bring gifts to the infant Jesus in the Gospel of Matthew bear the title of the priests of Iran, the magi, who were the guardians of the Zoroastrian tradition.",ev:[["c. 1500–1000 BCE","Zarathustra composes the Gathas, by the reckoning of many modern scholars; others place him in the 7th or 6th century BCE"],["c. 520 BCE","Darius I credits his victories to Ahura Mazda in the Behistun inscription"],["224","Ardashir I founds the Sasanian Empire, under which Zoroastrianism becomes the state religion"],["3rd century","The high priest Kartir organises the Zoroastrian church and its fire temples across the empire"],["651","The last Sasanian king, Yazdegerd III, is killed after the Arab conquest of Iran"],["9th–10th century","Zoroastrian priests compile the Pahlavi books, among them the Denkard and the Bundahishn"],["8th–10th century","Zoroastrians from Iran settle in Gujarat, according to the Story of Sanjan: the origin of the Parsis"],["1892","The Parsi Dadabhai Naoroji becomes the first Asian elected to the British House of Commons"]]},
  "Ancient Greek": {t:["Greek has the longest recorded history of any living Indo-European language, from the Mycenaean tablets of the 14th century BCE through the classical language of Athens to the Greek spoken today.","It was the language of Homer, the Athenian dramatists, historians and philosophers, and, after Alexander’s conquests, as the Koine or “common” Greek, the shared language of the eastern Mediterranean and of the New Testament.","Its alphabet, the first to write vowels as well as consonants, became the model of the Latin and Cyrillic alphabets, and its words supply the terms of science, medicine, philosophy and politics in languages across the world."],dyk:"The oldest Greek writing survived by accident: the Linear B tablets were records of unbaked clay, meant to be reused, until the fires that destroyed the palaces of Knossos and Pylos baked them hard.",ev:[["c. 1400 BCE","Scribes at Knossos record Mycenaean Greek in the Linear B script"],["c. 750 BCE","The Greeks adapt the Phoenician alphabet, adding letters for vowels"],["c. 700 BCE","The Iliad and the Odyssey take shape, the oldest works of Greek literature"],["403 BCE","Athens officially adopts the Ionic alphabet of twenty-four letters"],["334 BCE","Alexander the Great begins the conquests that carry Greek to Egypt, Persia and India"],["3rd century BCE","The Hebrew scriptures are translated into Greek in Alexandria: the Septuagint"],["1397","Manuel Chrysoloras begins teaching Greek in Florence, reviving its study in western Europe"],["1976","Greece makes Demotic, the popular form of the language, its official language"]]},
  "Kingdom of Hawaii": {t:["An island kingdom united by Kamehameha I between 1795 and 1810, with its capital at Lahaina from 1820 and at Honolulu from 1845.","It became a constitutional monarchy in 1840, and Britain and France recognised its independence in 1843.","Planters forced the Bayonet Constitution on Kalākaua in 1887, and a committee backed by US troops overthrew Liliʻuokalani in 1893."],dyk:"ʻIolani Palace in Honolulu was lit by electricity by 1887, four years before electric lighting was installed in the White House in Washington in 1891.",ev:[["1795","Kamehameha I wins the Battle of Nuʻuanu and takes Oʻahu"],["1810","Kaumualiʻi of Kauaʻi accepts Kamehameha as overlord, completing unification"],["1819","The kapu system is abolished after the death of Kamehameha I"],["1840","Kamehameha III grants the kingdom’s first constitution"],["1843","Britain and France jointly recognise Hawaiian independence"],["1848","The Great Māhele divides the kingdom’s land"],["1887","Kalākaua is forced to sign the Bayonet Constitution"],["1893","Queen Liliʻuokalani is overthrown and a Provisional Government proclaimed"]]},
  "Kingdom of Tonga": {t:["Tāufaʻāhau, baptised as George, ended half a century of civil war and united Tonga as King George Tupou I in 1845–1852.","His 1862 code freed commoners from forced service to chiefs, and his 1875 constitution, still in force, forbade the sale of land.","A British protected state from 1900 to 1970 but never a colony, Tonga remains a monarchy under King Tupou VI."],dyk:"Tonga regained full independence on 4 June 1970, the 108th anniversary of George Tupou I’s 1862 code freeing commoners from forced service to their chiefs.",ev:[["1826","Tāufaʻāhau defeats Laufilitonga at the Battle of Velata on Lifuka"],["1845","Tāufaʻāhau becomes Tuʻi Kanokupolu and King George Tupou I"],["1852","The fall of Pea and Houma ends the civil wars on Tongatapu"],["1862","George Tupou I’s code frees commoners from forced service to chiefs"],["1875","The constitution makes Tonga a constitutional monarchy"],["1900","A Treaty of Friendship makes Tonga a British protected state"],["1970","Tonga regains full independence and joins the Commonwealth"],["2010","Reforms give the people a majority of elected seats in parliament"]]},
  "Tuʻi Tonga Empire": {t:["A line of 39 sacred kings, traditionally founded by ʻAhoʻeitu around 950, whose royal centre at Muʻa on Tongatapu is marked by great stone tombs.","Its voyaging and tribute networks reached ʻUvea, Samoa and eastern Fiji, and its royal centres held stone tools from as far as the Society Islands.","From the fifteenth century junior royal lines governed in its name; the last Tuʻi Tonga, Laufilitonga, died in 1865 and the title lapsed."],dyk:"In July 1777 James Cook watched the ʻinasi first-fruits ceremony at Muʻa and wrote that its occasion was the Tuʻi Tonga Paulaho and his son eating together, a thing never done before.",ev:[["c. 950","ʻAhoʻeitu becomes the first Tuʻi Tonga, according to Tongan genealogies"],["c. 1200","Tradition credits Tuʻitātui with raising the Haʻamonga ʻa Maui trilithon at Heketā"],["c. 1300–1400","The royal tomb of Paepae-o-Teleʻa is built at Lapaha, Muʻa"],["15th century","Takalaua’s assassination leads to the creation of the Tuʻi Haʻatakalaua line"],["c. 1610","The Tuʻi Kanokupolu title is created for Ngata, son of the sixth Tuʻi Haʻatakalaua"],["1777","James Cook watches the ʻinasi first-fruits ceremony at Muʻa"],["1826","Tāufaʻāhau defeats Laufilitonga at the Battle of Velata"],["1865","Laufilitonga, the last Tuʻi Tonga, dies and the title lapses"]]},
  "Kingdom of Tahiti": {t:["A Polynesian kingdom created by the Pōmare family, who used European guns and allies to rise above Tahiti’s rival chiefs from about 1788.","Pōmare II’s victory at Fei Pi in 1815 made Tahiti a Christian kingdom, with Polynesia’s first written law code in 1819.","Anglo-French rivalry led to a French protectorate in 1842, a war in 1844–1847 and annexation by France in 1880."],dyk:"The landing of the first London Missionary Society missionaries at Matavai Bay on 5 March 1797 is still a public holiday in French Polynesia, the Arrivée de l’Évangile.",ev:[["1788","William Bligh’s HMS Bounty arrives at Matavai Bay to collect breadfruit plants"],["1791","Tu’s son, the future Pōmare II, is invested with the red-feathered maro ‘ura"],["1797","London Missionary Society missionaries land from the Duff at Matavai Bay"],["1815","Pōmare II defeats the chiefs of the old religion at the Battle of Fei Pi"],["1819","Pōmare II issues Tahiti’s first written law code and is baptised"],["1842","Pōmare IV signs a request for French protection under threat of bombardment"],["1844–1847","Tahitians resist French rule in the Franco-Tahitian War"],["1880","Pōmare V cedes Tahiti and its dependencies to France"]]},
  "Saudeleur dynasty": {t:["The first government to unite the whole of Pohnpei, ruling from Nan Madol, a complex of nearly a hundred artificial islets of stacked basalt.","Its history is known from Pohnpeian oral tradition and archaeology; its dates and even the number of its rulers are uncertain.","Tradition says the hero Isokelekel overthrew the last Saudeleur around 1628 and founded the Nahnmwarki chiefdoms that survive today."],dyk:"Uranium-thorium dating of coral from the tomb of Pohnpei’s first island-wide ruler places its building at about 1180–1200, before monument building began on most other Pacific islands.",ev:[["c. 80–200","First traces of human activity at the site of Nan Madol"],["c. 800","Building of artificial islets on the reef at Nan Madol is under way"],["c. 1100","By tradition, Olosohpa becomes the first Saudeleur and unites Pohnpei"],["c. 1180–1200","The tomb of Pohnpei’s first island-wide ruler is built at Nan Madol"],["c. 1200–1500","Most of Nan Madol’s palaces, temples and tombs are built"],["c. 1628","Isokelekel overthrows the last Saudeleur, Saudemwohl, and becomes the first Nahnmwarki"],["2016","Nan Madol becomes a UNESCO World Heritage Site and is listed as in danger"]]},
  "Rapa Nui": {t:["A Polynesian society on remote Easter Island, settled around 1200 and organised in kin groups under a sacred paramount chief of the Miru clan.","Its people carved some 887 moai, mostly from Rano Raraku tuff, and devised rongorongo, the only possible script known from Polynesia.","Slave raids and epidemics in the 1860s reduced the islanders to 111 by 1877, and Chile annexed the island in 1888."],dyk:"In the birdman rite, men swam to the islet of Motu Nui to await the first sooty tern egg of the season; the sponsor of the finder became tangata manu, the sacred birdman, for a year.",ev:[["c. 1200","Polynesian voyagers settle Rapa Nui; tradition names Hotu Matuʻa as the founder"],["c. 1250–1430","Contact with Native Americans leaves lasting traces in the Rapanui genome"],["1722","Jacob Roggeveen reaches the island on Easter Sunday, 5 April"],["1774","James Cook finds that some moai have already been toppled"],["1862–1863","Peruvian slave raiders carry off or kill about 1,500 islanders"],["1864","The missionary Eugène Eyraud arrives and later first reports the rongorongo tablets"],["1877","The island’s population falls to 111"],["1888","Atamu Tekena and eleven chiefs sign an agreement with Chile’s Policarpo Toro"]]},
  "Moche": {t:["A civilisation of Peru’s north coast, c. 100–800 CE, whose lords ruled irrigated desert valleys from huge adobe platforms such as the Huaca del Sol.","Its potters made lifelike portrait vessels and painted scenes of combat and sacrifice; its smiths plated copper with gold and silver.","Royal tombs at Sipán and El Brujo reveal warrior-priests and powerful women; climate crises and unrest ended it around 800."],dyk:"One Moche man, nicknamed ‘Cut Lip’ by the archaeologist Christopher Donnan for the scar on his lip, survives in some forty portrait vessels showing him from boyhood to middle age.",ev:[["c. 100","Moche culture emerges in the Moche and Chicama valleys of Peru’s north coast"],["c. 250","The Lord of Sipán is buried with gold, silver and copper regalia in the Lambayeque valley"],["c. 450","The tattooed Lady of Cao is buried with war clubs at Huaca Cao Viejo in the Chicama valley"],["c. 562–594","A severe drought recorded in Andean ice cores, with El Niño floods, strains Moche agriculture"],["c. 600","Late Moche centres grow at Galindo in the Moche valley and at Pampa Grande in Lambayeque"],["c. 700","Pampa Grande is burned and abandoned, probably after a revolt"],["c. 800","Galindo is abandoned and the Moche tradition comes to an end"],["1987","Walter Alva excavates the intact tomb of the Lord of Sipán at Huaca Rajada"]]},
  "Chavín": {t:["A temple town in Peru’s Ancash highlands, c. 950–400 BCE, whose priests drew pilgrims and offerings from the coast, mountains and forests.","Its stone galleries hid the Lanzón, a carved granite god, and its art of jaguars, eagles and caimans spread far across Peru.","It held sway through religion rather than armies; after its decline regional cultures such as Paracas developed their own styles."],dyk:"In 2001 archaeologists found twenty decorated trumpets made from conch shells, brought from the seas off Ecuador, hidden in a small gallery beside the temple’s Circular Plaza.",ev:[["c. 950 BCE","A temple settlement is founded at Chavín de Huántar, on Richard Burger’s revised dates"],["c. 950–800 BCE","The U-shaped Old Temple and the Lanzón gallery form the heart of the cult"],["c. 700–400 BCE","In the Janabarriu phase the town grows to some 42 hectares and Chavín art spreads widely"],["c. 400 BCE","The ceremonial centre is abandoned; a village later grows over the old plaza"],["1919","Julio C. Tello begins work at the site and calls Chavín the mother culture of the Andes"],["1945","A debris flow buries much of the site and the modern town under mud"],["1985","Chavín de Huántar is inscribed as a UNESCO World Heritage Site"]]},
  "Kingdom of Chimor": {t:["The largest Andean state before the Incas, ruling about 1,000 km of Peru’s desert coast from its capital, Chan Chan.","Chan Chan’s walled royal compounds held palaces, storerooms and burial platforms; each new king seems to have built his own.","Irrigation, conquest and skilled crafts made it rich; the Incas conquered it around 1470 and took its metalworkers to Cusco."],dyk:"Around 1450 about 140 children and 200 young llamas were sacrificed in a single event at Huanchaquito, near Chan Chan, apparently soon after heavy rains and flooding.",ev:[["c. 900–1000","Chimú culture takes shape in the Moche valley and building begins at Chan Chan"],["c. 1350","A massacre at Punta Lobos near Huarmey is linked to Chimú expansion to the south"],["c. 1370","By tradition, Ñançenpinco conquers the coast from the Saña or Jequetepeque valley south to Santa"],["c. 1375","Chimor absorbs the Lambayeque valley and moves Sicán metalworkers to Chan Chan"],["c. 1450","About 140 children and 200 young llamas are sacrificed at Huanchaquito near Chan Chan"],["c. 1470","Inca forces under Topa Inca Yupanqui conquer Chimor; Minchançaman is taken to Cusco"],["1986","Chan Chan becomes a UNESCO World Heritage Site and is listed as in danger"]]},
  "Wari Empire": {t:["From a city near Ayacucho, Wari spread planned administrative centres and colonies across highland Peru between about 600 and 1000.","Its tapestry tunics, pottery and Staff God imagery travelled widely, and feasts with maize and molle beer helped bind local leaders to the state.","The state broke up around 1000, but its roads, terraces and cord records foreshadowed the institutions of the Inca Empire."],dyk:"When Wari colonists left Cerro Baúl around 1000, they held a final feast, then burned their brewery and threw their drinking cups into the flames.",ev:[["c. 600","Wari emerges as a state in the Ayacucho basin of the central Peruvian highlands"],["7th century","Wari builds Pikillacta near Cusco and settles colonists on Cerro Baúl in Moquegua"],["c. 750","Royal and noble women are buried with rich offerings at El Castillo de Huarmey"],["c. 800","Wari officials record information on knotted and wrapped cords, early forms of the khipu"],["c. 1000","Cerro Baúl is ritually burned and abandoned as the Wari state breaks apart"],["2013","Archaeologists announce an unlooted Wari mausoleum at El Castillo de Huarmey"]]},
  "Tiwanaku": {t:["A ceremonial city at about 3,850 metres near Lake Titicaca, Tiwanaku dominated the southern Andes between about 500 and 1000.","Raised fields, llama caravans and colonies in warm valleys sustained it, while its Staff God imagery spread across the southern Andes.","The city was abandoned around 1010–1050; recent radiocarbon dating suggests this came before the great drought of the 1100s."],dyk:"Divers off the Island of the Sun in Lake Titicaca have recovered Tiwanaku offerings of puma-shaped incense burners and the bones of sacrificed young llamas.",ev:[["c. 180","Tiwanaku is founded in the southern Titicaca basin, according to recent radiocarbon modelling"],["c. 580","Work begins on the Pumapunku platform"],["c. 600","Tiwanaku draws migrants from across the region as its red-slipped pottery spreads"],["c. 650","Construction of the Akapana, the largest platform mound of the city, is under way"],["c. 910","Burials in the city’s tombs cease and a century of violent deaths begins"],["c. 1010–1050","Permanent residence ends and the city is rapidly abandoned"],["2000","Tiwanaku is inscribed on the UNESCO World Heritage List"]]},
  "Neo-Inca State": {t:["Founded by Manco Inca in 1537, it kept the Inca monarchy, court and Sun cult alive in the mountains of Vilcabamba until 1572.","Its rulers combined guerrilla war with diplomacy, and Titu Cusi’s account of 1570 gave an Inca view of the Spanish conquest.","Viceroy Toledo’s army took Vilcabamba in 1572, and the execution of Túpac Amaru in Cusco ended independent Inca rule."],dyk:"Hiram Bingham III reached the ruins of Vilcabamba at Espíritu Pampa in 1911, but believed that Machu Picchu, which he had also explored that year, was the last Inca refuge.",ev:[["1536","Manco Inca rebels and besieges Spanish-held Cusco for some ten months"],["1537","Manco repulses the Spaniards at Ollantaytambo, then withdraws to Vitcos and Vilcabamba"],["1539","Gonzalo Pizarro invades Vilcabamba; Manco escapes but Cura Ocllo is captured"],["1544","Manco Inca is murdered at Vitcos by Spanish fugitives he had sheltered"],["1558","Sayri Túpac renounces his claims in Lima and settles at Yucay"],["1566","Titu Cusi Yupanqui accepts the Treaty of Acobamba"],["1570","Titu Cusi dictates his account of the conquest for Philip II of Spain"],["1572","Spanish forces take Vilcabamba; Túpac Amaru is captured and executed in Cusco"]]},
  "Toltec state": {t:["An Early Postclassic state ruled from Tula in Hidalgo, a city of perhaps 30,000–60,000 people at its height in the 11th century.","Its warrior statues, colonnaded halls and chacmools have close parallels at Chichén Itzá, though the nature of that link is debated.","The Aztecs revered the Toltecs as founders of civilisation; Tula itself was abandoned around 1150, amid a severe drought."],dyk:"In Nahuatl the word toltecatl, ‘Toltec’, came to mean a skilled artisan, and the Aztecs called art and refinement toltecayotl, ‘Toltec-ness’.",ev:[["c. 600–650","Monumental building begins at Tula Chico, the first civic centre of Tula"],["c. 900","Construction starts at Tula Grande, the new ceremonial centre to the south"],["c. 950","The growing city absorbs the populations of Tula Chico and Cerro Magoni"],["c. 1050","The Late Tollan phase begins; the city covers about 16 square kilometres"],["1149","A severe drought begins, lasting until about 1167"],["c. 1150","Tula is largely abandoned and the Toltec state comes to an end"],["c. 1175","The Palacio Quemado and the ceremonial centre are burned"]]},
  "Purépecha Empire": {t:["A kingdom of western Mexico centred on Lake Pátzcuaro, ruled from Tzintzuntzan by a king the Spaniards called the cazonci.","In the late 1470s it routed an Aztec army led by Axayacatl, and the Aztecs never conquered it.","Its smiths led Mesoamerica in copper and bronze; it submitted to Spain in 1522, and its last king was executed in 1530."],dyk:"The Relación de Michoacán, the main source for the kingdom’s history, was illustrated with 44 paintings by Purépecha artists and is kept today in the royal library of El Escorial in Spain.",ev:[["c. 1350","Tariácuri unites the communities of the Lake Pátzcuaro basin"],["c. 1450","Power is concentrated at Tzintzuntzan, the kingdom’s only true city"],["c. 1478","Purépecha forces rout the Aztec army of Axayacatl near Taximaroa"],["1520","King Zuangua dies, probably of smallpox, and Tangaxuan II succeeds him"],["1522","Cristóbal de Olid enters Tzintzuntzan and Tangaxuan II submits to Spain"],["1530","Nuño de Guzmán has Tangaxuan II executed on 14 February"],["1536","Vasco de Quiroga is appointed the first bishop of Michoacán"]]},
  "Tlaxcala": {t:["A confederation of four Nahua city-states east of the Valley of Mexico, governed by its rulers and lords in council.","It resisted the Aztec Triple Alliance for generations despite the flower wars and a reported embargo on salt and cotton.","Its alliance with Hernán Cortés in 1519 supplied the warriors and support that brought down Tenochtitlan in 1521."],dyk:"Hernán Cortés compared the government of Tlaxcala to those of Venice, Genoa and Pisa, because, he wrote, it had no single supreme ruler.",ev:[["1348","Traditional date for the foundation of Tlaxcala by Teochichimec migrants"],["c. 1384","Quiahuixtlan completes the confederation of four altepetl"],["c. 1454","The Triple Alliance begins the ‘flower wars’ against Tlaxcala and its neighbours"],["c. 1504","Large-scale war with the Aztecs and Huexotzinco begins under Moctezuma II"],["1519","Tlaxcala fights Hernán Cortés, then allies with him on 23 September"],["1520","The Spaniards shelter in Tlaxcala after La Noche Triste and the Battle of Otumba"],["1521","Tlaxcalan forces help take Tenochtitlan, which falls on 13 August"]]},
  "League of Mayapan": {t:["From about 1220 to the 1440s the lords of northern Yucatán shared power in the walled city of Mayapan under the leadership of the Cocom.","Its potters made god-shaped incense burners, and its canoe traders linked Yucatán with the Gulf Coast, Belize and Honduras.","Around 1441 a Xiu-led revolt killed the Cocom lords; Mayapan was abandoned and Yucatán split into rival provinces."],dyk:"According to Diego de Landa, one son of the Cocom ruler survived the massacre of his family at Mayapan only because he was away trading in Honduras.",ev:[["c. 1100","Chichen Itza loses its dominance over northern Yucatán"],["1185–1204","Chronicles place Hunac Ceel\u0027s overthrow of Chac Xib Chac of Chichen Itza in this katun"],["c. 1220","Mayapan emerges as the capital of a confederacy of northern Yucatec lords"],["c. 1350–1400","Mass graves of dismembered, burned bodies mark violence inside the city"],["c. 1400","A long drought begins as rivalry grows between the Cocom and the Xiu"],["c. 1441","Nobles led by the Xiu kill the Cocom ruler; Mayapan is sacked and abandoned"],["1536","The Cocom of Sotuta massacre Xiu pilgrims at Otzmal"],["1542","The Spanish found Mérida, and the Xiu lord of Maní makes peace with them"]]},
  "Tikal": {t:["Tikal, ancient Mutal, was one of the two great powers of the Classic Maya, a city of tens of thousands in Guatemala\u0027s Petén forest.","In 378 a warrior linked with Teotihuacan remade its dynasty, and its long rivalry with the Snake kingdom of Calakmul shaped Maya politics.","Victories in 695 and 743–744 restored its power in an age of giant temples, but its kings vanished in the ninth-century collapse."],dyk:"Carved wooden lintels from Tikal\u0027s Temple IV, one of them celebrating a victory of 743, were taken to Switzerland in 1877 and are still in a museum in Basel.",ev:[["c. 90","Yax Ehb Xook, later honoured as founder of the royal line, rules at Tikal"],["292","Stela 29 records one of the earliest Long Count dates in the Maya lowlands"],["378","Sihyaj K\u0027ahk\u0027, linked with Teotihuacan, arrives and King Chak Tok Ich\u0027aak I dies"],["562","Tikal suffers a \u0027star war\u0027 defeat recorded at Caracol, opening a long hiatus"],["657","Calakmul\u0027s Yuknoom Ch\u0027een II drives King Nuun Ujol Chaak from Tikal"],["695","Jasaw Chan K\u0027awiil I defeats Yich\u0027aak K\u0027ahk\u0027 of Calakmul"],["743–744","Yik\u0027in Chan K\u0027awiil defeats El Perú and Naranjo, allies of Calakmul"],["869","Stela 11, Tikal\u0027s last dated monument, is raised in the Great Plaza"]]},
  "Muisca Confederation": {t:["Chibchan-speaking chiefdoms in Colombia\u0027s eastern highlands, led by the zipa of Bacatá in the south and the zaque of Hunza in the north.","They traded salt, cotton cloth and emeralds for gold, which their smiths cast into ornaments and votive figures offered in sacred lakes.","A small Spanish force under Gonzalo Jiménez de Quesada conquered them in 1537–1540 and founded Bogotá in the zipas\u0027 lands."],dyk:"A small gold raft found in a cave at Pasca in 1969 shows a Muisca chief and his attendants afloat, the kind of lake ceremony behind the legend of El Dorado.",ev:[["c. 800","The Early Muisca period begins in the highland basins of the Eastern Ranges"],["c. 1490","Chroniclers say the zipa Saguamanchica and zaque Michuá both die in battle near Chocontá"],["1514","Tisquesusa becomes zipa after Nemequene dies of a war wound"],["1537","Quesada\u0027s expedition enters Muisca lands and seizes the zaque at Hunza"],["1538","Santa Fe de Bogotá is founded on 6 August in the zipas\u0027 former lands"],["1539","The zipa Sagipa dies after torture; Tunja is founded on 6 August"],["1540","The last zaque, Aquiminzaque, is beheaded at Tunja"],["1969","A gold votive raft is found in a cave at Pasca"]]},
  "Cahokia": {t:["The largest Mississippian centre, built from about 1050 on the Mississippi floodplain opposite present-day St Louis.","Its Monks Mound, about 30 metres high, is the largest prehistoric earthwork in the Americas.","From the late 12th century the city shrank behind a palisade, and by about 1350 it was largely abandoned."],dyk:"From the centre of Cahokia’s reconstructed Woodhenge, a circle of 48 timber posts, the sun rises over Monks Mound at the spring and autumn equinoxes.",ev:[["c. 1050","Villages on the American Bottom are rebuilt to a grand plan around the Grand Plaza"],["c. 1100","Cahokia reaches its peak, with perhaps 10,000–20,000 people"],["c. 1165","A walled compound in the East St Louis precinct is burned"],["c. 1175","A palisade with bastions is built around the central precinct"],["c. 1200","Monks Mound receives its last major addition as the population falls"],["c. 1350","Cahokia is largely abandoned"],["1982","Cahokia Mounds becomes a UNESCO World Heritage Site"]]},
  "Powhatan Confederacy": {t:["A paramount chiefdom of some 30 Algonquian peoples in coastal Virginia, built by Wahunsenacah, whom the English called Powhatan.","It met the founders of Jamestown in 1607 and nearly destroyed the colony in 1609–1610 and again in 1622.","Defeated in 1646, its peoples became tributaries of Virginia; the Pamunkey and Mattaponi keep reservations confirmed in 1677."],dyk:"Some of the first Native American words to enter English came from Powhatan, among them raccoon, moccasin, tomahawk and persimmon.",ev:[["1570","Spanish Jesuits found the Ajacán mission, destroyed by local people the next year"],["c. 1597","Wahunsenacah kills the chief of the Kecoughtan and installs his son"],["1607","The English found Jamestown; John Smith is brought before Wahunsenacah"],["1614","Pocahontas marries John Rolfe, ending the First Anglo-Powhatan War"],["1622","Opechancanough’s coordinated attacks kill some 347 colonists"],["1646","Opechancanough is captured; the Treaty of 1646 makes the Powhatan tributaries"],["1677","Cockacoeske signs the Treaty of Middle Plantation"]]},
  "Cherokee Nation": {t:["A Native American republic that wrote down its laws from 1808 and adopted a constitution with three branches in 1827.","Sequoyah’s syllabary spread literacy in Cherokee, and the Cherokee Phoenix of 1828 printed English and Cherokee side by side.","Forced west on the Trail of Tears in 1838–1839, the Nation rebuilt at Tahlequah but lost its self-government when Oklahoma became a state in 1907."],dyk:"The Cherokee Stand Watie was the last Confederate general in the field to surrender, on 23 June 1865, more than two months after Lee’s surrender at Appomattox.",ev:[["1794","The Chickamauga Cherokee make peace with the United States at Tellico Blockhouse"],["1808","The first written Cherokee law creates the Lighthorse Guard"],["1827","The Cherokee Nation adopts a written constitution"],["1828","The Cherokee Phoenix appears at New Echota; John Ross is elected principal chief"],["1832","Worcester v. Georgia rules that Georgia’s laws have no force in the Cherokee Nation"],["1838","Forced removal on the Trail of Tears begins"],["1839","An Act of Union reunites the Cherokee, with Tahlequah as capital"],["1907","Oklahoma statehood ends the Nation’s self-government"]]},
  "Comancheria": {t:["Comancheria was the domain of the Nʉmʉnʉʉ, a people who moved from the Shoshone homelands onto the southern Plains around 1700.","Horses and bison sustained a decentralised society of bands and divisions that traded and raided from New Mexico to Texas and Mexico.","Epidemics, the destruction of the bison and US campaigns ended its independence; the last band surrendered at Fort Sill in 1875."],dyk:"In 1944 fourteen Comanche code talkers landed at Utah Beach with the US 4th Infantry Division, using their own language to pass army messages in Normandy.",ev:[["1706","Spanish records first mention the Comanche, allied with the Utes, near Taos"],["1758","Comanches and allies attack the Spanish mission of San Sabá in Texas"],["1779","Juan Bautista de Anza’s expedition kills the war leader Cuerno Verde"],["1786","Ecueracapa concludes peace with New Mexico under Governor Anza"],["1840","Council House Fight in San Antonio; Buffalo Hump leads a great raid to the coast"],["1867","The Medicine Lodge Treaty assigns a reservation in Indian Territory"],["1874","Mackenzie’s troops destroy the Comanche horse herd in Palo Duro Canyon"],["1875","Quanah Parker’s Kwahadi band surrenders at Fort Sill"]]},
  "Republic of Colombia": {t:["The constitution of 1886, inspired by Rafael Núñez, made Colombia a centralised Catholic republic and lasted, much amended, until 1991.","The republic lost Panama in 1903 and lived through La Violencia and a long armed conflict with guerrillas, paramilitaries and cartels.","The constitution of 1991 and the 2016 peace agreement with the FARC reshaped a country that now has about 53 million people."],dyk:"Rafael Núñez, the president behind the constitution of 1886, also wrote the words of Colombia’s national anthem, “¡Oh gloria inmarcesible!”, made official in 1920.",ev:[["1886","The constitution of August 1886 creates the centralised Republic of Colombia"],["1899–1902","The Thousand Days’ War between Liberal rebels and the Conservative government"],["1903","Panama secedes with United States support"],["1948","The assassination of Jorge Eliécer Gaitán sets off the Bogotazo and deepens La Violencia"],["1958","The National Front begins sixteen years of shared Liberal–Conservative rule"],["1991","A new constitution replaces the charter of 1886"],["2016","The government and the FARC sign a peace agreement"],["2022","Gustavo Petro becomes Colombia’s first left-wing president"]]},
  "Republic of Paraguay": {t:["Paraguay broke from Spanish rule and from Buenos Aires in 1811 and was isolated for decades under the dictator José Gaspar Rodríguez de Francia.","The War of the Triple Alliance of 1864–1870 against Brazil, Argentina and Uruguay killed a large share of its people, by some estimates over half.","It won the Chaco War against Bolivia in 1932–1935, lived under Stroessner from 1954 to 1989 and has been a democracy since the constitution of 1992."],dyk:"Paraguay’s Presidente Hayes department and the town of Villa Hayes are named after the US president Rutherford B. Hayes, whose arbitration award of 1878 gave Paraguay the disputed Chaco.",ev:[["1811","Paraguay defeats Belgrano’s army and ends the Spanish governor’s authority"],["1814","José Gaspar Rodríguez de Francia becomes supreme dictator"],["1842","A congress formally declares Paraguay’s independence"],["1864–1870","The War of the Triple Alliance against Brazil, Argentina and Uruguay"],["1932–1935","Paraguay defeats Bolivia in the Chaco War"],["1954","Alfredo Stroessner seizes power and rules until 1989"],["1984","The Itaipú dam, shared with Brazil, begins generating power"],["1992","A democratic constitution makes Guaraní an official language"]]},
  "Kilwa Sultanate": {t:["An island sultanate off southern Tanzania that grew rich as the middleman between the gold of the Zimbabwe plateau and the Indian Ocean.","Its Great Mosque, the palace of Husuni Kubwa and its copper coinage made Kilwa a showpiece of medieval Swahili culture.","Factional strife weakened it in the 15th century, and the Portuguese sack of 1505 ended its power on the coast."],dyk:"In 1944 five copper coins from Kilwa were found on Marchinbar Island off northern Australia, thousands of kilometres from East Africa; how they got there is still unknown.",ev:[["c. 957","Traditional date for the founding of the dynasty by Ali ibn al-Hasan of Shiraz"],["c. 1277","The Mahdali dynasty, of Yemeni origin, seizes power in Kilwa"],["c. 1310","Al-Hasan ibn Sulaiman becomes sultan and begins the palace of Husuni Kubwa"],["c. 1331","Ibn Battuta visits Kilwa and praises the generosity of its sultan"],["1502","Vasco da Gama forces Emir Ibrahim to pay tribute to Portugal"],["1505","Francisco de Almeida sacks Kilwa and builds Fort Santiago"],["1512","The Portuguese withdraw their garrison from Kilwa"],["1981","The ruins of Kilwa Kisiwani and Songo Mnara become a UNESCO World Heritage Site"]]},
  "Kingdom of Zimbabwe": {t:["A Shona kingdom on the Zimbabwe plateau, ruled from Great Zimbabwe, which grew rich on cattle and on gold and ivory sent to the coast at Sofala.","Its dry-stone walls, up to 11 metres high in the Great Enclosure, are the largest precolonial stone structures in southern Africa.","Power passed to the Mutapa and Butua states after about 1450, but the ruins gave the modern nation of Zimbabwe its name and emblem."],dyk:"The Zimbabwe Bird on the national flag copies soapstone carvings from the ruins; one was taken by a hunter in 1889 and sold to Cecil Rhodes, and four were returned from South Africa in 1981.",ev:[["c. 1000","Farming communities settle the hill at Great Zimbabwe"],["c. 1200","Builders begin enclosing the Hill Complex with dry-stone walls"],["14th century","The Great Enclosure and its conical tower are built south of the hill"],["c. 1450","Great Zimbabwe loses its role as the Mutapa and Butua states rise"],["1531","Vicente Pegado, captain at Sofala, records the name ‘Symbaoe’ for the stone buildings"],["1871","Karl Mauch visits the ruins and attributes them to the Queen of Sheba"],["1929","Gertrude Caton-Thompson’s excavations confirm the site’s African and medieval origin"],["1980","Independent Zimbabwe takes its name from the ruins"]]},
  "Kingdom of Mapungubwe": {t:["A kingdom at the Shashe–Limpopo confluence whose rulers moved onto Mapungubwe Hill around 1220, apart from the commoners living below.","It grew rich on cattle and on ivory and gold traded to the coast, and buried its elite with gold, including the famous gold-foil rhinoceros.","Abandoned around 1290, it passed leadership north to Great Zimbabwe; today it is a UNESCO site and a national symbol of South Africa."],dyk:"The golden rhinoceros of Mapungubwe, small enough to stand in the palm of a hand, was made of thin gold sheet fixed with tiny gold tacks onto a carved wooden core that has since decayed.",ev:[["c. 900","Zhizo farmers at Schroda begin trading ivory with the coast"],["c. 1000","Leopard’s Kopje newcomers settle K2 (Bambandyanalo), which becomes the region’s main centre"],["c. 1220","The ruling elite moves onto Mapungubwe Hill, apart from the commoners below"],["c. 1250","The capital and its surroundings hold some 5,000 people"],["c. 1290","Mapungubwe Hill is abandoned and leadership passes north to Great Zimbabwe"],["1933","The University of Pretoria begins excavations on Mapungubwe Hill"],["2002","South Africa institutes the Order of Mapungubwe, its highest honour"],["2003","The Mapungubwe Cultural Landscape becomes a UNESCO World Heritage Site"]]},
  "Kingdom of Ndongo": {t:["An Mbundu kingdom in the highlands of northern Angola whose rulers’ title, ngola, gave the country of Angola its name.","From 1579 it fought Portuguese Angola, winning at Lukala in 1590 but seeing its capital, Kabasa, sacked after 1617.","Queen Njinga resisted from 1624 to 1656, allied with Matamba, the Imbangala and the Dutch; Pungo Andongo fell in 1671."],dyk:"The ‘20. and odd’ Africans landed in English Virginia in August 1619 were probably captives from Portuguese campaigns against Ndongo, shipped from Luanda on a slave ship bound for Veracruz.",ev:[["1518","The ngola sends envoys to Portugal asking for missionaries"],["1560","A Portuguese embassy under Paulo Dias de Novais arrives in Ndongo"],["1579","Ngola Kilombo kia Kasenda has the Portuguese at Kabasa killed, starting a long war"],["1590","Ndongo and Matamba rout a Portuguese army at the Battle of Lukala"],["1622","Njinga Mbande negotiates peace in Luanda and is baptised as Ana de Sousa"],["1626","Portugal makes war on Njinga and sets up rival kings at Pungo Andongo"],["1647","Njinga and her Dutch allies defeat the Portuguese at the Battle of Kombi"],["1671","The Portuguese take Pungo Andongo, ending the Kingdom of Ndongo"]]},
  "Kingdom of Kano": {t:["A Hausa kingdom centred on the walled city of Kano, ruled by 43 kings from Bagauda, dated to 999, to the Fulani jihad.","Muhammad Rumfa (1463–1499) built the Gidan Rumfa, founded the Kurmi market and took advice on Islamic rule from al-Maghili.","Indigo-dyed cloth, leather, kola and the caravan trade made Kano the leading market city of the central Sudan."],dyk:"According to the Kano Chronicle, cowrie shells, later the everyday small change of Hausaland, first reached the region in the reign of Muhammad Sharefa (1703–1731).",ev:[["999","Bagauda becomes the first king of Kano, by the Kano Chronicle’s reckoning"],["c. 1350","Under Yaji, Wangara Muslims from Mali bring Islam to the Kano court"],["c. 1400","Kanajeji equips his cavalry with quilted armour, iron helmets and coats of mail"],["c. 1440","Abdullahi Burja pays tribute to Bornu and opens trade roads to Gonja"],["1463","Muhammad Rumfa becomes king; he builds the Gidan Rumfa and founds the Kurmi market"],["c. 1671","Kwararafa (Jukun) forces break into Kano and the king flees to Daura"],["1781","Muhammad Alwali II, the last Hausa king of Kano, comes to the throne"],["1805","The Fulani jihad reaches Kano; Alwali is later driven out and killed at Burum-Burum"]]},
  "Kingdom of Nri": {t:["An Igbo sacred kingdom whose priest-king, the Eze Nri, held ritual rather than military authority over much of northern Igboland.","Nri agents marked with ichi scars cleansed abominations, settled disputes and conferred Ozo titles across a wide area.","Its traditional history begins in 948; in 1911 British officials forced the Eze Nri to renounce his ritual powers."],dyk:"A dignitary buried at nearby Igbo-Ukwu had been buried seated on a wooden stool; the Eze Nri, too, were buried seated, in a wood-lined chamber.",ev:[["948","Traditional date for Eri, founder of the Nri line, in Onwuejeogwu’s reconstruction"],["1043","Ifikuanim, remembered as the first Eze Nri, begins his reign (traditional date)"],["c. 850–1150","Bronzes, beads and a seated burial are deposited at Igbo-Ukwu, near Nri"],["c. 1580","Nri influence reaches Igbo communities west of the Niger, by one reconstruction"],["1700s","Nri influence declines as the Atlantic slave trade and the Aro network expand"],["1901–1902","The Anglo-Aro War opens the Igbo interior to British rule"],["1911","A British expedition forces the Eze Nri to renounce his ritual powers"]]},
  "Kingdom of Burundi": {t:["A sacred kingship in the hills east of Lake Tanganyika, whose dynasty tradition traces to Ntare Rushatsi around 1680.","Ntare IV Rugamba roughly doubled its territory in the early 19th century, giving Burundi borders close to today’s.","It survived German and Belgian rule to become independent in 1962, but army officer Michel Micombero abolished it in 1966."],dyk:"The mountain gorilla’s species, Gorilla beringei, is named after Robert von Beringe, the German officer who shot two of the apes in 1902 and in 1903 led the campaign that forced Mwezi IV Gisabo to submit.",ev:[["c. 1680","Ntare Rushatsi founds the royal dynasty, according to tradition"],["c. 1800","Burundi and Rwanda partition the Kingdom of Bugesera"],["c. 1885","Mwezi IV Gisabo’s warriors repel the slave-trading forces of Rumaliza"],["1903","Mwezi IV submits to German rule in the Treaty of Kiganda"],["1916","Belgian troops occupy Burundi during the First World War"],["1961","UPRONA wins the elections; its leader, Prince Louis Rwagasore, is assassinated"],["1962","Burundi becomes independent as a constitutional monarchy under Mwambutsa IV"],["1966","Michel Micombero deposes Ntare V and proclaims a republic"]]},
  "Bamana Empire": {t:["A Bamana kingdom on the middle Niger, founded around 1712 by Biton Kulibali, who turned a young men’s association into an army.","Its power rested on the tonjon, soldiers of captive origin, and on the trade of Muslim Maraka towns such as Sinsani.","It resisted the Fulbe jihads until Umar Tall took Ségou in 1861; its kings live on in the griots’ epics."],dyk:"When Mungo Park reached Ségou in 1796, King Monzon (Mansong) would not receive him but sent him 5,000 cowries to buy food for his journey.",ev:[["c. 1712","Biton Kulibali turns the ton of Ségou into an army and makes himself king"],["c. 1754","Biton defeats Kaarta’s Massassi rulers and captures their king, Foulakoro"],["1766","Ngolo Diarra, a former tonjon, seizes power and founds the Diarra dynasty"],["1796","Mungo Park reaches the Niger at Ségou during the reign of Monzon Diarra"],["1818","Seku Amadu’s victory at Noukouma begins the Massina jihad that takes Djenné"],["1860","Umar Tall’s army defeats the Bamana at Woïtala"],["1861","Umar Tall takes Ségou and makes it the capital of the Toucouleur Empire"]]},
  "Ancestral Puebloans": {t:["The Ancestral Puebloans farmed the dry Colorado Plateau for some three thousand years, moving from caves and pithouses to villages of joined stone and adobe rooms called pueblos.","Between about 850 and 1150 they built the great houses of Chaco Canyon, linked by roads to dozens of outlying communities, and in the 13th century the cliff dwellings of Mesa Verde.","Drought and conflict led them to leave the Four Corners by about 1300 for the Rio Grande, Zuni, Acoma and Hopi country, where their descendants, the Pueblo peoples, still live."],dyk:"Many Ancestral Puebloan buildings can be dated to the year their roof beams were felled: in 1929 a charred beam found at Show Low, Arizona, closed the gap in A. E. Douglass’s tree-ring record and gave the ruins exact dates.",ev:[["c. 1500 BCE","Maize farming begins on the Colorado Plateau in the Basketmaker II period"],["c. 500","Basketmaker III villages take up pottery, the bow and arrow and beans"],["c. 850–1150","The great houses of Chaco Canyon, Pueblo Bonito among them, are built and linked by roads"],["c. 1130–1150","Drought; Chaco’s power fades and Aztec on the Animas River becomes a leading centre"],["c. 1190–1285","The cliff dwellings of Mesa Verde, Cliff Palace among them, are built and lived in"],["1276–1299","The Great Drought; by about 1300 the Four Corners region is empty as its people move south and east"],["1540","The Coronado expedition storms the Zuni town of Hawikuh and reaches the Rio Grande pueblos"],["1598","Juan de Oñate founds the Spanish colony of New Mexico"]]},
  "Celts": {t:["“Celts” was a Greek name for peoples of the European interior; today it is used above all for speakers of Celtic languages, who in the Iron Age lived from Iberia and Ireland to the Danube.","Archaeologists associate them with the Hallstatt and La Tène cultures, known for salt mines, rich princely burials, hillforts, the walled towns called oppida and a flowing, abstract art.","Celtic war bands sacked Rome and attacked Delphi, but Rome conquered most Celtic lands from the 3rd century BCE to the 1st century CE; the languages survive in Ireland, Scotland, Wales and Brittany."],dyk:"The Greek bronze krater, a vessel for mixing wine, found in a princely grave at Vix in Burgundy stands 1.64 metres high, weighs 208.6 kilograms and holds about 1,100 litres: the largest Greek bronze vessel known.",ev:[["c. 800 BCE","Iron working spreads in central Europe and the Hallstatt culture begins"],["c. 600 BCE","Greeks from Phocaea found Massalia; Greek wine and bronzes reach the Hallstatt princes"],["c. 450 BCE","The La Tène culture and its art style emerge between Champagne and Bohemia"],["c. 390 BCE","Gauls under Brennus rout the Romans at the Allia and sack Rome"],["279–278 BCE","A Celtic army attacks Delphi; three tribes cross into Asia Minor and settle in Galatia"],["225 BCE","Rome destroys a Gallic army at Telamon and goes on to conquer Cisalpine Gaul"],["58–50 BCE","Julius Caesar conquers Gaul; Vercingetorix surrenders at Alesia in 52 BCE"],["43–84 CE","Rome conquers most of Britain, crushing Boudica’s revolt and winning at Mons Graupius"]]},
  "Etruscans": {t:["The Etruscans of central Italy built independent city-states such as Veii, Tarquinia, Caere and Vulci, rich from metals, farming and trade with Greeks and Phoenicians from the 8th century BCE.","They spoke a language unrelated to Latin or Greek, wrote it in an alphabet taken from the Greeks, and are known above all from their tombs, with wall paintings, sculpture and rich grave goods.","By Roman tradition Etruscan kings ruled Rome in the 6th century BCE; from the capture of Veii in 396 BCE Rome conquered Etruria city by city and absorbed its people in the 1st century BCE."],dyk:"The longest known Etruscan text, probably a ritual calendar, written on a linen book, survives only because the cloth was cut into strips to wrap an Egyptian mummy, now in the Archaeological Museum in Zagreb.",ev:[["c. 900 BCE","The Villanovan culture of the early Iron Age appears on the sites of the later Etruscan cities"],["c. 700 BCE","The first Etruscan inscriptions are written in an alphabet adapted from the Greek"],["616–509 BCE","By Roman tradition, Etruscan kings rule Rome, from Tarquinius Priscus to Tarquinius Superbus"],["c. 540 BCE","Etruscan and Carthaginian ships fight the Phocaean Greeks off Alalia in Corsica"],["474 BCE","Hiero I of Syracuse destroys an Etruscan fleet off Cumae"],["396 BCE","Rome captures Veii after a long siege"],["264 BCE","Rome sacks Volsinii and moves its people to a new site"],["90 BCE","After the outbreak of the Social War the Etruscans receive Roman citizenship"]]},
  "Indus Valley Civilisation": {t:["The most extensive of the first urban civilisations, it covered more ground than Egypt and Mesopotamia together, with over a thousand known sites and great cities such as Harappa and Mohenjo-daro.","Its builders laid out streets on a grid, used bricks of standard proportions and drained whole neighbourhoods with covered sewers, yet left no palaces, royal tombs or images of war.","Its short inscriptions remain undeciphered, so its language, rulers and beliefs are known only through archaeology and through Mesopotamian texts that call it Meluhha."],dyk:"A cylinder seal of the time of the Akkadian Empire, now in the Louvre, belonged to a man named Shu-ilishu, who called himself “interpreter of the Meluhhan language”: Mesopotamians needed translators to deal with traders from the Indus.",ev:[["c. 7000 BCE","Farmers settle at Mehrgarh in Balochistan, beginning the long prelude to the Indus cities"],["c. 3300 BCE","The Early Harappan phase begins, with farming villages and small towns across the Indus plains"],["c. 2600 BCE","The mature phase begins: Harappa, Mohenjo-daro and other cities are laid out with grid streets and drains"],["c. 2300 BCE","Sargon of Akkad boasts of ships from Meluhha, Magan and Dilmun moored at his capital"],["c. 1900 BCE","The cities decline, and seals, script and standard weights fall out of use"],["c. 1300 BCE","The last Late Harappan cultures give way to the new village cultures of northern India"],["1921–1922","Excavations at Harappa under Daya Ram Sahni and at Mohenjo-daro under R. D. Banerji uncover the same seals"],["1924","John Marshall announces the discovery of a forgotten civilisation of the Indus"]]},
  "Lapita culture": {t:["The Lapita culture, named after a site in New Caledonia and known by its finely stamped pottery, appeared in the Bismarck Archipelago north-east of New Guinea between about 1500 and 1300 BCE.","Within a few centuries its seafarers crossed hundreds of kilometres of open ocean to become the first people of Vanuatu, New Caledonia, Fiji, Tonga and Samoa.","Descended largely from Austronesian voyagers of Island Southeast Asia, they probably spoke the ancestor of the Oceanic languages, and their descendants in Tonga and Samoa became the Polynesians."],dyk:"The name Lapita comes from a misunderstanding: at the New Caledonian site dug in 1952, archaeologists took it from xapeta’a, a word in the Haveke language meaning “to dig a hole” or “the place where one digs”.",ev:[["c. 1500–1300 BCE","Lapita pottery and settlements appear in the Bismarck Archipelago, north-east of New Guinea"],["c. 1000 BCE","Lapita voyagers become the first settlers of Vanuatu, New Caledonia and Fiji"],["c. 880 BCE","Nukuleka on Tongatapu is founded, the oldest dated settlement in Polynesia"],["c. 800 BCE","Settlers reach Samoa, leaving decorated pottery at Mulifanua on Upolu"],["c. 500 BCE","Dentate-stamped decoration has died out; plain pottery continues in Tonga and Samoa"],["1909","Father Otto Meyer finds the first recorded Lapita sherds on Watom Island, off New Britain"],["1952","Edward Gifford and Richard Shutler excavate the site of Lapita in New Caledonia"],["2003","The Lapita cemetery at Teouma on Efate, Vanuatu, is discovered"]]},
  "Maya civilisation": {t:["From the 1st millennium BCE to the Spanish conquest, the Maya of southern Mexico and Central America built hundreds of cities, from El Mirador and Tikal to Chichén Itzá, but never a single state.","Their scribes created the most complete writing system of the ancient Americas, recording the deeds of holy kings in precisely dated inscriptions, most of which have been deciphered since the 1950s.","The southern lowland cities were abandoned in the 9th and 10th centuries, but Maya kingdoms lasted in Yucatán and the highlands until the Spanish conquest, and well over six million Maya live today."],dyk:"In 2018 an airborne laser survey of the forests of northern Guatemala revealed more than 60,000 ancient Maya structures, from houses and reservoirs to causeways and defensive walls, many of them previously unknown.",ev:[["c. 1000 BCE","Maya farming communities build the first great ceremonial platforms, at Ceibal and Aguada Fénix"],["c. 300 BCE–150 CE","El Mirador flourishes, its La Danta complex rising some 70 metres above the forest floor"],["378","Siyaj K’ak', a war leader linked with Teotihuacan, arrives at Tikal and a new dynasty takes power"],["615","K’inich Janaab Pakal begins his 68-year reign at Palenque"],["c. 750–950","In the Classic Maya collapse the southern lowland kingdoms stop raising monuments, and their cities empty"],["c. 900–1100","Chichén Itzá is the leading power of northern Yucatán"],["1524","Pedro de Alvarado conquers the K’iche' kingdom of the Guatemalan highlands"],["1697","The Spanish take Nojpetén, capital of the Itza, the last independent Maya kingdom"]]},
  "Minoan civilisation": {t:["From about 1900 BCE the people of Bronze Age Crete built Europe’s first palaces, at Knossos, Phaistos and Malia: complexes of courts, storerooms and workshops that organised the island’s wealth.","Their wall paintings, carved seals, fine pottery and images of bull-leaping influenced the whole Aegean, and their ships carried their trade to Egypt, Cyprus and the Levant.","Their Linear A script is still undeciphered; after about 1450 BCE Mycenaean Greeks ruled from Knossos, and the name “Minoan” itself is modern, taken from the mythical King Minos."],dyk:"Wall paintings in Minoan style have been found far from Crete, at Tel Kabri in present-day Israel and at Tell el-Dab’a, the ancient Avaris in the Nile Delta, where they include scenes of young athletes leaping over bulls.",ev:[["c. 3100 BCE","The Early Minoan period begins as Crete enters the Bronze Age"],["c. 1900 BCE","The first palaces are built at Knossos, Phaistos and Malia"],["c. 1700 BCE","The first palaces are destroyed, probably by earthquakes, and rebuilt on a grander scale"],["17th or 16th century BCE","The eruption of Thera buries the town of Akrotiri under volcanic ash"],["c. 1450 BCE","Fires destroy palaces and villas across Crete; Mycenaean Greeks rule from Knossos"],["14th or 13th century BCE","The palace of Knossos is finally destroyed"],["c. 1200–1100 BCE","Cretans move to defensible heights such as Karphi as the Bronze Age ends"],["1900","Arthur Evans begins to excavate the palace of Knossos"]]},
  "Mississippian culture": {t:["The Mississippian culture was a way of life shared from about 800 to 1600 by many Native American peoples of the Mississippi valley and the South-East, built on maize farming and hereditary chiefs.","Its towns centred on earthen platform mounds and plazas, from Cahokia, the largest, to Moundville in Alabama, Etowah in Georgia and Spiro in Oklahoma.","Spanish expeditions from 1539 met its last great chiefdoms; after epidemics, wars and slave raids their peoples regrouped as the Creek, Choctaw, Chickasaw and other nations."],dyk:"Chunkey, a game in which players threw poles after a rolling stone disc, spread from the Cahokia region with Mississippian ways; Creek, Choctaw and Chickasaw men still played it in the 18th century, and the Cherokee have revived it.",ev:[["c. 800–1000","Emergent Mississippian villages in the central Mississippi valley come to depend on maize"],["c. 1050","Cahokia is rebuilt around a great plaza and becomes the largest town north of Mexico"],["c. 1120–1250","Mississippian ways spread across the South-East; Moundville becomes a regional capital"],["c. 1350","Cahokia, long in decline, is largely abandoned"],["c. 1450","Towns around the meeting of the Ohio and Mississippi are abandoned, leaving a “Vacant Quarter”"],["1539–1543","Hernando de Soto’s expedition marches through the Mississippian chiefdoms"],["1540","De Soto’s army burns the town of Mabila after an ambush; thousands of its people die"],["1566–1568","Juan Pardo’s expeditions build forts at Joara and other towns, destroyed by their people by 1568"]]},
  "Mycenaean civilisation": {t:["From about 1600 BCE warrior chiefs on the Greek mainland grew rich, as the gold of the shaft graves at Mycenae shows, and by 1400 BCE kings ruled palace states at Mycenae, Pylos, Thebes and elsewhere.","Their scribes wrote Linear B, deciphered in 1952 as the earliest known form of Greek, to record land, livestock, workers, weapons and offerings to gods such as Zeus and Poseidon.","Around 1200 BCE the palaces were destroyed and writing was forgotten; Homer’s epics, composed centuries later, remember Mycenae as Agamemnon’s city, but they are evidence of memory, not of fact."],dyk:"Zeus, Hera, Poseidon, Hermes and Dionysus are all named on Linear B tablets of about 1200 BCE from Pylos, the oldest written records of the Greek gods, some five centuries before Homer and Hesiod.",ev:[["c. 1600 BCE","Rich burials in the shaft graves of Mycenae mark the rise of a warrior elite"],["c. 1450 BCE","Mycenaean Greeks take over Knossos on Crete, where Linear B comes into use"],["c. 1250 BCE","The walls of Mycenae are extended and the Lion Gate is built"],["13th century BCE","A Hittite king writes to the king of Ahhiyawa as his “brother” in the Tawagalawa letter"],["c. 1200 BCE","A wave of destruction ends the palaces; Pylos burns around 1180 BCE"],["c. 1100 BCE","The last Mycenaean communities fade as Greece enters the Early Iron Age"],["1876","Heinrich Schliemann excavates the shaft graves of Grave Circle A at Mycenae"],["1952","Michael Ventris deciphers Linear B, showing that it records Greek"]]},
  "Nok culture": {t:["The Nok culture, named after the village in central Nigeria where its first sculpture was found in 1928, lasted from about 1500 BCE to around the turn of the Common Era.","From about 900 BCE its people made hollow clay figures of men and women with pierced eyes, elaborate hairstyles and jewellery, among the earliest sculpture known south of the Sahara.","Nok farmers grew pearl millet and smelted iron by the mid-first millennium BCE but lived in hamlets, not towns; looting for the art market has since ravaged most known sites."],dyk:"The first Nok sculpture was found in 1928 about 7 metres down in a tin mine, and a head found in 1943 served for a year as a scarecrow in a yam field before Bernard Fagg recognised it.",ev:[["c. 1500 BCE","Farming communities settle in central Nigeria: the Early Nok phase begins"],["c. 900 BCE","The Middle Nok phase opens; the first terracotta sculptures are made"],["c. 8th–6th century BCE","Iron smelting begins in the Nok region, by current estimates (the dates are debated)"],["c. 300 BCE","The Late Nok phase begins, known from only a few sites"],["c. 1 CE","Around the turn of the era the terracottas and the Nok settlements vanish from the record"],["1928","Colonel Dent Young finds the first Nok terracotta in a tin mine near the village of Nok"],["1943","A head used as a scarecrow leads Bernard Fagg to study the culture"],["2005","Goethe University Frankfurt begins long-term excavations of Nok sites"]]},
  "Olmecs": {t:["The Olmecs built the first great centres of Mesoamerica, San Lorenzo and then La Venta, in the tropical lowlands of Mexico’s Gulf Coast between about 1200 and 400 BCE.","Their sculptors moved basalt blocks of many tonnes from the Tuxtla Mountains to carve colossal heads and thrones, probably portraits and seats of rulers, and worked jade with great skill.","Their images of rulers, gods and the cosmos spread across Mesoamerica and helped shape the art and religion of later peoples such as the Maya, though how far they led that shared culture is debated."],dyk:"The Olmecs’ own name is unknown. “Olmec” comes from Nahuatl, the language of the Aztecs, in which the Olmeca were the “rubber people”, a name for those who lived on the Gulf Coast some two thousand years later.",ev:[["c. 1600 BCE","Offerings, among them the oldest known rubber balls, are laid in the sacred spring of El Manatí"],["c. 1200 BCE","San Lorenzo, above the Coatzacoalcos river, becomes the largest centre in Mesoamerica"],["c. 900 BCE","San Lorenzo declines, and La Venta in Tabasco becomes the leading Olmec centre"],["c. 900–500 BCE","Olmec-style reliefs are carved on the hillside of Chalcatzingo in central Mexico"],["c. 400 BCE","La Venta is abandoned, and the population of the Olmec heartland falls sharply"],["32 BCE","Stela C at Tres Zapotes, an Epi-Olmec monument, records one of the earliest Long Count dates"],["1862","The first known colossal head comes to light at Tres Zapotes, described by José María Melgar y Serrano"],["1938–1946","Matthew Stirling’s expeditions to Tres Zapotes, La Venta and San Lorenzo begin Olmec archaeology"]]},
  "Phoenicians": {t:["The Phoenicians were the Iron Age heirs of the Canaanite towns of the Lebanese coast: not one nation but rival city-states such as Tyre, Sidon, Byblos and Arwad, each with its own king.","Their merchants sold cedar, purple cloth, ivory and metalwork across the Near East, and from the 9th century BCE founded settlements from Cyprus to Spain, among them Carthage.","Their alphabet of 22 letters, taken up by the Greeks and the Aramaeans, is the ancestor of the Greek, Latin, Hebrew and Arabic scripts."],dyk:"Herodotus tells how Phoenician sailors sent by the pharaoh Necho II sailed round Africa in three years. He doubted their report that the sun had been on their right, the very detail that leads many scholars to take the voyage seriously.",ev:[["c. 1200–1150 BCE","The Late Bronze Age kingdoms collapse; the cities of the Lebanese coast emerge as independent kingdoms"],["c. 1000 BCE","The sarcophagus of King Ahiram of Byblos is inscribed in the Phoenician alphabet"],["10th century BCE","Hiram I makes Tyre the leading city; by the biblical account he sends cedar for Solomon’s temple"],["814 BCE","Tyrians traditionally found Carthage, as settlements spread to Cyprus, Sicily, Sardinia and Spain"],["677 BCE","Esarhaddon of Assyria captures rebellious Sidon and deports its people"],["c. 585–572 BCE","Tyre withstands a thirteen-year siege by Nebuchadnezzar II"],["539 BCE","The cities pass under Persian rule; their ships form the core of the Persian navy"],["332 BCE","Alexander the Great takes Tyre after a siege of about seven months"]]},
  "Scythians": {t:["The Scythians were Iranian-speaking horse nomads who from the 7th century BCE dominated the steppe north of the Black Sea, campaigned across the Near East and defied Darius I of Persia.","They left no writing of their own: we know them from Greek writers, above all Herodotus, who gave them most of Book 4 of his Histories, and from thousands of excavated burial mounds.","Their gold work of stags, panthers and griffins, and the treasures Greek goldsmiths made for their kings, belong to a wider Scythian world of related cultures that reached the Altai and Mongolia."],dyk:"Herodotus says the Scythians sent the invading Darius I a bird, a mouse, a frog and five arrows; one Persian read it as a warning that unless they could fly, burrow or swim away, Scythian arrows would kill them all.",ev:[["c. 800 BCE","The kurgan of Arzhan 1 is raised in Tuva, the earliest known burial with Scythian weapons, harness and animal art"],["670s BCE","Assyrian texts name the Scythians and their king Bartatua, who asks Esarhaddon for an Assyrian princess in marriage"],["c. 653–625 BCE","By Herodotus’s account, the Scythians of Madyes rule “Asia” for 28 years and raid as far as Palestine"],["c. 513 BCE","Darius I crosses the Danube to invade Scythia and withdraws without forcing a battle"],["c. 400–300 BCE","Royal kurgans such as Solokha, Chertomlyk and Tovsta Mohyla are raised on the lower Dnieper"],["339 BCE","King Ateas, who had extended his rule to the Danube, is killed fighting Philip II of Macedon"],["c. 110–107 BCE","Diophantus, general of Mithridates VI, defeats the Crimean Scythians of King Palakus"],["3rd century CE","Scythian Neapolis in Crimea is destroyed, probably by the Goths, ending the Late Scythian kingdom"]]},
  "Sogdians": {t:["The Sogdians, an Iranian people of the Zeravshan and Kashka Darya valleys in present-day Uzbekistan and Tajikistan, lived in oasis city-states such as Samarkand, Bukhara and Panjikent.","From the 4th to the 8th century CE their merchants dominated the trade between Central Asia and China, settling from the Tarim Basin to the Tang capital and serving Turkic and Chinese rulers.","Conquered by the Arabs in the early 8th century, they became Muslim and Persian- or Turkic-speaking, but their alphabet lives on, through the Uyghurs, in the Mongolian script."],dyk:"A Tang history claims that Sogdian parents put honey or sugar in a newborn son’s mouth and glue in his palm, so that he would grow up to speak sweet words and to hold on to money.",ev:[["c. 546–539 BCE","Cyrus the Great brings Sogdiana into the Achaemenid Empire"],["329–327 BCE","Alexander the Great conquers Sogdiana despite the resistance led by Spitamenes"],["c. 313","Sogdian merchants in China write the Ancient Letters, found near Dunhuang in 1907"],["568","The Sogdian Maniakh leads a Turkic embassy to the emperor Justin II in Constantinople"],["mid-7th century","The hall of the ambassadors at Afrasiab is painted for Varkhuman, king of Samarkand"],["712","The Arabs under Qutayba ibn Muslim take Samarkand"],["755–763","The An Lushan Rebellion, led by a general of Sogdian and Turkic parentage, shakes the Tang Dynasty"],["819–999","Under the Samanids the Sogdians become Muslim and come to speak Persian"]]},
  "Vikings": {t:["The Vikings were Scandinavian raiders, traders and settlers whose voyages between the 790s and the 1060s reached from Newfoundland to the Caspian Sea and from the Arctic to the Mediterranean.","Their raids fell hardest on monasteries and towns in Britain, Ireland and Francia, but they also founded Dublin, settled Iceland and Normandy, ruled much of England and gave a dynasty to the Rus’.","At home the age saw trading towns, the first kingdoms of Denmark, Norway and Sweden and conversion to Christianity, after which royal conquest took the place of free-roving raids."],dyk:"Wood cut with metal blades at L’Anse aux Meadows in Newfoundland has been dated to the year 1021 by a spike in radiocarbon that a solar storm of 993 left in tree rings: the earliest exact year known for Europeans in the Americas.",ev:[["793","Raiders plunder the monastery of Lindisfarne, the attack that usually marks the start of the Viking Age"],["860","Rus’ ships attack Constantinople; by tradition Rurik begins to rule at Novgorod two years later"],["865","The Great Heathen Army lands in England; Alfred the Great defeats it at Edington in 878"],["c. 870–930","Norse settlers take land in Iceland and found the Althing, its general assembly, about 930"],["911","Rollo receives lands around Rouen from Charles the Simple, the beginning of Normandy (traditional date)"],["c. 985","Erik the Red leads settlers from Iceland to Greenland"],["c. 1000","Leif Erikson sails to Vinland; Norse visitors cut wood at L’Anse aux Meadows in 1021"],["1066","Harald Hardrada of Norway is killed at Stamford Bridge, weeks before the Battle of Hastings"]]},
  "Abolitionism": {t:["Abolitionism grew from Quaker and evangelical protest into the first great campaigns of petitions, boycotts and public testimony, aimed first at the Atlantic slave trade and then at slavery itself.","Enslaved people fought for their own freedom throughout: the Haitian Revolution, great revolts in the British Caribbean and countless escapes pushed governments towards abolition.","By the time of Brazil’s Golden Law in 1888 slavery had been abolished throughout the Americas, but freedom rarely brought the formerly enslaved land, compensation or equality."],dyk:"Brazil’s Golden Law of 13 May 1888, which ended slavery in the last country of the Americas to keep it, has just two articles: the first declares slavery extinct in Brazil, the second revokes all provisions to the contrary.",ev:[["1787","Quakers and Anglicans found the Society for Effecting the Abolition of the Slave Trade in London"],["1791","Enslaved people rise in Saint-Domingue; their revolution ends slavery there and founds Haiti in 1804"],["1807","Britain and the United States ban the Atlantic slave trade"],["1831","Samuel Sharpe’s rising begins in Jamaica; in Boston William Lloyd Garrison founds The Liberator"],["1833","The Slavery Abolition Act frees the enslaved across most of the British Empire from 1834"],["1848","France and Denmark abolish slavery in their colonies"],["1865","The Thirteenth Amendment abolishes slavery throughout the United States"],["1888","Princess Isabel signs Brazil’s Golden Law, ending slavery in the last country of the Americas to keep it"]]},
  "Anti-apartheid movement": {t:["Opposition to apartheid joined African, Indian, coloured and white South Africans in campaigns of defiance, strikes and boycotts and, after the massacre at Sharpeville in 1960, in armed struggle.","Abroad, a worldwide movement of consumer, sports and cultural boycotts, disinvestment and sanctions made South Africa an outcast and added economic pressure to resistance at home.","Township uprisings, sanctions, a costly stalemate and the end of the Cold War brought the government to negotiate from 1990, leading to the first democratic election in April 1994."],dyk:"Protest against the South African rugby team’s tour of New Zealand in 1981 was so fierce that during the final Test, at Eden Park in Auckland, a light aircraft flew low over the ground dropping flour bombs onto the pitch.",ev:[["1948","The National Party wins power and begins to build apartheid into law"],["1952","The ANC and the South African Indian Congress launch the Defiance Campaign against Unjust Laws"],["1955","The Congress of the People adopts the Freedom Charter at Kliptown"],["1960","Police kill 69 protesters at Sharpeville, and the ANC and the PAC are banned"],["1964","Nelson Mandela and seven others are sentenced to life imprisonment in the Rivonia Trial"],["1976","The Soweto uprising begins with a schoolchildren’s march against teaching in Afrikaans"],["1990","F. W. de Klerk unbans the liberation movements, and Mandela is freed after 27 years"],["1994","South Africa holds its first election open to all, and Mandela becomes president"]]},
  "Civil rights movement": {t:["African Americans and their allies fought the segregation and disenfranchisement imposed on the South after Reconstruction with lawsuits, boycotts, sit-ins, freedom rides, marches and voter drives.","Non-violent campaigns from Montgomery to Selma met violent resistance, and the images of that violence helped persuade Congress to pass the Civil Rights Act of 1964 and the Voting Rights Act of 1965.","From 1965 the movement divided over Black Power, northern poverty and the Vietnam War, and the assassination of Martin Luther King Jr. in 1968 is often taken as the end of its classic phase."],dyk:"Rosa Parks was not the first to refuse: in March 1955, nine months before her arrest, the fifteen-year-old Claudette Colvin was arrested for keeping her seat on a Montgomery bus, and she was a plaintiff in the case that desegregated them.",ev:[["1954","The Supreme Court rules segregated public schools unconstitutional in Brown v. Board of Education"],["1955–1956","Rosa Parks’s arrest starts the Montgomery bus boycott, led by Martin Luther King Jr."],["1957","Federal troops escort nine Black students into Central High School in Little Rock, Arkansas"],["1960–1961","Student sit-ins spread across the South, and Freedom Riders challenge segregated bus travel"],["1963","The Birmingham campaign and the March on Washington, where King speaks of his dream"],["1964","The Civil Rights Act outlaws segregation in public places and discrimination in employment"],["1965","The Selma to Montgomery marches lead to the Voting Rights Act"],["1968","Martin Luther King Jr. is assassinated in Memphis, and Congress passes the Fair Housing Act"]]},
  "Enlightenment": {t:["The Enlightenment was a movement of writers, scientists and reformers who held that reason, evidence and free enquiry, not tradition or authority alone, should guide knowledge, belief and government.","Its thinkers, from John Locke and Voltaire to Adam Smith and Immanuel Kant, argued for toleration, natural rights, the rule of law, freer trade and the reform of cruel punishments.","Its ideas guided reforming monarchs and inspired the declarations of rights of 1776 and 1789, though the rights it proclaimed long excluded most women and the enslaved."],dyk:"Émilie du Châtelet finished her French translation of Isaac Newton’s Principia, with a long commentary of her own, in 1749, the year she died; published complete in 1759, it is still the standard French version.",ev:[["1687","Isaac Newton publishes the Principia, setting out the laws of motion and universal gravitation"],["1689","John Locke publishes his Two Treatises of Government and An Essay Concerning Human Understanding"],["1748","Montesquieu publishes The Spirit of the Laws, with its case for separating the powers of government"],["1751","The first volume of the Encyclopédie, edited by Denis Diderot and Jean le Rond d’Alembert, appears in Paris"],["1762","Jean-Jacques Rousseau publishes The Social Contract and Emile; both are banned in France and Geneva"],["1776","Adam Smith publishes The Wealth of Nations; the American Declaration of Independence proclaims equal rights"],["1784","Immanuel Kant answers the question “What is Enlightenment?” with the motto “Sapere aude”, dare to know"],["1789","The French National Assembly adopts the Declaration of the Rights of Man and of the Citizen"]]},
  "Indian independence movement": {t:["Begun by educated Indians seeking reform, the Indian National Congress grew under Mahatma Gandhi into a mass movement whose non-violent campaigns drew millions into the struggle against British rule.","It was never one body: moderates, radicals, revolutionaries, the Muslim League, peasants, workers, opponents of caste and the people of the princely states pursued different, often conflicting aims.","British rule ended on 14–15 August 1947 with the partition of British India into India and Pakistan, which uprooted some fifteen million people and was accompanied by killings on a vast scale."],dyk:"Gandhi took no part in the independence celebrations in Delhi: he spent 15 August 1947 in Calcutta, fasting, praying and spinning in a house in a riot-torn district that he shared with the Muslim League leader Huseyn Shaheed Suhrawardy.",ev:[["1885","The Indian National Congress holds its first session in Bombay"],["1905","Lord Curzon’s partition of Bengal provokes the Swadeshi movement and the boycott of British goods"],["1919","Troops fire on an unarmed crowd at Jallianwala Bagh in Amritsar, killing hundreds"],["1920–1922","Gandhi leads the Non-cooperation movement, in alliance with the Khilafat movement"],["1930","Gandhi’s Salt March to Dandi begins a nationwide campaign of civil disobedience"],["1940","The Muslim League’s Lahore Resolution demands independent states for the Muslim-majority areas"],["1942","The Congress launches the Quit India Movement, and its leaders are imprisoned"],["1947","British rule ends, and British India is partitioned into India and Pakistan"]]},
  "Labour movement": {t:["The labour movement arose with the Industrial Revolution in Britain, as factory hands, miners and craftsmen combined in trade unions to bargain over wages, hours and conditions.","Outlawed or harassed in its early decades, it won legal recognition, shorter hours and social insurance, and founded parties that governed many countries in the 20th century.","Its internationals, May Day and the International Labour Organization carried its demands worldwide, and in 1980 Poland’s Solidarity union challenged communist rule."],dyk:"The six Tolpuddle Martyrs, sentenced in 1834 to transportation to Australia, were convicted not of forming a union, which was by then legal, but of swearing secret oaths under a law passed after the naval mutinies of 1797.",ev:[["1799–1800","Britain’s Combination Acts outlaw workers’ combinations; their repeal in 1824 lets trade unions organise openly"],["1834","Six farm labourers from Tolpuddle in Dorset are sentenced to transportation for swearing a union oath"],["1838","The People’s Charter launches Chartism, a mass campaign for votes for working men"],["1864","The International Workingmen’s Association, the First International, is founded in London"],["1889","London’s dockers win their strike; the Second International calls for May Day demonstrations for the eight-hour day"],["1919","The International Labour Organization is founded under the Treaty of Versailles"],["1926","The Trades Union Congress calls a nine-day General Strike in Britain in support of the coal miners"],["1980","Strikes at Gdańsk’s shipyard lead to Solidarity, the first independent trade union recognised in the Soviet bloc"]]},
  "Pan-Africanism": {t:["Pan-Africanism, born among Black thinkers of the Caribbean, North America and Britain, held that Africans and people of African descent share a common history and destiny.","From the London conference of 1900 to the Manchester congress of 1945 it moved from appeals for fair treatment to demands for the independence of Africa.","Leaders such as Kwame Nkrumah called for a united Africa; the new states founded the Organisation of African Unity in 1963 instead, and the African Union in 2002."],dyk:"The words “the problem of the twentieth century is the problem of the colour-line”, famous from W. E. B. Du Bois’s The Souls of Black Folk (1903), had already appeared in the address he drafted for the London conference of 1900.",ev:[["1900","Henry Sylvester Williams’s Pan-African Conference meets in London; W. E. B. Du Bois drafts its address"],["1914","Marcus Garvey founds the Universal Negro Improvement Association in Jamaica"],["1919","Du Bois’s first Pan-African Congress meets in Paris during the peace conference"],["1935","Italy’s invasion of Ethiopia unites Africans and the diaspora in protest"],["1945","The Fifth Pan-African Congress in Manchester demands independence for Africa"],["1957–1958","Ghana becomes independent under Kwame Nkrumah; Accra hosts the All-African People’s Conference"],["1963","Thirty-two independent states found the Organisation of African Unity in Addis Ababa"],["2002","The African Union replaces the Organisation of African Unity"]]},
  "Protestant Reformation": {t:["Begun by Martin Luther’s protest against the sale of indulgences in 1517, the Reformation broke the unity of Western Christianity and created Lutheran, Reformed, Anglican and Anabaptist churches.","Its teachers held that sinners are saved by God’s grace through faith alone, that scripture is the highest authority in the Church and that all believers share in one priesthood.","Taken up or resisted by princes and cities, it became bound up with politics and war, until the Peace of Westphalia of 1648 ended the wars of religion in the Holy Roman Empire."],dyk:"The name Protestant comes from a protest: at the Diet of Speyer in 1529 six princes and fourteen imperial cities formally protested against the majority’s decision to restore the Edict of Worms against Luther’s teaching.",ev:[["1517","Martin Luther writes his Ninety-five Theses against the sale of indulgences"],["1521","Luther refuses to recant at the Diet of Worms and is outlawed by the Edict of Worms"],["1525","The German Peasants’ War is crushed; the first adult baptisms in Zurich begin the Anabaptist movement"],["1534","The Act of Supremacy makes Henry VIII supreme head of the Church of England"],["1541","John Calvin returns to Geneva, which adopts his Ecclesiastical Ordinances"],["1555","The Peace of Augsburg lets each prince of the empire choose Catholicism or Lutheranism for his lands"],["1598","Henry IV of France grants the Huguenots toleration in the Edict of Nantes"],["1648","The Peace of Westphalia ends the Thirty Years’ War and recognises the Reformed faith in the empire"]]},
  "Renaissance humanism": {t:["Renaissance humanism began in 14th-century Italy with Petrarch and his followers, who sought to revive the language, literature and moral wisdom of ancient Rome and Greece.","Humanists hunted for lost manuscripts, learned Greek from Byzantine teachers and developed the textual criticism with which Lorenzo Valla exposed the Donation of Constantine as a forgery.","Carried across Europe by printing and by scholars such as Erasmus, its course of grammar, rhetoric, poetry, history and moral philosophy shaped European schooling for four centuries."],dyk:"The roman type of most printed books today descends from a handwriting that Poggio Bracciolini and his Florentine circle developed around 1400, copying the Carolingian script of the old manuscripts in which they found the classics.",ev:[["1341","Petrarch is crowned poet laureate on the Capitoline Hill in Rome"],["1397","The Byzantine scholar Manuel Chrysoloras begins teaching Greek in Florence"],["1416–1417","Poggio Bracciolini finds complete texts of Quintilian and Lucretius in monastery libraries"],["1440","Lorenzo Valla shows that the Donation of Constantine is a forgery"],["1462","Cosimo de' Medici gives Marsilio Ficino the Greek manuscripts of Plato to translate into Latin"],["1495","Aldus Manutius begins printing the Greek classics in Venice"],["1516","Erasmus publishes the Greek New Testament at Basel, with a revised Latin translation and notes"],["1599","The Jesuits’ Ratio Studiorum makes the humanist course of study the rule in their colleges"]]},
  "Romanticism": {t:["Romanticism was a movement in literature, art, music and thought that from the 1790s prized feeling, imagination and nature over the rules and reason that had governed the arts of the 18th century.","Its poets, painters and composers, from Wordsworth and Byron to Victor Hugo, Caspar David Friedrich and Chopin, celebrated the individual, wild landscape, the Middle Ages and folk traditions.","It gave Europe’s nations poets, epics and fairy-tale collections and fed both liberal revolt and conservative nostalgia, until Realism displaced it around the middle of the 19th century."],dyk:"The cold, wet summer of 1816, which followed the eruption of Mount Tambora in Indonesia, kept Lord Byron and his guests indoors at the Villa Diodati by Lake Geneva, where his ghost-story contest led Mary Shelley to write Frankenstein.",ev:[["1798","William Wordsworth and Samuel Taylor Coleridge publish Lyrical Ballads; the Schlegel brothers found the Athenaeum"],["1812","The Brothers Grimm publish the first volume of their Children’s and Household Tales"],["1816","A ghost-story contest by Lake Geneva starts Mary Shelley on Frankenstein, published in 1818"],["1822","Adam Mickiewicz’s Ballads and Romances open the Romantic age of Polish literature"],["1824","Lord Byron dies at Missolonghi while aiding the Greek War of Independence"],["1830","Victor Hugo’s Hernani causes uproar in Paris; Hector Berlioz’s Symphonie fantastique is first performed"],["1835","Elias Lönnrot publishes the Kalevala, the epic of Finland, from songs collected in Karelia"],["1848","Revolutions sweep Europe; the poets Alphonse de Lamartine and Sándor Petőfi stand among their leaders"]]},
  "Scientific Revolution": {t:["From Copernicus in 1543 to Newton in 1687, European scholars replaced the Earth-centred cosmos and Aristotle’s physics with a Sun-centred system governed by mathematical laws.","Its people joined mathematics, measurement and experiment, used new instruments such as the telescope, microscope and air pump, and shared their results in books, letters, journals and academies.","Historians debate how revolutionary it was: it built on Greek, Islamic and medieval learning, and the name itself became common only in the 20th century."],dyk:"Newton’s Principia was printed in 1687 at the expense of Edmond Halley, partly because the Royal Society had spent its funds on an expensive illustrated History of Fishes by Francis Willughby and John Ray.",ev:[["1543","Nicolaus Copernicus publishes On the Revolutions; Andreas Vesalius publishes On the Fabric of the Human Body"],["1572","Tycho Brahe observes a new star and shows that it lies beyond the Moon, in heavens thought unchangeable"],["1609","Johannes Kepler’s New Astronomy shows that Mars moves in an ellipse around the Sun"],["1610","Galileo’s Starry Messenger reports mountains on the Moon and four moons of Jupiter"],["1628","William Harvey shows that the blood circulates, pumped by the heart"],["1633","The Roman Inquisition condemns Galileo for defending the motion of the Earth"],["1660","The Royal Society is founded in London"],["1687","Isaac Newton publishes the Principia, with the laws of motion and universal gravitation"]]},
  "Women's suffrage movement": {t:["The organised campaign for women’s votes, usually dated from the Seneca Falls Convention in New York in 1848, won its first national victory in New Zealand in 1893.","Suffragists used petitions, conventions, lobbying and marches; in Britain the militant suffragettes smashed windows, set fires and went on hunger strike in prison.","Much of Europe and North America gave women the vote around the First World War, but many women of colour and colonial subjects waited decades longer."],dyk:"In Finland’s first election with women voters, in 1907, nineteen women won seats in the new parliament, the first women elected to a national legislature anywhere in the world.",ev:[["1848","The Seneca Falls Convention in New York adopts the Declaration of Sentiments, which demands the vote for women"],["1869","Wyoming Territory gives women the vote; the American movement splits into two rival national associations"],["1893","New Zealand becomes the first self-governing country to give all adult women the vote in national elections"],["1903","Emmeline Pankhurst founds the Women’s Social and Political Union in Manchester"],["1906","Finland gives women both the vote and the right to stand for parliament, the first European country to do so"],["1918","Britain gives the vote to women over 30 who meet a property qualification"],["1920","The Nineteenth Amendment to the United States Constitution is ratified"],["1971","Swiss men vote to give women the vote in federal elections"]]},
  "Bhakti movement": {t:["Beginning among Tamil poet-saints in the 6th to 9th centuries, the bhakti movement taught that loving devotion to a personal god is the surest path to liberation, open to all whatever their birth.","Its saints, women and low-caste artisans as well as Brahmins, sang in India’s spoken languages, not Sanskrit, and their songs shaped literatures from Tamil and Kannada to Marathi, Hindi and Bengali.","Never one organisation, it spread region by region over a thousand years, made devotion the centre of popular Hinduism, and some of its saints’ songs are preserved in the Sikh scripture."],dyk:"Tulsidas recorded in the Ramcharitmanas itself that he began the poem at Ayodhya in 1574, on the festival of Rama’s birth; the Ramlila plays still staged across northern India each autumn are based on its verses.",ev:[["c. 6th–9th century","The Tamil Nayanars and Alvars compose hymns to Shiva and Vishnu and sing them at temples across the south"],["10th century","Nathamuni gathers the Alvars’ hymns as the Nalayira Divya Prabandham"],["12th century","Basava, minister at the Kalachuri court of Kalyani, leads the Virashaiva or Lingayat movement in Karnataka"],["1290","Dnyaneshwar completes the Dnyaneshwari, a Marathi verse commentary on the Bhagavad Gita"],["15th century","Kabir, a weaver of Varanasi, sings of a formless God beyond the rites of Hindus and Muslims"],["1510","Chaitanya Mahaprabhu becomes a renunciant and settles at Puri, spreading the chanting of Krishna’s names"],["1574","Tulsidas begins the Ramcharitmanas, the story of Rama retold in the Awadhi form of Hindi"],["c. 1650","Death of Tukaram, whose songs crown the Varkari tradition of Maharashtra"]]},
  "Nahda": {t:["The Nahda, the “awakening”, was a movement of 19th-century Arab writers, translators and teachers, Muslim and Christian, who sought to renew Arabic culture and join it to modern knowledge.","Through printing presses, newspapers, journals, dictionaries, schools and translations, centred in Cairo and Beirut, they created modern Arabic prose and Arabic journalism, drama and the novel.","Its thinkers debated the reform of religion, government and education and the place of women, and their ideas fed both Islamic modernism and Arab nationalism."],dyk:"The first play in Arabic, Marun al-Naqqash’s al-Bakhil (The Miser), adapted from Molière, was performed in Beirut in 1847; by 1850 he had built a theatre near his home for a new play drawn from the Thousand and One Nights.",ev:[["1820","Muhammad Ali founds a government press at Bulaq, near Cairo, which prints its first book in 1822"],["1826","Rifa’a al-Tahtawi goes to Paris as imam of an Egyptian student mission; his account of France appears in 1834"],["1847","Marun al-Naqqash stages al-Bakhil in Beirut, the first play in Arabic"],["1863","Butrus al-Bustani founds the National School in Beirut, open to pupils of every religion"],["1876","The newspaper al-Ahram begins publication in Alexandria and the journal al-Muqtataf in Beirut"],["1892","Jurji Zaydan founds al-Hilal in Cairo; Hind Nawfal launches al-Fatat, the first Arabic magazine for women"],["1899","Muhammad Abduh becomes Grand Mufti of Egypt; Qasim Amin publishes The Liberation of Women"],["1908","The Ottoman constitution is restored, loosening censorship, and the Egyptian University opens in Cairo"]]},
  "Self-Strengthening Movement": {t:["After defeat in the Second Opium War and amid the Taiping Rebellion, Qing officials set out to “strengthen themselves” by adopting Western arms, ships and industry while keeping the Confucian order.","Led above all by provincial governors such as Zeng Guofan, Li Hongzhang and Zuo Zongtang, it built arsenals, shipyards, mines, telegraphs, schools and a modern navy, and sent students abroad.","Without reform of government, finance or education its gains stayed scattered, and defeat by Japan in 1894–1895 exposed the limits of borrowing technology alone."],dyk:"China’s first railway in regular service, from Shanghai to Wusong, was built by a British firm without the government’s consent and opened in 1876; the Qing authorities bought it in 1877 and had it torn up.",ev:[["1861","The Zongli Yamen is created under Prince Gong to conduct relations with the Western powers"],["1862","The Tongwen Guan opens in Beijing to train interpreters, later adding mathematics and astronomy"],["1865","Zeng Guofan and Li Hongzhang found the Jiangnan Arsenal at Shanghai"],["1866","Zuo Zongtang founds the Fuzhou Navy Yard and its naval school"],["1872","The China Merchants’ Steam Navigation Company is founded; the first Educational Mission students sail for America"],["1884","A French squadron destroys the Fujian fleet at Fuzhou in the Sino-French War"],["1888","The Beiyang Fleet is formally established under Admiral Ding Ruchang"],["1895","Defeated by Japan, the Qing sign the Treaty of Shimonoseki"]]},
  "Absolute monarchy": {t:["Absolute monarchy placed the making of law, its execution and the final judgement of cases in one hereditary ruler, justified in early modern Europe by the divine right of kings.","Rulers such as Louis XIV, Peter the Great and Frederick the Great built standing armies, bureaucracies and court cultures that laid foundations of the modern state.","Revolutions between 1688 and 1917 ended absolutism across most of Europe; historians still debate how absolute these monarchs really were, and a few states keep the form today."],dyk:"Denmark–Norway’s King’s Law of 1665, the first written constitution in Europe to establish absolute monarchy, declared the king “the most perfect and supreme person on the Earth”, standing “above all human laws”.",ev:[["1576","Jean Bodin’s Six Books of the Commonwealth defines sovereignty as absolute and perpetual power"],["1661","Louis XIV begins his personal rule of France on the death of Cardinal Jules Mazarin"],["1665","Frederick III of Denmark signs the King’s Law, Europe’s first written constitution of absolute monarchy"],["1688","The Glorious Revolution deposes James II and ends moves towards absolute monarchy in England"],["1781","Joseph II grants religious toleration and abolishes personal serfdom in the Bohemian lands"],["1789","The French Revolution begins, and the National Assembly ends absolute monarchy in France"],["1848","Revolutions sweep Europe; Denmark gives up absolutism and Prussia receives a constitution"],["1905","Nicholas II’s October Manifesto promises Russia an elected Duma, ending unlimited autocracy"]]},
  "Aristocracy": {t:["Aristocracy, Greek for “rule of the best”, was praised by Plato and Aristotle as government by the most virtuous, but in practice it almost always meant rule by a hereditary, landowning nobility.","Noble elites governed most of Europe and much of Asia for over two thousand years, through bodies as varied as the Roman Senate, Venice’s Great Council, the Polish Sejm and Britain’s House of Lords.","Revolutions, new commercial and industrial wealth, mass democracy and the First World War stripped aristocracies of their power; only remnants, such as the noble seats in Tonga’s parliament, survive."],dyk:"From 1652 a single deputy in the Sejm of the Polish–Lithuanian Commonwealth could end a session and void all it had passed by declaring “I do not allow”; this noble privilege, the liberum veto, was abolished only in 1791.",ev:[["c. 750 BCE","The Bacchiad clan replaces the kings of Corinth with a magistrate chosen yearly from among its own members"],["509 BCE","By Roman tradition the last king is expelled, and patrician families rule through the Senate and two annual consuls"],["c. 330 BCE","Aristotle’s Politics defines aristocracy as rule by the best for the common good and oligarchy as its corruption"],["1016","Fujiwara no Michinaga becomes regent for his grandson Emperor Go-Ichijō, the height of Fujiwara power in Japan"],["1573","The Polish–Lithuanian nobility holds its first free royal election and binds the new king by the Henrician Articles"],["1789","On 4 August France’s National Assembly abolishes noble privileges; hereditary nobility itself is abolished in 1790"],["1911","The Parliament Act ends the House of Lords’ power to veto bills passed by the House of Commons"],["1918","Revolution topples the German and Austrian monarchies, sweeping away noble chambers such as the Prussian House of Lords"]]},
  "Chiefdom": {t:["A chiefdom joins several villages under a hereditary paramount chief who rules through kinship, ritual and tribute, without the officials, standing army or written law of a state.","Chiefdoms arose independently in Mesopotamia, Europe, the Americas, Africa and Polynesia, and some, like Cahokia and the Hawaiian chiefdoms, raised great monuments and fed large followings.","Anthropologists named the type in the 1950s and still argue over it, while chiefs remain a recognised tier of local government from Sierra Leone and Botswana to Samoa."],dyk:"The word cacique, which Spanish conquerors applied to native rulers throughout the Americas, was borrowed from the Taíno, whose chiefdoms Columbus met in the Caribbean in 1492.",ev:[["c. 5000 BCE","Temple towns of the Ubaid period rise in southern Mesopotamia; many archaeologists see them as early chiefdoms"],["c. 4500 BCE","A few richly furnished graves on Bulgaria’s Black Sea coast reveal one of Europe’s first hereditary elites"],["c. 1050","Cahokia, near present-day St Louis, grows rapidly into the largest chiefly centre north of Mexico"],["1492","Columbus reaches the Taíno chiefdoms of the Caribbean; Spanish conquest destroys them within a generation"],["1540","Hernando de Soto’s expedition passes through Cofitachequi and Coosa, paramount chiefdoms of the South-East"],["1607","English colonists at Jamestown meet Wahunsenacawh, paramount chief of some thirty peoples of Tidewater Virginia"],["1795","Kamehameha I conquers Oʻahu at the Battle of Nuʻuanu; by 1810 he rules all the Hawaiian Islands"],["1955","Kalervo Oberg names the chiefdom as a type; Elman Service sets it between tribe and state in 1962"]]},
  "City-state": {t:["A city-state is a city that governs itself and the countryside around it as a state of its own, with its own gods, laws and army and often citizens who share in government.","City-states arose in Sumer, Greece and Phoenicia, among the Maya, on the Swahili coast and in medieval Italy and Germany, usually in clusters of rivals sharing one culture.","Small size fostered participation, trade and invention but left city-states open to faction and conquest; Singapore, Monaco and Vatican City are their sovereign heirs today."],dyk:"Aristotle’s school collected the constitutions of 158 states, but only the Constitution of the Athenians survives, recovered from papyri found in Egypt and first published in 1891.",ev:[["c. 3500 BCE","Uruk in southern Mesopotamia grows into the first city and the centre of the earliest known city-state"],["c. 2450 BCE","Eannatum of Lagash records his victory over neighbouring Umma on the Stele of the Vultures"],["338 BCE","Philip II of Macedon defeats Athens and Thebes at Chaeronea and takes control of mainland Greece"],["562","Tikal is defeated by Caracol, an ally of Calakmul, in the wars of the Classic Maya city-states"],["1176","The Lombard League of Italian communes defeats Emperor Frederick Barbarossa at the Battle of Legnano"],["1370","The Treaty of Stralsund ends the Hanseatic towns’ war with Denmark at the height of the league’s power"],["1505","A Portuguese fleet sacks Kilwa and Mombasa, leading city-states of the Swahili coast"],["1965","Singapore leaves the Federation of Malaysia and becomes an independent city-state"]]},
  "Colonial rule": {t:["Colonial rule placed a territory and its people under a distant metropole that ruled them as subjects, through its own officials (direct rule) or through local rulers it controlled (indirect rule).","From Portugal’s capture of Ceuta in 1415 to the eve of the First World War, European empires spread across the Americas, Africa, Asia and the Pacific through conquest, settlement, slavery and trade.","Colonised peoples resisted throughout, from the Haitian Revolution to the liberation wars of the 20th century, and most colonies won independence between 1945 and 1975."],dyk:"Britain and France between them traced close to 40 per cent of the total length of the world’s international boundaries.",ev:[["1415","Portugal captures Ceuta in North Africa, the first overseas conquest of Europe’s colonial age"],["1521","Spanish conquistadors and their Indigenous allies take Tenochtitlan, capital of the Aztec Empire"],["1757","The East India Company’s victory at Plassey opens the way to its rule over Bengal"],["1804","Haiti declares independence after the revolution of the enslaved against French colonial rule"],["1884","The Berlin Conference opens and sets rules for the European partition of Africa"],["1947","British India becomes independent as India and Pakistan, amid the violence of partition"],["1960","The UN General Assembly declares the right of colonial peoples to independence"],["1975","Angola and Mozambique win independence after Portugal’s Carnation Revolution"]]},
  "Constitutional monarchy": {t:["Constitutional monarchy keeps a hereditary head of state but binds the crown by law; in its parliamentary form the monarch reigns while elected ministers govern.","It took shape in England with the Bill of Rights 1689 and spread through 19th-century Europe, then to Japan, Siam and the self-governing dominions of the British Empire.","After two world wars swept away many thrones, the surviving monarchies of Europe almost all adopted the British model of a ceremonial crown and parliamentary government."],dyk:"No British monarch has refused royal assent to a bill since 11 March 1708, when Queen Anne withheld it from the Scottish Militia Bill; the power has never been abolished but is widely thought to have lapsed.",ev:[["1689","The Bill of Rights forbids the English crown to suspend laws, levy taxes or keep a peacetime army without Parliament"],["1701","The Act of Settlement fixes a Protestant succession by statute, later bringing the House of Hanover to the throne"],["1708","Queen Anne withholds assent from the Scottish Militia Bill, the last royal veto in Britain"],["1791","Poland–Lithuania adopts the Constitution of 3 May, often called Europe’s first modern written constitution"],["1831","Belgium’s constitution declares that all powers emanate from the nation; Leopold I swears to uphold it"],["1889","Japan’s Meiji Constitution creates an Imperial Diet with an elected lower house under a sovereign emperor"],["1947","Japan’s new constitution makes the emperor “the symbol of the State and of the unity of the people”"],["1978","Spain’s constitution restores parliamentary monarchy under Juan Carlos I after Franco’s dictatorship"]]},
  "Dictatorship": {t:["In the Roman Republic a dictator was a lawful magistrate given supreme power for a single emergency and expected to lay it down as soon as the task was done.","Modern dictatorship, from Napoleon and the caudillos to Mussolini, Hitler and Stalin, means power held without legal limits or free elections and kept by repression and propaganda.","Political scientists divide dictatorships into personalist, military and one-party regimes, which differ in how they rule, how long they last and how they end."],dyk:"The title once carried honour: Giuseppe Garibaldi officially styled himself “Dictator” of Sicily during the Expedition of the Thousand in 1860, and leaders of Poland’s November Uprising of 1830 and January Uprising of 1863 held the same title.",ev:[["c. 501 BCE","By Roman tradition Titus Larcius is named the first dictator of the Republic"],["44 BCE","Julius Caesar is made dictator for life and assassinated; the office is then abolished"],["1799","Napoleon Bonaparte seizes power in the coup of 18 Brumaire, the model of Bonapartism"],["1917","The Bolsheviks take power in Russia, proclaiming a dictatorship of the proletariat"],["1922","Benito Mussolini comes to power in Italy and from 1925 builds the first fascist dictatorship"],["1933","Adolf Hitler becomes chancellor; the Enabling Act lets his cabinet make laws without the Reichstag"],["1973","General Augusto Pinochet’s coup overthrows Chile’s elected government"],["1989","Revolutions end the communist dictatorships of Central and Eastern Europe"]]},
  "Direct democracy": {t:["In a direct democracy the citizens vote on laws and policies themselves, in an open assembly or a referendum, rather than leaving them to elected representatives.","Athens from 508 to 322 BCE is the classic case: an assembly of male citizens, a council and juries chosen by lot governed, while women, slaves and resident foreigners had no vote.","Switzerland keeps the tradition alive in two cantonal open-air assemblies and in frequent national referendums and initiatives, devices also used by many US states."],dyk:"At the open-air Landsgemeinde of Appenzell Innerrhoden men traditionally carry a sword as proof of their right to vote; women were admitted only after the Federal Supreme Court ruled in 1990 that the canton must let them vote.",ev:[["508 BCE","Cleisthenes reorganises the Athenians into ten tribes and creates the Council of Five Hundred"],["462 BCE","Ephialtes strips the Council of the Areopagus of most of its powers; pay for jurors follows under Pericles"],["403 BCE","The Athenians restore their democracy after the rule of the Thirty Tyrants"],["322 BCE","After the Lamian War, Macedon imposes a property qualification and ends the Athenian democracy"],["1848","Switzerland’s federal constitution makes every constitutional amendment subject to a popular vote"],["1891","Swiss citizens gain the popular initiative to propose amendments to the federal constitution"],["1898","South Dakota becomes the first US state to adopt the initiative and the referendum"],["1990","The Federal Supreme Court orders Appenzell Innerrhoden to admit women to its Landsgemeinde"]]},
  "Elective monarchy": {t:["In an elective monarchy the crown passes by election rather than inheritance; the electors were usually few and powerful, and candidates often came from a single royal house.","The prince-electors of the Holy Roman Empire, whose rights the Golden Bull of 1356 fixed in law, and the free elections of Poland–Lithuania are its best-known European forms.","Elections let electors bind each new ruler with conditions, but invited bribery, foreign meddling and disputed choices, and most elective crowns became hereditary or disappeared."],dyk:"The word conclave, from the Latin for “with a key”, recalls how cardinals were locked in until they chose a pope, a rule imposed in 1274 after an election at Viterbo had dragged on for almost three years.",ev:[["633","The Fourth Council of Toledo rules that Visigothic kings be chosen by the nobles and the bishops"],["911","East Frankish magnates elect Conrad of Franconia king after the last Carolingian ruler, Louis the Child, dies"],["1356","Emperor Charles IV’s Golden Bull fixes the seven prince-electors and election by majority"],["1438","Albert II’s election begins three centuries in which the electors choose only Habsburgs, until 1740"],["1573","The first free election of the Polish–Lithuanian Commonwealth makes Henry of Valois king"],["1619","The Bohemian estates depose the Habsburg Ferdinand and elect Frederick V of the Palatinate"],["1806","The Holy Roman Empire is dissolved, and its college of electors ends with it"],["1957","Malaya’s Conference of Rulers elects the first Yang di-Pertuan Agong for a five-year term"]]},
  "Federation": {t:["In a federation a constitution divides power between a central government and member states, each governing its citizens directly in its own fields; neither can abolish the other.","It differs from a confederation, a league of sovereign states whose common council acts through them, and from a unitary state, whose regions hold only the powers the centre grants.","Pioneered by the United States in 1789 and adopted by Switzerland, Canada, Germany, Australia and India, federations are now home to about 40 per cent of the world’s people."],dyk:"Switzerland is still officially the Swiss Confederation, Confoederatio Helvetica in Latin, the source of its abbreviation CH, although it has been a federal state rather than a confederation since its constitution of 1848.",ev:[["1789","The Constitution of the United States takes effect, turning a confederation into the first modern federation"],["1848","After the Sonderbund War, Switzerland’s new constitution turns its confederacy into a federal state"],["1861","Seceding southern states form the Confederate States of America, and the American Civil War begins"],["1867","The British North America Act unites three colonies in the federal Dominion of Canada"],["1871","The German Empire is founded as a federation of 25 states under the king of Prussia"],["1901","After referendums in each colony, six Australian colonies federate as the Commonwealth of Australia"],["1950","India’s constitution comes into force, making the country a “Union of States”"],["1991","The Soviet Union, a federation of fifteen union republics, is dissolved"]]},
  "Feudalism": {t:["Feudalism bound lords and vassals by oaths of homage and fealty: the lord granted a fief, usually land, and the vassal owed military service, counsel and loyalty in return.","It grew as Carolingian royal power broke up in the 9th and 10th centuries, gave castle lords local power over peasants, and was abolished in France on the night of 4 August 1789.","Since Elizabeth A. R. Brown’s critique of 1974 and Susan Reynolds’s Fiefs and Vassals of 1994, historians have debated whether the term fits medieval Europe, let alone Japan."],dyk:"Sark in the Channel Islands, settled in 1565 by Helier de Carteret under a charter from Elizabeth I and divided into forty tenements whose holders sat in its parliament, kept what was called Europe’s last feudal system until 2008.",ev:[["c. 800","Under Charlemagne, grants of land to vassals in return for service become the usual reward of royal followers"],["c. 1000","Castles multiply in France as castellans seize rights of justice and taxation over the peasants around them"],["1086","William the Conqueror has the landholders of England swear fealty to him at Salisbury"],["1192","Minamoto no Yoritomo becomes shogun of Japan, ruling through vassals often compared with Europe’s"],["1215","King John accepts Magna Carta, which limits the feudal dues a king may demand of his barons"],["1337","Philip VI of France confiscates Gascony from his vassal Edward III of England; the Hundred Years’ War begins"],["1789","On the night of 4 August the French National Assembly votes to abolish the feudal regime"]]},
  "Military junta": {t:["A military junta is rule by a committee of officers, usually installed by a coup; it differs from a military strongman, who rules alone, and from civilian governments that merely depend on the army.","Korea’s Goryeo generals ruled collectively from 1170, but juntas became common only after 1945, governing much of Latin America, Africa and Asia and, for shorter spells, Greece, Turkey and Portugal.","Juntas usually promised to restore order and then hold elections; many did hand power back, but many also imprisoned, tortured and killed opponents, and one coup often led to another."],dyk:"Junta, Spanish for “meeting” or “council”, won its political fame through the committees Spaniards formed in 1808 to resist Napoleon’s invasion; these were not military councils, and the word only later came to mean rule by officers.",ev:[["1170","Goryeo’s generals seize power in Korea and rule through their council while kings reign as figureheads"],["1653","Soldiers expel England’s Rump Parliament; army officers draft a constitution making Oliver Cromwell Lord Protector"],["1808","Spaniards form local and national juntas to resist Napoleon’s invasion, the councils from which the modern term derives"],["1967","Colonels seize power in Greece and rule until their coup in Cyprus brings their fall in 1974"],["1973","The commanders of Chile’s army, navy, air force and police seize power and rule as a junta until 1990"],["1974","Ethiopia’s military council, the Derg, deposes Emperor Haile Selassie and rules until 1987"],["1976","Argentina’s armed forces seize power; defeat in the Falklands War of 1982 forces them to hold elections in 1983"],["2021","Myanmar’s armed forces seize power in a coup on 1 February, their third takeover since 1958"]]},
  "Nomadic confederation": {t:["A nomadic confederation joined herding tribes under one ruling clan and khan, and organised the whole people as an army in units of ten, a hundred, a thousand and ten thousand.","Steppe rulers lived largely on what they drew from settled empires by raids, tribute treaties and trade, as the Xiongnu did from Han China and Attila’s Huns from Constantinople.","Disputed successions repeatedly split these empires, and by 1757 the guns, forts and frontier treaties of Qing China and Russia had left the steppe no room for another."],dyk:"According to the Book of Han, Han envoys could enter the Xiongnu ruler’s tents only after setting aside their tallies of office and having their faces tattooed; the envoy Wang Wu agreed and was received with honour.",ev:[["209 BCE","Modu Chanyu takes power and unites the Xiongnu, founding the first great empire of the eastern steppe"],["198 BCE","After Emperor Gaozu’s defeat at Baideng, the Han buy peace with a princess and regular gifts of silk and grain"],["51 BCE","Amid a Xiongnu civil war, Huhanye pays homage in person at Chang’an and accepts Han overlordship"],["552","Bumin Qaghan overthrows the Rouran and founds the First Turkic Khaganate"],["1206","A kurultai at the source of the Onon river proclaims Temüjin Genghis Khan of the Mongols"],["1260","Rival kurultais elect Kublai Khan and Ariq Böke as Great Khan, and the Mongol Empire begins to break apart"],["1757","Qing armies crush the last Dzungar resistance, ending the last great nomadic empire of the steppe"]]},
  "Oligarchy": {t:["Oligarchy, Greek for “rule by few”, named the many Greek constitutions that kept power with the propertied; Aristotle called it a corrupt form of government, rule by the rich for the rich.","The Republic of Venice, whose Great Council was closed to new families from 1297, was the longest-lived oligarchy, governed by a hereditary patriciate until its fall in 1797.","Today the word is used loosely for the political power of great wealth, and Robert Michels’s “iron law of oligarchy” of 1911 held that all large organisations, even democratic ones, fall to a few."],dyk:"From 1268 Venice elected its doge in ten rounds that alternated drawing lots with voting, from thirty members of the Great Council drawn by lot to forty-one electors, to defeat bribery and family factions.",ev:[["683/682 BCE","Athens begins its yearly list of archons, an office then reserved for the well-born families, the Eupatridae"],["c. 430 BCE","In Herodotus’s Histories the Persian Megabyzus makes the first recorded case for rule by a few of the best men"],["411 BCE","The oligarchic Four Hundred overthrow the Athenian democracy, which is restored within a year"],["404 BCE","Sparta installs the Thirty at Athens; in eight months they kill about 1,500 citizens before democracy returns"],["c. 330 BCE","Aristotle’s Politics defines oligarchy as government by the wealthy in their own interest"],["1297","The Serrata begins to close Venice’s Great Council to new families, creating a hereditary ruling patriciate"],["1355","Venice’s Council of Ten has Doge Marino Faliero beheaded for plotting to make himself lord of the city"],["1797","Facing Napoleon’s ultimatum, Venice’s Great Council votes the Republic out of existence on 12 May"]]},
  "One-party state": {t:["In a one-party state a single party controls government by law or in practice; other parties are banned or allowed only as junior allies, and elections offer no real choice of rulers.","The form began in Soviet Russia between 1918 and 1921, spread to Fascist Italy and Nazi Germany, and after 1945 to the communist states and many newly independent countries in Africa and Asia.","Most one-party states became multi-party systems after 1989–1991, but communist parties still rule China, Vietnam, Laos, Cuba and North Korea, and dominant-party systems remain common."],dyk:"Article 6 of the Soviet constitution of 1977 named the Communist Party “the leading and guiding force of Soviet society”; its amendment in March 1990 ended the party’s legal monopoly less than two years before the Soviet Union dissolved.",ev:[["1918","The Bolsheviks dissolve the Constituent Assembly and expel rival socialist parties from the soviets"],["1921","The Tenth Congress of the Russian Communist Party bans factions as the last rival parties are suppressed"],["1926","Mussolini’s government dissolves every party except the National Fascist Party"],["1933","Germany’s Law against the Formation of New Parties makes the Nazi Party the only legal party"],["1949","The Chinese Communist Party wins the civil war and proclaims the People’s Republic of China on 1 October"],["1965","Tanzania becomes a one-party state by law, with rival candidates of the ruling party in most constituencies"],["1990","The Soviet Union amends Article 6 of its constitution, ending the Communist Party’s monopoly of power"],["2000","Mexico’s Institutional Revolutionary Party loses the presidency after 71 years in power"]]},
  "Parliamentary democracy": {t:["In a parliamentary democracy voters elect a parliament, and the government is formed from it and stays in office only as long as it keeps the confidence of a parliamentary majority.","The system grew up in Britain, where between the 1720s and the 1830s real executive power passed from the monarch to a prime minister and cabinet answerable to the House of Commons.","Spread through the British Empire and across Europe after 1918 and 1945, it is praised for flexibility and clear responsibility and blamed for unstable coalitions and weak checks on a majority."],dyk:"Germany’s Basic Law lets the Bundestag remove a chancellor only by electing a successor in the same vote, a rule meant to avoid the crises of the Weimar Republic; it has succeeded once, when Helmut Kohl replaced Helmut Schmidt in 1982.",ev:[["1721","Robert Walpole heads the British government until 1742; he is usually counted the first prime minister"],["1782","Lord North resigns in the face of the first motion of no confidence in a whole British government"],["1832","The Reform Act widens the franchise and strengthens the Commons’ hold on the choice of government"],["1848","Nova Scotia and the Province of Canada win responsible government, the first British colonies to do so"],["1911","The Parliament Act ends the House of Lords’ absolute veto over bills passed by the House of Commons"],["1933","The Reichstag passes the Enabling Act, ending parliamentary government in the Weimar Republic"],["1949","West Germany’s Basic Law introduces the constructive vote of no confidence"],["1950","India’s constitution makes it a parliamentary republic on the Westminster model"]]},
  "Presidential democracy": {t:["In a presidential democracy the people elect a president who heads the government for a fixed term and, unlike a prime minister, cannot be dismissed by the legislature for losing its support.","Devised by the framers of the Constitution of the United States in 1787, it rests on the separation of executive, legislative and judicial powers, each able to check the others.","It spread across Latin America in the 19th century; Juan Linz argued that its rigid terms and winner-takes-all elections endanger democracy, a view his critics dispute."],dyk:"Under the original Constitution the runner-up in the electoral college became vice-president, so in 1796 John Adams found his chief rival, Thomas Jefferson, serving as his deputy; the Twelfth Amendment of 1804 ended the arrangement.",ev:[["1789","The Constitution of the United States takes effect and George Washington is inaugurated as the first president"],["1803","In Marbury v. Madison the Supreme Court asserts its power to strike down acts of Congress"],["1824","Mexico’s first federal constitution creates a presidency on the American model"],["1889","Brazil’s monarchy falls and Deodoro da Fonseca becomes the first president of a presidential republic"],["1951","The Twenty-second Amendment limits American presidents to two terms"],["1973","Chile’s armed forces overthrow President Salvador Allende, ending four decades of constitutional rule"],["1974","Richard Nixon resigns as Congress moves to impeach him over the Watergate scandal"],["1987","After mass protests, South Korea adopts a constitution with direct presidential elections"]]},
  "Republic": {t:["A republic is a state without a monarch, governed as the “public thing”, res publica, by officials elected for limited terms who answer to the law and to the citizens.","From Rome to Venice, Florence and the Dutch Republic, most early republics were run by a narrow elite of patricians, nobles or merchants rather than by all their citizens.","Since the American and French revolutions the republic has become the usual form of the state: in 2017, 159 of the world’s 206 sovereign states had “republic” in their official names."],dyk:"San Marino, by tradition founded in 301, calls itself the world’s oldest surviving republic; its heads of state, two Captains Regent who rule jointly, still serve for only six months at a time.",ev:[["509 BCE","By Roman tradition the last king, Tarquinius Superbus, is expelled and the first two consuls are elected"],["287 BCE","The lex Hortensia gives the decisions of the plebeian assembly the force of law for all Romans"],["27 BCE","Octavian takes the name Augustus; the republic’s forms survive under the rule of one man"],["1297","The Serrata restricts Venice’s Great Council to the families already sitting in it"],["1588","The States General take sovereignty for themselves, founding the Dutch Republic"],["1776","The Declaration of Independence rejects the British monarchy; the American states adopt republican constitutions"],["1792","The National Convention abolishes the French monarchy and proclaims the First Republic"],["1918","The German and Austrian monarchies fall and both countries are proclaimed republics"]]},
  "Theocracy": {t:["The word theocracy, “rule of God”, was coined by the Jewish historian Josephus in the 1st century CE for a people whose law came from God and was administered by priests.","Popes ruled the Papal States from 756 to 1870, Dalai Lamas governed Tibet from 1642 to 1959, and since 1979 Iran’s constitution has placed a senior Islamic jurist at the head of the state.","Scholars debate which states count as theocracies: many distinguish rule by clergy from divine kingship, from caliphates bound by religious law, and from states that only have an official religion."],dyk:"In 1750 Marthanda Varma, king of Travancore in southern India, gave his kingdom to the god Padmanabha, a form of Vishnu; he and his successors then ruled as the deity’s servants, with the title Padmanabhadasa.",ev:[["c. 515 BCE","The rebuilt Temple in Jerusalem is dedicated; a priest-led Judean community forms around it under Persian rule"],["c. 95 CE","In Against Apion the Jewish historian Josephus coins “theocracy” for a constitution that gave all sovereignty to God"],["756","Pepin the Short grants the pope former Byzantine lands in Italy, founding the Papal States"],["1642","Güshi Khan confers authority over Tibet on the Fifth Dalai Lama, founding the Ganden Phodrang government"],["1870","Italian troops take Rome on 20 September, ending the Papal States"],["1929","The Lateran Treaty creates Vatican City, where the pope holds all legislative, executive and judicial power"],["1959","After the Tibetan uprising the 14th Dalai Lama flees to India, and the Lhasa government is dissolved"],["1979","A revolution and a new constitution make Iran an Islamic Republic headed by a senior Shia jurist"]]},
  "Tyranny": {t:["Greek tyrants were men who seized sole power in a city-state outside its traditional order, often by championing the common people against a narrow aristocracy.","Some, such as Cypselus of Corinth and Peisistratus of Athens, presided over prosperity, public building and new festivals, but few tyrannies outlasted the founder’s sons.","Plato and Aristotle made the tyrant the type of the worst ruler, governing for himself and without law, and their judgement fixed the meaning the word has had ever since."],dyk:"Herodotus tells that Peisistratus regained Athens after his first exile by entering the city in a chariot beside a tall woman named Phye, dressed in armour as Athena, while heralds proclaimed that the goddess was bringing him home.",ev:[["c. 657 BCE","Cypselus overthrows the Bacchiad aristocracy and makes himself tyrant of Corinth (traditional date)"],["546 BCE","Peisistratus defeats the Athenians at Pallene and begins his third and longest tyranny"],["514 BCE","Harmodius and Aristogeiton kill Hipparchus; Sparta drives out his brother Hippias in 510 BCE"],["480 BCE","Gelon of Syracuse and Theron of Acragas defeat a Carthaginian army at Himera"],["405 BCE","Dionysius I seizes power in Syracuse during a war with Carthage and rules until 367 BCE"],["404 BCE","Sparta installs the Thirty Tyrants, an oligarchy that rules Athens by terror until 403 BCE"],["192 BCE","Nabis, the last independent ruler of Sparta, is assassinated and Sparta is forced into the Achaean League"],["146 BCE","Rome destroys Corinth and brings the cities of southern Greece under Roman control"]]},
  "Ainu": {t:["The Ainu, whose name means “human being”, are the Indigenous people of Hokkaido, Sakhalin and the Kurils; their culture grew from the Satsumon culture with contributions from the Okhotsk culture.","Living in small river villages called kotan, they fished for salmon, hunted deer and bears and traded between Honshu and the Asian mainland, in a world where everything held a kamuy.","Japanese colonisation brought land seizure, forced labour, family separation, epidemics and bans on language and religion; a court first recognised the Ainu as an Indigenous people in 1997, and the Diet passed an act recognising them in 2019."],dyk:"When Russians and Japanese met at trading posts in northern Hokkaido in 1778–1779, the talks were held in the Ainu language, with Ainu guides translating for both sides.",ev:[["13th century","The Ainu culture period begins, following the Satsumon culture"],["1264–1308","The Ainu of northern Sakhalin resist the Mongol Yuan dynasty until they are subdued and pay tribute"],["1591","A Jesuit Latin manuscript first records the name, as Aino, and calls Hokkaido “Aino moxori”"],["1799–1806","The Tokugawa shogunate takes direct control of southern Hokkaido; forced labour, family separation and smallpox cut the Ainu population sharply"],["1869","The Meiji government sets up the Hokkaidō Development Commission to settle Hokkaido"],["1899","The Hokkaido Former Aborigines Protection Act takes Ainu land and aims to erase Ainu culture and identity"],["1997","The Sapporo District Court’s Nibutani Dam ruling recognises the Ainu as an Indigenous people, and the Ainu Culture Law replaces the 1899 act"],["2019","The National Diet passes an act recognising the Ainu as an Indigenous people of Japan"]]},
  "Ban Chiang culture": {t:["Ban Chiang is a village site in northeast Thailand, found in 1966, whose graves run from a Neolithic farming community to the Iron Age.","Its villagers cast their own bronze in small village settings, without a city or a militaristic state, and their skeletons show active lives with little sign of violence.","Its age is still disputed: early dates would have made it the world’s earliest Bronze Age culture, but later radiocarbon and Bayesian dating placed its bronze working much later."],dyk:"The site was found in 1966 when a Harvard student, Steve Young, tripped over the root of a kapok tree and fell onto the exposed tops of buried pottery jars.",ev:[["c. 2100 BCE","Rice phytoliths in a vessel from the lowest grave give the site’s oldest radiocarbon date; other dating puts first settlement c. 1500 BCE"],["c. 2000–1700 BCE","Bronze working begins by one dating, with crucibles and bronze fragments; Bayesian dating puts the Bronze Age transition c. 1000 BCE"],["c. 300 BCE – 200 CE","The red-on-buff painted pottery is made; the youngest grave dates to about 200 CE"],["1966","Steve Young finds pottery in a village path, and samples are later sent to the University of Pennsylvania for dating"],["1974–1975","The University of Pennsylvania Museum and the Thai Fine Arts Department excavate under Chester Gorman and Pisit Charoenwongsa"],["1992","Ban Chiang becomes a UNESCO World Heritage Site"],["2008","US federal raids ending Operation Antiquity uncover thousands of looted Ban Chiang artefacts in California museums"]]},
  "Bell Beaker culture": {t:["Bell Beaker is an archaeologists’ label for a set of objects and customs, named after a drinking vessel shaped like an upside-down bell, that appears across western Europe from about 2800 BCE.","Beaker groups spread copper, gold and later tin-bronze working along sea and river routes, from Ireland’s Ross Island mines to Portugal, Sicily and Hungary.","Its early spread from Iberia seems to have involved little migration, but its later spread carried steppe-related ancestry that replaced about 90% of Britain’s gene pool."],dyk:"Isotope analysis of the Amesbury Archer, the richest burial in Britain of his time (c. 2300 BCE), shows that he spent his childhood in Central Europe, probably in the region of the Alps.",ev:[["c. 2800 BCE","The earliest maritime-style bell beakers appear at the Tagus estuary in Portugal"],["c. 2600 BCE","Maritime Bell Beakers reach the Lower Rhine"],["c. 2500 BCE","Beakers arrive in Britain and Ireland, and Bell Beaker groups reach Csepel Island in Hungary"],["c. 2400–2200 BCE","Copper is mined and smelted at Ross Island in Ireland"],["c. 2300 BCE","The Pömmelte enclosure is built in central Germany, and the Únětice culture succeeds the Bell Beaker in central Europe"],["c. 2200–2100 BCE","Britain switches all its metalwork to tin-bronze"],["c. 1700 BCE","Beakers fall out of use in Britain and Ireland"],["1904","John Abercromby introduces the English name Bell Beaker"]]},
  "Caral–Supe civilisation": {t:["Caral–Supe was a cluster of as many as thirty population centres in three small valleys of Peru’s north-central coast, flourishing between about 3000 and 1800 BCE.","Its people raised great stepped platform mounds and sunken circular plazas, grew cotton and food crops by irrigation and ate fish from the coast, yet made no pottery and almost no art.","There is no evidence of warfare, and archaeologists still debate how it was governed and whether the sea or farming fed its rise."],dyk:"Caral–Supe builders hauled stones to their pyramids in loosely meshed bags of a highland grass, shicra, packing the filled bags behind each retaining wall; radiocarbon dates of these bags date Caral to about 2627 BCE.",ev:[["c. 3500 BCE","Huaricanga, in the Fortaleza valley, becomes the earliest securely dated city of Caral–Supe"],["c. 2600 BCE","Caral in the Supe valley is inhabited and grows into the largest centre of the civilisation"],["c. 2250 BCE","A gourd from a burial in the Pativilca valley is decorated with the oldest known image of the Andean Staff God"],["c. 2200 BCE","Caral–Supe influence reaches from the Chillón valley to the Santa valley; a long drought begins that later drives people from Caral"],["c. 1800 BCE","The civilisation declines as more powerful centres rise along the coast and in the Andes"],["1905","Max Uhle notes the site of Caral, though he does not recognise its hills as pyramids"],["2001","A paper in Science by Ruth Shady, Jonathan Haas and Winifred Creamer brings Caral to wide attention"],["2009","The Sacred City of Caral-Supe is inscribed as a UNESCO World Heritage Site"]]},
  "Dong Son culture": {t:["Đông Sơn is an archaeological culture named after a village in Thanh Hóa province, Vietnam, where bronze drums were first excavated in 1924; it centred on the Red River Delta.","Its people farmed rice, kept water buffalo and pigs, fished and sailed long dugout canoes, and cast bronze drums decorated with scenes of their world.","Who the Đông Sơn people were is debated: some link them to the Vietic ancestors of the Vietnamese, others see several peoples who shared one trading culture."],dyk:"The Cổ Loa drum weighs 72 kilograms, and casting it would have required the smelting of between 1 and 7 tonnes of copper ore.",ev:[["c. 1000 BCE","The Đông Sơn culture emerges from the Gò Mun culture in northern Vietnam"],["3rd century BCE","The Chinese text Shiben gives the first literary mention of bronze drums"],["1st century CE","After the defeat of the Trưng sisters and the Han general Ma Yuan’s conquest of the Red River Plain, the bronze drum culture disappears"],["1010–1225","Scattered Đông Sơn bronzes are said to have been found again under the Lý dynasty"],["1898","The Austrian archaeologist Franz Heger, creator of a classification of bronze drums, turns to the drums"],["1924","A fisherman, Nguyễn Văn Lắm, reports bronze finds to the École française d’Extrême-Orient, and excavations begin at Đông Sơn village"],["1970s","Finds in Isan, Thailand, show that bronze casting began in Southeast Asia first or developed there independently of China"]]},
  "Hopewell culture": {t:["Hopewell was not one people but a widespread set of Native American communities, from Lake Ontario to Florida, linked by trade and shared ceremony between about 100 BCE and 500 CE.","Living in small farming and foraging settlements, they built huge geometric earthworks and burial mounds, filled with goods made from materials carried hundreds of miles.","Around 500 CE the exchange ended and mound building stopped, but some Hopewell groups are thought to be ancestral to later peoples, among them the builders of Cahokia."],dyk:"Grave goods at Mound City include hundreds of pounds of obsidian traceable to Yellowstone, and the Ohio Hopewell may have made pilgrimages there, a walk of about 2,000 miles (3,200 kilometres) each way.",ev:[["c. 100 BCE","The Hopewell exchange network begins in the Middle Woodland period; the Toolesboro and Portsmouth earthworks are begun"],["c. 250 CE","Hopewell influence on the Point Peninsula complex of Ontario and New York ends"],["c. 500 CE","The Hopewell exchange ceases, mound building stops and the characteristic art is no longer made"],["1891–1892","Warren K. Moorehead explores the Hopewell Mound Group in Ross County, Ohio, giving the culture its name"],["1982","Ray Hively and Robert Horn publish their study of lunar sightlines at the Newark Earthworks"],["1983","Christopher Turner shows that the Hopeton earthworks align with sunrises and moonrises"]]},
  "Igbo-Ukwu culture": {t:["Igbo-Ukwu is a town in south-eastern Nigeria whose three excavated sites, a shrine, a burial chamber and a cache, held more than 700 objects of copper, bronze and iron.","Its smiths cast bronzes of such fine detail that experts first doubted they were local; analysis showed that most of the metal came from mines about 100 kilometres away.","Glass beads from as far as Mesopotamia, Iran and Egypt show that Igbo-Ukwu was tied into long-distance trade centuries before Europeans reached the coast."],dyk:"Isaiah Anozie, who found the first bronzes while digging in his compound in 1938, did not know what they were: he gave some to friends and neighbours and used some of the vessels to water his goats.",ev:[["c. 2000 BCE","Iron is smelted at Lejja in the Nsukka region, about 100 kilometres east of Igbo-Ukwu"],["9th century CE","Bronzes, beads and a rich burial are placed at Igbo-Ukwu, according to the first radiocarbon dates"],["1938","Isaiah Anozie finds bronzes while digging beside his home"],["1946","The district officer J. O. Field hands the objects he had bought to the Nigerian Department of Antiquities"],["1959–1964","Thurstan Shaw excavates Igbo Isaiah, Igbo Richard and Igbo Jonah"],["1970","Shaw publishes radiocarbon dates placing the sites in the 9th century"],["2022","New radiocarbon dates from Igbo Isaiah fall between the 10th and 13th centuries"]]},
  "Jōmon culture": {t:["For some 14,000 years the people of the Japanese archipelago lived mainly by hunting, gathering and fishing, yet many settled in villages, reaching a considerable degree of sedentism and cultural complexity.","Jōmon potters made the world’s oldest known ceramics, around 14,500 BCE; their pottery was typically decorated by pressing cords into the wet clay, the pattern that gives the culture its name.","The Jōmon people later mixed with the Yayoi rice farmers: modern Japanese carry part of their ancestry, and two Jōmon populations of Hokkaido merged to form the proto-Ainu."],dyk:"A domesticated peach, already similar to modern cultivated forms, appears at Jōmon sites around 4700–4400 BCE, earlier than a variety so close to modern peaches is attested in China itself.",ev:[["c. 14,500 BCE","Jōmon hunter-gatherers make the world’s oldest known pottery, fragments of which survive at Odai Yamamoto I"],["c. 12,000 BCE","As the glaciers melt at the end of the last glacial period, rising seas separate the archipelago from the Asian mainland"],["c. 5000 BCE","The Early Jōmon begins in the warm Holocene climatic optimum, with a rise in population and larger villages"],["c. 4700–4400 BCE","A domesticated peach, apparently brought from China, appears at Jōmon sites"],["c. 3520–2470 BCE","The Middle Jōmon, the warmest phase, produces “flame style” vessels, dogū figurines and more elaborate pit-houses"],["after 1500 BCE","The climate cools and the population appears to contract dramatically"],["c. 900 BCE","Korean-type settlements bringing wet rice farming and bronze and iron metallurgy are established in western Kyushu"],["1877","Edward S. Morse finds cord-marked sherds and gives the culture its name"]]},
  "Kerma culture": {t:["Kerma grew from a fortified village into a city of about 25 hectares, the capital of a centralised Nubian kingdom that controlled the Nile from the First to the Fourth Cataract.","Rich in gold, cattle, ivory and ebony, it traded with Egypt and fought it, raiding deep into Egypt around 1575–1550 BCE in alliance with the Hyksos.","Thutmose I of Egypt destroyed Kerma around 1504 BCE, but rebellions went on for two centuries, and the later Kingdom of Kush honoured Kerma as part of its past."],dyk:"Egyptian royal statues and monuments looted in Kerma’s raid on Egypt were carried back to Kerma, and the defeat is believed to have been erased later from Egypt’s official records; it is known from an inscription in the tomb of the governor Sobeknakht II at Nekheb.",ev:[["c. 3500 BCE","The pre-Kerma culture develops in Upper Nubia, with small kingdoms and settled farming"],["c. 2500 BCE","A new fortified village at Kerma begins the Early Kerma period"],["c. 2000 BCE","Egypt’s Middle Kingdom builds forts in Lower Nubia, while Kerma fortifies Sai as its border"],["c. 1750 BCE","The Classic Kerma period begins: the city grows to about 25 hectares and the Western Deffufa is built"],["c. 1575–1550 BCE","Kerma, allied with the Hyksos, invades deep into Egypt"],["c. 1504 BCE","After the campaigns of Thutmose I, Egypt annexes Kerma"],["1920s","George Andrew Reisner excavates Kerma, taking it for an Egyptian outpost"],["2003","Charles Bonnet’s Swiss team finds a cache of granite statues of the Twenty-fifth Dynasty pharaohs at Kerma"]]},
  "Liangzhu culture": {t:["Liangzhu was a highly stratified rice-farming society of the Yangtze River Delta whose jade, silk, ivory and lacquer went only to elite graves, a division that marks it as an early state.","Its centre, Liangzhu Ancient City near Hangzhou, enclosed 290 hectares with clay walls and six gates around a palace complex, with dams to the north, and is a UNESCO World Heritage Site.","Its jade cong and bi set the standard for ritual jades across Neolithic China, and the culture vanished from the Taihu Lake area after about 2300 BCE, probably because of floods."],dyk:"Liangzhu craftsmen used diamond tools to polish corundum axes to a mirror-like lustre, the earliest known use of diamond tools anywhere, and Liangzhu is the only prehistoric culture known to have worked sapphire.",ev:[["c. 3300 BCE","The Liangzhu culture emerges in the Yangtze River Delta"],["c. 2500 BCE","The Liangzhu culture flourishes"],["after c. 2300 BCE","The culture disappears from the Taihu Lake area, probably after decades of heavy rain and flooding"],["1936","Shi Xingeng first excavates the type site at Liangzhu in Yuhang County, Zhejiang"],["2007","The Zhejiang provincial government announces the discovery of the base of the ancient city walls, the centre of the culture"],["2008","The new Liangzhu Culture Museum is completed and opens"],["2019","The archaeological ruins of Liangzhu City are inscribed as a UNESCO World Heritage Site"]]},
  "Māori": {t:["The ancestors of the Māori sailed from eastern Polynesia in ocean-going waka and settled New Zealand around 1250–1350, last of all the Polynesian lands.","In isolation they built a distinct culture: the moa-hunting Archaic period gave way after 1500 to the Classic culture of iwi and hapū, pounamu, carved meeting houses and fortified pā.","After European contact Māori traded and adopted new tools and writing, but suffered war, disease and the loss of most of their land; today they lead a strong revival of their language and culture."],dyk:"When missionaries met Māori in 1815, Māori could draw accurate maps of their tribal boundaries on paper that matched European maps; the missionaries guessed that they had traditionally drawn maps on sand.",ev:[["c. 1250–1350","Polynesian settlers arrive in New Zealand in ocean-going waka, the main settlement coming in the first half of the 14th century"],["15th century","A group of Māori settles the Chatham Islands (Rēkohu) and becomes the Moriori"],["c. 1500","A significantly cooler climate and the extinction of the moa help bring about the Classic Māori culture"],["1642","Abel Tasman reaches New Zealand; a skirmish leaves four of his men and at least one Māori dead"],["1769","James Cook’s first voyage brings the first lasting contact between Māori and Europeans"],["1805–1840","The Musket Wars between iwi kill many and drive others from their lands"],["6 February 1840","The Treaty of Waitangi is first signed at Waitangi by the British Crown and Māori chiefs"]]},
  "Mapuche": {t:["The Mapuche lived in farming lineages along the rivers of south-central Chile, led by lonkos in peace and by elected toquis in war, without ever forming a state.","After 1550 they fought the Arauco War against Spain for nearly 350 years, and from 1598 kept their lands south of the Biobío River free of Spanish rule.","Chile and Argentina conquered their lands between 1861 and the 1880s; today the Mapuche are the largest Indigenous people of Chile and struggle for their land and rights."],dyk:"Mapuche silversmiths made their jewellery from melted Spanish, Argentine and Chilean silver coins, and old pendants that still hold whole coins help researchers to date them.",ev:[["c. 600–500 BCE","Archaeological finds show a Mapuche culture in what is now Chile"],["11 September 1541","Michimalonco attacks the new Spanish town of Santiago in the Destruction of Santiago"],["1553","Mapuche led by Lautaro defeat the Spanish at the Battle of Tucapel, where Governor Pedro de Valdivia is killed"],["1598","Warriors led by Pelantaro defeat the Spanish at the Battle of Curalaba, starting the uprising that destroys the Spanish cities south of the Biobío"],["1641","The Parliament of Quillín frees Spanish captives under an agreement between Mapuche and Spanish"],["1861–1883","Chile conquers Araucanía in the Occupation of Araucanía, ending Mapuche independence"],["1993","Chile’s Indigenous Law officially recognises the Mapuche people, their language Mapudungun and their culture"]]},
  "Mehrgarh culture": {t:["Mehrgarh is one of the earliest known places in South Asia where people farmed barley and wheat and herded sheep, goats and cattle, living in mud-brick houses.","Over thousands of years its villagers moved from a Neolithic life without pottery to wheel-made decorated wares, copper working, faience beads and seals.","Whether its farming came from the Near East or grew locally is debated, and so is the age of its first village: c. 7000 BCE in the older dating, c. 5250 BCE in the newer."],dyk:"Eleven molar crowns from nine adults buried at Mehrgarh had been drilled during life: the oldest evidence of its kind, taken as a sign of a long tradition of proto-dentistry among early farmers.",ev:[["c. 7000 or 5250 BCE","A small farming village is founded in the north-east corner of the site, by the older and the newer dating of Period I"],["4650–4000 BCE","In Period II pottery appears, with glazed faience beads, more detailed figurines and the first button seals"],["c. 4000–3500 BCE","In Period III Togau pottery with geometric designs, made on a potter’s wheel, appears, and settlements multiply across the region"],["c. 2600–2000 BCE","The site is largely abandoned in favour of the fortified town of Nausharo, during the Indus Valley Civilisation"],["1974","The French Archaeological Mission in the Indus Basin, led by Jean-François and Catherine Jarrige, discovers the site"],["1974–1986, 1997–2000","Excavations recover about 32,000 artefacts from six mounds"],["2006","A study in the journal Nature reports drilled human teeth from the Neolithic graveyard"]]},
  "Mumun culture": {t:["The Mumun is an archaeologists’ label for Korean prehistory c. 1500–300 BCE, named after the Korean word for its plain, undecorated cooking and storage pottery.","Its farmers grew millets, rice, barley, wheat and legumes, and by the Middle Mumun worked large dry fields and paddy fields while still hunting and fishing.","Egalitarian villages gave way to large settlements, elite burials with bronze and jade and simple chiefdom-like polities, and finally to fortified hilltops in a time of conflict."],dyk:"Early Mumun pit-houses could have as many as six hearths, which archaeologists read as homes shared by several generations of one household.",ev:[["c. 1800–1500 BCE","Megalithic burials, Mumun pottery and large settlements appear in the Liao River Basin and North Korea, probable forerunners of the Mumun in the south"],["c. 1500 BCE","The Early Mumun begins, with shifting cultivation, pit-house villages and the first rice farming beside millet"],["c. 850 BCE","The Middle Mumun begins; intensive dry-field and paddy farming support large settlements such as Daepyeong"],["c. 700–550 BCE","Burials with bronze artefacts and greenstone ornaments appear, and bronze production probably begins in southern Korea"],["550 BCE","The Late Mumun begins, with fewer, larger settlements, fortified hilltops such as Namsan and signs of conflict"],["c. 300 BCE","Iron and new hearth-ovens appear and bronze becomes the chief prestige good, closing the Mumun period"],["Mid-1990s","A boom in excavations greatly widens knowledge of the Mumun"],["2005","Songguk-ri Culture pit-houses are found deep in the interior of Gangwon Province"]]},
  "Natufians": {t:["The Natufians lived by hunting and gathering, yet their settlements were larger and more permanent than any before them, some with round stone houses and the first known food stores.","They cut wild cereals with stone sickles and made a bread-like food thousands of years before farming, and they may be the ancestors of the builders of the Levant’s first Neolithic settlements.","Dorothy Garrod named the culture in 1929 after the Wadi Natuf; ancient DNA shows that later Levantines descend mainly from the Natufians."],dyk:"At ʿAin Mallaha in Israel, about 12,000 BCE, an elderly person was buried together with a puppy four to five months old.",ev:[["c. 12,500 BCE","A pita-like bread of wild cereal seeds and tubers is made, among the oldest known bread-like foods"],["c. 12,400–12,000 BCE","A woman of apparent importance is buried in a ceremonial pit in Hilazon Tachtit cave"],["c. 12,000 BCE","At ʿAin Mallaha an elderly person is buried with a puppy"],["c. 10,800 BCE","The Late Natufian begins, in step with the cold, dry Younger Dryas"],["c. 9,500 BCE","The Natufian period ends at the very beginning of the Holocene"],["1928","Dorothy Garrod excavates Shuqba Cave and finds a layer of microliths between Upper Palaeolithic and Bronze Age deposits"],["1929","After finding similar material at el-Wad, Garrod names the Natufian culture after the Wadi Natuf"],["2018","Residues of 13,000-year-old beer are reported from a cave near Haifa"]]},
  "Nazca culture": {t:["The Nazca lived in the river valleys of Peru’s southern desert from about 100 BCE to 800 CE, farming with water drawn from underground channels, several dozen of which still work.","Their ceremonial centre at Cahuachi drew whole villages to feasts, where people received the fine painted pottery that carried Nazca images of gods and mythical beings.","They made the Nazca Lines, vast figures and lines on the desert floor whose purpose is still debated, and declined after about 500 CE amid floods and erosion."],dyk:"Some Nazca burials have a “head jar” in place of the missing head: a pot painted with a human face, sometimes with plants sprouting from it.",ev:[["c. 100 BCE","Nazca culture emerges from the Paracas culture on the southern coast of Peru"],["c. 1–450 CE","In the Early Nazca period, the mounds and plazas of Cahuachi are the centre of ritual and feasting"],["c. 450 CE","Around the end of Nazca phase 3 or start of phase 4 Cahuachi is abandoned, probably after a drought across the Andes"],["c. 450–550 CE","In the Middle Nazca period the puquios, underground aqueducts, are built"],["c. 500 CE","Nazca society begins to decline"],["c. 650 CE","Power shifts from the coast to the highlands with the rise of the Wari culture"],["c. 750 CE","Nazca culture has fallen, probably after El Niño floods on a landscape stripped of trees"]]},
  "Oxus civilisation": {t:["The Oxus civilisation was a Middle Bronze Age culture of walled towns in present-day Turkmenistan, Afghanistan and Uzbekistan, named the BMAC by Viktor Sarianidi in 1976.","Its farmers irrigated wheat and barley, its craftspeople worked bronze, copper, silver and gold, and its towns traded with the Indus Valley, the Iranian Plateau and the Persian Gulf.","Its link with the Indo-Iranians is debated; DNA shows its people descended mainly from local farmers related to those of the Iranian plateau, later mixing with steppe herders."],dyk:"A model of a cart drawn by a camel, from about 2200 BCE, was found at Altyn Depe: camels were domesticated within the Oxus civilisation.",ev:[["c. 3000 BCE","Models of two-wheeled carts at Altyn Depe give the earliest evidence of wheeled transport in Central Asia"],["c. 2800–2400 BCE","Altyn Depe in the Kopet Dag foothills develops a proto-urban society"],["c. 2400–2250 BCE","The urban Integration Era begins, by different datings, with walled centres such as Namazga Depe, Altyn Depe, Kelleli and Gonur Depe"],["c. 2250–2200 BCE","A foal is buried on a four-wheeled wagon with bronze-banded wheels in the Royal Necropolis at Gonur Depe"],["c. 2000 BCE","Contacts with the peoples of the Eurasian steppes to the north intensify"],["c. 1900 BCE","The walled centres shrink sharply, and Tazabagyab-Andronovo pottery spreads through the Bactrian and Margian countryside"],["c. 1700 BCE","The urban phase ends, by Dubova and Lyonnet’s dating"],["1976","Viktor Sarianidi names the complex the Bactria–Margiana Archaeological Complex"]]},
  "Painted Grey Ware culture": {t:["Painted Grey Ware is an archaeologists’ name for a culture identified by its fine grey bowls painted with simple black patterns, found at 1,576 sites in northern India.","Its people farmed with the plough, kept cattle, sheep, pigs and horses, worked iron and ivory, and lived mostly in villages, with several dozen towns.","It probably corresponds to the middle and late Vedic period and the Kuru-Panchala kingdom, and many of its settlements grew into the towns of the Northern Black Polished Ware period."],dyk:"The painted grey ware was a luxury: almost all of it is drinking ware, and it makes up only 10–15% of the pottery found from Vedic times, most of the rest being red ware.",ev:[["c. 1300–1000 BCE","Painted Grey Ware appears in the Ghaggar valley and the upper Ganga region (Uesugi’s Period I)"],["c. 1000–600 BCE","The culture spreads into the western part of the Ganga valley (Uesugi’s Period II)"],["c. 700–500 BCE","Northern Black Polished Ware succeeds it, with the rise of the Mahajanapada states"],["c. 600–300 BCE","In Uesugi’s Period III the culture interacts with regions to the east"],["2006","Plain Grey Ware is found at Anuradhapura in Sri Lanka in levels of 600–500 BCE, showing connections with northern India"],["2013","Excavations at Alamgirpur, near Delhi, reveal an overlap between late Harappan and the earliest Painted Grey Ware levels"],["2015","Two periods of Painted Grey Ware are identified at Ahichhatra, c. 1500–800 and 800–400 BCE"],["2018","1,576 Painted Grey Ware sites are known"]]},
  "Sámi": {t:["The Sámi are the Indigenous people of Sápmi, speaking about ten related Uralic languages, and have lived in the far north of Europe since the Bronze Age or early Iron Age.","For most of their history they lived by fishing, hunting, trapping and trade; large-scale reindeer herding grew from about 1500, and today about one Sámi in ten is connected to it.","Taxation, forced conversion, closed borders and assimilation policies bore down on them for centuries; since the 1970s Sámi parliaments, a flag, an anthem and a national day have marked a revival."],dyk:"All modern versions of the board game hnefatafl, usually sold as a Viking game, are based on the Sámi game tablut, the only tafl game whose rules survived relatively intact.",ev:[["c. 98 CE","Tacitus describes the Fenni, probably the first historical mention of the Sámi"],["1349","The Black Death reaches northern Norway; Sámi later settle the abandoned farms, and the Sea Sámi way of life takes shape"],["c. 1500","Wild reindeer decline under hunting driven by taxes, and reindeer herding begins to grow"],["1751","The Lapp Codicil to the Strömstad Treaty sets out how Sámi may use the land across the Swedish–Norwegian border"],["1852","Sámi angered by religious persecution and Norwegianisation rise in the Kautokeino Rebellion"],["6 February 1917","The first Sámi congress meets in Trondheim, bringing Norwegian and Swedish Sámi together"],["1979","The Alta hydro-electric controversy brings Sámi rights onto the political agenda"],["1989","The first Sámi Parliament in Norway is elected, after Finland’s of 1973 and before Sweden’s of 1993"]]},
  "Sangam-age Tamilakam": {t:["Sangam-age Tamilakam was the ancient Tamil-speaking country of southern India, divided among the Chera, Chola and Pandya kings and lesser chieftains, the Velir.","Its 2,381 surviving poems by 473 poets, at least 27 of them women, sing of love and war and are the earliest known literature of South India.","Farming, weaving, pearl fishing and shipbuilding supported a sea trade in pearls, pepper and textiles that brought Roman coins to Kerala and Tamil Nadu."],dyk:"The Sangam poems were forgotten for much of the second millennium; in 1883 U. V. Swaminatha Aiyar found a major store of their palm-leaf manuscripts in the library of the Thiruvavaduthurai Adhinam, a Shaiva monastery.",ev:[["6th century BCE","A settlement at Keezhadi, near Madurai, is occupied, according to radiocarbon dating"],["3rd century BCE","Inscriptions of the time of the Maurya Empire give the earliest datable references to the Tamil kingdoms"],["c. 237 BCE","Two adventurers from southern India take control of the Anuradhapura kingdom in Sri Lanka"],["145 BCE","Elara, a Chola general or prince, takes the throne of Anuradhapura and rules for forty-four years"],["c. 100 BCE–250 CE","The span Kamil Zvelebil finds most acceptable for the Sangam poems"],["1st century CE","The Periplus of the Erythraean Sea describes Muziris, a Chera port of the trade with Rome"],["1883","U. V. Swaminatha Aiyar finds major Sangam manuscripts at the Thiruvavaduthurai Adhinam"],["2013–2014","A survey along the Vaigai river led by Amarnath Ramakrishna identifies Keezhadi among 293 sites with archaeological remains"]]},
  "Sanxingdui culture": {t:["Sanxingdui was a Bronze Age culture in Sichuan, contemporary with the Shang dynasty, that cast bronzes in a style of its own: great masks with bulging eyes, a life-sized standing figure and a bronze tree almost 4 m high.","Its people built a walled city of 3.6 square kilometres, ringed by canals and divided into districts, and the culture is thought to have been governed by a strong central theocracy.","Many Chinese archaeologists identify it with the early kingdom of Shu, whose legendary founder Cancong was said to have protruding eyes like those of the bronze masks."],dyk:"Paint survives on the bronze faces, black on the large eyes and eyebrows and vermilion on the lips, nostrils and ear holes, which the sinologist Corinne Debaine-Francfort reads as offerings for the head to taste, smell and hear.",ev:[["c. 1600 BCE","A walled city is founded at Sanxingdui on the banks of the Yazi River"],["12th–11th centuries BCE","The date radiocarbon dating gives the gold, bronze, jade and pottery objects later found in the sacrificial pits"],["316 BCE","The state of Qin conquers the region of the kingdom of Shu"],["1927","A farmer dredging an irrigation ditch unearths a large cache of jade objects"],["1934","David Crockett Graham of West China Union University organises the first archaeological excavation"],["1986","Local workers find two sacrificial pits filled with broken and burned gold, bronze, jade and pottery objects"],["1997","The Sanxingdui Museum opens near the site"],["2020–2022","Six more sacrificial pits are excavated, yielding a gold mask, ivory, bronzes and traces of silk"]]},
  "South Indian megalithic culture": {t:["South India’s megalithic culture is an archaeologists’ label for an Iron Age way of burying the dead in graves built or marked with large stones, or in clay urns.","Its graves and settlements yield iron sickles, spears and swords, black and red ware pots, beads and ornaments, and pots scratched with symbols whose meaning is still unknown.","Its dating is argued over, from securely dated sites of about 1000 BCE to disputed claims of far earlier iron; the graffiti marks disappear from graves around 300 CE."],dyk:"When Adichanallur was first dug in 1876, a German ethnologist, Dr Jagor, took its pots, iron weapons and skulls to Berlin, to the museum now called the Ethnological Museum of Berlin.",ev:[["c. 1248–1155 BCE","Rice from an intact burial urn holding iron artefacts at Sivagalai, Tamil Nadu, gives these dates"],["c. 1000 BCE","Early Iron Age burials at Hallur in Karnataka and Adichanallur in Tamil Nadu, the more securely dated sites"],["905–696 BCE","The range given by carbon dates for samples from Adichanallur, reported in 2019"],["5th century BCE","The earliest reliably dated iron furnace in Tamil Nadu is built at Kodumanal"],["c. 300 CE","The graffiti symbols disappear from grave sites"],["1876","The mound at Adichanallur is first dug, and its finds go to the Berlin ethnological museum"],["1947","Mortimer Wheeler excavates Brahmagiri, helping to establish the culture sequence of south Indian prehistory"],["2004–2006","Excavations at Adichanallur uncover skeletons buried in clay urns"]]},
  "Taíno": {t:["The Taíno lived in villages of large round houses around a central plaza, farmed cassava in heaped mounds and were ruled by caciques, whose office usually passed through the female line.","Their religion centred on zemís, spirits and ancestors given form in carved wood, stone, shell and cotton, and honoured with cohoba snuff, songs and ceremonies.","Spanish conquest after 1492 brought forced labour, war and epidemics that killed most Taíno within decades, yet Taíno descent, customs and identity survive in the Caribbean today."],dyk:"The English words barbecue, hammock, canoe, tobacco, savanna and hurricane all come from Taíno words: barbacoa, hamaca, kanoa, tabaco, sabana and juracán.",ev:[["c. 500 BCE","Pottery-making farmers of the Ceramic Age, ancestors of the Taíno, enter the Caribbean from north-eastern South America"],["8th–10th century CE","A woman later studied as an “ancient Taíno” lives in the Bahamas; her genome was mapped in 2018"],["12 October 1492","Christopher Columbus lands in the Bahamas, on the island the Taíno called Guanahaní"],["1493","On his second voyage Columbus begins to demand tribute in gold and cotton from the Taíno of Hispaniola"],["1511","Caciques of Puerto Rico, among them Agüeybaná II, rise against the Spanish, while Antonio de Montesinos denounces the enslavement of the islanders"],["2 February 1512","The cacique Hatuey, who had fled from Hispaniola to Cuba to unite its peoples, is burned at the stake"],["1520s","Enriquillo leads more than 3,000 Taíno in a successful rebellion on Hispaniola and wins land and a royal charter"],["2010","9,399 people in Puerto Rico identify as Taíno in the United States census"]]},
  "Thracians": {t:["‘Thracians’ was the Greek name for some 200 tribes of south-eastern Europe who shared much of their culture but were rarely united in one state.","Greek and Roman writers called them warlike barbarians while hiring them as mercenaries and noting their poetry and music; the fairness of these accounts is now questioned.","Their tombs and gold and silver treasures, studied mainly in Bulgaria and Romania, give a fuller picture of a people gradually absorbed into Roman, Byzantine and Slavic societies."],dyk:"In 570 CE Antoninus Placentius reported a monastery in the valleys of Mount Sinai whose monks spoke Greek, Latin, Syriac, Egyptian and Bessian, the language of a Thracian tribe.",ev:[["8th century BCE","The first Greek colonies are founded on the Thracian coasts"],["637 BCE","The Thracian Treres, with the Cimmerians and Lycians, capture Sardis, the Lydian capital, except its citadel"],["513 BCE","Darius I of the Achaemenid Empire marches into Thrace and brings its tribes under Persian rule"],["early 5th century BCE","Teres I founds the Odrysian Kingdom, the first lasting Thracian state"],["73–71 BCE","The Thracian gladiator Spartacus leads a great slave uprising in southern Italy"],["46 CE","Thracia becomes a Roman province after the murder of King Rhoemetalces III"],["570 CE","Antoninus Placentius records monks speaking Bessian at a monastery near Mount Sinai"],["1960s–1970s","Intensive excavations in Bulgaria uncover many Thracian tombs and sanctuaries"]]},
  "Thule people": {t:["The Thule were the direct ancestors of the Inuit and Yupik, who developed in coastal Alaska by 1000 CE and in a few centuries spread across the Canadian Arctic to Greenland.","Bowhead whales were at the heart of Classic Thule life, hunted by cooperating boat crews under a captain, the umialik, and used for food, fuel, house frames and tools.","Dog sleds, kayaks and large skin boats let the Thule range far and trade widely, and they displaced the earlier Dorset people across the eastern Arctic."],dyk:"Long before European contact the Thule worked iron, some of it from meteorites such as the Cape York meteorite in Greenland and some traded from the Norse.",ev:[["c. 200 BCE","The Old Bering Sea stage, an early phase of the Thule Tradition, begins around the Bering Strait"],["c. 800 CE","The Punuk and Birnirk stages develop on the Bering Strait islands and the coasts of northern and western Alaska"],["c. 1000 CE","Thule culture has developed in coastal Alaska, and Thule groups begin moving east across the Canadian Arctic"],["11th century","The Norse reach the shores of Canada, and contact with the Thule follows"],["13th century","Thule migrants reach Greenland"],["c. 1300 CE","Thule populations have largely replaced the Dorset people of northern Canada and Greenland"],["c. 1600 CE","Colder climate ends whaling from boats in the High Arctic, which the Thule abandon; local Inuit groups emerge"],["1921–1924","Therkel Mathiassen of the Fifth Thule Expedition excavates sites and maps out the Thule culture"]]},
  "Ubaid culture": {t:["The Ubaid period left the earliest known settlements on the southern Mesopotamian plain, in villages of mud-brick houses with the first temples in Mesopotamia.","Ubaid pottery and customs spread from south-eastern Turkey to the Persian Gulf, according to Gil Stein and Rana Özbal largely through the peaceful spread of ideas rather than conquest.","Graves show growing differences in wealth and rank, but there were still no real cities: those came in the Uruk period that followed."],dyk:"A clay disc from the site of H3 in Kuwait shows a two-masted boat, the oldest evidence for the use of masts and sails.",ev:[["c. 6500 BCE","The Ubaid period begins in southern Mesopotamia; Tell el-ʿOueili is the oldest known Ubaid site"],["c. 5300 BCE","Ubaid pottery reaches its peak along the coast of the Persian Gulf"],["c. 5000–4900 BCE","Unalloyed copper pins and chisels are made at Mersin, among the earliest Ubaid metalwork"],["c. 4500–4000 BCE","Central houses grow larger as social differences increase in the late Ubaid"],["c. 3800 BCE","The Ubaid period gives way to the Uruk period in the south"],["1919","Henry Hall begins the first large excavation of Ubaid material at Tell al-ʿUbaid"],["1930","A conference in Baghdad defines the ‘Ubaid pottery style’"],["1960","Joan Oates shows that the Eridu and Hajji Muhammed styles belong to the Ubaid and divides it into phases"]]},
  "Vedic civilisation": {t:["The Vedic period takes its name from the Vedas, liturgical texts composed and passed on by word of mouth in the northern Indian subcontinent between the end of the Indus cities and new cities of c. 600 BCE.","Early Vedic society was tribal and pastoral, centred in the Punjab; later, with iron tools, it settled the western Ganges Plain and formed kingdoms such as the Kuru.","The age produced fire sacrifice, the four varnas and the early Upanishads, and its tradition became one of the main parts of the later “Hindu synthesis”."],dyk:"Horses, needed for cavalry and for sacrifice, could not be bred in India, so Vedic leaders kept up trade routes beyond the Hindu Kush to obtain them.",ev:[["c. 1900 BCE","The urban Indus Valley Civilisation collapses; in the mainstream view, Indo-Aryan groups then settle the northern Indus Valley"],["c. 1400–1000 BCE","The Rigveda, the oldest layer of the Vedas, is composed"],["Early Vedic period","The Bharatas under their chief Sudas defeat a confederation of ten tribes in the Battle of the Ten Kings on the river Parushni (Ravi)"],["c. 1200–1000 BCE","Vedic culture spreads east to the western Ganges Plain, and iron tools come into use"],["c. 12th–11th century BCE","The early Kuru kingdom forms; Vedic hymns are collected and the Śrauta rituals developed"],["c. 900–750 BCE","After the Kuru decline, the political centre of Vedic culture moves to Panchala under King Keśin Dālbhya"],["8th or 7th century BCE","Videha rises under King Janaka, patron of the sages Yajnavalkya, Uddalaka Aruni and Gargi Vachaknavi"],["c. 600–500 BCE","The Mahajanapadas, the first true cities and the śramaṇa movements, among them Jainism and Buddhism, mark the end of the period"]]},
  "Yamnaya culture": {t:["‘Yamnaya’ is an archaeologists’ label from a Russian word meaning ‘related to pits’, after the pit graves under burial mounds that mark this herding culture of the steppe.","Its people moved their herds across the steppe in carts and wagons and were organised in chiefdoms; whether they also rode horses is disputed.","The widely accepted Kurgan hypothesis holds that they spoke a stage of Proto-Indo-European, and DNA links them to much later European and South Asian ancestry, though critics question how far."],dyk:"In some areas elite members of the Yamnaya culture were buried with complete wooden wagons.",ev:[["c. 3750–3350 BCE","The core Yamnaya culture forms in the lower Dnieper–Don steppe"],["c. 3400–3200 BCE","The early Yamnaya horizon spreads quickly across the Pontic–Caspian steppes, in David Anthony’s account"],["c. 2800 BCE","The Catacomb culture begins to succeed the Yamnaya in its western range"],["c. 2700 BCE","The Poltavka culture follows the Yamnaya on the middle Volga"],["1901–1903","Vasily Gorodtsov excavates near the Donets River and defines the culture"],["2015","Genetic studies model the Yamnaya as a roughly equal mix of Eastern European and Caucasus hunter-gatherer ancestry"],["2025","Higher-resolution modelling traces about 80% of Yamnaya ancestry to a Caucasus–Lower Volga population"]]},
  "Yangshao culture": {t:["The Yangshao people farmed millet, and some rice, along the middle Yellow River and kept pigs and dogs; over two thousand years their region became a fully settled farming society.","Their potters, working without a wheel, made fine painted wares whose fish, face and geometric designs changed over time and spread west to the Majiayao culture and beyond.","Villages of houses round a central square were joined in the later phases by settlement hierarchies, large public buildings and, at Xishan, the first rammed-earth wall in China."],dyk:"A dragon figure from the Yangshao culture, dating to the fifth millennium BCE, is the world’s oldest known depiction of a dragon.",ev:[["c. 5000 BCE","The Early Yangshao, or Banpo phase, begins, with villages such as Banpo and Jiangzhai in the Wei River valley"],["5th millennium BCE","A dragon figure is made that is the oldest known depiction of a dragon"],["c. 4000 BCE","In the Middle Yangshao, or Miaodigou phase, the culture and its population expand in all directions"],["c. 3500 BCE","The Late Yangshao begins, with settlement hierarchies spreading and the first rammed-earth wall in China built at Xishan"],["c. 3300 BCE","The Majiayao culture, which grew out of the middle Yangshao through an intermediate Shilingxia phase, begins to the west"],["1921","Johan Gunnar Andersson discovers the Yangshao site in western Henan, which gives the culture its name"],["1954","The Yangshao culture is estimated to be more than 1,000 years older than the Anau culture, weakening Andersson’s theory of a western origin"]]},
  "Yayoi culture": {t:["The Yayoi period brought wet-rice farming to the Japanese archipelago, and with it permanent villages, stored grain, landholding and a more stratified society.","Farming migrants from the Korean Peninsula and other parts of the continent mixed with the Jōmon population, laying the foundations of the modern Japanese people and, most linguists think, spreading the Japonic languages.","Chinese histories describe the land of Wa as many scattered communities, among them the Na state, which received a golden seal in 57 CE, and Yamataikoku under Queen Himiko."],dyk:"The golden seal that Emperor Guangwu of the Later Han dynasty gave to the Na state of Wo in 57 CE, recorded in the Book of the Later Han, was found in northern Kyushu in the 18th century.",ev:[["c. 1000–800 BCE","The earliest start for the Yayoi suggested by disputed radiocarbon dates from residue on pottery"],["c. 300 BCE","The conventional start of the Yayoi period, as wet-rice farming spreads from northern Kyushu"],["1st century CE","Iron farming tools and weapons come into use, and large regional powers emerge across western Japan"],["57 CE","The Na state of Wo receives a golden seal from Emperor Guangwu of the Later Han dynasty"],["late 2nd century CE","The political entity known as Wa-koku has formed"],["3rd century CE","The Wei zhi records Queen Himiko of Yamataikoku, who took the throne of Wa as a spiritual leader after a civil war"],["mid-3rd century CE","The first keyhole-shaped burial mounds mark the transition to the Kofun period"],["19th century","Archaeologists name the culture after the Yayoi district of Tokyo, where its pottery was first found"]]},
  "Hungary": {t:["Hungary's change from communism to capitalism, the rendszerváltás, was peaceful: Round Table Talks began in March 1989, Imre Nagy was reburied as a martyr that June, and free elections in May 1990 made József Antall prime minister.","Hungary joined NATO in 1999, the European Union on 1 May 2004 and the Schengen Area in 2007; in January 2008 its border guards were merged into the police.","From 2010 Viktor Orbán's Fidesz won four parliamentary supermajorities and passed a new constitution, in an era of democratic backsliding that ended when Péter Magyar's Tisza Party won the election of April 2026."],dyk:"Hungary's Fundamental Law contains eternity clauses guaranteeing human dignity, the separation of powers, the state structure and the rule of law, which even the two-thirds supermajority needed for other amendments may not touch.",ev:[["1989","The Hungarian Socialist Workers' Party opens Round Table Talks with the opposition in March; the reburial of Imre Nagy in June marks the symbolic end of communism in Hungary."],["1990","Free elections in May bring the Hungarian Democratic Forum to the head of a coalition; József Antall becomes the first democratically elected prime minister since the Second World War."],["1991","The removal of state subsidies and rapid privatisation, with the Yugoslav Wars on the southern border, bring a severe recession."],["1999","Hungary joins NATO."],["2004","Hungary joins the European Union on 1 May."],["2010","Viktor Orbán's Fidesz wins a two-thirds parliamentary supermajority and the legislature approves a new constitution."],["2026","Péter Magyar's Tisza Party wins a supermajority in the election of 12 April; Magyar is sworn in as prime minister on 9 May."]]},
  "Federal Republic of Germany": {t:["The western sectors held by France, the United Kingdom and the United States were merged on 23 May 1949 into the Federal Republic, which chose Bonn as a provisional capital to stress that two German states were meant to be temporary.","Marshall Plan aid and the Wirtschaftswunder from the early 1950s, NATO membership in 1955 and a founding place in the European Economic Community set West Germany's course; the Saarland joined on 1 January 1957.","Reunification on 3 October 1990 brought the five re-established eastern states into the Federal Republic, which regained full sovereignty on 15 March 1991 and is now the world's third-largest exporter and importer."],dyk:"Germany has the world's oldest universal health care system, dating from Bismarck's social legislation of the 1880s; the Federal Republic still insures its population by statute, and spent 12.27% of its GDP on health in 2024.",ev:[["1949","On 23 May the three western occupation zones are merged into the Federal Republic of Germany; Konrad Adenauer is elected the first federal chancellor and Bonn becomes the provisional capital."],["1955","West Germany joins NATO; it is a founding member of the European Economic Community."],["1957","On 1 January the Saarland joins West Germany."],["1990","On 3 October after the Two Plus Four Treaty, the German Democratic Republic is dissolved and its five re-established states accede to the Federal Republic."],["1991","On 15 March Germany regains its full sovereignty from the Allies."],["2002","Germany introduces the euro; the European Central Bank sits in Frankfurt."],["2005","Angela Merkel becomes the first female chancellor."],["2022","After Russia's invasion of Ukraine, Chancellor Olaf Scholz announces a one-time 100 billion euro infusion into the Bundeswehr and spending beyond NATO's 2% target."]]},
  "Hellenic Republic": {t:["Turkey's invasion of Cyprus on 20 July 1974, after a Greek-backed coup there, brought down the junta; Konstantinos Karamanlis returned, the first multiparty elections since 1964 were held, and a 1975 referendum rejected the monarchy.","Greece became the tenth member of the European Communities in 1981, adopted the euro in January 2001 and hosted the 2004 Summer Olympic Games in Athens; New Democracy and PASOK alternated in power for four decades.","The debt crisis from 2010 brought bailouts of 110 billion and 130 billion euros, a 25% fall in GDP between 2009 and 2015 and the emigration of 350,000 to 450,000 people before the bailouts ended in 2018."],dyk:"The Greek merchant fleet, the largest in the world at 18% of global capacity and first in tankers and dry bulk carriers, was built after the Second World War from surplus ships sold off by the United States government.",ev:[["1974","Turkey invades Cyprus on 20 July after a Greek-backed coup; the junta collapses, Konstantinos Karamanlis returns and the first multiparty elections since 1964 are held."],["1975","A democratic and republican constitution is promulgated after a referendum chooses not to restore the monarchy."],["1981","Greece becomes the tenth member of the European Communities; Andreas Papandreou's PASOK comes to power."],["2001","The euro replaces the drachma in January."],["2004","Athens hosts the Summer Olympic Games."],["2010","A 110 billion euro rescue package from the eurozone and the IMF averts default; harsh austerity follows."],["2018","The bailouts end; Alexis Tsipras and Zoran Zaev sign the Prespa Agreement, settling the Macedonia naming dispute."],["2019","Kyriakos Mitsotakis of New Democracy becomes prime minister; re-elected in June 2023 with 158 seats."]]},
  "Republic of Austria": {t:["Austria's second republic was declared on 27 April 1945 with the approval of the Red Army, while most of the west and south were still under Nazi rule; the Federal Constitutional Law of 1920 was declared valid again on 1 May 1945.","The Austrian State Treaty of 15 May 1955 ended ten years of Allied occupation; on 26 October 1955, with the last troops gone, parliament declared the country's perpetual neutrality, and the day is now Austria's National Day.","After a referendum carried by two-thirds in 1994 Austria joined the European Union on 1 January 1995, signed the Schengen Agreement the same year and adopted the euro in 1999; Vienna hosts the OSCE and OPEC."],dyk:"Austria built a nuclear power station at Zwentendorf on the Danube after a unanimous vote of parliament in 1972, then voted 50.5% to 49.5% against nuclear power in a 1978 referendum; parliament banned it and the finished plant never produced electricity.",ev:[["1945","On 27 April Karl Renner, Adolf Schärf, Leopold Kunschak and Johann Koplenig declare Austria's secession from the Third Reich and set up a provisional government in Vienna, backed by Joseph Stalin."],["1946","On 26 July parliament passes the first nationalisation law; about 70 mining and manufacturing companies pass to the state."],["1955","The Austrian State Treaty of 15 May restores full independence; on 26 October, with the occupation troops gone, parliament declares permanent neutrality."],["1978","A referendum rejects nuclear power by 50.5% to 49.5% and the finished Zwentendorf plant is never switched on."],["1986","Kurt Waldheim, former secretary-general of the United Nations and a Wehrmacht officer accused of war crimes, is elected president."],["1995","Austria joins the European Union on 1 January after a two-thirds referendum majority, and signs the Schengen Agreement."],["2017","Sebastian Kurz's People's Party wins the snap election and forms a government with the Freedom Party, sworn in on 18 December; it falls in 2019 over the Ibiza scandal."],["2024","After the election of 29 September, coalition talks collapse and Karl Nehammer resigns; a People's Party, Social Democrat and NEOS coalition under Christian Stocker eventually takes office."]]},
  "Republic of Turkey": {t:["The Treaty of Lausanne of 24 July 1923 won international recognition for the Turkish state as the Ottoman Empire's successor, and the Republic was proclaimed on 29 October 1923 in Ankara, the new capital.","Mustafa Kemal's reforms turned a religion-based, multi-communal monarchy into a secular nation state: a civil code based on the Swiss code in 1926, the alphabet reform, and the vote for women in 1934.","Turkey joined NATO in 1952 after fighting in the Korean War and keeps the alliance's second-largest military; coups or memorandums in 1960, 1971, 1980 and 1997 broke its multiparty politics, and a 2017 referendum made it a presidential republic."],dyk:"Non-Muslims were 19.1% of the population of what is now Turkey in 1914 and 2.5% by 1927, after the genocides of the war years and the population exchange with Greece; today they are about 0.2%.",ev:[["1923","The Republic is proclaimed in Ankara after the Treaty of Lausanne and the withdrawal of the last Allied troops from Istanbul on 4 October; Mustafa Kemal becomes its first president."],["1934","Women gain the right to vote nationally; the Surname Law gives Mustafa Kemal the name Atatürk."],["1938","Atatürk dies and İsmet İnönü becomes the second president; Turkey stays neutral in almost all of the Second World War."],["1952","After fighting with the UN forces in the Korean War, Turkey joins NATO as a bulwark against Soviet expansion into the Mediterranean."],["1980","The third military coup, after those of 1960 and 1971; the constitution still in force is approved by referendum in 1982."],["2002","Recep Tayyip Erdoğan's Justice and Development Party (AKP) wins power, beginning more than two decades of AKP government."],["2016","On 15 July an attempted coup fails; by 2024 the government counts 13,251 people jailed in connection with it."],["2017","A referendum replaces the parliamentary republic with an executive presidency and abolishes the office of prime minister."]]},
  "Saudi Arabia": {t:["Abdulaziz recaptured Riyadh in 1902, took Al-Ahsa from the Ottomans in 1913 with the Ikhwan, conquered the Kingdom of Hejaz in 1924–25 and, after crushing the Ikhwan at the Battle of Sabilla in 1929, united Hejaz and Nejd as Saudi Arabia on 23 September 1932.","Oil found in Al-Ahsa in 1938 and developed by Aramco from 1941 made the kingdom the world's largest oil producer by 1976; the 1973 embargo quadrupled oil prices, and the state bought out Aramco's American owners in 1980.","The Al Saud rule as absolute monarchs under the Basic Law of 1992, with uncodified Sharia and the ulema, led by the Al ash-Sheikh, sharing power in a pact dating from 1744; no political parties or national elections are permitted."],dyk:"Saudi Arabia's slave population was estimated at 300,000 as recently as the early 1960s; slavery was officially abolished only in 1962.",ev:[["1932","On 23 September Prince Faisal declares on Ibn Saud's behalf the unification of the kingdoms of Hejaz and Nejd as the Kingdom of Saudi Arabia, now the Saudi National Day."],["1938","Vast oil reserves are discovered in Al-Ahsa on the Persian Gulf; full-scale development begins in 1941 under the American-controlled Aramco."],["1973","Saudi Arabia leads an oil embargo against the Western countries that supported Israel in the Yom Kippur War, and oil prices quadruple."],["1979","The Iranian Revolution and the seizure of the Grand Mosque in Mecca by Islamist militants, retaken after ten days, push the royal family towards stricter religious observance and a greater role for the ulema."],["1990","After Iraq invades Kuwait, King Fahd asks the United States to intervene and allows American and coalition troops to be stationed in the kingdom; Saudi forces join the Gulf War of 1991."],["1992","King Fahd introduces the Basic Law in March; the Consultative Council of sixty appointed members is inaugurated in December 1993."],["2015","Saudi Arabia mobilises 150,000 troops and 100 fighter jets to intervene in the civil war in Yemen; women vote and stand in municipal elections for the first time."],["2017","Crown Prince Mohammed bin Salman takes power; as many as 500 princes, ministers and businessmen are arrested in an anti-corruption campaign in November."]]},
  "Lebanese Republic": {t:["Greater Lebanon was created under French Mandate on 1 September 1920, joining Mount Lebanon with the north, the south and the Beqaa; the republic was proclaimed on 1 September 1926 and won its independence in November 1943.","The unwritten National Pact of 1943 reserves the presidency for a Maronite Christian, the premiership for a Sunni and the speakership for a Shia; the Taif Agreement of 1989 made parliament's 128 seats equal between Christians and Muslims.","The civil war of 1975–1990 killed an estimated 150,000 people and displaced nearly a million; Syrian forces stayed until 2005 and Israel held the south until 2000, and Hezbollah has since outgunned the national army."],dyk:"Lebanon has held no census since 1932, when Christians were 53% of the population: the relative size of its religious communities is too sensitive for its confessional politics to count.",ev:[["1926","On 1 September the Lebanese Republic is proclaimed under the French Mandate, with a constitution inspired by France's adopted on 23 May; the country stays under French control."],["1943","The new government abolishes the mandate on 8 November and is imprisoned by the French; under British pressure the officials are released on 22 November and France accepts Lebanon's independence."],["1975","Full-scale civil war breaks out between Christian groups and the forces of the PLO and left-wing Druze and Muslim militias."],["1989","Parliament agrees the Taif Agreement, with a timetable for Syrian withdrawal and equal Christian and Muslim representation; the war ends at the end of 1990."],["2000","Israeli forces withdraw fully from southern Lebanon in May; 25 May becomes Liberation Day."],["2005","Former Prime Minister Rafic Hariri is assassinated on 14 February; mass demonstrations force Syria to withdraw its troops by 26 April."],["2019","Mass protests from 17 October against sectarian rule, corruption and the liquidity crisis; the currency collapses and the state defaults in 2020."],["2024","Israel invades on 1 October after killing Hezbollah's leader Hassan Nasrallah on 27 September; a ceasefire follows in November."]]},
  "Syrian Arab Republic": {t:["Syria seceded from the United Arab Republic on 28 September 1961; the Ba'athist coup of 8 March 1963 then founded a one-party state that ruled under martial law until 2011 and fell in December 2024.","Hafez al-Assad's Corrective Movement of November 1970 made the Ba'athist state a hereditary dictatorship: Alawite loyalists held the key posts, a cult of personality surrounded the family, and his son Bashar succeeded him in 2000.","The uprising that began on 26 January 2011 became a thirteen-year civil war with more than 600,000 dead, over 5 million refugees and a GDP that shrank by 84% between 2010 and 2023; Hay'at Tahrir al-Sham took Damascus on 8 December 2024."],dyk:"By 2021 the amphetamine captagon, produced by associates and relatives of Bashar al-Assad, was Syria's largest export at a minimum of US$3.4 billion a year, against about US$122 million for olive oil, its largest legal export.",ev:[["1961","On 28 September a coup takes Syria out of the United Arab Republic and ends the political union with Egypt."],["1963","On 8 March the Military Committee of the Arab Socialist Ba'ath Party seizes power and establishes a one-party state under martial law."],["1967","In the Six-Day War Israel captures two-thirds of the Golan Heights in under 48 hours."],["November 1970","Hafez al-Assad, Minister of Defense, deposes Salah Jadid in the bloodless Corrective Movement and becomes the state's strongman."],["1982","The Islamist uprising of the Muslim Brotherhood ends in the Hama massacre, in which Ba'athist troops and paramilitaries kill between 2,000 and 40,000 people."],["2000","Hafez al-Assad dies on 10 June; his son Bashar is elected president unopposed, and the Damascus Spring is suppressed by autumn 2001."],["2011","Protests from 26 January become a nationwide uprising; the army is sent against the cities and defectors form the Free Syrian Army."],["2024","On 8 December opposition forces led by Hay'at Tahrir al-Sham capture Damascus, ending 53 years of Assad family rule; Bashar al-Assad flees to Moscow."]]},
  "Azerbaijan": {t:["The Supreme Council of Azerbaijan adopted a Declaration of Independence on 18 October 1991, affirmed by a referendum in December, days before the Soviet Union ceased to exist on 26 December.","The First Nagorno-Karabakh War left Armenians in control of 14–16 percent of Azerbaijani territory by 1994; the Second War of 2020 and the offensive of September 2023 returned it all and ended with the expulsion of nearly all ethnic Armenians from Nagorno-Karabakh.","Oil and gas from the Azeri–Chirag–Guneshli and Shah Deniz fields, carried west by the Baku–Tbilisi–Ceyhan pipeline from 2006, raised GDP twenty-fold between 1995 and 2012 while the New Azerbaijan Party kept power from 1993."],dyk:"Nearly half of all the mud volcanoes on Earth are concentrated in Azerbaijan, and at Yanar Dag on the Absheron Peninsula a natural gas fire blazes continuously on a hillside, which is why Baku is known as the 'land of fire'.",ev:[["1991","The Supreme Council of Azerbaijan adopts a Declaration of Independence on 18 October, affirmed by a nationwide referendum in December."],["1993","President Abulfaz Elchibey is overthrown by a military insurrection led by Colonel Surat Huseynov, which brings Heydar Aliyev to power."],["1994","The First Nagorno-Karabakh War ends with Armenians holding 14–16 percent of Azerbaijani territory; in September SOCAR signs a 30-year contract with 13 oil companies."],["1995","The constitution is adopted on 12 November, completing the formation of the political system."],["2003","Ilham Aliyev succeeds his father Heydar as President and chairman of the New Azerbaijan Party."],["2006","The Baku–Tbilisi–Ceyhan pipeline becomes operational in May, carrying Caspian oil to Turkey and world markets; the new manat is launched on 1 January."],["2020","The Second Nagorno-Karabakh War, six weeks from 27 September, ends in a ceasefire that returns the seven districts and parts of Nagorno-Karabakh to Azerbaijani control."],["2023","An offensive in September ends the Republic of Artsakh, dissolved on 1 January 2024, and nearly all ethnic Armenians are expelled from Nagorno-Karabakh."]]},
  "Armenia": {t:["Armenia declared its statehood on 21 September 1991 after the failed August coup in Moscow, and the Soviet Union's dissolution in December recognised its independence.","The First Nagorno-Karabakh War ended in a Russian-brokered ceasefire in 1994 with Armenian-backed forces holding almost the whole former autonomous oblast and most of seven adjacent districts, which they kept until the six-week war of 2020.","Azerbaijan's offensive of 19–20 September 2023, after a blockade that starved Artsakh of food and medicine, drove almost its entire Armenian population of about 139,000 into Armenia."],dyk:"A cuneiform inscription found in Yerevan records that the city was founded in the summer of 782 BCE by King Argishti I of Urartu, making the capital of the republic one of the world's oldest continuously inhabited cities.",ev:[["1991","Armenia declares its statehood on 21 September after the failed August coup in Moscow; Levon Ter-Petrosyan is elected the first president in October."],["1993","Turkey joins Azerbaijan's railway and air blockade of Armenia; the new currency, the dram, is introduced and suffers hyperinflation."],["1994","A Russian-brokered ceasefire ends the First Nagorno-Karabakh War, with some 30,000 dead and over a million displaced."],["2009","Armenia and Turkey sign protocols on 10 October to normalise relations and reopen their border, but they are never ratified."],["2018","Protests from April to May, the 'velvet revolution', force Serzh Sargsyan's resignation; parliament elects Nikol Pashinyan prime minister in May."],["2020","On 27 September Full-scale war erupts over Nagorno-Karabakh; the ceasefire after six weeks is seen by many as Armenia's defeat and capitulation."],["2023","Azerbaijan's offensive of 19–20 September ends the Republic of Artsakh, and almost its entire Armenian population flees to Armenia."],["2025","Parliament approves a bill endorsing EU accession on 12 February; on 8 August Pashinyan and Ilham Aliyev sign a joint declaration committing to a peace deal."]]},
  "Georgia": {t:["The Supreme Council declared independence on 9 April 1991 after a referendum on 31 March, making Georgia the first non-Baltic Soviet republic to do so; its first president, Zviad Gamsakhurdia, was deposed in a coup within the year and civil war lasted until December 1993.","Abkhazia and South Ossetia won de facto independence with Russian support in the wars of the early 1990s, when 230,000 to 250,000 Georgians were expelled from Abkhazia; after the war of August 2008 Russia recognised both, and Georgia regards them as occupied territory.","The Rose Revolution of 2003 turned a near-failed state into a market economy that the World Bank called the world's number one reformer, and the European Union made Georgia a candidate in December 2023, before the ruling Georgian Dream party paused accession in 2024."],dyk:"Georgia hosts the world's earliest known sites of winemaking, dating to about 6000 BCE, and the Georgian folk song 'Chakrulo' was one of 27 pieces of music carried into space on the Voyager Golden Records launched on 20 August 1977.",ev:[["1991","The Supreme Council declares independence on 9 April after the referendum of 31 March; Zviad Gamsakhurdia is elected president on 26 May with 86.5 percent."],["1993","The civil war that began with the coup against Gamsakhurdia ends in December; Abkhaz separatists and North Caucasian militants expel some 230,000 to 250,000 Georgians from Abkhazia."],["1995","A new constitution is adopted and Eduard Shevardnadze, head of state since 1992, is elected president."],["2003","The Rose Revolution led by Mikheil Saakashvili, Zurab Zhvania and Nino Burjanadze deposes Shevardnadze after the fraudulent elections of 2 November."],["2008","Russia invades on 8 August after fighting in South Ossetia; a ceasefire follows on 12 August, and on 26 August Russia recognises Abkhazia and South Ossetia as independent."],["2012","Georgian Dream defeats Saakashvili's United National Movement in the first peaceful electoral transfer of power, as the state becomes a parliamentary republic."],["2023","The European Council grants Georgia candidate status for EU membership in December, despite unfulfilled conditions."],["2024","The disputed election of 26 October and the suspension of EU accession until 2028 plunge the country into crisis; the outgoing president Salome Zourabichvili refuses to recognise her successor."]]},
  "Uzbekistan": {t:["Uzbekistan declared independence on 31 August 1991 after the failed coup in Moscow, and Islam Karimov, Communist first secretary since 1989, ruled it as an authoritarian president until his death in September 2016.","The economy rests on commodities: in 2011 Uzbekistan was the world's seventh-largest producer and fifth-largest exporter of cotton and its seventh-largest gold producer, while Soviet-era plants and ample gas make it the largest electricity producer in Central Asia.","Shavkat Mirziyoyev, president from December 2016, made the currency fully convertible in September 2017, abolished Soviet-style exit visas and mended relations with every neighbour, though V-Dem still classed the state a closed autocracy in 2024."],dyk:"Uzbekistan is one of only two doubly landlocked countries in the world, the other being Liechtenstein: none of its rivers reaches the sea, and the Aral Sea on its northern edge, once the fourth-largest inland sea on Earth, has shrunk to about a tenth of its former area since the 1960s.",ev:[["1991","Uzbekistan declares independence on 31 August after the failed coup in Moscow; Islam Karimov is elected president on 29 December."],["1994","The Oliy Majlis replaces the Supreme Soviet, the Republican Stock Exchange opens and Uzbekistan applies to join the World Trade Organization."],["2001","After the 11 September attacks Uzbekistan grants the United States access to the Karshi-Khanabad airfield for operations in Afghanistan."],["2005","Government troops fire into crowds of protesters in Andijan, killing 187 by official count and several hundred by witness accounts; the United States is ordered to leave Karshi-Khanabad."],["2011","The Afrosiyob high-speed train between Tashkent and Samarkand, the first in Central Asia, makes its first trip on 26 August."],["2016","Karimov dies on 2 September; Prime Minister Shavkat Mirziyoyev is elected president with 88.6 percent of the vote and sworn in on 14 December."],["2017","In September the som becomes fully convertible at market rates, ending the chief barrier to foreign business."],["2020","The United Nations announces 'major progress' against forced labour in the cotton harvest, with 94 percent of pickers working voluntarily."]]},
  "Republic of Egypt": {t:["The Free Officers' coup of 22–23 July 1952 ended the monarchy, and on 18 June 1953 Egypt was declared a republic with Muhammad Naguib as president and Gamal Abdel Nasser as prime minister; Nasser took the presidency in 1956.","Egypt fought Israel in 1948, 1956, 1967 and 1973, lost the Sinai Peninsula and the Gaza Strip in the Six-Day War, and under Anwar Sadat made peace in 1979, regaining Sinai by 1982 at the cost of expulsion from the Arab League.","The revolution of 25 January 2011 toppled Hosni Mubarak after thirty years, but the military removed the elected president Mohamed Morsi on 3 July 2013, and Abdel Fattah el-Sisi has ruled since, winning a third six-year term in December 2023."],dyk:"Egypt has the oldest continuous parliamentary tradition in the Arab world: its first popular assembly met in 1866, and the Suez Canal, opened in 1869, still earned the state a record $9.4 billion in 2023.",ev:[["1953","On 18 June the monarchy is abolished and Egypt declared a republic, with Muhammad Naguib as president and Gamal Abdel Nasser as prime minister."],["1956","Nasser becomes president in June, the last British troops leave the Canal Zone on 13 June, and on 26 July he nationalises the Suez Canal, provoking the Suez Crisis."],["1967","In the Six-Day War Israel captures the Sinai Peninsula and the Gaza Strip; an Emergency Law expanding police powers is enacted and stays in force until 2012."],["1973","Sadat coordinates with Syria in the Fourth Arab-Israeli War to reclaim Sinai, restoring Arab morale and his own legitimacy."],["1979","The Egypt–Israel peace treaty is signed after Sadat's 1977 visit to Jerusalem; Egypt is temporarily expelled from the Arab League."],["1981","Sadat is assassinated by an Islamic extremist; Hosni Mubarak succeeds him in a referendum in which he is the sole candidate."],["2011","After 18 days of protests centred on Tahrir Square, Mubarak resigns on 11 February and the military takes control."],["2013","The military removes President Mohamed Morsi on 3 July; the dispersal of pro-Morsi camps on 14 August kills 595, the deadliest day in modern Egyptian history."]]},
  "Kingdom of Morocco": {t:["Morocco regained its independence from France in March 1956 and from Spain a month later, and Sultan Mohammed V became King in 1957; the Alawi dynasty that had seized power in 1631 still reigns.","Under Hassan II (1961–1999) a truth commission later confirmed nearly 10,000 cases of abuse, from death in detention to forced exile, in the 'Years of Lead'; in 1975 his Green March sent 350,000 civilians into the Spanish Sahara, which Morocco has occupied ever since.","Mohammed VI answered the protests of 2011 with a new constitution, rejoined the African Union in 2017 and normalised relations with Israel in 2020 in exchange for American recognition of Moroccan sovereignty over Western Sahara."],dyk:"Morocco was the first nation to recognise the United States, when Sultan Mohammed III placed American merchant ships under his protection on 20 December 1777, and the Moroccan–American Treaty of Friendship of 1786 is the United States' oldest unbroken friendship treaty.",ev:[["1957","Sultan Mohammed V, restored from exile in 1955 and sovereign of an independent Morocco since March 1956, takes the title of King."],["1961","Hassan II becomes King on 3 March; he holds the first general elections in 1963, then declares a state of emergency and suspends parliament in 1965."],["1975","On 6 November some 350,000 civilians cross into the Spanish Sahara in the Green March; Spain cedes the territory to Morocco and Mauritania and Moroccan forces occupy it."],["1991","A UN-monitored ceasefire ends fifteen years of war with the Polisario Front in Western Sahara, leaving the territory's status undecided."],["1999","Hassan II dies and is succeeded by his son Mohammed VI, who sets up the Equity and Reconciliation Commission to examine his father's abuses."],["2011","Thousands rally for reform during the Arab Spring; the King wins a landslide in a July referendum on a new constitution, and the Justice and Development Party's Abdelilah Benkirane heads the government."],["2020","On 10 December Morocco normalises relations with Israel, and the United States becomes the first Western state to back Moroccan sovereignty over Western Sahara."],["2026","After the general election of 23 September, Fatima Ezzahra El Mansouri is appointed the first woman prime minister on 29 September."]]},
  "Islamic Republic of Pakistan": {t:["Pakistan was created on 14 August 1947 by the partition of British India, in riots that killed between 200,000 and 2,000,000 people and the largest migration in history; it adopted a republican constitution in 1956 and became an Islamic republic of two provinces, East and West Pakistan.","East Pakistan seceded as Bangladesh in 1971 after a nine-month war in which independent researchers estimate 300,000 to 500,000 civilians died; the loss drove Pakistan to build the nuclear weapons it tested in 1998, the seventh state to do so.","Military coups in 1958, 1977 and 1999 put generals in power for three long stretches, and the first transfer from one elected government to another came only in May 2013."],dyk:"The name Pakistan was coined in January 1933 by the activist Choudhry Rahmat Ali in a pamphlet, Now or Never, as an acronym of Panjab, Afghania, Kashmir, Sindh and Baluchistan; in Persian and Urdu it also means 'the land of the pure'.",ev:[["1956","Pakistan adopts a republican constitution and becomes an Islamic republic with two geographically separate provinces, East Pakistan and West Pakistan."],["1958","President Iskander Mirza imposes martial law and is succeeded by General Ayub Khan, who suspends the constitution; a presidential constitution follows in 1962."],["1971","After the military refuses to transfer power to the Awami League and launches Operation Searchlight, war with India ends in defeat and East Pakistan becomes Bangladesh."],["1977","A military coup against Zulfikar Ali Bhutto's Pakistan Peoples Party ends democracy; General Zia-ul-Haq becomes president in 1978 and Islamises law and the economy."],["1998","Nawaz Sharif authorises nuclear tests in answer to India's, making Pakistan the seventh nuclear-armed state."],["1999","The Kargil War brings Pakistan and India to the brink, and General Pervez Musharraf takes power in a bloodless coup."],["2008","After Benazir Bhutto's assassination in 2007 the Pakistan Peoples Party wins the election; Musharraf resigns on 18 August and Asif Ali Zardari succeeds him."],["2013","The Pakistan Muslim League (N) wins the general election and Nawaz Sharif becomes prime minister for the third time, in the first successful democratic transition."]]},
  "Singapore": {t:["Singapore joined the Federation of Malaysia on 16 September 1963 and was expelled from it two years later: on 9 August 1965 the Malaysian Parliament voted 126 to 0 to separate it, leaving a city-state without a hinterland.","Growth averaged about 6 percent a year from 1965 to 1995 and about 8 percent through the 1980s and 1990s, making Singapore one of the Four Asian Tigers, the only Asian state with a AAA rating from all the major agencies and the country with the highest PPP-adjusted GDP per head in the world.","The People's Action Party has won every election since 1959; the Workers' Party took 10 of 93 seats in 2020, when Pritam Singh became the first de jure leader of the opposition, and Lawrence Wong, the first prime minister born after independence, took office on 15 May 2024."],dyk:"At independence Singapore had only two infantry regiments commanded by British officers, so the government asked commanders of the Israel Defense Forces to build the Singapore Armed Forces from scratch; its conscription and reserve system still follows the Israeli model.",ev:[["1965","Expelled from Malaysia, Singapore becomes an independent republic on 9 August, with Lee Kuan Yew as prime minister and Yusof bin Ishak as president."],["1967","Singapore co-founds the Association of Southeast Asian Nations and begins interchanging its dollar at par with Brunei's."],["1971","Britain withdraws its forces in October, leaving a token British, Australian and New Zealand presence; the Singapore Armed Forces, built with Israeli instructors, must guarantee independence."],["1981","Changi Airport opens, replacing Paya Lebar, as the Port of Singapore grows into one of the world's busiest and the economy turns to high-technology industry."],["1990","Goh Chok Tong succeeds Lee Kuan Yew as prime minister after 31 years; Nominated Members of Parliament are introduced the same year."],["2004","Lee Hsien Loong, Lee Kuan Yew's eldest son, becomes the third prime minister."],["2015","Lee Kuan Yew dies on 23 March and the nation mourns for a week; in September the PAP wins 69.9 percent of the vote."],["2024","Lawrence Wong becomes the fourth prime minister on 15 May, the first born after independence; his party wins 65.5 percent and 87 of 97 seats in 2025."]]},
  "Kingdom of Bhutan": {t:["Ugyen Wangchuck, penlop of Trongsa, united Bhutan after the civil wars of 1882–85 and in 1907 was unanimously chosen hereditary king by an assembly of monks, officials and leading families.","The Treaty of Punakha (1910) and the 1949 treaty with India placed Bhutan's foreign relations under British, then Indian, guidance; the revised treaty that took effect on 1 January 2011 ended that arrangement.","Between 1988 and the early 1990s the census, citizenship and 'One Nation, One People' policies led to the forcible deportation of some 107,000 Nepali-speaking Lhotshampas, about one-sixth of the population."],dyk:"Bhutan lifted its ban on television and the internet only in 1999, making it one of the last countries to introduce television; the king called it a step to modernisation but warned that its 'misuse' could erode traditional values.",ev:[["1907","Ugyen Wangchuck is unanimously chosen hereditary king of Bhutan by the Lhengye Tshog of leading monks, officials and heads of families."],["1910","The Treaty of Punakha gives Britain control of Bhutan's foreign affairs, making the kingdom in effect a British protectorate."],["1949","A treaty signed with newly independent India on 8 August continues the arrangement, India guiding Bhutan's external relations."],["1953","King Jigme Dorji Wangchuck establishes a 130-member National Assembly, followed by a Royal Advisory Council (1965) and a Cabinet (1968)."],["1971","Bhutan is admitted to the United Nations after three years as an observer and is the first country to recognise Bangladesh's independence."],["1988–1992","A census in southern Bhutan and the 'One Nation, One People' policy lead to the denationalisation and forcible deportation of some 107,000 Lhotshampas."],["2008","The first parliamentary elections are held, the Constitution establishes a parliamentary government, and Jigme Khesar Namgyel Wangchuck is crowned on 6 November."],["2011","The revised Indo-Bhutan Friendship Treaty comes into effect on 1 January, giving Bhutan full control of its foreign relations."]]},
  "East Timor": {t:["Indonesia invaded on 7 December 1975, nine days after Fretilin's declaration of independence; the occupation that followed caused at least 102,800 conflict-related deaths between 1974 and 1999, by one estimate as many as 200,000.","A UN-supervised referendum in August 1999 voted clearly for independence, met by a punitive campaign of violence by pro-integration militias backed by elements of the Indonesian military, before UNTAET took over the territory on 25 October 1999.","Timor-Leste became independent on 20 May 2002; its Petroleum Fund, set up in 2005, received $23 billion from oil sales by 2021 and funds 80% of government spending, but is at risk of exhaustion as the Bayu-Undan field runs out."],dyk:"Timor-Leste's name means 'East East': Timor comes from timur, 'east' in Indonesian or Malay, and Leste is 'east' in Portuguese. In Tetun the country is Timór Lorosa'e, 'where the sun rises'.",ev:[["1975","On 28 November Fretilin unilaterally declares independence; nine days later, on 7 December, the Indonesian military invades East Timor."],["1991","The Indonesian military massacres more than 200 demonstrators, a turning point that brings international pressure on Indonesia."],["August 1999","A UN-supervised referendum votes clearly for independence; pro-integration militias backed by the Indonesian military answer with a campaign of violence, and INTERFET lands to restore order."],["2002","On 20 May the Constitution comes into force and Timor-Leste is recognised as independent by the UN, with Xanana Gusmão as its first president; it joins the UN on 27 September."],["2005","The Timor-Leste Petroleum Fund is established to turn oil and gas revenue into lasting wealth."],["2006","A crisis of unrest and factional fighting drives 155,000 people from their homes; UN security forces return to restore order."],["2018","Timor-Leste and Australia settle their maritime boundary by treaty after conciliation before the Permanent Court of Arbitration."],["2025","ASEAN announces that Timor-Leste will be admitted as its 11th full member at the October summit in Kuala Lumpur."]]},
  "Rwanda": {t:["Germany (1897) and Belgium (1916) ruled through the Tutsi king and treated Hutu and Tutsi as different races; Belgium's identity cards of 1935 fixed the labels, and the Hutu revolution of 1959 drove over 100,000 Tutsi into exile before independence on 1 July 1962.","Between 500,000 and 1,000,000 Tutsi and moderate Hutu were killed in about 100 days from 6 April 1994 in attacks planned and ordered by the interim government; the RPF's military victory in July ended the genocide.","Under the RPF and Paul Kagame, president since 2000, poverty fell from 60.3% in 2000 to 27.4% in 2024 and the economy grew 9.4% in 2025, while elections are manipulated and Human Rights Watch documents detention, disappearances and torture."],dyk:"Rwanda joined the Commonwealth of Nations in 2009 as one of its few members with no historical link to the British Empire, and in 2008 it changed the medium of instruction in its schools from French to English.",ev:[["1959","The Rwandan Revolution: Hutu activists kill Tutsi and burn their houses, driving more than 100,000 people into neighbouring countries."],["1962","On 1 July Rwanda, separated from Burundi after a 1961 referendum abolished the monarchy, becomes independent under President Grégoire Kayibanda."],["1973","Juvénal Habyarimana takes power in a military coup; pro-Hutu discrimination continues with less violence and more prosperity."],["1990","The Rwandan Patriotic Front, formed of Tutsi refugees, invades northern Rwanda from Uganda, beginning the Rwandan Civil War."],["1994","On 6 April Habyarimana's plane is shot down near Kigali; within hours the genocide begins, killing 500,000 to 1,000,000 Tutsi and moderate Hutu in about 100 days."],["July 1994","The RPF takes control of the whole country, ending the genocide; some two million Hutu flee to Zaïre and other neighbours."],["2000","Paul Kagame, the RPF's former commander, becomes president; a constitution follows in 2003 after a national referendum."],["2025","On 25 January the Democratic Republic of the Congo severs diplomatic relations over Rwanda's support for the M23 rebellion after the Goma offensive."]]},
  "Republic of Haiti": {t:["Haiti, independent since 1 January 1804 as the only state established by a slave revolt, paid France 150 million francs (reduced to 90 million in 1838) for recognition; by 1900 debt repayment took 80% of government spending, and the debt was not cleared until 1947.","US Marines occupied Haiti from July 1915 to 1934, imposing a constitution that allowed foreign land ownership and building roads by forced labour; the Duvaliers (1957–1986) ruled by terror through the Tontons Macoutes, killing an estimated 40,000 to 60,000 people.","The earthquake of 12 January 2010 killed between 160,000 and 316,000 people; since the assassination of President Jovenel Moïse on 7 July 2021 the presidency has been vacant, gangs control most of Port-au-Prince and no elected official remains."],dyk:"The constitution written for Haiti under US occupation in 1915, which for the first time allowed foreigners to own land in the country, was drafted by the future US president Franklin D. Roosevelt.",ev:[["1859","On 15 January Emperor Faustin Soulouque abdicates after General Fabre Geffrard's revolution and the republic is restored, with Geffrard as president."],["July 1915","After President Vilbrun Guillaume Sam's execution of 167 prisoners and his lynching, US Marines land at Port-au-Prince; the occupation lasts until 1934."],["1937","Dominican dictator Rafael Trujillo's army bludgeons and bayonets 20,000–30,000 Haitians on the border in the Parsley Massacre."],["September 1957","François 'Papa Doc' Duvalier is elected president; he rules by terror until his death in 1971 and is followed by his son until 1986."],["February 1986","Jean-Claude 'Baby Doc' Duvalier leaves the country under US pressure after nationwide demonstrations."],["September 1994","Operation Uphold Democracy: 20,000 US troops enter Haiti and Jean-Bertrand Aristide, overthrown by Raoul Cédras's coup of 1991, is restored."],["2010","On 12 January a magnitude-7.0 earthquake kills between 160,000 and 316,000 people and leaves up to 1.6 million homeless; a cholera outbreak from a UN base follows."],["2021","On 7 July President Jovenel Moïse is assassinated at his residence; the presidency has remained vacant and the state has since collapsed."]]},
  "Oriental Republic of Uruguay": {t:["Uruguay became independent by the Treaty of Montevideo of 1828, brokered by Britain through Viscount John Ponsonby after the 500-day Cisplatine War between Brazil and the United Provinces of the Río de la Plata; its first constitution followed on 18 July 1830.","The Colorados and the Blancos fought the thirteen-year Guerra Grande (1839–1851), during which Montevideo was besieged for nine years and Garibaldi led its Italian legion; their rivalry ended in a formula of co-participation after 1872.","José Batlle y Ordóñez's reforms (1903–1915) made Uruguay the 'Switzerland of the Americas'; a civic-military dictatorship (1973–1985) gave it the world's highest proportion of political prisoners before democracy returned in 1985."],dyk:"On 11 December 2013 Uruguay became the first country in the world to fully legalise the growth, use and sale of cannabis, by a Senate vote of 16 to 13, under President José Mujica, a former Tupamaro guerrilla who had spent almost fifteen years in prison.",ev:[["1828","The Treaty of Montevideo, fostered by Britain through Viscount John Ponsonby, ends the Cisplatine War and creates Uruguay as an independent state."],["1830","On 18 July the first constitution is adopted; the country is officially the Oriental State of Uruguay."],["1843–1851","The Guerra Grande: an Argentine army on Manuel Oribe's behalf besieges Montevideo for nine years until Brazilian intervention and Urquiza's rising defeat Oribe."],["1904","The last Blanco rising ends at the Battle of Masoller with the death of Aparicio Saravia; President José Batlle y Ordóñez's reforms follow."],["1933","Gabriel Terra dissolves the General Assembly in a coup and governs by decree; a new constitution of 1934 strengthens the presidency."],["1973","At President Juan María Bordaberry's request the armed forces disband Parliament and establish a civilian-military regime."],["1985","Julio María Sanguinetti takes office after the elections of 1984, restoring democracy and full freedom of the press."],["2013","On 11 December Uruguay becomes the first country to fully legalise cannabis, after legalising abortion in 2012 and same-sex marriage in 2013."]]},
  "Principality of Monaco": {t:["Francesco Grimaldi captured the fortress on the Rock of Monaco in 1297 with his men disguised as Franciscan friars; after a century of feud with Genoa the family bought Monaco outright from the Crown of Aragon in 1419, and Honoré II styled himself Prince in 1612.","In 1861 Charles III ceded Menton and Roquebrune, some 95% of the principality's territory, to France for 4,100,000 francs in exchange for recognition of Monaco's sovereignty; the Monte Carlo casino paid so well that income tax was abolished in 1869.","Monaco has the world's highest nominal GDP per head (US$185,742), 31% of its residents are millionaires, and fewer than 10,000 of its 38,423 inhabitants are Monégasque; France still provides its defence, and in June 2024 the FATF put it under increased monitoring for money laundering."],dyk:"Monégasque citizens are forbidden to enter the Monte Carlo casino unless they work there, a rule decreed so as not to overtax them; by 1869 the casino's earnings let the principality stop collecting income tax from its citizens altogether, a policy that still stands.",ev:[["1297","Francesco Grimaldi, 'Malizia', and his men dressed as Franciscan friars capture the fortress protecting the Rock of Monaco."],["1419","The Grimaldi family purchases Monaco from the Crown of Aragon and becomes its official and undisputed ruler."],["1612","Honoré II begins to style himself Prince of Monaco; Spain recognises his sovereignty in 1633 and Louis XIII of France by the Treaty of Péronne in 1641."],["1793","Revolutionary French forces capture Monaco, which remains occupied and annexed until the Grimaldi are restored in 1814."],["1861","The Franco-Monégasque Treaty recognises Monaco's sovereignty; Charles III cedes Menton and Roquebrune to France for 4,100,000 francs."],["1869","Flush with the casino's earnings, the principality stops collecting income tax from its residents."],["1911","The Monégasque Revolution of 1910 forces the first constitution on the hitherto absolute princes."],["1993","Monaco becomes a member of the United Nations with full voting rights."]]},
  "Western Xia": {t:["Li Yuanhao levied every man between 15 and 60, put as many as 370,000 under arms, promulgated the Tangut script in 1036 and in 1038 declared himself emperor of the Great Xia; after six years of war the Song recognised him and paid an annual tribute of 250,000 units of silk, silver and tea.","For most of the 11th century child emperors reigned under empress dowagers and their clans, the Mocang and then two generations of the Liang; Empress Dowager Liang rode at the head of the cavalry against the Song until she was poisoned by Liao assassins in 1099.","Western Xia pioneered printing with ceramic and wooden movable type, and under Emperor Renzong (1139–1193) founded schools, examinations and a Hanlin Academy and completed most of the Tangut Buddhist canon; the Mongols destroyed the state so thoroughly that its history stayed obscure until the 20th century."],dyk:"The Auspicious Tantra of All-Reaching Union, a 449-page Tangut text found in the ruins of the Baisigou Square Pagoda in the Helan Mountains, is the earliest surviving book printed with wooden movable type; twelve Tangut titles printed with movable type survive today.",ev:[["1038","Li Yuanhao declares himself emperor of the Great Xia at Xingqing, taking the Tangut clan name Weiming and creating a Chinese-style bureaucracy."],["1044","After victories at Sanchuan Pass and Haoshuichuan and the repulse of a Liao invasion of 100,000, Jingzong makes peace: the Song recognise him and pay 250,000 units of silk, silver and tea a year."],["1081","The Song launch a five-pronged invasion while the Liang clan imprisons Emperor Huizong; Lanzhou falls, but the Xia flood the Song camps by breaching the Yellow River dikes."],["1099","Empress Dowager Liang, who led armies in person, is poisoned by assassins from the Liao; the Song 'advance and fortify' campaign has built 40 forts across the Ordos."],["1124","Emperor Chongzong turns away the fugitive Liao emperor Tianzuo and declares himself a vassal of the Jurchen Jin."],["1147","Emperor Renzong institutes imperial examinations, after founding schools throughout the country and Confucian temples."],["1210","After the Mongol siege of Zhongxing, Emperor Xiangzong submits to Genghis Khan, giving him his daughter Chaka and a tribute of camels, falcons and textiles."],["September 1227","Emperor Mo surrenders after a six-month siege and is executed; the Mongols slaughter the capital's population and plunder the imperial tombs."]]},
  "Northern Wei": {t:["Tuoba Gui broke the Later Yan at the Battle of Canhe Slope in 395 and his successors conquered the Helian Xia, Northern Yan and, in 439, the Northern Liang, uniting the north and ending the Sixteen Kingdoms period.","Empress Dowager Feng's reforms of 485–486, the equal-field landholding system and the three-elders system, redistributed land against tax and labour obligations and registered the population, doubling the registered households to more than five million; the equal-field system lasted until the mid-8th century.","Emperor Xiaowen moved the capital to Luoyang in 494, changed the imperial surname to Yuan, encouraged marriage with Chinese families and abandoned Xianbei customs; the rift between this sinicised court and the steppe soldiers of the Six Garrisons brought the rebellions of 523 and the dynasty's collapse."],dyk:"A Northern Wei empress was chosen not by birth or imperial favour but by a ceremony in which the candidate had to forge a golden statue with her own hands; only a consort whose statue came out well could become empress.",ev:[["386","Tuoba Gui reasserts Tuoba independence as Prince of Dai and then Prince of Wei, as Former Qin breaks apart after the Battle of Fei River."],["395","Tuoba Gui inflicts a heavy defeat on the Later Yan crown prince Murong Bao at the Battle of Canhe Slope; the Central Plains are overrun and Yan splits in two."],["439","Emperor Taiwu conquers the Northern Liang in the Hexi Corridor, unifying northern China and ending the Sixteen Kingdoms period."],["450","Emperor Wen of Liu Song's great invasion is lured across the Yellow River and destroyed; Wei armies devastate the provinces to the south until January 451."],["485–486","Empress Dowager Feng introduces the equal-field landholding system and the three-elders system, breaking the local aristocrats' hold on the rural population."],["494","Emperor Xiaowen moves the capital from Pingcheng to Luoyang and pursues systematic sinicisation; the Tuoba take the surname Yuan."],["528","Empress Dowager Hu poisons the young Emperor Xiaoming; the warlord Erzhu Rong butchers some 2,000 courtiers in the Heyin massacre and throws her into the Yellow River."],["534–535","Emperor Xiaowu flees Gao Huan for Yuwen Tai's west; the dynasty splits into Eastern Wei and Western Wei."]]},
  "Qin dynasty": {t:["Beginning in 230 BCE, King Ying Zheng of Qin conquered Han, Zhao, Yan, Wei, Chu and Qi in turn, and in 221 BCE took the new title Shi Huangdi, 'First Emperor'.","The empire was divided into 36 commanderies and more than 1,000 districts run by appointed officials, ending aristocratic rule; the Han dynasty inherited this administrative state.","The dynasty's 14 years make it the shortest of any major Chinese dynasty, with only two emperors, yet it is credited with originating the imperial system that lasted until 1911."],dyk:"Qin is the likeliest origin of the name China: the term appears in Sanskrit as Cina and Sina, then in Greek as Thinai or Sinai, before entering the languages of Europe.",ev:[["230 BCE","Qin attacks the state of Han directly to its east and takes its capital city of Xinzheng, opening the wars of unification."],["221 BCE","Qin conquers Qi, taking its capital at Linzi, and King Zheng declares himself Shi Huangdi, the First Emperor."],["215 BCE","The general Meng Tian conquers the Ordos region from the Xiongnu and agriculture is established there."],["214 BCE","Some 500,000 men are sent south against the Baiyue peoples; after heavy losses, Qin takes the coastal lands around Guangzhou and the provinces of Fuzhou and Guilin."],["210 BCE","Qin Shi Huang dies on a journey to the eastern frontiers; Li Si and Zhao Gao hide his death, alter his will and place Huhai on the throne as Qin Er Shi."],["209 BCE","Popular revolt breaks out as men across China attack officials, raise armies and declare themselves kings."],["207 BCE","Ziying, a son of Fusu, surrenders to Liu Bang on his arrival at Xianyang and is soon executed by Xiang Yu."],["206 BCE","Xianyang is destroyed, marking the end of the imperial Qin dynasty; the Chu–Han Contention follows."]]},
  "Hunnic Empire": {t:["By 370 the Huns had reached the Volga; their conquest of the Alans and Goths drove thousands of Goths to seek refuge across the Lower Danube in 376.","Under Attila, sole ruler from 445, the Eastern Roman Empire agreed in 449 to pay an annual tribute of 2,100 pounds of gold; in 451 he invaded Gaul and in 452 Italy.","After Attila died in 453 the Gepid king Ardaric's Germanic coalition defeated his sons at the Battle of Nedao, and the last king Dengizich was killed in Thrace in 469."],dyk:"Only three words of the Hunnic language are recorded, all apparently Indo-European; everything else known of it comes from personal and tribal names, so the language is held by many to be unclassifiable.",ev:[["370","The Huns arrive on the Volga, setting the Goths and Alans moving westward."],["395","The Huns make their first large-scale attack on the Eastern Roman Empire, overrunning Armenia and pillaging Cappadocia and Thrace, and invade the Sasanian Empire, where they are badly defeated."],["435","The brothers Attila and Bleda force the Eastern Roman Empire to sign the Treaty of Margus, granting the Huns trade rights and an annual tribute."],["447","Attila, sole ruler since Bleda's death in 445, invades the Balkans and Thrace; the war ends in 449 with a tribute of 2,100 pounds of gold a year."],["451","Attila's forces enter Gaul, attack Metz and besiege Orléans; a combined Roman and Visigothic army fights them at the Battle of the Catalaunian Plains."],["453","Attila dies of a haemorrhage on his wedding night, having sacked northern Italy the year before and met Pope Leo I near Mantua."],["454","At the Battle of Nedao the Gepid king Ardaric leads a Germanic coalition against Attila's son Ellak; the Huns lose many of their Germanic vassals."],["469","Dengizich is defeated and killed in Thrace; the Huns are absorbed by other peoples such as the Bulgars."]]},
  "Hephthalite Empire": {t:["The Hephthalites, who called themselves Ebodalo on their coins, were militarily important from 450, when they defeated the Kidarites, to 560, when the First Turkic Khaganate and the Sasanian Empire destroyed them.","Peroz I fought three wars against them from 474: captured and ransomed twice, he was defeated and killed at the Battle of Herat in 484, and the Sasanians paid tribute until the 530s.","They were a tribal confederation of nomadic and settled communities who adopted the Bactrian language, took Sasanian coin designs, and ruled a largely Iranian population through local rulers."],dyk:"Polyandry was the Hephthalites' most noted custom: brothers shared one wife, whose children belonged to the eldest, and the number of horns on a married woman's headdress showed how many husbands she had.",ev:[["456","The first Hephthalite embassy reaches the Chinese court of the Northern Wei; twenty-four embassies to China are recorded in all, the last in 558."],["458","The Hephthalite king Akhshunwar helps Peroz I gain the Sasanian throne from his brother."],["474","Peroz I begins three wars against his former allies; captured in the first two, he pays thirty mules loaded with silver drachms and leaves his son Kavad as a hostage."],["484","At the Battle of Herat Peroz I is defeated and killed by the Hephthalite king Kun-khi; for two years the Hephthalites plunder and control the eastern Sasanian Empire."],["488","A Hephthalite army defeats the Sasanian army of Balash and places Kavad I, who had lived four years among the Hephthalites, on the throne."],["509","The Hephthalites capture Sughd, the capital of Sogdiana, and push north of Turfan to the Urumchi region in the Tarim Basin."],["516","King Yilituo Yandai sends the first Hephthalite ambassador to the Southern Liang court, recorded in the Portraits of Periodical Offering of Liang."],["557","The Turks of the First Turkic Khaganate and the Sasanians under Khosrow I defeat the Hephthalites after an eight-day battle near Qarshi, the Battle of Gol-Zarriun; the empire breaks into principalities."]]},
  "Uyghur Khaganate": {t:["In 744 a Uyghur–Karluk alliance destroyed the Basmyls who had taken the Göktürk capital, and Kutlug I Bilge Khagan claimed supreme rule over all the tribes from a new capital at Ordu-Baliq.","Uyghur horsemen helped the Tang retake Chang'an and Luoyang from An Lushan's rebels in 757 and again in 762, looting Luoyang each time and extracting silk, titles, a fixed horse trade and royal marriages.","After Bögü Qaghan's conversion in 762 Manichaeism became the official religion, binding the khaganate to the Sogdian merchants who ran its Silk Road trade."],dyk:"In 762 the Uyghurs sacking Luoyang burnt down the Buddhist temples in which the people had taken refuge, killing more than 10,000; the Tang then paid 100,000 pieces of silk to make their allies leave.",ev:[["744","The Basmyls capture Ötüken and kill Özmiş Khagan; a Uyghur–Karluk alliance then destroys the Basmyls, and Kutlug I Bilge Khagan builds his capital at Ordu-Baliq."],["745","The Uyghurs kill Kulun Beg, the last khagan of the Göktürks, and send his head to the Tang."],["757","About 4,000 Uyghur horsemen under Bayanchur Khan's eldest son help Tang armies retake Chang'an and Luoyang; the Uyghurs loot Luoyang for three days."],["762","Bögü Qaghan helps defeat the rebels at Luoyang, sacks the city, and is converted by Manichaean priests; Manichaeism becomes the official religion."],["779","Tun Baga Tarkhan kills his nephew Bögü Qaghan and nearly two thousand of his family, clique and Sogdians, takes the throne and suppresses Manichaeism."],["792","Baoyi Qaghan defeats the Tibetans and Karluks and takes Gaochang; a Tibetan force besieging Yushu is destroyed."],["795","Qutluq Bilge Qaghan dies and the Yaghlakar dynasty ends; the general Qutluq II declares himself qaghan, founding the Ädiz dynasty."],["840","Invited by the minister Kulug Bagha, some 80,000 Yenisei Kyrgyz horsemen sack Ordu-Baliq, behead Qasar Qaghan and burn the empire's cities."]]},
  "Qara Khitai": {t:["Yelü Dashi fled the Jin conquest of the Liao in 1124 with the 20,000 troops of the Kedun garrison, took Balasaghun in 1134 and made the Kingdom of Qocho, the Karluks and the Karakhanids his vassals.","At the Battle of Qatwan on 9 September 1141 the Khitans encircled and destroyed the Seljuk army of Ahmad Sanjar north of Samarkand, winning all of Transoxiana and Khwarazm's tribute.","The state called itself the Great Liao, kept the Chinese calendar, titles, coins and seals, and was ruled by two empresses in its own right, Xiao Tabuyan and Yelü Pusuwan."],dyk:"In 1146 a Jin envoy refused to dismount before the regent Xiao Tabuyan and demanded she bow to the Son of Heaven; she had him executed, and the Jin learned his fate only in 1175 from deserters.",ev:[["1124","Yelü Dashi flees north-west to the garrison of Kedun on the Orkhon River, wins the allegiance of its 20,000 troops and proclaims himself gurkhan."],["1134","Dashi conquers the Karakhanid city of Balasaghun; the Kankalis, Karluks, Kyrgyz and the Kingdom of Qocho become vassals, while a Khitan attack on the Jin ends in disaster."],["1141","On 9 September the Khitans destroy Ahmad Sanjar's Seljuk army at the Battle of Qatwan north of Samarkand; Transoxiana is lost to the Seljuks and Khwarazm becomes a vassal."],["1143","Yelü Dashi dies; his wife Xiao Tabuyan rules as regent with the titles of empress Gantian, Gurkhan and Dashi."],["1172","The Qara Khitai cross the Amu Darya to defeat Khwarazm for unpaid tribute and install Tekish as Khwarazm Shah on 11 December."],["1198","A Qara Khitai army invading Ghurid lands near Kurzuban is routed in a night attack with 12,000 losses; Balkh passes to the Ghurids."],["1211","The Naiman refugee Kuchlug, married to Yelü Zhilugu's daughter, revolts and captures the gurkhan while he is hunting; Zhilugu remains nominal ruler until his death two years later."],["1218","Pursued by Genghis Khan's general Jebe, Kuchlug is captured and decapitated; the Mongols complete the conquest of the former Qara Khitai lands by 1220."]]},
  "Durrani Empire": {t:["In June 1747, after Nader Shah Afshar's death, a nine-day loya jirga near Kandahar chose Ahmad Khan of the Sadozai as Shah, and he renamed his Abdali tribe Durrani.","Ahmad Shah invaded India eight times, sacked Delhi in 1757 and on 14 January 1761 decisively defeated the Marathas at the Third Battle of Panipat, the high point of Afghan power.","His successors fought one another for the throne; by 1818 the Sadozai held little more than Kabul and its surroundings, and in 1823 the Barakzai displaced them."],dyk:"When Ahmad Shah's envoy Khwaja Mirhan reached Beijing in 1763 he refused to kowtow to the Qianlong Emperor; the Qing read it as a claim of equality and cut ties with the Afghans, though the envoy himself was shown favour.",ev:[["1747","After Nader Shah Afshar's death in June, a loya jirga near Kandahar lasting nine days chooses Ahmad Khan, crowned Padshah, Durr-i-Durran, by the holy man Sabir Khan."],["1749","The Mughal Emperor Ahmad Shah Bahadur cedes Sindh, the Punjab and the trans-Indus lands to Ahmad Shah to save his capital from attack."],["1757","Ahmad Shah sacks Delhi but leaves the Mughal emperor in nominal control in return for recognising Afghan suzerainty over Punjab, Sindh and Kashmir."],["1761","On 14 January the Durranis decisively defeat the Marathas under Sadashivrao Bhau at the Third Battle of Panipat, fought along a twelve-kilometre front."],["1762","Ahmad Shah crosses into Punjab for the sixth time, takes Amritsar, massacres thousands of Sikhs in the Vadda Ghallughara and destroys the Golden Temple."],["1772","Ahmad Shah dies in the mountains east of Kandahar; after Shah Wali Khan is assassinated at Farah, Timur Shah takes the throne in November."],["1809","On 7 June Shuja Shah signs the first Afghan pact with a European power, with the British East India Company; weeks later Mahmud Shah deposes him."],["1823","Ayub Shah, the last Sadozai ruler of the empire, is deposed and presumably killed."]]},
  "Sui Dynasty": {t:["In 589 Sui troops entered Jiankang and the last Chen emperor surrendered, ending the Northern and Southern dynasties period and reuniting China proper.","The Sui built the Grand Canal, extended the Great Wall and rebuilt Luoyang as a planned capital, conscripting millions of workers at a heavy human cost.","Four expeditions against Goguryeo all failed by 614, and the dynasty disintegrated amid revolts that ended with Emperor Yang's assassination in 618."],dyk:"The Sui army massed against Goguryeo was so large that the histories record it took 30 days for all its units to leave their rallying point near Shanhaiguan, and it stretched over about 410 kilometres.",ev:[["581","Yang Jian, regent for the child Emperor Jing of Northern Zhou, usurps the throne as Emperor Wen and names his dynasty Sui, after a bloody purge of 59 Zhou princes."],["588","The Sui amass 518,000 troops along the northern bank of the Yangtze River, from Sichuan to the East China Sea, against the Chen dynasty."],["589","Sui troops enter Jiankang and the last emperor of Chen surrenders; the city is razed and China proper is reunified."],["601","Emperor Wen has relics of the Buddha distributed to temples throughout China, presenting himself as a Cakravartin king in imitation of Ashoka."],["602","The Sui retake the Hanoi area from the Early Lý ruler Lý Phật Tử, opening the Linyi-Champa Campaign of 602–605."],["605","Emperor Yang moves the capital to Luoyang, re-founded as a planned city, and enormously enlarges the Grand Canal works."],["614","The last of four massive expeditions against Goguryeo ends in failure, leaving a deficit of money and men from which the Sui never recover."],["618","Emperor Yang is assassinated by the minister Yuwen Huaji; in the north Li Yuan rises and takes the throne as Emperor Gaozu of Tang."]]},
  "Manchukuo": {t:["Historians consider Manchukuo a puppet state: Japanese vice-ministers made every decision, the Kwantung Army commander was also ambassador with a veto over the emperor, and Puyi was a figurehead.","The Kwantung Army used more than ten million Chinese civilians as slave labour, Unit 731 vivisected prisoners near Harbin, and Special Security Courts sentenced thousands to death for 'thought crimes'.","Only Japan's allies and dependents recognised the state; the League of Nations endorsed the Lytton Report against it in February 1933 and Japan left the League."],dyk:"The Tokyo tribunal found that Japan used the 'alleged but false independence of Manchukuo' to run a worldwide drug traffic; in 1937 the League of Nations was told that 90 per cent of the world's illicit white drugs were of Japanese origin.",ev:[["1932","After the Mukden incident and the Japanese invasion of Manchuria in 1931, Manchukuo is proclaimed on 18 February and formally established at Xinjing on 1 March, with Puyi as nominal head of state."],["1932","On 15 September Japan recognises the state through the Japan–Manchukuo Protocol; the Manchukuo Imperial Army is founded by the Army and Navy Act of 15 April."],["1933","The League of Nations endorses the Lytton Report in February, finding Japan had broken international law; Japan withdraws from the League."],["1934","On 1 March Manchukuo is proclaimed a monarchy and Puyi takes the throne with the era name Kangde; El Salvador, the Dominican Republic and Costa Rica recognise the state."],["1936","Five Year Plans modelled on the Soviet Union's begin; Nobusuke Kishi, deputy minister since 1935, brings the zaibatsu into a state-directed heavy industry."],["1937","Manchukuo serves as the base for Japan's invasion of the rest of China after the Marco Polo Bridge incident; 'thought crime' is introduced and an emergency law mobilises society for total war."],["1939","A border skirmish between Manchukuoan and Mongolian cavalry in May escalates into the Battles of Khalkhin Gol, where a Soviet–Mongolian force defeats the Kwantung Army."],["1945","The Soviet Union declares war on 8 August and invades; Manchukuo units surrender or mutiny, Puyi abdicates on 17 August and is captured by the Soviets."]]},
  "Ur": {t:["The Royal Cemetery of Ur, most of whose royal tombs date to about 2600 BCE, held gold and semi-precious stones brought from Iran, Afghanistan, India, Asia Minor, the Levant and the Persian Gulf, and attendants killed to accompany their rulers.","Sargon of Akkad made his daughter Enheduanna high priestess of Nanna at Ur, and control of that priesthood remained a symbolic marker of political control over the region for five centuries.","Ur-Nammu, governor of Ur under Utu-hengal of Uruk, made the city the seat of a new kingdom, built its ziggurat and issued the Code of Ur-Nammu, one of the oldest law codes known."],dyk:"Woolley believed the attendants in the royal tombs had gone willingly to their deaths; CT scans of surviving skulls show they were killed by blows to the head, perhaps from the spiked end of a copper axe.",ev:[["c. 2600 BCE","The royal tombs of the Royal Cemetery are built, among them the unlooted tomb of Queen Puabi, with the Standard of Ur and the Lyres of Ur among their treasures."],["26th century BCE","Mesannepada, the first king of Ur recorded in the Sumerian King List, rules; a cylinder bearing his name was found in the Royal Cemetery."],["25th century BCE","Ur comes under the control of Eannatum of Lagash, whose successor Enannatum I leaves memorials there."],["c. 2400 BCE","Lugalkinishedudu, king of Uruk, proclaims himself king of Ur."],["c. 2334 BCE","Sargon of Akkad conquers Ur and installs his daughter Enheduanna as high priestess of Nanna."],["22nd century BCE","The Akkadian Empire ends under Sharkalisharri; Ur passes to Gutian or local rule and then to the influence of Lagash under Ur-Bau and Gudea."],["c. 2112 BCE","Ur-Nammu, governor of Ur under Utu-hengal of Uruk, moves the kingship to Ur and founds the Third Dynasty."]]},
  "Lagash": {t:["The Stele of the Vultures records Eannatum's victory over Umma around 2450 BCE in the dispute over the Gu'edena, one of the earliest organised battles known, won by a dense phalanx of spearmen.","Urukagina, the last ruler of the First Dynasty, made judicial, social and economic reforms that may well be the first legal code known to have existed.","The Gudea cylinders found at Girsu contain the longest known text in the Sumerian language, from a reign marked by riches, power and the building of temples."],dyk:"The dynasties of Lagash are missing from the Sumerian King List; the one tablet that lists its rulers, The Rulers of Lagash, is generally read as a satirical parody of the King List, its thirty kings given improbable reigns.",ev:[["c. 2520 BCE","The First Dynasty of Lagash begins; En-hegal is believed to be its first ruler, followed by Lugalshaengur, named an ensi of Lagash on a mace head of Mesilim, king of Kish."],["c. 2450 BCE","Eannatum defeats the army of Umma over the fertile Gu'edena, the battle shown on the Stele of the Vultures."],["c. 2300 BCE","Sargon of Akkad lays waste the land from Lagash to the sea; his son Rimush later reconquers the rebellious city, recording 8,049 killed and 5,460 enslaved at Ur and Lagash."],["c. 2260 BCE","Puzur-Mama declares Lagash independent after the death of Shar-Kali-Sharri; the Second Dynasty begins."],["c. 2150 BCE","Gudea rules a rich and powerful Lagash, builds and restores temples, campaigns against Anshan and leaves the Gudea cylinders."],["c. 2110 BCE","Ur-Nammu of Ur slays Nam-mahani, ensi of Lagash, ending the Second Dynasty; the Lagash state becomes the largest province of the Ur III empire."]]},
  "Sidon": {t:["Glass and purple dye were Sidon's two pivotal industries; a considerable mound of broken Murex trunculus shells near the southern harbour shows the scale of the dye works.","Sidon's navy fought with the Persian fleet at the Battle of Salamis in 480 BCE, and from the mid-5th century BCE warships were a prominent feature of the city's coins.","Cambyses II of Persia rewarded Sidon for supporting his conquest of Egypt with the territories of Dor, Joppa and the Plain of Sharon."],dyk:"The oldest testimony to words of the Phoenician language of Sidon is in the Book of Deuteronomy, which records that the Sidonians called Mount Hermon 'Sirion'.",ev:[["c. 1350 BCE","Sidon, part of the Egyptian Empire, is ruled by Zimredda during the Amarna period, as Egypt's hold on the Levant weakens and the coastal cities fight for dominance."],["7th century BCE","The Temple of Eshmun, to the Phoenician god of healing, is built north of the city near the Awali River."],["6th century BCE","After Nebuchadnezzar II's subjection of the city to the Neo-Babylonian Empire, Sidon passes to the Achaemenid Empire."],["480 BCE","Sidon's navy plays a significant role at the Battle of Salamis, aligned with the Persian fleet against the Greeks."],["5th century BCE","Eshmunazar II reigns as 'king of the Sidonians'; his sarcophagus, found in 1855, names Eshmun and Baal Sidon as the chief gods of the city."],["351 BCE","Artaxerxes III invades Phoenicia at the end of the Persian era."],["333 BCE","Alexander the Great occupies Sidon, beginning its Hellenistic period."]]},
  "Kingdom of Phrygia": {t:["Midas, the historical king believed to be the Mita of Assyrian texts, ruled Phrygia at its peak from about 720 BCE to about 695 BCE by Eusebius or 676 BCE by Julius Africanus.","Phrygia fought Assyria from 715 BCE over the Neo-Hittite lands of central Anatolia; an Assyrian inscription of 709 BCE suggests Mita had offered submission and struck a truce.","Excavations at Gordium confirm a violent destruction around 675 BCE, and the so-called Tomb of Midas held a wooden chamber under a vast tumulus with a coffin, furniture and food offerings."],dyk:"According to Strabo and others, Midas killed himself by drinking bulls' blood when the Cimmerians overran his kingdom and sacked Gordium.",ev:[["8th century BCE","The kingdom with its capital at Gordium expands into an empire dominating most of central and western Anatolia, bordering Assyria and Urartu."],["c. 720 BCE","Midas, the Mita of Assyrian texts, begins his reign over Phrygia at the peak of its power."],["715 BCE","Phrygia enters military conflict with Assyria over the Neo-Hittite lands of central Anatolia."],["709 BCE","An Assyrian inscription from the reign of Sargon of Assyria names Mita, suggesting Phrygia has offered its submission and struck a truce."],["c. 695 BCE","Cimmerian invaders sack Gordium; by Strabo's account Midas drinks bulls' blood and dies."],["c. 675 BCE","The destruction of Gordium confirmed by excavation marks the end of the independent kingdom; the Cimmerians remain in western Anatolia."]]},
  "Kingdom of Armenia (Artaxiad)": {t:["Tigranes the Great entered Syria in 83 BCE at the invitation of a faction in its civil wars and ruled it for 17 years, putting the Seleucid Empire virtually at an end.","At its peak Armenia held Iberia, Albania, Cappadocia, Cilicia, Osroene, Adiabene, Syria, Judea and Atropatene, with Parthia and some Arab tribes as Tigranes' vassals.","Armenia became a Roman client kingdom in 66 BCE after Pompey defeated its ally Mithridates VI of Pontus at the Battle of the Lycus; the last Artaxiad kings were overthrown in 12 CE."],dyk:"Strabo and Plutarch say Hannibal was received at the court of Artaxias I and, in a story they also tell, planned and supervised the building of Artaxata, though the tale is reckoned apocryphal.",ev:[["190 BCE","The Seleucids are defeated by Rome at the Battle of Magnesia; in the same year Artaxias I founds a Hellenistic Armenian state, with Zariadres ruling the kingdom of Sophene."],["189 BCE","Artaxias I's reign begins; he seizes Yervandashat and unites the Armenian Highlands at the expense of neighbouring tribes."],["185 BCE","Artaxias founds Artaxata (Artashat) near the Araxes, at the junction of trade routes linking the Greek world with Bactria, India and the Black Sea."],["83 BCE","Tigranes the Great enters Syria and establishes himself as its ruler, ending the Seleucid Empire in all but name."],["69 BCE","Rome conquers Tigranes' empire; Armenia's brief imperial period ends."],["66 BCE","After Pompey defeats Mithridates VI of Pontus at the Battle of the Lycus, Armenia becomes a Roman client kingdom."],["34 BCE","Mark Antony invades and defeats the kingdom; Rome loses its hegemony in the Final War of the Republic of 32–30 BCE."],["12 CE","The last Artaxiad kings are overthrown, suspected of allegiance to Parthia."]]},
  "Kingdom of Colchis": {t:["Colchis exported gold, iron, timber and honey mostly to the Greek city-states, and Greek and Roman sources say between 70 and 300 languages were spoken in Dioscurias alone.","Sarduri II of Urartu recorded a victory over Qulḫa in the mid-8th century BCE, and Askold Ivanchik holds that Qulḫa flourished as an independent state in the second half of that century.","Under the Achaemenids the southern tribes formed the 19th satrapy while the northern tribes sent 100 girls and 100 boys to the Persian court every five years."],dyk:"The oldest 'Colchian' coins, dated to the mid-6th century BCE and long the primary evidence for a Colchian state, have on reassessment turned out to be the production of an Achaemenid satrapy.",ev:[["mid-8th century BCE","Sarduri II, king of Urartu, inscribes his victory over Qulḫa on a stele."],["second half of the 8th century BCE","Qulḫa flourishes as an independent state, by Askold Ivanchik's reading of cuneiform texts and archaeology, but hardly survives the end of the century."],["8th century BCE","Scythians and Cimmerians migrating from Central Asia invade Colchis; the Scythians make a base on the kingdom's former territory for raids into Media and Anatolia."],["6th century BCE","The kingdom of Colchis (Kolkheti) emerges in western Georgia, what Svante Cornell calls the beginning of proto-Georgian statehood."],["mid-6th century BCE","The oldest 'Colchian' coins are struck, now understood as the output of an Achaemenid satrapy."],["400 BCE","Shortly after reaching Trapezus, the Ten Thousand decisively defeat the Colchians in battle."]]},
  "Old Kingdom of Egypt": {t:["Under Sneferu, Khufu, Khafre and Menkaure of the Fourth Dynasty (2613–2494 BCE) the art of pyramid-building was perfected and the pyramids of Giza were raised.","The king, not yet called pharaoh, was held to be the incarnation of Horus, a living god who ruled absolutely and could demand the services and wealth of his subjects.","In the Sixth Dynasty power passed to hereditary nomarchs, and a drought between 2200 and 2150 BCE that stopped the Nile flood brought famine and the kingdom's collapse."],dyk:"Old Kingdom shipbuilders used neither treenails nor metal fasteners: planks and superstructure were tightly tied and bound together with rope, and such ships sailed the length of the Red Sea to Punt.",ev:[["2686 BCE","The Third Dynasty begins; its first king Djoser orders the Step Pyramid at Saqqara, the work of his vizier Imhotep."],["2613 BCE","Sneferu founds the Fourth Dynasty, holds territory from Libya to Sinai and Nubia, and builds the Meidum, Bent and Red Pyramids."],["2589 BCE","Khufu commissions the Great Pyramid of Giza, in which the fully developed pyramid style is reached."],["2494 BCE","Userkaf founds the Fifth Dynasty, marked by the growing cult of Ra and the sun temples of Abusir."],["2375 BCE","Unas, the last king of the Fifth Dynasty, has the Pyramid Texts inscribed in his pyramid, the earliest ruler to do so."],["c. 2300 BCE","The canal to Lake Moeris is dug, among the very large works of Nile flood control."],["2278 BCE","Pepi II begins his long reign (2278–2214 BCE), during which internal disorder sets in."],["2181 BCE","The Sixth Dynasty ends; drought, famine and civil war open the First Intermediate Period."]]},
  "Marinid Sultanate": {t:["The Marinids took Fez in 1248 and Marrakesh in 1269, ending Almohad rule in the western Maghreb; in 1276 they founded Fes Jdid as their administrative and military centre.","Abu al-Hasan (r. 1331–1348) conquered Tlemcen in 1337 and defeated the Hafsids in 1347, making himself master of a territory from southern Morocco to Tripoli, but lost his eastern lands within a year.","A Portuguese–Castilian army defeated the Marinids at the Battle of Río Salado in 1340 and Castile took Algeciras in 1344, expelling them from the Iberian Peninsula for good."],dyk:"Abu al-Hasan copied the Qur'an in his own hand four times, sending copies to Medina, Mecca and the Al-Aqsa Mosque in Jerusalem; a fifth, begun at Bijaya for Hebron, was finished by his son after his dethronement.",ev:[["1244","Abu Yahya's reign begins; between 1244 and 1248 the Marinids take Taza, Rabat, Salé, Meknes and Fez from the weakened Almohads."],["1269","Abu Yusuf Yaqub captures Marrakesh, effectively ending Almohad rule."],["1276","Fes Jdid, 'New Fez', is founded as the dynasty's administrative and military centre."],["1294","The Marinids hold Rota, Tarifa and Gibraltar, seeking control of the Strait's trade from Algeciras."],["1337","Abu al-Hasan conquers the Abdalwadid kingdom of Tlemcen."],["1340","A Portuguese–Castilian army defeats the Marinids at the Battle of Río Salado near Tarifa."],["1347","Abu al-Hasan defeats the Hafsids of Ifriqiya and rules from southern Morocco to Tripoli; within a year a revolt of Arab tribes in southern Tunisia costs him the east."],["1465","Abd al-Haqq II, the last Marinid sultan, is killed in a revolt in Fez after appointing a Jewish vizier, Aaron ben Batash."]]},
  "Vandal Kingdom": {t:["Gaiseric took Carthage without a fight in 439, while most of its people were at the races in the hippodrome, and styled himself King of the Vandals and Alans.","The kingdom's fleet looted the coasts of both Roman empires for decades, sacked Rome in 455 and destroyed a combined imperial fleet at Cape Bon in 468 with fire ships.","The Vandal kings were Arian Christians: Huneric exiled almost 5,000 Nicene clergy into the desert and in 483 ordered every Nicene church closed and its property confiscated."],dyk:"The best Vandal warriors ended their days as five cavalry regiments, the Vandali Iustiniani, on the Persian frontier of the empire that had destroyed their kingdom.",ev:[["429","Gaiseric leads the Vandals and Alans across from Hispania to Africa and besieges Hippo Regius, where Saint Augustine dies on 28 August 430."],["435","A treaty with Valentinian III grants the Vandals coastal Numidia and parts of Mauretania."],["439","Gaiseric breaks the treaty, captures Carthage without a fight and makes it his capital."],["442","A second treaty gives the Vandals Byzacena, Tripolitania and part of Numidia and confirms their hold on Proconsular Africa."],["455","The Vandals sack Rome, carrying off the empress Licinia Eudoxia, her daughters and the spoils of the Temple in Jerusalem."],["468","At Cape Bon the Vandals destroy the Western fleet and part of the Eastern fleet sent to overthrow them."],["477","Gaiseric dies at 88; his son Huneric succeeds and from 482 persecutes Nicene Christians and Manichaeans."],["534","Gelimer, besieged at Mount Pappua after the defeats at Ad Decimum and Tricamarum, surrenders to the Byzantines."]]},
  "Aghlabid emirate": {t:["The Aghlabids were independent in all but name, yet paid the Abbasid caliph 800,000 dirhams a year and named him in the Friday khutba.","Their conquest of Sicily, begun in 827 under the qadi Asad ibn al-Furat, took Palermo in 831, Syracuse in 878 and Taormina only in 902.","Ziyadat Allah I rebuilt the Great Mosque of Kairouan in 836; its minaret is the oldest surviving in North Africa and its teak minbar the oldest in the world."],dyk:"The Aghlabid emirs were Mu'tazilites who held that the Qur'an was created, a doctrine the Maliki majority of Ifriqiya rejected; the scholar Sahsun was persecuted under Muhammad I for refusing it.",ev:[["800","Harun al-Rashid appoints Ibrahim I ibn al-Aghlab hereditary emir of Ifriqiya; he founds al-Abbasiyya outside Kairouan."],["824","The Arab jund revolts under Mansur ibn Nasr al-Tunbudhi and occupies Tunis and Kairouan; Ziyadat Allah I crushes the rebellion in 827 with Ibadi Berber help."],["827","Asad ibn al-Furat leads the Aghlabid conquest of Sicily, invited by the Byzantine rebel Euphemios."],["836","Ziyadat Allah I completely rebuilds the Great Mosque of Kairouan."],["870","The Aghlabids conquer Malta."],["876","Ibrahim II moves his residence from al-Abbasiyya to the new palace-city of Raqqada."],["902","Ibrahim II dies besieging Cosenza; Abu Abdallah al-Shi'i takes Mila, the first blow to Aghlabid rule in Africa."],["909","The Kutama rout the Aghlabid army near al-Aribus on 18 March; Ziyadat Allah III flees to Egypt and Abu Abdallah enters Raqqada on 25 March."]]},
  "Idrisid dynasty": {t:["Idris I, a great-grandson of Hasan ibn Ali, fled the Abbasids after the Battle of Fakhkh and was made imam by the Awraba Berbers of Volubilis in 788.","Idris II moved his seat to Fez in 809 and welcomed Arab settlers from Córdoba in 818 and from Aghlabid Tunisia in 824, giving the city its Arab character.","After Idris II's death in 828 the realm was divided among his sons; the Idrisids lost Fez for good in 927 and were removed from power by the Umayyads of Córdoba in 974."],dyk:"Idris I left no male heir when an Abbasid agent poisoned him in 791, but his wife Lalla Kanza bore his only son shortly after his death; the boy, Idris II, was proclaimed imam by the Awraba at the age of eleven.",ev:[["788","Idris ibn Abdallah, fleeing the Abbasids after the Battle of Fakhkh, settles at Volubilis, where the Awraba Berbers make him their imam."],["791","Idris I is poisoned by an Abbasid agent; his posthumous son Idris II is brought up under the regency of the freedman Rashid."],["809","Idris II has the Awraba leader Ishak killed and moves his seat from Walili to Fez, founding the settlement of al-'Aliya."],["828","Idris II dies; the state reaches from western Algeria to the Sous, and his son Muhammad divides it among seven brothers."],["836–863","Ali ibn Muhammad and Yahya I rule in stability; the al-Qarawiyyin and al-Andalusiyyin mosques are founded in Fez."],["868","The Sufri Kharijite tribes of Madyuna, Ghayata and Miknasa defeat Ali ibn Umar and occupy Fez until Yahya III retakes it."],["927","Musa ibn Abul 'Afiya of the Miknasa captures and kills Hassan I al-Hajam: the Idrisids never again hold Fez."],["974","The Umayyad general Ghalib expels the Idrisids from their lands and takes al-Hasan and other Idrisids as hostages to Córdoba."]]},
  "Alodia": {t:["Alodia was the last of the three Nubian kingdoms to accept Christianity: in 580 the bishop Longinus baptized the king, his family and the nobility.","In the 10th century Ibn Hawqal and al-Aswani found a large, polyethnic kingdom more powerful than Makuria, with a capital of fine buildings and churches full of gold.","Succession was matrilineal, passing to the son of the king's sister, and al-Aswani wrote that the king could enslave any subject at will."],dyk:"As late as 1930, Hamaj villagers in the southern Gezira would swear by 'Soba the home of my grandfathers and grandmothers which can make the stone float and the cotton ball sink'.",ev:[["569","John of Ephesus mentions Alodia for the first time, as a kingdom on the cusp of Christianization."],["580","Longinus is sent at the king's request and baptizes him, his family and the nobility; Alodia joins the Coptic Patriarchate of Alexandria."],["652","Makuria and the Arabs sign the Baqt after two failed invasions; the treaty explicitly leaves Alodia unaffected."],["9th century","Al-Yaqubi describes Alodia as the stronger of the two Nubian kingdoms, a country three months' journey across."],["10th century","Ibn Hawqal and al-Aswani visit the kingdom and describe Soba's prosperity under kings Eusebius and Stephanos."],["1220","The Damadim attack Nubia from the south, according to Ibn Sa'id al-Maghribi; Soba may have been conquered and destroyed."],["1276","Al-Abwab, the northernmost province, is recorded as an independent splinter kingdom."],["1504","Soba lies in ruins; Abdallah Jammah and the Funj king Amara Dunqas destroy the kingdom, and the Funj found Sennar."]]},
  "Kingdom of Macedon": {t:["Before the 4th century BCE Macedon was a small kingdom centred on Aigai, briefly a vassal of the Achaemenid Empire under Amyntas I and Alexander I, who fought on the Persian side at Plataea in 479 BCE.","Philip II (359–336 BCE) rebuilt the army around the sarissa-armed phalanx, took the mines of Crenides and Amphipolis, and defeated Athens and Thebes at the Battle of Chaeronea in 338 BCE.","Elected hegemon of the League of Corinth in 337 BCE, Philip was assassinated by his bodyguard Pausanias of Orestis at his daughter's wedding feast at Aigai in 336 BCE, and Alexander succeeded him."],dyk:"Alexander I of Macedon was at first refused entry to the foot race at the Olympic Games because only Greeks could compete; he produced an Argead genealogy tracing his line to Temenus of Argos, and the Hellanodikai let him run.",ev:[["c. 650 BCE","One of the earliest Argead kings establishes Aigai as the capital, in Robert Malcolm Errington's reckoning."],["547–498 BCE","Amyntas I reigns, the first king of whom much is known; the Persian general Megabazus persuades him to submit as a vassal of the Achaemenid Empire."],["479 BCE","Macedonian soldiers fight on the Persian side at the Battle of Plataea; the Achaemenid withdrawal from Europe soon ends Persian control of Macedonia."],["413–399 BCE","Archelaus I moves the capital north to Pella, improves the coinage and brings Euripides to his court; his assassination plunges the kingdom into chaos."],["359 BCE","Bardylis's Illyrians kill Perdiccas III and 4,000 Macedonian troops in battle; Philip II accedes at twenty-four."],["352 BCE","Philip II defeats Onomarchus at the Battle of Crocus Field and is elected archon of the Thessalian League."],["338 BCE","Philip II defeats Athens and Thebes at the Battle of Chaeronea and forms the League of Corinth, which elects him hegemon in 337 BCE."],["336 BCE","Philip II is assassinated by Pausanias of Orestis at Aigai; the army and leading aristocrats proclaim Alexander III king."]]},
  "Etruscan League": {t:["The league of twelve cities, the Dodecapolis, was mostly an economic and religious alliance, a loose confederation like the Greek leagues; authority stayed with the individual cities and their leading families.","According to Livy the twelve city-states met once a year at the Fanum Voltumnae at Volsinii, where they chose a leader, the zilath mechl rasnal, who was largely a ceremonial figure rather than a federal executive.","Allied with Carthage, the Etruscans held the northern Tyrrhenian Sea after the Battle of Alalia around 540 BCE, but Syracuse defeated them at Cumae in 474 BCE and Rome destroyed Veii in 396 BCE."],dyk:"The Etruscans called themselves Rasna, 'the people'; the league's annual assembly chose a zilath mechl rasnal, a 'magistrate of the Etruscan people', and inscriptions speak of the Mechlum Rasnal, the 'community of the people'.",ev:[["600–500 BCE","By legend, an alliance forms among twelve Etruscan settlements, founded by Tarchon and his brother Tyrrhenus: the Etruscan League or Dodecapolis."],["c. 540 BCE","Allied with Carthage against the Phocaean Greeks, the Etruscans fight the Battle of Alalia and keep full ownership of Corsica."],["474 BCE","Hiero of Syracuse defeats the Etruscans at the Battle of Cumae; their hold on Latium and Campania weakens."],["396 BCE","Rome destroys Veii after a ten-year siege; from the same year the Celts invade the Po Valley."],["358 BCE","Tarquinia and Caere ally against Rome."],["310 BCE","The Etruscans are defeated by the Romans at Lake Vadimone."],["264 BCE","Volsinii, seat of the Fanum Voltumnae, is defeated by Rome; the league's independence ends."]]},
  "Socialist Federal Republic of Yugoslavia": {t:["The Federal People's Republic of Yugoslavia was proclaimed on 29 November 1945 after an election in which the People's Front took an average of 85% of the vote; it was renamed the Socialist Federal Republic in 1963.","Expelled from the Cominform on 28 June 1948, Yugoslavia steered between the blocs: it refused the Warsaw Pact and NATO alike, co-founded the Non-Aligned Movement and introduced workers' self-management in June 1950.","After Tito's death on 4 May 1980 debt, inflation and nationalism overwhelmed a collective presidency; the League of Communists dissolved in January 1990 and four republics declared independence between June 1991 and April 1992."],dyk:"The Cominform chose 28 June 1948 to expel Yugoslavia: the anniversary of the Battle of Kosovo Field in 1389, the assassination of Archduke Ferdinand at Sarajevo in 1914 and the Vidovdan Constitution of 1921.",ev:[["1945","On 29 November the Constituent Assembly abolishes the monarchy and proclaims the Federal People's Republic of Yugoslavia, a one-party state of six people's republics."],["1948","On 28 June the Cominform expels Yugoslavia for 'nationalist elements' and 'Trotskyism'; Soviet troops mass on the Hungarian border and 16,000 suspected Cominformists go to Goli Otok."],["June 1950","Workers' self-management is introduced: workers' councils manage enterprises and share their profits."],["1963","A new constitution renames the state the Socialist Federal Republic of Yugoslavia; emigration of workers is legalised and Western travel opens."],["1974","The third constitution gives the republics and the provinces of Kosovo and Vojvodina wide autonomy; Tito is elected President-for-life."],["1980","On 4 May Tito dies; a collective presidency rotating among the republics takes his place as the foreign debt mounts."],["January 1990","The League of Communists of Yugoslavia dissolves along federal lines; multi-party elections bring separatist parties to power outside Serbia and Montenegro."],["1992","On 27 April the Federal Council adopts the Constitution of the Federal Republic of Yugoslavia for Serbia and Montenegro, formally ending the breakup."]]},
  "Visigothic Kingdom": {t:["Settled as Roman federates in the Garonne valley in 418, the Visigoths under Euric (466–484) took Hispania Tarraconensis, Arles and Marseille and were recognized as an independent kingdom by Julius Nepos in 475.","After Alaric II fell to the Franks at Vouillé in 507 the kingdom lost Gaul but Septimania; Liuvigild conquered the Suebi in 585 and Swinthila drove the last Byzantine garrisons from Hispania by 625.","The Liber Iudiciorum of 654 gave Goths and Hispano-Romans one law, based almost wholly on Roman law, and became the basis of Spanish law through the Middle Ages."],dyk:"The Visigoths founded the only new cities in Western Europe between the 5th and 8th centuries: Reccopolis, built by Liuvigild in 578 with a palace and a mint after a victory over the Franks, Victoriacum, Luceo and Ologicus, raised with Basque labour in 621.",ev:[["418","Honorius rewards his Visigothic federates under King Wallia with land in the Garonne valley of Gallia Aquitania; Toulouse becomes their capital."],["451","Theodoric I fights under Flavius Aetius against Attila at the Battle of the Catalaunian Plains and is killed as the Huns are driven back."],["475","Julius Nepos signs an alliance granting Euric the lands south of the Loire and west of the Rhone; the kingdom is formally independent."],["507","The Franks and Burgundians kill Alaric II at the Battle of Campus Vogladensis (Vouillé) and sack Toulouse; by 508 only Septimania remains in Gaul."],["589","Reccared I renounces Arianism at the Third Council of Toledo and the kingdom becomes Nicene Christian."],["625","Swinthila captures the last Byzantine holdings in Spain; the whole peninsula is Visigothic."],["654","Recceswinth completes the Liber Iudiciorum, begun by Chindaswinth, abolishing separate laws for Goths and Hispano-Romans."],["711","Tariq ibn Ziyad lands with about 7,000 Berbers; Roderic is betrayed and killed at the Guadalete, and the Muslims take Toledo."]]},
  "Principality of Wallachia": {t:["Basarab I's victory over Charles I of Hungary at the Battle of Posada in 1330 consolidated Wallachia as an independent principality.","Wallachia accepted Ottoman suzerainty in 1417 and kept it until the mid-nineteenth century, yet preserved its own princes, boyars and Orthodox Church throughout.","Slavery of Roma, attested from 1385, was part of Wallachian society until the law of February 1856 freed all slaves as taxpayers."],dyk:"The Transylvanian Saxons, angered when Vlad III strengthened Wallachia's borders and disrupted their trade routes, spread grotesque poems painting him as a drinker of blood; those tales inspired the main character of Bram Stoker's Dracula in 1897.",ev:[["1330","Basarab I refuses tribute to Charles I of Hungary and decisively defeats his invasion at the Battle of Posada, consolidating the Wallachian state."],["1417","After Mehmed I takes Turnu Măgurele and Giurgiu, Mircea I accepts a peace treaty and Wallachia submits to Ottoman suzerainty for the first time."],["1462","Vlad III the Impaler is defeated by Mehmed the Conqueror after the Night Attack at Târgoviște and must accept an increased tribute."],["1600","Michael the Brave, having broken with the Ottomans, briefly rules Wallachia, Transylvania and Moldavia in a personal union."],["1715","Nicholas Mavrocordatos brings Phanariote rule to Wallachia; the Ottomans appoint its princes from the Greeks of Constantinople."],["1821","Tudor Vladimirescu's Pandur uprising enters Bucharest on 21 March; the turmoil ends Phanariote rule and restores local princes."],["1848","The Islaz Proclamation of 9 June and a Provisional Government depose Gheorghe Bibescu; Ottoman troops crush the revolution on 13 September."],["1859","Alexander John Cuza, already prince of Moldavia, is voted prince of Wallachia on 5 February, uniting the two principalities."]]},
  "Great Moravia": {t:["Rastislav asked Constantinople for teachers in 863 to free his church from Frankish priests; the mission of Cyril and Methodius gave the Slavs their first alphabet and liturgy.","Moravia reached its greatest extent under Svatopluk I (870–894), when Bohemia, Pannonia and Lesser Poland at least formally accepted his suzerainty.","Pope John VIII's bull Industriae tuae of 880 recognised Old Church Slavonic as the fourth liturgical language, beside Latin, Greek and Hebrew."],dyk:"Great Moravia's capital has never been found: the sources name a Veligrad, and Mikulčice, with its palace and twelve churches on an island in the Morava, is the most widely accepted candidate.",ev:[["c. 833","Mojmír I, duke of the Moravians, expels Pribina from Nitra across the Danube; the union of Nitra with Moravia makes Great Moravia."],["846","Louis the German campaigns against the Moravians and installs Mojmír's nephew Rastislav as duke."],["863","At Rastislav's request Emperor Michael III sends Constantine (Cyril) and Methodius, who bring the Glagolitic alphabet and the Slavonic liturgy."],["871","The Moravians rise against the Frankish governors William and Engelschalk; Svatopluk returns, leads the revolt and drives the Franks out."],["880","Pope John VIII's bull Industriae tuae takes Svatopluk under papal protection, confirms Methodius as archbishop and recognises Old Church Slavonic in the liturgy."],["885","Methodius dies on 6 April; Bishop Wiching of Nitra has the Slavonic rite restricted and, in 886, Methodius's disciples expelled."],["894","Svatopluk I dies in the summer; under his son Mojmír II the subjugated tribes begin to break away."],["907","No Moravian force fights at Brezalauspurc, where the Hungarians rout the Bavarians; the Moravian state has ceased to exist between 902 and 907."]]},
  "Cossack Hetmanate": {t:["The Treaty of Zboriv of 18 August 1649 recognised the Hetmanate within the Commonwealth, with 40,000 Registered Cossacks and Crown forces barred from the Kyiv, Bratslav and Chernihiv lands.","At the Pereiaslav Council of 1654 Khmelnytsky and the Cossack elite swore allegiance to Tsar Alexis in return for self-government, a bond Russia tightened with every later agreement.","Peter I's troops burnt the capital Baturyn on 13 November 1708, killing up to 15,000 people, after Ivan Mazepa allied with Charles XII of Sweden."],dyk:"Visitors found the Hetmanate unusually literate: in the 1740s 866 of 1,099 settlements in seven regimental districts had primary schools, more per head than in Russia or Poland, and Paul of Aleppo wrote in 1654 that even wives and daughters could read.",ev:[["1649","Bohdan Khmelnytsky signs the Treaty of Zboriv on 18 August: the Registered Cossacks rise to 40,000 and Crown forces are barred from the Kyiv, Bratslav and Chernihiv voivodeships."],["1654","At the Pereiaslav Council Khmelnytsky and the Cossack elite swear allegiance to Tsar Alexis in return for self-government and war on Poland."],["1667","The Treaty of Andrusovo, made without any Cossack representative, splits the Hetmanate along the Dnieper between Russia and the Commonwealth."],["1687","Ivan Mazepa is elected hetman, ending the civil wars of the Ruin and opening a flowering of Cossack Baroque architecture and learning."],["1708","Mazepa allies with Charles XII of Sweden on 28 October; on 13 November Menshikov's troops sack Baturyn and kill up to 15,000 people."],["1709","The Battle of Poltava on 8 July ends in the defeat of the Swedes and Mazepa; the Hetmanate's autonomy becomes nominal."],["1750","Kyrylo Rozumovsky is elected hetman in absentia after Elizabeth restores the office; he moves the capital back to Baturyn and reforms the courts."],["1764","Catherine II forces Rozumovsky to resign and by decree of 21 October abolishes the hetmanship, handing power to the Little Russian Collegium under Pyotr Rumyantsev."]]},
  "Kingdom of the Two Sicilies": {t:["Ferdinand I created the kingdom in 1816 by annulling the Sicilian constitution of 1812 and merging the Kingdom of Naples and the Kingdom of Sicily into one state ruled from Naples.","The Naples–Portici line of 1839 was the first railway on the Italian peninsula, yet by 1859 the kingdom had only 99 kilometres of track against Piedmont's 850.","Garibaldi's Expedition of the Thousand took Sicily in 1860 and won the Battle of the Volturno with half its army local volunteers; Francis II surrendered at Gaeta in February 1861."],dyk:"Sicily's mines near Catania and Agrigento supplied most of the world's sulphur; when Ferdinand II granted a French company the monopoly in 1840, breaking an 1816 trade agreement with Britain, the Sulphur Crisis followed and was settled only by French mediation.",ev:[["1816","Ferdinand IV annuls the Sicilian constitution of 1812, merges Naples and Sicily into the Regno delle Due Sicilie and takes the title Ferdinand I."],["1820","A Carbonari revolution forces Ferdinand to grant the Spanish constitution of 1812 on 13 July; a rising in Palermo the same month is quickly suppressed."],["1821","Ferdinand cancels the constitution on 23 February before 50,000 Austrian troops, who enter Naples on 24 March after smashing General Guglielmo Pepe's resistance."],["1839","The railway from Naples to Portici opens, the first on the Italian peninsula, and the main streets of Naples are lit by gas."],["1848","Rebellion in Palermo on 12 January demands the 1812 constitution; Ferdinand II grants a liberal ministry, declares war on Austria on 7 April, then turns the Swiss Guard on Naples on 15 May."],["1856","Britain and France break off diplomatic relations after the kingdom refuses to release its political prisoners."],["1860","Giuseppe Garibaldi's Expedition of the Thousand lands in Sicily, crosses to the mainland and wins the Battle of the Volturno; at Teano he hands the kingdom to Victor Emmanuel."],["1861","Francis II surrenders and abdicates at Gaeta in February; the Two Sicilies are annexed to the Kingdom of Sardinia, proclaimed the Kingdom of Italy."]]},
  "Mandatory Palestine": {t:["The League of Nations charged Britain in 1922 both to put the Balfour Declaration's Jewish national home into effect and to develop self-governing institutions for a population then 78 per cent Muslim Arab.","The Arab revolt of 1936–1939 cost more than 5,000 Arab, 400 Jewish and 200 British lives; the White Paper of 1939 that followed cut Jewish immigration and land purchase as the Holocaust began.","The UN General Assembly recommended partition on 29 November 1947; the Jewish Agency accepted it, the Palestinian Arab leadership and the Arab League rejected it, and civil war broke out at once."],dyk:"Of the eleven religious communities the British recognised under the Ottoman millet system, Muslims, Jews and nine Christian denominations, none was Protestant, and since personal status lay with confessional courts there was no civil marriage in Mandatory Palestine.",ev:[["1920","A British civilian administration under High Commissioner Sir Herbert Samuel replaces military rule in July; riots in Jerusalem in April have killed five Jews and four Arabs."],["1922","The League of Nations grants Britain the Mandate for Palestine; the Palestine Order in Council plans a Legislative Council whose seats the Arabs reject, boycotting the 1923 elections."],["1929","Riots in August, including the Hebron massacre of Jews, leave 250 people dead."],["1936","The Arab general strike of April to October, led by the Arab Higher Committee under Amin al-Husseini, opens the Arab revolt in Palestine."],["1939","The revolt ends in March with more than 5,000 Arabs, 400 Jews and 200 British dead; the White Paper restricts Jewish immigration and land purchase and promises an independent state within ten years."],["1946","The Irgun blows up the King David Hotel in Jerusalem, headquarters of the British administration, killing 92 people; Britain begins interning illegal Jewish immigrants in Cyprus."],["1947","The UN General Assembly adopts Resolution 181 on 29 November, recommending partition into Arab and Jewish states; civil war between the two communities begins at once."],["1948","The Mandate expires at midnight on 14–15 May; David Ben-Gurion declares the State of Israel, Arab armies cross the borders, and the 1948 war divides the territory."]]},
  "Qara Qoyunlu": {t:["Qara Yusuf returned from Mamluk captivity to defeat the Timurids at Nakhchivan in 1406 and Sardrud in 1408, and by taking Tabriz and Baghdad in 1410 freed the Qara Qoyunlu from the Jalayirids.","Jahan Shah (1436–1467) became independent on Shah Rukh's death in 1447, conquered Isfahan, Shiraz and Yazd in 1452–1453 and occupied Herat for some months in 1458.","The Qara Qoyunlu court wrote to the Timurids and Ottomans in Persian and to the Mamluks in Arabic, and Jahan Shah styled himself Padishah-i Iran, King of Kings of Iran."],dyk:"Sultan Quli, founder of the Qutb Shahi Sultanate of Golconda in southern India in 1518, was a fourth-generation descendant of the Qara Qoyunlu ruler Qara Iskander.",ev:[["1384","Qara Mahammad invades Mardin and takes the submission of its Artuqid ruler Majd al-Din Isa, who becomes a vassal."],["1400","Timur defeats the Qara Qoyunlu; Qara Yusuf flees to the Mamluk Sultanate, where an-Nasir Faraj imprisons him together with the Jalayirid sultan Ahmad."],["1408","Qara Yusuf crushes the Timurids Abu Bakr and Miran Shah at the Battle of Sardrud on 20 April; Miran Shah is killed."],["1410","Qara Yusuf conquers Tabriz, executes Shaykh Uways Jalayir, captures Baghdad and takes control of Armenia; the Qara Qoyunlu are independent."],["1420","Qara Yusuf dies in December; his sons fight for the succession and Shah Rukh invades, occupying Tabriz briefly in 1421."],["1447","On Shah Rukh's death Jahan Shah throws off Timurid vassalage, takes the titles sultan and khan and seizes Sultaniya, Hamadan and Qazvin."],["1458","Jahan Shah advances to Herat and holds the Timurid capital for some months, until Hasan Ali's revolt and Abu Said's march on Tabriz force him back."],["1467","Jahan Shah is killed at the Battle of Chapakchur after his failed attack on Aq Qoyunlu Diyarbakır; by 1468 Uzun Hasan has conquered Iraq, Azerbaijan and western Iran."]]},
  "Armenian Kingdom of Cilicia": {t:["Ruben's revolt against Byzantium in 1080 founded the principality; Levon II's coronation at Tarsus on 6 January 1198, backed by the Holy Roman Emperor, made it a kingdom.","Het'um I's alliance with the Mongols, sealed at Karakorum in 1250 and 1253, drew Mamluk vengeance: Sis was sacked in 1266 and 40,000 Armenians carried off.","Cilician society adopted Western feudalism, chivalry and French titles, and the Armenian alphabet gained two letters, Ֆ and Օ, from the contact."],dyk:"Marco Polo set out on his journey to China in 1271 from Ayas, the Cilician Armenian port where the Genoese held licensed warehouses and Italian was the language of trade.",ev:[["1080","Ruben, a noble close to the murdered Bagratid king Gagik II, raises Armenian troops against the Byzantine Empire and founds the principality of Cilicia."],["1198","Prince Levon II is crowned King Levon I in the cathedral of Tarsus on 6 January, with a banner from Henry VI, Holy Roman Emperor; Cilician Armenia becomes a kingdom."],["1226","Queen Zabel is forced to marry Het'um, son of the regent Constantine of Baberon; as Het'um I he unites the rival Rubenid and Het'umid houses."],["1253","Het'um I visits Möngke Khan at Karakorum, confirming the Armeno-Mongol alliance his brother Smbat negotiated in 1247–1250."],["1266","Mamluk forces under Al-Mansur Ali and Qalawun overrun the Armenians at the Disaster of Mari, sack and burn Sis, massacre thousands and take 40,000 captives."],["1299","Het'um II joins the Mongol khan Ghazan to defeat the Mamluks at the Battle of Wadi al-Khazandar on 23 December."],["1307","The Mongol representative Bularghu murders King Levon III, the former king Het'um II and their party outside Anazarba; Oshin drives him out and becomes king."],["1375","Sis falls to the Mamluks, then the fortress of Gaban where King Levon V had taken refuge; the kingdom ends and Levon dies in exile in Paris in 1393."]]},
  "Zengid dynasty": {t:["Zengi's capture of the County of Edessa after the siege of 1144 made him a hero in the Muslim world; he was assassinated by a slave two years later.","Nur ad-Din took Damascus from the Burids in 1154 and, through his general Shirkuh and Shirkuh's nephew Saladin, brought Fatimid Egypt under Zengid dominion in 1169.","Saladin crushed the armies of Mosul and Aleppo at the Horns of Hama on 13 April 1175 and received Aleppo on 12 June 1183, ending Zengid rule in Syria."],dyk:"When Saladin took Amid from the Zengid coalition in April 1183, the Ayyubids counted among its stores 80,000 candles, a tower full of arrowheads and 1,040,000 books.",ev:[["1127","After the murder of Aqsunqur al-Bursuqi, the Seljuk Empire names Zengi, son of Aq Sunqur al-Hajib, atabeg of Mosul."],["1144","Zengi captures the County of Edessa from the Crusaders after the siege of Edessa, a feat that makes him a hero in the Muslim world."],["1154","Nur ad-Din captures Damascus from the Turkic Burid dynasty and rules Syria from there."],["1169","Shirkuh kills the vizier Shawar and seizes Egypt as Fatimid vizier in Nur ad-Din's name; on his death the same year his nephew Saladin succeeds him."],["1174","Nur ad-Din dies on 15 May; his eleven-year-old son as-Salih Ismail inherits, and Saladin enters Damascus on 23 November."],["1183","Imad ad-Din Zangi hands Aleppo to Saladin on 12 June in exchange for Sinjar, Nusaybin and Raqqa, ending Zengid rule in Syria."],["1234","Badr al-Din Lu'lu', atabeg to the child emirs of Mosul, takes the city in his own name, possibly after murdering the last Zengid emir Nasir ad-Din Mahmud."],["1250","Al-Jazira in northern Iraq, the last Zengid territory, falls to an-Nasir Yusuf, the Ayyubid emir of Aleppo."]]},
  "Champa": {t:["Champa was less a single kingdom than a confederation of Cham principalities along the coast, Indrapura, Amaravati, Vijaya, Kauthara and Panduranga, united by language and culture, with a king of kings in some periods.","Between the 7th and 10th centuries Cham fleets controlled the spice and silk trade of the South China Sea, and eaglewood from the highlands was the kingdom's chief export.","The Vietnamese conquest of Vijaya in 1471, in which 120,000 people were killed or captured, reduced Champa to Kauthara and Panduranga; Panduranga was annexed by Minh Mạng in 1832."],dyk:"The Đông Yên Châu inscription, found in Champa and dated to around 350 CE, is the oldest known text written in a native Southeast Asian language, centuries before the first Khmer, Mon or Malay texts.",ev:[["192","Khu Liên, an official at Xianglin, rebels against the Eastern Han dynasty and founds Lâm Ấp, the predecessor state of Champa."],["380–413","Bhadravarman, the first king acknowledged in the inscriptions, establishes the linga Bhadresvara at Mỹ Sơn."],["605","The Sui Empire invades Lâm Ấp, overruns Sambhuvarman's resistance and sacks the capital at Trà Kiệu."],["875","Indravarman II founds Indrapura and a Buddhist dynasty; the years to 982 are called the Golden Age of Champa art."],["1177","Jaya Indravarman IV's fleet takes Angkor by surprise, kills the Khmer king and begins a four-year Cham occupation of Cambodia."],["1283–1285","The Yuan army under Sogetu takes Vijaya; Indravarman V and Prince Harijit wage a two-year guerrilla war and drive the Mongols out."],["1471","Lê Thánh Tông's army destroys Vijaya; 120,000 Cham are killed or captured and the kingdom shrinks to Kauthara and Panduranga."],["1832","Minh Mạng arrests the last king, Po Phaok The, and annexes Panduranga as the provinces of Ninh Thuận and Bình Thuận."]]},
  "Indo-Greek Kingdom": {t:["The Indo-Greeks struck the first bilingual coins, Greek on one face and Prakrit in Kharoshthi (at first Brahmi) on the other, with Indian animals and Buddhist symbols, a concession to another culture never before made in the Hellenic world.","Menander I, ruling the Punjab from Sagala from 165 to 130 BCE, carried the kingdom to its greatest extent, campaigned to Mathura and is remembered in the Milinda Panha as a convert to Buddhism who became an arhat.","After Menander the realm splintered among some twenty known kings, lost the Hindu Kush to the Yuezhi after Hermaeus (c. 80 BCE) and its centre to the Indo-Scythian Azes I in 48/47 BCE; Strato II and Strato III fell to Rajuvula about 10 CE."],dyk:"Kings Euthydemus II, Pantaleon and Agathocles issued the world's first cupro-nickel coins around 180–170 BCE, an alloy then known only in China; copper-nickel was not used in coinage again until the 19th century.",ev:[["c. 200 BCE","Demetrius I of Bactria, son of Euthydemus, invades the Kabul valley, Arachosia and perhaps Gandhara, founding the Indo-Greek realm."],["c. 185–170 BCE","Pantaleon and Agathocles strike the first bilingual coins, with Indian inscriptions in Brahmi, found as far east as Taxila."],["c. 180/175 BCE","Apollodotus I makes himself independent of Bactria as the first proper Indo-Greek king, ruling Gandhara and western Punjab."],["165–130 BCE","Menander I rules the Punjab from Sagala, extends the kingdom to its greatest extent and campaigns across northern India to Mathura."],["c. 130 BCE","The Greco-Bactrian kingdom falls to the Scythians and Heliocles is probably killed; the Indo-Greeks are cut off from the Greek world."],["c. 113 BCE","Heliodorus, ambassador of Antialcidas to the Shunga king Bhagabhadra, raises a pillar to Vāsudeva at Vidisha."],["48/47 BCE","Hippostratus loses to the Indo-Scythian Azes I, who founds an Indo-Scythian dynasty in the central territories."],["c. 10 CE","The Northern Satrap Rajuvula conquers the eastern Punjab kingdom of Strato II and Strato III, the last Indo-Greek kings."]]},
  "Travancore": {t:["Travancore's victory over the Dutch East India Company at the Battle of Colachel in 1741 is considered the earliest example of an organised Asian power overcoming European military technology and tactics.","On 3 January 1750 Marthanda Varma dedicated the kingdom to the deity Padmanabha, and its rulers thereafter governed as Padmanabha-dasar, servants of Padmanabha.","Treaties of 1788, 1795 and 1805 placed Travancore under British dominance; after Velu Thampi's rebellion of 1809 almost all its forces were disbanded and the East India Company undertook its defence."],dyk:"Chithira Thirunal's Temple Entry Proclamation of 12 November 1936 opened every Hindu temple in Travancore to the backward communities and won praise from Mahatma Gandhi; Swami Vivekananda had earlier called the state \"The Lunatic Asylum in India\" for its caste discrimination.",ev:[["1729","Marthanda Varma becomes king of Venad and begins to unify the small kingdoms of the south by brutal methods."],["1741","Travancore defeats the Dutch East India Company at the Battle of Colachel and captures Eustachius De Lannoy, who later modernises its army."],["1750","On 3 January Marthanda Varma dedicates Travancore to Padmanabha; the kings rule thereafter as servants of the deity."],["1755","Travancore defeats the Zamorin of Kozhikode at the battle of Purakkad and becomes the dominant state of Kerala."],["1789","On 28 December Tipu Sultan of Mysore attacks the Nedunkotta lines from the north and is defeated at the Battle of Nedumkotta."],["1809","Velu Thampi Dalawa's war on the East India Company is crushed; he kills himself to avoid capture and Travancore's forces are disbanded."],["1936","On 12 November Chithira Thirunal's Temple Entry Proclamation opens the temples of Travancore to the backward communities."],["1949","On 1 July Travancore, which acceded to the Indian Union on 12 August 1947, merges with Cochin to form the state of Travancore–Cochin."]]},
  "Malacca Sultanate": {t:["Malacca's rise rested on Ming protection: Zheng He called there in 1407, and in exchange for regular tribute the Yongle Emperor shielded Parameswara from the threat of Siamese attack.","Under Mansur Shah (r. 1459–1477) Malacca conquered Pahang, received Indragiri, Jambi, Tungkal and Siantan from Majapahit and vassalised Siak, ruling much of the Malay Peninsula and the east coast of Sumatra.","Malacca became the centre of Islamic learning in the archipelago; Classical Malay became the lingua franca of Maritime Southeast Asia and Jawi script the medium of its religious and intellectual exchange."],dyk:"Afonso de Albuquerque said that taking Malacca from the Moors would ruin Cairo and Mecca and leave Venice no spices but what her merchants bought in Portugal; Tomé Pires wrote that \"whoever is lord of Malacca shall have his hands on the throat of Venice\".",ev:[["c. 1400","Parameswara, fleeing the sack of Singapura, founds Malacca at a fishing village of the Orang Laut at the mouth of the Bertam River."],["1405","The Yongle Emperor sends Yin Qing to Malacca; Zheng He follows in 1407 and takes Parameswara to China, recognising him as its ruler."],["1424–1444","Raja Tengah takes the name Muhammad Shah and the title Sultan, Islamises the administration and issues the Maritime Laws of Malacca."],["1446","Ayutthaya invades by land and is beaten with the help of Tun Perak, who becomes Bendahara; a Siamese naval attack is repelled at Batu Pahat in 1456."],["1459–1477","Mansur Shah conquers Pahang with a fleet of 200 ships and gains Indragiri, Jambi, Tungkal and Siantan from Majapahit; he dies at the peak of Malacca's splendour."],["1509","On 1 August Diogo Lopes de Sequeira arrives from Portugal; a plot to kill him fails, but several of his men are taken captive."],["1511","On 15 August Afonso de Albuquerque captures Malacca after a failed assault on 25 July; Mahmud Shah flees south."],["1526","The Portuguese raze Mahmud Shah's base at Bintan; he dies at Kampar two years later, and his sons found the Sultanates of Perak and Johor."]]},
  "Chenla": {t:["Chenla is a Chinese label: most historians now hold that it was never a unitary kingdom but a series of loose and temporary confederations of Khmer principalities, Michael Vickery's 'Dângrêk Chieftains'.","Isanavarman I, whose embassy reached the Sui court in 616–17 and whose capital was Isanapura (Sambor Prei Kuk), absorbed the territories of Funan and called himself King of Kings ruling 'Suvarnabhumi as far as the sea'.","After 707 the Tang histories divide Chenla into Land and Water Chenla; Water Chenla fell to the Javanese around 790, while from Land Chenla Jayavarman II proclaimed the Khmer Empire in 802."],dyk:"Judith Jacob found fourteen categories of slaves in Chenla's inscriptions, distinguished by origin and duty; they could be bought, sold and given away, bound by their parents' debts or born into bondage.",ev:[["598","On 13 April Narasimhagupta, vassal of Bhavavarman I, erects a figure of Vishnu at Isanapura; the same year Bhavavarman builds a temple at the centre of his kingdom of Bhavapura."],["616–617","Isanavarman I sends the first Chenla embassy to the Sui court; the Sui annals of 636 are the oldest Chinese text to name Chenla."],["627–649","Chenla subdues Funan; the New Book of Tang credits Isanavarman with annexing its territory at the beginning of the Zhenguan era."],["657","On 14 June Jayavarman I, son of Candravarman, issues his earliest inscriptions; his reign of about thirty years is the last over a united Chenla."],["707","After the end of the Shenlong era the Tang histories record Chenla divided into Land Chenla (Wendan) and Water Chenla."],["713","On 5 April Queen Jayadevi, ruling at Angkor, complains of 'bad times' in her Western Baray inscription as the kingdom breaks into principalities."],["c. 790","The last king of Water Chenla is killed and his realm absorbed into the Javanese monarchy; Jayavarman II and Indrayudha defeat a Cham army and found Hariharalaya."],["802","Jayavarman II proclaims the Khmer Empire, ending the pre-Angkor period."]]},
  "Funan": {t:["Funan is generally considered the first known kingdom in Southeast Asia, though its own name is unknown: 'Funan' is Chinese, and its people may have been Khmer, Austronesian or a mixture of both.","Roman gold medallions of Antoninus Pius and Marcus Aurelius and Persian, Indian and Greek goods found at Óc Eo show a trading state that may have been Ptolemy's Kattigara, where Roman and Chinese merchants met.","Fan Shiman, the 3rd-century 'Great King of Funan', built great ships, attacked more than ten kingdoms and extended his territory five or six thousand li before dying on campaign against Chin-lin, the 'Frontier of Gold'."],dyk:"A group of Funanese musicians visited China in 263 CE and so impressed the emperor that he ordered an institute for Funanese music to be founded near Nanking.",ev:[["1st century CE","By the legend in the Book of Liang, the foreigner Hùntián lands in the Mekong Delta, marries the queen Liǔyè and founds Funan."],["225–230","The first Funanese embassy reaches Lü Dai, governor of Eastern Wu; a second follows in 243, and the envoys Kang Tai and Zhu Ying sojourn in Funan."],["243","Fan Chan sends embassies to India and China; around 245 the Chinese describe walled villages, palaces, archives and taxes paid in gold, silver, pearls and perfumes."],["5th century","The Brahmin Qiáochénrú (Kaundinya) is chosen king at Pánpán and changes all the laws to conform to the system of India."],["480","Jayavarman, 'Protégé of Victory', begins a reign that lasts until his death in 514."],["514","Rudravarman kills his brother Gunavarman for the throne and becomes the last known king of Funan, reigning to about 545."],["6th century","Chenla, Funan's vassal, subjugates the capital T'e-mu and the king migrates south to Nafuna."],["627–649","Isanavarman of Chenla annexes the territory of Funan at the beginning of the Zhenguan era."]]},
  "Medang Kingdom": {t:["The 150 years from Panangkaran to Balitung (760–910) were the apogee of classical Javanese civilisation, when Kalasan, Sewu, Borobudur and Prambanan rose on the Kedu and Kewu plains.","Under the Shailendras Javanese fleets raided Tonkin in 767 and Champa in 774 and 787, Dharanindra took Ligor and became Maharaja of Srivijaya, and the young Jayavarman II lived at the Javanese court before proclaiming Cambodia's independence in 802.","The centre moved to East Java about 929 under Mpu Sindok; Dharmawangsa's naval invasion of Srivijaya in 990 failed, and in 1016–1017 the vassal king of Wurawari destroyed the palace and killed him at his daughter's wedding."],dyk:"A 10th-century Arab account describes 1,000 boats of the Waqwaq, probably Javanese or Srivijayan, attacking Qanbaloh on the East African coast in 945–946 for ivory, ambergris and Bantu slaves; Javanese inscriptions of 931 and 1053 record labour brought from Jenggi, Zanzibar.",ev:[["732","Sanjaya erects a lingga on the hill at Canggal; the inscription names him Rakai Mataram Sang Ratu Sanjaya, lord of Mataram."],["778","Panangkaran builds the Kalasan temple to the goddess Tara and a monastery for Buddhist monks of the Shailendra realm."],["787","Javanese fleets raid Champa a second time and burn the temple at Phan Rang, after demolishing Po Nagar at Nha Trang in 774."],["825","Samaratungga completes Borobudur, the stone mandala begun under Dharanindra."],["856","The Shivagrha inscription records Rakai Pikatan's victory over a rebel in a hill fortress and the consecration of the Shiva temple at Prambanan."],["898","On 10 May Balitung takes the throne, reunites the kingdom after thirteen years of turmoil and for the first time brings parts of East Java under Mataram."],["929","Mpu Sindok moves the capital to Tamwlang in East Java and founds the Isyana dynasty."],["1016–1017","Haji Wurawari attacks from Lwaram, destroys the palace and kills Dharmawangsa and most of the royal family: the pralaya of Mataram."]]},
  "Pyu city-states": {t:["Twelve walled cities have been excavated, five of them large: Beikthano, Maingmaw, Binnaka, Halin and Sri Ksetra, the last more than 13 km round and larger than Pagan or Mandalay; three have been World Heritage Sites since 2014.","The Pyu were the first in Southeast Asia to adapt Brahmic script to a tonal language, and their calendar, begun at Sri Ksetra on 22 March 638, became the Burmese calendar still used in Myanmar.","Nanzhao's raids from 754 culminated in 832, when its warriors overran the Pyu country and carried off 3,000 prisoners from Halin; the Burmans then took over the Pyu realm, and by the 13th century the Pyu had become Burmans."],dyk:"Tang records describe the Pyu as a humane people to whom war was virtually unknown, who wore silk cotton rather than silk so as not to kill silkworms, and whose boys entered the monastery from the age of seven until twenty.",ev:[["c. 2nd century BCE","Tibeto-Burman-speaking Pyu enter the Irrawaddy valley from Yunnan by the Taping and Shweli rivers and settle the plains around the Irrawaddy–Chindwin confluence."],["70 CE","Halin's wooden city gates, its earliest dated artefacts, are made; the city in the Mu valley grows into the largest Pyu centre."],["80 CE","The Pyu adopt the Sakra Era, two years after it came into use in India."],["638","On 22 March the Vikrama dynasty at Sri Ksetra launches a new calendar, which later becomes the Burmese calendar."],["739","On 25 March King Duttabaung founds Sri Ksetra's second dynasty."],["801","Sri Ksetra's embassy, with 35 musicians singing in Sanskrit, reaches the Tang court."],["832","Nanzhao warriors overrun the Pyu country and take 3,000 prisoners from Halin."],["c. 1020","The main walls of Pagan are built; the Burmans have taken over the Pyu realm and found the Pagan Empire in the mid-11th century."]]},
  "Rhodesia": {t:["Ian Smith's cabinet declared independence on 11 November 1965 to forestall Britain's policy of no independence before majority rule; no state ever recognised Rhodesia, and United Nations Security Council Resolution 216 called on all states to deny it recognition and assistance.","In 1976 the country held 270,000 white Rhodesians and six million black Africans, yet under the 1961 constitution whites held 50 of the 66 seats in the Assembly and the republican constitution of 1969 reserved the majority of seats for whites.","ZANU's ZANLA and ZAPU's ZIPRA fought the Rhodesian Bush War from the Sinoia engagement of April 1966; by 1978–79 defence took 47% of the budget, and the Lancaster House Agreement of late 1979 ended the rebellion."],dyk:"From 1975 to 1980 the Rhodesian security forces ran a chemical and biological warfare programme: they contaminated supplies planted in guerrilla caches and rural stores with parathion and thallium, poisoned water sources along infiltration routes, and used Vibrio cholerae, the agent of cholera.",ev:[["1965","On 11 November the Cabinet of Rhodesia issues a unilateral declaration of independence from the United Kingdom; Governor Sir Humphrey Gibbs dismisses Ian Smith and his ministers, who ignore him."],["1965","On 12 November United Nations Security Council Resolution 216 calls on all states not to recognise 'this illegal racist minority regime in Southern Rhodesia'."],["1966","On 28 April seven ZANLA insurgents are cornered and killed near Sinoia, the first engagement of the Rhodesian Bush War, kept by ZANU as Chimurenga Day."],["1970","On 2 March Rhodesia declares itself a republic after a referendum of 1969 severed the last ties with the Crown by 61,130 votes to 14,327."],["1972","On 21 December ZANLA insurgents under Rex Nhongo cross from Mozambique and raid a commercial farm, opening the raids on white farmers across the north-east."],["1975","The end of Portuguese rule in Mozambique after the Carnation Revolution leaves Rhodesia almost surrounded by hostile states."],["1978","On 3 September ZIPRA fighters shoot down the Air Rhodesia Viscount Hunyani near Kariba with a surface-to-air missile and kill 10 of its 18 survivors."],["1979","On 1 June under the Internal Settlement Abel Muzorewa becomes the first black prime minister of the renamed Zimbabwe Rhodesia; the Lancaster House Agreement ends UDI in December."]]},
  "Gold Coast Colony": {t:["The British Crown took over the African Company of Merchants' nine forts in 1821; the Bond of 1844, by which Fante and other chiefs submitted murder and robbery to British jurisdiction, laid the legal basis of the colony proclaimed on 24 July 1874.","British rule was imposed on Asante by war: Kumasi was burnt in 1874, occupied again in 1896 when the asantehene was exiled, and annexed as a colony in 1902 after the War of the Golden Stool.","Cacao trees introduced in 1878 became the colony's mainstay; by the end of the 1940s the Gold Coast exported more than half of the world's cocoa, grown largely by African farmers."],dyk:"Kwame Nkrumah won his seat in the Legislative Assembly election of February 1951 while in jail for sedition; the governor, Sir Charles Arden-Clarke, released him and invited him to form a government as 'leader of government business'.",ev:[["1821","The British Crown dissolves the African Company of Merchants and places its Gold Coast forts under Charles MacCarthy, governor of Sierra Leone."],["1824","MacCarthy is killed and most of his force wiped out in a battle with Asante forces; a British, Fante and Accra force defeats an Asante invasion of the coast in 1826."],["1844","Commander Henry Worsley Hill negotiates the Bond of 1844 with Fante and other chiefs, who submit murder and robbery to British jurisdiction."],["1874","Sir Garnet Wolseley's force occupies and burns Kumasi in January; the coastal protectorate is proclaimed the Gold Coast Colony on 24 July."],["1896","A second British expedition occupies Kumasi, makes Asante a protectorate and exiles the asantehene."],["1902","After the War of the Golden Stool of 1900 Asante is proclaimed a colony and the Northern Territories a protectorate under the governor of the Gold Coast."],["1948","Rioting in Accra and other towns over ex-servicemen's pensions, housing and the foreign hold on the economy; Nkrumah and the UGCC's 'Big Six' are detained."],["1957","On 6 March the Colony of the Gold Coast becomes independent as Ghana."]]},
  "Ibadan": {t:["Ibadan came into being in 1829, in the turmoil that destroyed Old Oyo, Ijaye and Owu, as a war camp of warriors from Oyo, Ifẹ and Ijebu on a forested range of hills at the fringe of the grassland.","Where most Yoruba cities had hereditary kings, Ibadan was a military republic run by four chiefs, three offices open to all freeborn men and one reserved for women, and the warrior class was its dominant and wealthiest group.","In 1840 the armies of Ibadan decisively defeated the Sokoto Caliphate's southward advance, and between the 1860s and 1890s the city-state ruled an empire over much of northern and eastern Yorubaland."],dyk:"Ibadan's name is coined from 'Eba-Odan', 'by the edge of the meadow': the camp stood where the forest met the grassland, which made it both a strongpoint and a market for the goods of both zones.",ev:[["1829","Ibadan comes into existence as a war camp for warriors from Oyo, Ifẹ and Ijebu, amid the turmoil in which Old Oyo, Ijaye and Owu disappear; by the end of the year it dominates the Yoruba region."],["1840","The armies of Ibadan decisively defeat the Sokoto Caliphate's attempt to expand into the south, halting its progress."],["1852","The Church Missionary Society sends David and Anna Hinderer, who found a mission and church in the city in 1853 and open its first Western school."],["c. 1865","In the 1860s Ibadan becomes the centre of an empire extending over much of northern and eastern Yorubaland, a position it holds into the 1890s."],["1893","On 15 August Fijabi, the Baale of Ibadan, signs a treaty with George C. Denton, acting Governor of Lagos Colony, and the Ibadan area becomes a British protectorate."]]},
  "Malindi": {t:["Malindi was a Swahili town of coral houses and patrician families whose elders, the wazee, elected a chief, the mwenye mui; the Portuguese mistook these men for kings.","In 1414 the fleet of Zheng He visited the town and Malindi's ruler sent an envoy with a giraffe to China; in 1498 Vasco da Gama was warmly received, after his hostile reception in Mombasa, and raised the pillar that still stands.","Malindi used the Portuguese against its rivals: it supported their conquest of Kilwa and Mombasa in 1505, held their factory from 1502 to 1593, and in 1593 its Sheikh took possession of Mombasa itself."],dyk:"Vasco da Gama came to Malindi in 1498 to sign a trade agreement and to hire a guide for the voyage to India; the padrão he erected, the Vasco da Gama Pillar, was in 1823 the only vestige of 'the once splendid city of Melinda' that a British Admiralty chart could find.",ev:[["c. 1250","After two centuries of sparse habitation following the destruction of the first town around 1000, Malindi recovers and prospers."],["c. 1300","Abu al-Fida (1273–1331), the Kurdish geographer, makes the first written reference to the present-day Malindi, south of the mouth of a river rising hundreds of miles inland."],["1414","The fleet of the Chinese explorer Zheng He visits the town, and Malindi's ruler sends an envoy with a giraffe as a present to China."],["1498","Vasco da Gama meets the Malindi authorities, signs a trade agreement, hires a guide for India and erects a padrão; the town has 5,000 to 10,000 people."],["1500","King Dom Manuel I of Portugal offers Malindi vassal status; a Portuguese trading post had been set up in 1499 and a factory follows in 1502."],["1505","Malindi supports the Portuguese conquest of its rivals Kilwa and Mombasa, and flourishes as merchants, craftsmen and sailors flock to it."],["1593","The Portuguese move their main base to Mombasa, surrendered by the Segeju to the Sheikh of Malindi, who moves his court there and rules until 1630."]]},
  "Kingdom of Ife": {t:["In Yoruba religion Oduduwa descended on a chain, cast earth on the primordial ocean and founded Ilé-Ifẹ̀ as the first city; his sons, daughters and grandchildren went out to found Ila Orangun, Owu, Ketu, Sabe, Egba, Popo, Ijesha and Oyo, and his son Oranmiyan the second dynasty of Benin.","Between 1200 and 1400 the artists of Ife made naturalistic sculptures in terracotta, stone and copper alloy, many under the patronage of King Obalufon II, honoured as the inventor of bronze casting in a life-size copper mask.","The sacred grove of Igbo Olokun held one of the earliest known glass workshops in West Africa, at its peak from the eleventh to the fifteenth century; its high-lime, high-alumina beads have been found at Igbo-Ukwu, Gao, Essouk and Kissi."],dyk:"Ife is called the city of 401 deities: the Ooni is counted the 401st orisha, the only one that speaks, and traditional worshippers are said to celebrate a festival of one deity on every day of the year.",ev:[["c. 900","By 900 Ifẹ̀, founded between 1000 and 500 BCE, has become an important West African emporium producing sophisticated art."],["c. 1050","Glass production is under way at the sacred grove of Igbo Olokun, if it has not begun earlier; the eleventh to fifteenth centuries are its peak."],["c. 1200","From the twelfth to the fourteenth century the city is a settlement of substantial size, its houses laid with potsherd pavements."],["c. 1300","The artists of Ife develop a refined naturalistic tradition in terracotta, stone and copper alloy, much of it under King Obalufon II."],["c. 1400","After 1400 production of the sculptures declines as political and economic power shifts to the neighbouring kingdom of Benin, which, like Oyo, grows into a major empire."],["c. 1650","The distinct Yoruba glassmaking technology persists in the Osun Grove into the seventeenth century."],["c. 1850","In the mid-nineteenth century the Oyo Empire, founded from Ife by Oranmiyan and stretching at its height from the Niger to the Volta, collapses."]]},
  "Derg": {t:["The Coordinating Committee of the Armed Forces, Police and Territorial Army, fewer than 110 privates, NCOs and junior officers, deposed Emperor Haile Selassie on 12 September 1974, killed sixty officials of his government on 23 November and abolished the monarchy in March 1975.","The Red Terror of 1976–1978 killed tens of thousands without trial, by the highest estimates up to 980,000, among them members of the rival Marxist-Leninist EPRP and MEISON; Mengistu Haile Mariam, chairman after the shootout of 3 February 1977, intensified it.","The famine of 1983–85, which the Derg itself estimated at more than a million deaths, was deliberately worsened in the rebel areas of Tigray and Eritrea as a counter-insurgency strategy, and the regime's enforced resettlement killed between 50,000 and 100,000 more."],dyk:"The Derg was said to have 120 members at its founding in 1974, in fact fewer than 110, and it never admitted a new one; by 1980 expulsions and killings had reduced it to 38, all but three of them Amhara.",ev:[["1974","The Derg is established as the Coordinating Committee of the Armed Forces, Police and Territorial Army by junior and mid-level officers; announced on 28 June, it elects Major Mengistu Haile Mariam chairman."],["1974","On 12 September the Derg deposes and imprisons Emperor Haile Selassie during nationwide protests; three days later it renames itself the Provisional Military Administrative Council."],["1974","On 23 November the Derg removes and kills its chairman, Lieutenant General Aman Andom, with some of his supporters and 60 officials of the imperial government, the Massacre of the Sixty."],["1975","On 4 March the land reform 'Land to the Tiller' nationalises all rural land and abolishes tenancy; the monarchy is formally abolished the same month, and Haile Selassie dies on 27 August."],["1976","On 23 September the Red Terror begins after a failed attempt on Mengistu's life attributed to the EPRP; in less than two years up to 980,000 people are killed by the highest estimates."],["1977","On 3 February Chairman Tafari Benti is killed in a shootout and Mengistu takes power; Vice-Chairman Atnafu Abate is executed with 40 officers on 13 November; Somalia invades the Ogaden."],["1983–1985","Famine in northern Ethiopia, multiplied by the government's policies in the rebel regions, kills about 1.2 million people; Live Aid raises money in July 1985."],["1987","On 22 February the Derg government ends after a referendum approves the constitution of the People's Democratic Republic of Ethiopia; the Derg is formally abolished in September, its members keeping power."]]},
  "Sultanate of Ifat": {t:["Ibn Sa'id al-Maghribi placed the capital Wafāt on high ground in a river valley where the people grew bananas and sugar cane; al-Umari counted seven cities, an army of 20,000 soldiers and 15,000 horsemen, and a ruler who wore headbands of silk.","Sabr ad-Din's rebellion of 1332 aimed to make him king of all Ethiopia, turn the churches into mosques and set the Christian queen to grind corn; Emperor Amda Seyon destroyed Ifat's capital, looted his camp of gold and slaves, imprisoned him and installed his brother Jamal ad-Din I.","Haqq ad-Din II moved the capital to the Harar plateau and fought the emperor in more than twenty battles before dying in 1376; his brother Sa'ad ad-Din II was defeated in 1403 and killed at Zeila, after which, al-Maqrizi wrote, 'the strength of the Muslims was abated'."],dyk:"When Emperor Amda Seyon threatened in 1320 to divert the Nile and starve Egypt unless the Mamluk sultan al-Nasir Muhammad stopped persecuting the Copts, the Egyptians dismissed it as an idle threat; the fear that Ethiopia might tamper with the Nile nonetheless stayed with them for centuries.",ev:[["c. 1275","Sultan Umar Walasma, founder of the dynasty, dies after carving out his kingdom and conquering the Sultanate of Shewa; 'four or five sons' rule briefly before Sabr ad-Din I."],["1288","Sultan Wali Asma imposes his rule on Hubat, Zeila and the other Muslim states of the region."],["1320","Haqq ad-Din I invades Amhara, burns churches, forces conversions and kills the emperor's envoy; Amda Seyon I raids Shewa and Ifat, and Dadader Haqq ad-Din falls at the battle of Marra Biete."],["1332","Sabr ad-Din rebels to become 'King of all Ethiopia'; Amda Seyon destroys the capital of Ifat, imprisons him and appoints Jamal ad-Din I in his place."],["1376","Haqq ad-Din II, who moved the capital to the Harar plateau and fought over twenty battles with the emperor, dies in battle; his brother Sa'ad ad-Din II succeeds."],["1403","Ifat's troops are defeated on the Harar plateau; Sa'ad ad-Din II flees to Zeila and is killed there, by al-Maqrizi's account (another source dates his death to 1410 under Emperor Yeshaq)."]]},
  "Kingdom of Dagbon": {t:["The Lunsi, the drummer-historians of the court, trace the royal line to Tohazhie the Red Hunter, who left Tunga east of Lake Chad for Zamfara and Mali, and to Naa Gbewaa, who settled at Pusiga and whose children founded Mamprugu, Nanung and, through his daughter Yennenga, the Mossi kingdoms.","Naa Nyagsi (r. 1416–1432) overthrew many of the Tindaamba, the earth priests who had led the Dagomba towns, set his sons, brothers and uncles over the conquered peoples and made his capital at Yani Dabari; the surviving tindaamba kept their ritual office.","At the Battle of Adibo in 1896 about 7,000 Dagomba with bows and arrows charged a German force of 100 well-armed men under Valentin von Massow, Hans Gruner and Gaston Thierry; it was a massacre, Yendi was destroyed and the Gbewaa Palace burnt."],dyk:"Dagbon's scholars of the house of Moliyili wrote in a modified Arabic script, lexically Arabic but syntactically Dagbani; their manuscripts on law, pilgrimage, medicine and metallurgy were burned in the German invasion, and much of what survived was carried to Denmark in the twentieth century.",ev:[["c. 1400","In the fifteenth century Naa Gbewaa unifies the Dagomba and related peoples ruled by the Tindaamba and settles at Pusiga, where he rules until he goes blind; his grave is there."],["1416–1432","Naa Nyagsi wages a war of expansion, overthrows many of the Tindaamba and establishes his capital at Yani Dabari near Tamale."],["1788","Yendi, the capital since the Gonja wars, is said to be bigger than Kumasi and Salaga."],["1888","Dagbon is placed in the neutral Salaga Area, from Yeji to Yendi, agreed between the Germans and the British to forestall conflict."],["1896","The Germans defeat the Dagomba at the Battle of Adibo, destroy Yendi and burn the Gbewaa Palace; Eastern Dagbon falls to German Togoland."],["1899","Yaa Naa Andani II dies in August; the British and Germans split Dagbon between German Togoland and the Gold Coast."],["1900","On 7 April Friedrich Rigler's German expedition attacks the Dagomba who had fled to Sang in British territory, kills at least 83, among them Andani's son Idi, and installs Alasan as Yaa Naa."]]},
  "Kingdom of Loango": {t:["Njimbe's constitution rotated the throne among the rulers of four provinces, Kaye, Boke, Selage and Kabango, the ruler of Kaye succeeding when the king died.","Loango exported considerable copper to the European market and thousands of metres of cloth to Portuguese Luanda in the early seventeenth century; from the late seventeenth century its Vili merchants also traded in slaves on a considerable scale.","After King Buatu died in 1787 no king was elected for over a hundred years; a priest called the Nganga Mvumbi, who guarded the unburied body of the dead king, kept what remained of royal authority."],dyk:"European ships never built permanent factories at Loango: they anchored offshore and dealt with royal officials called mafouks, who managed trade in the king's interest and kept direct European influence at arm's length.",ev:[["c. 1561","Sebastião de Souto, a priest in Kongo, records that King Diogo I has sent missionaries to convert Loango: the earliest documentary mention of the kingdom."],["c. 1565","Njimbe, very likely the founder and first ruler of the traditions, takes the throne and reigns for 60 years, according to a Dutch description of 1625."],["c. 1610","The English traveller Andrew Battel visits Loango and names Gembe, or Njimbe, as the predecessor of the reigning king."],["c. 1640","Olfert Dapper's Dutch informants describe the government, religion and founding traditions of Loango, the only comprehensive account of the seventeenth century."],["1663","The Capuchin Bernardo Ungaro baptises the king as Afonso, and 6,000 of his subjects with him; a civil war between Christian and non-Christian parties follows his death."],["1683","Queen Verónica I of Ndongo-Matamba promises by treaty to stop trading with the Vili merchants operating in the Mbundu-speaking regions of eastern Angola."],["1766","French missionaries under Abbé Liévin-Bonaventure Proyart find a king who came to power only after a seven-year interregnum managed by a regent, the Mani Boman."],["1787","King Buatu dies and no successor is elected for over a hundred years; the Nganga Mvumbi holds residual royal authority."]]},
  "Republic of Cuba (1902-1959)": {t:["From 1902 to 1934 the Platt Amendment, written into both Cuban and American law, gave the United States the right to intervene in Cuba, restricted its foreign relations and leased it the naval base at Guantánamo Bay.","Sugar ruled its politics: the First World War boom and the 1920 crash known as the Dance of the Millions ruined the country and handed more power to foreign investors, and by 1959 American firms owned about 40 per cent of the sugar land, 90 per cent of the mines and 80 per cent of the utilities.","The 1940 constitution wrote the right to work and to health care into law, but after his coup of 1952 Batista suspended it, and his secret police killed between hundreds and about 20,000 people before he fled in December 1958."],dyk:"In 1950 Cuba became the first country in Latin America to broadcast television, and by the late 1950s it had the ninth highest number of television sets and the fourth highest number of channels of any country in the world.",ev:[["1902","On 20 May Cuba gains formal independence as the Republic of Cuba, its constitution granting the United States the right to intervene under the Platt Amendment."],["1906","After a rigged election veterans rise in the August Revolution; President Tomás Estrada Palma resigns with his cabinet, and the United States occupies the island until 1909."],["1912","The Partido Independiente de Color's attempt to set up a separate Black republic in Oriente is crushed by the army under General Monteagudo with considerable bloodshed."],["1920","Sugar prices peak and crash in the Dance of the Millions, ruining the country financially and strengthening foreign investors."],["August 1933","A general strike, sugar workers' uprisings and an army revolt force Gerardo Machado into exile; in September the Sergeants' Revolt under Fulgencio Batista overthrows his successor."],["1934","The Treaty of Relations ends the Platt Amendment, binding Cuba to favour the American economy in return for a guaranteed 22 per cent of the U.S. sugar market."],["1940","A new constitution with the rights to labour and health care is adopted, and Batista is elected president."],["1952","Batista seizes power in a coup before the presidential election, suspends the 1940 constitution and revokes most political liberties."]]},
  "Confederate States of America": {t:["Historians widely agree that preserving slavery was the principal aim of secession, as the states' own secession documents show; in 1860 enslaved people were 39 per cent of the eleven states' population and 31 per cent of free households owned slaves.","Its permanent constitution copied much of the United States Constitution verbatim but added explicit protections for slavery in every territory, forbade any state to bar slaveholders from bringing their slaves in, and kept the ban on the African slave trade.","Outnumbered about four to one in military manpower and far more in industry and railroads, the Confederacy passed the first national conscription in North America on 16 April 1862, financed itself by printing money until flour cost $100 a barrel in Richmond, and won recognition from no foreign government."],dyk:"No foreign government ever recognised the Confederacy: when Ambrose Dudley Mann reported a letter from Pope Pius IX addressed to \"the Illustrious and Honorable Jefferson Davis, President of the Confederate States of America\", Secretary of State Judah P. Benjamin replied that Mann had mistranslated it and that it was \"a mere inferential recognition\".",ev:[["1860","On 20 December South Carolina votes unanimously for secession after Abraham Lincoln's election; Mississippi, Florida, Alabama, Georgia, Louisiana and Texas follow by 1 February 1861."],["1861","On 8 February delegates at the Montgomery Convention form the Confederate States of America; Jefferson Davis is elected provisional president the next day."],["1861","On 12 April Confederate forces under Beauregard bombard and take Fort Sumter in Charleston harbor; Lincoln calls up 75,000 militia and Virginia, Arkansas, Tennessee and North Carolina secede."],["1862","Davis is inaugurated under the permanent constitution for a six-year term; the Permanent Congress has opened in Richmond on 18 February."],["1862","On 16 April the Confederate Congress imposes the first mass conscription on North American territory, making white men from 18 to 35 soldiers for three years."],["September 1862","Lee's invasion of Maryland is turned back at Antietam and Bragg's of Kentucky fails; Lincoln's preliminary Emancipation Proclamation ends British and French thoughts of recognition."],["July 1863","Vicksburg and Port Hudson fall, closing the Mississippi, and Lee's strike into Pennsylvania is repulsed at Gettysburg; the Confederacy withdraws into an interior defence."],["1865","On 9 April Richmond having fallen when Lee's lines broke at Petersburg, Lee surrenders at Appomattox Court House; Davis is captured on 10 May and the last land forces surrender by June."]]},
  "Colonial Brazil": {t:["Brazil was a slave society from the outset: about 35 per cent of all Africans taken in the Atlantic slave trade were sent there, more than ever reached the Thirteen Colonies, and the trade lasted longer than in any other country of the Americas.","Sugar made the colony: from 1600 to 1650 it was 95 per cent of exports, and in the Bahia sugar regions owners found it cheaper to work the enslaved to death over a few years and buy replacements.","The enslaved fled to fortified settlements called quilombos; the largest, the Quilombo dos Palmares under Ganga Zumba and Zumbi, grew to many thousands and held out until Domingos Jorge Velho destroyed it and killed Zumbi in 1695."],dyk:"Only two of the fifteen hereditary captaincies into which John III divided Brazil in 1534–1536 prospered: Pernambuco by growing sugar, and São Vicente chiefly by capturing Indigenous people to trade them as slaves.",ev:[["1500","On 22 April Pedro Álvares Cabral's fleet of 13 ships lands at what is now Porto Seguro and takes possession of the land in the name of Manuel I."],["1534–1536","John III divides the land into fifteen hereditary captaincies; only Pernambuco and São Vicente prosper."],["1549","Tomé de Sousa arrives as first governor-general with the first Jesuits and founds the capital, Salvador, on All Saints Bay."],["1565","Estácio de Sá founds Rio de Janeiro in the war against France Antarctique; the last French settlers are expelled in 1567."],["1630–1654","The Dutch West India Company holds Recife, Olinda and the sugar coast as Dutch Brazil until it withdraws in 1654."],["1695","An army under Domingos Jorge Velho destroys the Quilombo dos Palmares and kills Zumbi."],["1763","The capital of the State of Brazil moves from Salvador to Rio de Janeiro, nearer the gold of Minas Gerais."],["1808","Prince Regent John and the Portuguese court arrive in Brazil, fleeing Napoleon, and open its ports to friendly nations."]]},
  "Saint-Domingue": {t:["By the 1780s Saint-Domingue produced about 40 per cent of the sugar and 60 per cent of the coffee consumed in Europe, more than all the British West Indies together, and its taxes were a major source of the French budget.","Between 1681 and 1791 an estimated 790,000 to 860,000 enslaved Africans were brought to its plantations, a third of the whole Atlantic slave trade in 1783–1791; some 5 to 10 per cent died every year, so the population was kept up only by constant importation.","Enslaved Africans and Creoles planned their rising at the Vodou ceremony of Bois Caïman in 1791; slavery was abolished in 1793, Toussaint Louverture's constitution of 1801 declared it abolished for ever, and the French army sent to restore it was beaten at the Battle of Vertières on 18 November 1803."],dyk:"Deported to France in 1802, Toussaint Louverture warned his captors: \"In overthrowing me you have cut down in Saint-Domingue only the trunk of the tree of liberty; it will spring up again from the roots, for they are numerous and they are deep.\"",ev:[["1665","Louis XIV officially recognises French colonisation of Hispaniola and Tortuga, with slavery-based plantation agriculture and cattle farming."],["1685","The Code Noir regulates slavery and grants freed people full citizenship; the colony's first sugar windmill is built."],["1697","By the Peace of Ryswick Spain tacitly recognises French control of Tortuga and the western third of Hispaniola."],["1758","Mackandal, the one-armed maroon leader who united the maroon bands and raided for six years, is captured after a plot to poison the planters' water and burned alive at Cap-Français."],["1789","Some 8,000 plantations worked by 406,000 to 465,000 enslaved people produce half the sugar and coffee consumed in Europe and the Americas."],["1791","After the Vodou ceremony at Bois Caïman the enslaved of the northern plain rise, killing 2,000 Creoles and burning 280 sugar plantations within two months."],["1793","Civil Commissioner Léger-Félicité Sonthonax abolishes slavery in the colony by emancipation proclamation; Toussaint Louverture joins the Republic."],["1803","On 18 November Dessalines's army defeats the French at the Battle of Vertières near Cap-Haïtien; the last French troops withdraw and Haiti declares independence in 1804."]]},
  "United Provinces of the Río de la Plata": {t:["The Primera Junta swore loyalty to the captive Ferdinand VII but refused the authority of Spain's Council of Regency, and historians still debate whether the \"Mask of Ferdinand\" hid independence as the goal from the start.","The Assembly of the Year XIII freed the children of slaves, abolished the Inquisition, torture, noble ranks and the mit'a, encomienda and yanaconazgo, and approved the anthem and arms of Argentina, yet rejected Artigas's deputies and their demand for independence and federalism.","On 9 July 1816 the Congress of Tucumán declared independence from Ferdinand VII, his successors and metropole, in Spanish, Quechua and Aymara; San Martín's Army of the Andes then won Chacabuco and Maipú, while at home the Directory fell to the federal caudillos at Cepeda in 1820."],dyk:"Manuel Belgrano raised the new light blue and white flag at Rosario in 1812 without asking; the First Triumvirate ordered him to hide it and sent him a Spanish red and yellow one, but he had already left for the north and never received the message.",ev:[["1810","The May Revolution: an Open Cabildo dismisses Viceroy Cisneros and the Primera Junta takes power in Buenos Aires in the name of the captive Ferdinand VII."],["1811","On 20 June the First Upper Peru campaign ends in the Disaster of Huaqui; Paraguay has already repelled Belgrano and Montevideo's fleet has destroyed the Junta's squadron at San Nicolás."],["1813","On 31 January the Assembly of the Year XIII opens, abolishing the Inquisition, noble ranks and Indigenous labour drafts and freeing the children of slaves."],["1814","On 20 June after William Brown's victories at Martín García and Buceo, Montevideo surrenders and Alvear occupies the last royalist capital of the viceroyalty."],["1816","On 9 July the Congress of Tucumán declares the United Provinces in South America independent of Ferdinand VII, his successors and metropole."],["1818","On 5 April San Martín's United Army defeats the royalists at the Battle of Maipú, consolidating the independence of Chile."],["1820","The federal armies of López and Ramírez rout Rondeau's Directorial troops at Cepeda; on 11 February the Congress dissolves and the national government ends."],["1828","The Eastern Bank becomes independent as Uruguay after British intervention in the Cisplatine War; the Federal Pact of 1831 follows."]]},
  "El Perú-Waka'": {t:["The first recorded meeting between Teotihuacan and the Maya took place at Waka' in January 378, when the war leader Siyaj K'ahk' passed through roughly eight to ten days before taking over Tikal: the moment archaeologists call La Entrada.","Waka' abandoned its early alliance with Tikal for Calakmul, sealed by the marriage of K'inich Balam to a princess of the Kan dynasty who bore the high title ix kaloomté; Lady K'abel governed the Wak kingdom for the Snake dynasty between 672 and 692.","Tikal's ruler Yik'in Chan K'awiil defeated Waka' in 743, made it a vassal and carried off an image of a celestial serpent, possibly its patron deity; a decade later the city was destroyed and K'inich Balam's successor captured and sacrificed."],dyk:"Burial 39, the tomb of an early seventh-century king, held 23 ceramic figurines of a royal court at a ceremony, among them a kneeling king with the Maize God's hair, a female singer conjuring a deer spirit, a dwarf blowing a shell trumpet and two helmeted dwarfs who may be boxers.",ev:[["378","The Teotihuacan war leader Siyaj K'ahk' arrives at Waka' in January, ten days before reaching Tikal: La Entrada, the first recorded meeting of Teotihuacan and the Maya."],["c. 400","Waka' reaches its political peak with a population of tens of thousands, drawn by its location and trade."],["416","Stela 15, a text-only monument, is erected naming the kings back to the mid fourth century and recording Siyaj K'ahk's coming."],["672–692","Lady K'abel, daughter of Calakmul's king Yuknoom Yich'aak K'ak' and wife of K'inich B'ahlam II, governs the Wak kingdom as a lady warlord for the Kan dynasty."],["692","Stela 34 portrays Lady K'abel; her tomb, found in the main pyramid temple in 2012, held an alabaster jar naming Lady Water Lily Hand and Lady Snake Lord."],["732","Calakmul's ruler Yuknoom Took' K'awiil, likely the brother of Lady T'abi, is defeated, captured and sacrificed in Tikal's central plaza."],["743","Yik'in Chan K'awiil of Tikal defeats Waka', makes it a vassal and takes the image of its celestial serpent to Tikal, recorded on Temple IV."],["c. 753","About a decade after its defeat Waka' is destroyed and K'inich Balam's successor is captured and sacrificed."]]},
  "Republic of Texas": {t:["Texas declared independence from Mexico on 2 March 1836, after Santa Anna's Siete Leyes centralised the Mexican republic and he began enforcing laws against slavery, which Mexico had abolished in 1829 and which the Texians refused to end.","Its 1836 constitution made slavery a cornerstone of the state: slaves could not be freed without the consent of Congress, Congress could pass no law against slavery or the slave trade, and no free person of African descent could reside permanently in the republic.","Only seven nations recognised Texas, and its claim to the Rio Grande as its border, disputed by Mexico throughout, passed to the United States at annexation and led to the Mexican–American War."],dyk:"In 1839 Texas became the first nation in the world to enact a homestead exemption, under which creditors cannot seize a person's primary residence.",ev:[["1835","On 2 October hostilities between Texian settlers and Mexican troops open at the Battle of Gonzales, the first engagement of the Texas Revolution."],["1836","On 2 March the Convention of 1836 proclaims the Texas Declaration of Independence; David G. Burnet becomes interim president."],["1836","On 21 April major fighting ends, and the Treaties of Velasco, signed by Santa Anna as a prisoner, secure Texas's independence, which the Mexican Congress refuses to recognise."],["1837","On 3 March President Andrew Jackson appoints Alcée La Branche chargé d'affaires, the United States officially recognising the republic."],["1839","President Mirabeau B. Lamar moves the capital to the new town of Austin; the Lone Star Flag is adopted and France recognises Texas on 25 September."],["1840","After 34 Comanche leaders are massacred at peace talks in San Antonio, Buffalo Hump leads the Great Raid of 1840 to the Gulf coast; the Comanches are caught at the Battle of Plum Creek."],["1842","On 11 September Adrián Woll's 1,400 Mexican troops capture San Antonio; Texans fight at the Battle of Salado Creek while 53 surrendered volunteers are massacred nearby."],["1845","On 29 December Texas is annexed and admitted as the 28th state of the United States; power passes from the republic on 19 February 1846."]]},
  "New Netherland": {t:["The colony existed for the fur trade: the Dutch depended on Native nations to capture, skin and deliver beaver pelts, and after the Mohawks conquered the Mahicans in 1628 they held a near-monopoly of that trade.","Peter Minuit acquired Manhattan from unnamed Native people on 24 May 1626 for goods worth 60 guilders, a figure a historian turned into the famous $24 in 1846 by a faulty conversion.","Its 1664 Articles of Capitulation kept the liberty of conscience New Netherlanders already enjoyed, and the Flushing Remonstrance of 1657 is counted a precursor of the religious-freedom clause in the United States Bill of Rights."],dyk:"New Amsterdam's wal, the rampart that gave Wall Street its name, was built out of fear of an English invasion; when four English frigates finally came in 1664 the town surrendered without resistance.",ev:[["1609","Henry Hudson, hired by the Dutch East India Company, sails the Halve Maen into Upper New York Bay and up the river that bears his name as far as the site of Troy."],["1614","On 17 March the States General grants an exclusive trade patent between the 40th and 45th parallels; traders of the New Netherland Company build Fort Nassau near Albany."],["1621","On 3 June the Dutch Republic charters the Dutch West India Company with exclusive rights in West Africa and the Americas."],["May 1624","New Netherland becomes a province; 30 families land at Fort Orange and Noten Eylant from the ship Nieu Nederlandt under Cornelius Jacobsen May, the first director."],["1626","On 24 May Peter Minuit and Walloon colonists acquire Manhattan for goods worth 60 guilders and build Fort Amsterdam at its southern tip."],["1629","The Charter of Freedoms and Exemptions creates the patroonships; Rensselaerswyck becomes the only truly successful one."],["1655","Director-general Peter Stuyvesant conquers New Sweden on the Delaware; Jews are granted full residency in New Amsterdam."],["1664","On 27 August four English frigates under Richard Nicolls demand the surrender of New Amsterdam, which falls without resistance."]]},
  "San people": {t:["The San, who call themselves by the names of their own nations such as the ǃKung, ǀXam and Khwe, descend from hunter-gatherer societies that some 10,000 years ago were spread from Tanzania to Cape Agulhas.","Traditionally semi-nomadic and egalitarian, they lived by hunting and gathering, took decisions by consensus with women as relative equals, and shared through a gift economy.","From the 18th century Dutch colonists’ commandos killed thousands of San at the Cape, and in 1777 the Dutch East India Company endorsed a policy of eradicating them; in Botswana the San have since been moved off land such as the Central Kalahari Game Reserve."],dyk:"In long droughts the San dig into damp sand and suck water up through a hollow grass stem, letting it run down a second straw into an empty ostrich egg.",ev:[["After 650 CE","As the Khoe and Xhosa move into the Eastern Cape, most San leave the coasts for the interior"],["1652","The Dutch settle at the Cape of Good Hope, where the Cape San number an estimated 30,000 to 50,000"],["c. 1714","The Dutch East India Company’s loan farm system sends Trekboer stock farmers into San lands"],["1777","The Dutch East India Company officially endorses a policy of eradicating the San"],["1863","Louis Anthing estimates that no more than 500 San are left in all of Bushmanland, facing starvation"],["1912–1915","The worst genocidal violence against the San in German South West Africa falls in the area from Otavi to Gobabis"],["2003","The San win a benefit-sharing agreement over their knowledge of the hoodia plant, and their representatives ask to be called by their own nations’ names"]]},
  "Khoekhoe": {t:["By one account a proto-Khoe people emerged between 400 BCE and 100 CE in southern Zimbabwe, as San peoples met herding communities drifting south from East Africa; with their sheep and later cattle, Khoekhoe herders spread south to the Cape.","In 1510 ox-mounted ǃUriǁ’aekua defeated the party of Francisco de Almeida at the Battle of Salt River, killing him and fifty of his men.","Smallpox, land seizure and war under Dutch rule broke up Khoekhoe society, and in German South-West Africa from 1904 to 1907 over 10,000 Nama, more than half the people, may have died."],dyk:"The International Astronomical Union has named the star Mu¹ Scorpii Xami di mûra, “eyes of the lion”, after its traditional name in the Khoekhoe language.",ev:[["400 BCE–100 CE","By Mellet’s account a proto-Khoe people emerges in southern Zimbabwe as San peoples meet herders from East Africa"],["After 1000 CE","Widespread Khoekhoe settlements and large herds appear south of the Orange River"],["1510","Ox-mounted ǃUriǁ’aekua defeat and kill Francisco de Almeida at the Battle of Salt River"],["1738","Georg Schmidt founds Genadendal among the Khoe-speaking peoples, the first mission station in southern Africa"],["1829","The Kat River Settlement gives Khoekhoe land of their own near the eastern frontier of the Cape Colony"],["1853","The Cape franchise gives the vote to men meeting a low property test, regardless of colour"],["1904–1907","In the war with German forces in German South-West Africa more than half of the Nama may die"],["1994","Apartheid ends, and with it the racial designation “Coloured” imposed on some Khoekhoe"]]},
  "Tuareg": {t:["The Tuareg, who call themselves Imuhagh, Kel Tamasheq (“speakers of Tamasheq”) and Kel Tagelmust (“veiled people”), are an Amazigh people whose founding queen, Tin Hinan, is believed to have lived in the 4th or 5th century.","Organised in confederations under an amenokal and ranked into nobles, vassals, clerics, artisans and enslaved people, they controlled trans-Saharan trade routes and ran salt caravans across the desert.","The Tuareg resisted French conquest from 1881 to 1920; after independence their homeland was divided among five states, and uprisings followed in Mali and Niger from the 1960s."],dyk:"Among the Tuareg it is the men, not the women, who traditionally veil their faces: a man takes on the tagelmust when he reaches maturity, as a rite of passage to manhood.",ev:[["4th–5th century","Tin Hinan, the Tuareg founding queen, leads her people south into the Sahel; her tomb stands at Abalessa in the Hoggar"],["7th century","Islam reaches North Africa with the Umayyad Caliphate, and the Tuareg in time adopt it"],["1449","A Tuareg ruling house founds the Sultanate of Agadez in the Aïr Mountains"],["1881","Tuareg fighters annihilate the French expedition led by Paul Flatters"],["1902","The French defeat the Kel Ahaggar at the Battle of Tit"],["1990","After a clash at Tchin-Tabaraden, Tuareg in Mali and Niger rise and claim independence for their homeland"],["1992–1995","Peace agreements in Mali and Niger decentralise power and bring Tuareg fighters into the national armies"],["April 2026","During the Mali War the Azawad Liberation Front captures Kidal and parts of Gao"]]},
  "Aboriginal Australians": {t:["The ancestors of Aboriginal Australians reached Sahul, the land that joined Australia and New Guinea, 50,000 to 65,000 years ago, and may have settled across the continent within 6,000 years of landing.","More than 400 distinct peoples, each with its own language and Country, pass down their beliefs through dance, stories, songlines and art, which together tell of creation in the Dreaming.","From 1788 British colonisation brought disease, frontier war and dispossession: in the 150 years that followed, 90% of Indigenous Australians died, and between 1910 and 1970 between 10 and 33 percent of Aboriginal children were removed from their families."],dyk:"A 2011 study of DNA from an early-20th-century lock of an Aboriginal person’s hair found that, outside Africa, Aboriginal peoples have lived continuously in the same territory longer than any other human population.",ev:[["1788","British colonisation begins at Port Jackson with the arrival of Governor Arthur Phillip and the First Fleet"],["1790","Pemulwuy begins a guerrilla war against the settlers around Sydney, carried on by his son Tedbury until 1810"],["1939","About 200 people leave Cummeragunja Station in protest at their treatment, in the Cummeragunja walk-off"],["1966","The Wave Hill Walk-Off begins, a strike over working conditions that grows into a claim to the land"],["1967","A referendum passed by a 90% majority gives Aboriginal affairs to the federal government and removes discriminatory census provisions from the Constitution"],["1976","The Aboriginal Land Rights Act lets Aboriginal people in the Northern Territory claim land by traditional association"],["1992","In the Mabo Case the High Court declares terra nullius invalid and recognises native title"],["2008","Prime Minister Kevin Rudd makes a formal apology for the Stolen Generations"]]},
  "Kalinago": {t:["Long described as invaders from South America who conquered the earlier Igneri, the Kalinago appear from archaeology and ancient DNA to have formed from the islands’ own peoples together with newcomers from the mainland.","They kept their independence in the Lesser Antilles against Spain and later France and England; Dominica and Saint Vincent were left to them as reserves in 1660, but the British had annexed both by 1763.","On Saint Kitts in 1626 English and French settlers massacred an estimated 2,000 Kalinago, and Spanish tales of Carib cannibalism, never backed by hard evidence, have been read as a campaign to justify such genocidal expeditions."],dyk:"The English word “cannibal” comes from the Kalinago word karibna, “person”, after Columbus spread stories of man-eating Caribs that he had apparently heard from their Taíno enemies.",ev:[["c. 1200 CE","By the traditional account, Caribs migrate from the Orinoco region of South America to the islands"],["1492","Columbus reaches the Caribbean and hears from the Taíno of Carib raids"],["1626","English and French settlers massacre an estimated 2,000 Kalinago at Bloody Point on Saint Kitts"],["1660","France and England make the Treaty of Saint Charles with the Kalinago, leaving them Dominica and Saint Vincent as reserves"],["1763","Britain has annexed Saint Lucia, Tobago, Dominica and Saint Vincent"],["1797","After the Second Carib War the British expel the Garifuna of Saint Vincent to Honduras"],["1903","The British government grants the Kalinago a territory of 3,700 acres on the east coast of Dominica"],["2015","Dominica officially changes the people’s name from Carib to Kalinago"]]},
  "Inuit": {t:["Inuit, “the people” in Inuktitut and Kalaallisut, descend from the Thule people, who spread east from the Bering Strait around 1000 CE and replaced the Dorset culture, the Tuniit of Inuit tradition.","They lived by hunting whales, seals, caribou and other animals, travelling by qajaq, umiaq and dog sled, and shared food within the household and, to a large extent, the whole community.","Disease, missionaries and Canadian policy, including the High Arctic relocation of the 1950s, transformed Inuit life, but Inuit organised from the 1970s and won land claims, among them the agreement that created Nunavut in 1999."],dyk:"A girl of about nine, buried near Utqiaġvik in Alaska around 1200 CE, had been born with a congenital defect and could never walk, yet her family had cared for her all her life.",ev:[["c. 1000 CE","The Thule people, ancestors of the Inuit, emerge from the Bering Strait and western Alaska and spread east across the Arctic"],["c. 1100 CE","Inuit migrants reach west Greenland and settle there"],["1576","Martin Frobisher’s search for the Northwest Passage brings the first well-documented contact between Europeans and Inuit, and he takes three Inuit captive to England"],["1953","In the High Arctic relocation the Canadian government moves 17 Inuit families from Inukjuak to Resolute and Grise Fiord"],["1971","Inuit found the Inuit Tapirisat of Canada, today Inuit Tapiriit Kanatami"],["1975","The James Bay and Northern Quebec Agreement settles the land claim of the Quebec Inuit, with autonomy in the new region of Nunavik"],["1979","Denmark grants Greenland home rule"],["1999","Nunavut is established as a territory of Canada under the Nunavut Land Claims Agreement of 1993"]]},
  "Navajo": {t:["The Navajo call themselves Diné, “the people”; their language, Diné bizaad, is Southern Athabaskan, and their ancestors are believed to have migrated from northwestern Canada and eastern Alaska.","From the Pueblo peoples they took up farming and loom weaving, and from the Spanish sheep and goats, which became a currency and a measure of standing in a matrilineal society where women’s families owned the herds, homes and fields.","In 1864 the US Army forced around 9,000 Navajo on the Long Walk to internment at Bosque Redondo; the treaty of 1868 let the survivors return to part of their homeland, which grew into the largest reservation in the United States."],dyk:"During the Second World War up to four hundred Navajo code talkers carried messages for the US Marine Corps in a code built on their own language, in which the word for “turtle” stood for a tank; the Japanese never deciphered it.",ev:[["1620s","Fray Geronimo de Zarate-Salmeron calls the people of the Chama Valley region Apachu de Nabajo, an early form of the name Navajo"],["1849","Colonel John MacRae Washington leads 400 soldiers into Navajo country and signs a treaty, and the Navajo peace leader Narbona is killed on the way to it"],["1863","On General James H. Carleton’s orders Kit Carson’s troops sweep through Navajo land, killing people, destroying crops and dwellings, fouling wells and seizing livestock"],["1864","The US Army forces around 9,000 Navajo men, women and children on the Long Walk of over 300 miles to internment at Bosque Redondo"],["1868","The Treaty of Bosque Redondo lets the surviving Navajo return to a reservation on part of their former homeland"],["1933","The federal government begins the Navajo Livestock Reduction, made mandatory in 1935"],["1942","Navajo transmitting Marine Corps combat simulations in their own language prove faster than any cryptographic facility, and the Marines recruit code talkers"]]},
  "Lakota people": {t:["The Lakota, whose name means “allies”, are the westernmost of the Seven Council Fires of the Sioux; pushed west onto the Plains, they became horse-mounted bison hunters and made the Black Hills their home by the 1770s.","The 1868 Fort Laramie Treaty closed the Black Hills to white settlement, but after gold was found there in 1874 war followed, and despite the Lakota and Cheyenne victory at the Battle of the Little Bighorn in 1876, resistance was broken by 1877.","In 1890 Sitting Bull was killed and the 7th Cavalry massacred Lakota at Wounded Knee; the tribes still refuse the 1980 Supreme Court award for the Black Hills, because accepting it would end their claim to the land."],dyk:"When the Lewis and Clark Expedition met the Sicangu in 1804, warriors seized a boat’s cable and both sides readied their weapons, until the Sicangu leader Black Buffalo let go and invited the Americans upriver under Sicangu escort.",ev:[["1804","The Lewis and Clark Expedition meets the Sicangu near the mouth of the Bad River, and a standoff ends when Black Buffalo grants the Americans passage"],["1851","The Fort Laramie Treaty recognises Lakota title to nearly 100,000 square miles north of the North Platte in return for roads and military posts"],["1855","General William S. Harney’s troops attack a Lakota and Cheyenne village at Blue Water Creek, killing at least 86 and taking 70 women and children captive"],["1866–1868","Red Cloud leads the Lakota and their allies to victory in Red Cloud’s War, and the 1868 Fort Laramie Treaty establishes the Great Sioux Reservation"],["1874","Custer’s expedition confirms gold in the Black Hills, and prospectors flood in against the terms of the 1868 treaty"],["1876","Lakota and Cheyenne forces under Crazy Horse and Sitting Bull defeat Custer at the Battle of the Little Bighorn"],["1890","Sitting Bull is killed at Standing Rock, and two weeks later the 7th Cavalry kills at least 270 Lakota in the Wounded Knee Massacre"],["1980","In United States v. Sioux Nation of Indians the Supreme Court awards $122 million for the Black Hills, which the tribes refuse"]]},
  "Clovis culture": {t:["Clovis is the earliest widely recognised archaeological culture of North America, found from southern Canada to northern Mexico around 13,050 to 12,750 years ago.","Its makers were highly mobile hunter-gatherers who carried fine stone tools hundreds of kilometres, relied on big game such as mammoths and bison, and also ate small animals and plants.","Older sites such as Monte Verde II in Chile show that Clovis people were not the first inhabitants of the Americas, and most researchers have abandoned the “Clovis First” model since the beginning of the 21st century."],dyk:"Isotope analysis of Anzick-1, a young boy buried in Montana with over 100 stone and bone artefacts stained with red ochre, suggests that mammoth made up about 35–40 per cent of his group’s diet.",ev:[["c. 11,100 BCE","Clovis points and tools come into use across North America, about 13,050 years ago by the dating of a 2020 study"],["c. 11,040–10,890 BCE","A young boy, Anzick-1, is buried about 12,990 to 12,840 years ago in Montana with over 100 stone and bone artefacts stained with red ochre"],["c. 10,800–10,650 BCE","About 12,750 to 12,600 years ago Clovis gives way to regional traditions, among them the Folsom tradition of central North America"],["1929","Ridgely Whiteman, aged 19, discovers the Clovis site at Blackwater Draw in eastern New Mexico"],["1932–1937","Crews under Edgar Billings Howard and later John L. Cotter excavate the best-documented Clovis finds near Clovis, New Mexico"],["1950s","Paul S. Martin proposes the overkill hypothesis, that human hunters, Clovis peoples among them, drove the North American megafauna to extinction"],["1968","The Anzick-1 burial is found near Wilsall, Montana"]]},
  "Paracas culture": {t:["The Paracas culture flourished on the south coast of Peru from about 800 to 100 BCE as a set of local chiefdoms joined by shared religion and trade, with irrigation systems to raise their harvests.","Its dead were bound in a seated position and wrapped in many layers of finely woven and embroidered cloth, and the Paracas Necropolis textiles are considered among the finest ever produced in the Pre-Columbian Andes.","The Paracas culture is believed to have evolved into the Nazca culture, which shared its religion and carried on its textile making, head-hunting and warfare."],dyk:"The Paracas culture shows the earliest trepanations known in the Americas: parts of the skull were scraped and drilled away, and by the healing of the bone nearly 40 per cent of patients survived long-term.",ev:[["c. 800 BCE","The Paracas culture emerges on the south coast of Peru, within the Chavín sphere of interaction"],["c. 550 BCE","Cerro del Gentil in the Upper Chincha Valley begins to host feasts for people from across the Paracas sphere"],["500–380 BCE","In the middle Paracas period Chavín influence dwindles, and Paracas communities form their own identities and expand their trade"],["c. 300–200 BCE","About 420 people are buried in two clusters of pit tombs at the Paracas Necropolis, wrapped in textile mummy bundles"],["c. 200 BCE","A termination ritual with a great feast and offerings closes Cerro del Gentil"],["1920s","Julio Tello makes the first formal investigations of the Paracas site"],["1931–1933","Looters plunder the Paracas Necropolis, and its textiles begin to appear on the international market"],["2018","Drone surveys reveal many geoglyphs in Palpa province, now assigned to the Paracas culture"]]},
  "La Tène culture": {t:["The La Tène culture followed the Hallstatt culture without a definite break about 450 BCE and spread from its core north of the Alps across much of Europe, as far as Galatia in Asia Minor.","Its people were those whom Greek and Roman writers called Celts and Gauls, though how far its objects, a language and a people coincide is debated.","From the 2nd century BCE its people built oppida, walled towns of up to hundreds of hectares, and many of them became Roman cities, among them Lutetia (Paris) and Avaricum (Bourges)."],dyk:"At the bottom of a well at the oppidum of Paule in Brittany lay the remains of a wooden structure of 68–27 BCE, thought to be a machine for drawing water, with a crank and connecting rod: the earliest known evidence for such a mechanism.",ev:[["early 5th century BCE","Elite graves are built at Glauberg in Hesse, a region once thought peripheral to the La Tène world"],["c. 450 BCE","The La Tène culture succeeds the final phase of the Hallstatt culture north of the Alps"],["c. 387 BCE","Celts under Brennus defeat the Romans and sack Rome"],["4th century BCE","In several major migrations the culture spreads across France, Germany and Central Europe and on to Hispania, Italy, the Balkans and Asia Minor"],["279 BCE","Celtic groups who have crossed the Balkans attack and sack Delphi"],["2nd century BCE","Oppida appear more or less at once from the Atlantic to central Europe"],["58–50 BCE","Julius Caesar’s Gallic Wars complete the Roman conquest of Gaul"],["1857","A drought lowers Lake Neuchâtel and reveals the type site of La Tène"]]},
  "Hallstatt culture": {t:["The Hallstatt culture grew out of the Urnfield culture of the Late Bronze Age, and its Iron Age phases, from about 800 to 450 BCE, form the Hallstatt period proper.","The salt mines of Hallstatt, worked most intensively from the 8th to the 5th centuries BCE, made its community unusually rich, and the salt has preserved cloth, wood, leather and tools.","Late in the period fortified princely seats such as the Heuneburg traded with the Greek and Etruscan Mediterranean, but at the end many centres were destroyed or abandoned and the La Tène culture took their place."],dyk:"The Vix krater, a Greek vessel buried in the rich grave at the foot of Mont Lassois in eastern France, is the largest known metal vessel from Western classical antiquity.",ev:[["c. 1200 BCE","The finds at Hallstatt begin, in the Hallstatt A phase of the Urnfield culture"],["c. 800 BCE","Iron ore processing arrives and the Hallstatt period proper, Hallstatt C, begins, with iron swords among the bronze ones"],["778 ± 5 BCE","Timber from the cart grave of Wehringen gives a firm tree-ring date for early Hallstatt C"],["c. 600 BCE","After the founding of Marseille, Greek and Etruscan trade up the Rhône begins to transform the settlements north of the Alps"],["c. 500 BCE","Major activity at Hallstatt ends and salt mining shifts to the Hallein mine at Dürrnberg"],["c. 450 BCE","Hallstatt D gives way to the La Tène culture after great centres such as the Heuneburg are destroyed or abandoned"],["1846","Johann Georg Ramsauer discovers the great prehistoric cemetery at Hallstatt"],["1902","Paul Reinecke divides the period into Hallstatt A to D"]]},
  "Cucuteni–Trypillia culture": {t:["The culture spread from the eastern Carpathians to the Dnieper, and in its middle phase its people built some of the largest settlements in Eurasia, a few with as many as three thousand structures.","Its settlements were burned and rebuilt every 60 to 80 years, sometimes on the plan of the old buildings, for reasons scholars still debate.","How it ended is disputed: Marija Gimbutas saw invasion from the steppe, others gradual change or a drier climate, and ancient DNA shows steppe-related ancestry entering late in its history."],dyk:"At Poduri in Romania thirteen habitation levels were built one on top of another over many years, as the settlement was destroyed and rebuilt on the same spot.",ev:[["c. 5050 BCE","The Cucuteni–Trypillia culture takes shape from earlier farming cultures in the region between the Prut and the Siret"],["c. 4100–3500 BCE","In the middle phase mega-sites such as Talianki, with up to three thousand structures, are built"],["first half of the 4th millennium BCE","Miniature models of animals and cups on four wheels are made, showing that the idea of pulling things on wheels was known"],["c. 3200 BCE","The climate turns colder and drier, a change some scholars link to the culture’s end"],["c. 2950 BCE","The Cucuteni–Trypillia culture comes to an end, in circumstances still debated"],["1884","Teodor T. Burada names and describes the culture after the village of Cucuteni in Romania"],["1897","Vincenc Chvojka presents his Ukrainian finds to the 11th Congress of Archaeologists, the official date of the discovery of the Trypillia culture"]]},
  "Nuragic civilisation": {t:["The Nuragic people of Sardinia built the nuraghe, a stone tower with vaulted inner chambers, in large numbers from about 1800 BCE, and more than 7,000 still dot the island.","They were skilled metalworkers, among the main metal producers of Europe, and their pottery and bronzes reached the Aegean, Cyprus, Spain and the Etruscan cities of Italy.","Ancient DNA shows strong continuity with Sardinia’s Neolithic farmers and almost no steppe-related ancestry, unlike many other Bronze Age peoples of Europe."],dyk:"The Giants of Mont’e Prama, stone statues up to 2.5 metres tall found near Cabras in 1974, have been dated between the 11th and 8th centuries BCE; if that is confirmed, they would be the oldest statues of people in the Mediterranean after those of Egypt.",ev:[["c. 1800–1600 BCE","The first proto-nuraghi are built in the late Bonnanaro culture"],["mid-2nd millennium BCE","The classic nuraghe, a tower with tholos chambers, evolves from the proto-nuraghe"],["13th century BCE","Nuragic pottery reaches Tiryns, Kommos and Cyprus along the sea routes to the eastern Mediterranean"],["12th–11th century BCE","The building of new nuraghi stops"],["c. 900 BCE","Phoenicians begin to visit Sardinia more often, as the Iron Age era of the aristocracies begins"],["540 BCE","A Carthaginian expedition under Malchus against a still strongly Nuragic Sardinia fails"],["238 BCE","Carthage surrenders Sardinia to Rome during the Mercenary War"],["1974","The Giants of Mont’e Prama are found near Cabras"]]},
  "Iberians": {t:["In the narrow sense, the Iberians were the pre-Indo-European peoples of the eastern and southern coasts of the peninsula that bears their name, distinct from the Celts and Celtiberians of its interior.","From the late 5th century BCE their societies centred on fortified towns, oppida, led by aristocracies and by chieftains bound to their followers by a tie the Romans called fides.","Iberian soldiers fought in Italy, Greece and Sicily and for both sides in the Second Punic War, after which their lands became Roman provinces and their language gave way to Latin."],dyk:"According to Arrian, the Iberians sent envoys to Alexander the Great in 324 BCE, along with embassies of Carthaginians, Italics and Gauls, to ask for his friendship.",ev:[["6th century BCE","Greek colonists make the first historical reference to the Iberians, as the non-Celtic peoples south of the Ebro"],["5th century BCE","A great fortress is built at Saguntum, and Iberian soldiers begin to fight in Italy, Greece and Sicily"],["late 5th–early 4th century BCE","An aristocracy and a system of clients take hold, and the oppidum becomes the centre of political life"],["324 BCE","Iberian envoys seek the friendship of Alexander the Great"],["221 BCE","Hannibal takes command of the Carthaginian forces and completes the conquest of the Iberians south of the Ebro"],["210 BCE","Publius Cornelius Scipio Africanus arrives in Iberia and turns the war against Carthage"],["197 BCE","The Iberian tribes of Hispania Citerior revolt against Rome"],["1st–2nd century CE","The Iberian language dies out, replaced by Latin"]]},
  "Tocharians": {t:["The Tocharians are known by a borrowed name: scholars called their languages after the Tókharoi of Bactria, an identification now generally considered erroneous, and what they called themselves is unknown.","Their two languages, Tocharian A and Tocharian B, were Indo-European, and by glotto-chronological data closest to Western branches such as proto-Germanic and proto-Italic.","Their oasis cities, Kucha the largest, were Buddhist centres on the Silk Road; they never recovered from the Tang conquest of the 640s, and their people blended with the Uyghurs, whose language replaced theirs."],dyk:"Among the everyday texts written in Tocharian are travel passes: small slips of poplar wood telling the officials at the next station along the road the size of the caravan allowed to pass.",ev:[["c. 2000 BCE","Settled Bronze Age farming communities appear in the oases of the northern Tarim and the Turpan Depression"],["177 BCE","The Xiongnu drive the Yuezhi from western Gansu and then overcome the Tarim statelets"],["60 BCE","After campaigns begun in 108 BCE, the Han dynasty establishes the Protectorate of the Western Regions under Zheng Ji"],["401","Kumārajīva of Kucha, captured in 384, is brought to Chang’an, where he heads a translation bureau until his death in 413"],["c. 480–550","The Hephthalites rule the region, and the swordsmen of the Kizil Caves appear to have been painted in these years"],["630","The monk Xuanzang visits Kucha and records about a hundred convents with more than five thousand monks"],["648","The Tang send an army under Ashina She’er, who takes Kucha and later has 11,000 of its people executed in reprisal for the killing of the protector-general"],["9th century","The Tocharian languages die out as the oasis peoples blend with the Uyghurs, who found the Kingdom of Qocho in 866"]]},
  "Longshan culture": {t:["The Longshan culture is named after the town of Longshan in Shandong, near the Chengziya site found in 1928, and is best known for thin, polished black pottery made on the potter’s wheel.","In the 3rd millennium BCE its population grew sharply: towns were walled with rammed earth, a few centres grew to over 200 hectares, and the dagger-axe points to more frequent warfare.","Around 2000 BCE its population fell sharply and large settlements were abandoned, except in central Henan, where the culture developed into the Bronze Age Erlitou culture."],dyk:"Some Longshan men from Shandong stood between 180 and 190 cm tall, taller than any other Neolithic population in the world; the tallest yet found, from Shaanxi, was a youth of about 16–18 who measured 193 cm.",ev:[["3000–2600 BCE","The Miaodigou II phase in Henan, Shanxi and Shaanxi marks the passage from the Yangshao culture to the Henan Longshan"],["by 2800 BCE","Sheep and goats, domesticated on the Loess Plateau, reach western Henan and then spread across the middle and lower Yellow River"],["2600–2000 BCE","In the late period regional variants flourish, settlements form hierarchies and some thirty towns are walled with rammed earth"],["c. 2000 BCE","The population falls sharply and large centres are abandoned, possibly through climate change at the end of the Holocene Climatic Optimum"],["1928","The Chengziya site near Longshan in Shandong is found, and excavated in 1930 and 1931"],["1950s","Excavations at Shanxian in western Henan identify the Miaodigou II phase"],["1963","Kwang-chih Chang describes a uniform “Longshanoid horizon”, which he replaces in 1986 with a “Chinese interaction sphere” of regional cultures"]]},
  "Hongshan culture": {t:["The Hongshan culture farmed millet in the West Liao river basin of northeast China from about 4700 to 2900 BCE; in its late phase millet made up as much as 80% of the diet.","Its burials hold some of the earliest known examples of jade working, including the jade pig dragons and embryo dragons for which the culture is known.","At Niuheliang it built a ritual complex of stone cairn tombs and an underground “Goddess Temple” holding clay figures up to three times life size."],dyk:"The “Goddess Temple” at Niuheliang takes its name from a clay female head with eyes inlaid with jade, found among clay figures as large as three times the size of living people.",ev:[["c. 4700 BCE","The Hongshan culture appears in the West Liao river basin, after the Xinglongwa, Xinle and Zhaobaogou cultures"],["3600–3300 BCE","Stone harvesting knives of Yangshao origin appear at Haminmangha, a sign of influence from the Yellow River basin"],["c. 2900 BCE","The Hongshan culture comes to an end; the Lower Xiajiadian culture follows in the region from 2200 BCE"],["c. 2200 BCE","Climate change begins, about 4,200 years ago, to turn the West Liao region, once rich in lakes and forests, into desert"],["1908","The Japanese archaeologist Torii Ryūzō discovers the Hongshanhou site at Chifeng"],["1935","Kōsaku Hamada and Mizuno Seiichi excavate Hongshanhou extensively"]]},
  "Erlitou culture": {t:["Most archaeologists consider the Erlitou culture, centred on a palace city in Henan, the first state-level society in China.","Erlitou was the earliest large-scale bronze-producing culture in China, and the city monopolised the casting of ritual bronze vessels, among them the earliest ding.","Chinese archaeologists generally identify it with the later part of the Xia dynasty, but some Western scholars call this premature, since no contemporary writing has been found to prove the link."],dyk:"Tracks of vehicles found near the palace area at Erlitou are the earliest evidence of wheeled wagons in China.",ev:[["c. 1920 BCE","An outburst flood at Jishi Gorge destroys the Lajia site on the upper Yellow River, a flood some authors link to the later Xia flood myth"],["c. 1750 BCE","By radiocarbon dating the Erlitou culture begins, and Erlitou grows quickly into a regional centre of several thousand people"],["c. 1600 BCE","A walled city is built at Yanshi, 6 km northeast of Erlitou, which the Xia–Shang–Zhou Chronology Project takes as the founding of the Shang"],["1450–1300 BCE","In the Upper Erligang phase all the palaces of Erlitou are abandoned and the city shrinks to a village of 30 ha"],["1959","Xu Xusheng discovers the Erlitou site and suggests it was Bo, the first capital of the Shang"],["late 1970s","Archaeologists in China begin to identify Erlitou with Zhenxun, the last capital of the Xia"],["2007","Radiocarbon studies narrow the culture’s dates to 1750–1500 BCE"],["October 2019","The Erlitou Site Museum of the Xia Capital, with more than 2,000 objects from the site, opens in Luoyang"]]},
  "Hoabinhian": {t:["The Hoabinhian is a tradition of stone tools, chiefly flaked river cobbles, left by hunter-gatherers across mainland Southeast Asia from the late Pleistocene to the Holocene.","It was first defined from Madeleine Colani’s excavations in Hòa Bình province, northern Vietnam, but later study showed that its tools form a continuous range of shapes and sizes rather than distinct types.","Ancient DNA from two Hoabinhian individuals shows a deeply branching East Asian ancestry, shared most closely today with peoples such as the Andamanese Onge and Jarawa, the Semang and the Maniq."],dyk:"Madeleine Colani sorted just 82 artefacts from Sao Dong into 28 types; her typology proved so complicated that most Hoabinhian sites are identified simply by the presence of sumatraliths.",ev:[["c. 8000–4000 BCE","The Bacsonian variant, richer in edge-ground cobble tools, is made in northern Vietnam"],["after 6800 BCE","Cord-marked pottery appears in the Hoabinhian levels of Spirit Cave in northwest Thailand"],["1927","Madeleine Colani publishes her nine excavations in the northern Vietnamese province of Hòa Bình"],["1932","The First Congress of Prehistorians of the Far East defines the Hoabinhian"],["1964","J. M. Matthews shows that the cobble tools of Sai Yok form a continuous range rather than Colani’s distinct types"],["1994","A conference in Hanoi votes to keep the term and to call the Hoabinhian an industry of the late Pleistocene to mid Holocene"],["2016","Hoabinhian artefacts dating from 41,500 BCE are recognised at the Xiaodong rock shelter in Yunnan, 40 km from the border with Myanmar"]]},
  "Mesopotamian religion": {t:["Every city had its patron god, among them Enki at Eridu, Enlil at Nippur, Marduk at Babylon and Ashur at Assur, and each god lived in a temple run as a household, its image fed, dressed and served.","Priests read the will of the gods in entrails, birds, the sky and dreams, and ordinary people prayed to a personal god and warded off demons with incantations.","It left the oldest body of recorded religious literature, from the Epic of Gilgamesh to the Enuma Elish, and many biblical stories were possibly based on its myths."],dyk:"Cult statues were brought to life in night rituals in which their mouths were “opened” and washed so that they could see and eat; while the god “ate” its twice-daily banquet, a curtain was drawn before the table, just as the king could not be seen eating.",ev:[["c. 3500 BCE","Writing is invented in Mesopotamia, bringing the first evidence of a recognisably Mesopotamian religion"],["c. 2600 BCE","A Sumerian list of about 560 deities, found at Fara and Tell Abu Salabikh, ranks five gods above the rest"],["c. 2335 BCE","Sargon of Akkad unites Mesopotamia, and Sumerian and Akkadian gods are increasingly identified with one another"],["18th century BCE","Hammurabi of Babylon raises Marduk to supremacy alongside Anu and Enlil in southern Mesopotamia"],["c. 12th century BCE","The Enuma Elish tells how Marduk made the heavens and the earth from the body of Tiamat"],["539 BCE","The Achaemenid Empire of Cyrus the Great conquers Mesopotamia but leaves its native religion undisturbed"],["2nd century BCE","Under the Parthians a revival in Assyria dedicates temples once more to Ashur, Sin, Shamash, Hadad, Bel and Ishtar"],["c. 400–500","The old religion has almost completely died out, its people having largely become Syriac Christians"]]},
  "Canaanite religion": {t:["The Canaanites honoured a pantheon headed by El and his consort Asherah, with Baal Hadad, the storm god who brought the rain, and Anat, Astarte, Dagon and Resheph among the other deities.","Most of what is known comes from the clay tablets of Ugarit, dated around 1275 BCE, which preserve the Baal Cycle and other myths with hymns, prayers and ritual texts.","In the first millennium BCE its branches lived on among Phoenicians, Arameans and Moabites, many scholars count Israelite Yahwism among them, and Phoenician settlers carried it west as the Punic religion."],dyk:"In the Baal Cycle the storm god Baal is swallowed by Mot, Death, and a terrible drought follows, until the goddess Anat attacks Mot with a knife, grinds him to pieces and scatters him, so that Baal can return and refresh the earth with rain.",ev:[["3rd millennium BCE","The Ebla tablets from Tell Mardikh in Syria list offerings to El, Baal and Dagon, the earliest evidence of Canaanite religion"],["15th century BCE","Inscriptions of Idrimi, king of Alalakh, shed further light on Canaanite religion"],["c. 1275 BCE","The Ugaritic texts, more than three hundred of them on Canaanite myths, rites and prayers, date from about this time"],["c. 1200 BCE","Ugarit is destroyed"],["9th century BCE","Phoenicians found Carthage and other Punic communities in the western Mediterranean"],["c. 850 BCE","The Mesha Stele is set up in Moab, one of the few sources for religion in the southern Levant beyond Israel and Judah"],["3rd–2nd century BCE","The Roman Republic conquers the Punic lands, where Punic religious practice continues"],["4th century CE","The last Punic religious practices die out"]]},
  "Roman religion": {t:["Roman religion was a matter of correct practice rather than belief: prayer, vow and sacrifice were exchanged with the gods on the principle of do ut des, “I give that you might give”.","Its priests were men of the elite who also held political office, while the six Vestals tended the sacred hearth of the state and every household honoured its own Lares and Penates.","Rome absorbed the gods of the peoples it ruled and the mystery cults of the East, but its conflict with Christianity ended in 380, when Nicene Christianity became the empire’s official religion."],dyk:"The consul Publius Claudius Pulcher, in 249 BCE, threw the sacred chickens into the sea when they would not eat before a naval battle, “saying that they might drink, since they would not eat”; he was defeated, and his impiety ruined his career.",ev:[["509 BCE","The expulsion of Tarquinius Superbus ends Roman kingship and begins the Republic, whose elected magistrates also serve as priests"],["206 BCE","During the war with Hannibal the Sibylline books call for the cult of the Magna Mater from Pessinus"],["186 BCE","The Senate restricts the Bacchanals, a popular mystery cult of Bacchus"],["64","After the Great Fire of Rome, Nero blames the Christians, who are persecuted and killed"],["303","Diocletian’s first edict against Christianity orders the destruction of churches and Christian texts"],["313","The Edict of Milan makes mutual toleration the ideology of the empire"],["380","Under Theodosius I, Nicene Christianity becomes the official state religion of the Roman Empire"],["391","Theodosius I ends official support for all other cults and extinguishes the sacred fire of the Vestals"]]},
  "Celtic religion": {t:["Celtic religion was polytheistic: the names of over two hundred deities survive, among them Lugus, Toutatis, Taranis, Cernunnos, Epona and Belenos, and several gods were seen as threefold.","Its priests were the druids, and its rites were held in sacred groves called nemetons, at springs and in timber temples, with offerings, often of weapons, thrown into rivers, lakes and bogs.","Almost everything known of it comes from archaeology, from Greek and Roman writers who were often hostile, and from medieval Irish and Welsh tales written down by Christian monks."],dyk:"In Ireland the satire of a gifted poet was a serious curse: the filid, visionary poets and keepers of lore, were also magicians, for Irish magic was bound up with poetry.",ev:[["6th century BCE","The Warrior of Hirschlanden is made in what is now Germany, one of the rare Celtic monumental stone sculptures from before the Roman conquest"],["late 4th century BCE","The Celts begin to strike coins, copying Greek and Roman models, with heads and horses that may have had religious meaning"],["58–51 BCE","Rome conquers Gaul, and Celtic religion there blends with Roman religion into a syncretic Gallo-Roman faith"],["43","Rome conquers southern Britain, where Iron Age sacred sites are reused for Roman temples"],["2nd century","The Coligny calendar, the oldest attested Celtic calendar, is made in Roman Gaul"],["3rd century","The Gauls begin gradually to convert to Christianity"],["5th century","The Celtic peoples of Britain and Ireland begin gradually to convert to Christianity"],["early 7th century","The church in Ireland has relegated the druids to irrelevancy, while the filid keep much of their pre-Christian learning and status"]]},
  "Slavic paganism": {t:["The Slavs worshipped a supreme god of the sky and thunder, later known as Perun, alongside Veles of the underworld, Mokosh, Dazhbog and a host of spirits of waters, forests, fields, households and ancestors.","West Slavic temples held many-headed idols, such as the four-headed Svetovid at Arkona and the three-headed Triglav of Wolin, kept by priests called volkhvs.","Rulers adopted Christianity in Great Moravia (863), Bulgaria (864), Poland (966) and Kievan Rus’ (988), but popular resistance lasted for centuries, and the old rites lived on in a “double faith”."],dyk:"According to legend, when Vladimir the Great sought a new faith for Kievan Rus’, his envoys found “no joy … but sorrow and great stench” in Volga Bulgaria, but were won over by the beauty of the rites in Constantinople.",ev:[["6th century","Procopius of Caesarea writes that the Slavs and Antes hold the god of lightning to be lord over all and sacrifice bulls to him"],["864","Bulgaria adopts Christianity, a year after Great Moravia"],["966","Mieszko I, the first historical ruler of Poland, is baptised with much of his court"],["980","Vladimir the Great raises idols of Perun, Dazhbog, Stribog, Simargl and Mokosh on a hill at Kiev"],["988","Vladimir is baptised with his subjects, and the idols of Kiev are burned or thrown into the Dnieper"],["1035–1037","An uprising against Christianity among the West Slavs reaches its height"],["1168","Arkona on Rugia surrenders to King Valdemar I of Denmark, and Bishop Absalon destroys the temple of Svetovid"],["1331","A holy place of trees and springs at Kobarid, in present-day Slovenia, is stamped out in a “crusade”"]]},
  "Mithraism": {t:["Initiates, the syndexioi or “those united by the handshake”, passed through seven grades and met for ritual meals in small underground temples, the mithraea, made to represent the cave where Mithras killed the bull.","Soldiers were strongly represented, with merchants, customs officials, freedmen and slaves, and the cult spread through Rome and Ostia, the Rhine and Danube frontiers, North Africa and Britain.","Its origins are still debated: Franz Cumont saw it as the Roman form of the Persian religion, but since the 1970s scholars have generally rejected his model, many seeing a new creation of the Roman world."],dyk:"Votive coins scattered over the floor of the mithraeum at Pons Sarravi (Sarrebourg) in Gallia Belgica run from Gallienus to Theodosius I: when the temple was destroyed, Christians apparently regarded the coins as polluted and left them behind.",ev:[["67 BCE","Cilician pirates are said to practise “secret rites” of Mithras, though whether this bears on the origins of the mysteries is unclear"],["66","Tiridates I of Armenia, crowned by Nero, tells the emperor that he reveres him “as Mithras”"],["c. 80","Statius’s Thebaid, one of the earliest literary references, pictures Mithras in a cave; the first mithraea appear"],["c. 145","Justin Martyr charges the cult of Mithras with imitating the Christian communion"],["184","The Virunum album records a Mithraic festival of commemoration on 26 June"],["4th century","Mithraists face persecution from Christians, and their sanctuaries are destroyed"],["c. 395","Votive coins at Sarrebourg end with the reign of Theodosius I, near the end of the cult"],["1971","At the First International Congress of Mithraic Studies, John R. Hinnells and R. L. Gordon severely criticise Cumont’s theory of Persian origins"]]},
  "Tengrism": {t:["Tengrism centres on Tengri, the eternal blue sky, with the earth mother and many other gods and spirits; many scholars see it as originally polytheistic, with a monotheistic form growing up among rulers.","It was the faith of the Xiongnu, the Göktürks, the Bulgars, the Khazars and the Mongol Empire, whose khans held that they ruled because “Heaven so ordained”.","Turkic and Mongol peoples largely turned to Islam and Buddhism from the 14th century; since the 1990s Tengrism has been revived in Central Asia and Siberia, a modern and monotheistic movement distinct from the historical religion."],dyk:"In 1290 the Ilkhan Arghun told Pope Nicholas IV that whoever prays to Eternal Tengri with righteous thoughts has done as much as if he had received baptism.",ev:[["4th century BCE","Chinese chronicles first record Tengri, as the sky god of the Xiongnu"],["209 BCE","The Xiongnu empire is founded, the first of a succession of steppe khanates and empires that practised Tengrism"],["8th–10th centuries","The Orkhon inscriptions in Old Turkic script record that the khagans acted because “Heaven so ordained”"],["1240","The Secret History of the Mongols is written, tracing Genghis Khan’s line to Borte Chino, born with “destiny from Tengri”"],["1262","Hulegu Khan writes from Maragheh to Louis IX of France, in a letter that treats Nestorian Christianity as part of the khans’ Tengrism"],["14th century","Özbeg Khan of the Golden Horde turns to Islam, and the Turkic and Mongolic peoples of Central Asia largely convert"],["1990–1993","The Yakut philologist Lazar Afanasyev-Teris founds the Tengrist organisation Kut-Siur, later Aiyy Faith"],["2005","Dastan Sarygulov founds Tengir Ordo in Kyrgyzstan to promote the values and traditions of Tengrism"]]},
  "Bon": {t:["Bonpos hold that Bon is Tibet’s original religion, taught by the Buddha Tonpa Shenrab and brought to Tibet through Zhangzhung; many Western scholars see it as a form of Buddhism that keeps genuinely ancient pre-Buddhist elements.","Its teachings closely resemble Tibetan Buddhism, especially the Nyingma school, with karma, rebirth, monasticism and Dzogchen, but its authority comes from Zhangzhung rather than India, and it keeps rituals for divination, the dead and local gods.","Long cast as an adversary in Buddhist histories, Bon suffered in the Dzungar invasion of 1717 and in the Cultural Revolution, and was recognised as a Tibetan religion by the Fifth Dalai Lama and again, in exile, in 1979."],dyk:"In Bon, Confucius is worshipped as a holy king and master of magic, divination and astrology, and is seen as a reincarnation of Tonpa Shenrab.",ev:[["c. 100 BCE","According to Robert Thurman, King Pudegungyal of the Yarlung dynasty institutes a Bon court religion"],["8th century","Bon declines under the Buddhist king Trisong Detsen (r. 740–797); Bon histories say its texts were hidden as treasures"],["11th century","Treasure revealers such as Shenchen Luga (996–1035) bring out Bon texts as Yungdrung Bon takes shape"],["14th century","Loden Nyingpo (1360–1385) reveals the Zibji, the life of Tonpa Shenrab, and New Bon begins in eastern Tibet"],["1405","Menri monastery, the most important Bon monastery, is built in Tsang"],["1717","Many Bonpos and Nyingmapas are executed during the Dzungar invasion of Tibet"],["1950","China invades Tibet, where there are about 300 Bon monasteries; Bonpo scholars begin to reach Europe and North America"],["1979","The Central Tibetan Administration in exile accepts Bon as a religious group with the same rights as the Buddhist schools"]]},
  "Chinese folk religion": {t:["Chinese folk religion has no single church or creed: one takes part by belonging to a village, a lineage or a temple association with its gods and rituals, not by believing an official doctrine.","Its common core is Tian, Heaven, the source of moral meaning; qi, the energy of which all things are made; the veneration of ancestors; and bao ying, moral reciprocity.","Condemned as “feudal superstition” after 1911 and attacked most of all in the Cultural Revolution (1966–1976), it revived after 1978, with millions of temples rebuilt or built from scratch."],dyk:"Many temples in northern China reopened because their gods were said to reclaim them: a Chenghuang Temple in Yulin, Shaanxi, used as a granary in the Cultural Revolution, was restored in the 1980s after the seeds stored in it were always found to have rotted.",ev:[["c. 1250 BCE","Divination, a major component of folk religion, has developed in China by 1250–1150 BCE"],["c. 1000 BCE","The Yijing and the Eight Trigrams are well established"],["531","A cult of Ganesha, the Elephant-Head God, is attested, as influences from the Indian subcontinent arrive with the spread of Buddhism"],["960–1279","Under the Song dynasty folk practices blend with Buddhist, Confucian and Taoist teachings into the popular religion that lasts to the present"],["1898","Kang Youwei persuades the emperor to order temples that perform no state sacrifices turned into schools; the confiscations are soon reversed"],["1928","The Nationalist government’s “Standards for retaining or abolishing gods and shrines” try to abolish the cults of all gods but great heroes and sages"],["1966–1976","The Cultural Revolution makes the most serious and last systematic effort to destroy the ancient Chinese religion"],["1978","After the adoption of the new constitution the religion revives rapidly, with millions of temples rebuilt or built from scratch"]]},
  "Druze faith": {t:["The Druze, who call themselves al-Muwaḥḥidūn, “the monotheists”, hold to the strict unity of God, reincarnation and the eternity of the soul; their faith grew out of Ismāʿīlī Islam, but most Druze do not identify as Muslims.","Since 1043 the faith has accepted no converts: one is Druze only by birth to two Druze parents, and only the initiated ʻuqqāl read its holy books.","From the Chouf of Mount Lebanon and later the Jabal al-Druze, Druze lords and fighters helped shape the history of the Levant, while facing repeated persecution from Fatimid, Mamluk and Ottoman rulers and modern extremists."],dyk:"The Druze still keep a ban on mulukhiyah that the Fatimid caliph al-Hakim bi-Amr Allah imposed during his reign (996–1021): though it was lifted after him, they eat no mulukhiyah of any kind to this day.",ev:[["1017","Hamza ibn Ali begins to preach the Unitarian doctrine in Cairo, and the divine call is opened"],["1018","The caliph al-Hakim has the preacher al-Darazi executed, leaving Hamza ibn Ali the sole leader of the new faith"],["1021","After al-Hakim’s disappearance the regent Sitt al-Mulk orders the army to destroy the movement, opening years of persecution, the mihna"],["1043","Baha al-Din al-Muqtana declares that no new pledges will be accepted, and the faith closes to converts"],["1305","After a fatwa of Ibn Taymiyya, the Mamluk sultan al-Nasir Muhammad inflicts a disastrous defeat on the Druze at Keserwan"],["1635","The Ottoman sultan has Fakhr-al-Din II killed, the Ma’an emir under whom Druze dominion had reached from the Antioch plain to Safad"],["1711","The battle of Ain Dara routs the Yamani faction, and many Yamani Druze migrate from Mount Lebanon to the Hauran"],["1925–27","Under Sultan Pasha al-Atrash the Druze provide much of the military force of the Syrian Revolution against French rule"]]},
  "Yazidism": {t:["Yazidis believe in one God who created the world and entrusted it to seven angels, led by Tawûsî Melek, the Peacock Angel, whom they hold to be the leader of the archangels and no source of evil.","Sheikh Adi ibn Musafir, a 12th-century mystic who settled at Lalish, united the scattered Yazidi tribes; his tomb is the holiest Yazidi site, and the three castes of sheikhs, pirs and murids are traced to his reforms.","Yazidis remember 74 farmans, campaigns of destruction, from Ottoman expeditions and the massacres of 1832 to the genocide by the Islamic State at Sinjar in 2014, when over 5,000 were killed and thousands of women and girls enslaved."],dyk:"In the Yazidi account of creation, the body of Adam lay lifeless for seven centuries: his soul would not enter it until music, played on the saz and the qudum, came down from heaven.",ev:[["12th century","Sheikh Adi ibn Musafir settles in the valley of Lalish, unites the scattered Yazidi tribes and returns their ancient temple to them"],["1246","Badr al-Din Lu’lu, ruler of Mosul, has Sheikh Hasan, the leader who had consolidated the Yazidi community, killed"],["1414","A joint army of neighbouring Sunni Kurdish tribes ransacks Lalish"],["1566","The Ottoman Sheikh al-Islam issues fatwas legitimising the killing of Yazidis and the enslavement and sale of Yazidi women"],["1640","An Ottoman army under Melek Ahmed Pasha storms Mount Sinjar, where 3,060 Yazidis are killed"],["1832","The forces of Muhammad Pasha of Rawanduz massacre the Yazidis of Sheikhan, enslave thousands and execute those who refuse Islam"],["1915","During the Armenian genocide many Yazidis are killed, and others flee from Van, Kars and Bazîd to Transcaucasia"],["2014","The Islamic State captures Sinjar and begins the genocide of the Yazidis: over 5,000 are killed and thousands of women and girls forced into sexual slavery"]]},
  "Haitian Vodou": {t:["Vodouists serve Bondye, a remote creator God, through the lwa, spirits mostly named after West and Central African deities, equated with Catholic saints and grouped in nations such as the Rada and the Petwo.","In the dans, the night ceremony of drumming, song and dance, a lwa is invited to possess a worshipper, the chwal or “horse”, and to speak through them to the congregation.","Forbidden in the colony, Vodou became Haiti’s dominant religion after the Revolution; long maligned by outsiders as sorcery, it was officially recognised in 2003 and has spread with Haitian emigrants."],dyk:"The word Vodou comes from the Fon language of West Africa: Vôdoun, a word for a spirit or deity in the kingdom of Dahomey, was first recorded in the Doctrina Christiana of 1658.",ev:[["c. 1512","Spanish colonists on Hispaniola begin importing enslaved West Africans, some of them priests of African traditional religions"],["1685","The French Code Noir forbids the open practice of African religions and orders that the enslaved be baptised as Roman Catholics"],["c. 1750","Among the enslaved of Saint-Domingue, African religions mixed with Catholic and Freemasonic elements take the form of Vodou"],["1791","According to legend, a Vodou ritual at Bois-Caïman sparks the Haitian Revolution"],["1805","The Roman Catholic Church cuts ties with Haiti until 1860, and Vodou becomes the country’s dominant religion"],["1915","The United States occupies Haiti until 1934, stirring foreign interest in Vodou and its reassessment by Haitian indigenists"],["1941","The government launches Operation Nettoyage, a Church-backed campaign to destroy many Vodou temples"],["2003","President Jean-Bertrand Aristide grants Vodou official recognition, after the constitution of 1987 enshrined freedom of religion"]]},
  "Pali": {t:["Pali is a Middle Indo-Aryan language that scholars see as a blend of several Prakrit dialects of around the 3rd century BCE, partly Sanskritised; Buddhist tradition long called it Magadhi, the Buddha’s own speech.","Its great work is the Tipiṭaka, the canon of Theravada Buddhism, written down in Sri Lanka in the 1st century BCE and carried, with its commentaries, to Burma, Thailand, Laos and Cambodia.","Pali has no script of its own and lived on as a language of study, chant and royal letters; it has lent words to Burmese (thousands of them), Khmer, Lao, Sinhala and Thai."],dyk:"In Sri Lanka, reciting the vows of Aṅgulimāla in Pali is believed to ease the pain of childbirth, and in Thailand the chanting of part of the Abhidhammapiṭaka for the recently dead can last as long as seven working days.",ev:[["c. 3rd century BCE","Around the time of Ashoka, a language close to the Pali of the canon may take shape as a compromise among the dialects in which the earliest Buddhist teachings were kept"],["1st century BCE","Monks in Sri Lanka write down the Tipiṭaka, until then handed down by mouth, in the time of King Vattagamini"],["4th–5th century","Buddhaghosa compiles the commentaries, among them the Visuddhimagga, and revives Pali as a language of Buddhist scholarship"],["9th century","The oldest surviving Pali manuscript, four palm-leaf folios of the Cullavagga later found in Nepal, is written"],["11th century","A “Pali renaissance” begins around the Pagan Kingdom and spreads across mainland Southeast Asia"],["14th century","Pali dies out as a literary language in mainland India, while the Subodhālaṅkāra brings Sanskrit poetics into Pali"],["1881","The Pali Text Society is founded to publish romanised Pali texts and English translations"],["2024","The Government of India designates Pali a classical language of India"]]},
  "Old English": {t:["Old English grew from the dialects of the Angles, Saxons and Jutes who settled in Britain in the 5th century, and it replaced the Common Brittonic and Latin of Roman Britain over most of what became England.","It was a heavily inflected language, with five cases, three genders and a freer word order than Modern English; perhaps around 85% of its words are no longer in use, but those that survived are the basic elements of English vocabulary.","Under Alfred the Great, and later the Winchester standard of Bishop Æthelwold, it became a written language of government and literature, until the Norman Conquest of 1066 made Anglo-Norman French the language of the upper classes."],dyk:"With few and relatively unimportant exceptions, all surviving Old English poetry is preserved in just four manuscripts; the earliest English poet known by name, Cædmon, was a lay brother at the monastery of Whitby.",ev:[["c. 450","Anglo-Saxon settlers bring to Britain the dialects that become Old English"],["658–680","Cædmon composes his hymn, the oldest surviving work of Old English literature"],["early 8th century","The Franks Casket is carved with the oldest coherent runic texts in Old English"],["9th century","Scandinavian rule and settlement begin, bringing strong Old Norse influence to the speech of eastern and northern England"],["late 9th century","Alfred the Great unites the kingdoms outside the Danelaw, and West Saxon becomes the standard language of government and literature"],["late 10th century","A new literary standard, Late West Saxon, arises at Winchester under Bishop Æthelwold"],["1019","Cnut addresses a proclamation in Old English to Earl Thorkell the Tall and the English people"],["1066","The Norman Conquest: Anglo-Norman replaces English as the language of the upper classes"]]},
  "Tamil": {t:["Tamil is a Dravidian language attested since about 300 BCE in Tamil-Brahmi inscriptions, and one of the longest-surviving classical languages in the world.","Its early literature includes the Tolkāppiyam, the oldest Tamil grammar, and the 2,381 Sangam poems, dated between the 1st century BCE and the 5th century CE; Tamil inscriptions have been found as far away as Sri Lanka, Thailand and Egypt.","Old Tamil became Middle Tamil by the 8th century and Modern Tamil from 1600; today Tamil is official in Tamil Nadu, Puducherry, Sri Lanka and Singapore, and in 2004 it became the first recognised classical language of India."],dyk:"Scholars trace the English word rice to Tamil arici, through loans from the Tamil of 400 BCE into Hebrew and then into Greek óruza.",ev:[["c. 300 BCE","Old Tamil appears in short inscriptions in Tamil-Brahmi, a variant of the Brahmi script"],["c. 150 BCE","The Hathigumpha inscription of Kharavela, king of Kalinga, names a Tamira Samghatta, a Tamil confederacy"],["1st century BCE","Egyptian pottery of this date found at Quseir al-Qadim, likely the port of Myos Hormos, bears Tamil-Brahmi inscriptions"],["8th century","Old Tamil has become Middle Tamil, which has gained a present tense and all but lost the old āytam sound"],["13th century","The Naṉṉūl restates the rules of the Tolkāppiyam and becomes the standard grammar of literary Tamil"],["1578","Portuguese missionaries print the prayer book Thambiran Vanakkam, making Tamil the first Indian language to be printed and published"],["20th century","The Pure Tamil Movement campaigns to remove Sanskrit elements from Tamil"],["2004","Tamil becomes the first legally recognised classical language of India"]]},
  "Malay": {t:["Malay is an Austronesian language whose ancestor, Proto-Malayic, was spoken in western Borneo at least by 1000 BCE; its oldest record is the Kedukan Bukit inscription of 683 in Sumatra.","Srivijaya spread Old Malay as a lingua franca of traders; under the Malacca Sultanate (1402–1511) it took in Arabic words with Islam and became Classical Malay, the language of courts and letters.","Written first in Indian-derived scripts, then in Jawi and now mainly in the Latin script, Malay is spoken by close to 300 million people as Standard Malay and as Indonesian."],dyk:"Among the oldest surviving letters in Malay are those Sultan Abu Hayat of Ternate sent to the king of Portugal around 1521–1522, although the Ternateans spoke the unrelated Ternate language and used Malay only as a lingua franca.",ev:[["683","The Kedukan Bukit inscription near Palembang, the earliest known stone inscription in Old Malay, is written in the Pallava script"],["c. 1303","The Terengganu Inscription Stone, the earliest evidence of Classical Malay and of Jawi writing, urges the spread of Islam and sets out ten Sharia laws"],["1345–1377","In the reign of Adityawarman of the Melayu Kingdom the Tanjung Tanah Law, a pre-Islamic legal text, is produced for the Minangkabau"],["1402–1511","Classical Malay becomes the lingua franca of the region under the Malacca Sultanate"],["1511","The Portuguese capture Malacca; the court moves to Johor and Malay literary centres scatter across the archipelago"],["1824","The Anglo-Dutch Treaty divides the Malay world between Dutch and British rule, both of which use Malay to centralise and modernise"],["1945","Indonesia’s constitution makes Indonesian, developed from Riau Malay, the national language"],["1968","Malay becomes the sole official language of Peninsular Malaysia"]]},
  "Armenian": {t:["Armenian is a branch of the Indo-European family on its own; in 1875 Heinrich Hübschmann showed that it is not an Iranian language, despite its many Parthian and Persian loanwords.","Written since Mesrop Mashtots created its alphabet in 405, it kept Classical Armenian, or Grabar, as its literary standard from the 5th century to the 19th.","Two modern standards grew up in the 19th century: Eastern Armenian, the official language of Armenia, and Western Armenian, carried by the diaspora after the Armenian genocide."],dyk:"Because Armenian borrowed so much, only around 1,500 words of Classical Armenian are known to have been inherited from Indo-European; even its word for “skull”, xalam, is thought to come from an Anatolian language, cognate with Hittite ḫalanta, “head”.",ev:[["405","Mesrop Mashtots creates the Armenian alphabet of 36 letters"],["5th century","The Bible is translated into Armenian, the language’s oldest surviving text"],["10th century","Gregory of Narek writes the Book of Lamentations, adding well above a thousand new words to the literary language"],["11th–14th centuries","In Bagratid Armenia and the Armenian Kingdom of Cilicia the letters օ and ֆ are added to the alphabet"],["1794","Azdarar, the first Armenian periodical, is published in Classical Armenian"],["1875","Heinrich Hübschmann uses the comparative method to show that Armenian is not an Iranian language"],["1920s","A spelling reform in Soviet Armenia adds the letter և and makes ու a single letter"]]},
  "Mongolian": {t:["Mongolian is the principal Mongolic language; its written history begins in the 13th century, when Genghis Khan adopted a script from the Uyghurs and the Mongol Empire spoke Middle Mongol.","Its vowels follow strict harmony and its grammar builds words from chains of suffixes, with seven to nine cases and five voices.","Written in more scripts than almost any other language, it is spoken today by perhaps 5–6 million people, in Cyrillic in Mongolia and in the traditional script in Inner Mongolia, where since 2023 Mandarin has been the only language of instruction in its schools."],dyk:"The Cyrillic script, closer to the spoken language than the traditional one, helped raise literacy in Mongolia from 17.3% to 73.5% between 1941 and 1950; campaigns using the traditional script had raised it only from 3.0% to 17.3% between 1921 and 1940.",ev:[["1204","Genghis Khan adopts a script for the Mongolian language, adapted from the Uyghur alphabet"],["c. 1224","The Stele of Yisüngge, perhaps the earliest surviving Mongolian text, records a report on sports in stone"],["13th–15th century","Middle Mongol is written in four scripts: Uyghur Mongolian, ’Phags-pa for decrees, Chinese for The Secret History of the Mongols, and Arabic for dictionaries"],["17th century","Classical Mongolian, a highly standardised written language, begins; its great works include the Mongolian Kangyur and Tengyur"],["1686","The Soyombo alphabet is created for Buddhist texts"],["1941","Cyrillic is made mandatory in the Mongolian state, after a Latin alphabet adopted that year lasts two months"],["1991–1994","An attempt to bring back the traditional script in Mongolia fails in the face of popular resistance"],["2020","China requires three subjects to be taught in Mandarin in Inner Mongolia’s Mongolian-language schools; the protests that follow are quickly suppressed"]]},
  "Ottoman Turkish": {t:["Ottoman Turkish was the Turkish of the empire’s court, poetry and administration, so full of Arabic and Persian that words from them made up as much as 88% of its vocabulary.","It was largely unintelligible to rural Turks, who spoke kaba Türkçe, “rough Turkish”, with far fewer loanwords, the basis of modern standard Turkish.","In 1928, under Mustafa Kemal Atatürk, the Republic of Turkey replaced the Perso-Arabic script with an extended Latin alphabet and began replacing Arabic and Persian loanwords with Turkish ones."],dyk:"The same speaker could use two languages for one thing: a scribe would write the Arabic word asel for honey in a document, but would ask for it by the Turkish word bal when buying it.",ev:[["14th century","Old Ottoman Turkish, almost identical with the Turkish of the Seljuks and the Anatolian beyliks, is the language of the young Ottoman state"],["16th century","Classical Ottoman Turkish becomes the language of poetry and administration, as it remains until the Tanzimat"],["1839–1876","In the Tanzimat era the language comes to be called “Ottoman”, lisân-ı Osmânî or Osmanlıca"],["1850s","New Ottoman Turkish begins to take shape under the influence of journalism and Western-oriented literature"],["1928","Atatürk’s reforms replace the Perso-Arabic script with an extended Latin alphabet and begin replacing Arabic and Persian loanwords"],["1960s","Ottoman Turkish is still at least partly intelligible to speakers of the Turkish of the day"],["2014","Turkey’s Education Council decides that Ottoman Turkish should be taught in Islamic high schools and as an elective in other schools"]]},
  "Middle Persian": {t:["Middle Persian, the language of Persia proper, became the prestige and literary language of the Sasanian Empire, used even by non-Persian Iranians, and stayed a prestige language for some time after the empire fell.","It had shed most of Old Persian’s case endings, using prepositions and compound tenses instead, and in its past tenses it treated the doer of an action like a by-phrase, an ergative pattern that New Persian gave up.","Almost all its literature is Zoroastrian, written mostly in the 9th to 11th centuries in Book Pahlavi, when the language had long ceased to be spoken; so the script’s name, Pahlavi, came to mean the language itself."],dyk:"Pahlavi scribes wrote many Persian words as Aramaic ones, about a thousand in Book Pahlavi: “me” was written LY, Aramaic for “to me”, but read aloud as the Persian man, and “foot” was written as Aramaic for “his foot” and read pāy.",ev:[["4th century BCE","The fall of the Achaemenid Empire opens the Middle period of the Iranian languages"],["2nd century BCE","Coins issued in the province of Pars carry legends in early Pahlavi"],["224","The Sasanians, native speakers of Middle Persian, take power from the Parthian Arsacids, and Middle Persian becomes the prestige language of the state"],["3rd century","The prophet Mani writes the Šābuhragān in Middle Persian in a script of his own making"],["6th–7th centuries","The earliest Zoroastrian texts in Middle Persian are probably written down, codifying an older oral tradition"],["7th century","The Arabs overthrow the Sasanians, and Middle Persian begins to evolve rapidly into New Persian"],["9th–11th centuries","Most surviving Zoroastrian Middle Persian texts are written, long after the language has ceased to be spoken"],["14th century","Copyists make most of the manuscripts through which Middle Persian texts survive"]]},
  "Old Church Slavonic": {t:["Old Church Slavonic was shaped by Cyril and Methodius for their mission to Great Moravia from 863, with a new alphabet, Glagolitic, and translations of the Gospels and liturgy for the Christianisation of the Slavs.","Expelled from Moravia, their students carried it to Bulgaria, where Boris I founded the Preslav and Ohrid schools, Cyrillic was developed and the language became the language of state and church in 893.","As the oldest attested Slavic language it preserves features of Proto-Slavic, and as Church Slavonic it held among the eastern Slavs a place like that of Latin in Western Europe."],dyk:"The full text of the Second Book of Enoch survives only in Old Church Slavonic, although the original had almost certainly been written in Greek or even Hebrew or Aramaic.",ev:[["862/863","Cyril and Methodius develop the Glagolitic alphabet and translate prayers and liturgical books for a mission to Great Moravia"],["885","Pope Stephen V prohibits the use of Old Church Slavonic in Great Moravia in favour of Latin"],["886","Svatopluk I expels the Byzantine missionaries, and their exiled students take the language to the Bulgarian Empire"],["893","The First Bulgarian Empire adopts Old Church Slavonic as its state and liturgical language, and Cyrillic supersedes Glagolitic as official"],["988","Kievan Rus’ adopts Orthodox Christianity and with it Old Church Slavonic in the Cyrillic script"],["1056–1057","The Ostromir Gospel, the earliest manuscript with Russian elements, is written"],["early 1370s","Patriarch Euthymius of Tarnovo reforms Bulgarian orthography on older Old Church Slavonic models"],["1755","Mikhail Lomonosov defines three styles for the balance of Church Slavonic and Russian in the literary language"]]},
  "Gothic": {t:["Gothic is the earliest Germanic language attested in sizeable texts, almost all of them copies of the Bible translated in the 4th century for the Visigothic Christians of Moesia under their Arian bishop Ulfilas.","It is closer to Proto-Germanic than any other Germanic language except the scanty Ancient Nordic runic inscriptions, keeping a dual on its verbs, a passive voice and reduplicated past tenses that the others lost.","It declined from the mid-6th century, after the Goths’ defeat by the Franks and their elimination in Italy; in Spain it lost its last role as a church language in 589 and lived on at home only into the 8th century."],dyk:"J. R. R. Tolkien wrote a poem in Gothic, “Bagme Bloma”, ‘Flower of the Trees’, published privately in 1936, and in a letter of 1965 he rendered his own name in Gothic as Ruginwaldus Dwalakoneis.",ev:[["4th century","Ulfilas, Arian bishop of the Visigothic Christians in Moesia, commissions a translation of the Greek Bible into Gothic, in an alphabet most likely of his own making"],["early 6th century","The Visigoths lose Occitania, where they had used the Gothic Bible"],["6th century","The Codex Argenteus, the best-preserved Gothic manuscript, is copied and kept by the Ostrogoths in Italy"],["mid-6th century","Gothic is in decline after the Goths’ defeat by the Franks and their elimination in Italy"],["589","The Visigoths convert from Arianism to Nicene Christianity, and Gothic loses its last role as a church language in Spain"],["8th century","Gothic is still spoken at home in the Iberian Peninsula, its last attested use there"],["840–842","Walafrid Strabo reports that peoples around Tomis still speak the language of the Gothic Bible and use it in their liturgy"],["mid-9th century","Graffiti in the Gothic alphabet are written in the basilica of Mangup in Crimea, perhaps its youngest attestation"]]},
  "Guarani": {t:["Guarani is a Tupian language that Paraguay kept: where people across the Americas shifted to the colonial languages, Paraguayans held on to Guarani while also adopting Spanish.","Jesuit missionaries first wrote it down, in grammars and a dictionary of 1629–1640; the Guarani of their missions built new words from its own roots, while the Guarani spoken outside took in Spanish words freely.","Banned from Paraguay’s state schools for over a hundred years, yet used by populists to stir national feeling, it was made equal to Spanish in the constitution of 1992."],dyk:"Guarani marks time on nouns as well as verbs: tetã ruvichakue is “ex-president” and tetã ruvicharã “president-elect”, and pa'irãgue, “the ex-future priest”, is someone who studied for the priesthood but did not finish.",ev:[["1629","The Jesuit Alonso de Aragona completes a teaching grammar of Guarani, not printed until 1979"],["1639","Antonio Ruiz de Montoya produces the Tesoro de la Lengua Guaraní, the first dictionary of its kind"],["1640","Ruiz de Montoya’s Arte de la lengua Guaraní becomes the starting point for all later grammars of the language"],["18th century","The Jesuits are expelled, and the people of the reductions move towards Asunción, where the mission Guarani gives way to the everyday Guarani of Paraguay"],["1992","Paraguay’s new democratic constitution makes Guarani a language equal to Spanish"],["2004","Guarani becomes the second official language of the Argentine province of Corrientes"],["2010","The Brazilian town of Tacuru adopts Guarani as a co-official language"],["2022","Only 12% of Paraguayans now speak Guarani alone, against 28% in 2002, while Spanish monolingualism has not risen"]]},
  "Georgian": {t:["Georgian belongs to the small Kartvelian family with Mingrelian, Laz and Svan, and no link between this family and any other is accepted in mainstream linguistics.","It became a written language after the Kingdom of Iberia was Christianised in the mid-4th century, replacing Aramaic as the literary language; its oldest literary work dates from the 5th century.","Its verbs can hold up to eight parts and mark both subject and object, and its words can open with as many as eight consonants, as in gvprtskvni, “you peel us”."],dyk:"Georgian counts in twenties, as Basque does: the number 93 is otkhmotsdatsamet’i, literally “four times twenty plus thirteen”.",ev:[["2nd century","The Roman grammarian Marcus Cornelius Fronto makes the earliest known reference to Georgian"],["4th century","The Christianisation of the Kingdom of Iberia makes Georgian a written language, replacing Aramaic as the literary language"],["5th century","Iakob Tsurtaveli writes the Martyrdom of the Holy Queen Shushanik, the oldest surviving literary work in Georgian"],["11th century","Old Georgian develops into Middle Georgian, and Leonti Mroveli writes down the traditional account of the first Georgian script"],["12th century","Shota Rustaveli writes the epic poem The Knight in the Panther’s Skin"],["1629","Nikoloz Cholokashvili’s Alphabetum Ibericum and Georgian–Italian dictionary, the first printed books partly in Georgian, appear for Catholic missionaries"],["1950–1964","A team under Arnold Chikobava produces the eight-volume Explanatory dictionary of the Georgian language"]]},
  "Coptic": {t:["Coptic is the last stage of Egyptian, a language whose recorded history may be the longest of any, written not in hieroglyphs or Demotic but in Greek letters with seven signs taken from Demotic.","Christian from its first literary texts in the 3rd century, it was the language of the saints and monks of Egypt; Sahidic was its great literary dialect, and Shenoute’s sermons helped to standardise it.","After the Arab conquest Arabic replaced it, in government at the turn of the 8th century and later in writing and speech; Coptic survives in the liturgy of the Coptic churches and in borrowed words such as adobe and barge."],dyk:"The word adobe goes back to Coptic: Sahidic tōōbe, “brick”, became Arabic ṭūba, passed through Andalusi Arabic into Spanish as adobe, and from Spanish into American English.",ev:[["1st century","The earliest known Old Coptic text, Egyptian written in Greek letters, is set down"],["3rd century","Literary Coptic appears in biblical texts, as notes in Greek Bibles and in bilingual Greek–Coptic texts"],["c. 325","Sahidic begins its age as the literary language of all Egypt, which lasts to about 800"],["c. 700","After the Arab conquest, the Umayyad caliph Abd al-Malik ibn Marwan decrees that Arabic replace Greek as the sole language of administration"],["11th century","Bohairic replaces Sahidic as the liturgical language of the Coptic Church"],["14th century","The last known literary work in Coptic is written, late in the century"],["17th century","Coptic survives as a minority first language until at least this century"],["20th century","Pope Cyril VI of Alexandria starts a Church-sponsored movement to revive Coptic, in the second half of the century"]]},
  "Ge'ez": {t:["Ge'ez was the language of the Kingdom of Aksum, carved on stone from the 4th century in a script made for it, which today also writes Amharic, Tigrinya and most other languages of Ethiopia.","Its Bible of 81 books, translated mostly from Greek in the first century of the Aksumite church, keeps the only complete text of the Book of Enoch.","No longer a living language by the 14th century, it remained Ethiopia’s official written language until the 19th, much like Medieval Latin in Europe, and is still the liturgical language of the Ethiopian and Eritrean churches and the Beta Israel."],dyk:"The Apostolic Tradition, an early Christian text attributed to Hippolytus of Rome, is lost in its original Greek; its Ge'ez translation, made in the late 5th century, is the best surviving witness to it.",ev:[["4th century","Aksum becomes Christian under King Ezana, and surviving Ge'ez literature begins"],["c. 400","The Hawulti obelisk at Matara is inscribed with the oldest known example of the Ge'ez script"],["5th century","The Aksumite Collection of liturgical, theological, synodal and historical texts is translated from Greek, late in the century"],["6th century","Ge'ez inscriptions in South Arabia record the conquests of Kaleb of Axum, the king who conquered Himyar"],["14th century","The Kebra Nagast, “Glory of the Kings”, retells the story of the Queen of Sheba, Solomon and their son Menelik I"],["c. 1450","The Fetha Negest, “Laws of the Kings”, is translated into Ge'ez; it serves as Ethiopia’s supreme law until 1931"],["c. 1532","Enbaqom writes the expanded Ge'ez version of his Anqasa Amin, “Gate of the Faith”, a classic of later Ge'ez literature"],["19th century","Ge'ez ceases to be the official written language of Ethiopia"]]},
  "Hawaiian": {t:["Hawaiian grew from the speech of Polynesian settlers, Marquesans arriving in roughly 300 CE by one account, and is closest to Marquesan and Tahitian.","Written down by New England missionaries from the 1820s, it became the language of a literate kingdom, of its constitution, newspapers and schools.","After the overthrow of the monarchy, the Republic of Hawaii’s Act 57 of 1896 made English the language of the schools and children were punished for speaking Hawaiian; immersion schools since 1984 have begun to bring it back."],dyk:"Hawaiian-medium schools teach the shape of a sentence as a pepeke, a squid: its head (poʻo) stands for the predicate, the point where head and tentacles meet (piko) for the subject, and the tentacles (ʻawe) for the object.",ev:[["c. 300","Marquesans colonise the Hawaiian Islands, by one account, followed by later waves from the Society Islands and Samoa-Tonga"],["1778","James Cook’s expedition makes Europe’s first recorded contact with Hawaiʻi and writes the island’s name as Owhyhee"],["1820","Protestant missionaries from New England arrive and set about creating a written Hawaiian"],["1834","The first Hawaiian-language newspapers are published"],["1839","The Hawaiian Bible is completed, and King Kamehameha III establishes the first Hawaiian-language constitution, in 1839 and 1840"],["1896","The Republic of Hawaii’s Act 57 makes English the medium of instruction in all public and private schools"],["1984","The ʻAha Pūnana Leo opens its first Hawaiian-language immersion preschool"],["1987","Hawaiian is again allowed as a medium of instruction in public schools, after 91 years"]]},
  "Phoenician": {t:["Phoenician was spoken in the cities of the northern Levant and carried by Tyro-Sidonian trade and colonies across the Mediterranean, where it became a lingua franca of the maritime world in the Iron Age.","Its alphabet, an abjad that wrote only consonants, passed to the Greeks and, through the Etruscans, to the Romans, and is generally believed to be at least a partial ancestor of almost all modern alphabets.","Almost nothing written on papyrus or parchment survived the damp coasts, so the language is known from about 10,000 inscriptions; a bilingual found in Malta let Jean-Jacques Barthélemy decipher it in 1758."],dyk:"The word gorilla comes from Punic: Hanno the Navigator’s interpreters gave the name to a tribe of hostile ‘hairy people’ in the Gulf of Guinea, it passed into Greek as gorillai, and in 1847 Thomas S. Savage applied it to the western gorilla.",ev:[["c. 1050 BCE","The alphabet, first attested on inscribed bronze arrowheads, comes to be called Phoenician rather than Proto-Canaanite"],["9th–7th century BCE","Phoenician loses its old case endings, as Akkadian spellings of the name ‘Gift of Baal’ show"],["c. 500 BCE","The Pyrgi Tablets are inscribed in Etruscan and Phoenician"],["3rd century BCE","Punic writers begin to mark final vowels with the letter aleph"],["c. 149 BCE","Carthage is destroyed, after which the cursive Neo-Punic script becomes predominant"],["1st century BCE","Phoenician seems to die out in the eastern Mediterranean"],["6th century","Punic, the western form of the language, seems to die out, perhaps lingering into the 9th century"],["1758","Jean-Jacques Barthélemy deciphers the alphabet from the Cippi of Melqart, a Greek and Punic bilingual"]]}
};
